(window.QUESTIONS_PARTS = window.QUESTIONS_PARTS || {})["ya3"] = [{"id":"ya3-105-1-1","subject":"ya3","topic":"牙科解剖與生理","meta":"105年第1次第1題","year":105,"session":1,"number":1,"question":"有關牙齒結構與其發育來源細胞或組織的配對，下列敘述何者錯誤？","options":["(A) 牙釉質（enamel）－外胚層（ectoderm）","(B) 牙本質（dentin）－牙乳頭（dental papilla）","(C) 牙周韌帶（periodontium）－齒濾泡（dental follicle）","(D) 牙髓組織（dental pulp）－齒囊（dental sac）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-1-2","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第1次第2題","year":105,"session":1,"number":2,"question":"牙髓隨著年齡的增長會發生形態變化（morphologic changes）與生理變化（physiologic changes）。有關形態變化的敘述，下列何者錯誤？","options":["(A) 隨著年齡增加，牙髓腔的體積會因為二級、三級牙本質（secondary and tertiary dentin） 沉積而減少","(B) 大臼齒牙髓腔中的牙本質沉積在頂端（roof）與底部（floor）比頰舌側或近遠心側少","(C) 牙髓腔中的神經與血管隨著年紀增加而減少，因此老年人的牙髓活性測試反應通常較弱","(D) 牙髓石（pulp stone）與牙齒疼痛（dental pain）之間沒有明確的關係"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-1-3","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第1次第3題","year":105,"session":1,"number":3,"question":"下列有關成熟牙髓組織之敘述，何者錯誤？","options":["(A) 由牙乳頭（dental papilla）發育形成","(B) 因硬組織包圍，所以不具有體積變化之調節能力","(C) 具有良好之側枝循環，傷口癒合快速良好","(D) 由顯微血液循環（microcirculation）供給血液"],"answer":2,"clinical_level":"重點"},{"id":"ya3-105-1-4","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第1次第4題","year":105,"session":1,"number":4,"question":"關於牙髓中的間質蛋白（extracellular protein）之敘述，下列何者錯誤？","options":["(A) 主要是第一型與第三型膠原蛋白（collagen）","(B) 含有少量的第五型膠原蛋白（collagen）","(C) 含有多量的彈性纖維（elastic fiber）和嗜氧性纖維（oxytalan fiber）","(D) 網狀纖維（reticulin fiber）於牙髓中可見到"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-1-5","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第1次第5題","year":105,"session":1,"number":5,"question":"關於牙本質的老化現象，下列敘述何者錯誤？","options":["(A) 牙髓腔及根管的管徑大小會減小","(B) 膠原纖維的數目會減少，尤其是在牙髓腔的部分","(C) 造牙本質細胞的數目和大小會減小，甚至消失","(D) 管周牙本質（peritubular dentin）會增加"],"answer":1,"clinical_level":"重點"},{"id":"ya3-105-1-6","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第1次第6題","year":105,"session":1,"number":6,"question":"下列那兩項檢查，最能區分患齒為牙髓疾病或是牙周疾病？","options":["(A) 牙周囊袋檢測及牙髓活性測試","(B) 症狀嚴重程度及牙髓活性測試","(C) X光片檢查及牙周囊袋檢測","(D) 膿腫或瘻管的位置及牙周囊袋檢測"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-1-7","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第1次第7題","year":105,"session":1,"number":7,"question":"下列有關根管感染之敘述，何者為錯誤？","options":["(A) 無菌老鼠暴露之牙髓腔不會引起根尖牙周炎","(B) 根管內之細菌對根尖組織並不會有所影響","(C) 一般而言，單純缺血壞死之牙髓組織並不會造成根尖發炎現象","(D) 微生物之存在與根尖牙周炎之形成有明顯的關係"],"answer":1,"clinical_level":"重點"},{"id":"ya3-105-1-8","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第1次第8題","year":105,"session":1,"number":8,"question":"有關電子牙髓活性測試（EPT）的敘述，下列何者錯誤？","options":["(A) EPT是利用電極刺激牙髓中A-delta神經纖維","(B) EPT用以診斷牙髓發炎的程度","(C) 要測試的牙齒必須隔離及保持乾燥","(D) EPT使用時，電極不要靠近齒頸部"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-1-9","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第1次第9題","year":105,"session":1,"number":9,"question":"當病人牙齒疼痛求診，身為牙醫師卻找不到明確的原因時，應採取下列何種措施？","options":["(A) 給予緊急髓腔開擴後轉診專科醫師","(B) 給予止痛藥並轉診專科醫師","(C) 給予根管治療後觀察","(D) 拔除牙齒"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-1-10","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第1次第10題","year":105,"session":1,"number":10,"question":"關於測試窩洞（test cavity），下列何者正確？","options":["(A) 在做測試窩洞之前應先給予病人局部麻醉","(B) 外傷的牙齒適用","(C) 準確度不如冷測試","(D) 在其他各種測試的結果均不能確定時才使用"],"answer":3,"clinical_level":"重點"},{"id":"ya3-105-1-11","subject":"ya3","topic":"牙齒外傷處理","meta":"105年第1次第11題","year":105,"session":1,"number":11,"question":"牙齒外傷造成牙齒敲痛與動搖，但牙齒並無位移時，是屬於何種牙齒外傷？","options":["(A) Concussion","(B) Subluxation","(C) Extrusive luxation","(D) Intrusive luxation"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-1-12","subject":"ya3","topic":"牙齒外傷處理","meta":"105年第1次第12題","year":105,"session":1,"number":12,"question":"下列有關牙根水平斷裂之敘述，何者正確？","options":["(A) 診斷上最好要有三張不同角度之X光影像","(B) 牙根中間部斷裂時牙髓全部壞死機會很高","(C) 牙根冠部斷裂只要確實固定則預後良好","(D) 牙根尖部斷裂須儘早拔除"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-1-13","subject":"ya3","topic":"牙齒外傷處理","meta":"105年第1次第13題","year":105,"session":1,"number":13,"question":"下列有關牙齒外傷之敘述何者錯誤？","options":["(A) 以偏移角度來做根尖片X光照射，有助於判別牙根的內吸收或外吸收","(B) 發炎性牙根外吸收（external inflammatory root resorption）常伴隨齒槽骨的吸收（bone resorption）","(C) 當牙髓產生轉移性鈣化（calcific metamorphosis）時，大部分之牙髓通常已壞死，要儘快 進行根管治療","(D) 牙根發生外吸收的機會比發生牙根內吸收高"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-1-14","subject":"ya3","topic":"牙齒外傷處理","meta":"105年第1次第14題","year":105,"session":1,"number":14,"question":"當牙齒因外傷撞擊發生牙冠斷裂導致牙髓暴露時，下列何者較不是擬定治療計畫較需考慮的 因素？","options":["(A) 牙齒的齒位","(B) 牙根發育的情況","(C) 斷裂延伸的範圍","(D) 意外發生到現在的時間"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-1-15","subject":"ya3","topic":"黏著與美學修復","meta":"105年第1次第15題","year":105,"session":1,"number":15,"question":"下列何者不屬於牙齒美白（tooth bleaching）使用的藥劑？","options":["(A) 過氧化氫（hydrogen peroxide）","(B) 過硼酸鈉（sodium perborate）","(C) 過氧化尿素（carbamide peroxide）","(D) 氫氧化鈣（calcium hydroxide）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-1-16","subject":"ya3","topic":"根管器械","meta":"105年第1次第16題","year":105,"session":1,"number":16,"question":"下列有關根管銼針（file）與根管鑽針（reamer）的敘述，何者正確？","options":["(A) 根管銼針的橫切面為三角形，根管鑽針的橫切面為正方形","(B) 根管銼針為不銹鋼材質，根管鑽針則為碳鋼材質","(C) 每單位的長度中，根管銼針的切削刃比根管鑽針多","(D) 根管銼針只能使用銼修動作（filing action），根管鑽針只能使用鑽修動作（reaming action）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-1-17","subject":"ya3","topic":"根管器械","meta":"105年第1次第17題","year":105,"session":1,"number":17,"question":"今有一10號器械，其D0為0.10 mm，D16為0.74 mm，請問其錐度（taper）為：","options":["(A) 2%","(B) 4%","(C) 6%","(D) 8%"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-1-18","subject":"ya3","topic":"根管器械","meta":"105年第1次第18題","year":105,"session":1,"number":18,"question":"鎳鈦旋轉器械作為根管治療的修形之使用原則，下列敘述何者錯誤？","options":["(A) 鎳鈦旋轉器械在尋找根管及通過鈣化根管方面較不銹鋼手動器械表現佳","(B) 在放射線不透性（radiopacity）方面不銹鋼器械較鎳鈦旋轉器械更為清晰","(C) 鎳鈦旋轉器械之修形對於彎曲的根管能有效維持根管的中心性，較不易產生根管偏誤的情 形","(D) 鎳鈦旋轉器械仍然必須注意週期性疲勞斷裂可能發生的問題"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-1-19","subject":"ya3","topic":"根管治療程序","meta":"105年第1次第19題","year":105,"session":1,"number":19,"question":"對於牙髓壞死（pulp necrosis）但無牙齦膿腫的牙齒發生劇烈的自發性疼痛時，較佳的緊急 處理為何？","options":["(A) 給予抗生素控制感染，同時給予NSAIDs類止痛藥控制疼痛","(B) 進行冠髓切除術（pulpotomy）","(C) 決定正確的根管工作長度，並進行根管清創","(D) 進行單次根管治療並完成根管充填（single visit root canal treatment）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-1-20","subject":"ya3","topic":"根管治療程序","meta":"105年第1次第20題","year":105,"session":1,"number":20,"question":"下圖X光片中，右下第一大臼齒發生何種治療過程意外（procedural accident）?","options":["(A) 平台（ledge）","(B) 根管偏移（transportation）","(C) 切削穿孔（stripping perforation）","(D) 牙根垂直斷裂（vertical root fracture）"],"answer":2,"image":"ya3-105-1-20.jpeg","clinical_level":"一般"},{"id":"ya3-105-1-21","subject":"ya3","topic":"根尖手術與再治療","meta":"105年第1次第21題","year":105,"session":1,"number":21,"question":"垂直牙根斷裂（vertical root fracture）因為臨床診斷不易，因此常需要藉助何種術式協助診 斷？","options":["(A) 根尖手術（apical surgery）","(B) 探測性手術（exploratory surgery）","(C) 半切斷術（hemisection）","(D) 蓄意再植術（intentional replantation）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-1-22","subject":"ya3","topic":"根尖手術與再治療","meta":"105年第1次第22題","year":105,"session":1,"number":22,"question":"關於根尖手術使用緣下翻瓣（submarginal flap），下列敘述何者錯誤？","options":["(A) 適用於後牙","(B) 沒有術後牙齦萎縮的問題","(C) 可能產生術後疤痕","(D) 不適用於牙周不良的牙齒"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-1-23","subject":"ya3","topic":"根管治療程序","meta":"105年第1次第23題","year":105,"session":1,"number":23,"question":"根管治療失敗病例，以下原因何者較常見？","options":["(A) 器械斷裂（separated instrument）","(B) 冠部滲漏（coronal leakage）","(C) 充填材料超過根尖（overfilling）","(D) 沒有置放牙根釘柱（post）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-1-24","subject":"ya3","topic":"根管治療程序","meta":"105年第1次第24題","year":105,"session":1,"number":24,"question":"牙齒打金屬釘柱（metal post）時，釘柱長度通常依據下列何項參考值？","options":["(A) 根管長度的1/2","(B) 牙冠長度的1/2","(C) 有骨頭支持的牙根長度的1/2","(D) 牙齒長度2/3"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-1-25","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第1次第25題","year":105,"session":1,"number":25,"question":"下列何者不是微生物侵犯牙髓的途徑？","options":["(A) 牙本質小管","(B) 暴露的牙髓（因齲齒或外傷）","(C) 側根管","(D) 硬化牙本質（sclerotic dentin）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-1-26","subject":"ya3","topic":"醫學倫理與法規","meta":"105年第1次第26題","year":105,"session":1,"number":26,"question":"使用患者的那些資料與樣本，不需要簽立人體試驗同意書？","options":["(A) 收集患者拔除的牙齒，進行電子顯微鏡觀察研究","(B) 收集患者根管中的腐敗組織樣本，進行根管中微生物的研究","(C) 收集患者根尖手術取出的根尖囊腫組織，進行組織病理切片染色研究","(D) 收集患者臨床上患牙的X光片影像，進行根管充填緻密度與根尖病灶大小的分析研究"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-1-27","subject":"ya3","topic":"窩洞設計與分類","meta":"105年第1次第27題","year":105,"session":1,"number":27,"question":"窩洞修形（cavity preparation）之輪廓外形（outline form），首先是由下列何者來決定其設 計？","options":["(A) 齲齒病灶的位置及範圍","(B) 復形材料的固位力","(C) 便利器械操作","(D) 抵抗咬合壓力"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-1-28","subject":"ya3","topic":"窩洞設計與分類","meta":"105年第1次第28題","year":105,"session":1,"number":28,"question":"最常見的坑道（tunnel）修復體失敗的原因為：","options":["(A) 微滲漏（microleakage）","(B) 邊緣嵴（marginal ridge）斷裂或續發性齲齒","(C) 修復體外懸（restorative overhang）","(D) 鄰近牙的障礙（disturbance）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-1-29","subject":"ya3","topic":"窩洞設計與分類","meta":"105年第1次第29題","year":105,"session":1,"number":29,"question":"關於牙釉質的敘述，何者正確？","options":["(A) 氫氧磷灰石（hydroxyapatite）為牙釉質組成中最大成分，約占其體積比的96%","(B) 牙釉質表面為非通透性（not permeable）","(C) 牙釉質之透明度與牙齒礦化程度無關","(D) 在X光片上牙釉質之平滑面齲齒（smooth surface caries）是呈三角形，其底部在牙釉質表 面上"],"answer":3,"clinical_level":"重點"},{"id":"ya3-105-1-30","subject":"ya3","topic":"牙科解剖與生理","meta":"105年第1次第30題","year":105,"session":1,"number":30,"question":"有關被覆牙本質（mantle dentin）的敘述，下列何者正確？","options":["(A) 位於齲蝕之下方延展區","(B) 包含在牙本質結構中，礦化程度較低","(C) 含牙本質小管之數目多，管壁礦化程度高","(D) 是最靠近牙髓腔之牙本質"],"answer":1,"clinical_level":"重點"},{"id":"ya3-105-1-31","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第1次第31題","year":105,"session":1,"number":31,"question":"放線菌（Actinomyces）產生齲齒的好發部位為：","options":["(A) 咬合面","(B) 鄰接面","(C) 頰側小凹（buccal pit）","(D) 牙根部"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-1-32","subject":"ya3","topic":"窩洞設計與分類","meta":"105年第1次第32題","year":105,"session":1,"number":32,"question":"預防老年人牙根齲齒有四大策略，但不包含下列何者？","options":["(A) 增加唾液分泌量與緩衝（buffer）能力","(B) 減少口腔中candida albicans的數量","(C) 減少攝取精緻碳水化合物的數量與頻率","(D) 嘗試讓已脫鈣的組織再礦化，並防止新的齲齒生成"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-1-33","subject":"ya3","topic":"黏著與美學修復","meta":"105年第1次第33題","year":105,"session":1,"number":33,"question":"牙釉質被酸蝕過後，會呈現多種不同的結構型態（pattern），第二種結構型態（type II pattern）指的是下列何者？","options":["(A) 只有牙釉質柱周圍（prism peripheries）被溶解，牙釉質柱中心（prism core）則無","(B) 只有牙釉質柱中心（prism core）被溶解，牙釉質柱周圍（prism peripheries）則無","(C) 牙釉質柱中心（prism core）和牙釉質柱周圍（prism peripheries）都被溶解","(D) 牙釉質柱周圍（prism peripheries）或牙釉質柱中心（prism core）皆不受影響"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-1-34","subject":"ya3","topic":"黏著與美學修復","meta":"105年第1次第34題","year":105,"session":1,"number":34,"question":"複合樹脂充填前，酸蝕牙釉質大多使用：","options":["(A) 15～20%硫酸","(B) 30～37%磷酸","(C) 5～10%硝酸","(D) 30%檸檬酸"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-1-35","subject":"ya3","topic":"黏著與美學修復","meta":"105年第1次第35題","year":105,"session":1,"number":35,"question":"下列何者為牙本質黏著劑（dentin bonding agent）常用之含親水性官能基樹脂單體 （hydrophilic resin monomer）？","options":["(A) bisphenol glycidyl methacrylate（Bis-GMA）","(B) urethane dimethacrylate（UDMA）","(C) 2-hydroxyethyl methacrylate（HEMA）","(D) triethylene glycol dimethacrylate（TEGDMA）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-1-36","subject":"ya3","topic":"黏著與美學修復","meta":"105年第1次第36題","year":105,"session":1,"number":36,"question":"對於酸蝕後之牙本質表面，下列何者可作為再潤濕劑（rewetting agent）？","options":["(A) 次氯酸鈉溶液（NaOCl）","(B) 雙氧水（H2O2）","(C) 丙酮（acetone）","(D) chlorhexidine"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-1-37","subject":"ya3","topic":"窩洞設計與分類","meta":"105年第1次第37題","year":105,"session":1,"number":37,"question":"何者是牙科治療計畫控制階段（control phase）的目標？","options":["(A) 重新評估治療計畫可行性","(B) 提供全口重建的治療意見","(C) 去除齲齒或發炎等活躍性（active）病灶","(D) 解決病人疼痛腫脹等急性問題"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-1-38","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第1次第38題","year":105,"session":1,"number":38,"question":"應用雷射螢光（laser fluorescence）技術檢測齲齒的原理，下列敘述何者錯誤？","options":["(A) 以光學原理檢測齒質結構之變化","(B) 需要清潔乾燥的齒質進行檢測","(C) 依據閾值，判斷齒質是否發生齲齒","(D) 檢測結果偽陽性（false positive）機率低"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-1-39","subject":"ya3","topic":"窩洞設計與分類","meta":"105年第1次第39題","year":105,"session":1,"number":39,"question":"對於處理磨耗（abrasion）、酸蝕（erosion）、裂耗（abfraction）或咬耗（attrition）的時 機，下列何者錯誤？","options":["(A) 該病灶部位有齲齒的情況","(B) 該病灶部位太深，以致可能影響牙齒的結構","(C) 病人在該部位有明顯敏感的狀況","(D) 只要看到缺損就應該予以填補治療"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-1-40","subject":"ya3","topic":"牙體修形程序","meta":"105年第1次第40題","year":105,"session":1,"number":40,"question":"關於鑽石鑽針（diamond bur）與鎢鋼鑽針（carbide bur）的比較，下列何者錯誤？","options":["(A) 使用鎢鋼鑽針製備產生較少熱","(B) 鎢鋼鑽針較適合製備二級固位設計（secondary retention features）","(C) 鎢鋼鑽針較適合製備牙釉質斜面（enamel beveling）","(D) 鎢鋼鑽針的硬度較低"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-1-41","subject":"ya3","topic":"牙體修形程序","meta":"105年第1次第41題","year":105,"session":1,"number":41,"question":"關於牙體復形中操作區域隔離（isolation）的敘述，下列何者錯誤？","options":["(A) 橡皮障（rubber dam）可以提供乾燥乾淨的操作環境，防止感染","(B) 施打含血管收縮劑的麻藥可以控制疼痛、減少唾液的分泌、控制出血","(C) 排齦可以減少牙齦溝液、排開軟組織、避免窩洞製備時牙齦外傷","(D) No. 212橡皮障夾（rubber dam clamp）可用於第二類型窩洞，下壓軟組織"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-1-42","subject":"ya3","topic":"複合樹脂與材料","meta":"105年第1次第42題","year":105,"session":1,"number":42,"question":"在第四類型窩洞（class IV）複合樹脂填補的窩洞設計，有關牙釉質斜面（bevel）的敘述， 下列何者錯誤？","options":["(A) 唇側牙釉質邊緣可做扇形（scallop）斜面","(B) 唇側牙釉質斜面寬度至少1 mm","(C) 牙釉質斜面寬度為2 mm，較1 mm斜面之複合樹脂強度（strength）為高","(D) 增加唇側牙釉質斜面寬度可改善複合樹脂界面美觀"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-1-43","subject":"ya3","topic":"複合樹脂與材料","meta":"105年第1次第43題","year":105,"session":1,"number":43,"question":"在光聚合複合樹脂成分中，可當作光起始劑之加速劑（accelerator）為下列何者？","options":["(A) 醯胺（amine）","(B) 過氧化苯（benzoyl peroxide）","(C) 對苯二酚（hydroquinone）","(D) 樟腦醌（camphorquinone）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-1-44","subject":"ya3","topic":"複合樹脂與材料","meta":"105年第1次第44題","year":105,"session":1,"number":44,"question":"有關複合樹脂完成（finishing）和拋光（polishing）處理方式的敘述，下列何者錯誤？","options":["(A) 以diamond paste處理是屬於拋光","(B) 以fine diamond bur處理是屬於拋光","(C) 以24-blade carbide fissure bur處理是屬於完成","(D) 以white stone處理是屬於完成"],"answer":1,"clinical_level":"重點"},{"id":"ya3-105-1-45","subject":"ya3","topic":"複合樹脂與材料","meta":"105年第1次第45題","year":105,"session":1,"number":45,"question":"相較於汞齊，後牙複合樹脂之彈性模數（modulus of elasticity）與彈性變形量（elastic deformation）之敘述，下列何者正確？","options":["(A) 具較低的彈性模數，因此彈性變形量較高","(B) 具較低的彈性模數，因此彈性變形量較低","(C) 具較高的彈性模數，因此彈性變形量較低","(D) 具較高的彈性模數，因此彈性變形量較高"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-1-46","subject":"ya3","topic":"窩洞設計與分類","meta":"105年第1次第46題","year":105,"session":1,"number":46,"question":"下列關於第二類型（class II）複合樹脂單純盒狀（box-only）窩洞的製備，何者正確？","options":["(A) 為了增加固位性（retention）需要做出斜面（bevel）","(B) 需二級固位設計（secondary retention）","(C) 建議使用於單純鄰接面齲齒","(D) 開始時使用柱狀鑽針（cylinder bur）作為窩洞製備的器械"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-1-47","subject":"ya3","topic":"牙體修形程序","meta":"105年第1次第47題","year":105,"session":1,"number":47,"question":"研光（burnishing）用於汞齊填補的那一個階段？","options":["(A) 壓擠（condensation）之前","(B) 雕塑（carving）之前與之後","(C) 磨光（polishing）之後","(D) 完成（finishing）之後"],"answer":1,"clinical_level":"重點"},{"id":"ya3-105-1-48","subject":"ya3","topic":"黏著與美學修復","meta":"105年第1次第48題","year":105,"session":1,"number":48,"question":"關於瓷嵌體（ceramic inlay）的製作及黏著，下列敘述何者錯誤？","options":["(A) 窩洞邊緣不可作斜面（bevel）","(B) 嵌體的窩洞面（inner surface）用氫氟酸或噴砂處理以增加黏合","(C) 用樹脂黏合劑（resin cement）黏著","(D) 未黏著前需在口內作咬合調整"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-1-49","subject":"ya3","topic":"黏著與美學修復","meta":"105年第1次第49題","year":105,"session":1,"number":49,"question":"下列何者為聚羧乙烯（carbopol）在漂白藥劑當中作為添加劑（additive）的目的？","options":["(A) 中和碳醯胺過氧化物（carbamide peroxide）的酸性","(B) 當作漂白劑之激發劑","(C) 當作增厚劑可延長漂白藥劑作用時間","(D) 當作去敏感劑可沉積在牙本質小管，減少漂白後之敏感"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-1-50","subject":"ya3","topic":"黏著與美學修復","meta":"105年第1次第50題","year":105,"session":1,"number":50,"question":"有關上顎前牙的比例（proportionality），下列敘述何者錯誤？","options":["(A) 於正面觀，上顎正中門牙：側門牙：犬齒寬度的黃金比例為1.618：1.0：0.618","(B) 黃金比例的產生是由於60%的人具有此比例","(C) 上顎正中門牙的寬／長比（width-to-length ratio）大約為0.85～0.86","(D) 上顎側門牙的寬／長比（width-to-length ratio）大約為0.76～0.79"],"answer":1,"clinical_level":"重點"},{"id":"ya3-105-1-51","subject":"ya3","topic":"複合樹脂與材料","meta":"105年第1次第51題","year":105,"session":1,"number":51,"question":"製作熱壓式陶瓷嵌體（ceramic inlay），溫度需加熱至：","options":["(A) 500～700℃","(B) 850～1,100℃","(C) 1,300～1,500℃","(D) 1,800～2,100℃"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-1-52","subject":"ya3","topic":"窩洞設計與分類","meta":"105年第1次第52題","year":105,"session":1,"number":52,"question":"下列何者不是鑄造嵌體（inlay）常用的合金？","options":["(A) 高金含量合金（high-gold alloys）","(B) 基底金屬合金（base metal alloys）","(C) 鈀銀合金（palladium-silver alloys）","(D) 鈦合金（titanium alloys）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-1-53","subject":"ya3","topic":"牙科解剖與生理","meta":"105年第1次第53題","year":105,"session":1,"number":53,"question":"下列何者與牙齦上皮角化之關連性最大？","options":["(A) 牙齦上皮層本身","(B) 牙齦上皮下之結締組織","(C) 齒槽骨之緻密程度","(D) 牙周韌帶"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-1-54","subject":"ya3","topic":"牙周疾病與診斷","meta":"105年第1次第54題","year":105,"session":1,"number":54,"question":"下列有關夏庇氏纖維（Sharpey's fiber）之敘述，何者最正確？","options":["(A) 它是內源性纖維（intrinsic fiber）","(B) 它是外源性纖維（extrinsic fiber）","(C) 它將上皮穩定的固定於結締組織上","(D) 它主要的功能是穩定的將上皮細胞連接"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-1-55","subject":"ya3","topic":"牙周疾病與診斷","meta":"105年第1次第55題","year":105,"session":1,"number":55,"question":"有關附連牙齦（attached gingiva）寬度之敘述，下列何者最正確？","options":["(A) 它即是牙齦結締組織附著於牙根表面之長度","(B) 它即是角化牙齦之寬度","(C) 它的寬度也包含上皮組織附著於牙根表面之寬度","(D) 它即是牙齦溝之深度"],"answer":2,"clinical_level":"重點"},{"id":"ya3-105-1-56","subject":"ya3","topic":"牙周疾病與診斷","meta":"105年第1次第56題","year":105,"session":1,"number":56,"question":"P. gingivalis, T. forsythia等牙周致病菌造成口臭，是因為會產生？","options":["(A) Ammonia","(B) Volatile sulfide compounds","(C) N-acetylmuramic acid","(D) Menadione"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-1-57","subject":"ya3","topic":"牙周疾病與診斷","meta":"105年第1次第57題","year":105,"session":1,"number":57,"question":"依統計，下列何種牙周骨缺損（osseous defect）為臨床上最常見？","options":["(A) Hemiseptum","(B) Three-wall osseous defect","(C) Interdental crater","(D) Circumferential defect"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-1-58","subject":"ya3","topic":"牙科解剖與生理","meta":"105年第1次第58題","year":105,"session":1,"number":58,"question":"下列何種細胞，其主要的功能為呈現抗原（antigen-presenting）？","options":["(A) 漿細胞（plasma cells）","(B) 造纖維細胞（fibroblasts）","(C) 嗜中性白血球（neutrophils）","(D) 樹狀突細胞（dendritic cells）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-1-59","subject":"ya3","topic":"牙科解剖與生理","meta":"105年第1次第59題","year":105,"session":1,"number":59,"question":"牙齦溝內系統性體液免疫（systemic humoral immune）反應，依圖中4所示，抗原呈現細胞 （antigen-presenting cells）進入鄰近淋巴結後所產生後續的免疫反應 ，如圖中5、6、7所 示，下列何者錯誤？","options":["(A) 反應5：漿細胞在淋巴結內產生並將牙周致病菌特定抗體送出","(B) 反應5：特定抗體再由淋巴液直接送回到牙齦組織","(C) 反應6：特定抗體將離開循環系統進入牙齦溝內","(D) 反應7：特定抗體可導致對細菌產生凝聚、毒殺和吞噬作用"],"answer":1,"image":"ya3-105-1-59.jpeg","clinical_level":"一般"},{"id":"ya3-105-1-60","subject":"ya3","topic":"牙周疾病與診斷","meta":"105年第1次第60題","year":105,"session":1,"number":60,"question":"根據Haffajee & Socransky（2001年）研究顯示，抽菸者較非抽菸者在某些牙位有較高比例 的牙周致病菌，下列何者非其所指的牙位？","options":["(A) 上顎牙齒的腭側（palatal）","(B) 上顎門牙區","(C) 下顎門牙區","(D) 下顎臼齒區"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-1-61","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第1次第61題","year":105,"session":1,"number":61,"question":"下列關於牙周－根管合併病灶預後的敘述，何者較正確？","options":["(A) 若牙周病因大於根管病因，經牙周治療後可得較佳之預後","(B) 若牙周病因大於根管病因，經根管治療後可得較佳之預後","(C) 若根管病因大於牙周病因，經牙周治療後可得較佳之預後","(D) 若根管病因大於牙周病因，經根管治療後可得較佳之預後"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-1-62","subject":"ya3","topic":"牙科解剖與生理","meta":"105年第1次第62題","year":105,"session":1,"number":62,"question":"宿主對牙齦溝區域內微生物抗原的體液免疫反應，下列過程何者錯誤？","options":["(A) 包括巨噬細胞（macrophages）和蘭格罕氏細胞（Langerhans cells）兩種抗原呈現細胞 會進入牙齦淋巴循環","(B) 此類抗原呈現細胞到達淋巴結後，刺激淋巴細胞產生特異免疫反應","(C) 對牙周病菌的特異抗體，是由牙周組織內的漿細胞（plasma cells）產生","(D) 抗體對微生物作用可導致細菌的調理作用（opsonization）與吞噬作用（phagocytosis）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-1-63","subject":"ya3","topic":"牙周非手術治療","meta":"105年第1次第63題","year":105,"session":1,"number":63,"question":"以curettes做牙齦下牙根整平術時，較使用scaler的優點多，惟下列何者並非其優點？","options":["(A) 預防軟組織撕裂傷","(B) 有較好的觸覺感","(C) 和牙根有較好的緊密接觸","(D) 使用的操作力較小"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-1-64","subject":"ya3","topic":"牙周非手術治療","meta":"105年第1次第64題","year":105,"session":1,"number":64,"question":"牙周基本治療（phase I）約4週後，較可預期的效果為何？","options":["(A) 新骨生成（new bone formation）","(B) 新結締組織附連（new connective tissue attachment）","(C) 長連接上皮附連（long junctional epithelium attachment）","(D) 新牙骨質生成（new cementum formation）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-1-65","subject":"ya3","topic":"牙周手術與再生","meta":"105年第1次第65題","year":105,"session":1,"number":65,"question":"根據文獻資料對Miller class I-II牙齦退縮之個案，預估完全牙根覆蓋的平均百分比（mean % of teeth），下列何種術式效果最好？","options":["(A) 冠向移位翻瓣手術（coronally advanced flap）","(B) 引導組織再生術（guided tissue regeneration）","(C) 牙釉基質蛋白再生術（enamel matrix proteins regenerative technique）","(D) 游離齒齦移植術（free gingival graft）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-1-66","subject":"ya3","topic":"植牙學","meta":"105年第1次第66題","year":105,"session":1,"number":66,"question":"依照Siebert（1983）對齒槽嵴缺損的分類，唇舌寬度正常但冠根方向不足，是屬於Siebert 的那個分類？","options":["(A) Class I","(B) Class II","(C) Class III","(D) Class IV"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-1-67","subject":"ya3","topic":"植牙學","meta":"105年第1次第67題","year":105,"session":1,"number":67,"question":"有關骨移植材料下列之敘述，何者錯誤？","options":["(A) 骨誘導作用（osteoinduction）是一種物理過程","(B) 取自上顎粗隆（maxillary tuberosity）的骨質為鬆質骨","(C) 拔牙後8～12週齒槽窩形成的物質，可作為骨移植材料","(D) 腸骨嵴骨髓（iliac crest marrow）移植常造成牙根吸收現象"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-1-68","subject":"ya3","topic":"牙周手術與再生","meta":"105年第1次第68題","year":105,"session":1,"number":68,"question":"下列關於骨手術（osseous surgery）的敘述何者錯誤？","options":["(A) 逆結構（reverse architecture）是因為喪失齒間骨質（interdental bone）而形成的","(B) 骨切除手術（osseous resective surgery）是最可期待的牙周囊袋減少（pocket reduction）的技術","(C) 一骨壁骨缺損（one-wall bony defect）以骨切除手術為最佳選擇","(D) 骨成形術（osteoplasty）需去除牙齒支持骨（tooth-supporting bone）"],"answer":3,"clinical_level":"重點"},{"id":"ya3-105-1-69","subject":"ya3","topic":"牙周手術與再生","meta":"105年第1次第69題","year":105,"session":1,"number":69,"question":"下列關於牙釉基質蛋白（enamel matrix proteins）的敘述何者錯誤？","options":["(A) 主要成分為牙釉質形成素（amelogenins）","(B) 使用Emdogain®不會引起牙根吸收或黏連","(C) 它無法防止上皮細胞牙根方向移動","(D) 誘導無細胞牙骨質（acelluar cementum）形成"],"answer":2,"clinical_level":"重點"},{"id":"ya3-105-1-70","subject":"ya3","topic":"牙周手術與再生","meta":"105年第1次第70題","year":105,"session":1,"number":70,"question":"藉生物性的改變牙根表面（biomodification of root surface）以促進產生新附連（new attachment），下列敘述何者錯誤？","options":["(A) 檸檬酸（citric acid）在狗與人類的研究皆有相同的良好效果","(B) 纖維黏連蛋白（fibronectin）可以在牙根上形成新附連","(C) 四環素（tetracycline）加纖維黏連蛋白（fibronectin）並不能獲得更好的加乘效果","(D) 四環素（tetracycline）可以移除牙根的非結晶表面層（amorphous surface layer），同時 暴露出牙本質小管（dentinal tubules）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-1-71","subject":"ya3","topic":"牙周手術與再生","meta":"105年第1次第71題","year":105,"session":1,"number":71,"question":"在牙周手術後會有手術區域牙齒敏感（hypersensitivity），有關此一問題之敘述，下列何者 錯誤？","options":["(A) 手術中以牙刮（curette）刮除牙骨質（cementum）使牙本質小管（dentinal tubules）暴 露而引起牙齒敏感","(B) 牙齒敏感會慢慢的在幾週後消失","(C) 在臨床上給抗敏感藥劑（desensitizing agent）通常可以馬上解除患者牙齒敏感的問題","(D) 牙菌斑的控制可以減少牙齒敏感發生"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-1-72","subject":"ya3","topic":"牙周手術與再生","meta":"105年第1次第72題","year":105,"session":1,"number":72,"question":"一般而言，下列何者是牙周手術的禁忌（contraindications）？","options":["(A) 牙周治療時合作度不好的患者（poor patient cooperation）","(B) 有狹心症病史之患者（angina pectoris）","(C) 服用抗凝血劑治療之患者（anticoagulant treatment）","(D) 作過腎臟移植之患者（renal transplantation）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-1-73","subject":"ya3","topic":"牙周疾病與診斷","meta":"105年第1次第73題","year":105,"session":1,"number":73,"question":"在牙周維護性治療（supportive periodontal therapy）檢查中，下列何種檢測較能反應目前牙 周發炎狀況？","options":["(A) X光檢查齒槽骨高度","(B) 牙周附連水平","(C) 牙齒搖動度","(D) 探測流血"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-1-74","subject":"ya3","topic":"牙周非手術治療","meta":"105年第1次第74題","year":105,"session":1,"number":74,"question":"如遇到已接受完牙周病治療的患者，但治療效果不佳；病人仍有抽菸的習慣，並且有糖尿病 的病史，口內多顆牙齒有搖晃情形，那一種回診追蹤的間隔最合適？","options":["(A) 一年一次","(B) 一年兩次","(C) 一年三次","(D) 一年四次以上"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-1-75","subject":"ya3","topic":"牙科解剖與生理","meta":"105年第1次第75題","year":105,"session":1,"number":75,"question":"牙周致病菌P. gingivalis與粥狀斑（atheromatous plaque）之形成，有可能與內毒素引發下 列細胞轉化成泡沫細胞有關？","options":["(A) 嗜中性白血球","(B) 巨噬細胞","(C) T細胞","(D) B細胞"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-1-76","subject":"ya3","topic":"牙科解剖與生理","meta":"105年第1次第76題","year":105,"session":1,"number":76,"question":"天疱瘡（pemphigus）的水疱出現在何處？","options":["(A) 上皮內","(B) 上皮與結締組織交接處","(C) 淺層的結締組織內","(D) 深層的結締組織內"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-1-77","subject":"ya3","topic":"牙周非手術治療","meta":"105年第1次第77題","year":105,"session":1,"number":77,"question":"孕婦有嚴重牙周病時，則下列敘述何者錯誤？","options":["(A) 可能引發早產機率增加","(B) 牙齦溝液中前列腺素E2增加","(C) 牙周病應儘早處理，施行深部牙根整平及合併抗生素治療","(D) 產下體重過輕嬰兒機率增加"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-1-78","subject":"ya3","topic":"植牙學","meta":"105年第1次第78題","year":105,"session":1,"number":78,"question":"有關植體和固定補綴物存活率的影響敘述，下列何者正確？①粗糙面的植體（rough implant surface）存活率高 ② 機械面的植體（machined implant）存活率高 ③植入在移植後的骨 （grafted bone）區域的植體存活率高 ④植牙數目多存活率高 ⑤植牙分布均衡存活率高","options":["(A) ①②③","(B) ①④⑤","(C) ②③④","(D) ③④⑤"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-1-79","subject":"ya3","topic":"植牙學","meta":"105年第1次第79題","year":105,"session":1,"number":79,"question":"在獲取頦（chin）自體骨時，一般要求與下顎前牙根尖的最小距離約為多少？","options":["(A) 3 mm","(B) 5 mm","(C) 7 mm","(D) 8 mm"],"answer":1,"clinical_level":"重點"},{"id":"ya3-105-1-80","subject":"ya3","topic":"植牙學","meta":"105年第1次第80題","year":105,"session":1,"number":80,"question":"有關拔牙後立即植牙之適應症，下列何者錯誤？","options":["(A) 根管治療失敗之牙齒","(B) 牙根斷裂之牙齒","(C) 嚴重牙周病之牙齒","(D) 根尖有較大感染之牙齒"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-2-1","subject":"ya3","topic":"牙科解剖與生理","meta":"105年第2次第1題","year":105,"session":2,"number":1,"question":"有關牙齒發育與解剖的敘述，下列何者正確？","options":["(A) 當牙本質形成（dentinogenesis）啟動後牙濾泡（dental follicle）會形成牙髓（dental pulp）","(B) 赫威氏上皮根鞘（Hertwig's epithelial root sheath）會決定牙根管的大小與形狀","(C) 側根管區（lateral canals）在根管中1／3（middle third）最常出現","(D) 牙本質小管（dentinal tubule）數目由牙髓區（pulp）往周邊（periphery）漸漸減少"],"answer":3,"clinical_level":"重點"},{"id":"ya3-105-2-2","subject":"ya3","topic":"根管治療程序","meta":"105年第2次第2題","year":105,"session":2,"number":2,"question":"有關適當的髓腔入口修形（access preparation）之原則，下列敘述何者錯誤？","options":["(A) 治療前需對牙齒內部解剖有所預測","(B) 遇到根管尋找困難時，橡皮障不能拆下，免得受到污染","(C) 開口的目的是直達根尖孔，而非只達根管入口而已","(D) 一般齒內治療之入口修形，均經過咬合面或舌面而不經由鄰接面"],"answer":1,"clinical_level":"重點"},{"id":"ya3-105-2-3","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第2次第3題","year":105,"session":2,"number":3,"question":"下列那些情況不是引起老人牙齒變色的原因？","options":["(A) 牙釉質變薄","(B) 食物和飲料","(C) 牙本質過度堆積（extensive dentin apposition）","(D) 使用過量四環黴素（tetracycline）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-2-4","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第2次第4題","year":105,"session":2,"number":4,"question":"有關牙髓的A-delta纖維，下列敘述那項錯誤？","options":["(A) 有髓鞘（myelination）","(B) 分佈在pulp-dentin junction處","(C) 閾值比C纖維低","(D) 傳導神經衝動的速度比C纖維慢"],"answer":3,"clinical_level":"重點"},{"id":"ya3-105-2-5","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第2次第5題","year":105,"session":2,"number":5,"question":"牙本質小管之管徑與分布狀況，下列敘述何者正確？","options":["(A) 位於牙本質－牙釉質交界（DEJ）之管徑較大，約為3µm","(B) 位於牙本質－牙釉質交界（DEJ）之管徑較小，約為1µm","(C) 位於牙髓腔側之管徑較大，約為6µm","(D) 位於牙髓腔側之管徑較小，約為3µm"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-2-6","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第2次第6題","year":105,"session":2,"number":6,"question":"下列何者無法用來做為臨床牙髓活性測試？","options":["(A) 電髓測試（electric pulp test）","(B) 熱測試（thermal test）","(C) 紅外線杜卜勒微流儀（infra red Doppler flowmetry）","(D) 窩洞測試（test cavity）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-2-7","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第2次第7題","year":105,"session":2,"number":7,"question":"下列有關口腔顏面疼痛之敘述，何者錯誤？","options":["(A) 疼痛的位置與真正造成疼痛的位置，有相當的距離是為牽連痛（referred pain）","(B) 牙齒的疼痛有可能是非牙齒（nonodontogenic）原因所造成","(C) 由牙齒原因所產生的牽連痛，主要因刺激牙髓中的A-delta 纖維所引發","(D) 牽連痛常會由下顎臼齒患牙轉移到同側的上顎臼齒區或耳朵旁的區域（periauricular area）"],"answer":2,"clinical_level":"重點"},{"id":"ya3-105-2-8","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第2次第8題","year":105,"session":2,"number":8,"question":"發現牙齒根尖放射線透射區時，最常用以鑑別診斷齒源性病變（odontogenic lesion）或非齒源性病變（nonodontogenic lesion）的方法為那一項？","options":["(A) 牙髓活性測試","(B) 偏一角度的根尖片","(C) 病變的位置","(D) 牙周探針探測"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-2-9","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第2次第9題","year":105,"session":2,"number":9,"question":"牙髓活性之相關測試常有遲延反應（delayed response）之測試為：","options":["(A) 窩洞測試","(B) 冷測試","(C) 熱測試","(D) 電髓測試"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-2-10","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第2次第10題","year":105,"session":2,"number":10,"question":"細菌侵入牙髓組織最重要的路徑是：","options":["(A) 透過牙齦溝","(B) 口腔中的齲齒","(C) 經由引菌作用（anachoresis）循環全身","(D) 經由裂齒症（cracked teeth）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-2-11","subject":"ya3","topic":"牙齒外傷處理","meta":"105年第2次第11題","year":105,"session":2,"number":11,"question":"對於疑似牙根橫向斷裂的牙齒，應如何進行X光片拍攝來幫助正確診斷？","options":["(A) 使用與牙齒長軸成90度與45度的垂直照射角度","(B) 使用與牙齒長軸成90度與60度的垂直照射角度","(C) 使用近心與遠心偏移15度的水平照射角度","(D) 使用近心與遠心偏移30度的水平照射角度"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-2-12","subject":"ya3","topic":"牙齒外傷處理","meta":"105年第2次第12題","year":105,"session":2,"number":12,"question":"影響脫落齒再植預後的最重要因素為何？","options":["(A) 病人年齡","(B) 撞擊力之大小","(C) 牙周韌帶細胞存活之多寡","(D) 牙槽骨斷裂與否"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-2-13","subject":"ya3","topic":"牙齒外傷處理","meta":"105年第2次第13題","year":105,"session":2,"number":13,"question":"對於剛受傷的牙齒（traumatized teeth）進行齒髓活性測試，下列敘述何者最合理？","options":["(A) 齒髓活性測試可評估預後（prognosis）","(B) 齒髓活性測試決定何者需要根管治療","(C) 齒髓活性測試可知何者血管供應不正常","(D) 收集齒髓活性測試數值，建立一個基準值以供比較（baseline for comparison）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-2-14","subject":"ya3","topic":"牙齒外傷處理","meta":"105年第2次第14題","year":105,"session":2,"number":14,"question":"患者在外傷後一個小時內，帶著浸泡於鮮奶中的#11前來急診，經評估後決定重新植入牙齒並固定，下列何者錯誤？","options":["(A) 封閉型根尖（closed apex），建議在7～10天時進行根管治療","(B) 封閉型根尖，如超過2週才進行根管治療，則應該先置入氫氧化鈣敷藥觀察","(C) 開放型根尖（open apex），愈早進行根管治療愈好","(D) 開放型根尖，應該每隔3～4週進行牙髓活性試驗"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-2-15","subject":"ya3","topic":"根管治療程序","meta":"105年第2次第15題","year":105,"session":2,"number":15,"question":"下列何者較不適合作為根管沖洗液？","options":["(A) 2.5％次氯酸鈉溶液（NaOCl）","(B) 2％chlorhexidine","(C) MTAD","(D) 3％EDTA"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-2-16","subject":"ya3","topic":"根管器械","meta":"105年第2次第16題","year":105,"session":2,"number":16,"question":"美國牙醫醫協會規格第28號（ADA specification no.28），標準根管銼針（file）不包括下列何種大小？","options":["(A) 4號","(B) 6號","(C) 8號","(D) 10號"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-2-17","subject":"ya3","topic":"根管治療程序","meta":"105年第2次第17題","year":105,"session":2,"number":17,"question":"有關根柱（post）功能之敘述，下列何者正確？","options":["(A) 防止牙齒斷裂","(B) 提供冠心（core）的固持性","(C) 加強牙根與牙冠間的強度","(D) 防止牙齒垂直斷裂"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-2-18","subject":"ya3","topic":"根管器械","meta":"105年第2次第18題","year":105,"session":2,"number":18,"question":"K式根管銼針（K-type files）之橫切面設計由正方形改為菱形（K-Flex type files）之後，下列何者被明顯地提昇？","options":["(A) 抗張強度（tensile strength）","(B) 堅硬度（stiffness）","(C) 彈性度（elasticity）","(D) 可彎曲性（flexibility）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-2-19","subject":"ya3","topic":"根尖手術與再治療","meta":"105年第2次第19題","year":105,"session":2,"number":19,"question":"有關根尖手術（periapical surgery）中根尖切除的敘述，下列何者錯誤？","options":["(A) 切面儘量垂直牙根長軸","(B) 根尖切除達3 mm","(C) 儘量製造粗糙不規則的牙根表面，以利牙骨質附著","(D) 以檸檬酸（citric acid）處理，可以移除牙根切面的塗抹層（smear layer）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-2-20","subject":"ya3","topic":"牙科解剖與生理","meta":"105年第2次第20題","year":105,"session":2,"number":20,"question":"有關手術用止血劑的敘述，下列何者正確？","options":["(A) 止血膠網（Surgicel）主要作用於內生性凝血路徑（intrinsic clotting pathway）","(B) 止血膠棉（gelform）可促進血小板凝集而達到止血效果","(C) 硫酸鐵（ferric sulfate）主要作用於外生性凝血路徑（extrinsic clotting pathway）","(D) 硫酸鈣（calcium sulfate）為生物可吸收性止血劑，主要靠物理性機制達到止血效果"],"answer":3,"clinical_level":"重點"},{"id":"ya3-105-2-21","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第2次第21題","year":105,"session":2,"number":21,"question":"根管治療後，根尖周圍持續存在放射線透過性（radiolucency），對此現象的原因敘述，下列何者錯誤？","options":["(A) 主要原因為根尖部位之根管系統持續存在根管內感染","(B) 根管外存在感染亦為原因之一，最常見之根尖周圍細菌為E. faecalis","(C) 根管過度充填或其他材料引起異物反應（foreign body reaction）","(D) 根尖病灶癒合之疤痕組織（scar tissue）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-2-22","subject":"ya3","topic":"根管治療程序","meta":"105年第2次第22題","year":105,"session":2,"number":22,"question":"Mineral trioxide aggregate（MTA）用於穿孔的修補，主要的優勢為何？","options":["(A) 良好的生物相容性","(B) 硬化時間短，臨床操作便利","(C) 接觸到唾液或血液，不易被沖刷掉","(D) 能直接與齒質鍵結"],"answer":0,"clinical_level":"重點"},{"id":"ya3-105-2-23","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第2次第23題","year":105,"session":2,"number":23,"question":"下列有關牙髓病灶與牙周病灶的說明何者錯誤？","options":["(A) 牙髓病變有時會造成牙周組織的破壞","(B) 牙周病灶有時會造成牙髓組織的病變","(C) 牙髓病灶與牙周病灶可獨立存在","(D) 牙周病灶不會造成牙髓組織的病變"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-2-24","subject":"ya3","topic":"醫學倫理與法規","meta":"105年第2次第24題","year":105,"session":2,"number":24,"question":"患者接受根管治療時，發現有鈣化根管，最好的處理方式為何？","options":["(A) 不要讓患者知道，不要處理","(B) 不要讓患者知道，默默處理","(C) 告知患者，放棄治療","(D) 告知患者，與患者討論治療計畫，必要時須轉診"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-2-25","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第2次第25題","year":105,"session":2,"number":25,"question":"九歲病患主訴上顎門齒吃甜食與喝冰水時會疼痛，晚上睡覺時偶爾會覺得上顎門齒隱隱作痛。檢查發現左上正中牙齒顎側有一 齲齒的窩洞，對冷刺激有疼痛反應且會持續約30秒的時間，無敲痛的現象，牙齒周圍牙齦呈現正常形態且無觸痛情況，放射線 學檢查結果如圖所示。則病患左上正中門齒的診斷為何？","options":["(A) 可逆性牙髓炎（reversible pulpitis）合併正常根尖周圍組織（normal periapical）","(B) 不可逆性牙髓炎（irreversible pulpitis）合併正常根尖周圍組織（normal periapical）","(C) 可逆性牙髓炎（reversible pulpitis）合併無症狀根尖牙周炎（asymptomatic apical periodontitis）","(D) 不可逆性牙髓炎（irreversible pulpitis）合併無症狀根尖牙周炎（asymptomatic apical periodontitis）"],"answer":1,"image":"ya3-105-2-25.jpeg","clinical_level":"重點"},{"id":"ya3-105-2-26","subject":"ya3","topic":"根管治療程序","meta":"105年第2次第26題","year":105,"session":2,"number":26,"question":"承上題，請問對病患左上正中門齒較為合適的治療方式為何？","options":["(A) 間接覆髓治療（indirect pulp capping）","(B) 直接覆髓治療（direct pulp capping）","(C) 冠髓切除術（pulpotomy）","(D) 牙髓切除術（pulpectomy）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-2-27","subject":"ya3","topic":"黏著與美學修復","meta":"105年第2次第27題","year":105,"session":2,"number":27,"question":"下列何者無法作為CAD/CAM嵌體的瓷材？","options":["(A) Leucite-reinforced ceramic","(B) Lithium disilicate","(C) Feldspathic glass ceramic","(D) Zirconia"],"answer":[0,1,2,3],"clinical_level":"一般","explanation_pending":false},{"id":"ya3-105-2-28","subject":"ya3","topic":"牙髓診斷與病理","meta":"105年第2次第28題","year":105,"session":2,"number":28,"question":"有關修復性牙本質（reparative dentin）之敘述何者錯誤？","options":["(A) 牙齒以機械性修形後，在接近牙髓1.5mm處易形成","(B) 牙本質受切割，造牙本質細胞突被破壞，15天內牙髓間葉細胞分化成新的造牙本質細胞","(C) 修復性牙本質幾乎不具牙本質小管","(D) 修復性牙本質即是繼發性牙本質（secondary dentin）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-2-29","subject":"ya3","topic":"牙科解剖與生理","meta":"105年第2次第29題","year":105,"session":2,"number":29,"question":"飲水加氟，氟的添加濃度至少達多少ppm以上，牙齒產生氟斑（fluorosis）的機率顯著增加？","options":["(A) 1 ppm","(B) 20 ppm","(C) 5 ppm","(D) 10 ppm"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-2-30","subject":"ya3","topic":"窩洞設計與分類","meta":"105年第2次第30題","year":105,"session":2,"number":30,"question":"鄰接面牙釉質表面齲蝕通常位於：","options":["(A) 接觸區上（at the contact area）","(B) 接觸區的顏面方向（facial to the contact area）","(C) 接觸區的舌面方向（lingual to the contact area）","(D) 接觸區的牙齦面方向（gingival to the contact area）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-2-31","subject":"ya3","topic":"黏著與美學修復","meta":"105年第2次第31題","year":105,"session":2,"number":31,"question":"有一組牙本質黏著劑，其中甲劑成分是2-Hydroxyethyl methacrylate（HEMA）、樹脂單體，乙劑成分是磷酸酯（phosphoric ester）、水、樹脂單體，下列何者敘述錯誤？","options":["(A) 這是一組自酸蝕（self-etch）黏著劑","(B) 甲劑是黏著劑（adhesive），乙劑是酸蝕處理劑（acidic primer）","(C) 操作時先用甲劑，再使用乙劑","(D) 乙劑用完不需沖洗"],"answer":2,"clinical_level":"重點"},{"id":"ya3-105-2-32","subject":"ya3","topic":"複合樹脂與材料","meta":"105年第2次第32題","year":105,"session":2,"number":32,"question":"根據Feilezer（1987），第四類型窩洞之復形，如下圖，其結構因素（C-factor）是多少？","options":["(A) 0.25～0.5","(B) 1～1.5","(C) 2～3","(D) 4～5"],"answer":0,"image":"ya3-105-2-32.jpeg","clinical_level":"一般"},{"id":"ya3-105-2-33","subject":"ya3","topic":"窩洞設計與分類","meta":"105年第2次第33題","year":105,"session":2,"number":33,"question":"患者於左側上顎小臼齒近心頰側面處齒頸部有明顯V形窩洞，邊緣尖銳，表面平整，經檢查咬合有離中心咬合接觸（eccentric occlusal contact），其最可能的診斷為何？","options":["(A) 酸蝕（erosion）","(B) 咬耗（attrition）","(C) 磨折（abfraction）","(D) 磨耗（abrasion）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-2-34","subject":"ya3","topic":"醫學倫理與法規","meta":"105年第2次第34題","year":105,"session":2,"number":34,"question":"以臨床流行病學理念應用於解釋診斷測試與黃金標準（gold standard）之機率表（contingency table）如下，其中C區（C area）代表：","options":["(A) 真實正反應（true positive）","(B) 虛正反應（false positive）","(C) 真實負反應（true negative）","(D) 虛負反應（false negative）"],"answer":3,"image":"ya3-105-2-34.jpeg","clinical_level":"重點"},{"id":"ya3-105-2-35","subject":"ya3","topic":"窩洞設計與分類","meta":"105年第2次第35題","year":105,"session":2,"number":35,"question":"鄰接面牙釉質齲齒的放射線影像呈現錐形（cone），其尖端朝向何處？","options":["(A) 牙齒鄰接面","(B) 牙釉質牙本質交接面","(C) 牙根尖","(D) 牙冠"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-2-36","subject":"ya3","topic":"窩洞設計與分類","meta":"105年第2次第36題","year":105,"session":2,"number":36,"question":"典型第一類型窩洞，具有幾個線角（line angle）？","options":["(A) 4個","(B) 6個","(C) 8個","(D) 10個"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-2-37","subject":"ya3","topic":"牙體修形程序","meta":"105年第2次第37題","year":105,"session":2,"number":37,"question":"下列何種鎢鋼磨針屬於切削齒質用？","options":["(A) 6刃型（6-blade）","(B) 12刃型（12-blade）","(C) 18刃型（18-blade）","(D) 26刃型（26-blade）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-2-38","subject":"ya3","topic":"牙科解剖與生理","meta":"105年第2次第38題","year":105,"session":2,"number":38,"question":"為了防止大量的口水破壞牙體復形充填品質，可使用阿托品（Atropine），但不可用於那類病患？","options":["(A) 糖尿病","(B) 腎臟病","(C) 肝硬化","(D) 青光眼"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-2-39","subject":"ya3","topic":"牙體修形程序","meta":"105年第2次第39題","year":105,"session":2,"number":39,"question":"後牙橡皮障夾（clamp）的弓（bow）通常位在欲隔離牙齒的何側？","options":["(A) 近心側","(B) 遠心側","(C) 頰側","(D) 舌側"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-2-40","subject":"ya3","topic":"複合樹脂與材料","meta":"105年第2次第40題","year":105,"session":2,"number":40,"question":"複合樹脂中的填料（filler）對物性之影響，下列何者錯誤？","options":["(A) 增加熱膨脹係數","(B) 提高耐磨性","(C) 減少聚合收縮","(D) 增加硬度"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-2-41","subject":"ya3","topic":"牙體修形程序","meta":"105年第2次第41題","year":105,"session":2,"number":41,"question":"前牙複合樹脂填補時，下列何者不是木楔（wedge）使用的主要目的？","options":["(A) 看清樹脂填補的位置","(B) 固定透明帶（strip）的位置","(C) 使相鄰牙齒稍微分開","(D) 避免複合樹脂外懸（overhang）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-2-42","subject":"ya3","topic":"複合樹脂與材料","meta":"105年第2次第42題","year":105,"session":2,"number":42,"question":"依據ADA（American Dental Association）規定，複合樹脂（composite resin）在X光片上需呈現放射線不透性 （radiopacity）應比相同厚度的鋁金屬大，請問鋁金屬的放射線不透性與下列何者相同？","options":["(A) 牙釉質","(B) 牙本質","(C) 牙髓腔","(D) 齲齒"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-2-43","subject":"ya3","topic":"窩洞設計與分類","meta":"105年第2次第43題","year":105,"session":2,"number":43,"question":"下列三種牙釘：①自旋式螺釘（self-threading pin） ②磨擦式閉鎖牙釘（friction-locked pin） ③黏合式牙釘（cemented pin），其固持力（retentive force）由大至小的次序為：","options":["(A) ②＞①＞③","(B) ③＞①＞②","(C) ①＞②＞③","(D) ②＞③＞①"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-2-44","subject":"ya3","topic":"牙體修形程序","meta":"105年第2次第44題","year":105,"session":2,"number":44,"question":"關於汞齊窩洞髓壁（pulpal wall）的修形，下列那一項操作方式錯誤？","options":["(A) 去除感染的牙本質可用圓盤狀匙形挖子（discoid-type spoon excavator）","(B) 去除感染的牙本質可用慢速圓形碳鋼磨針（round carbide bur）","(C) 儘可能用較小的磨針來清除感染的牙本質，以避免過度的深入牙本質","(D) 當刮除（excavation）感染的齒質達到與健康的牙本質硬度相同時就應停止"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-2-45","subject":"ya3","topic":"牙體修形程序","meta":"105年第2次第45題","year":105,"session":2,"number":45,"question":"關於汞齊填壓，下列操作方式何者錯誤？","options":["(A) 一般而言，填壓的步驟需在研磨（trituration）後2.5～3.5分鐘之內完成","(B) 於咬合面窩緣（cavosurface margin）的填壓方向需垂直於窩緣的牙釉質表面","(C) 最初的填壓需使用較大面積的充填尖（nib），才能使窩洞的角落充填緻密","(D) 雕刻前咬合面汞齊需過量填壓（overpack）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-2-46","subject":"ya3","topic":"黏著與美學修復","meta":"105年第2次第46題","year":105,"session":2,"number":46,"question":"下列何者不是造成年輕牙齒外染性變色（extrinsic discoloration）的原因？","options":["(A) 殘存的納史密斯氏膜（Nasmyth's membrane）","(B) 口腔衛生不佳","(C) 生色性微生物（chromogenic microorganism）","(D) 飲水含過量氟化物"],"answer":3,"clinical_level":"重點"},{"id":"ya3-105-2-47","subject":"ya3","topic":"黏著與美學修復","meta":"105年第2次第47題","year":105,"session":2,"number":47,"question":"牙齒於居家漂白（home bleaching）期間發生敏感現象時，下列那一個處置步驟不正確？","options":["(A) 減少牙托（tray）每天配戴的時間","(B) 減少牙托配戴的頻率，由每天改成每2～3天","(C) 於漂白前用氟膠或硝酸鉀溶液（potassium nitrate solution），以牙托配戴30分鐘","(D) 牙面塗佈黏著劑（bonding agent）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-2-48","subject":"ya3","topic":"窩洞設計與分類","meta":"105年第2次第48題","year":105,"session":2,"number":48,"question":"下圖分別是①②③④四位病友的臨床圖片，這四位病友中，那一位是咬耗性（attrition）疾病？","options":["(A) ①","(B) ②","(C) ③","(D) ④"],"answer":2,"image":"ya3-105-2-48.jpeg","clinical_level":"一般"},{"id":"ya3-105-2-49","subject":"ya3","topic":"窩洞設計與分類","meta":"105年第2次第49題","year":105,"session":2,"number":49,"question":"鑄金嵌體窩洞設計中，第二級外展（secondary flare）使用於那一個位置？","options":["(A) 頰側溝的周圍","(B) 咬合面","(C) 鄰接盒的頰側面","(D) 固位溝的周圍"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-2-50","subject":"ya3","topic":"牙體修形程序","meta":"105年第2次第50題","year":105,"session":2,"number":50,"question":"以金屬鑄造體進行第二類窩洞復形時，在鄰接盒處進行二級外展（secondary flare）的修形時，使用下列何種鑽針較為合適？","options":["(A) long pear-shape carbide bur","(B) round carbide bur","(C) pointed football diamond bur","(D) inverted cone diamond bur"],"answer":2,"image":"ya3-105-2-50.jpeg","clinical_level":"一般"},{"id":"ya3-105-2-51","subject":"ya3","topic":"複合樹脂與材料","meta":"105年第2次第51題","year":105,"session":2,"number":51,"question":"鑽石鑽針（diamond bur）中，粗度分類為中（medium）者，其顆粒大小應為下列何者？","options":["(A) 125～150 µm","(B) 88～125 µm","(C) 60～74 µm","(D) 38～44 µm"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-2-52","subject":"ya3","topic":"複合樹脂與材料","meta":"105年第2次第52題","year":105,"session":2,"number":52,"question":"相較於傳統鹵素光燈，有關氬雷射（argon laser）對複合樹脂的聚合，下列何者錯誤？","options":["(A) 樹脂聚合程度較高","(B) 光照深度較深","(C) 光波段較集中","(D) 光照溫度較低"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-2-53","subject":"ya3","topic":"牙科解剖與生理","meta":"105年第2次第53題","year":105,"session":2,"number":53,"question":"牙冠與牙根之牙本質是由下列何者分化（differentiation）而來？","options":["(A) Ectoderm","(B) Dental papilla","(C) Dental follicle","(D) Hertwig's epithelial root sheath"],"answer":1,"clinical_level":"重點"},{"id":"ya3-105-2-54","subject":"ya3","topic":"牙科解剖與生理","meta":"105年第2次第54題","year":105,"session":2,"number":54,"question":"下列有關牙骨質之敘述，何者錯誤？","options":["(A) 所含的礦化物質主要是氫氧磷灰石（hydroxyapatite）","(B) 與骨骼相似，包含血管及淋巴管，但是不包含神經組織","(C) 恆牙牙骨質不進行生理性吸收或重塑（remodeling），終其一生持續沈積","(D) 無細胞外生性纖維牙骨質主要發現於靠近齒頸端部分"],"answer":1,"clinical_level":"重點"},{"id":"ya3-105-2-55","subject":"ya3","topic":"牙科解剖與生理","meta":"105年第2次第55題","year":105,"session":2,"number":55,"question":"下圖為牙周齒槽骨表面之組織切片，經抗酒石酸鹽酸性磷酸酶（tartrate resistant acid phosphatase，TRAP）染色後，箭頭所 指處，下列何者最正確？","options":["(A) 它是造骨細胞（osteoblasts）","(B) 它是破骨細胞（osteoclasts）","(C) 它是神經叢（nerve bundles）","(D) 它是血管叢（blood vessels）"],"answer":1,"image":"ya3-105-2-55.jpeg","clinical_level":"一般"},{"id":"ya3-105-2-56","subject":"ya3","topic":"牙科解剖與生理","meta":"105年第2次第56題","year":105,"session":2,"number":56,"question":"Th-3 cell cytokine（TGF-β），主要可促進下列那種免疫球蛋白之合成轉換（switch）？","options":["(A) IgA","(B) IgE","(C) IgG","(D) IgM"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-2-57","subject":"ya3","topic":"牙周疾病與診斷","meta":"105年第2次第57題","year":105,"session":2,"number":57,"question":"某牙齒治療前囊袋深度達8 mm，牙齦退縮為2 mm，治療後探測深度變為5 mm，牙齦退縮為3 mm，其附連高度變化為：","options":["(A) 增加2 mm","(B) 增加3 mm","(C) 减少2 mm","(D) 减少3 mm"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-2-58","subject":"ya3","topic":"牙周手術與再生","meta":"105年第2次第58題","year":105,"session":2,"number":58,"question":"下列何種方法最適合用在牙周炎的初期牙根分叉侵犯（grade I furcation involvement）的治療？","options":["(A) 分叉處成形術（furcation plasty）","(B) 牙根切除術（root resection）","(C) 塗佈牙釉基質衍生物（enamel matrix derivatives）","(D) 骨移植術（bone grafting）"],"answer":0,"clinical_level":"重點"},{"id":"ya3-105-2-59","subject":"ya3","topic":"牙周疾病與診斷","meta":"105年第2次第59題","year":105,"session":2,"number":59,"question":"有關動情激素（estrogen）和黃體酮（progesterone）可影響牙周組織之敘述，下列何者錯誤？","options":["(A) 動情激素可影響唾液過氧化酵素（peroxidase）對抗不同微生物","(B) 動情激素可刺激膠原蛋白的代謝，但是不會促進血管形成（angionesis）","(C) 動情激素可觸發autocrine和paracrine的多胜肽生長因子訊息路徑","(D) 動情激素和黃體酮可調節牙周組織內血管反應和結締組織的更新"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-2-60","subject":"ya3","topic":"牙周疾病與診斷","meta":"105年第2次第60題","year":105,"session":2,"number":60,"question":"有關牙周炎與植體周圍炎的組織病理變化之敘述，下列何者正確？①牙周炎與齒槽骨之間有1 mm的未發炎結締組織隔開 ② 植體周圍炎處有大量嗜中性白血球，並在病灶和生物膜之間缺少上皮隔開","options":["(A) ①正確 ②錯誤","(B) ①錯誤 ②正確","(C) ①②均正確","(D) ①②均錯誤"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-2-61","subject":"ya3","topic":"牙周疾病與診斷","meta":"105年第2次第61題","year":105,"session":2,"number":61,"question":"罹患牙周病的病人與抽菸的關係，下列敘述何者錯誤？","options":["(A) 抽菸會促進牙齦血管擴張，亦會增加牙齦探測流血（bleeding on probing）之現象","(B) 抽菸會降低免疫細胞的吞噬反應","(C) 抽菸會增加囊袋探測深度，也會增加齒槽骨的吸收","(D) 抽菸會增加牙周手術治療後的不良反應"],"answer":0,"clinical_level":"重點"},{"id":"ya3-105-2-62","subject":"ya3","topic":"牙科解剖與生理","meta":"105年第2次第62題","year":105,"session":2,"number":62,"question":"在牙周疾病發展的免疫反應中，有關T細胞的分化（differentiation）的敘述，下列何項錯誤？","options":["(A) T細胞分化且成熟的路徑，是經由與抗原呈現細胞（antigen-presenting cell）相互黏著（adhesion）和相互作用 （interaction）而決定","(B) 抗原呈現細胞（antigen-presenting cell）分泌較高量的IL-12胞激素，有利於T細胞分化成T helper 1細胞","(C) 細胞激素IL-4，IL-10會阻礙T helper 1細胞的分化並提升T helper 2細胞的分化","(D) T helper 1細胞主要是對抗extracellular antigen，T helper 2細胞主要是控制且對抗intracellular molecule"],"answer":3,"clinical_level":"重點"},{"id":"ya3-105-2-63","subject":"ya3","topic":"牙周非手術治療","meta":"105年第2次第63題","year":105,"session":2,"number":63,"question":"目前認可最有效的牙菌斑控制和牙齦炎治療的漱口水，係因其中含有下列何種物質之故？","options":["(A) Sanguinarine","(B) Stannous fluoride","(C) Chlorhexidine and essential oil","(D) Quaternary ammonium compounds"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-2-64","subject":"ya3","topic":"牙周疾病與診斷","meta":"105年第2次第64題","year":105,"session":2,"number":64,"question":"對於臨床牙齦輕微發炎，用牙周探測具（periodontal probe）去探測時沒有流血；若使用gingival index（Löe and Silness）來 紀錄牙齦發炎程度，其數值為：","options":["(A) 0","(B) 1","(C) 2","(D) 3"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-2-65","subject":"ya3","topic":"牙周手術與再生","meta":"105年第2次第65題","year":105,"session":2,"number":65,"question":"在牙齦切除術後由牙周韌帶來的微血管，在手術後至少幾天才會與牙齦的血管接合？","options":["(A) 7","(B) 14","(C) 28","(D) 56"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-2-66","subject":"ya3","topic":"牙周疾病與診斷","meta":"105年第2次第66題","year":105,"session":2,"number":66,"question":"Hamp等人（1975）的根叉侵犯分類所測量的是何項根叉缺損？","options":["(A) 寬度","(B) 長度","(C) 垂直缺損","(D) 水平缺損"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-2-67","subject":"ya3","topic":"牙周手術與再生","meta":"105年第2次第67題","year":105,"session":2,"number":67,"question":"游離牙齦移植術的癒合會受到移植體（graft）的影響，下列敘述何者正確？","options":["(A) 移植體達到功能性整合（functional integration）所需時間比移植體與周圍組織的形態上可區別性所需時間更長","(B) 0.75 mm厚度的移植體約需10.5週才會完全癒合","(C) 1.75 mm厚度的移植體約需12.5週才會完全癒合","(D) 來自角化上皮（keratinized epitheliun）的移植體常含上皮與結締組織（connective tissue）一併移植"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-2-68","subject":"ya3","topic":"牙周手術與再生","meta":"105年第2次第68題","year":105,"session":2,"number":68,"question":"下列何者不是牙齦切除術或牙齦整形術之適應症？","options":["(A) 牙齦肥大（gingival enlargement）","(B) 陷口狀牙齦（gingival crater）","(C) 深的齒槽骨上囊袋（deep suprabony pocket）","(D) 骨陷口（bony crater）"],"answer":3,"clinical_level":"重點"},{"id":"ya3-105-2-69","subject":"ya3","topic":"牙周手術與再生","meta":"105年第2次第69題","year":105,"session":2,"number":69,"question":"有關引導組織再生術（guided tissue regeneration, GTR）應用於牙根覆蓋的手術之敘述，下列何者錯誤？","options":["(A) 術後除了達到牙根覆蓋外，也可重建附連組織","(B) 使用牙周敷料以保護傷口","(C) 依照Pini Prato等人1992年之研究，大於4.98 mm之牙齦退縮，GTR比游離齒齦移植得到較多的牙根覆蓋","(D) 使用全皮層瓣術先翻瓣到黏膜齒齦交界處，超過黏膜齒齦交界處再使用部分皮層瓣術"],"answer":1,"clinical_level":"重點"},{"id":"ya3-105-2-70","subject":"ya3","topic":"牙周手術與再生","meta":"105年第2次第70題","year":105,"session":2,"number":70,"question":"進行臨床牙冠加長術時，齒槽骨嵴至補綴物邊緣最少應有多少mm距離以維持牙周健康？","options":["(A) 1","(B) 2","(C) 3","(D) 4"],"answer":2,"clinical_level":"一般"},{"id":"ya3-105-2-71","subject":"ya3","topic":"牙周手術與再生","meta":"105年第2次第71題","year":105,"session":2,"number":71,"question":"下列何者不是牙周骨切除術（resective osseous surgery）的適應症？","options":["(A) 較深的三壁骨內缺損","(B) 淺的骨陷口（crater）","(C) 骨嵴邊緣較厚","(D) 骨嵴邊緣不規則"],"answer":0,"clinical_level":"重點"},{"id":"ya3-105-2-72","subject":"ya3","topic":"牙周手術與再生","meta":"105年第2次第72題","year":105,"session":2,"number":72,"question":"下列那種縫線組織反應最低？","options":["(A) Silk","(B) ePTFE","(C) Gut","(D) Polyglactin 910"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-2-73","subject":"ya3","topic":"牙周疾病與診斷","meta":"105年第2次第73題","year":105,"session":2,"number":73,"question":"因牙齒解剖構造（anatomic factor）會影響牙周病牙齒的治療預後（prognosis），依據此觀念列出三類牙齒①犬齒 ②第二小 臼齒 ③第二大臼齒，預後由好至壞的排列次序為：","options":["(A) ①③②","(B) ③①②","(C) ②③①","(D) ①②③"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-2-74","subject":"ya3","topic":"牙周疾病與診斷","meta":"105年第2次第74題","year":105,"session":2,"number":74,"question":"抽菸對牙周病的致病原因和治療時的影響，下列敘述何者錯誤？","options":["(A) 抽菸會對牙菌斑堆積速率有影響","(B) 抽菸會增加深的牙周囊袋內牙周致病菌的水平（levels）","(C) 抽菸會對牙周引導組織再生手術有負向影響","(D) 抽菸會增加在牙周手術後維持期時牙根分岔處的破壞"],"answer":0,"clinical_level":"重點"},{"id":"ya3-105-2-75","subject":"ya3","topic":"牙周非手術治療","meta":"105年第2次第75題","year":105,"session":2,"number":75,"question":"治療有糖尿病的牙周病病患，有合併使用低劑量doxycycline之治療方式，其目的為何？","options":["(A) 減少基質金屬蛋白酶（matrix metalloproteinases）","(B) 抑制牙周致病菌","(C) 抑制PGE2的產生","(D) 減少TNF-α"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-2-76","subject":"ya3","topic":"牙周疾病與診斷","meta":"105年第2次第76題","year":105,"session":2,"number":76,"question":"由於alkaline phosphatase之缺陷，導致牙骨質發育不良，乳牙提早脫落之嚴重牙周病為：","options":["(A) Papillon-Lefèvre syndrome","(B) Ehler-Danlos syndrome","(C) Leukocyte adhesion deficiency","(D) Hypophosphatasia"],"answer":3,"clinical_level":"一般"},{"id":"ya3-105-2-77","subject":"ya3","topic":"牙周疾病與診斷","meta":"105年第2次第77題","year":105,"session":2,"number":77,"question":"病患有高血壓之病史，牙齦出現腫大，此症狀與下列何種類之降血壓藥最有關聯？","options":["(A) 利尿劑","(B) 鈣離子通道阻斷劑","(C) β-阻斷劑（β-blockers）","(D) α-阻斷劑（α-blockers）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-105-2-78","subject":"ya3","topic":"植牙學","meta":"105年第2次第78題","year":105,"session":2,"number":78,"question":"下列何種植體周圍炎的情況適合做根向位移翻瓣術與切除性手術（apically positioned flap and osseous resective therapy）？ ①中度至重度水平性骨吸收且垂直性骨吸收小於3 mm ②單壁及雙壁骨缺損（one-wall and two-wall bone defects） ③植體 種植於美觀區 ④植體表面不易消毒清潔（detoxification）","options":["(A) 僅①②","(B) 僅②④","(C) ①②④","(D) ①③④"],"answer":0,"clinical_level":"一般"},{"id":"ya3-105-2-79","subject":"ya3","topic":"牙科解剖與生理","meta":"105年第2次第79題","year":105,"session":2,"number":79,"question":"服用抗凝血劑warfarin之病患，有關植牙手術前之考量敘述，下列何者錯誤？","options":["(A) Warfarin主要是抑制維生素K依賴型凝血因子","(B) Warfarin抑制II, VII, IX, X凝血因子","(C) 檢測服用warfarin患者的凝血狀況，主要的檢查是活化部份凝血酶時間（activated partial thromboplastin time）","(D) 病患半年內有中風病史，不可隨意讓患者停止服用warfarin"],"answer":2,"clinical_level":"重點"},{"id":"ya3-105-2-80","subject":"ya3","topic":"植牙學","meta":"105年第2次第80題","year":105,"session":2,"number":80,"question":"前牙美觀區的植牙，為了美觀考量，植體上緣平台面須放置於比鄰牙唇側之牙骨質－牙釉質交界處（cemento-enamel junction），更往根尖向多少毫米（mm）？","options":["(A) 0","(B) 1～2","(C) 4～5","(D) ＞5"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-1-1","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第1次第1題","year":106,"session":1,"number":1,"question":"有關牙本質（dentin）之敘述，下列何者錯誤？","options":["(A) 主要含70％的無機物（inorganic substance）","(B) 主要的無機物為Ca10(PO4)6(OH)2","(C) 其中30％為有機成分（organic substance）","(D) 有機物中大部分為膠原蛋白（collagen）"],"answer":2,"clinical_level":"重點"},{"id":"ya3-106-1-2","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第1次第2題","year":106,"session":1,"number":2,"question":"在牙齒形成過程中，造牙本質細胞（odontoblast）的分化，是由下列那一種細胞釋放各種生長因子所刺激產生？","options":["(A) 外釉上皮（outer enamel epithelium）","(B) 內釉上皮（inner enamel epithelium）","(C) 網狀星形細胞層（stellate reticulum）","(D) 基底膜（basement membrane）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-1-3","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第1次第3題","year":106,"session":1,"number":3,"question":"下列有關對根管鈣化（canal calcification）的敘述，何者錯誤？","options":["(A) 隨著年齡的增加而增加","(B) 女性比男性嚴重","(C) 外傷可能會加速其形成","(D) 牙髓炎會加速其形成"],"answer":1,"clinical_level":"重點"},{"id":"ya3-106-1-4","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第1次第4題","year":106,"session":1,"number":4,"question":"下列有關牙髓神經A-delta纖維與C纖維的疼痛閾值，何者正確？","options":["(A) A-delta纖維較C纖維高","(B) A-delta纖維較C纖維低","(C) 二者高低不一定","(D) 二者無差異"],"answer":1,"clinical_level":"重點"},{"id":"ya3-106-1-5","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第1次第5題","year":106,"session":1,"number":5,"question":"牙髓組織的那個區域是儲備細胞（reserve cell）的主要來源區？","options":["(A) 中央區（central zone）","(B) 多細胞區（cell-rich zone）","(C) 無細胞區（cell-free zone）","(D) 造牙本質細胞區（odontoblastic zone）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-1-6","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第1次第6題","year":106,"session":1,"number":6,"question":"有關牙髓測試（pulp test）的使用原理，下列何者正確？","options":["(A) 電子牙髓測試主要使用微弱電流，以刺激牙髓本體的C型神經纖維","(B) 1989年Bender發現前牙區（anterior teeth），放置電子牙髓測試探頭（probe）的理想位置是在牙頸部（cervical）","(C) 溫度變化測試（thermal test）主要是活化牙本質小管（dentinal tubules）內牙本質液（dentinal fluid），轉而刺激牙髓的A型 神經纖維","(D) 溫度變化測試（thermal test）中，冷測試（cold test）較有可能傷害牙髓組織"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-1-7","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第1次第7題","year":106,"session":1,"number":7,"question":"有關根尖囊腫（radicular cyst）之敘述，下列何者錯誤？","options":["(A) 無法由X光片明確判讀","(B) 根據是否與根管相通，可以分成pocket cyst與true cyst","(C) 根尖囊袋性囊腫（pocket cyst）經根管治療後，須再經手術方能癒合","(D) 根尖真性囊腫（true cyst）特別是含有大量膽固醇（cholesterol）堆積者，常造成根管治療後根尖病變持續存在"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-1-8","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第1次第8題","year":106,"session":1,"number":8,"question":"根尖周圍組織發炎持續存在與下列何者有關？","options":["(A) 殘留牙髓組織","(B) 微生物","(C) 不流動的組織液","(D) 無菌的壞死牙髓"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-1-9","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第1次第9題","year":106,"session":1,"number":9,"question":"42歲女性患者主訴右下後牙區在喝冷水時有劇烈抽痛的現象，其X光片如下圖所示。造成患者主訴疼痛的牙齒與病因來源為 何？","options":["(A) 第一大臼齒的牙髓病變","(B) 第一大臼齒的根尖周圍病變","(C) 第二大臼齒的牙髓病變","(D) 第二大臼齒的根尖周圍病變"],"answer":2,"image":"ya3-106-1-9.jpeg","clinical_level":"一般"},{"id":"ya3-106-1-10","subject":"ya3","topic":"根尖手術與再治療","meta":"106年第1次第10題","year":106,"session":1,"number":10,"question":"比較下圖兩張X光片中的第一小臼齒，並選出最恰當的敘述？","options":["(A) 該牙齒接受根管治療及根尖區手術，根尖區組織修復（repair）","(B) 該牙齒接受根管治療及根尖區手術，牙根處出現外生骨贅（exostosis）","(C) 該牙齒接受根管治療，併發齒頸部吸收（cervical resorption）","(D) 該牙齒接受根管治療，牙根尖發生取代性吸收（replacement resorption）"],"answer":0,"image":"ya3-106-1-10.jpeg","clinical_level":"一般"},{"id":"ya3-106-1-11","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第1次第11題","year":106,"session":1,"number":11,"question":"下列何者較不易用於診斷牙根垂直斷裂？","options":["(A) 光環狀（halo-like）骨喪失","(B) J型（J-type）牙根周圍骨病灶","(C) 深窄牙周囊袋（deep narrow pocket）","(D) 根尖疏鬆（apical rarefaction）影像"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-1-12","subject":"ya3","topic":"牙齒外傷處理","meta":"106年第1次第12題","year":106,"session":1,"number":12,"question":"外傷牙齒於下列那一項情況必須進行根管治療？","options":["(A) 產生發炎性牙根外吸收","(B) 產生取代性牙根外吸收","(C) 牙髓測試呈現陰性反應","(D) 牙冠變色"],"answer":0,"clinical_level":"一般"},{"id":"ya3-106-1-13","subject":"ya3","topic":"牙齒外傷處理","meta":"106年第1次第13題","year":106,"session":1,"number":13,"question":"進行Cvek冠髓切除術（Cvek pulpotomy）時，一般需移除牙髓暴露處以下多深的牙髓組織？","options":["(A) 1 mm","(B) 2 mm","(C) 4 mm","(D) 6 mm"],"answer":1,"clinical_level":"重點"},{"id":"ya3-106-1-14","subject":"ya3","topic":"牙齒外傷處理","meta":"106年第1次第14題","year":106,"session":1,"number":14,"question":"牙齒受到外傷後，敲擊牙齒時會產生敏感或疼痛，牙齒動搖度（mobility）也有增加，但是牙齒本身並沒有位移 （displacement）的情形，是為下列何者？","options":["(A) concussion","(B) subluxation","(C) extrusive luxation","(D) intrusive luxation"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-1-15","subject":"ya3","topic":"根管治療程序","meta":"106年第1次第15題","year":106,"session":1,"number":15,"question":"下列何者對於Enterococcus faecalis最具殺菌效力？","options":["(A) 5％NaOCl","(B) 0.12％CHX","(C) 17％EDTA","(D) Ca(OH)2"],"answer":0,"clinical_level":"重點"},{"id":"ya3-106-1-16","subject":"ya3","topic":"根管治療程序","meta":"106年第1次第16題","year":106,"session":1,"number":16,"question":"有關根管治療用的牙膠針（gutta-percha cone）各成分之功能，下列敘述何者錯誤？","options":["(A) 馬來牙膠（gutta-percha）做為基質（matrix）用","(B) 氧化鋅（zinc oxide）做為填料（filler）用","(C) 重金屬鹽類（heavy metal salts）做為放射線不透性（radiopacity）用","(D) 蠟或樹脂（wax or resin）做為提高其強度用"],"answer":3,"clinical_level":"重點"},{"id":"ya3-106-1-17","subject":"ya3","topic":"根管器械","meta":"106年第1次第17題","year":106,"session":1,"number":17,"question":"有關20號標準根管銼針（file），下列敘述何者錯誤？","options":["(A) 顏色為黃色","(B) 錐度（.04 taper）其D0之直徑為0.20 mm","(C) 錐度（.02 taper）其D16之直徑為0.32 mm","(D) 錐度（.04 taper）其D16之直徑為0.84 mm"],"answer":2,"clinical_level":"重點"},{"id":"ya3-106-1-18","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第1次第18題","year":106,"session":1,"number":18,"question":"如果患者唾液分泌量很多，導致橡皮障（rubber dam）隔絕效果不佳時，可給予下列何種藥物以減少分泌？","options":["(A) 副交感神經拮抗劑（anticholinergic agent）","(B) 抗膽素脂酵素（anticholinesterase）","(C) 抗痙攣劑（anticonvulsive agent）","(D) 抑腎上腺劑（adrenolytic agent）"],"answer":0,"clinical_level":"重點"},{"id":"ya3-106-1-19","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第1次第19題","year":106,"session":1,"number":19,"question":"下列為治療同顆牙齒拍攝不同角度的X光片。相對於A圖，B圖中第一大臼齒拍攝的角度以及箭頭所指的根管名稱為何？","options":["(A) 從近心側往遠心側拍攝，箭頭所指根管為近心頰側根管（MB canal）","(B) 從近心側往遠心側拍攝，箭頭所指為第二近心頰側根管（MB2 canal）","(C) 從遠心側往近心側拍攝，箭頭所指為近心頰側根管（MB canal）","(D) 從遠心側往近心側拍攝，箭頭所指為第二近心頰側根管（MB2 canal）"],"answer":2,"image":"ya3-106-1-19.jpeg","clinical_level":"一般"},{"id":"ya3-106-1-20","subject":"ya3","topic":"根管治療程序","meta":"106年第1次第20題","year":106,"session":1,"number":20,"question":"牙髓腔開擴（access opening）要去除齒頸部三角（cervical triangle），其主要目的為何？","options":["(A) 去除牙髓角（pulp horns）","(B) 達成器械不受阻礙的直線入口（straight-line access）","(C) 移除所有峽部（isthmus）","(D) 容易找出最大之根管"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-1-21","subject":"ya3","topic":"根尖手術與再治療","meta":"106年第1次第21題","year":106,"session":1,"number":21,"question":"下列何者不是一般根尖周圍手術傷口癒合中經過三個相關連的時期？","options":["(A) 發炎時期（inflammatory phase）","(B) 組織增生／再生時期（proliferation phase）","(C) 組織修補時期（repair phase）","(D) 組織成熟時期（maturation phase）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-1-22","subject":"ya3","topic":"根尖手術與再治療","meta":"106年第1次第22題","year":106,"session":1,"number":22,"question":"目前常用的牙根尖逆充填材料中，封填能力與生物相容性最優者為：","options":["(A) Super EBA","(B) Intermediate Restorative Material（IRM）","(C) Amalgam","(D) Mineral trioxide aggregate（MTA）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-1-23","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第1次第23題","year":106,"session":1,"number":23,"question":"以下那一種菌株常被發現於失敗的根管治療牙齒，可單獨存活於根管中成為單一感染（monoinfection）？","options":["(A) Enterococcus faecalis","(B) Fusobacterium necrophorum","(C) Porphyromonas gingivalis","(D) Prevotella oralis"],"answer":0,"clinical_level":"一般"},{"id":"ya3-106-1-24","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第1次第24題","year":106,"session":1,"number":24,"question":"筋膜空間感染依據發生位置分為下顎骨以下、面頰與側臉部、咽喉與頸部、中臉部等四大區域，其中下顎骨以下的解剖感染位 置對根管治療關聯最大，下列何者不是下顎骨以下部位的解剖感染位置？","options":["(A) 頰側前庭空間（buccal vestibulae space）","(B) 頦下空間（submental space）","(C) 舌下空間（sublingual space）","(D) 面頰空間（buccal space）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-1-25","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第1次第25題","year":106,"session":1,"number":25,"question":"相較於年輕的病人，對於年長病人根管開口（orifice）的敘述，下列何者正確？","options":["(A) 在X光片下年長的病人根管開口較靠近根尖","(B) 臨床上年長的病人根管開口較靠近牙齒的根尖","(C) 醫師較容易感覺出年長病人根管的開口","(D) 年長病人根管的開口變異性較大"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-1-26","subject":"ya3","topic":"複合樹脂與材料","meta":"106年第1次第26題","year":106,"session":1,"number":26,"question":"當進行修形和磨光（finishing and polishing）操作時，牙醫師為達到增強視覺效果而採用某些處理方式，下列何者為不當的醫 療行為？","options":["(A) 採用橡皮障來防濕","(B) 只單獨使用空氣冷卻（air coolant），並以高速持續性施行研磨","(C) 使用頭罩式放大鏡裝置","(D) 使用高容量吸除器（high-volume evacuator）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-1-27","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第1次第27題","year":106,"session":1,"number":27,"question":"下列何者不是老人牙齒顏色逐漸變黃的主因？","options":["(A) 牙釉質變薄","(B) 牙釉質變透明","(C) 牙釉質表面堆積微量元素","(D) 硬化牙本質（sclerotic dentin）變少"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-1-28","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第1次第28題","year":106,"session":1,"number":28,"question":"正常成人唾液分泌量約為：","options":["(A) 1～1.5公升／週","(B) 1～1.5公升／天","(C) 2.5～3.0公升／週","(D) 2.5～3.0公升／天"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-1-29","subject":"ya3","topic":"黏著與美學修復","meta":"106年第1次第29題","year":106,"session":1,"number":29,"question":"下列那一種牙齒變色可經由磨光（polishing）來移除？","options":["(A) 發育及礦化變異","(B) 外來的染色","(C) 攝取過量的氟化物","(D) 四環黴素造成變色"],"answer":1,"clinical_level":"重點"},{"id":"ya3-106-1-30","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第1次第30題","year":106,"session":1,"number":30,"question":"下列那個因素不是唾液抑制齲齒的機轉？","options":["(A) 沖除細菌","(B) 中和細菌酸性代謝物","(C) 促進齒質再礦化","(D) 潤滑口腔黏膜"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-1-31","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第1次第31題","year":106,"session":1,"number":31,"question":"關於突變形鏈球菌（mutans streptococci）易造成齲齒的原因，何者錯誤？","options":["(A) 可以附著於牙釉質（enamel）上","(B) 會產生酸","(C) 不耐酸","(D) 會產生bacteriocins"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-1-32","subject":"ya3","topic":"窩洞設計與分類","meta":"106年第1次第32題","year":106,"session":1,"number":32,"question":"下列有關牙根齲蝕之敘述，何者錯誤？","options":["(A) 進展相當緩慢","(B) 通常沒有症狀","(C) 較接近牙髓","(D) 發生率受唾液分泌量影響"],"answer":0,"clinical_level":"一般"},{"id":"ya3-106-1-33","subject":"ya3","topic":"複合樹脂與材料","meta":"106年第1次第33題","year":106,"session":1,"number":33,"question":"根據Feilzer（1987），結構因子（configuration-factor, C-factor）之定義為何？","options":["(A) 鍵結面的數目除以未鍵結面的數目","(B) 未鍵結面的數目除以鍵結面的數目","(C) 鍵結面的數目減未鍵結面的數目","(D) 未鍵結面的數目減鍵結面的數目"],"answer":0,"clinical_level":"一般"},{"id":"ya3-106-1-34","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第1次第34題","year":106,"session":1,"number":34,"question":"關於牙根表面的硬化牙本質（sclerotic dentin）敘述，下列何者錯誤？","options":["(A) 由於外源性染色的緣故，所以顏色通常較深","(B) 用探針去檢查，可發現其質地是堅硬的","(C) 相較於一般牙本質，對酸蝕的抵抗（resistance）較強","(D) 通常是由於活躍性（active）齲齒造成"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-1-35","subject":"ya3","topic":"牙體修形程序","meta":"106年第1次第35題","year":106,"session":1,"number":35,"question":"就磨針刃（bur blade）設計而言，若負的耙狀角度（negative rake angle）愈大時，下列敘述何者正確？","options":["(A) 磨針切削效能（cutting efficiency）會愈大","(B) 移除切削碎末（chips）會愈多","(C) 切削碎末（chips）堵塞愈多","(D) 磨針使用期限愈長"],"answer":3,"clinical_level":"重點"},{"id":"ya3-106-1-36","subject":"ya3","topic":"窩洞設計與分類","meta":"106年第1次第36題","year":106,"session":1,"number":36,"question":"右下顎第一大臼齒，齲齒範圍涵蓋近心面、咬合面、頰側面與咬頭，則修形的窩洞屬於下列那一類型？","options":["(A) 第一類型窩洞","(B) 第二類型窩洞","(C) 第三類型窩洞","(D) 第四類型窩洞"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-1-37","subject":"ya3","topic":"窩洞設計與分類","meta":"106年第1次第37題","year":106,"session":1,"number":37,"question":"關於窩洞底（cavity floor）的敘述，下列何者錯誤？","options":["(A) 與牙齒長軸（long axis）平行的平面","(B) 與咬合力的方向垂直的平面","(C) 是增加抗力形（resistance form）的構造","(D) 是分散咬合力的構造"],"answer":0,"clinical_level":"一般"},{"id":"ya3-106-1-38","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第1次第38題","year":106,"session":1,"number":38,"question":"下列何種疾病的病患可能較不適合使用橡皮障（rubber dam）作為操作範圍隔離的器具？","options":["(A) 高血壓","(B) 糖尿病","(C) 氣喘","(D) 心臟病"],"answer":2,"clinical_level":"重點"},{"id":"ya3-106-1-39","subject":"ya3","topic":"牙體修形程序","meta":"106年第1次第39題","year":106,"session":1,"number":39,"question":"橡皮障在齒齦緣必須反轉（inversion）向牙齦溝，其目的為何？","options":["(A) 增加密封性","(B) 保護牙齦","(C) 保護橡皮障","(D) 保護牙齒"],"answer":0,"clinical_level":"重點"},{"id":"ya3-106-1-40","subject":"ya3","topic":"窩洞設計與分類","meta":"106年第1次第40題","year":106,"session":1,"number":40,"question":"第三類型（class III）窩洞的齲蝕若侵犯至牙本質－牙骨質面時，則窩洞的斜面（bevel）設計應在何處？","options":["(A) 牙釉質緣","(B) 牙骨質緣","(C) 牙本質－牙骨質面","(D) 牙釉質緣與牙本質－牙骨質面"],"answer":0,"clinical_level":"一般"},{"id":"ya3-106-1-41","subject":"ya3","topic":"黏著與美學修復","meta":"106年第1次第41題","year":106,"session":1,"number":41,"question":"在第二類型（class II）窩洞複合樹脂填補時，若無牙髓暴露疑慮，對於襯底（liner）使用的考量，下列何者正確？","options":["(A) 須使用氫氧化鈣襯底以減少術後敏感","(B) 使用氫氧化鈣襯底後，再進行酸蝕，黏著性質不受影響","(C) 使用光聚合型氫氧化鈣襯底，可減少操作時間","(D) 不須以氫氧化鈣襯底，以避免減少黏著面積"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-1-42","subject":"ya3","topic":"窩洞設計與分類","meta":"106年第1次第42題","year":106,"session":1,"number":42,"question":"牙根齲蝕，若從鄰接面以溝修形（slot preparations）的方式做汞齊充填，其牙齦壁深度應為何？","options":["(A) 0.3～0.5 mm","(B) 0.75～1.0 mm","(C) 1.25～1.5 mm","(D) 1.75～2.0 mm"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-1-43","subject":"ya3","topic":"窩洞設計與分類","meta":"106年第1次第43題","year":106,"session":1,"number":43,"question":"關於上顎小臼齒第一類型汞齊填補（class I amalgam restoration）窩洞修形，下列何者錯誤？","options":["(A) 咬合面髓壁深度（pulpal depth）約為1.5～2.0mm","(B) 咬合面髓壁深度可隨著頰舌咬頭的傾斜度而有所改變","(C) 若齲齒範圍接近邊緣嵴，近遠心壁必須向咬合面聚攏（converge）","(D) 近遠心邊緣嵴應至少保留1.6mm以上的齒質"],"answer":2,"clinical_level":"重點"},{"id":"ya3-106-1-44","subject":"ya3","topic":"牙體修形程序","meta":"106年第1次第44題","year":106,"session":1,"number":44,"question":"操作球狀（spherical）汞齊合金時，不同於切削型（lathe-cut）汞齊合金，應使用何種填壓器與技術較佳？","options":["(A) 小的填壓器，垂直填壓術","(B) 小的填壓器，側向填壓術","(C) 大的填壓器，垂直填壓術","(D) 大的填壓器，側向填壓術"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-1-45","subject":"ya3","topic":"黏著與美學修復","meta":"106年第1次第45題","year":106,"session":1,"number":45,"question":"有關牙齒漂白藥劑的正確使用方式，下列何者正確？","options":["(A) 3%的過氧化氫（hydrogen peroxide）使用於活齒的診間漂白（in-office bleaching）","(B) 10～15%的carbamide peroxide使用於活齒的持續漂白","(C) 過硼酸鈉（sodium perborate）使用於非活齒的診間漂白","(D) 30%的過氧化氫（hydrogen peroxide）使用於非活齒的持續漂白"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-1-46","subject":"ya3","topic":"黏著與美學修復","meta":"106年第1次第46題","year":106,"session":1,"number":46,"question":"關於顏色的解讀，下列敘述何者錯誤？","options":["(A) 填補較久的複合樹脂，其顏色會變淡（light）","(B) 不同的光源下，物體顏色的解讀隨之不同","(C) 充填複合樹脂時，取一小塊樹脂於窩洞附近聚合，是最好的顏色選擇方法","(D) 觀看藍色的物體，可快速恢復對黃－橘色系的分辨能力"],"answer":0,"clinical_level":"一般"},{"id":"ya3-106-1-47","subject":"ya3","topic":"窩洞設計與分類","meta":"106年第1次第47題","year":106,"session":1,"number":47,"question":"下列何種情況應選擇鑄造金（cast gold）嵌體而非陶瓷嵌體？","options":["(A) 臼齒全部咬頭覆蓋","(B) 磨牙（bruxism）習慣","(C) 臼齒近心和遠心邊緣嵴（marginal ridge）喪失","(D) 裂齒症（cracked tooth syndrome）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-1-48","subject":"ya3","topic":"黏著與美學修復","meta":"106年第1次第48題","year":106,"session":1,"number":48,"question":"關於樹脂嵌體及瓷嵌體的製作及黏著，下列敘述何者錯誤？","options":["(A) 二者都可用樹脂黏合劑（resin cement）黏著","(B) 窩洞修形的邊緣不可有斜面","(C) 瓷嵌體不需用偶合劑（coupling agent）處理","(D) 黏著後在口內做咬合調整"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-1-49","subject":"ya3","topic":"醫學倫理與法規","meta":"106年第1次第49題","year":106,"session":1,"number":49,"question":"決定病人的牙科治療計畫時，所採取的步驟為何？ ①與病人討論並決定最後的治療計畫 ②檢查病人口內狀況，確認問題，以 及評估風險 ③決定建議的治療計畫 ④鑑定治療方案之替代品","options":["(A) ①②③④","(B) ②③④①","(C) ③④①②","(D) ④①②③"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-1-50","subject":"ya3","topic":"牙體修形程序","meta":"106年第1次第50題","year":106,"session":1,"number":50,"question":"手持器械Angle former的四個編碼（12─85─5─8）中，其中第三個數字表示下列何者？","options":["(A) blade width 0.5 mm","(B) cutting edge angle 5 °","(C) blade length 5 mm","(D) blade angle 95 °"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-1-51","subject":"ya3","topic":"複合樹脂與材料","meta":"106年第1次第51題","year":106,"session":1,"number":51,"question":"用光聚合複合樹脂填補前牙齲齒，其步驟順序何者正確？①清除牙菌斑 ②上橡皮障 ③窩洞製備（cavity preparation） ④ 比色","options":["(A) ①②③④","(B) ②③①④","(C) ④①②③","(D) ①④②③"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-1-52","subject":"ya3","topic":"複合樹脂與材料","meta":"106年第1次第52題","year":106,"session":1,"number":52,"question":"關於複合樹脂聚合的敘述，下列何者錯誤？","options":["(A) 聚合反應開始於自由基（free radicals）形成","(B) 聚合反應主要是形成共價鍵（covalent bond）","(C) 空氣抑制層（air-inhibited layer）的形成是因為自由基（free radicals）對氧不反應","(D) 空氣抑制層（air-inhibited layer）的存在可使先後填補的樹脂產生結合"],"answer":2,"clinical_level":"重點"},{"id":"ya3-106-1-53","subject":"ya3","topic":"牙周疾病與診斷","meta":"106年第1次第53題","year":106,"session":1,"number":53,"question":"下列有關初級牙骨質（primary cementum）之敘述，何者正確？","options":["(A) 屬cellular cementum","(B) 含intrinsic fibers","(C) 在牙根apical third可見","(D) 不含Sharpey's fibers"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-1-54","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第1次第54題","year":106,"session":1,"number":54,"question":"下列何者最能代表大部分口腔上皮（oral epithelium）的角質化程度？","options":["(A) 正角質化（orthokeratinization）","(B) 不完全角質化（parakeratinization）","(C) 無角質化（nonkeratinization）","(D) 各種不同角質化程度的綜合表現"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-1-55","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第1次第55題","year":106,"session":1,"number":55,"question":"有關牙周組織中黑色素細胞（melanocytes）之敘述，下列何者錯誤？","options":["(A) 負責製造pigment melanin","(B) 為clear cells中的一種細胞","(C) 含有melanin granules","(D) 與角化細胞（keratinocytes）相同，含有半胞橋小體（hemidesmosomes）或tonofilaments"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-1-56","subject":"ya3","topic":"牙周疾病與診斷","meta":"106年第1次第56題","year":106,"session":1,"number":56,"question":"白比隆-雷佛利症候群（Papillon-Lefévre Syndrome）因嗜中性白血球缺乏下列那種活性而引起嚴重的牙周破壞？","options":["(A) 溶解酵素（lysozyme）","(B) 膠原蛋白酶（collagenase）","(C) 細胞自溶解素C（cathepsin C）","(D) 乳鐵蛋白（lactoferrin）"],"answer":2,"clinical_level":"重點"},{"id":"ya3-106-1-57","subject":"ya3","topic":"牙周疾病與診斷","meta":"106年第1次第57題","year":106,"session":1,"number":57,"question":"下列有關CPITN指數（Community Periodontal Index for Treatment Needs）的敘述，何者錯誤？","options":["(A) 全口牙齒區分成六個象限來檢查","(B) Code 3是指象限內的所有牙齒其牙周囊袋探測深度均＜3 mm","(C) Code 4是指象限內至少有一顆牙齒其牙周囊袋探測深度 ≥ 6 mm","(D) TN值為3則表示須要進行複雜性牙周治療"],"answer":1,"clinical_level":"重點"},{"id":"ya3-106-1-58","subject":"ya3","topic":"牙周疾病與診斷","meta":"106年第1次第58題","year":106,"session":1,"number":58,"question":"牙齦溝內局部細胞免疫（local cellular immune）反應，依圖中4所示，抗原呈現細胞（antigen-presenting cells）進入鄰近淋 巴結後所產生後續的免疫反應，如圖中5、6、7所示，下列何者錯誤？","options":["(A) 反應5：特定B淋巴球或前漿細胞（pre-plasma cells）在鄰近淋巴結內先增生後再進入血液內","(B) 反應5：特定T淋巴球在鄰近淋巴結內先增生後再進入血液內","(C) 反應6：淋巴球回到牙周組織開始進行體液和細胞調控免疫（humoral and cell-mediated immune）的功能","(D) 反應7：細胞調控免疫功能主要由type 2 T helper cells（Th-2）細胞調控"],"answer":3,"image":"ya3-106-1-58.jpeg","clinical_level":"一般"},{"id":"ya3-106-1-59","subject":"ya3","topic":"牙周疾病與診斷","meta":"106年第1次第59題","year":106,"session":1,"number":59,"question":"有關牙周病流行病學研究結果之敘述，下列何者正確？","options":["(A) 一般男生比女生有較佳的牙周健康，是因為男生有較好的口腔衛生行為","(B) 非裔美國人（African Americans）比墨裔美國人（Mexican Americans）有較低的牙周炎流行率","(C) 在種族之間牙周炎的流行率差異，與社會經濟地位無關","(D) 附連喪失會隨年齡增加而增加，但年齡對牙周囊袋深度的影響較輕微"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-1-60","subject":"ya3","topic":"牙周非手術治療","meta":"106年第1次第60題","year":106,"session":1,"number":60,"question":"有關initial periodontal therapy使用雷射進行牙齦下牙結石清除之敘述，下列何者錯誤？","options":["(A) 雷射治療能夠移除菌斑和牙結石，且不會在牙根表面形成塗抹層（smear layer）","(B) 金屬表面的反射，常造成其他組織的傷害如病人眼睛、喉嚨","(C) 使用相對低能量的二氧化碳雷射，只有殺菌作用而無法去除牙結石","(D) 雷射治療合併使用超音波洗牙／牙根整平術，比單獨使用超音波洗牙／牙根整平術有附加效益（adjunctive benefit）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-1-61","subject":"ya3","topic":"牙周手術與再生","meta":"106年第1次第61題","year":106,"session":1,"number":61,"question":"根據Hamp等學者對牙根分叉侵犯分為grade I、II、III，有關牙根分叉的治療計畫之敘述，下列何者錯誤？","options":["(A) Grade I建議以超音波洗牙和牙根整平術或根叉整形術（furcation plasty）等方式治療","(B) Grade II建議以根叉整形術、造隧道手術（tunnel preparation）、切根手術（root resection）、拔牙等方式治療","(C) Grade II在上顎臼齒建議以引導組織再生手術（guided tissue regeneration）治療","(D) Grade III者建議以造隧道手術、切根手術、拔牙等方式治療"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-1-62","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第1次第62題","year":106,"session":1,"number":62,"question":"牙周致病菌Porphyromonas gingivalis具有莢膜（capsule），此構造主要有助於：","options":["(A) 保護細菌避免被吞噬","(B) 毒素合成小囊泡（vesicle）的產生","(C) 細菌之附著","(D) 刺激吞噬細胞產生IL-1"],"answer":0,"clinical_level":"一般"},{"id":"ya3-106-1-63","subject":"ya3","topic":"牙周非手術治療","meta":"106年第1次第63題","year":106,"session":1,"number":63,"question":"依據Waerhaug（1978）的報告，深度大於5 mm的牙周囊袋，接受清創與根面整平術（SRP）的治療後，有多少百分比會殘 留牙結石於牙根表面？","options":["(A) 10","(B) 20","(C) 50","(D) 90"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-1-64","subject":"ya3","topic":"牙周疾病與診斷","meta":"106年第1次第64題","year":106,"session":1,"number":64,"question":"下顎前牙舌側面比較容易有牙齦上結石的產生，主要是受到何種唾液腺管的影響？","options":["(A) Stensen's and Wharton's ducts","(B) Stensen's and Bartholin's ducts","(C) Bartholin's and Wharton's ducts","(D) Stensen's, Wharton's and Bartholin's ducts"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-1-65","subject":"ya3","topic":"牙周手術與再生","meta":"106年第1次第65題","year":106,"session":1,"number":65,"question":"改良式魏德曼翻瓣術（modified Widman flap）的順序為何？①牙齦溝切開，由囊袋底部向牙骨嵴切下 ②內斜切（internal bevel incision），由牙齦邊緣0.5～1 mm向牙骨嵴切下 ③以黏膜剝離器翻開牙齦 ④以牙刮（curette）將牙間骨頭上的軟組 織刮除","options":["(A) ①②④③","(B) ②③①④","(C) ①④②③","(D) ②①④③"],"answer":1,"clinical_level":"重點"},{"id":"ya3-106-1-66","subject":"ya3","topic":"牙周手術與再生","meta":"106年第1次第66題","year":106,"session":1,"number":66,"question":"有一位病患在maxillary central與lateral incisors之間有non-3-wall intrabony defect，此兩顆牙齒間的interdental space width＞ 2 mm，而該患者堅持只進行一次手術，如果要進行GTR的治療，以Cortelini & Tonitti（2005）所提出的GTR evidence-based operative decision making流程，下列何種術式與醫材組合最適當？","options":["(A) Modified papilla preservation technique + bone graft + bioresorbable membrane","(B) Modified papilla preservation technique + bone graft + non-bioresorbable membrane","(C) Modified papilla preservation technique + EMD（enamel matrix protein, Emdogain）","(D) Simplified papilla preservation technique + bone graft + bioresorbable membrane"],"answer":0,"clinical_level":"一般"},{"id":"ya3-106-1-67","subject":"ya3","topic":"牙周疾病與診斷","meta":"106年第1次第67題","year":106,"session":1,"number":67,"question":"Nordland & Tarnow 1998研究指出對齒間乳突高度做分類，當齒間乳突的頂端介於齒間接觸點與鄰接牙CEJ之間時，是屬那個 分類？","options":["(A) Class I","(B) Class II","(C) Class III","(D) Class IV"],"answer":0,"clinical_level":"一般"},{"id":"ya3-106-1-68","subject":"ya3","topic":"牙周手術與再生","meta":"106年第1次第68題","year":106,"session":1,"number":68,"question":"有關牙周手術的基本原則之敘述，下列何者錯誤？","options":["(A) 抽菸患者，術後至少禁菸3～4週","(B) 須填寫手術同意書","(C) 後天性免疫缺乏症候群（AIDS）之患者可使用Cavitron","(D) 術前給予diazepam可減少患者之焦慮"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-1-69","subject":"ya3","topic":"牙周手術與再生","meta":"106年第1次第69題","year":106,"session":1,"number":69,"question":"在牙齦切除術時所使用的器械，下列何者錯誤？","options":["(A) Kirkland knife用來切牙弓最後一顆牙的遠心側","(B) Orban periodontal knife用來切頰側及舌側面","(C) Bard-Parker Blades No. 11和12當做輔助器械","(D) Scissors可以用來當做輔助器械"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-1-70","subject":"ya3","topic":"牙周手術與再生","meta":"106年第1次第70題","year":106,"session":1,"number":70,"question":"牙齦切除手術後幾小時，手術區邊緣的上皮細胞活性會達到最高峰？","options":["(A) 3～6小時","(B) 6～12小時","(C) 12～24小時","(D) 24～36小時"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-1-71","subject":"ya3","topic":"牙周手術與再生","meta":"106年第1次第71題","year":106,"session":1,"number":71,"question":"當患者有gummy smile，牙齦為厚的型態（thick biotype），且齒骨嵴有骨平台（bony ledge）時，下列何者是增加牙冠長度 較理想的手術方法？","options":["(A) 牙齦切除術（gingivectomy）","(B) 根向移位翻瓣術（apically displaced flap）和修骨手術","(C) 改良式魏德曼翻瓣術（modified Widman flap）","(D) 乳頭保存翻瓣術（papilla preservation flap）"],"answer":1,"clinical_level":"重點"},{"id":"ya3-106-1-72","subject":"ya3","topic":"牙周手術與再生","meta":"106年第1次第72題","year":106,"session":1,"number":72,"question":"關於牙冠增長術（crown lengthening procedure）之應用，下列敘述何者錯誤？","options":["(A) 可處理齒頸部1/3處之牙齦下齲齒","(B) 可應用強逼萌出（forced eruption）方式","(C) 美觀區域之單顆牙齒可用此手術方式來解決","(D) 需要骨切除時不可以僅限於要處理的那一顆牙齒"],"answer":2,"clinical_level":"重點"},{"id":"ya3-106-1-73","subject":"ya3","topic":"牙周非手術治療","meta":"106年第1次第73題","year":106,"session":1,"number":73,"question":"為了阻止進一步的附連喪失（loss of attachment），下列有關嚴重牙周炎（advanced periodontitis）病人的牙周維護性治療 （supportive periodontal therapy, SPT）的敘述，何者正確？","options":["(A) 定期回診比短時間內密集回診重要","(B) 短時間內密集回診比定期回診重要","(C) 3個月定期回診","(D) 6個月定期回診"],"answer":0,"clinical_level":"重點"},{"id":"ya3-106-1-74","subject":"ya3","topic":"牙周疾病與診斷","meta":"106年第1次第74題","year":106,"session":1,"number":74,"question":"牙周病的復發與下列何者的關聯最大？","options":["(A) 年齡","(B) 性別","(C) 牙菌斑控制","(D) 糖尿病"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-1-75","subject":"ya3","topic":"牙周疾病與診斷","meta":"106年第1次第75題","year":106,"session":1,"number":75,"question":"目前研究顯示，懷孕婦女口腔衛生不佳或有嚴重牙周炎，會出現之不良結果中不包括：","options":["(A) 胎兒窘迫（fetal distress）","(B) 先兆子癇 （pre-eclampsia）","(C) 化膿性肉芽腫（pyogenic granuloma）","(D) 早產兒（pre-term birth）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-106-1-76","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第1次第76題","year":106,"session":1,"number":76,"question":"下列何者是血糖控制不佳的糖尿病患者，造成牙周組織破壞加重的最主要物質？","options":["(A) 胰島素（insulin）","(B) 醣化作用終產物（advanced glycation end-products）","(C) 類胰島素之生長素（insulin-like growth factor）","(D) 皮質類固醇（corticosteroid）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-1-77","subject":"ya3","topic":"牙周疾病與診斷","meta":"106年第1次第77題","year":106,"session":1,"number":77,"question":"關於牙周炎與系統性疾病（systemic disease）間之關係，下列敘述何者錯誤？","options":["(A) 牙周炎與體重不足之早產兒有相當的關係","(B) Offenbacher 1994田鼠的實驗顯示羊膜內之PGE2及TNF-α減少與體重不足之幼田鼠無關","(C) 牙周炎是動脈粥樣硬化（atherosclerosis）與冠狀動脈疾病的危險因子","(D) 幽門螺旋桿菌（H. pylori）可能會引起動脈硬化"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-1-78","subject":"ya3","topic":"植牙學","meta":"106年第1次第78題","year":106,"session":1,"number":78,"question":"植體補綴完成之病人，除了有臨床問題發生之外，應每隔幾個月接受放射線追蹤檢查？","options":["(A) 6","(B) 12","(C) 24","(D) 36"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-1-79","subject":"ya3","topic":"植牙學","meta":"106年第1次第79題","year":106,"session":1,"number":79,"question":"侵犯型牙周炎病患，局部牙齒喪失換成植牙，在定期維護下，其植體周圍軟組織內的菌種主要為何？","options":["(A) Cocci","(B) Fusiform","(C) Motile rod","(D) Spirochete"],"answer":0,"clinical_level":"重點"},{"id":"ya3-106-1-80","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第1次第80題","year":106,"session":1,"number":80,"question":"下列何種雙磷酸鹽抑制噬骨細胞活性的強度最大？","options":["(A) Alendronate","(B) Etidronate","(C) Tiludronate","(D) Zoledronate"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-2-1","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第2次第1題","year":106,"session":2,"number":1,"question":"當原始的造牙本質細胞（odontoblasts）死亡，而由新分化的類造牙本質細胞（differentiated odontoblast-like cells）所分泌形成的牙本質，稱為：","options":["(A) 球狀牙本質（globular dentin）","(B) 修復性牙本質（reparative dentin）","(C) 反應性牙本質（reactionary dentin）","(D) 繼生牙本質（secondary dentin）"],"answer":1,"clinical_level":"重點"},{"id":"ya3-106-2-2","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第2次第2題","year":106,"session":2,"number":2,"question":"有關牙髓鈣化（pulpal calcification）之敘述，下列何者正確？","options":["(A) 鈣化組織主要成分為carbonated hydroxyapatite","(B) 常導致後續的牙髓壞死，是牙髓病變的先兆","(C) 會導致牙髓血流量的改變，造成不明原因的牙髓疼痛","(D) 牙髓仍有活性，但常造成根尖的緻密性骨炎（condensing osteitis）"],"answer":0,"clinical_level":"重點"},{"id":"ya3-106-2-3","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第2次第3題","year":106,"session":2,"number":3,"question":"造牙本質細胞（odontoblasts）之功能為：","options":["(A) 分泌鹼性磷酸酶（alkaline phosphatase）","(B) 負責牙髓中膠原蛋白之周轉（turn over）","(C) 分泌typeⅢ膠原蛋白","(D) 分化（differentiation）之能力"],"answer":0,"clinical_level":"重點"},{"id":"ya3-106-2-4","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第2次第4題","year":106,"session":2,"number":4,"question":"長期慢性牙髓炎若發生急性發作時，常表現出鈍而難以忍耐的脹痛，是那種神經纖維被激發？","options":["(A) A-alpha纖維","(B) A-delta纖維","(C) B纖維","(D) C纖維"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-2-5","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第2次第5題","year":106,"session":2,"number":5,"question":"齲齒是細菌侵入牙髓腔最常發生的途徑，主要是細菌在沒有牙釉質或牙骨質阻擋下能順利通過牙本質小管，一 般牙本質小管的管徑約為：","options":["(A) 0.1－0.4 µm","(B) 1.0－4.0 µm","(C) 10－40 µm","(D) 100－140 µm"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-2-6","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第2次第6題","year":106,"session":2,"number":6,"question":"有關各種牙髓活性測試對於檢測正常牙髓組織的準確性高低比較，下列何者正確？","options":["(A) 電髓測試 ≈ 冷測試＞熱測試","(B) 冷測試 ≈ 熱測試＞電髓測試","(C) 熱測試＞冷測試＞電髓測試","(D) 電髓測試＞冷測試＞熱測試"],"answer":0,"clinical_level":"一般"},{"id":"ya3-106-2-7","subject":"ya3","topic":"醫學倫理與法規","meta":"106年第2次第7題","year":106,"session":2,"number":7,"question":"疾病診斷是擬定治療計畫的基礎，在評估疾病及鑑別診斷時必須參考一些常用檢診資料，下列何者較不重要？","options":["(A) 適切的評估與目前相關疾病的病史","(B) 正確的臨床及放射線檢查","(C) 詢問病患的轉診醫師及日期","(D) 完整的診斷測試檢查及牙髓活性測試，牙周囊袋記錄等"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-2-8","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第2次第8題","year":106,"session":2,"number":8,"question":"源於牙髓感染的根尖牙周炎（apical periodontitis），其組織病理敘述何者正確？","options":["(A) 急性根尖牙周炎（acute apical periodontitis）其病理組織以淋巴球（lymphocyte）、漿細胞（plasma cell） 為主","(B) 慢性根尖牙周炎（chronic apical periodontitis）其病理組織以中性球（neutrophil）、淋巴球（lymphocyte） 為主","(C) 根尖真性囊腫（apical true cyst）是牙根尖發炎的囊腫，有完整的病理性空腔，外圍完全以上皮組織 （epithelial tissue）包覆，與牙根沒有相連","(D) 根尖囊袋性囊腫（apical pocket cyst）是牙根尖發炎的囊腫，有囊袋上皮組織的病理性空腔，與牙根沒有相 連"],"answer":2,"clinical_level":"重點"},{"id":"ya3-106-2-9","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第2次第9題","year":106,"session":2,"number":9,"question":"有關窩洞測試（test cavity）的敘述，下列何者正確？","options":["(A) 在所有牙髓活性檢查中最常被採用","(B) 若病人有反應表示正常的齒髓組織","(C) 屬侵入性檢查","(D) 必要時使用麻醉"],"answer":2,"clinical_level":"重點"},{"id":"ya3-106-2-10","subject":"ya3","topic":"根管治療程序","meta":"106年第2次第10題","year":106,"session":2,"number":10,"question":"下列何者為判定單一牙根中是否含有兩個根管的較佳方式？","options":["(A) 使用根管用顯微鏡觀察","(B) 使用根管用探針探測","(C) 改變（shift）X光照射角度","(D) 用電子根尖定位器（electronic apex locator）偵測"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-2-11","subject":"ya3","topic":"牙齒外傷處理","meta":"106年第2次第11題","year":106,"session":2,"number":11,"question":"如圖，患者左上正中門齒曾因車禍撞擊而脫落，經再植復位固定後，原本外觀已無異常，但卻慢慢發現左上 正中門齒似乎變短，則最有可能的診斷為：","options":["(A) 牙髓發炎合併內吸收（internal root resorption）","(B) 牙髓發炎合併外吸收（external root resorption）","(C) 牙髓壞死合併慢性根尖牙周炎（chronic apical periodontitis）","(D) 牙髓壞死合併取代性吸收（replacement resorption）"],"answer":3,"image":"ya3-106-2-11.jpeg","clinical_level":"一般"},{"id":"ya3-106-2-12","subject":"ya3","topic":"牙齒外傷處理","meta":"106年第2次第12題","year":106,"session":2,"number":12,"question":"有一位八歲小朋友，上顎正中門齒因受傷導致牙根斷裂，下列敘述何者正確？","options":["(A) 從平行照射的X光片即可看到牙根的斷裂線","(B) 一旦發現EPT沒有反應，必須馬上施行根管治療","(C) 牙齒復位後，需要固定1～2星期","(D) 若是根尖1／3處斷裂，通常不需要根管治療，但是要長期觀察"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-2-13","subject":"ya3","topic":"牙齒外傷處理","meta":"106年第2次第13題","year":106,"session":2,"number":13,"question":"下列何種牙齒外傷，牙髓壞死的機會最高？","options":["(A) 根尖孔閉合且牙根中段水平斷裂之牙齒","(B) 根尖孔閉合之內縮齒","(C) 根尖孔閉合之側向脫位齒","(D) 根尖孔未閉合之脫落齒"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-2-14","subject":"ya3","topic":"牙齒外傷處理","meta":"106年第2次第14題","year":106,"session":2,"number":14,"question":"脫槽（avulsion）牙齒復位後，經判斷牙髓組織無法存活時，何時進行根管治療最適當？","options":["(A) 立刻","(B) 隔天","(C) 7～10天","(D) 3～4週後"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-2-15","subject":"ya3","topic":"根管器械","meta":"106年第2次第15題","year":106,"session":2,"number":15,"question":"下列何者不是根管銼針（file）的國際標準長度？","options":["(A) 31 mm","(B) 25 mm","(C) 23 mm","(D) 21 mm"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-2-16","subject":"ya3","topic":"根管治療程序","meta":"106年第2次第16題","year":106,"session":2,"number":16,"question":"下列藥劑，何者去除塗抹層（smear layer）的效果最差？","options":["(A) MTAD","(B) EDTA","(C) Chlorhexidine","(D) RC-Prep"],"answer":2,"clinical_level":"重點"},{"id":"ya3-106-2-17","subject":"ya3","topic":"窩洞設計與分類","meta":"106年第2次第17題","year":106,"session":2,"number":17,"question":"有關根管治療後牙齒根柱（post）的使用，下列何者敘述錯誤？","options":["(A) 平行根柱（parallel post）比錐狀根柱（tapered post）具有較高的固位力（retention）","(B) 錐狀根柱會產生楔形效應（wedging effect）","(C) 平行根柱的應力最大處在其尖端（apex）","(D) 錐狀根柱比平行根柱更能抵抗張力（tensile force）和剪力（shear force）"],"answer":3,"clinical_level":"重點"},{"id":"ya3-106-2-18","subject":"ya3","topic":"根管治療程序","meta":"106年第2次第18題","year":106,"session":2,"number":18,"question":"根管治療中臨時復形（temporary restoration）最重要的考量為何？","options":["(A) 用來覆蓋住根管的小棉球","(B) 至少有足夠厚度填充材以達到封閉效果","(C) 必須符合美觀（esthetics）的要求","(D) 抵抗牙齒斷裂"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-2-19","subject":"ya3","topic":"根管治療程序","meta":"106年第2次第19題","year":106,"session":2,"number":19,"question":"有關前牙髓腔開擴的步驟，下列敘述何者錯誤？","options":["(A) 首先使用兩側平行（parallel side）的鑽石不銹鋼磨針，以垂直牙釉質表面90°方向進行髓腔開口","(B) 磨針感覺進入牙髓腔後，修磨方向改變為平行牙齒長軸（long axis），而形成直線開口（straight line access）的形狀","(C) 使用尖端有切削（cutting tip）能力的磨針修飾髓腔開口（refine access），形成合適固持形狀（retention form）","(D) 清除齒質突出（overhang）或髓角處（pulp horn）的牙髓組織污染"],"answer":2,"clinical_level":"重點"},{"id":"ya3-106-2-20","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第2次第20題","year":106,"session":2,"number":20,"question":"欲分辨出上顎第一大臼齒四個根管，較理想的X光照射角度為：","options":["(A) 平行法照射","(B) 近心向二十度照射（mesial projection）錐筒（cone）指向該牙遠心處","(C) 遠心向二十度照射（distal projection）錐筒（cone）指向該牙近心處","(D) 將錐筒（cone）往上偏移二十度照射"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-2-21","subject":"ya3","topic":"根管治療程序","meta":"106年第2次第21題","year":106,"session":2,"number":21,"question":"根尖手術常用的逆充填材料不包含下列何者？","options":["(A) Zinc oxide-eugenol cements","(B) Intermediate restorative material（IRM）","(C) Bio-Oss","(D) Mineral trioxide aggregate（MTA）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-2-22","subject":"ya3","topic":"牙齒外傷處理","meta":"106年第2次第22題","year":106,"session":2,"number":22,"question":"患者因外傷造成多顆牙齒不規則排列，下列何者為合理推論？","options":["(A) 脫臼（luxation）","(B) 半脫臼（subluxation）","(C) 齒槽骨斷裂（alveolar fracture）","(D) 牙根斷裂（root fracture）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-2-23","subject":"ya3","topic":"窩洞設計與分類","meta":"106年第2次第23題","year":106,"session":2,"number":23,"question":"根管治療過的牙齒之所以會造成牙齒斷裂，最主要是因為：","options":["(A) 拔髓後，齒質脫水，牙齒變脆","(B) 牙齒本身已喪失過多齒質","(C) 根管充填不夠緻密","(D) 牙冠製作不良，產生滲漏"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-2-24","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第2次第24題","year":106,"session":2,"number":24,"question":"壞死的牙髓組織與微生物的毒素等若經由根管出口（portals of exit）擴散後，較不會造成下列那一項硬組織的 破壞？","options":["(A) 牙釉質（enamel）","(B) 齒槽骨（bone）","(C) 牙骨質（cementum）","(D) 牙本質（dentin）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-106-2-25","subject":"ya3","topic":"根管治療程序","meta":"106年第2次第25題","year":106,"session":2,"number":25,"question":"8歲的蔡小妹妹因左下第一大臼齒深度齲齒而接受牙髓治療。圖一是治療完成當次所拍攝的X光片，圖二則是 經過兩年追蹤觀察後的X光片。蔡小妹妹接受的牙髓治療術式為何？ 圖一 圖二","options":["(A) 根尖成形術（apexification）","(B) 根尖生成術（apexogenesis）","(C) 牙髓切除術（pulpectomy）","(D) 間接覆髓術（indirect pulp capping）"],"answer":1,"image":"ya3-106-2-25.jpeg","clinical_level":"一般"},{"id":"ya3-106-2-26","subject":"ya3","topic":"醫學倫理與法規","meta":"106年第2次第26題","year":106,"session":2,"number":26,"question":"45歲女性左上正中門齒與側門齒牙冠斷裂到診所求診。這兩顆牙齒在經過數次的根管治療後，病患被告知左 上正中門齒有嚴重根管鈣化現象，建議轉診到牙髓病專科醫師門診接受進一步的治療。下圖為牙髓病專科醫 師為患齒進行X光片檢查的影像。請問對於左上正中門齒髓腔開擴偏移，並可能造成牙根穿孔的問題，應如何 向病人與轉診醫師說明？","options":["(A) 為避免引起醫療糾紛，按照轉診醫師的說法向病人解釋治療計畫","(B) 按照轉診醫師的根管鈣化的說法向病人解釋治療計畫，但私下告知轉診醫師患齒的其他問題","(C) 為釐清醫療責任，應向病患說明患齒發生髓腔開擴偏移與可能牙根穿孔的問題，但不需特別告知轉診醫師","(D) 需同時向病患與轉診醫師說明患齒發生髓腔開擴偏移與可能牙根穿孔問題"],"answer":3,"image":"ya3-106-2-26.jpeg","clinical_level":"一般"},{"id":"ya3-106-2-27","subject":"ya3","topic":"黏著與美學修復","meta":"106年第2次第27題","year":106,"session":2,"number":27,"question":"下列何者不是樹脂（resin）與牙齒鍵結的可能機制？","options":["(A) 機械性黏著（mechanical adhesion）","(B) 吸附性黏著（adsorption adhesion）","(C) 擴散性黏著（diffusion adhesion）","(D) 靜電性黏著（electrostatic adhesion）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-2-28","subject":"ya3","topic":"複合樹脂與材料","meta":"106年第2次第28題","year":106,"session":2,"number":28,"question":"下列關於玻璃離子體黏合劑（glass ionomer cement）的敘述，何者正確？","options":["(A) 氟離子的釋出量，初期並不多，一週後才釋出較明顯","(B) 反應時由鋁離子先產生交鏈（cross linkage），24小時後由鈣離子取代","(C) 反應過程中，玻璃離子體內部與牙齒間，均產生化學鍵結","(D) 加入Ag-Sn強化，強度與汞齊相當，但較不美觀"],"answer":2,"clinical_level":"重點"},{"id":"ya3-106-2-29","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第2次第29題","year":106,"session":2,"number":29,"question":"製作金屬嵌體（inlay）印模時，下列何種患者可以使用含血管收縮劑之排齦線（retraction cord）？","options":["(A) 癲癇（epilepsy）患者","(B) 心律不整（cardiac arrhythmias）患者","(C) 嚴重心血管疾病（severe cardiovascular disease）患者","(D) 服用β-blockers藥物患者"],"answer":0,"clinical_level":"一般"},{"id":"ya3-106-2-30","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第2次第30題","year":106,"session":2,"number":30,"question":"在成熟牙本質（mature dentin）中，牙本質小管（dentinal tubule）內的細胞突通常達到之位置為下列何者？","options":["(A) 牙本質牙釉質交界（dentinoenamel junction）","(B) 牙本質外1/3（outer third of dentin）","(C) 牙本質中1/3（middle third of dentin）","(D) 牙本質內1/3（inner third of dentin）"],"answer":3,"clinical_level":"重點"},{"id":"ya3-106-2-31","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第2次第31題","year":106,"session":2,"number":31,"question":"有關被覆牙本質（mantle dentin）之敘述，下列何者正確？","options":["(A) 礦化程度較低，其膠原纖維走向平行牙本質牙釉質交界（dentinoenamel junction）","(B) 礦化程度較低，其膠原纖維走向垂直牙本質牙釉質交界（dentinoenamel junction）","(C) 礦化程度較高，其膠原纖維走向平行牙本質牙釉質交界（dentinoenamel junction）","(D) 礦化程度較高，其膠原纖維走向垂直牙本質牙釉質交界（dentinoenamel junction）"],"answer":1,"clinical_level":"重點"},{"id":"ya3-106-2-32","subject":"ya3","topic":"牙髓診斷與病理","meta":"106年第2次第32題","year":106,"session":2,"number":32,"question":"下列何種因素不會加速牙釉質去礦化（demineralization）？","options":["(A) 鏈球菌（streptococcus）附著","(B) 果糖進食次數","(C) 中性的口腔環境","(D) 唾液分泌量不足"],"answer":2,"clinical_level":"重點"},{"id":"ya3-106-2-33","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第2次第33題","year":106,"session":2,"number":33,"question":"攝取蔗糖容易造成齲齒，此現象的機制為何？①含有蔗糖的食物會造成菌落容易長成，增加生物膜（biofilm） 的致齲性 ②牙菌斑的細菌會快速代謝蔗糖，造成酸鹼值下降 ③攝取蔗糖會造成生長中牙胚的牙釉質脫鈣 ④唾液分泌會因為大量攝取蔗糖而減少","options":["(A) ①②","(B) ②③","(C) ③④","(D) ①③"],"answer":0,"clinical_level":"一般"},{"id":"ya3-106-2-34","subject":"ya3","topic":"黏著與美學修復","meta":"106年第2次第34題","year":106,"session":2,"number":34,"question":"使用全酸蝕式（total etch）牙本質黏著劑時，為提昇黏著劑與牙本質之鍵結，下列何種處置方式最佳？","options":["(A) 酸蝕，水洗，吹至全乾","(B) 酸蝕，水洗，吹至微濕","(C) 酸蝕後擦拭，吹至微濕","(D) 酸蝕，水洗，保持全濕"],"answer":1,"clinical_level":"重點"},{"id":"ya3-106-2-35","subject":"ya3","topic":"黏著與美學修復","meta":"106年第2次第35題","year":106,"session":2,"number":35,"question":"下圖為自酸蝕性（self - etching）牙本質黏著劑處理後，樹脂和牙本質的鍵結面（interface）在穿隧式電子顯 微鏡下（transmission electron micrograph）的影像，下列敘述何者正確？（A = adhesive, D = dentin, H = hybrid layer, T = resin tag）①H層可能含有樹脂成分 ②A層內細黑點可能是膠原纖維（collagen fiber）的橫 斷面 ③T結構的深度為影響黏著強度的主要因素 ④T結構可能含有塗抹層（smear layer）的成分","options":["(A) ①④","(B) ①③","(C) ②③","(D) ②④"],"answer":0,"image":"ya3-106-2-35.jpeg","clinical_level":"一般"},{"id":"ya3-106-2-36","subject":"ya3","topic":"黏著與美學修復","meta":"106年第2次第36題","year":106,"session":2,"number":36,"question":"牙本質與樹脂黏著強度與下列何者成正比？","options":["(A) 牙本質小管的管徑（diameter of dentin tubule）","(B) 管周牙本質的厚度（thickness of peritubular dentin）","(C) 管間牙本質的面積（area of intertubular dentin）","(D) 牙本質小管的通透性（permeability of dentin tubule）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-2-37","subject":"ya3","topic":"醫學倫理與法規","meta":"106年第2次第37題","year":106,"session":2,"number":37,"question":"下列有關牙科治療計畫的階段排序，何者正確？①緊急階段（urgent phase） ②再評估階段（re-evaluation phase） ③明確／改正治療階段（definitive / corrective phase） ④控制階段（control phase） ⑤重新照 顧階段（recare and re-assessment phase）","options":["(A) ①④②③⑤","(B) ①②⑤③④","(C) ②①④③⑤","(D) ①②③④⑤"],"answer":0,"clinical_level":"一般"},{"id":"ya3-106-2-38","subject":"ya3","topic":"窩洞設計與分類","meta":"106年第2次第38題","year":106,"session":2,"number":38,"question":"汞齊填補物產生邊緣縫隙（marginal ditching），下列敘述何者正確？","options":["(A) 使用高銅汞齊填補所致","(B) 汞齊硬化後膨脹所致","(C) 可能由不當的修形（tooth preparation）所致","(D) 填補後沒有拋光（polish）所致"],"answer":[1,2],"clinical_level":"一般","explanation_pending":false},{"id":"ya3-106-2-39","subject":"ya3","topic":"窩洞設計與分類","meta":"106年第2次第39題","year":106,"session":2,"number":39,"question":"某先生有乾口症且口腔衛生不佳，全口28顆牙齒中有24顆發現有齲齒或是填補過有再發性齲齒。完成該病患 全口治療及口腔衛生教育後，應建議多久定期回診？","options":["(A) 4～6週","(B) 3～4個月","(C) 6～7個月","(D) 9～12個月"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-2-40","subject":"ya3","topic":"牙體修形程序","meta":"106年第2次第40題","year":106,"session":2,"number":40,"question":"使用旋轉器械切削齒質時，保護牙髓免於傷害的敘述，下列何者錯誤？","options":["(A) 銳利鑽針比鈍的鑽針易造成牙髓升溫","(B) 空氣－水（air-water spray）冷卻可減少傷害","(C) 無水冷卻時，鑽石鑽針比鎢鋼鑽針易造成傷害","(D) 輕且間歇性的切削方式（light and intermittent application）不易造成牙髓升溫"],"answer":0,"clinical_level":"一般"},{"id":"ya3-106-2-41","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第2次第41題","year":106,"session":2,"number":41,"question":"在Universal System中，編號13之牙齒，在FDI System中，應如何編號？","options":["(A) 13","(B) 6","(C) 25","(D) 27"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-2-42","subject":"ya3","topic":"牙體修形程序","meta":"106年第2次第42題","year":106,"session":2,"number":42,"question":"有關橡皮障（rubber dam）在齒齦緣必須反轉（inversion）向牙齦溝的目的，下列何者錯誤？","options":["(A) 增加密封性","(B) 可以向下壓制牙齦","(C) 讓橡皮障不容易撕裂","(D) 防止口水或牙齦液滲出"],"answer":2,"clinical_level":"重點"},{"id":"ya3-106-2-43","subject":"ya3","topic":"複合樹脂與材料","meta":"106年第2次第43題","year":106,"session":2,"number":43,"question":"有關發光二極體（light-emitting diode，LED）和鹵素光（quartz-tungsten-halogen，QTH）兩種複合樹脂光 聚機的比較，下列敘述何者錯誤？","options":["(A) 通常QTH光聚機內置濾光片（filter），LED光聚機無濾光片","(B) 相同光強度（intensity）之LED光聚機產生熱量較少","(C) LED光源波長光譜較QTH寬","(D) LED光源壽命較QTH長"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-2-44","subject":"ya3","topic":"黏著與美學修復","meta":"106年第2次第44題","year":106,"session":2,"number":44,"question":"前牙複合樹脂填補時，下列何者不會影響樹脂顏色選擇？","options":["(A) 光線（lighting）是否適當","(B) 室內溫度（room temperature）","(C) 是否使用橡皮障（rubber dam）","(D) 眼睛疲乏（eye fatigue）"],"answer":1,"clinical_level":"重點"},{"id":"ya3-106-2-45","subject":"ya3","topic":"複合樹脂與材料","meta":"106年第2次第45題","year":106,"session":2,"number":45,"question":"下列何者不是造成複合樹脂填補術後敏感的可能原因？","options":["(A) 樹脂聚合收縮","(B) 造成牙釉質微碎裂","(C) 咬合力造成樹脂變形","(D) 樹脂之吸水率高"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-2-46","subject":"ya3","topic":"窩洞設計與分類","meta":"106年第2次第46題","year":106,"session":2,"number":46,"question":"汞齊復形與金合金嵌體窩洞的鄰接面固位溝（retentive groove）主要差異為：","options":["(A) 位置","(B) 近遠心（mesio-distal）走向","(C) 製備的鑽針尺寸","(D) 咬合牙齦（occluso-gingival）軸向"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-2-47","subject":"ya3","topic":"窩洞設計與分類","meta":"106年第2次第47題","year":106,"session":2,"number":47,"question":"第二類型汞齊（amalgam）填補之窩洞修形中，固位溝（retention groove）的設計應為：","options":["(A) 0.5mm深，1.0mm寬","(B) 1.0mm深，0.5mm寬","(C) 0.5mm深，0.5mm寬","(D) 0.1mm深，0.1mm寬"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-2-48","subject":"ya3","topic":"黏著與美學修復","meta":"106年第2次第48題","year":106,"session":2,"number":48,"question":"附圖為何種美白技術，其最常用的美白劑成分與濃度為何？","options":["(A) home-applied technique；10～15% carbamide peroxide","(B) home-applied technique；30～35% hydrogen peroxide","(C) walking bleaching technique；10～15% carbamide peroxide","(D) walking bleaching technique；30～35% hydrogen peroxide"],"answer":0,"image":"ya3-106-2-48.jpeg","clinical_level":"一般"},{"id":"ya3-106-2-49","subject":"ya3","topic":"黏著與美學修復","meta":"106年第2次第49題","year":106,"session":2,"number":49,"question":"有關牙齒復形時，形狀對視覺效果的影響，下列何者錯誤？","options":["(A) 要造成牙齒較短效果，可強調釉質橫（perikymata）","(B) 要造成牙齒較短效果，可強調發育溝（developmental depression）","(C) 要造成牙齒較窄效果，可將近心線角與遠心線角向發育溝靠近","(D) 要造成牙齒較長效果，可將外廓高隆線（height of contour）向牙齦移動"],"answer":1,"clinical_level":"重點"},{"id":"ya3-106-2-50","subject":"ya3","topic":"黏著與美學修復","meta":"106年第2次第50題","year":106,"session":2,"number":50,"question":"下列有關內在性變色（intrinsic discolorations）的敘述，何者錯誤？","options":["(A) 牙釉質缺陷可能會造成內在性變色","(B) 皆需以根管內漂白法（internal bleaching）來處理","(C) 孩童時期生病發高燒也可能會導致內在性變色","(D) 輕微變色可用漂白，輕微磨除（microabrasion）或深度磨除（macroabrasion）改善"],"answer":1,"clinical_level":"重點"},{"id":"ya3-106-2-51","subject":"ya3","topic":"牙體修形程序","meta":"106年第2次第51題","year":106,"session":2,"number":51,"question":"下列何種印模方法不適合用於陶瓷嵌體？","options":["(A) 加成矽膠印模材（addition silicone impression materials）","(B) 縮合矽膠印模材（condensation silicone impression materials）","(C) 光學印模（optical impression）","(D) 藻膠（alginate）印模材"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-2-52","subject":"ya3","topic":"窩洞設計與分類","meta":"106年第2次第52題","year":106,"session":2,"number":52,"question":"下列敘述何者不是金屬嵌體（inlay）修形中牙齦斜面（gingival bevel）設計的目的？","options":["(A) 移除牙齦邊緣薄弱的牙釉質","(B) 可供牙齦邊緣金屬研光（burnish）","(C) 增加嵌體強度，承受咬合力","(D) 增加嵌體邊緣貼合度"],"answer":2,"clinical_level":"重點"},{"id":"ya3-106-2-53","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第2次第53題","year":106,"session":2,"number":53,"question":"對齒槽骨而言，織網骨（woven bone）是指：","options":["(A) Socket wall","(B) Buccal plate","(C) Lingual plate","(D) Between buccal plate and lingual plate"],"answer":0,"clinical_level":"一般"},{"id":"ya3-106-2-54","subject":"ya3","topic":"牙周疾病與診斷","meta":"106年第2次第54題","year":106,"session":2,"number":54,"question":"下列關於健康角化牙齦的敘述何者正確？","options":["(A) 上顎頰側牙齦最寬的是門齒區","(B) 下顎舌側牙齦最窄的是門齒區","(C) 牙齦寬度隨著年齡增加而增加","(D) 牙齦可被碘溶液染色"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-2-55","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第2次第55題","year":106,"session":2,"number":55,"question":"下列關於牙齦上皮（gingival epithelium）結構或功能的敘述，何項是錯誤的？","options":["(A) 上皮組織細胞之間以hemidesmosome相連結","(B) 上皮組織的基底層（basal layer）是產生新上皮組織細胞的來源","(C) 上皮組織內的basal lamina可預防結締組織（connective tissue）內的大分子往外滲出","(D) Langerhans cell在上皮組織內扮演抗原呈現（antigen presentation）的角色"],"answer":0,"clinical_level":"重點"},{"id":"ya3-106-2-56","subject":"ya3","topic":"牙周疾病與診斷","meta":"106年第2次第56題","year":106,"session":2,"number":56,"question":"下列何者不是廣泛性侵犯性牙周炎（generalized aggressive periodontitis）之特徵？","options":["(A) 有家族群聚（familial aggregation）","(B) 快速牙周附連喪失","(C) 最少有2顆鄰接面附連喪失的牙齒不是門齒或第一大臼齒","(D) 對致病菌血清抗體反應差"],"answer":2,"clinical_level":"重點"},{"id":"ya3-106-2-57","subject":"ya3","topic":"牙周疾病與診斷","meta":"106年第2次第57題","year":106,"session":2,"number":57,"question":"下表為某一受檢者之社區牙周治療需求指數記錄（Community Periodontal Index for Treatment Needs， CPITN），代表該病患目前之治療需求為何？","options":["(A) 毋須牙周治療，缺牙部位可以直接重建","(B) 僅需接受口腔衛生輔導","(C) 僅需洗牙及牙根整平處置","(D) 某些部位可能需手術處置，甚至進一步牙周專業處理"],"answer":3,"image":"ya3-106-2-57.jpeg","clinical_level":"重點"},{"id":"ya3-106-2-58","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第2次第58題","year":106,"session":2,"number":58,"question":"在發炎牙齦組織中，下列何種細胞扮演呈現抗原（antigen presentation）和組織傷口癒合的重要角色？","options":["(A) T細胞","(B) NK細胞","(C) 巨噬細胞","(D) 嗜中性細胞"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-2-59","subject":"ya3","topic":"牙周疾病與診斷","meta":"106年第2次第59題","year":106,"session":2,"number":59,"question":"下列那一顆大臼齒具有牙根凹陷（root concavity）的機率最高？","options":["(A) 上顎第一大臼齒近心牙根","(B) 上顎第一大臼齒遠心牙根","(C) 下顎第一大臼齒近心牙根","(D) 下顎第一大臼齒遠心牙根"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-2-60","subject":"ya3","topic":"牙周疾病與診斷","meta":"106年第2次第60題","year":106,"session":2,"number":60,"question":"1976年Page和Schröeder將牙齦炎和牙周炎的組織病理病灶分成四個時期，如圖文字所示最可能是何時期的 病灶？","options":["(A) Initial gingivtis","(B) Early gingivtis","(C) Established gingivtis","(D) Periodontitis"],"answer":2,"image":"ya3-106-2-60.jpeg","clinical_level":"重點"},{"id":"ya3-106-2-61","subject":"ya3","topic":"牙周疾病與診斷","meta":"106年第2次第61題","year":106,"session":2,"number":61,"question":"李醫師以checkerboard DNA-DNA hybridization方式測試某一患者在某處牙齦下牙周囊袋內是否含有red complex（1998年Socransky的分類）的細菌，下列何種細菌不屬於李醫師要測試的細菌？","options":["(A) P. gingivalis","(B) T. forsythia","(C) T. denticola","(D) F. nucleatum"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-2-62","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第2次第62題","year":106,"session":2,"number":62,"question":"下列那一種細胞會將外來的抗原（antigen）呈現（present）給T細胞，在牙周病的先天和後天免疫系統 （innate and adaptive immune system）反應中扮演連接橋樑的角色？","options":["(A) Neutrophil","(B) Dendritic cell","(C) Basophil","(D) Eosinophil"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-2-63","subject":"ya3","topic":"牙周手術與再生","meta":"106年第2次第63題","year":106,"session":2,"number":63,"question":"牙周手術後第一個月，常出現牙齒搖動度增加，其發生之主要原因是：","options":["(A) 手術後傷口發炎","(B) 手術後傷口感染","(C) 手術後牙齦退縮","(D) 手術破壞牙齦環帶（gingival cuff）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-2-64","subject":"ya3","topic":"牙周非手術治療","meta":"106年第2次第64題","year":106,"session":2,"number":64,"question":"下列何種牙刮（curettes）具有區域專一性？","options":["(A) Barnhar curettes","(B) Columbia curettes","(C) Nabers curettes","(D) Gracey curettes"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-2-65","subject":"ya3","topic":"牙周手術與再生","meta":"106年第2次第65題","year":106,"session":2,"number":65,"question":"有關牙周敷料的敘述，下列何者錯誤？","options":["(A) 牙周敷料具有促進傷口癒合的功能，因含有癒合因子（healing factor）","(B) 牙周敷料可以減少術後的感染及出血","(C) 目前常被使用的Coe-Pak，不含有eugenol，因為eugenol會引起過敏","(D) 牙周敷料是以倒凹（undercut）的方式，停留在牙縫間而非黏附在牙齒上面"],"answer":0,"clinical_level":"重點"},{"id":"ya3-106-2-66","subject":"ya3","topic":"牙周疾病與診斷","meta":"106年第2次第66題","year":106,"session":2,"number":66,"question":"有關牙齦退縮程度的大小與修復治療的關係，下列敘述何者錯誤？","options":["(A) 有牙齦下補綴物且較窄的角化牙齦之牙齒，其牙齦發炎指數較高","(B) 邊緣牙齦（marginal gingiva）的寬度比厚度更會影響牙齦退縮的程度","(C) 年長的成年人牙齦退縮，主要是牙周病引起的","(D) 良好的口腔衛生可以改善牙齦下補綴物之牙齦健康狀況"],"answer":1,"clinical_level":"重點"},{"id":"ya3-106-2-67","subject":"ya3","topic":"牙周手術與再生","meta":"106年第2次第67題","year":106,"session":2,"number":67,"question":"依照骨缺損的形態，深且寬的骨內缺損，最佳的處理方式為何？","options":["(A) 引導組織再生術合併骨移植","(B) 翻瓣手術合併骨移植或不使用骨移植材料","(C) 去除缺損的骨質合併骨再生手術","(D) 骨切除術"],"answer":0,"clinical_level":"一般"},{"id":"ya3-106-2-68","subject":"ya3","topic":"牙周手術與再生","meta":"106年第2次第68題","year":106,"session":2,"number":68,"question":"下列何者不是骨切除術（resective osseous surgery）的適應症？","options":["(A) 水平性骨缺損","(B) 淺的火山口狀缺損","(C) 半中隔（hemiseptum）骨缺損","(D) 三壁之骨缺損"],"answer":3,"clinical_level":"重點"},{"id":"ya3-106-2-69","subject":"ya3","topic":"牙周手術與再生","meta":"106年第2次第69題","year":106,"session":2,"number":69,"question":"上皮下結締組織移植術（subepithelial connective tissue graft）覆蓋牙根效果最好的主因是：","options":["(A) 移植組織較厚","(B) 縫合技術","(C) 結締組織直接與骨接觸","(D) 可有來自分層瓣膜與骨膜雙重血液循環"],"answer":3,"clinical_level":"重點"},{"id":"ya3-106-2-70","subject":"ya3","topic":"牙周手術與再生","meta":"106年第2次第70題","year":106,"session":2,"number":70,"question":"Lindhe與他的同事在1982年發表的研究中，發現若在少於下列何數值的牙周囊袋深度做改良式魏德曼翻瓣術 （modified Widman flap）會導致牙周附連喪失？","options":["(A) 4.2 mm","(B) 5.2 mm","(C) 7.0 mm","(D) 8.5 mm"],"answer":0,"clinical_level":"一般"},{"id":"ya3-106-2-71","subject":"ya3","topic":"牙周手術與再生","meta":"106年第2次第71題","year":106,"session":2,"number":71,"question":"以電刀手術（electrosurgery）進行牙齦切除術（gingivectomy），下列敘述何者錯誤？","options":["(A) 不可用於裝所有類型心律調節器（cardiac pacemaker）的病患","(B) 可用於牙齦腫大的病患","(C) 對繫帶（frenum）手術效果良好","(D) 以電刀做牙齦切除術，因較少出血所以傷口癒合較快"],"answer":3,"clinical_level":"重點"},{"id":"ya3-106-2-72","subject":"ya3","topic":"牙周手術與再生","meta":"106年第2次第72題","year":106,"session":2,"number":72,"question":"下列何種牙周手術的切開（incision）方式是如下圖所示？","options":["(A) Modified Widman flap","(B) Papilla preservation flap","(C) Excisional new attachment procedure","(D) Palatal flap"],"answer":1,"image":"ya3-106-2-72.jpeg","clinical_level":"一般"},{"id":"ya3-106-2-73","subject":"ya3","topic":"牙周疾病與診斷","meta":"106年第2次第73題","year":106,"session":2,"number":73,"question":"牙周疾病治療過並且控制良好的病患，須每隔幾年接受全口放射線照射檢查？","options":["(A) 1","(B) 2","(C) 3","(D) 5"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-2-74","subject":"ya3","topic":"牙周非手術治療","meta":"106年第2次第74題","year":106,"session":2,"number":74,"question":"判斷下列兩個敘述是正確或是錯誤？①在預防牙周炎的復發，已被治療後的牙周炎患者進入每3個月的回診， 與以顯微鏡偵測牙齦下菌叢為基礎的回診治療同樣有效 ②在病人每3個月的回診治療中，顯微鏡偵測牙齦下 菌叢對未來牙周的破壞預測，具高度的可信賴性","options":["(A) ①②均正確","(B) ①②均錯誤","(C) ①正確②錯誤","(D) ①錯誤②正確"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-2-75","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第2次第75題","year":106,"session":2,"number":75,"question":"下列何種生物標的物在早產兒母親牙齦溝液中含量較正常嬰兒母親為高，且其絨毛膜內含量對分娩開始時 機具有決定影響者為何？","options":["(A) IL-2","(B) PGE2","(C) IL-4","(D) IL-10"],"answer":1,"clinical_level":"一般"},{"id":"ya3-106-2-76","subject":"ya3","topic":"牙科解剖與生理","meta":"106年第2次第76題","year":106,"session":2,"number":76,"question":"人體內缺乏下列何種物質，會造成大細胞性貧血（macrocytic anemia）？","options":["(A) 維生素A","(B) 維生素C","(C) 菸鹼酸（niacin）","(D) 葉酸（folic acid）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-2-77","subject":"ya3","topic":"牙周疾病與診斷","meta":"106年第2次第77題","year":106,"session":2,"number":77,"question":"須藉由口服藥來控制糖尿病的55歲女性牙周病患者，因失業一年為家計煩惱，每天需抽菸兩包，飲酒一大 杯，下列各項因素中，何者對加速此患者牙周疾病破壞最不具相關性？","options":["(A) 未控制好的糖尿病","(B) 嚴重抽菸（heavy smoking）","(C) 骨質疏鬆症（osteoporosis）","(D) 長期在極度壓力下"],"answer":2,"clinical_level":"一般"},{"id":"ya3-106-2-78","subject":"ya3","topic":"植牙學","meta":"106年第2次第78題","year":106,"session":2,"number":78,"question":"下列有關植體的敘述，何者錯誤？","options":["(A) 粗糙面的植體（rough implant surface）可提高第二級穩定（secondary stability）","(B) 機械面的植體（machined implant）受細菌感染的機率較低","(C) 螺紋型的植體較容易達到第一級穩定（primary stability）","(D) 圓錐形（conical）的植體設計，主要是提升第二級穩定（secondary stability）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-106-2-79","subject":"ya3","topic":"植牙學","meta":"106年第2次第79題","year":106,"session":2,"number":79,"question":"植體周圍炎的動物研究顯示其病理機轉與牙周炎不同，主要是：","options":["(A) 相同時間內，植體周圍炎骨吸收較多","(B) 感染源去除後，植體周圍組織癒合較快","(C) 植體周圍炎骨再生效果較佳","(D) 植體周圍炎，嗜中性白血球較多"],"answer":0,"clinical_level":"重點"},{"id":"ya3-106-2-80","subject":"ya3","topic":"植牙學","meta":"106年第2次第80題","year":106,"session":2,"number":80,"question":"當牙齦是在健康情況下，以大於0.5 N的力探測人工植體周圍的牙齦溝，通常牙周探測具的前端（直徑0.5 mm）會落在何項解剖位置內？","options":["(A) 牙齦溝內","(B) 連接上皮（junctional epithelium）","(C) 結締組織內，但較近連接上皮（junctional epithelium）端","(D) 結締組織內，但逼近齒槽骨"],"answer":3,"clinical_level":"重點"},{"id":"ya3-107-1-1","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第1次第1題","year":107,"session":1,"number":1,"question":"有關發育完成的牙髓組織之敘述，下列何者正確？","options":["(A) 由於豐富的側枝循環已形成，受傷後有快速的癒合能力","(B) 其結締組織含幹細胞（stem cells）","(C) 是由dental lamina分化而來","(D) 血流量穩定，鮮少因周圍環境變化而改變"],"answer":1,"clinical_level":"重點"},{"id":"ya3-107-1-2","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第1次第2題","year":107,"session":1,"number":2,"question":"下列何者與牙髓內A-δ神經纖維較有關係？","options":["(A) 對炎性介質（inflammatory mediators）反應","(B) 與牽連痛（referred pain）有關係","(C) 與液體流動有關係","(D) 屬於傳導較慢的鈍痛"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-1-3","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第1次第3題","year":107,"session":1,"number":3,"question":"下列何種纖維不存在牙髓組織中？","options":["(A) 第一型膠原纖維（type I collagen fiber）","(B) 第三型膠原纖維（type III collagen fiber）","(C) 彈性纖維（elastic fiber）","(D) 神經纖維（nerve fiber）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-1-4","subject":"ya3","topic":"根管治療程序","meta":"107年第1次第4題","year":107,"session":1,"number":4,"question":"判讀X光片，根管封填良窳的標準不包括：","options":["(A) 根管封填的長度與形狀","(B) 根管封填出現側根管","(C) 根管封填的緻密度","(D) 牙冠填補物"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-1-5","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第1次第5題","year":107,"session":1,"number":5,"question":"隨著牙髓老化或受齲齒、牙齒磨損、覆髓之影響，牙髓中之造牙本質細胞（odontoblast）有何變化？","options":["(A) 細胞變大，數目增加","(B) 細胞變小，數目增加","(C) 細胞變大，數目變少","(D) 細胞變小，數目變少"],"answer":3,"clinical_level":"重點"},{"id":"ya3-107-1-6","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第1次第6題","year":107,"session":1,"number":6,"question":"對於乳牙或牙根尚未發育完全的牙齒，下列何者是決定牙髓診斷的重要依據？","options":["(A) 冷測試","(B) 電髓測試","(C) X光檢查","(D) 病史及疼痛的性質"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-1-7","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第1次第7題","year":107,"session":1,"number":7,"question":"有關裂齒症（cracked tooth syndrome）的敘述，下列何者錯誤？","options":["(A) 下顎大臼齒裂痕常見於近遠心方向","(B) 一旦發現裂痕，應立即採取根管治療","(C) 咬東西時，可能有銳痛","(D) 可以使用照光或染色法來診斷"],"answer":1,"clinical_level":"重點"},{"id":"ya3-107-1-8","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第1次第8題","year":107,"session":1,"number":8,"question":"起源於牙髓的牙根周圍病灶（periradicular lesion），其放射線攝影檢查的特徵不包括下列那一項？","options":["(A) 根尖處齒槽骨板（lamina dura）消失","(B) 通常可發現造成牙髓壞死的致病原因","(C) 其放射線透射病灶形狀通常為水滴狀","(D) 其放射線透射病灶的位置，會隨照攝的角度改變而呈現接近或遠離牙根尖"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-1-9","subject":"ya3","topic":"牙齒外傷處理","meta":"107年第1次第9題","year":107,"session":1,"number":9,"question":"最常發生牙齒外傷的年齡層為：","options":["(A) 1～10歲","(B) 20～30歲","(C) 40～50歲","(D) 60～70歲"],"answer":0,"clinical_level":"一般"},{"id":"ya3-107-1-10","subject":"ya3","topic":"牙齒外傷處理","meta":"107年第1次第10題","year":107,"session":1,"number":10,"question":"下列那一項牙齒外傷，可以先觀察而不需作處理？","options":["(A) 牙根橫向斷裂","(B) 複雜性（complicated）牙冠斷裂","(C) 內縮鬆脫齒（intrusive luxation）且根尖開口未閉合","(D) 脫落齒（avulsion）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-1-11","subject":"ya3","topic":"牙齒外傷處理","meta":"107年第1次第11題","year":107,"session":1,"number":11,"question":"牙齒外傷牙冠斷裂進行部分冠髓切除術（partial pulpotomy）時，一般須移除牙髓暴露處以下多深的牙髓組 織？","options":["(A) 1 mm","(B) 2 mm","(C) 4 mm","(D) 6 mm"],"answer":1,"clinical_level":"重點"},{"id":"ya3-107-1-12","subject":"ya3","topic":"牙齒外傷處理","meta":"107年第1次第12題","year":107,"session":1,"number":12,"question":"關於外傷牙之診斷與治療，下列敘述何者錯誤？","options":["(A) 當牙根水平斷裂（horizantal root fracture）且根管冠部牙髓喪失活性時，因根尖部分經常也會同時喪失活 性，故建議冠部及根尖部同時進行根管治療","(B) 當懷疑牙根水平斷裂（horizantal root fracture）時，應至少選擇3個角度（45，90及110度）照射根尖X光 片，以利斷裂線於X光片上明顯判讀","(C) 未成熟牙之牙冠斷裂，為維持牙髓之活性，活髓治療（vital pulp therapy）須優先被考慮","(D) 外傷未成熟牙齒之根尖成形術（apexification），可於氫氧化鈣敷藥後，利用三氧礦化聚合物MTA （mineral trioxide aggregate）進行根尖部位之充填"],"answer":0,"clinical_level":"一般"},{"id":"ya3-107-1-13","subject":"ya3","topic":"根管治療程序","meta":"107年第1次第13題","year":107,"session":1,"number":13,"question":"下列何者不是使用根管沖洗溶液的主要功用？","options":["(A) 移除根管內的碎屑殘渣並溶解污染的有機物質","(B) 殺菌消毒並潤滑根管","(C) 移除根管壁薄膜層並開啟牙本質小管開口","(D) 增加根管封填時的密閉性"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-1-14","subject":"ya3","topic":"根管器械","meta":"107年第1次第14題","year":107,"session":1,"number":14,"question":"在進行髓腔開擴時，下列何種狀況可以先不放置橡皮障（rubber dam）？","options":["(A) 相鄰的牙齒有轉位的情況而會導致橡皮障夾（clamp）不易置放的病例","(B) 橡皮障夾（clamp）會夾到牙齦而造成病患不舒服時","(C) 在髓腔開擴（access opening）時，髓腔或是根管開口難以定位者","(D) 曾經被修磨過的支台齒"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-1-15","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第1次第15題","year":107,"session":1,"number":15,"question":"造成壞死牙髓變色的主要物質為何？","options":["(A) 膽紅素（bilirubin）","(B) 硫化鐵（ferric sulfide）","(C) 氧化鐵（ferric oxide）","(D) 血小板（platelet）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-1-16","subject":"ya3","topic":"根管治療程序","meta":"107年第1次第16題","year":107,"session":1,"number":16,"question":"臨床上消毒馬來膠針（gutta-percha），下列何者最適宜？","options":["(A) 蒸餾水1分鐘","(B) 3%雙氧水（H2O2）1分鐘","(C) 生理食鹽水溶液（normal saline）1分鐘","(D) 5%次氯酸鈉溶液（NaOCl）1分鐘"],"answer":3,"clinical_level":"重點"},{"id":"ya3-107-1-17","subject":"ya3","topic":"牙齒外傷處理","meta":"107年第1次第17題","year":107,"session":1,"number":17,"question":"對於剛受外傷牙齒（traumatized teeth）去拍攝該顆牙齒部位的牙根尖X光片，其主要目的為何？","options":["(A) 可以看大部分的牙根斷裂","(B) 診察震盪（concussion）損傷","(C) 定位異物（foreign objects）","(D) 蒐集到受傷牙齒的基準資料"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-1-18","subject":"ya3","topic":"根尖手術與再治療","meta":"107年第1次第18題","year":107,"session":1,"number":18,"question":"下列何者不是牙根周圍手術（periradicular surgery）的止血劑？","options":["(A) Surgicel","(B) Gelfoam","(C) potassium sulfate","(D) epinephrine pellets"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-1-19","subject":"ya3","topic":"根管治療程序","meta":"107年第1次第19題","year":107,"session":1,"number":19,"question":"下列何者不是單次根管診療（single-visit）之適應症？","options":["(A) 有活性牙髓之病例","(B) 牙冠斷裂之前牙","(C) 診療期間無法達到良好密封（well-sealed）之牙齒","(D) 合併顏面腫脹的根管治療病例"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-1-20","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第1次第20題","year":107,"session":1,"number":20,"question":"下列有關側根管與副根管（lateral and accessory canals）之敘述，何者正確？","options":["(A) 側根管通常在牙根的牙冠三分之一比根尖三分之一常見","(B) 牙髓感染可經由側根管與副根管導致牙周組織的破壞","(C) 大臼齒的牙根分叉（furcation）有較多的副根管，但其存在並無重要臨床意義","(D) 側根管臨床上很容易就可以診斷出來，照X光片並無助於診斷"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-1-21","subject":"ya3","topic":"牙周手術與再生","meta":"107年第1次第21題","year":107,"session":1,"number":21,"question":"大臼齒的牙周治療計畫，若需涵蓋牙根切除術（root resection），下列敘述何者正確？","options":["(A) 直接切除，於牙髓暴露處以氫氧化鈣覆髓，再以永久填補物填補","(B) 為避免牙周病情加重，先進行牙根切除，再儘快完成根管治療","(C) 先進行根管清創，待切除牙根後，再進行根管充填","(D) 先完成根管治療，再進行牙根切除"],"answer":3,"clinical_level":"重點"},{"id":"ya3-107-1-22","subject":"ya3","topic":"根管治療程序","meta":"107年第1次第22題","year":107,"session":1,"number":22,"question":"當牙髓病治療發現疑似分離器械於根管時，下列何者處理較不適當？","options":["(A) 告知病患分離器械於根管，並解釋分離器械是引起疼痛之原因","(B) 告知病患X光片顯示有白色影像，可能阻礙了清創的進行，適當的解釋與安撫，避免病患驚慌","(C) 試著自行取出，若無設備或是未接受過訓練，可轉診根管治療專科醫師治療","(D) 若無法取出或繞道分離器械，又有根尖病灶，可以完成非手術性根管治療後，再以手術性根管治療處理"],"answer":0,"clinical_level":"一般"},{"id":"ya3-107-1-23","subject":"ya3","topic":"根管治療程序","meta":"107年第1次第23題","year":107,"session":1,"number":23,"question":"下圖是兩種角度拍攝X光片中的第一大臼齒，在那一個根管有斷裂的器械（如下圖箭頭處所示）？","options":["(A) 近心頰側根管（MB canal）","(B) 第二近心頰側根管（MB2 canal）","(C) 遠心頰側根管（DB canal）","(D) 腭側根管（P canal）"],"answer":0,"image":"ya3-107-1-23.jpeg","clinical_level":"一般"},{"id":"ya3-107-1-24","subject":"ya3","topic":"根管治療程序","meta":"107年第1次第24題","year":107,"session":1,"number":24,"question":"承上題，在此X光片中，除了見到分離器械外還可能發生何種根管治療的意外（procedure accident）？","options":["(A) 根管zipping","(B) 人為根管（artificial canal）","(C) 根尖穿孔（apical perforation）","(D) 切削穿孔（stripping perforation）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-1-25","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第1次第25題","year":107,"session":1,"number":25,"question":"10歲小女生前來牙科檢查牙齒，發現下顎第二小臼齒咬合面咬頭凸出（如下圖），下列敘述何者錯誤？","options":["(A) 此凸出的咬頭叫做Carabelli cusp","(B) 時常雙側性發生","(C) 東方人種較常發生","(D) 下顎小臼齒較常發生"],"answer":0,"image":"ya3-107-1-25.jpeg","clinical_level":"一般"},{"id":"ya3-107-1-26","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第1次第26題","year":107,"session":1,"number":26,"question":"承上題，臨床上常發生的狀況為何？①常造成牙髓壞死 ②牙髓早期壞死以致牙根發育不全 ③需要立刻做根 管治療 ④常造成咬合干擾","options":["(A) ①②③","(B) ①②④","(C) ①③④","(D) ②③④"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-1-27","subject":"ya3","topic":"窩洞設計與分類","meta":"107年第1次第27題","year":107,"session":1,"number":27,"question":"有關牙釉質之敘述，下列何者錯誤？","options":["(A) 全身最硬的組織","(B) 愈接近牙本質牙釉質交界處（dentino-enamel junction）硬度愈高","(C) 有高的彈性係數（elastic modulus）及低的抗張強度（tensile strength）","(D) 進行窩洞製備時，牙釉稜柱（enamel rods）需有牙本質的支持"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-1-28","subject":"ya3","topic":"複合樹脂與材料","meta":"107年第1次第28題","year":107,"session":1,"number":28,"question":"下列何種材料與齒質間的熱膨脹係數相差最大？","options":["(A) 金箔","(B) 鑄造金合金","(C) 玻璃離子體黏合劑","(D) 複合樹脂"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-1-29","subject":"ya3","topic":"牙科解剖與生理","meta":"107年第1次第29題","year":107,"session":1,"number":29,"question":"牙釉質在接受氟化物處理前與後，下列開始發生去礦化作用的酸鹼值，何者最有可能？","options":["(A) 5.5/3.5","(B) 3.5/5.5","(C) 7.0/5.5","(D) 5.5/7.0"],"answer":0,"clinical_level":"一般"},{"id":"ya3-107-1-30","subject":"ya3","topic":"窩洞設計與分類","meta":"107年第1次第30題","year":107,"session":1,"number":30,"question":"下列何者不是影響鄰接面齲齒的因素？","options":["(A) 牙齒鄰接面的表面形態","(B) 牙齦乳頭（gingival papillae）的大小形狀","(C) 病患的口腔衛生習慣","(D) 復形填補的材料"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-1-31","subject":"ya3","topic":"牙周疾病與診斷","meta":"107年第1次第31題","year":107,"session":1,"number":31,"question":"下列何者非牙根齲蝕的好發因子（risk factor）？","options":["(A) 牙根暴露","(B) 老年人","(C) 戴活動假牙者","(D) 常吃較硬食物"],"answer":3,"clinical_level":"重點"},{"id":"ya3-107-1-32","subject":"ya3","topic":"牙科解剖與生理","meta":"107年第1次第32題","year":107,"session":1,"number":32,"question":"牙本質含重量百分比18%的有機質，其主要的成分是：","options":["(A) 第一類膠原蛋白（Type I Collagen）","(B) 第二類膠原蛋白（Type II Collagen）","(C) 第三類膠原蛋白（Type III Collagen）","(D) 第四類膠原蛋白（Type IV Collagen）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-107-1-33","subject":"ya3","topic":"黏著與美學修復","meta":"107年第1次第33題","year":107,"session":1,"number":33,"question":"在陶瓷嵌體的黏著操作中，黏著面的表面處理，下列步驟之排列順序，何者正確？①塗佈氫氟酸 （hydrofluoric acid） ②塗佈樹脂黏著劑（bonding agent） ③塗佈矽烷偶合劑（silane coupling agent）","options":["(A) ②①③","(B) ①②③","(C) ①③②","(D) ③①②"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-1-34","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第1次第34題","year":107,"session":1,"number":34,"question":"一般以hydrodynamic theory解釋牙齒接受冷熱刺激後引發牙本質敏感症（dentinal hypersensitivity），其機 轉為何？","options":["(A) 牙髓腔產生膨脹或收縮","(B) 牙髓腔的液體成分改變","(C) 牙本質液體的流動刺激神經末梢的接受器","(D) 牙釉質與牙本質的熱膨脹係數不同"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-1-35","subject":"ya3","topic":"窩洞設計與分類","meta":"107年第1次第35題","year":107,"session":1,"number":35,"question":"下列有關鄰接面齲齒的敘述，何者錯誤？","options":["(A) 鄰接面齲蝕易被忽視，可由放射線攝影檢查","(B) 鄰接面棕黃色斑點若是硬質牙齒則不需要治療","(C) 鄰接面棕黃色斑點常見於年輕的患者","(D) 鄰接面棕黃色斑點常是氟化磷灰石（fluorohydroxyapatite）形成，抗齲性較高"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-1-36","subject":"ya3","topic":"牙體修形程序","meta":"107年第1次第36題","year":107,"session":1,"number":36,"question":"窩洞修形時，下列何者最適合製備倒凹型的窩洞？","options":["(A) No. 4 carbide bur","(B) No. 33 1/2 carbide bur","(C) No. 271 carbide bur","(D) No. 169L carbide bur"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-1-37","subject":"ya3","topic":"牙體修形程序","meta":"107年第1次第37題","year":107,"session":1,"number":37,"question":"牙體復形過程中，使用指靠（finger rest）的主要目的為何？","options":["(A) 放鬆手指肌肉","(B) 分散手指施力支點","(C) 穩住手持器械避免滑動","(D) 增加手持器械握持面積"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-1-38","subject":"ya3","topic":"窩洞設計與分類","meta":"107年第1次第38題","year":107,"session":1,"number":38,"question":"右上顎第一大臼齒近心面齒頸部窩洞屬於G.V Black窩洞分類之何種類型？","options":["(A) 第一類型","(B) 第二類型","(C) 第三類型","(D) 第五類型"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-1-39","subject":"ya3","topic":"牙體修形程序","meta":"107年第1次第39題","year":107,"session":1,"number":39,"question":"為了手用切削器械（hand instrument）施力操作時維持平衡，應使刃部的切削緣（blade cutting edge）與握 柄長軸（long axis of the handle）保持在多少mm範圍內？","options":["(A) 0～0.5","(B) 1～3","(C) 4～6","(D) 7～8"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-1-40","subject":"ya3","topic":"牙體修形程序","meta":"107年第1次第40題","year":107,"session":1,"number":40,"question":"有關牙體復形治療時，使用橡皮障（rubber dam）的敘述，下列何者錯誤？","options":["(A) 可提高填補品質","(B) 防止病人吞入異物","(C) 保持操作範圍視野清晰","(D) 會降低工作效率"],"answer":3,"clinical_level":"重點"},{"id":"ya3-107-1-41","subject":"ya3","topic":"牙體修形程序","meta":"107年第1次第41題","year":107,"session":1,"number":41,"question":"第五類型窩洞充填，使用排齦線之時機為何？①麻醉前 ②麻醉後 ③窩洞修形前 ④窩洞修形後","options":["(A) ①③","(B) ①④","(C) ②③","(D) ②④"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-1-42","subject":"ya3","topic":"黏著與美學修復","meta":"107年第1次第42題","year":107,"session":1,"number":42,"question":"下列何者不是前牙複合樹脂比色之原則？","options":["(A) 使用自然光源","(B) 牙齒隔離之前先比色","(C) 先以少許複合樹脂光聚合後比色","(D) 牙齒吹乾後比色"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-1-43","subject":"ya3","topic":"牙體修形程序","meta":"107年第1次第43題","year":107,"session":1,"number":43,"question":"複合樹脂充填時，為補償隔片厚度，以獲得適當的鄰接面接觸，最重要的步驟始於：","options":["(A) 窩洞設計","(B) 窩洞修形","(C) 先行置放木楔","(D) 樹脂修形與磨光"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-1-44","subject":"ya3","topic":"複合樹脂與材料","meta":"107年第1次第44題","year":107,"session":1,"number":44,"question":"有關三明治填補法（open-sandwich technique）之敘述，何者錯誤？","options":["(A) 不適用於窩洞邊緣在牙骨質或牙本質上","(B) 使用樹脂改良型玻璃離子體（resin-modified glass ionomer）密封牙齦壁","(C) 可減低術後敏感","(D) 可減少牙齦壁（gingival wall）之去礦化（demineralization）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-107-1-45","subject":"ya3","topic":"窩洞設計與分類","meta":"107年第1次第45題","year":107,"session":1,"number":45,"question":"以汞齊修復包括覆蓋牙尖（capping cusp）時，汞齊厚度在非功能性牙尖（nonfunctional cusp）至少應為多 少mm？","options":["(A) 1.0","(B) 1.5","(C) 2.0","(D) 2.5"],"answer":1,"clinical_level":"重點"},{"id":"ya3-107-1-46","subject":"ya3","topic":"牙體修形程序","meta":"107年第1次第46題","year":107,"session":1,"number":46,"question":"汞齊窩洞充填有局部深度齲蝕時，以樹脂改良型玻璃離子體（resin-modified glass ionomer）當底墊 （base），下列敘述何者正確？","options":["(A) 殘餘牙本質（remaining dentin）的厚度1.5 mm時需作底墊","(B) 需覆蓋所有髓壁（pulpal wall）的牙本質","(C) 需覆蓋窩洞所有暴露的牙本質","(D) 底墊需有0.5 mm以上的厚度"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-1-47","subject":"ya3","topic":"窩洞設計與分類","meta":"107年第1次第47題","year":107,"session":1,"number":47,"question":"在窩洞設計中，提供防止齒質斷裂與復形物移位的機械性設計為：","options":["(A) 抗力型（resistance form）","(B) 固位型（retention form）","(C) 便利型（convenience form）","(D) 外型（outline form）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-107-1-48","subject":"ya3","topic":"牙體修形程序","meta":"107年第1次第48題","year":107,"session":1,"number":48,"question":"非活性牙的持續漂白法（walking bleach）之操作，下列敘述何者錯誤？","options":["(A) 最適當的漂白藥劑是30～35%的過氧化氫（hydrogen peroxide）","(B) 髓腔內的充填物及牙膠（gutta-percha）需移除至臨床牙冠（clinical crown）以下1～2 mm","(C) 髓腔的根管開口及其周遭需以樹脂強化玻璃離子體（RMGI）封閉","(D) 漂白藥劑需每週更換"],"answer":0,"clinical_level":"一般"},{"id":"ya3-107-1-49","subject":"ya3","topic":"黏著與美學修復","meta":"107年第1次第49題","year":107,"session":1,"number":49,"question":"陶瓷鑲面（ceramic veneer）相較於直接複合樹脂（direct resin composite）充填，下列何者正確？","options":["(A) 製作時間較短","(B) 較可能修復（repair）","(C) 較不可能造成對咬牙磨耗（wear）","(D) 美觀持久性較佳"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-1-50","subject":"ya3","topic":"窩洞設計與分類","meta":"107年第1次第50題","year":107,"session":1,"number":50,"question":"有關金屬冠蓋體（onlay）復形之頸部製備（collar preparation）的描述，何者錯誤？","options":["(A) 頸部製備可增加固位（retention）和抗力（resistance）","(B) 頸部製備具有0.8 mm深的肩台（shoulder）","(C) 頸部製備的高度（occlusogingivally）為2～3 mm","(D) 製備方式是平行牙齒長軸在牙本質磨出溝槽（slot）"],"answer":3,"clinical_level":"重點"},{"id":"ya3-107-1-51","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第1次第51題","year":107,"session":1,"number":51,"question":"下列情況有關覆髓之敘述，何者錯誤？","options":["(A) 當牙髓暴露小於0.5 mm時，可進行覆髓治療","(B) 當牙齒曾有持續疼痛症狀而目前不痛時，可進行覆髓治療","(C) 當牙髓暴露而出血可控制時，可進行覆髓治療","(D) 當牙髓暴露時可用氫氧化鈣輕放在暴露點上進行覆髓治療"],"answer":1,"clinical_level":"重點"},{"id":"ya3-107-1-52","subject":"ya3","topic":"牙體修形程序","meta":"107年第1次第52題","year":107,"session":1,"number":52,"question":"在牙齒接受完嵌體修形後，至下次正式黏著上嵌體前，製作臨時填補物的敘述，下列何者錯誤？","options":["(A) 承受足夠咬合力","(B) 可維持牙周組織健康","(C) 黏著強度越低越好","(D) 輔助維持支台齒之位置"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-1-53","subject":"ya3","topic":"牙科解剖與生理","meta":"107年第1次第53題","year":107,"session":1,"number":53,"question":"下列有關basal lamina之敘述，何者正確？","options":["(A) 含lamina lucida及lamina densa","(B) 厚度為300至400 µm","(C) 位於上皮基底層下約300至400 µm","(D) 在組織學上是periodic acid-Schiff（paS）染色呈陰性反應"],"answer":0,"clinical_level":"一般"},{"id":"ya3-107-1-54","subject":"ya3","topic":"牙科解剖與生理","meta":"107年第1次第54題","year":107,"session":1,"number":54,"question":"Merkel's cells主要功能為：","options":["(A) Phagocytosis","(B) Cytokine secretion","(C) Tactile sensation","(D) Antigen presentation"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-1-55","subject":"ya3","topic":"牙科解剖與生理","meta":"107年第1次第55題","year":107,"session":1,"number":55,"question":"下列有關牙骨質的敘述，何者正確？","options":["(A) 牙骨質是一種與骨骼相似的鈣化組織，但只有牙骨質的鈣化成分是以hydroxyapatite為主","(B) 牙骨質可由造牙骨質母細胞或貼附牙骨質上的牙周韌帶細胞產生","(C) 含細胞牙骨質多附著在牙根底部三分之一及根尖分岔處，分佈其中的cementocyte可以分泌堆積造成牙骨質 的厚度增加","(D) 無細胞牙骨質分佈在整個牙根表面，只能進行牙骨質堆積而無法吸收，造成牙骨質厚度終生不斷增加"],"answer":1,"clinical_level":"重點"},{"id":"ya3-107-1-56","subject":"ya3","topic":"牙周疾病與診斷","meta":"107年第1次第56題","year":107,"session":1,"number":56,"question":"下列何種檢查對鑑別診斷“侵犯性牙周炎”（aggressive periodontitis）或慢性牙周炎兩種疾病是有幫助 的？","options":["(A) 牙周囊袋深度","(B) 附著牙齦寬度","(C) 牙齦發炎指數和牙菌斑指數","(D) 嗜中性白血球的吞噬功能"],"answer":3,"clinical_level":"重點"},{"id":"ya3-107-1-57","subject":"ya3","topic":"牙周疾病與診斷","meta":"107年第1次第57題","year":107,"session":1,"number":57,"question":"依照Socransky（1998）的分類，在牙齦下牙菌斑形成時，下列何種細菌不屬於後期出現的red complex？","options":["(A) P. gingivalis","(B) T. forsythia（原B. forsythus）","(C) T. denticola","(D) F. nucleatum"],"answer":3,"clinical_level":"重點"},{"id":"ya3-107-1-58","subject":"ya3","topic":"牙周疾病與診斷","meta":"107年第1次第58題","year":107,"session":1,"number":58,"question":"在慢性牙周病患者牙齦組織內，下列何種是分泌interleukin-1的主要細胞？","options":["(A) 多形核嗜中性細胞（PMNs）","(B) 巨噬細胞（macrophages）","(C) 角質細胞（keratinocytes）","(D) 漿細胞（plasma cells）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-1-59","subject":"ya3","topic":"牙科解剖與生理","meta":"107年第1次第59題","year":107,"session":1,"number":59,"question":"下列何者不參與天生的初期免疫反應（innate immunity）？","options":["(A) B細胞（B cells）","(B) 上皮細胞（epithelial cells）","(C) 類toll 受體（toll-like receptor）","(D) 補體（complement）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-107-1-60","subject":"ya3","topic":"牙周疾病與診斷","meta":"107年第1次第60題","year":107,"session":1,"number":60,"question":"具有白血球毒素（leukotoxin）之牙周致病菌為：","options":["(A) Porphyromonas gingivalis","(B) Prevotella intermedia","(C) Aggregatibacter actinomycetemcomitans","(D) Campylobacter rectus"],"answer":[2,3],"clinical_level":"重點","explanation_pending":false},{"id":"ya3-107-1-61","subject":"ya3","topic":"牙周手術與再生","meta":"107年第1次第61題","year":107,"session":1,"number":61,"question":"下圖左下側牙齒34/35近心側放射線所顯示，下列敘述何者正確？①35若是two-wall or three-wall角性骨缺 損，適合牙周再生性手術 ②愈深的骨缺損有較多的臨床改善 ③若只考慮角度大小，當角A小於25°，而角 B大於37°時，牙周再生手術後牙齒34比牙齒35可獲得較多的附連組織","options":["(A) 僅①②","(B) ①②③","(C) 僅②③","(D) 僅①③"],"answer":1,"image":"ya3-107-1-61.jpeg","clinical_level":"一般"},{"id":"ya3-107-1-62","subject":"ya3","topic":"牙周非手術治療","meta":"107年第1次第62題","year":107,"session":1,"number":62,"question":"關於牙周病治療計畫和預後的敘述，下列何者正確？","options":["(A) 病人接受牙周病治療時，常因假牙形態不佳、次發性齲齒，而須將不良的贋復物拆除","(B) 牙周初期治療後，評估是否進入牙周手術療程，只評估牙周情況、預後，不需要考量病人的合作意願","(C) 倘若病人就診時，牙周情況嚴重，應立即給與積極性牙周手術治療，以把握牙周治療的黃金時間","(D) 倘若病人的牙齒有合併牙周和根管的問題，應先處理好牙周病的治療，再評估根管治療的可行性"],"answer":0,"clinical_level":"一般"},{"id":"ya3-107-1-63","subject":"ya3","topic":"牙周非手術治療","meta":"107年第1次第63題","year":107,"session":1,"number":63,"question":"有關doxycycline在做為host modulation使用時，下列敘述何者正確？","options":["(A) 劑量為25 mg，一天一次","(B) 劑量為50 mg，一天二次","(C) 劑量為25 mg，一天三次","(D) 劑量為20 mg，一天二次"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-1-64","subject":"ya3","topic":"牙科解剖與生理","meta":"107年第1次第64題","year":107,"session":1,"number":64,"question":"下圖所示牙齦組織切片（HE染色）中，箭頭所指之細胞，下列何者正確？","options":["(A) Keratinocytes in basal layer","(B) Fibroblasts","(C) Keratinocytes in granular layer","(D) Endothelial cells"],"answer":0,"image":"ya3-107-1-64.jpeg","clinical_level":"一般"},{"id":"ya3-107-1-65","subject":"ya3","topic":"牙周手術與再生","meta":"107年第1次第65題","year":107,"session":1,"number":65,"question":"有關牙周翻瓣術的切開法，下列敘述何者正確？","options":["(A) 內斜切 (internal bevel incision) 是由牙周囊袋底部向牙骨嵴切下","(B) 牙齦溝切開法（crevicular incision)是由牙齦上端適當距離向牙骨嵴切下","(C) 牙齦溝切開法（crevicular incision）又稱first incision","(D) 齒間切開法（interdental incision）可去除牙周囊袋內襯（pocket lining）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-1-66","subject":"ya3","topic":"牙周手術與再生","meta":"107年第1次第66題","year":107,"session":1,"number":66,"question":"有關牙根表面處理（root surface conditioning）的敘述，下列何者錯誤？","options":["(A) 可以去除塗抹層（smear layer）","(B) 可以防止上皮組織向下生長","(C) 處理後在組織學上的癒合是結締組織與新生牙骨質形成附連","(D) 以EDTA作牙根表面處理不會造成周圍牙周組織的壞死，因為EDTA的pH值為中性"],"answer":2,"clinical_level":"重點"},{"id":"ya3-107-1-67","subject":"ya3","topic":"牙周手術與再生","meta":"107年第1次第67題","year":107,"session":1,"number":67,"question":"有關接受牙周手術之患者在術前該處理的敘述，下列何者錯誤？","options":["(A) 只有medically compromised的患者才必須在手術前給予抗生素","(B) 研究指出，為了減少術後患者的疼痛及腫脹，所以必須在術前給予抗生素，且在術後要連續使用4～7天","(C) 在術前1小時給予ibuprofen（Motrin），及以0.12%的chlorhexidine（Peridex）漱口可減少疼痛與感染的機 會","(D) 牙周手術合併進行骨移植的患者，為了提高獲得新生牙周附連的成功機會，必須要術前給予抗生素"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-1-68","subject":"ya3","topic":"植牙學","meta":"107年第1次第68題","year":107,"session":1,"number":68,"question":"有關脫鈣冷凍乾燥異體骨（demineralized freeze-dried bone allograft, DFDBA）之敘述，下列何者錯誤？","options":["(A) 取自死亡24小時內捐獻者之皮質骨","(B) DFDBA含有骨成形蛋白（bone morphogenetic proteins, BMPs）","(C) Osteogenin分離自人骨的細胞外基質，具有促進骨再生的能力","(D) 被HIV感染的機率約為1～8百萬分之一"],"answer":0,"clinical_level":"一般"},{"id":"ya3-107-1-69","subject":"ya3","topic":"牙周手術與再生","meta":"107年第1次第69題","year":107,"session":1,"number":69,"question":"有關牙冠增長術的適應症敘述，下列何者錯誤？","options":["(A) 合併補綴的方法，可以解決病人們的美觀問題","(B) 牙根中間1/3的位置之穿孔或牙根斷裂","(C) 牙齦下齲齒","(D) 沒有足夠的牙齒結構來維持牙冠的固位（retention）"],"answer":1,"clinical_level":"重點"},{"id":"ya3-107-1-70","subject":"ya3","topic":"牙周手術與再生","meta":"107年第1次第70題","year":107,"session":1,"number":70,"question":"於前牙區進行pouch與onlay augmentation procedures，術後幾個月製作永久假牙最合適？","options":["(A) 1","(B) 3","(C) 6","(D) 12"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-1-71","subject":"ya3","topic":"牙周手術與再生","meta":"107年第1次第71題","year":107,"session":1,"number":71,"question":"Gingivectomy傷口癒合時，新生上皮每天移動的速率約為：","options":["(A) 0.25 mm／天","(B) 0.50 mm／天","(C) 0.75 mm／天","(D) 1.0 mm／天"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-1-72","subject":"ya3","topic":"牙周手術與再生","meta":"107年第1次第72題","year":107,"session":1,"number":72,"question":"有關牙周翻瓣手術後傷口的癒合過程，下列敘述何者錯誤？","options":["(A) 手術後24小時內島瓣（flap）與牙齒之間有大量之白血球（PMNs）、紅血球聚集及血液凝塊","(B) 手術後一週有膠原纖維（collagen fiber）平行於牙根表面","(C) 全層瓣（full-thickness flap）暴露的牙骨嵴會在1～3天內壞死，導致牙骨嵴吸收約1 mm","(D) 手術後一個月，牙齦溝上皮（gingival crevice epithelium）會完全形成"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-1-73","subject":"ya3","topic":"牙周疾病與診斷","meta":"107年第1次第73題","year":107,"session":1,"number":73,"question":"下列有關periodontal index（PI, Russell 1954）與periodontal disease index（PDI, Ramfjord 1959）的敘 述，何者正確？","options":["(A) PI指數記分最高為6","(B) PDI指數記分最高為8","(C) PDI不測牙周囊袋深度","(D) PDI指數經常被評論低估牙周病的流行率"],"answer":2,"clinical_level":"重點"},{"id":"ya3-107-1-74","subject":"ya3","topic":"牙周非手術治療","meta":"107年第1次第74題","year":107,"session":1,"number":74,"question":"牙周病已成功治療後，若沒有定期回診，其牙周炎的復發機率是定期回診的幾倍？","options":["(A) 1～2倍","(B) 3～4倍","(C) 5～7倍","(D) 大於8倍"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-1-75","subject":"ya3","topic":"牙周疾病與診斷","meta":"107年第1次第75題","year":107,"session":1,"number":75,"question":"副甲狀腺機能過旺症（hyperparathyroidism）之病患，有關牙周組織出現的症狀之敘述，下列何者正確？","options":["(A) 齒槽骨板（lamina dura）增厚","(B) 齒槽骨板（lamina dura）消失","(C) 齒槽骨密度增加","(D) 牙周韌帶的寬度變窄"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-1-76","subject":"ya3","topic":"牙科解剖與生理","meta":"107年第1次第76題","year":107,"session":1,"number":76,"question":"下列何種檢驗，可以檢視糖尿病患者，最近三個月血糖控制的情形？","options":["(A) 空腹血糖濃度（fasting blood sugar）","(B) 隨機血糖濃度（casual blood sugar）","(C) 葡萄糖耐受試驗（glucose tolerance test）","(D) 醣化血色素（glycated hemoglobin）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-1-77","subject":"ya3","topic":"牙周疾病與診斷","meta":"107年第1次第77題","year":107,"session":1,"number":77,"question":"下列何種病患中會出現類似壞死潰瘍性牙周炎（necrotizing ulcerative periodontitis）的情况？","options":["(A) 單純皰疹病毒感染","(B) 人類免疫缺乏病毒感染","(C) 黴菌感染","(D) 結核病菌感染"],"answer":1,"clinical_level":"重點"},{"id":"ya3-107-1-78","subject":"ya3","topic":"植牙學","meta":"107年第1次第78題","year":107,"session":1,"number":78,"question":"為了避免垂直性骨吸收（vertical bone resorption），相鄰兩顆直徑5 mm寬的植體圓心之距離至少應有多少 mm？","options":["(A) 3","(B) 5","(C) 7","(D) 8"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-1-79","subject":"ya3","topic":"植牙學","meta":"107年第1次第79題","year":107,"session":1,"number":79,"question":"健康植體周圍軟組織的上皮附連（epithelium attachment）長度約為多少毫米？","options":["(A) 0.5","(B) 1","(C) 2","(D) 3"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-1-80","subject":"ya3","topic":"植牙學","meta":"107年第1次第80題","year":107,"session":1,"number":80,"question":"下列何者不是去除植體的適應症？","options":["(A) 給予負荷一年內快速且嚴重的骨破壞","(B) 不利的嚴重骨缺損（一骨壁）（one-wall bony defect）","(C) 非手術性或手術性治療無效時","(D) 植體周圍骨喪失（小於植體長度的50%）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-2-1","subject":"ya3","topic":"醫學倫理與法規","meta":"107年第2次第1題","year":107,"session":2,"number":1,"question":"根管治療中發生分離器械而且無法移除時，下列何種處理最恰當？","options":["(A) 立即拔掉患者牙齒","(B) 繼續進行根管治療及根管充填，並不需要告知患者","(C) 若患者仍感疼痛，在告知患者後拔掉牙齒","(D) 告知患者並分析可能的影響，必要時安排轉診"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-2-2","subject":"ya3","topic":"牙科解剖與生理","meta":"107年第2次第2題","year":107,"session":2,"number":2,"question":"有關牙骨質（cementum）的敘述，下列何者正確？","options":["(A) 牙骨質的硬度小於齒槽骨","(B) 是由齒濾泡（dental follicle）分化而來","(C) 無細胞無纖維牙骨質（acellular afibrillar cementum）參與纖維附連（fiber attachment）","(D) 原生無細胞外在纖維牙骨質（primary acellular extrinsic fiber cementum）是最先形成的牙骨質"],"answer":1,"clinical_level":"重點"},{"id":"ya3-107-2-3","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第2次第3題","year":107,"session":2,"number":3,"question":"下列何者是健康牙髓內最主要的免疫細胞？","options":["(A) 巨噬細胞（macrophage）","(B) 嗜中性白血球（neutrophil）","(C) 組織細胞（histiocyte）","(D) 樹突細胞（dendritic cell）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-2-4","subject":"ya3","topic":"根管治療程序","meta":"107年第2次第4題","year":107,"session":2,"number":4,"question":"關於上顎第一大臼齒牙根與根管解剖形態的敘述，下列何者錯誤？","options":["(A) 通常有3個牙根與4個根管","(B) 遠心頰側牙根通常有1個根管","(C) 近心頰側牙根通常有近心頰側與近心腭側2個根管","(D) 近心腭側根管不易尋找，通常是因為齲齒產生的二級牙本質蓋住根管開口"],"answer":3,"clinical_level":"重點"},{"id":"ya3-107-2-5","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第2次第5題","year":107,"session":2,"number":5,"question":"52歲男性患者自述右上第一大臼齒頰側牙齦反覆腫脹已經持續1個月，臨床檢查發現患齒頰側牙齦有明顯的腫 脹（swelling）並有輕微的觸痛感，此外在附連牙齦（attached gingiva）有竇管（sinus tract）出現，同時患 齒咬合面有明顯磨耗現象，於近心頰側牙根的頰側與舌側均有深且窄（8～10 mm）的牙周囊袋，並有敲痛與 咬痛的問題，放射線學檢查結果如下圖所示。則患齒的問題最有可能是下列何者所引起？","options":["(A) 慢性根尖周圍炎（chronic apical periodontitis）","(B) 牙根穿孔（root perforation）","(C) 垂直牙根斷裂（vertical root fracture）","(D) 側邊牙周囊腫（lateral periodontal cyst）"],"answer":2,"image":"ya3-107-2-5.jpeg","clinical_level":"一般"},{"id":"ya3-107-2-6","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第2次第6題","year":107,"session":2,"number":6,"question":"因失敗的根管治療所造成的持續性根尖周圍炎，根管常存在何種高比例（存在數目較原發性根管內感染高約9 倍）的微生物？","options":["(A) 白色念珠菌（Candida albicans）","(B) 糞腸球菌（Enterococcus faecalis）","(C) 福賽斯坦納菌（Tannerella forsythia）","(D) 金黃色葡萄球菌（Staphylococcus aureus）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-2-7","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第2次第7題","year":107,"session":2,"number":7,"question":"關於根尖周圍炎（apical periodontitis），下列敘述何者正確？","options":["(A) 外生性（exogenous）及內生性（endogenous）的因素都有可能產生","(B) 在根管系統中牙髓的感染並非造成根尖周圍炎最主要的原因","(C) 學者Kakehashi發現無菌環境（germ-free）下，牙髓神經暴露伴有食物殘渣，將導致牙髓根尖發炎","(D) 根尖微生物導致根尖感染（apical infection）一定會同時造成根尖發炎（apical inflammation）"],"answer":0,"clinical_level":"重點"},{"id":"ya3-107-2-8","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第2次第8題","year":107,"session":2,"number":8,"question":"關於牙根根管內吸收（internal root resorption）的敘述，下列何者錯誤？","options":["(A) 可藉由不同水平角度之根尖片來診斷牙根根管內吸收的存在","(B) 出現牙根根管內吸收的牙齒，臨床上病人多會有強烈疼痛的反應","(C) 可能從牙冠透出粉紅色的斑點（pink spot）","(D) 曾經受到外傷或做過假牙的活髓牙齒，有較高的機率出現牙根根管內吸收"],"answer":1,"clinical_level":"重點"},{"id":"ya3-107-2-9","subject":"ya3","topic":"牙齒外傷處理","meta":"107年第2次第9題","year":107,"session":2,"number":9,"question":"關於牙齒脫位（luxation）的敘述，下列何者正確？","options":["(A) 內縮脫位（intrusive luxation）代表有牙齒移位，且動搖度（mobility）增加","(B) 牙齒脫位是常見的牙齒外傷形式，通常合併有牙齒支持組織的受損","(C) 發育完成之恆齒受到內縮脫位後，若需矯正拉出治療應儘快在2～3個月內開始","(D) 側向脫位（lateral luxation）的牙齒，通常伴隨水平牙根斷裂"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-2-10","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第2次第10題","year":107,"session":2,"number":10,"question":"關於垂直牙根斷裂（vertical root fracture）的敘述，下列何者錯誤？","options":["(A) 臨床上可在牙冠上面看到裂痕，並往下延伸至牙根","(B) 頰舌側方向的裂痕發生率較近遠心方向的發生率高","(C) 較常發生在曾經做過根管治療牙齒的牙根上","(D) 利用牙周探針檢查，牙周囊袋深度可能正常或出現窄且深的囊袋"],"answer":0,"clinical_level":"重點"},{"id":"ya3-107-2-11","subject":"ya3","topic":"根管治療程序","meta":"107年第2次第11題","year":107,"session":2,"number":11,"question":"下列3種根管封填方法：側方封填法（lateral compaction）、連續熱塑馬來膠充填技術（continuous wave compaction technique）與熱塑性馬來膠注射法（thermoplastic injection technique）之比較，下列敘述何者 錯誤？","options":["(A) 封填時工作長度的控制以側方封填法最佳","(B) 操作時造成牙齒牙根尖溫度的上升程度以熱塑性馬來膠注射法最高","(C) 操作時較容易造成牙根斷裂的為側方封填法","(D) 操作時馬來膠的流動程度以熱塑性馬來膠注射法最佳"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-2-12","subject":"ya3","topic":"根管器械","meta":"107年第2次第12題","year":107,"session":2,"number":12,"question":"造成根管鎳鈦旋轉器械分離的主要原因，下列何者影響最小？","options":["(A) 臨床醫師的操作經驗","(B) 複雜的根管解剖形態","(C) 器械製造的過程與品質","(D) 未使用專用的電動馬達"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-2-13","subject":"ya3","topic":"根管治療程序","meta":"107年第2次第13題","year":107,"session":2,"number":13,"question":"有關馬來膠針（gutta-percha point）敘述何者正確？","options":["(A) 馬來膠針受熱65℃以上，α形態（α form）之牙膠會融化（melt）","(B) 臨床使用之馬來膠針，馬來膠（gutta-percha）比例約占65%","(C) 馬來膠針受熱後自然冷卻再結晶形成α形態（α form）之馬來膠","(D) 近年來熱馬來膠針充填使用β形態（β form）之馬來膠漸漸增加"],"answer":0,"clinical_level":"重點"},{"id":"ya3-107-2-14","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第2次第14題","year":107,"session":2,"number":14,"question":"關於伴隨有急性牙根尖膿腫之牙髓壞死（pulp necrosis with acute apical abscess）的牙齒，若發現周圍組 織有腫脹的情形須施予緊急治療，則下列處置何者不適當？","options":["(A) 切開引流（I & D）","(B) 給與抗生素","(C) 根管開擴後，冠部不封閉（keep open）","(D) 使用氫氧化鈣[Ca(OH)2]當根管內用藥"],"answer":2,"clinical_level":"重點"},{"id":"ya3-107-2-15","subject":"ya3","topic":"根管治療程序","meta":"107年第2次第15題","year":107,"session":2,"number":15,"question":"關於根管沖洗液次氯酸鈉的敘述，下列何者錯誤？","options":["(A) 是目前臨床上最常被使用的根管沖洗液","(B) 能達到有效率抗菌能力的主因是其具有與氫氧化鈣類似的高酸鹼值","(C) 它對於壞死組織的溶解能力較佳，活髓組織則不具效果","(D) 具有中和蛋白質胺基酸的作用"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-2-16","subject":"ya3","topic":"根管治療程序","meta":"107年第2次第16題","year":107,"session":2,"number":16,"question":"在根管清潔和修形的過程中，造成根管阻塞的原因，下列敘述何者錯誤？","options":["(A) 使用過大尺寸或過硬的器械造成根管壁類似平台（ledge）的狀態","(B) 以冠部向下修形法（crown down technique）處理彎曲根管修形","(C) 器械斷折阻礙根管後，使得後續器械無法通過","(D) 先前根管充填的材料無法有效以現有溶劑移除"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-2-17","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第2次第17題","year":107,"session":2,"number":17,"question":"在進行上顎第一大臼齒根管治療過程中，顴骨突（zygomatic process）的影像常導致根尖片中牙根尖看不清 楚。利用cone-image shift的觀念，可以如何改變照射角度？","options":["(A) 改變照射錐（cone）之水平角度由近心往遠心照射，使影像中之顴骨突往近心方向移動","(B) 改變照射錐（cone）之水平角度由近心往遠心照射，使影像中之顴骨突往遠心方向移動","(C) 改變照射錐（cone）之水平角度由遠心往近心照射，使影像中之顴骨突往近心方向移動","(D) 改變照射錐（cone）之水平角度由遠心往近心照射，使影像中之顴骨突往遠心方向移動"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-2-18","subject":"ya3","topic":"牙周手術與再生","meta":"107年第2次第18題","year":107,"session":2,"number":18,"question":"下圖為右側上顎第一大臼齒手術前與手術後的X光片，則其所接受的治療術式為何？","options":["(A) 根尖切除術（apicoectomy）","(B) 半切斷術（hemisection）","(C) 牙根切斷術（root amputation）","(D) 蓄意再植術（intentional replantation）"],"answer":2,"image":"ya3-107-2-18.jpeg","clinical_level":"一般"},{"id":"ya3-107-2-19","subject":"ya3","topic":"根尖手術與再治療","meta":"107年第2次第19題","year":107,"session":2,"number":19,"question":"關於牙根尖手術逆向窩洞修形（retrograde cavity preparation）的敘述，下列何者錯誤？","options":["(A) 標準的逆向窩洞為平行牙齒長軸（long axis）的二級窩洞（class II cavity）","(B) 標準的逆向窩洞深度至少應有3 mm","(C) 若使用黏著性逆充填材料時，逆向窩洞須調整成淺扇貝形（shallow scalloped cavity）","(D) 使用有鑽石覆蓋（diamond-coated）的超音波器械進行逆向窩洞修形時，有較好的切削力"],"answer":0,"clinical_level":"一般"},{"id":"ya3-107-2-20","subject":"ya3","topic":"根尖手術與再治療","meta":"107年第2次第20題","year":107,"session":2,"number":20,"question":"關於上顎前牙根尖手術Ochsenbein-Luebke皮瓣設計的敘述，下列何者錯誤？","options":["(A) 切線可以分為垂直與水平兩個方向","(B) 上顎前牙垂直切線須避開上唇繫帶","(C) 手術切線要避免經過根尖病變骨缺損的正上方","(D) 手術後不會在牙齦上留下疤痕"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-2-21","subject":"ya3","topic":"根尖手術與再治療","meta":"107年第2次第21題","year":107,"session":2,"number":21,"question":"在根管重新治療過程中，常使用熱源或超音波器械移除根管內材料，其產生的熱可能會造成局部溫度上升。 當牙周韌帶（periodontal ligament）的溫度上升多少度時，即可能開始造成周圍附連組織（attachment apparatus）的傷害？","options":["(A) 5°C","(B) 10°C","(C) 20°C","(D) 30°C"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-2-22","subject":"ya3","topic":"根尖手術與再治療","meta":"107年第2次第22題","year":107,"session":2,"number":22,"question":"下列根管再治療（endodontic retreatment）的過程中用以移除馬來膠的溶劑（solvent），何者溶解效果最 差？","options":["(A) 甲基氯仿","(B) 桉油醇（eucalyptol）","(C) 氯仿","(D) 溴氯三氟乙烷（halothane）"],"answer":1,"clinical_level":"重點"},{"id":"ya3-107-2-23","subject":"ya3","topic":"窩洞設計與分類","meta":"107年第2次第23題","year":107,"session":2,"number":23,"question":"針對根管治療後的牙齒，若以局部贋復物（partial restorations）來做修復，下列幾種不同的局部贋復物，何 者能夠保留最多的齒質結構？","options":["(A) 複合樹脂填補（composite resin）","(B) 陶瓷貼片（veneer）","(C) 覆蓋式嵌體（overlay）","(D) 髓腔固位冠（endocrown）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-107-2-24","subject":"ya3","topic":"牙科解剖與生理","meta":"107年第2次第24題","year":107,"session":2,"number":24,"question":"使用三種抗生素糊劑（triple-antibiotics paste）進行牙根發育未成熟恆牙（immature permanent tooth）的根 管清潔與消毒時，須注意那一種抗生素會造成牙齒染色？","options":["(A) ciprofloxacin","(B) metronidazole","(C) minocycline","(D) clindamycin"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-2-25","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第2次第25題","year":107,"session":2,"number":25,"question":"10歲男童因左上顎小臼齒區腭側牙齦腫脹1週而來求診，臨床檢查發現第一小臼齒對冷刺激有感覺，但第二 小臼齒對冷刺激沒有反應，電髓活性檢查（electric pulp test）時小臼齒都有輕微的酸痛感，腭側觸診檢查時 兩顆小臼齒皆有明顯不適，敲診檢查發現第一小臼齒有輕微不適感，而第二小臼齒有明顯的敲痛症狀，患齒 的臨床影像紀錄與放射線學檢查結果如下圖所示。則下列診斷何者最有可能？","options":["(A) 第一小臼齒慢性根尖膿腫（chronic apical abscess）","(B) 第二小臼齒慢性根尖膿腫（chronic apical abscess）","(C) 第一小臼齒急性根尖膿腫（acute apical abscess）","(D) 第二小臼齒急性根尖膿腫（acute apical abscess）"],"answer":1,"image":"ya3-107-2-25.jpeg","clinical_level":"一般"},{"id":"ya3-107-2-26","subject":"ya3","topic":"窩洞設計與分類","meta":"107年第2次第26題","year":107,"session":2,"number":26,"question":"對於根管治療後的牙齒進行永久贋復物製作時，下列敘述何者錯誤？","options":["(A) 有2 mm冠部齒質以提供圍箍效應（ferrule effect）","(B) 根柱（post）在根尖區的寬度最多可達牙根寬度的一半","(C) 根柱（post）的深度應達到牙根長度的一半","(D) 根尖部根管需至少留有5 mm的馬來膠充填"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-2-27","subject":"ya3","topic":"複合樹脂與材料","meta":"107年第2次第27題","year":107,"session":2,"number":27,"question":"在複合樹脂與牙本質的剪力黏著測試（shear bond test）中，若斷裂面是位於複合樹脂中，則此斷裂模式為 何？","options":["(A) 黏著性斷裂（adhesive failure）","(B) 內聚性斷裂（cohesive failure）","(C) 壓力性斷裂（compressive failure）","(D) 張力性斷裂（tensile failure）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-2-28","subject":"ya3","topic":"複合樹脂與材料","meta":"107年第2次第28題","year":107,"session":2,"number":28,"question":"複合樹脂中所含之矽烷偶合劑（silane coupling agent）與樹脂，其物理性質的敘述，何者正確？","options":["(A) 會減少複合樹脂的強度","(B) 會增加複合樹脂的溶解度（solubility）","(C) 用以黏合樹脂基質（matrix）和填料（filler）","(D) 會增加樹脂的吸水性（water absorption）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-2-29","subject":"ya3","topic":"窩洞設計與分類","meta":"107年第2次第29題","year":107,"session":2,"number":29,"question":"汞齊復形物包括覆蓋牙尖（capping cusp）時，在功能性咬頭（functional cusp）的汞齊厚度至少要多少 mm？","options":["(A) 1.5","(B) 2.0","(C) 2.5","(D) 3.0"],"answer":1,"clinical_level":"重點"},{"id":"ya3-107-2-30","subject":"ya3","topic":"牙科解剖與生理","meta":"107年第2次第30題","year":107,"session":2,"number":30,"question":"老化導致的牙釉質改變，下列何者錯誤？","options":["(A) 色別（hue）會加強（intensified）","(B) 水含量減少","(C) 通透性（permeability）升高","(D) 孔洞（pore volume）的體積減少"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-2-31","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第2次第31題","year":107,"session":2,"number":31,"question":"某些牙齒在局部麻醉或電髓測試無反應的情況下仍有疼痛反應，其主要原因為下列何種神經纖維（fiber）被 刺激所導致？","options":["(A) A-δfiber","(B) B fiber","(C) C fiber","(D) parasympathetic nerve fiber（副交感神經纖維）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-2-32","subject":"ya3","topic":"牙科解剖與生理","meta":"107年第2次第32題","year":107,"session":2,"number":32,"question":"下列何者不是唾液促進齒質再礦化（remineralization）的因素？","options":["(A) 產生抗菌物質","(B) 清洗附著細菌","(C) 中和細菌代謝產物","(D) 降低口腔酸鹼值呈酸性"],"answer":3,"clinical_level":"重點"},{"id":"ya3-107-2-33","subject":"ya3","topic":"窩洞設計與分類","meta":"107年第2次第33題","year":107,"session":2,"number":33,"question":"攝取下列那種飲食後，齲齒發生率的增加機會最低？","options":["(A) 糖果","(B) 運動飲料","(C) 茶","(D) 果汁"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-2-34","subject":"ya3","topic":"黏著與美學修復","meta":"107年第2次第34題","year":107,"session":2,"number":34,"question":"下列何者不是全酸蝕式（total-etch）牙本質黏著劑中底劑（primer）的特性？","options":["(A) 其中樹脂單體同時具有親水性（hydrophilic）及疏水性（hydrophobic）的官能基","(B) 包覆住牙本質的膠原纖維（collagen fibrils）的外層，使其不易塌陷","(C) 移除塗抹層（smear layer）","(D) 調整牙本質表面自由能（surface free energy）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-2-35","subject":"ya3","topic":"黏著與美學修復","meta":"107年第2次第35題","year":107,"session":2,"number":35,"question":"有關自酸蝕式黏著劑（self - etching primer）的敘述，下列何者錯誤？","options":["(A) 可同時進行對牙本質酸蝕以及滲入底劑（priming）","(B) 減少鍵結表面過濕（overwetting）或過乾（overdrying）的可能性","(C) 移除全部的塗抹層（smear layer）","(D) 其酸性樹脂單體（acidic monomer）酸鹼值（pH）較磷酸高"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-2-36","subject":"ya3","topic":"根管治療程序","meta":"107年第2次第36題","year":107,"session":2,"number":36,"question":"下列那一種根管內沖洗液不會影響牙根的牙本質（root dentin）硬度？","options":["(A) 次氯酸鈉溶液（NaOCl）","(B) 雙氧水（H2O2）","(C) EDTA","(D) chlorhexidine gluconate"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-2-37","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第2次第37題","year":107,"session":2,"number":37,"question":"某病人因為上顎右側第一大臼齒區腫痛，且外觀發現右上臉部局部紅腫且有局部發熱，前來就醫。在治療計 畫的緊急階段（urgent phase）中，下列何者不是處理重點？","options":["(A) 解決病人疼痛問題","(B) 解決病人腫脹問題","(C) 詳細詢問病人全身系統性病史及現況","(D) 和病人討論植牙細節"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-2-38","subject":"ya3","topic":"牙周疾病與診斷","meta":"107年第2次第38題","year":107,"session":2,"number":38,"question":"下列敘述何者不是酸蝕（erosion）造成齒質缺損的特徵 ？","options":["(A) 去礦化物質引起的化學反應","(B) 檸檬汁引起的酸蝕，病灶呈圓盤狀","(C) 胃酸逆流引起的酸蝕，好發在舌側或咬合面","(D) 酸蝕病灶齒質，表面呈現粗糙不規則"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-2-39","subject":"ya3","topic":"窩洞設計與分類","meta":"107年第2次第39題","year":107,"session":2,"number":39,"question":"對於小窩及溝裂齲齒（pit and fissure caries），下列敘述何者錯誤？","options":["(A) 使用探針確認的精準度高","(B) 病灶齒質變得比較鬆軟","(C) 病灶牙齒的牙釉質失去透明光澤","(D) 小型溝裂齲齒建議以複合樹脂復形"],"answer":0,"clinical_level":"重點"},{"id":"ya3-107-2-40","subject":"ya3","topic":"牙體修形程序","meta":"107年第2次第40題","year":107,"session":2,"number":40,"question":"高速手機（high speed handpiece）搭配8刃（8 blades） 的鎢鋼鑽針（carbide bur），其臨床用途與下列何 種方式類似？","options":["(A) 高速手機搭配顆粒大小為88～125 µm（medium）的鑽石鑽針（diamond bur）","(B) 高速手機搭配顆粒大小為38～44 µm（very fine）的鑽石鑽針（diamond bur）","(C) 低速手機（low speed handpiece）搭配12刃（12 blades） 的鎢鋼鑽針（carbide bur）","(D) 手持式湯匙狀刮勺（spoon excavator）"],"answer":0,"clinical_level":"重點"},{"id":"ya3-107-2-41","subject":"ya3","topic":"牙體修形程序","meta":"107年第2次第41題","year":107,"session":2,"number":41,"question":"如下圖，用於移除多餘銀汞合金充填材料的手持器械（hand instrument）為何？","options":["(A) hoe","(B) gingival margin trimmer","(C) amalgam knife","(D) enamel hatchet"],"answer":2,"image":"ya3-107-2-41.jpeg","clinical_level":"一般"},{"id":"ya3-107-2-42","subject":"ya3","topic":"牙體修形程序","meta":"107年第2次第42題","year":107,"session":2,"number":42,"question":"關於復形治療防濕所用的橡皮障（rubber dam），下列敘述何者正確？","options":["(A) 在後牙復形時，只要打一個洞，暴露出欲復形的牙齒","(B) 欲隔離多顆牙齒時，將打的洞連在一起比較好","(C) 前牙復形時，建議隔離出兩側第一小臼齒間之所有前牙","(D) 若使用比較薄的橡皮障，則需要打大一點的洞"],"answer":2,"clinical_level":"重點"},{"id":"ya3-107-2-43","subject":"ya3","topic":"黏著與美學修復","meta":"107年第2次第43題","year":107,"session":2,"number":43,"question":"進行前牙修復之比色時，下列何者是避免條件等色（metamerism）發生之必要條件？","options":["(A) 請牙醫師與助理同時比色","(B) 比色時靠近窗邊","(C) 使用多種光源進行比色","(D) 凝視比色板比色"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-2-44","subject":"ya3","topic":"黏著與美學修復","meta":"107年第2次第44題","year":107,"session":2,"number":44,"question":"前牙複合樹脂填補時，對顏色的選擇，下列敘述何者錯誤？","options":["(A) 若複合樹脂填補厚度小於2.5mm，填補物的色澤易受下層齒質顏色影響","(B) 使用比色板（shade guide）應以明度（value）排列","(C) 大部分的比色板由壓克力樹脂（acrylic resins）製成，具有與複合樹脂相同的光學性質（optical properties）","(D) 最好的選色方式是根據每種複合樹脂做出專屬的比色板（custom shade tabs）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-2-45","subject":"ya3","topic":"複合樹脂與材料","meta":"107年第2次第45題","year":107,"session":2,"number":45,"question":"以玻璃離子黏合劑（glass ionomer cement）作為後牙複合樹脂填補的襯裡（liner）時，無法達到下列何種 目的？","options":["(A) 降低聚合光對牙髓造成的溫度升高","(B) 釋放氟以降低二次齲齒","(C) 降低樹脂填補後敏感之狀況","(D) 降低樹脂吸水率"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-2-46","subject":"ya3","topic":"窩洞設計與分類","meta":"107年第2次第46題","year":107,"session":2,"number":46,"question":"進行後牙複合樹脂第一類型窩洞製備時，若延伸至邊緣嵴（marginal ridge）時，應保留多少寬度的齒質？","options":["(A) 所有後牙皆應保留1.5 mm寬的齒質","(B) 所有後牙皆應保留2.0 mm寬的齒質","(C) 小臼齒應保留2.0 mm寬的齒質","(D) 大臼齒應保留2.0 mm寬的齒質"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-2-47","subject":"ya3","topic":"黏著與美學修復","meta":"107年第2次第47題","year":107,"session":2,"number":47,"question":"改善牙釉質發育不全（enamel hypoplasia）（如附圖）的美觀問題，下列治療計畫何者最恰當？","options":["(A) 輕微磨除（microabrasion）","(B) 深度磨除（macroabrasion）","(C) 活性漂白（vital bleaching）","(D) 陶瓷貼面（porcelain veneers）"],"answer":3,"image":"ya3-107-2-47.jpeg","clinical_level":"一般"},{"id":"ya3-107-2-48","subject":"ya3","topic":"黏著與美學修復","meta":"107年第2次第48題","year":107,"session":2,"number":48,"question":"利用假象（illusions）的方式可讓門牙的寬度及長度看起來與實際不同，下列敘述何者正確？","options":["(A) 牙齦輪廓高度（gingival height of contour）靠近牙齦（gingivally），可讓門牙看起來較短","(B) 垂直發育溝（vertical developmental depressions）較明顯，可讓門牙看起來較長","(C) 近遠心線角（mesial and distal line angles）相距較近，可讓門牙看起來較寬","(D) 發育溝（developmental depressions）相距較遠，可讓門牙看起來較窄"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-2-49","subject":"ya3","topic":"黏著與美學修復","meta":"107年第2次第49題","year":107,"session":2,"number":49,"question":"下列有關外在性變色（extrinsic discolorations）的敘述，何者錯誤？","options":["(A) 可由抽菸或食物造成","(B) 可能和remnants of Nasmyth's membrane有關","(C) 可能和牙齦流血有關","(D) 多在牙齒發育過程中造成"],"answer":3,"clinical_level":"重點"},{"id":"ya3-107-2-50","subject":"ya3","topic":"窩洞設計與分類","meta":"107年第2次第50題","year":107,"session":2,"number":50,"question":"有關陶瓷嵌體的敘述，下列何者正確？","options":["(A) 一定要用玻璃離子體（glass ionomer）製作襯底，不然會影響牙髓活性","(B) 咬合面的修磨厚度為1～1.5 mm","(C) 在咬合面及牙齦面的窩洞邊緣必須要有30度的斜面（bevel），才能有良好的邊緣密合度","(D) 所有邊緣應該是90度butt-joint窩緣面"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-2-51","subject":"ya3","topic":"窩洞設計與分類","meta":"107年第2次第51題","year":107,"session":2,"number":51,"question":"金屬嵌體（inlay）窩洞修形中的鴿尾形（dovetail）設計目的為何？","options":["(A) 減少齒質破壞","(B) 提供固位（retention）效果","(C) 提昇鄰近邊緣嵴（marginal ridge）強度","(D) 避免窩洞產生倒凹（undercut）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-2-52","subject":"ya3","topic":"牙體修形程序","meta":"107年第2次第52題","year":107,"session":2,"number":52,"question":"對於金屬冠蓋體（onlay）固定前所使用的臨時復形材料，不需具備何種特性？","options":["(A) 對牙齒刺激性低","(B) 可維持修形後牙齒的位置","(C) 提供咀嚼功能","(D) 與牙齒黏著力強"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-2-53","subject":"ya3","topic":"牙科解剖與生理","meta":"107年第2次第53題","year":107,"session":2,"number":53,"question":"對齒槽骨而言，trabecular bone是指下列何者？","options":["(A) Socket wall","(B) Buccal plate","(C) Lingual plate","(D) Between buccal plate and lingual plate"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-2-54","subject":"ya3","topic":"牙科解剖與生理","meta":"107年第2次第54題","year":107,"session":2,"number":54,"question":"有關次級牙骨質（secondary cementum）之敘述，下列何者錯誤？","options":["(A) 屬cellular cementum","(B) 在牙根apical third可見","(C) 發生於active eruption完成後","(D) 不含有原纖維間基質（interfibrillar matrix）與膠原原纖維（collagen fibrils）"],"answer":3,"clinical_level":"重點"},{"id":"ya3-107-2-55","subject":"ya3","topic":"牙科解剖與生理","meta":"107年第2次第55題","year":107,"session":2,"number":55,"question":"下列有關Langerhans cell之敘述，何者最正確？","options":["(A) 產生角質素（keratin）","(B) 它可感受壓力","(C) 它具有可呈現免疫抗原之特性","(D) 產生膠原蛋白（collagen）"],"answer":2,"clinical_level":"重點"},{"id":"ya3-107-2-56","subject":"ya3","topic":"牙周疾病與診斷","meta":"107年第2次第56題","year":107,"session":2,"number":56,"question":"51歲男性病患，在左下顎36,37的interdental area有9 mm牙周附連喪失，37有近心側傾斜，導致兩邊 marginal ridge高低不一，其最有可能導致附連喪失的因素為何？","options":["(A) 36, 37之角化牙齦不足","(B) 36有disto-lingual root","(C) 36 distal root有enamel projection","(D) 26有plunger cusp"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-2-57","subject":"ya3","topic":"牙周疾病與診斷","meta":"107年第2次第57題","year":107,"session":2,"number":57,"question":"牙齦下菌斑所形成之red complex牙周致病菌，均具有下列何種毒性因子可刺激macrophage產生IL-1β？","options":["(A) Leukotoxin","(B) Fimbrillin","(C) Gingipain","(D) Lipopolysaccharide"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-2-58","subject":"ya3","topic":"牙周疾病與診斷","meta":"107年第2次第58題","year":107,"session":2,"number":58,"question":"下列那類疾病與白血球缺陷無關？","options":["(A) Aggressive periodontitis","(B) Necrotizing periodontal diseases","(C) Leukocyte adhesion deficiency syndromes","(D) Endodontic-periodontal combined lesion"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-2-59","subject":"ya3","topic":"牙周疾病與診斷","meta":"107年第2次第59題","year":107,"session":2,"number":59,"question":"牙周病的免疫病理機轉，下列敘述何者錯誤？","options":["(A) 宿主防禦系統與細菌產生的牙菌斑間的平衡被破壞會造成牙周組織疾病","(B) 體液免疫反應特別是IgA和IgG在牙周病理過程中是保護性角色","(C) 細菌的產物會引起宿主細胞的生物免疫反應，而造成細胞激素的分泌，進而造成牙周組織的變化","(D) 最近研究顯示慢性牙周炎主要是由Th-1細胞所調控"],"answer":3,"clinical_level":"重點"},{"id":"ya3-107-2-60","subject":"ya3","topic":"牙周疾病與診斷","meta":"107年第2次第60題","year":107,"session":2,"number":60,"question":"以遺傳的角度來看牙周病，下列敘述何者錯誤？","options":["(A) 牙周炎是一種多因素的（multifactorial）疾病","(B) 牙周炎是由多項基因多型性變化和多項環境因素交互作用","(C) 罹患aggressive periodontitis者，有家族群聚（familial aggregation）的現象","(D) 台灣華人牙周炎的嚴重度與IL-1+3954的genotype有明顯關係"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-2-61","subject":"ya3","topic":"牙髓診斷與病理","meta":"107年第2次第61題","year":107,"session":2,"number":61,"question":"有關單顆牙齒危險因子評估（single tooth risk assessment），何者預後不屬於“irrational-to-treat”而不需在 第一期治療時拔除牙齒？","options":["(A) 牙根根尖侵犯","(B) 牙根縱向斷裂至根尖下1/3處","(C) 牙根分叉處齲齒延伸至根管或髓腔處","(D) 反覆性牙周膿腫和附連喪失至根尖處"],"answer":0,"clinical_level":"一般"},{"id":"ya3-107-2-62","subject":"ya3","topic":"牙科解剖與生理","meta":"107年第2次第62題","year":107,"session":2,"number":62,"question":"對於樹突狀細胞（dendritic cell）的敘述，下列何者錯誤？","options":["(A) Langerhans cells是一種位於squamous epithelium內的dendritic cells","(B) Dendritic cells消化抗原後，會將它傳送到淋巴結","(C) Peripheral dendritic cells是來自於myeloid stem cells的白血球","(D) Dendritic cells不會表現intercellular adhesion molecule-1（ICAM-1），但與antigen uptake and processing 有關"],"answer":3,"clinical_level":"重點"},{"id":"ya3-107-2-63","subject":"ya3","topic":"牙周疾病與診斷","meta":"107年第2次第63題","year":107,"session":2,"number":63,"question":"口腔內，用手指壓“甲處”牙齦有滲出液從牙齦溝流出，用手指壓“乙處”則否，則下列敘述何者最正確？","options":["(A) 甲處比乙處有較深牙周囊袋","(B) 甲處比乙處有較明顯急性發炎反應","(C) 甲處比乙處有較多牙齦下牙結石","(D) 甲處比乙處有較多的附連喪失"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-2-64","subject":"ya3","topic":"牙周疾病與診斷","meta":"107年第2次第64題","year":107,"session":2,"number":64,"question":"下列有關呼吸異味（breath malodor）之敘述，何者錯誤？","options":["(A) 研究指出Porphyromonas gingivalis, Prevotella intermedia可以製造H2S和methylmercaptan","(B) 當有深度囊袋存在時，呼吸異味與methylmercaptan／H2S的關係會增加","(C) 舌頭背面覆蓋物於牙周病患者為正常人的6倍","(D) 口乾症的病人較不易有口臭"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-2-65","subject":"ya3","topic":"牙周疾病與診斷","meta":"107年第2次第65題","year":107,"session":2,"number":65,"question":"牙周囊袋深度（pocket depth）是牙周病手術評估時非常重要的因素，但它仍然需要一些輔助因素，下列何 者不是它的輔助因素？","options":["(A) 牙周附連水平（clinical attachment level）","(B) 疼痛（pain）","(C) 滲出液（exudation）","(D) 牙齒形態（tooth morphology）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-2-66","subject":"ya3","topic":"牙周手術與再生","meta":"107年第2次第66題","year":107,"session":2,"number":66,"question":"適度的應用止血劑，對於牙周手術時造成的慢而持續的血液滲出有幫助，有關止血劑的使用敘述，下列何者 錯誤？","options":["(A) Gelfoam®吸收時間約4～6週","(B) 被氧化的纖維素（oxidized cellulose），不可以當表面敷料來使用","(C) Collaplug® 可能會引起過敏反應","(D) Thrombin直接注射組織中，可加強止血效果"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-2-67","subject":"ya3","topic":"牙周手術與再生","meta":"107年第2次第67題","year":107,"session":2,"number":67,"question":"有關牙釉基質蛋白（enamel matrix protein）之敘述，下列何者錯誤？","options":["(A) 會促進新牙骨質形成","(B) 主要成分牙釉質形成素（amelogenins）會促進間葉細胞的附連","(C) 可以防止表皮細胞向牙根方向移動","(D) 適用於寬且喪失骨壁的骨內缺損"],"answer":3,"clinical_level":"重點"},{"id":"ya3-107-2-68","subject":"ya3","topic":"牙周手術與再生","meta":"107年第2次第68題","year":107,"session":2,"number":68,"question":"依1999年Cortellini等人研究發現，當齒間空間（interdental space）≦2 mm時，下列何者是骨內缺損再生手 術進入（surgical access）的較佳方式？","options":["(A) 簡化的乳突保存翻瓣術（simplified papilla preservation flap）","(B) 改良式乳突保存技術（modified papilla preservation techanique）","(C) 齒槽嵴切開（crestal incision）","(D) 內斜面切開（internal bevel incision）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-107-2-69","subject":"ya3","topic":"牙周手術與再生","meta":"107年第2次第69題","year":107,"session":2,"number":69,"question":"半齒槽中隔（hemiseptum）是屬於何種骨缺損？","options":["(A) 單壁骨","(B) 雙壁骨","(C) 三壁骨","(D) 複雜骨"],"answer":0,"clinical_level":"一般"},{"id":"ya3-107-2-70","subject":"ya3","topic":"牙周疾病與診斷","meta":"107年第2次第70題","year":107,"session":2,"number":70,"question":"下列有關牙齦退縮的敘述，何者錯誤？","options":["(A) 造成年輕人與老年人牙齦退縮的主要原因是牙周疾病","(B) 縱向研究指出預防牙齦退縮，牙齦高度不是一個重要因子","(C) 當牙齦退縮發生時將導致牙齦高度下降","(D) 醫源性（iatrogenic）因子也常跟牙齦退縮有關"],"answer":0,"clinical_level":"重點"},{"id":"ya3-107-2-71","subject":"ya3","topic":"牙周手術與再生","meta":"107年第2次第71題","year":107,"session":2,"number":71,"question":"關於牙周手術處理一般原則（general principles）的敘述，下列何者錯誤？","options":["(A) 手術中發生的暈厥（syncope），常因為恐懼及焦慮而引起","(B) 手術中患者臉色蒼白及流汗（perspiration）是焦慮或疼痛的反應","(C) 肺結核之患者可使用超音波洗牙機來潔牙","(D) 後、中腭區域（posterior and midpalatal regions）應避免做切線或翻瓣設計，以減少術中出血"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-2-72","subject":"ya3","topic":"牙周手術與再生","meta":"107年第2次第72題","year":107,"session":2,"number":72,"question":"牙周再生手術（periodontal regeneration）的翻瓣（flap）設計，下列敘述何者錯誤？","options":["(A) 可以使用乳突保存手術（papilla preservation technique）","(B) 最好做牙齦溝內切開（crevicular incision），形成牙周瓣膜（flap）","(C) 可以使用改良式魏德曼翻瓣術（modified Widman flap）的切法，切去1～2 mm的邊緣牙齦（marginal gingiva）","(D) 保留越多牙齦越好"],"answer":2,"clinical_level":"重點"},{"id":"ya3-107-2-73","subject":"ya3","topic":"牙周疾病與診斷","meta":"107年第2次第73題","year":107,"session":2,"number":73,"question":"病患回診檢查時發現某牙齒之搖動度增加，但探測深度及X光並無改變，也無探測出血狀况，最不可能導致 搖動度增加的原因為：","options":["(A) 咬合創傷","(B) 持續性牙齦發炎","(C) 磨牙","(D) 牙冠牙根比例不佳"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-2-74","subject":"ya3","topic":"牙周非手術治療","meta":"107年第2次第74題","year":107,"session":2,"number":74,"question":"就維護性治療而言，牙周病病患若有根叉侵犯（furcation involvement），複雜的補綴物（complicated prosthesis）及不良的牙冠牙根比時，其第一年內回診間隔（recall interval）最好為：","options":["(A) 1至2個月至少一次","(B) 3至4個月至少一次","(C) 6至12個月至少一次","(D) 有不舒服時才回診"],"answer":0,"clinical_level":"一般"},{"id":"ya3-107-2-75","subject":"ya3","topic":"牙科解剖與生理","meta":"107年第2次第75題","year":107,"session":2,"number":75,"question":"一位78歲骨質疏鬆症女性，在接受拔牙術後引發牙齦癒合不良與左上顎齒槽骨外露現象。經排除其他疾病及 病患長期服用藥物之病史，最相關之藥物為：","options":["(A) Ibuprofen","(B) Alendronate","(C) Teriparatide","(D) Nifidipine"],"answer":1,"clinical_level":"一般"},{"id":"ya3-107-2-76","subject":"ya3","topic":"牙科解剖與生理","meta":"107年第2次第76題","year":107,"session":2,"number":76,"question":"缺鐵性貧血患者呈現的紅血球特徵為何？","options":["(A) 小細胞，低色素性（microcytic, hypochromic）","(B) 大細胞，高色素性（macrocytic, hyperchromic）","(C) 小細胞，高色素性（microcytic, hyperchromic）","(D) 大細胞，低色素性（macrocytic, hypochromic）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-107-2-77","subject":"ya3","topic":"牙周手術與再生","meta":"107年第2次第77題","year":107,"session":2,"number":77,"question":"某病患為第一型糖尿病患，HbA1c數值顯示控制在6%，目前服藥控制中，無出現任何糖尿病之副作用或感 染，病患要接受牙周手術治療，則下列敘述何者正確？","options":["(A) 較一般牙周病患治療反應差，故術前要給予抗生素","(B) 較一般牙周病患治療反應差，但術前無須給予抗生素","(C) 與一般牙周病患治療反應相類似，但術前一定要給予抗生素","(D) 與一般牙周病患治療反應相類似，但術前之給予抗生素並非必要"],"answer":3,"clinical_level":"一般"},{"id":"ya3-107-2-78","subject":"ya3","topic":"植牙學","meta":"107年第2次第78題","year":107,"session":2,"number":78,"question":"根據Lang（1994年）狗的研究中顯示，以牙周探測具在健康的植體周圍組織做探測時，牙周探測具末端的位 置在何處？","options":["(A) 牙齦溝底部","(B) 連接上皮之冠部三分之一（coronal third of junctional epithelium）","(C) 連接上皮之根尖處（apical base of epithelium）","(D) 齒槽骨的表面"],"answer":2,"clinical_level":"一般"},{"id":"ya3-107-2-79","subject":"ya3","topic":"植牙學","meta":"107年第2次第79題","year":107,"session":2,"number":79,"question":"有關Botticelli等人（2004年）臨床研究評估拔牙後立即植牙後骨吸收量之敘述，下列何者正確？","options":["(A) 頰側骨寬度的吸收平均大於50%","(B) 舌側骨寬度的吸收平均大於50%","(C) 頰、舌側骨寬度的吸收平均皆小於10%","(D) 頰、舌側骨高度的吸收平均皆小於10%"],"answer":0,"clinical_level":"一般"},{"id":"ya3-107-2-80","subject":"ya3","topic":"植牙學","meta":"107年第2次第80題","year":107,"session":2,"number":80,"question":"種植單顆植體（直徑4 mm，長度13 mm）時，為避免傷害相鄰牙周組織，兩側鄰牙最少應相距多少mm？","options":["(A) 5","(B) 6","(C) 7","(D) 8"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-1-1","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第1次第1題","year":108,"session":1,"number":1,"question":"下列有關牙髓神經之敘述，何者錯誤？","options":["(A) 牙髓內的痛覺神經主要有⼆種，⼀種為A-δ神經纖維，另⼀種為C神經纖維","(B) A-δ神經纖維是不含髓鞘（unmyelinated sheath），傳導速度2～30m/sec比C神經纖維傳導速度慢","(C) A-δ神經纖維通常分布於牙本質和牙髓交界處（pulp-dentin junction），受刺激時傳導劇烈疼痛","(D) C神經纖維分布於⼤部分牙髓組織，受刺激時傳導鈍痛"],"answer":1,"clinical_level":"重點"},{"id":"ya3-108-1-2","subject":"ya3","topic":"根管器械","meta":"108年第1次第2題","year":108,"session":1,"number":2,"question":"根管治療使⽤橡⽪障（rubber dam）隔離的效果與影響不包括：","options":["(A) 減少⼝⽔滲漏","(B) 預防⼝鏡起霧","(C) 增加根管治療的總時間","(D) 減少病⼈交談與漱⼝"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-1-3","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第1次第3題","year":108,"session":1,"number":3,"question":"有關牙髓細胞的敘述何者錯誤？","options":["(A) 牙冠與牙根部的造牙本質細胞（odontoblast）都是柱狀（columnar）形態","(B) 纖維⺟細胞（fibroblast）是牙髓中主要細胞之⼀","(C) 牙髓中的未分化（undifferentiated）細胞主要分布在多細胞區（cell-rich zone）與⾎管周圍","(D) 造牙本質細胞（odontoblast）的活性愈強，細胞內的胞器⼀般來說亦較多"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-1-4","subject":"ya3","topic":"根管治療程序","meta":"108年第1次第4題","year":108,"session":1,"number":4,"question":"髓腔開擴（access cavity preparation）是根管治療中最先⾯對，也是最重要的⼀個動作，關於其基本原則與 步驟，下列敘述何者錯誤？","options":["(A) 必須移除⾜夠的齒質才能提供清楚的視野觀察到根管開⼝","(B) 年輕病⼈的牙髓腔較年⻑病⼈⼤，所以在髓腔開擴時要向外延展多⼀些","(C) 下顎⼤⾅齒應該由遠⼼⼩窩（distal pit）開始穿透，鑽針朝向遠⼼⽅向來進⾏髓腔開擴","(D) 上顎⼤⾅齒應該由近⼼⼩窩（mesial pit）中央開始穿透，鑽針朝向腭側⽅向來進⾏髓腔開擴"],"answer":2,"clinical_level":"重點"},{"id":"ya3-108-1-5","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第1次第5題","year":108,"session":1,"number":5,"question":"為何愈接近牙髓時，牙本質通透性愈⾼？","options":["(A) 牙本質⼩管直徑愈⼩","(B) 牙本質⼩管分布密度愈⾼","(C) 牙本質⼩管⻑度愈⻑","(D) 牙本質愈厚"],"answer":1,"clinical_level":"一般"},{"id":"ya3-108-1-6","subject":"ya3","topic":"醫學倫理與法規","meta":"108年第1次第6題","year":108,"session":1,"number":6,"question":"下列何者為正確之診斷步驟順序：①適當的了解病⼈全⾝及牙科的病史 ②主客觀的檢查及X光的檢查 ③ 傾聽病⼈的主訴 ④檢查資料的分析 ⑤有系統的診斷及適當的治療計畫","options":["(A) ①→②→③→④→⑤","(B) ②→③→①→④→⑤","(C) ③→①→②→④→⑤","(D) ①→③→②→④→⑤"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-1-7","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第1次第7題","year":108,"session":1,"number":7,"question":"50歲男性病患抱怨最近⼀個⽉咬食物時，左下顎⼤⾅齒會突然痛⼀下，偶爾也會對冰⽔敏感，牙齒X光檢查無 任何蛀牙或放射線透射病灶，敲診正常，牙周狀況亦無異常，在此狀況最有助益的檢查是那⼀項？","options":["(A) 電髓試驗","(B) 窩洞測試","(C) 光纖透照法","(D) ⿇醉注射法"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-1-8","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第1次第8題","year":108,"session":1,"number":8,"question":"牙髓的發炎狀況尚未超越根尖孔達到牙周韌帶前，病患通常不容易定位疼痛的齒源，最主要的原因為何？","options":["(A) 發炎牙髓有硬組織保護","(B) 牙周韌帶有充分的⾎液循環","(C) 牙髓含有疼痛感覺纖維（pain sensory fiber），但具較少量的本體感受纖維（proprioceptive sensory fiber）","(D) 牙周韌帶有本體感受纖維（proprioceptive sensory fiber）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-1-9","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第1次第9題","year":108,"session":1,"number":9,"question":"下列有關牙齒根尖病變的敘述，何者正確？","options":["(A) 為確定根管治療有效，要等到X光片上病變範圍完全癒合才可做根管充填","(B) 急性根尖牙周炎（acute apical periodontitis）主要的發炎細胞為巨噬細胞（macrophage）","(C) 不論其診斷為急性或慢性，做敲診檢查時（percussion），⼀定會有嚴重疼痛的情形","(D) 急性根尖牙周炎的牙齒，不⼀定有清楚的根尖放射線透射區（apical radiolucency）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-1-10","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第1次第10題","year":108,"session":1,"number":10,"question":"無症狀且齒質完整之下顎⾅齒，X光檢查發現，根尖有放射線透過性病灶，活性試驗為無反應，下列處置何 者最適宜？","options":["(A) 暫不處理，每3個⽉追蹤","(B) 局部⿇醉，進⾏根管治療","(C) 拍攝不同⾓度根尖X光片，確定病灶之原因","(D) 先製作暫時牙套保護"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-1-11","subject":"ya3","topic":"牙齒外傷處理","meta":"108年第1次第11題","year":108,"session":1,"number":11,"question":"複雜性牙冠斷裂（complicated crown fracture）侵犯牙釉質、牙本質及牙髓組織，其發⽣比率約為：","options":["(A) 0.9～13%","(B) 3.9～23%","(C) 10.9～33%","(D) 25.9～43%"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-1-12","subject":"ya3","topic":"牙齒外傷處理","meta":"108年第1次第12題","year":108,"session":1,"number":12,"question":"有關⽔平牙根斷裂（horizontal root fracuture）的敘述，下列何者正確？","options":["(A) ⼀定會造成牙髓壞死","(B) 斷裂牙根的根尖部分經常仍保有活性","(C) 根管治療須在7～10天內進⾏","(D) 由於任何位置的⽔平牙根斷裂，預後都非常不佳，通常會建議拔除"],"answer":1,"clinical_level":"重點"},{"id":"ya3-108-1-13","subject":"ya3","topic":"牙齒外傷處理","meta":"108年第1次第13題","year":108,"session":1,"number":13,"question":"影響脫槽齒（avulsed tooth）預後之最重要因素為何？","options":["(A) 齒槽部位之處理","(B) 根管治療開始的時間","(C) 牙根表⾯污染源之去除","(D) ⼝外時間之⻑短"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-1-14","subject":"ya3","topic":"牙齒外傷處理","meta":"108年第1次第14題","year":108,"session":1,"number":14,"question":"有關牙齒外傷性傷害（traumatic dental injury）之敘述，下列何者錯誤？","options":["(A) 壞死感染牙髓提供引起牙周發炎的刺激物，造成牙根發炎性外吸收（external inflammatory root resorption）","(B) 發炎牙髓組織伴隨牙根構造吸收，造成牙根發炎性內吸收（internal inflammatory root resorption）","(C) ⼝外時間⼩於60分鐘之封閉型根尖（closed apex）脫槽齒（avulsed tooth），應於7⾄10天內進⾏臨床根 管治療之⼯作","(D) ⼝外時間⼩於60分鐘之開放型根尖（open apex）脫槽齒（avulsed tooth），應於7⾄10天內進⾏臨床根管 治療之⼯作"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-1-15","subject":"ya3","topic":"根管治療程序","meta":"108年第1次第15題","year":108,"session":1,"number":15,"question":"根管充填材料牙膠針（gutta-percha）在充填之前，應如何消毒？","options":["(A) 不需消毒，直接充填","(B) 泡在75%酒精1分鐘，擦乾後充填","(C) 泡在⽣理食鹽⽔溶液1分鐘，以75%酒精擦拭後充填","(D) 泡在5%次氯酸鈉（NaOCl）溶液1分鐘，以75%酒精擦拭後充填"],"answer":3,"clinical_level":"重點"},{"id":"ya3-108-1-16","subject":"ya3","topic":"窩洞設計與分類","meta":"108年第1次第16題","year":108,"session":1,"number":16,"question":"有關根管治療後的牙齒其補綴修復的敘述，下列何者錯誤？","options":["(A) 根管治療後的前牙必須做假牙冠保護","(B) 若有咬合牙尖對合（occlusal intercuspation），根管治療後的後牙必須做假牙冠保護","(C) 做假牙冠的功⽤主要為防⽌牙齒冠部和根部的斷裂","(D) 下顎第⼀⼩⾅齒若其舌側咬頭（lingual cusp）⼩且沒有咬合牙尖對合（occlusal intercuspation），可以不 ⽤做假牙冠修復"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-1-17","subject":"ya3","topic":"根管治療程序","meta":"108年第1次第17題","year":108,"session":1,"number":17,"question":"下列何種沖洗液若不幸由根尖跑⾄牙根周圍組織（periradicular tissues）會造成氣腫（emphysema）？","options":["(A) 過氧化氫（hydrogen peroxide）","(B) 稀釋的優碘溶液（diluted β-iodine solution）","(C) ⽣理食鹽⽔（normal saline）","(D) ⼄醇（alcohol）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-1-18","subject":"ya3","topic":"根管治療程序","meta":"108年第1次第18題","year":108,"session":1,"number":18,"question":"有關根管內消毒材料之敘述，何者錯誤？","options":["(A) 蛋⽩質分解（proteolytic）之沖洗液中最常使⽤的是NaOCl","(B) NaOCl可經由增加溫度提⾼組織溶解效果及滅菌能⼒","(C) 氫氧化鈣糊劑之調拌應愈稀愈好","(D) 氫氧化鈣糊劑應充填⾄根管操作⻑度較能發揮最⼤療效"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-1-19","subject":"ya3","topic":"根管治療程序","meta":"108年第1次第19題","year":108,"session":1,"number":19,"question":"有關牙根根尖區域的敘述，下列何者錯誤？","options":["(A) 根尖孔（apical foramen）通常不會在牙根最尖端（true apex）的位置","(B) 根尖狹窄（apical constriction）是根管治療清潔，修形與充填的終點","(C) 根尖狹窄（apical constriction）不易由臨床判斷，根尖孔（apical foramen）位置則⼤多可由X光來判讀","(D) 根尖孔（apical foramen）形狀有可能為非圓形"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-1-20","subject":"ya3","topic":"根管治療程序","meta":"108年第1次第20題","year":108,"session":1,"number":20,"question":"在齒內治療時，發⽣齒頸部的根管穿孔，下列何者為修補穿孔的最佳時機？","options":["(A) 儘快處理","(B) 在根管擴⼤清創完成尚未充填時","(C) 在根管充填完成時","(D) 在充填完成後追蹤評估時"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-1-21","subject":"ya3","topic":"根尖手術與再治療","meta":"108年第1次第21題","year":108,"session":1,"number":21,"question":"有關牙髓⼿術的翻瓣設計，下列敘述何者較為正確？","options":["(A) ⽅形翻瓣（rectangular flap）適合⽤於多顆前牙同時進⾏的根尖⼿術","(B) ⼯作⻑度為30 mm的上顎⽝齒進⾏根尖⼿術應選擇三⾓形翻瓣（triangular flap）","(C) 牙根中段穿孔的矯正性⼿術（corrective surgery）適合使⽤半⽉形翻瓣（semilunar flap）","(D) 上顎⾅齒的根尖⼿術可使⽤Ochsenbein-Luebke翻瓣"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-1-22","subject":"ya3","topic":"根管治療程序","meta":"108年第1次第22題","year":108,"session":1,"number":22,"question":"下列何者非mineral trioxide aggregate（MTA）的主要成分？","options":["(A) aluminum oxide","(B) tricalcium silicate","(C) tricalcium aluminate","(D) tricalcium oxide"],"answer":0,"clinical_level":"重點"},{"id":"ya3-108-1-23","subject":"ya3","topic":"根管治療程序","meta":"108年第1次第23題","year":108,"session":1,"number":23,"question":"下列那⼀項是造成根管充填良好的牙齒，根尖放射線通透性病變持續存在最常⾒的原因？","options":["(A) 根管內根尖部位感染","(B) 根管外感染","(C) 根管充填物過度充填⾄根尖區引起異物反應","(D) 根尖囊腫"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-1-24","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第1次第24題","year":108,"session":1,"number":24,"question":"下列何者不是牙髓與牙周間可能相通的管道（channel）？","options":["(A) 牙本質⼩管（dentinal tubule）","(B) 腭齦溝（palatogingival groove）","(C) 齒中齒（dens invaginatus）","(D) 側根管（lateral canal）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-1-25","subject":"ya3","topic":"牙周疾病與診斷","meta":"108年第1次第25題","year":108,"session":1,"number":25,"question":"下列何種牙周炎，其感染源⾃於牙髓？","options":["(A) 牙壞死牙周炎（odontonecrosis periodontitis）","(B) 逆向牙周炎（retrograde periodontitis）","(C) 牙髓性牙周炎（pupal periodontitis）","(D) 邊緣性牙周炎（marginal periodontitis）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-108-1-26","subject":"ya3","topic":"醫學倫理與法規","meta":"108年第1次第26題","year":108,"session":1,"number":26,"question":"某醫師看診時，遇到社經地位較⾼的病患，總是特別⽤⼼親切，也優先排診治療。這位醫師違反何項倫理原 則？","options":["(A) 公平正義原則","(B) ⾏善原則","(C) 不傷害原則","(D) ⾃主原則"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-1-27","subject":"ya3","topic":"牙科解剖與生理","meta":"108年第1次第27題","year":108,"session":1,"number":27,"question":"關於多結性牙釉質（gnarled enamel）的敘述，下列何者錯誤？","options":["(A) 由相鄰的牙釉柱（enamel rods）相互纏繞在⼀起所組成","(B) 接近牙齒表⾯呈現不規則排列的彎曲路徑","(C) 比規則排列之牙釉柱（enamel rods）容易斷裂","(D) 通常會出現在齒頸部、切端處或咬合區域"],"answer":2,"clinical_level":"重點"},{"id":"ya3-108-1-28","subject":"ya3","topic":"牙科解剖與生理","meta":"108年第1次第28題","year":108,"session":1,"number":28,"question":"關於牙釉質再礦化（remineralization）與氟化物之相關性，下列敘述何者錯誤？","options":["(A) 牙釉質可吸附來⾃飲⽔中的氟化物","(B) 牙釉質可吸收⽣物層（biofilm）上的氟化物","(C) 氟化物可加速牙菌斑造成的脫鈣作⽤","(D) 含氟的氫氧磷灰⽯（fluorohydroxyapatite）較能對抗脫鈣"],"answer":2,"clinical_level":"重點"},{"id":"ya3-108-1-29","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第1次第29題","year":108,"session":1,"number":29,"question":"下列何者非猛爆性齲齒（rampant caries）？","options":["(A) 奶瓶性齲齒（baby bottle caries）","(B) 繼發性齲齒（secondary caries）","(C) 放射線治療後齲齒（radiation therapy caries）","(D) 甲基安非他命性齲齒（meth-mouth caries）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-108-1-30","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第1次第30題","year":108,"session":1,"number":30,"question":"齲齒（caries）的發⽣與下列何種菌種最不相關？","options":["(A) Streptococcus mutans","(B) Lactobacillus","(C) Staphylococcus","(D) Actinomyces"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-1-31","subject":"ya3","topic":"牙科解剖與生理","meta":"108年第1次第31題","year":108,"session":1,"number":31,"question":"下列何者不是使牙齒再礦化的唾液組成成分？","options":["(A) IgA","(B) 磷酸鹽","(C) 鈣離⼦","(D) 富含脯氨酸（proline）之蛋⽩質"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-1-32","subject":"ya3","topic":"黏著與美學修復","meta":"108年第1次第32題","year":108,"session":1,"number":32,"question":"在（a）牙髓端及（b）牙本質-牙釉質交接處的牙本質⼩管，分別佔牙本質表⾯積的百分比為多少？","options":["(A) （a）10% 、（b）22%","(B) （a）22%、（b）10%","(C) （a）2.2%、（b）1%","(D) （a）22%、（b）1%"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-1-33","subject":"ya3","topic":"牙科解剖與生理","meta":"108年第1次第33題","year":108,"session":1,"number":33,"question":"牙本質液（dentinal fluid）會因牙髓液壓（pulpal pressure）由牙髓處流向牙本質-牙釉質交接處，牙髓的液 壓值約為多少？","options":["(A) 34－40 mmHg","(B) 25－30 mmHg","(C) 15－20 mmHg","(D) 5－10 mmHg"],"answer":1,"clinical_level":"一般"},{"id":"ya3-108-1-34","subject":"ya3","topic":"牙體修形程序","meta":"108年第1次第34題","year":108,"session":1,"number":34,"question":"關於牙科⼿動器械改良握筆式抓握法（modified pen grasp）⽀撐（rest）⽅式的敘述，下列何者錯誤？","options":["(A) 與倒握筆式抓握法（inverted pen grasp）的⽀撐⼿指是相同的","(B) ⽀撐處為對側的牙⼸","(C) ⽀撐⼿指為無名指，也可加上⼩指","(D) ⽀撐處離治療區越近，穩定度越好"],"answer":1,"clinical_level":"一般"},{"id":"ya3-108-1-35","subject":"ya3","topic":"牙體修形程序","meta":"108年第1次第35題","year":108,"session":1,"number":35,"question":"關於美國牙醫協會（ADA）型號為169L（ISO 型號 009）的鎢鋼鑽針的敘述，下列何者錯誤？","options":["(A) 較 169 鎢鋼鑽針⻑","(B) 先端直徑（head diameter） 為0.90 mm","(C) 可⽤於製備固位溝（retention groove）","(D) 外形為平⾏裂溝（parallel fissure）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-1-36","subject":"ya3","topic":"窩洞設計與分類","meta":"108年第1次第36題","year":108,"session":1,"number":36,"question":"如圖所⽰，在近⼼-咬合窩洞製備（MO tooth preparation）中，下列何者不會與牙齦壁（gingival wall）相 連？","options":["(A) 頰側壁（buccal wall）","(B) 舌側壁（lingual wall）","(C) 軸壁（axial wall）","(D) 髓壁（pulpal wall）"],"answer":3,"image":"ya3-108-1-36.jpeg","clinical_level":"重點"},{"id":"ya3-108-1-37","subject":"ya3","topic":"複合樹脂與材料","meta":"108年第1次第37題","year":108,"session":1,"number":37,"question":"關於複合樹脂中填料（filler）的敍述，下列何者錯誤？","options":["(A) 填料顆粒愈⼤，樹脂聚合後，外部拋光的表⾯更為光滑","(B) 填料顆粒愈⼤，樹脂表⾯較容易沾染食物⾊素","(C) 填料顆粒愈⼤，光源照射時容易產⽣散射（scattering）","(D) 填料硬度較基質（matrix）⾼"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-1-38","subject":"ya3","topic":"牙體修形程序","meta":"108年第1次第38題","year":108,"session":1,"number":38,"question":"對於⼤部分的臨床情況⽽⾔，下列何者是填補牙根齲蝕（root caries）最適當的材料？","options":["(A) 玻璃離⼦體黏合劑","(B) 複合樹脂","(C) 汞⿑","(D) 氧化鋅丁香油酚黏合劑"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-1-39","subject":"ya3","topic":"複合樹脂與材料","meta":"108年第1次第39題","year":108,"session":1,"number":39,"question":"關於樹脂填補使⽤分層術式（incremental technique）的優點之敘述， 下列何者錯誤？","options":["(A) 增加與窩洞的鍵結強度","(B) 避免複合樹脂聚合不完全","(C) 減少對牙齒產⽣的變形","(D) 減少整個樹脂填補物的內在氣泡"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-1-40","subject":"ya3","topic":"黏著與美學修復","meta":"108年第1次第40題","year":108,"session":1,"number":40,"question":"關於前牙複合樹脂鑲⾯（veneer）復形的操作過程，下列敘述何者正確？","options":["(A) 應先清除表⾯污漬後，等待牙齒完全乾燥後再進⾏比⾊，避免⽔氣的誤差","(B) 如要增加⾃然外觀，切端可使⽤不透光樹脂（opaquer）填補","(C) 如要遮蓋變⾊齒質，可使⽤著⾊劑（tint）","(D) 填補後，可使⽤ No.12 ⼑片將鄰接⾯多餘的樹脂移除"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-1-41","subject":"ya3","topic":"複合樹脂與材料","meta":"108年第1次第41題","year":108,"session":1,"number":41,"question":"在進⾏前牙複合樹脂三級窩洞製備時，下列敘述何者正確？","options":["(A) 不需要製備額外的固位型（retention form）","(B) 無⽀持的唇側牙釉齒（unsupported labial enamel）須移除","(C) 窩洞主要的固位（retention）來⾃於腭側斜⾯","(D) 使⽤鎢鋼鑽針（carbide bur）較鑽⽯鑽針（diamond bur）進⾏窩洞的製備，可以得到較好的微機械固位 （micromechanical retention）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-1-42","subject":"ya3","topic":"複合樹脂與材料","meta":"108年第1次第42題","year":108,"session":1,"number":42,"question":"關於複合樹脂聚合時產⽣收縮的敘述，下列何者錯誤？","options":["(A) 使⽤ soft-start 光照可減少收縮應⼒","(B) 可使⽤基底為Silorane 的樹脂減少收縮應⼒","(C) 使⽤ RMGI 或流動樹脂作襯底（liner）可減少收縮應⼒","(D) 使⽤流動樹脂來填補可減少收縮量"],"answer":3,"clinical_level":"重點"},{"id":"ya3-108-1-43","subject":"ya3","topic":"窩洞設計與分類","meta":"108年第1次第43題","year":108,"session":1,"number":43,"question":"複合樹脂填補時，窩洞設計中斜⾯（bevel）的敘述，下列何者錯誤？","options":["(A) 斜⾯可增加複合樹脂和牙齒的鍵結強度","(B) 斜⾯只能設計在牙釉質","(C) 正中⾨牙的舌側⾯都要有斜⾯設計","(D) 後牙咬合⾯不需有斜⾯設計"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-1-44","subject":"ya3","topic":"複合樹脂與材料","meta":"108年第1次第44題","year":108,"session":1,"number":44,"question":"為了降低汞⿑填補後產⽣的脆弱 gamma 2 產物，故增加成份中何者的含量？","options":["(A) 銅","(B) 錫","(C) 鋅","(D) 銀"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-1-45","subject":"ya3","topic":"窩洞設計與分類","meta":"108年第1次第45題","year":108,"session":1,"number":45,"question":"以汞⿑填補五級（Class V）窩洞時，下列何者最適⽤於增加固位（retention）？","options":["(A) 製備 retention coves","(B) 使⽤ pin","(C) 利⽤ amalgam bonding","(D) 製備 bevel"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-1-46","subject":"ya3","topic":"複合樹脂與材料","meta":"108年第1次第46題","year":108,"session":1,"number":46,"question":"根據圖中粒⼦來分類，應為何種汞⿑合⾦？","options":["(A) 球型（spherical）","(B) 切削型（lathe-cut）","(C) 混合型（admixed）","(D) 單⼀組成 （unicompositional alloys）"],"answer":2,"image":"ya3-108-1-46.jpeg","clinical_level":"一般"},{"id":"ya3-108-1-47","subject":"ya3","topic":"窩洞設計與分類","meta":"108年第1次第47題","year":108,"session":1,"number":47,"question":"以⾦屬嵌體修復時，下列何者不是製備斜⾯（bevel）的好處？","options":["(A) 可以增加抗⼒形（resistance form）","(B) 完成時容易研光（burnish）","(C) 增加牙齒與嵌體的接觸⾯積","(D) 斜⾯⼩於 45 度之黏合劑薄膜厚度（film thickness）比無斜⾯更⼩"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-1-48","subject":"ya3","topic":"窩洞設計與分類","meta":"108年第1次第48題","year":108,"session":1,"number":48,"question":"如圖，關於上顎⼩⾅齒⾦屬冠蓋體頰側製備咬合渠（occlusal channel），下列敘述何者錯誤？","options":["(A) 增加⾦屬冠蓋體厚度","(B) 避免⾦屬冠蓋體往頰側脫出","(C) 增加⾦屬冠蓋體強度","(D) 減少⾦屬冠蓋體變形"],"answer":1,"image":"ya3-108-1-48.jpeg","clinical_level":"一般"},{"id":"ya3-108-1-49","subject":"ya3","topic":"複合樹脂與材料","meta":"108年第1次第49題","year":108,"session":1,"number":49,"question":"有關⽩榴⽯強化陶瓷（leucite-reinforced ceramic）和⼆矽酸鋰陶瓷（lithium disilicate ceramic）的比較，何 者正確？","options":["(A) 兩者都只能利⽤加熱壓鑄式（heat pressed）⽅式製作陶瓷復形物","(B) ⽩榴⽯強化陶瓷表⾯硬度（surface hardness）和牙釉質相近","(C) 兩者都不能⽤於製作全瓷冠","(D) ⽩榴⽯強化陶瓷的強度（strength）⾼於⼆矽酸鋰陶瓷"],"answer":1,"clinical_level":"一般"},{"id":"ya3-108-1-50","subject":"ya3","topic":"黏著與美學修復","meta":"108年第1次第50題","year":108,"session":1,"number":50,"question":"關於牙齒漂⽩術後造成牙齒敏感的敘述，下列何者錯誤？","options":["(A) 過氧化物（peroxide）只需 5～15 分鐘就可穿透牙齒到達牙髓組織","(B) 在漂⽩過程中若發⽣敏感，不可塗氟以免影響漂⽩效果","(C) 通常術後敏感可恢復","(D) 3～5％ 硝酸鉀（potassium nitrate）可直接穿透牙齒到達牙髓組織，達到鎮定神經的效果"],"answer":1,"clinical_level":"一般"},{"id":"ya3-108-1-51","subject":"ya3","topic":"牙周疾病與診斷","meta":"108年第1次第51題","year":108,"session":1,"number":51,"question":"下列何者不是導致 diastema 的原因？","options":["(A) 病理性位移（pathological migration）","(B) 吞嚥習慣不良（tongue thrusting）","(C) 較⼤的 curve of Spee","(D) 後牙缺失"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-1-52","subject":"ya3","topic":"黏著與美學修復","meta":"108年第1次第52題","year":108,"session":1,"number":52,"question":"10% 碳酸醯胺過氧化物（carbamide peroxide），當其適度分解後，相對約含有多少 % 之過氧化氫 （hydrogen peroxide）？","options":["(A) 1%","(B) 3%","(C) 5%","(D) 7%"],"answer":1,"clinical_level":"重點"},{"id":"ya3-108-1-53","subject":"ya3","topic":"牙科解剖與生理","meta":"108年第1次第53題","year":108,"session":1,"number":53,"question":"在牙骨質形成過程中，接續赫威⽒上⽪鞘（Hertwig's epithelial sheath）退化的下⼀步驟為下列何者？","options":["(A) 牙本質鈣化","(B) 造牙本質細胞（odontoblasts）的分化","(C) 造牙骨質細胞（cementoblasts）的分化","(D) 齒濾泡間質細胞（dental follicle mesenchymal cells ）與牙本質的接觸"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-1-54","subject":"ya3","topic":"牙科解剖與生理","meta":"108年第1次第54題","year":108,"session":1,"number":54,"question":"關於牙齦上⽪細胞結構的敘述，下列何者錯誤？","options":["(A) ⿊⾊素細胞屬於樹狀突細胞，分佈在牙齦上⽪的基底層及顆粒層","(B) 蘭格罕⽒細胞（Langerhans cells），含有g-特殊顆粒（g-specific granules）","(C) 麥克⽒細胞（Merkel cells）與觸覺的感覺有相關","(D) 上⽪細胞的基底板，其成分中硬骨板（lamina densa），由第四型的膠原蛋⽩所組成"],"answer":0,"clinical_level":"重點"},{"id":"ya3-108-1-55","subject":"ya3","topic":"牙科解剖與生理","meta":"108年第1次第55題","year":108,"session":1,"number":55,"question":"關於牙齒萌出的敘述，下列何者錯誤？","options":["(A) 主動萌出（active eruption），是指牙齒的萌出是朝著牙齒的咬合⾯⽅向進⾏","(B) 當牙齒與它的功能性對咬牙接觸時，臨床牙冠⻑度⼤約是解剖牙冠的1/3","(C) 理想狀況下，牙齒的萌出速度能配合牙齒磨耗，以維持牙齒的垂直距離","(D) 牙齒萌出過程中，連接上⽪的尾端與齒槽脊的距離⼀直穩定的維持在1.07 mm左右"],"answer":1,"clinical_level":"重點(深度)"},{"id":"ya3-108-1-56","subject":"ya3","topic":"牙科解剖與生理","meta":"108年第1次第56題","year":108,"session":1,"number":56,"question":"下列位於牙齦結締組織的神經構造，何者扮演溫度感受器的⾓⾊？","options":["(A) terminal argyrophil fibers","(B) Meissner-type corpuscles","(C) Krause-type end bulbs","(D) treelike configuration free nerve endings"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-1-57","subject":"ya3","topic":"牙周疾病與診斷","meta":"108年第1次第57題","year":108,"session":1,"number":57,"question":"關於抽菸與牙周炎的關係，下列敘述何者正確？","options":["(A) 牙菌斑形成速度比非抽菸者要快","(B) 牙齦下的牙菌斑細菌存在著⼤量的A. actinomycetemcomitans、T. forsythia 及 P. gingivalis","(C) 其多形核嗜中性⽩⾎球（PMNs）的chemotaxis及migration功能是健全的","(D) 與非抽菸者在探測後牙齦出⾎（BoP）的百分比是相同的"],"answer":1,"clinical_level":"重點"},{"id":"ya3-108-1-58","subject":"ya3","topic":"牙周疾病與診斷","meta":"108年第1次第58題","year":108,"session":1,"number":58,"question":"依據Page & Schroeder（1976年）的分期，關於established lesion的敘述，下列何者正確？","options":["(A) 主要的細胞以PMNs為主","(B) PMNs會穿過pocket epithelium，於組織與biofilm之間形成⼀道防線","(C) 在臨床上可確診為牙周炎","(D) 牙周韌帶與齒槽骨都有發炎"],"answer":1,"clinical_level":"重點"},{"id":"ya3-108-1-59","subject":"ya3","topic":"牙周疾病與診斷","meta":"108年第1次第59題","year":108,"session":1,"number":59,"question":"下列表格為某患者之基本牙周篩選系統（basic periodontal examination）的檢查紀錄，則針對該患者治療之 敘述，何者正確？","options":["(A) 只治療蛀牙即可","(B) 其缺牙區可直接進⾏贋復重建","(C) 此⼀患者必須進⾏更詳細的全⼝牙周檢查以確定牙周狀況及治療","(D) ⼝腔衛⽣教育與牙結⽯清除及牙根整平術即可改善其狀況"],"answer":2,"image":"ya3-108-1-59.jpeg","clinical_level":"一般"},{"id":"ya3-108-1-60","subject":"ya3","topic":"牙周疾病與診斷","meta":"108年第1次第60題","year":108,"session":1,"number":60,"question":"關於局部型侵襲性牙周炎的特徵，下列敘述何者正確？","options":["(A) Socransky 1998的red complex species細菌是主要的致病菌","(B) 病患發病年齡在30歲以上","(C) 對致病菌⾎清抗體反應強烈","(D) 除⾨牙及第⼀⼤⾅齒外更增加三顆牙齒有牙周附連喪失及牙周骨破壞"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-1-61","subject":"ya3","topic":"牙周疾病與診斷","meta":"108年第1次第61題","year":108,"session":1,"number":61,"question":"依骨下缺損（infrabony defect）分類，兩牙齒鄰間頰舌側仍有骨壁，⽽中間骨缺損已侵犯到兩牙齒牙根，其 分類為下列何者？","options":["(A) 單壁（one-wall）骨內缺損","(B) 雙壁（two-wall）骨內缺損","(C) 三壁（three-wall）骨內缺損","(D) 鄰間陷⼝（interproximal crater）缺損"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-1-62","subject":"ya3","topic":"牙周疾病與診斷","meta":"108年第1次第62題","year":108,"session":1,"number":62,"question":"關於壞死潰瘍性牙齦炎（necrotizing ulcerative gingivitis）和原發性疱疹⼝齦炎（primary herpetic gingivostomatitis）兩者疾病的敘述，下列何者錯誤？","options":["(A) 原發性疱疹齦⼝炎是⼀種傳染性（communicable）急性牙齦感染","(B) 壞死潰瘍性牙齦炎在已開發國家較不常發⽣於孩童⾝上","(C) 原發性疱疹齦⼝炎⼀般病情是7到10天","(D) 壞死潰瘍性牙齦炎若使⽤清創（debridement）⽅式將會加劇病情"],"answer":3,"clinical_level":"重點"},{"id":"ya3-108-1-63","subject":"ya3","topic":"牙周疾病與診斷","meta":"108年第1次第63題","year":108,"session":1,"number":63,"question":"咬合創傷與牙周炎關係的敘述，下列何者錯誤？","options":["(A) 動物實驗說明單純的咬合創傷不但會引起齒槽骨、牙周膜和牙骨質的改變，也會影響牙齦組織","(B) 當牙周組織先已有牙菌斑引起的牙周炎時，咬合創傷便會起偕同破壞作⽤（co-destruction）","(C) ⾃限性牙鬆動在沒有牙齦炎症的情況下，不造成牙周組織的破壞","(D) 在矯正治療前必須先治療已有的牙周病"],"answer":0,"clinical_level":"重點"},{"id":"ya3-108-1-64","subject":"ya3","topic":"牙周非手術治療","meta":"108年第1次第64題","year":108,"session":1,"number":64,"question":"關於雷射在牙周病基本治療的應⽤，下列敘述何者正確？","options":["(A) Nd：YAG lasers 具有偵測、回饋與有效去除牙結⽯的功能","(B) Er：YAG lasers有殺菌作⽤，可以取代傳統的SRP therapy","(C) 光動⼒療法所使⽤的光敏感劑都是crystal violet","(D) Photodynamic therapy 所⽤的的雷射機種是diode lasers"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-1-65","subject":"ya3","topic":"牙周非手術治療","meta":"108年第1次第65題","year":108,"session":1,"number":65,"question":"關於牙周刮匙（curettes）的敘述，下列何者正確？","options":["(A) Gracey curettes 的lower shank與牙根表⾯夾⾓⾓度呈80°時清潔效率最佳","(B) 刃切緣（cutting edge）與牙根表⾯夾⾓⾓度呈60°時，易造成軟組織傷害","(C) curettes 器械磨利（sharpening）時，須維持刃切緣（cutting edge）結構⾓度呈70°較佳","(D) Gracey curettes刃（blade）的face與lower shank結構夾⾓⾓度呈90°"],"answer":2,"clinical_level":"重點"},{"id":"ya3-108-1-66","subject":"ya3","topic":"牙周手術與再生","meta":"108年第1次第66題","year":108,"session":1,"number":66,"question":"使⽤Emdogain治療齒槽脊上骨缺損（supracrestal defect）伴隨有淺之垂直缺損（vertical defect）區域時， 下列何種材料／術式不建議併⽤？","options":["(A) 牙周再⽣膜","(B) 骨移植材料","(C) 冠向移前翻瓣⼿術（coronally advanced flap）","(D) 骨切除術（resective osseous surgery）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-1-67","subject":"ya3","topic":"植牙學","meta":"108年第1次第67題","year":108,"session":1,"number":67,"question":"下列何者不是取⽤⾃體骨之常⽤器械？","options":["(A) 骨膜剝離器（periosteum elevator）","(B) 碳鋼磨針（carbide bur）","(C) 骨鑿（back-action chisel）","(D) 環鋸（trephine）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-1-68","subject":"ya3","topic":"牙周手術與再生","meta":"108年第1次第68題","year":108,"session":1,"number":68,"question":"關於牙周敷料的敘述，下列何者正確？","options":["(A) 可與含抗菌藥物之粉末或凝膠並⽤以加強效果","(B) ⽬前最常使⽤的是Coe-Pak，但須留意不可⽤於對eugenol過敏的病患","(C) 主要的功能在於促進術後⽌⾎，但無⽌痛效果","(D) 依據傷⼝復原之進程，建議牙周敷料應置放兩週後移除"],"answer":0,"clinical_level":"重點"},{"id":"ya3-108-1-69","subject":"ya3","topic":"牙周手術與再生","meta":"108年第1次第69題","year":108,"session":1,"number":69,"question":"關於骨移植⼿術（grafting technique）的敘述，下列何者錯誤？","options":["(A) 需徹底做術前潔牙","(B) 不需要做咬合調整","(C) 牙齦乳突保存翻瓣術是最適當的⼿術⽅式","(D) 術後通常需要服⽤抗⽣素"],"answer":1,"clinical_level":"一般"},{"id":"ya3-108-1-70","subject":"ya3","topic":"牙周手術與再生","meta":"108年第1次第70題","year":108,"session":1,"number":70,"question":"Initial Miller class I-II recession defects，經施⾏coronally advanced flaps的術式後，可獲得約多少的牙根覆 蓋？","options":["(A) 10 %","(B) 30 %","(C) 70 %","(D) 90 %"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-1-71","subject":"ya3","topic":"牙周手術與再生","meta":"108年第1次第71題","year":108,"session":1,"number":71,"question":"關於牙周再⽣⼿術⻑期預後之敘述，下列何者錯誤？","options":["(A) 牙周再⽣區域的穩定性與病⼈是否定期回診以及⼝腔清潔狀況非常有關","(B) 根據⻑期追蹤的結果，經牙周再⽣的組織較⾃然的牙周組織易產⽣牙周炎","(C) 吸菸為影響再⽣穩定度、造成牙周炎復發之危險因⼦之⼀","(D) 若確實執⾏牙周⽀持治療及居家照顧，⼆級根叉侵犯之牙經再⽣治療後亦能有⻑期穩定的預後"],"answer":1,"clinical_level":"一般"},{"id":"ya3-108-1-72","subject":"ya3","topic":"牙周手術與再生","meta":"108年第1次第72題","year":108,"session":1,"number":72,"question":"具gummy smile且thick gingival phenotype和齒槽嵴有bony ledge，考量美觀的情況下，最理想的術式為下 列何者？","options":["(A) 乳頭保存翻瓣術（papilla preserve flap）","(B) 根向移位翻瓣術（apically displaced flap）","(C) 改良式魏徳曼翻瓣術（modified Widman flap）","(D) 牙齦切除術（gingivectomy）"],"answer":0,"clinical_level":"重點"},{"id":"ya3-108-1-73","subject":"ya3","topic":"牙周疾病與診斷","meta":"108年第1次第73題","year":108,"session":1,"number":73,"question":"關於Functional diagram（Lang and Tonetti, 2003）牙周危險評估的敘述，下列何者錯誤？","options":["(A) BoP介於20%與30%時，決定患者的牙周病的進展為higher risk","(B) 殘餘PPD＞ 4 mm本⾝不具有單獨評估因⼦的價值","(C) 如果有超過8顆牙齒喪失可被考慮為high risk","(D) 使⽤「BL%／age」評估牙周病危險度，積極治療前比治療後（SPT）更正確"],"answer":3,"clinical_level":"重點"},{"id":"ya3-108-1-74","subject":"ya3","topic":"牙周疾病與診斷","meta":"108年第1次第74題","year":108,"session":1,"number":74,"question":"上顎第⼀⼩⾅齒由於下列何種特殊牙齒型態，⽽不利於牙周之維護？","options":["(A) ⾼繫帶附著（frenum attachment）","(B) 發育溝（developmental groove）","(C) 牙釉質突（enamel projection）","(D) 牙根凹陷（root concavity）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-1-75","subject":"ya3","topic":"牙科解剖與生理","meta":"108年第1次第75題","year":108,"session":1,"number":75,"question":"對於腎臟疾病患者的牙周治療準則，下列何種敘述最為正確？","options":["(A) 已會診內科醫師的患者不需再監控其凝⾎時間、出⾎時間及⾎⼩板數量","(B) 不建議給予acetaminophen及diazepam等藥物","(C) 進⾏⾎液透析治療的腎臟疾病患者，建議在⾎液透析當天進⾏牙周病治療","(D) 進⾏間歇性腹膜透析（intermittent peritoneal dialysis）治療的腎臟疾病患者，通常不需在牙科治療前給予 預防性抗⽣素"],"answer":3,"clinical_level":"重點"},{"id":"ya3-108-1-76","subject":"ya3","topic":"牙周非手術治療","meta":"108年第1次第76題","year":108,"session":1,"number":76,"question":"關於糖尿病患者在進⾏牙周病治療時的敘述，下列何者最為正確？","options":["(A) 主要監測糖尿病控制狀況的檢驗⽅式為空腹⾎糖值（fasting blood glucose）及隨機⾎糖值（casual glucose）","(B) 空腹⾎糖值（fasting blood glucose）可以監測患者兩、三個⽉內的⾎糖控制狀況","(C) ⼀般⽽⾔，對於HbA1c控制在8%以下的患者，牙周病的治療計畫與常⼈無異","(D) 只要患者有按時服藥，皆可以安排牙周病⼿術"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-1-77","subject":"ya3","topic":"牙科解剖與生理","meta":"108年第1次第77題","year":108,"session":1,"number":77,"question":"關於C-反應蛋⽩（C-reactive protein, CRP）的敘述，下列何者錯誤？","options":["(A) ⾎清CRP上升和纖維蛋⽩升⾼是⼼⾎管疾病的公認危險因⼦","(B) ⼼臟的炎症或傳染性刺激可使⼼臟產⽣急性期蛋⽩如CRP和纖維蛋⽩，並且可作為炎症標記","(C) CRP誘導單核細胞和巨噬細胞產⽣組織因⼦，刺激凝⾎通路，增加⾎液凝固","(D) 與無牙周炎的患者相比，牙周炎患者⾎清CRP和纖維蛋⽩濃度經常升⾼"],"answer":1,"clinical_level":"一般"},{"id":"ya3-108-1-78","subject":"ya3","topic":"植牙學","meta":"108年第1次第78題","year":108,"session":1,"number":78,"question":"下列那項是達到最佳骨整合的⾸要條件？","options":["(A) 植體種植合併骨移植術","(B) 植體種植下去時達到初始穩定度","(C) 植體立即受⼒（immediate loading）","(D) 立即種植（immediate implant placement）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-108-1-79","subject":"ya3","topic":"植牙學","meta":"108年第1次第79題","year":108,"session":1,"number":79,"question":"立即植牙（immediate implant placement）的優點不包括下列何者？","options":["(A) 避免頰側齒槽窩壁的吸收","(B) 減少⼿術次數","(C) 縮短治療時間","(D) 減少因翻瓣所造成的⾎液供應破壞"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-1-80","subject":"ya3","topic":"植牙學","meta":"108年第1次第80題","year":108,"session":1,"number":80,"question":"關於植體－植體周圍軟組織界⾯的敘述，下列何者錯誤？","options":["(A) 有類似牙齦溝的結構，⼀般認為深度在正常無炎症或僅有極輕微炎症狀況下為1.5～2.0 mm","(B) 屏障上⽪（barrier epithelium）⻑約2 mm，與天然牙的sulcular epithelium有共同的特徵","(C) 植體之結締組織區，位於屏障上⽪與alveolar crest之間，⾼約1～1.5 mm","(D) 類似⾃然牙的⽣物性寬度，植體的⽣物性屏障（biological barrier）約有4～4.5 mm"],"answer":1,"clinical_level":"重點"},{"id":"ya3-108-2-1","subject":"ya3","topic":"窩洞設計與分類","meta":"108年第2次第1題","year":108,"session":2,"number":1,"question":"有關牙本質小管的分布與牙本質通透性（dentin permeability）之敘述，下列何者錯誤？","options":["(A) 越靠近牙本質－牙釉質交接處（dentin-enamel junction）的牙本質，其牙本質小管數量會越少","(B) 越靠近牙髓腔的牙本質，其牙本質小管管徑會越大","(C) 牙根部的牙本質通透性較牙冠部大，因此當牙齦萎縮導致牙根暴露時容易發生牙本質敏感的問題","(D) 在咬合面窩洞修形時，深窩洞底部的牙本質通透性較淺窩洞大"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-2-2","subject":"ya3","topic":"牙科解剖與生理","meta":"108年第2次第2題","year":108,"session":2,"number":2,"question":"有關type IV膠原蛋白（collagen）的敘述，下列何者正確？","options":["(A) 主要在基底膜（basement membranes）被發現","(B) 由造牙本質細胞（odontoblasts）合成，可調節鈣化速率","(C) 提供牙髓組織構造的本體","(D) 牙髓組織中並無此類型膠原蛋白"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-2-3","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第2次第3題","year":108,"session":2,"number":3,"question":"有關牙髓的敘述，何者錯誤？","options":["(A) 牙齒發育之後，牙髓就不能繼續形成牙本質","(B) 成熟的牙髓含有幹細胞（stem cell）","(C) 牙髓缺乏真正的側枝循環系統，小動脈（arterioles）會經由根尖孔（apical foramen）進入牙髓","(D) 發炎反應會引起牙髓組織壓力增加，但是體積並無變化"],"answer":0,"clinical_level":"重點"},{"id":"ya3-108-2-4","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第2次第4題","year":108,"session":2,"number":4,"question":"牙髓結構中那一層有較多的造纖維細胞（fibroblast）與未分化之間葉（mesenchymal）細胞？","options":["(A) 中心區（central zone）（即牙髓本質（pulp proper））","(B) 多細胞區（cell-rich zone）","(C) 無細胞區（cell-free zone）","(D) 造牙本質細胞區（dentinoblast（odontoblast）zone）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-108-2-5","subject":"ya3","topic":"牙科解剖與生理","meta":"108年第2次第5題","year":108,"session":2,"number":5,"question":"副根管（accessory canal）的形成是源於下列何種因素？","options":["(A) 造牙骨質母細胞（cementoblast）生長失敗","(B) 造牙骨質母細胞（cementoblast）發育不良","(C) 馬拉塞氏上皮殘留體（epithelial cell rests of Malassez）的介入","(D) 赫威氏上皮根鞘（Hertwig’s epithelial root sheath）的不全"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-2-6","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第2次第6題","year":108,"session":2,"number":6,"question":"下列有關牙髓及根尖周圍病變之敘述，何者錯誤？","options":["(A) 牙髓及根尖周圍病變之病因，細菌擔任重要角色","(B) 沒有細菌污染也常會形成牙髓及根尖周圍病變","(C) Kakehashi認為於無菌老鼠實驗製造牙髓暴露，僅造成少量發炎反應並形成鈣化之牙本質橋","(D) Sundqvist和Möller等人認為具壞死牙髓之先前外傷牙齒，無根尖病灶者之牙齒皆為無菌"],"answer":1,"clinical_level":"重點"},{"id":"ya3-108-2-7","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第2次第7題","year":108,"session":2,"number":7,"question":"有關牙髓壞死引起的牽連痛（referred pain）之敘述，下列何者錯誤？","options":["(A) 若病人可以明確的指出是那顆牙齒痛則可以排除牽連痛的可能","(B) 引起牽連痛的神經為牙髓內的C型神經纖維","(C) 若患齒位於右側牙弓則牽連痛一般不會出現在左側牙弓","(D) 後牙發生牽連痛的機率比前牙高"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-2-8","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第2次第8題","year":108,"session":2,"number":8,"question":"在未經治療牙齒的根尖病灶中，主要存在的淋巴球細胞為何？","options":["(A) 漿細胞（plasma cells）","(B) B細胞","(C) T細胞","(D) B細胞與T細胞"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-2-9","subject":"ya3","topic":"牙齒外傷處理","meta":"108年第2次第9題","year":108,"session":2,"number":9,"question":"下列何種溶液對於保存脫落齒（avulsed tooth）有較好的效果？","options":["(A) 口水（saliva）","(B) 自來水（tap water）","(C) 生理食鹽水（normal saline）","(D) 牛奶（milk）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-2-10","subject":"ya3","topic":"牙齒外傷處理","meta":"108年第2次第10題","year":108,"session":2,"number":10,"question":"當根尖閉合（closed apex）的牙齒可能因脫槽（avulsion）外傷後，應該在何時開始根管治療，來防止發生牙 根外吸收的情況？","options":["(A) 外傷後3～5天內","(B) 外傷後7～10天內","(C) 外傷後1個月內","(D) 不用進行根管治療，除非有症狀的時候"],"answer":1,"clinical_level":"一般"},{"id":"ya3-108-2-11","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第2次第11題","year":108,"session":2,"number":11,"question":"下列何者不是牙根垂直斷裂的典型X光影像表現？","options":["(A) 根尖疏鬆（apical rarefaction）","(B) J型（J-shaped）牙根周圍骨病灶","(C) 深窄囊袋（deep narrow pocket）","(D) 影像光環狀（halo-like）骨喪失"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-2-12","subject":"ya3","topic":"牙齒外傷處理","meta":"108年第2次第12題","year":108,"session":2,"number":12,"question":"脫落齒（avulsed tooth）一般而言需要固定多久？","options":["(A) 7～10天","(B) 1個月","(C) 2個月","(D) 直到根管治療完成"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-2-13","subject":"ya3","topic":"根管治療程序","meta":"108年第2次第13題","year":108,"session":2,"number":13,"question":"下列何種根管沖洗溶液（irrigation solution），會釋出氧離子自由基（oxygen-free radical）而影響牙本質對樹 脂鍵結作用？","options":["(A) sodium hypochlorite（NaOCl）","(B) chlorhexidine","(C) EDTA","(D) sodium ascorbate"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-2-14","subject":"ya3","topic":"根管治療程序","meta":"108年第2次第14題","year":108,"session":2,"number":14,"question":"下列有關影響次氯酸鈉（NaOCl）藥效之說明，何者錯誤？","options":["(A) 其作用與氯（chlorine）有關","(B) 加熱可加強其殺菌效果","(C) 保存越久，殺菌力會降低","(D) 與EDTA共同作用，殺菌力更好"],"answer":3,"clinical_level":"重點"},{"id":"ya3-108-2-15","subject":"ya3","topic":"根管治療程序","meta":"108年第2次第15題","year":108,"session":2,"number":15,"question":"下列何者不是使用chlorhexidine作為沖洗液的優點？","options":["(A) 廣範圍（broad-spectrum）的殺菌力","(B) 毒性較低","(C) 具組織溶解力","(D) 滲漏到口腔黏膜不會造成潰瘍"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-2-16","subject":"ya3","topic":"牙體修形程序","meta":"108年第2次第16題","year":108,"session":2,"number":16,"question":"下列何組器械對牙本質的切削效率較佳？①正斜角（positive rake angle） ②負斜角（negative rake angle） ③深的螺紋溝（groove） ④淺的螺紋溝","options":["(A) ①③","(B) ①④","(C) ②③","(D) ②④"],"answer":0,"clinical_level":"重點"},{"id":"ya3-108-2-17","subject":"ya3","topic":"根管治療程序","meta":"108年第2次第17題","year":108,"session":2,"number":17,"question":"根管治療在進行入口修形（access cavity preparation）時，下列何處較易發生穿孔意外？","options":["(A) 上顎小臼齒的近心側","(B) 大臼齒的遠心側","(C) 上顎前牙的舌側","(D) 下顎前牙的舌側"],"answer":0,"clinical_level":"重點"},{"id":"ya3-108-2-18","subject":"ya3","topic":"根管治療程序","meta":"108年第2次第18題","year":108,"session":2,"number":18,"question":"下列何者不是根管清創與擴大（cleaning and shaping）的基本目標（objectives）？","options":["(A) 移除感染的軟硬組織","(B) 讓治療所需要的沖洗消毒液（disinfecting irrigants）可達到根管的根尖區（apical third）","(C) 有助於根管治療過程殺菌藥品的置放","(D) 維持牙本質小管（dentinal tubule）的通透性（permeability）"],"answer":3,"clinical_level":"重點"},{"id":"ya3-108-2-19","subject":"ya3","topic":"根管治療程序","meta":"108年第2次第19題","year":108,"session":2,"number":19,"question":"有關三氧礦化聚合物MTA（mineral trioxide aggregate）的敘述，何者錯誤？","options":["(A) 凝固時間約為3～4小時","(B) 放射線不透性高於Super-EBA及IRM，但低於銀粉之放射線不透性","(C) 初期pH值為10.2，調拌3小時後可高至pH值12.5，1週後pH值約為9.5","(D) 需在乾燥的情況下才會硬化"],"answer":3,"clinical_level":"重點"},{"id":"ya3-108-2-20","subject":"ya3","topic":"根尖手術與再治療","meta":"108年第2次第20題","year":108,"session":2,"number":20,"question":"在根尖手術進行緣下翻瓣（submarginal flap）時，其水平切線（horizontal incision）應至少距離牙齦溝底部 （depth of the gingival sulcus）多少距離，以保留足夠的附連牙齦（attached gingiva）進而預防黏膜牙齦的破 壞？","options":["(A) 0.5 mm","(B) 1 mm","(C) 1.5 mm","(D) 2 mm"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-2-21","subject":"ya3","topic":"根管器械","meta":"108年第2次第21題","year":108,"session":2,"number":21,"question":"分離器械留存於根管底部的牙齒在下列那一項情況下，根管治療的預後最差？","options":["(A) 分離器械為15號file，牙齒為活性牙","(B) 分離器械為40號file，牙齒為活性牙","(C) 分離器械為40號file，牙齒為非活性牙，無根尖病變","(D) 分離器械為15號file，牙齒為非活性牙，有根尖病變"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-2-22","subject":"ya3","topic":"根管治療程序","meta":"108年第2次第22題","year":108,"session":2,"number":22,"question":"根管治療後的牙齒會被拔除之主要原因為何？","options":["(A) 牙齒斷裂","(B) 牙冠部復形物或贋復物不良","(C) 根管清創與修形不足","(D) 根管充填品質不佳"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-2-23","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第2次第23題","year":108,"session":2,"number":23,"question":"關於側根管及副根管，下列何者錯誤？","options":["(A) 如果出現在furcation的位置，應要做好清創的工作","(B) 側根管裡多為結締組織與血管","(C) 大多出現於根尖處1/3","(D) 牙髓與牙周病變可經側根管互通"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-2-24","subject":"ya3","topic":"醫學倫理與法規","meta":"108年第2次第24題","year":108,"session":2,"number":24,"question":"有關根管治療風險管理（risk management）之敘述，下列何者錯誤？","options":["(A) 醫病關係之建立為最主要因素","(B) 知情同意（informed consent）為重要之因素","(C) 最好的風險管理是慎選病患，並拒絕任何可能有風險的相關患者","(D) 針對醫療事故索賠，牙科主要防範要素為：保存正確良好之病歷紀錄"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-2-25","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第2次第25題","year":108,"session":2,"number":25,"question":"15歲男性左下臼齒區頰側牙齦出現膿包而前來求診，臨床檢查發現左下第一大臼齒與第二小臼齒均有敲痛與 觸痛的情況，第一大臼齒對冷刺激有輕微疼痛反應，但移除刺激後疼痛感便立即消失，第二小臼齒則對冷刺 激沒有反應。使用馬來膠針（gutta-percha）檢測膿包處竇管（sinus tract）來源，其臨床照片與X光片檢查結 果如下圖所示。則此病患的牙齒疾病診斷應為何？","options":["(A) 左下第一大臼齒與第二小臼齒均為牙髓壞死合併慢性根尖牙周炎（chronic apical periodontitis）","(B) 左下第一大臼齒牙髓壞死合併慢性根尖膿腫（chronic apical abscess）與第二小臼齒牙髓壞死合併慢性根尖牙 周炎（chronic apical periodontitis）","(C) 左下第一大臼齒牙髓壞死合併慢性根尖膿腫（chronic apical abscess）與第二小臼齒牙髓與根尖組織正常 （normal apical tissue）","(D) 左下第一大臼齒牙髓與根尖組織正常（normal apical tissue）與第二小臼齒牙髓壞死合併慢性根尖膿腫 （chronic apical abscess）"],"answer":3,"image":"ya3-108-2-25.jpeg","clinical_level":"一般"},{"id":"ya3-108-2-26","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第2次第26題","year":108,"session":2,"number":26,"question":"承上題，則此病患合適的治療計畫為何？","options":["(A) 左下第一大臼齒根管治療與第二小臼齒根尖成形術（apexification）","(B) 左下第一大臼齒根管治療","(C) 左下第一大臼齒與第二小臼齒根管治療","(D) 左下第二小臼齒根尖成形術（apexification）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-2-27","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第2次第27題","year":108,"session":2,"number":27,"question":"下列何者為牙齒受到齲齒或咬耗（attrition）等刺激時，造牙本質細胞（odontoblast）所產生的牙本質？","options":["(A) 三級（tertiary）牙本質","(B) 原生（primary）牙本質","(C) 前牙本質（predentin）","(D) 繼生（secondary）牙本質"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-2-28","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第2次第28題","year":108,"session":2,"number":28,"question":"牙齒面臨外傷或齲齒時，下列何者是啟動牙本質三度修復（tertiary repair）及調控發炎反應最主要的生長因子 （growth factor）？","options":["(A) BMP-2（bone morphogenetic protein-2）","(B) TGF-β1（transforming growth factor-β1）","(C) PDGF（platelet-derived growth factor）","(D) NGF（nerve growth factor）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-108-2-29","subject":"ya3","topic":"窩洞設計與分類","meta":"108年第2次第29題","year":108,"session":2,"number":29,"question":"若口內檢查時，發現左上正中門齒表面乾燥時呈現不透明的白色斑點，但濕潤時呈現透明，此病灶最有可能 為下列何者？","options":["(A) developmental white spot","(B) demineralized white sopt","(C) active caries","(D) inactive caries"],"answer":1,"clinical_level":"一般"},{"id":"ya3-108-2-30","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第2次第30題","year":108,"session":2,"number":30,"question":"關於 zone of dentinal caries 之敘述，下列何者正確？","options":["(A) 對於進展快速的齲蝕（rapidly progressing caries）而言，zone 之間的差異性較大","(B) 相較於 affected dentin，infected dentin 位於較深層位置","(C) Affected dentin 中牙本質小管內有大的結晶顆粒","(D) Infected dentin 的牙本質可以自行修復"],"answer":2,"clinical_level":"重點"},{"id":"ya3-108-2-31","subject":"ya3","topic":"窩洞設計與分類","meta":"108年第2次第31題","year":108,"session":2,"number":31,"question":"齲齒活性較高的成年人，建議間隔多久拍攝一次咬翼片以便追蹤檢查？","options":["(A) 6～18 個月","(B) 3 個月","(C) 2～3 年","(D) 5 年"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-2-32","subject":"ya3","topic":"黏著與美學修復","meta":"108年第2次第32題","year":108,"session":2,"number":32,"question":"牙釉質經過酸蝕後，與黏著劑（bonding agent）間的鍵結主要是靠下列何者？","options":["(A) 氫鍵（hydrogen bond）","(B) 離子鍵（ionic）","(C) 共價鍵（covalent）","(D) 機械性結合（mechanical）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-2-33","subject":"ya3","topic":"複合樹脂與材料","meta":"108年第2次第33題","year":108,"session":2,"number":33,"question":"牙科複合樹脂及黏著劑（adhesive）之主要單體成分為：","options":["(A) HEMA（2-hydroxyethyl methacrylate）","(B) Bis-GMA（bisphenol A glycerolate dimethacrylate）","(C) GPDM（glycerol phosphate dimethacrylate）","(D) BPDM（biphenyl dimethacrylate）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-108-2-34","subject":"ya3","topic":"牙體修形程序","meta":"108年第2次第34題","year":108,"session":2,"number":34,"question":"下列何種手動器械（hand instruments）屬於excavator？①ordinary hatchets ②hoes ③angle formers ④chisel","options":["(A) 僅①②③","(B) 僅②③④","(C) 僅①②④","(D) ①②③④"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-2-35","subject":"ya3","topic":"牙體修形程序","meta":"108年第2次第35題","year":108,"session":2,"number":35,"question":"右手操作的牙醫師，治療病人右下顎正中門齒舌側齲齒，應坐在病人那一方向？","options":["(A) 5 點鐘方向","(B) 7 點鐘方向","(C) 9 點鐘方向","(D) 12 點鐘方向"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-2-36","subject":"ya3","topic":"牙體修形程序","meta":"108年第2次第36題","year":108,"session":2,"number":36,"question":"磨牙過程中，為避免病人誤吞鬆脫的尖銳器械，最有效的預防方法為下列何者？","options":["(A) 放置張口器（mouth retractor）","(B) 綁牙線於器械上","(C) 放置橡皮障（rubber dam）","(D) 用紗布放置在病人唇側"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-2-37","subject":"ya3","topic":"複合樹脂與材料","meta":"108年第2次第37題","year":108,"session":2,"number":37,"question":"複合樹脂聚合過程中，關於單體（monomer）轉換度（degree of conversion）的敘述，下列何者錯誤？","options":["(A) 光源強度越高，光聚合轉換度越高","(B) 光照時間越長，光聚合轉換度越高","(C) 含 BIS-GMA 的複合樹脂轉換度可達65%","(D) 複合樹脂顏色越深，光聚合轉換度越高"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-2-38","subject":"ya3","topic":"複合樹脂與材料","meta":"108年第2次第38題","year":108,"session":2,"number":38,"question":"關於複合樹脂之敘述，下列何者正確？","options":["(A) 微粒子型複合樹脂（microfilled resin composite）長期顏色穩定度低於混成型複合樹脂（hybrid resin composite）","(B) 微粒子型複合樹脂（microfilled resin composite）填料成分約占80%重量比","(C) 增加填料比例可以增加複合樹脂之熱膨脹係數（coefficient of thermal expansion）","(D) 微粒子型複合樹脂（microfilled resin composite）平均粒子大小約為0.04nm"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-2-39","subject":"ya3","topic":"複合樹脂與材料","meta":"108年第2次第39題","year":108,"session":2,"number":39,"question":"關於C-factor（configuration factor）的敘述，下列何者正確？①為鍵結面的數目除以非鍵結面的數目 ②為 非鍵結面的數目除以鍵結面的數目 ③低 C-factor 窩洞之收縮應力較高 ④高 C-factor 窩洞之收縮應力較高","options":["(A) ①③","(B) ①④","(C) ②③","(D) ②④"],"answer":1,"clinical_level":"一般"},{"id":"ya3-108-2-40","subject":"ya3","topic":"窩洞設計與分類","meta":"108年第2次第40題","year":108,"session":2,"number":40,"question":"前牙複合樹脂填補時，下列何者不符合從唇側面（facial approach）製備窩洞的原則？","options":["(A) 齲蝕病變位於唇側面","(B) 牙齒排列不齊，從舌側面進入困難","(C) 唇側面製作斜面（bevel）較為美觀","(D) 舊填補物位於唇側面"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-2-41","subject":"ya3","topic":"黏著與美學修復","meta":"108年第2次第41題","year":108,"session":2,"number":41,"question":"在前牙鄰接面齲齒（interproximal caries）中，若齲齒範圍達到牙本質且延伸至牙根，下列敘述何者正確？","options":["(A) 對於高齲齒率的患者，可用流動樹脂（flowable resin composites）填補","(B) 對於高齲齒率的患者，可用樹脂修飾玻璃離子黏合劑（resin-modified glass-ionomer）填補齒頸部部分，再用 複合樹脂填補剩餘部分","(C) 對於低齲齒率的患者，牙根齲齒不須填補","(D) 窩洞製備需依靠機械倒凹式設計（mechanical undercut）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-108-2-42","subject":"ya3","topic":"黏著與美學修復","meta":"108年第2次第42題","year":108,"session":2,"number":42,"question":"大範圍前牙填補時，關於樹脂顏色的敘述，下列何者錯誤？","options":["(A) 四類窩洞（Class IV）填補時，使用較不透明（opaque）的樹脂會讓填補後呈現較暗的顏色","(B) 可以使用藍色或灰色著色樹脂（tinting resin），加強牙齒的透明度（translucent）","(C) 可以使用白色著色樹脂（tinting resin），加強牙齒切端的光環感（halo）","(D) 唇側可使用微粒型複合樹脂（microfill composites）來達到較光滑的表面"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-2-43","subject":"ya3","topic":"窩洞設計與分類","meta":"108年第2次第43題","year":108,"session":2,"number":43,"question":"修磨臼齒咬合面複合樹脂第一類型窩洞往頰側溝（facial groove）延伸時，下列敘述何者正確？","options":["(A) 咬合面邊緣都要修磨長斜面（long bevel）","(B) 咬合面邊緣都要修磨短斜面（short bevel）","(C) 咬合面邊緣不要修磨斜面","(D) 頰側邊緣需修磨斜面"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-2-44","subject":"ya3","topic":"牙體修形程序","meta":"108年第2次第44題","year":108,"session":2,"number":44,"question":"小芳醫師在填補汞齊時，發現原本使用混合型汞齊（admixed amalgam），換成球形（spherical）汞齊後，下 列操作步驟何者正確？①選用較小頭填壓器 ②更需要側向填壓 ③應施與更大填壓力 ④應快速操作避 免硬化","options":["(A) ①②③④","(B) 僅①②④","(C) 僅③","(D) 僅②④"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-2-45","subject":"ya3","topic":"複合樹脂與材料","meta":"108年第2次第45題","year":108,"session":2,"number":45,"question":"汞齊填補物可以承受較大的咬力，其主要鍵結為下列何者？","options":["(A) 金屬鍵","(B) 離子鍵","(C) 共價鍵","(D) 氫鍵"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-2-46","subject":"ya3","topic":"牙體修形程序","meta":"108年第2次第46題","year":108,"session":2,"number":46,"question":"使用汞齊填補，當製備近心側第二類（Class II）窩洞時，為了避免傷害鄰牙，移除近心面齲齒時，應從何處 下鑽針最適當？","options":["(A) 近心邊緣嵴（marginal ridge）","(B) 咬合中央窩","(C) 近心發育溝","(D) 頰側近心線角"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-2-47","subject":"ya3","topic":"窩洞設計與分類","meta":"108年第2次第47題","year":108,"session":2,"number":47,"question":"第二級金合金嵌體窩洞修形的咬合面及鄰接面需做 30～40 度的斜面，下列敘述何者錯誤？","options":["(A) 斜面大於 40 度，則金屬太厚難以研光（burnish）","(B) 斜面小於 30 度，則金屬強度太弱","(C) 是為了平行於牙釉稜柱的走向","(D) 可讓鑄造體更密貼於窩洞"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-2-48","subject":"ya3","topic":"黏著與美學修復","meta":"108年第2次第48題","year":108,"session":2,"number":48,"question":"以樹脂黏合劑黏著嵌體，造成術後敏感的影響因子為下列何者？①剩餘牙本質厚度 ②窩洞塗抹抗菌劑 ③ 黏著時唾液汙染 ④印模材料的選擇","options":["(A) ①②③④","(B) 僅①②③","(C) 僅②③④","(D) 僅①③"],"answer":1,"clinical_level":"一般"},{"id":"ya3-108-2-49","subject":"ya3","topic":"窩洞設計與分類","meta":"108年第2次第49題","year":108,"session":2,"number":49,"question":"小臼齒近心頰側鄰接面金合金嵌體窩洞修形的二度開展（secondary flare），常被省略是為了下列何者因素？","options":["(A) 美觀問題的呈現","(B) 邊緣強度的考量","(C) 日後較易清潔","(D) 減少印模的誤差"],"answer":0,"clinical_level":"重點"},{"id":"ya3-108-2-50","subject":"ya3","topic":"黏著與美學修復","meta":"108年第2次第50題","year":108,"session":2,"number":50,"question":"下列那一種造成牙齒變色的原因可經由磨光（polishing）來移除？","options":["(A) 抽煙造成的染色","(B) 牙齒發育及礦化變異","(C) 過量氟化物造成的染色","(D) 四環黴素造成的變色"],"answer":0,"clinical_level":"重點"},{"id":"ya3-108-2-51","subject":"ya3","topic":"黏著與美學修復","meta":"108年第2次第51題","year":108,"session":2,"number":51,"question":"黏著瓷鑲面（porcelain veneer）時，比照磷酸對於牙齒之表面處理，下列何者會對陶瓷產生類似效果？","options":["(A) 矽烷偶合劑（silane coupling agent）","(B) 磷酸（phosphoric acid）","(C) 氫氟酸（hydrofluoric acid）","(D) 聚丙烯酸（polyacrylic acid）"],"answer":2,"clinical_level":"重點"},{"id":"ya3-108-2-52","subject":"ya3","topic":"牙髓診斷與病理","meta":"108年第2次第52題","year":108,"session":2,"number":52,"question":"下列何者不是內生性牙齒變色（intrinsic discoloration）的原因？","options":["(A) 氟斑齒","(B) 蛀牙","(C) 外傷","(D) 牙齦出血"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-2-53","subject":"ya3","topic":"牙齒外傷處理","meta":"108年第2次第53題","year":108,"session":2,"number":53,"question":"關於黏連（ankylosis）的敘述，下列何者錯誤？","options":["(A) 指牙周韌帶骨質與齒槽骨的融合（fusion）","(B) 可能代表一種生理重塑的形式（physiological remodeling）","(C) 可在慢性根尖炎症後發生（chronic periapical inflammation）","(D) 可在牙齒再植後發生（tooth replantation）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-108-2-54","subject":"ya3","topic":"牙周疾病與診斷","meta":"108年第2次第54題","year":108,"session":2,"number":54,"question":"關於牙齦點斑（gingival stippling）的敘述，下列何者錯誤？","options":["(A) 附連牙齦有牙齦點斑，邊緣牙齦沒有","(B) 頰側比舌側明顯","(C) 嬰兒時就出現，一直增加到成年期","(D) 減少或消失是牙齦疾病的共同徵象"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-2-55","subject":"ya3","topic":"牙科解剖與生理","meta":"108年第2次第55題","year":108,"session":2,"number":55,"question":"牙周組織的神經末梢構造，下列何者與疼痛的感覺相關？","options":["(A) 呈樹狀外形的游離末梢（free endings）","(B) 主要位於牙根尖的盧費尼氏小體（Ruffini's corpuscles）","(C) 梅斯納氏小體（Meissner corpuscles）","(D) 類似膠囊圍繞的紡錘狀（spindlelike）神經末梢"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-2-56","subject":"ya3","topic":"牙周疾病與診斷","meta":"108年第2次第56題","year":108,"session":2,"number":56,"question":"下列何種牙齦細胞可能在側位牙周囊腫（lateral periodontal cysts）形成的機轉上擔任重要角色？","options":["(A) 麥克氏細胞（Merkel cells）","(B) 黑色素細胞（melanocytes）","(C) 蘭格罕氏細胞（Langerhans cells）","(D) 赫威氏上皮根鞘細胞（Hertwig's epithelial root sheath cells）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-2-57","subject":"ya3","topic":"牙周疾病與診斷","meta":"108年第2次第57題","year":108,"session":2,"number":57,"question":"關於牙齦炎的敘述，下列何者錯誤？","options":["(A) 糖尿病會加劇牙菌斑對牙齦炎的嚴重度","(B) 牙齦病灶可分為牙菌斑引起及非牙菌斑引起兩大類","(C) 性賀爾蒙的改變例如女性懷孕會加劇牙齦炎的嚴重度","(D) 目前已有足夠證據顯示牙齦炎與營養不良有關"],"answer":3,"clinical_level":"重點"},{"id":"ya3-108-2-58","subject":"ya3","topic":"牙周疾病與診斷","meta":"108年第2次第58題","year":108,"session":2,"number":58,"question":"依據Page & Schröeder（1976年）的牙周組織病理病灶分期，關於advanced lesion之敘述，下列何者錯誤？","options":["(A) 巨噬細胞扮演著破壞的角色，所以大量出現在病灶中","(B) 在臨床表現及組織切片中，皆可證實有骨喪失","(C) 漿細胞與B細胞是主要的細胞","(D) 在病灶中的造纖維細胞受細胞激素之刺激，會產生matrix metalloproteinases（MMPs）"],"answer":0,"clinical_level":"重點"},{"id":"ya3-108-2-59","subject":"ya3","topic":"牙周疾病與診斷","meta":"108年第2次第59題","year":108,"session":2,"number":59,"question":"關於牙周病治療預後（prognosis）的評估，下列何者不屬於解剖因素？","options":["(A) 牙根間隔距離","(B) 牙根凹陷","(C) 鈣化根管","(D) 牙根叉病變"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-2-60","subject":"ya3","topic":"牙周非手術治療","meta":"108年第2次第60題","year":108,"session":2,"number":60,"question":"牙周炎治療時使用抗生素，若要選擇對鏈球菌種作用較少，而對A. actinomycetemcomitans所有菌種均有感受 性（susceptiblility）的抗生素為下列何者？","options":["(A) ciprofloxacin","(B) augmentin","(C) metronidazole","(D) azithromycin"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-2-61","subject":"ya3","topic":"牙周疾病與診斷","meta":"108年第2次第61題","year":108,"session":2,"number":61,"question":"牙周組織發炎反應宿主的調控物質中，下列何者具有抗微生物作用？","options":["(A) 脂氧素（lipoxin）","(B) 消散素（resolvin）","(C) 保護素（protectin）","(D) 防禦素（defensin）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-2-62","subject":"ya3","topic":"牙周疾病與診斷","meta":"108年第2次第62題","year":108,"session":2,"number":62,"question":"關於吸菸與牙周病的敘述，下列何者錯誤？","options":["(A) 齒槽骨的吸收程度與吸菸量有關，與局部牙菌斑多少較無關","(B) 吸菸減弱口腔中性多核白細胞的趨化和吞噬功能","(C) 吸菸減少血清IgG","(D) 吸菸者的牙周炎病情較重，牙齦探診出血比例高"],"answer":3,"clinical_level":"重點"},{"id":"ya3-108-2-63","subject":"ya3","topic":"牙周疾病與診斷","meta":"108年第2次第63題","year":108,"session":2,"number":63,"question":"下列何種細菌不能以BANA-test很快地偵測到？","options":["(A) P. gingivalis","(B) T. forsythia","(C) T. denticola","(D) A. actinomycetemcomitans"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-2-64","subject":"ya3","topic":"牙周疾病與診斷","meta":"108年第2次第64題","year":108,"session":2,"number":64,"question":"刷牙時合併使用牙膏，能有效清除牙菌斑的最主要因素為下列何者？","options":["(A) detergent or surfactant","(B) emulsifying agent : sodium lauryl sulfate","(C) abrasive : silica , calcium carbonate","(D) function of access of brush filaments"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-2-65","subject":"ya3","topic":"牙周非手術治療","meta":"108年第2次第65題","year":108,"session":2,"number":65,"question":"下列牙周器械，何者的刀刃切緣屬於雙刃？","options":["(A) sickle","(B) hoe","(C) chisel","(D) file"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-2-66","subject":"ya3","topic":"牙周手術與再生","meta":"108年第2次第66題","year":108,"session":2,"number":66,"question":"關於可吸收牙周再生膜優於不可吸收牙周再生膜的敘述，下列何者錯誤？","options":["(A) 可避免於患部進行二次手術","(B) 術後併發症較少","(C) 可以得到同等於不可吸收牙周再生膜之療效","(D) 無須進行初級縫合（primary closure）"],"answer":3,"clinical_level":"重點"},{"id":"ya3-108-2-67","subject":"ya3","topic":"牙周手術與再生","meta":"108年第2次第67題","year":108,"session":2,"number":67,"question":"依照根叉侵犯型態，下顎大臼齒頰側二級根叉侵犯，下列何者為最佳的處理方式？","options":["(A) 引導組織再生手術（guided tissue regeneration）","(B) 骨切除術（resective osseous surgery）","(C) 牙根整平暨修型術（root planing and odontoplasty）","(D) 牙齒切半術（hemisection）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-2-68","subject":"ya3","topic":"牙周手術與再生","meta":"108年第2次第68題","year":108,"session":2,"number":68,"question":"黏膜牙齦手術（mucogingival surgery）術式選擇的準則，下列敘述何者錯誤？","options":["(A) 手術前，牙齒表面沒有牙菌斑及沒有發炎的牙齦是必需的","(B) 游離牙齦移植及游離結締組織移植可以創造出口腔前庭及附連牙齦寬度","(C) 在萎縮處的冠向作牙齦增高術（coronal gingival augmentation）比在根向作牙齦增高術，可以得到更多的血 液供應","(D) 做蒂狀移位手術（pedicle displacement），鄰近的供給部位牙齦需有足夠的寬度與厚度"],"answer":2,"clinical_level":"重點"},{"id":"ya3-108-2-69","subject":"ya3","topic":"牙周手術與再生","meta":"108年第2次第69題","year":108,"session":2,"number":69,"question":"關於牙周敷料（periodontal dressing）的敘述，下列何者錯誤？","options":["(A) 可用於術後保護傷口","(B) 可獲得且維持黏膜皮瓣與其下骨頭的緊密貼附","(C) 可避免術後流血","(D) 使用抗菌藥物漱口時，可避免敷料下的牙菌斑形成"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-2-70","subject":"ya3","topic":"牙周手術與再生","meta":"108年第2次第70題","year":108,"session":2,"number":70,"question":"下列何者不是牙齦切除術（gingivectomy）的適應症？","options":["(A) 牙周囊袋的降低","(B) 建立利於感染控制的齒齦部位","(C) 修正異常牙齦肥大","(D) 重建生物性寬度"],"answer":3,"clinical_level":"重點"},{"id":"ya3-108-2-71","subject":"ya3","topic":"牙周手術與再生","meta":"108年第2次第71題","year":108,"session":2,"number":71,"question":"運用游離軟組織移植進行牙根覆蓋術後，關於組織癒合的敘述，下列何者錯誤？","options":["(A) 其存活端看與移植床周圍結締組織的血漿擴散和再血管化","(B) 在術後6個月可觀察到creeping attachment現象","(C) 組織切片結果顯示移植區牙根大部分產生上皮附連","(D) 合併使用牙釉基質蛋白（enamel matrix protein）可促進結締組織附連生長"],"answer":1,"clinical_level":"一般"},{"id":"ya3-108-2-72","subject":"ya3","topic":"牙周手術與再生","meta":"108年第2次第72題","year":108,"session":2,"number":72,"question":"關於crown lengthening procedure（CLP）的敘述，下列何者錯誤？","options":["(A) 手術要使齒槽骨嵴至鄰近牙之牙冠邊緣最少應有3至4 mm距離以免侵犯biological width.","(B) 可用於可以強逼萌出（forced eruption）的病例","(C) 斷裂牙根面在牙根尖端2/3處時不可作CLP","(D) “Fiberotomy” 可應用於與”angular bone defects”相關的病例"],"answer":3,"clinical_level":"重點"},{"id":"ya3-108-2-73","subject":"ya3","topic":"牙周疾病與診斷","meta":"108年第2次第73題","year":108,"session":2,"number":73,"question":"病人在牙周病治療完成後，牙齦探測流血（BoP）為9%，有6個≧5mm殘存牙周囊袋，4顆牙缺失，齒槽骨與 年紀的關係（BL%/age）是0.75，Type I diabetes，無抽菸的習慣，若依Lang & Tonetti提出的功能性圖 （functional diagram），此病人是屬於何種類別？","options":["(A) low-risk","(B) medium-risk","(C) severe-risk","(D) high-risk"],"answer":1,"clinical_level":"重點"},{"id":"ya3-108-2-74","subject":"ya3","topic":"牙周非手術治療","meta":"108年第2次第74題","year":108,"session":2,"number":74,"question":"關於支持性牙周治療（supportive periodontal treatment）的敘述，下列何者錯誤？","options":["(A) 病人若是高蛀牙危險群，應該每6～18個月定期拍攝後牙咬翼片（bite-wing radiographs）","(B) 支持性牙周治療包括檢查（examination）、洗牙（scaling）和拋光（polishing）","(C) 維持期（maintenance phase）應在牙周手術治療之後開始","(D) 牙周控制不好的患者，應於每12～24個月定期拍攝根尖（periapical）及垂直咬翼片（bite-wing radiographs）"],"answer":2,"clinical_level":"重點"},{"id":"ya3-108-2-75","subject":"ya3","topic":"醫學倫理與法規","meta":"108年第2次第75題","year":108,"session":2,"number":75,"question":"由於許多患者會隱匿自己的感染性疾病或是不清楚病情，因此在牙科診療過程中，下列何者處置較能保障醫 護人員的安全？","options":["(A) 只要針對高風險族群，進行高規格感染控制處置即可，盡量減少超音波器械或高速手機等會產生水霧的工 具","(B) 建議所有醫療人員，需施打C型肝炎病毒疫苗","(C) 在進行牙科診療前，請患者以葡萄糖酸氯己定 （chlorhexidine gluconate）溶液漱口30秒","(D) HIV感染的患者由於免疫系統受損，進行牙科處置前須服用預防性抗生素，以減少感染風險"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-2-76","subject":"ya3","topic":"牙科解剖與生理","meta":"108年第2次第76題","year":108,"session":2,"number":76,"question":"關於糖尿病患者在進行牙周病治療時的敘述，下列何者較不正確？","options":["(A) 較長時間的牙周病治療前，可利用血糖儀（glucometer）來了解患者血糖現況","(B) 若在預計兩個小時的治療之前監測到患者血糖為70 mg/dL，則很有可能在治療過程中出現低血糖狀況","(C) 低血糖症狀包含顫抖、焦慮不安、盜汗、頭暈等，需停止牙科治療，給予含糖飲食","(D) 若患者的降血糖用藥為metformin和thiazolidinediones等類型，會有很高的機會產生低血糖症狀"],"answer":3,"clinical_level":"一般"},{"id":"ya3-108-2-77","subject":"ya3","topic":"牙周疾病與診斷","meta":"108年第2次第77題","year":108,"session":2,"number":77,"question":"唐氏症（Down syndrome）相關牙周破壞的高盛行率與嚴重程度加劇，與下列何者最有相關性？","options":["(A) 多型單核細胞趨化性（chemotaxis）低下，較差的細胞吞噬（phagocytosis）功能","(B) 齒間空隙、牙齒擁擠、繫帶過高","(C) 咬合不正（malocclusion）","(D) 兒童口腔中有較多的牙周致病菌（P. gingivalis）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-108-2-78","subject":"ya3","topic":"植牙學","meta":"108年第2次第78題","year":108,"session":2,"number":78,"question":"若需將自然牙與人工植體連結成一個三單位牙橋，下列何種贋復體設計較可以避免自然牙發生下壓內縮 （intrusion）？","options":["(A) 與自然牙暫時黏著之套疊式義齒（telescope denture）","(B) 牙齒與人工植體之間以彈性附連體（resilient attachment）","(C) 與自然牙永久黏著的一體鑄造牙橋（one piece casting bridge）","(D) 牙齒與人工植體之間以半精密式附連體（semiprecision attachment）相連"],"answer":2,"clinical_level":"一般"},{"id":"ya3-108-2-79","subject":"ya3","topic":"植牙學","meta":"108年第2次第79題","year":108,"session":2,"number":79,"question":"對植體骨整合（osseointegration）的過程，在植入後就開始進行之敘述，以下何者最為正確？","options":["(A) 當植體與骨頭間的移動距離在50 μm時，就會大幅降低骨整合率，因此具初級穩定度是植體成功的要件","(B) 骨細胞的溫度閾值為攝氏47度，且不可超過一分鐘，超過時會因過熱導致骨壞死或是變成腐骨","(C) 片狀骨（lamellar bone）在骨頭及植體之間以每天最快100 μm的速度生長，數個月後慢慢的被網狀骨 （woven bone）取代","(D) 上顎後牙區骨量較多，下顎前牙區骨脊較窄，因此上顎後牙區能提供植體良好的初級穩定度"],"answer":1,"clinical_level":"一般"},{"id":"ya3-108-2-80","subject":"ya3","topic":"植牙學","meta":"108年第2次第80題","year":108,"session":2,"number":80,"question":"對”Maintenance of Implants”之敘述，下列何者錯誤？","options":["(A) 以conventional methods偵測有植體鬆動，顯示有loss of integration與implant failure","(B) 探測深度少於4至5 mm認為是健康條件之一","(C) 建議在loading後前3個月，不要囊袋探測，以避免干擾癒合","(D) 健康的植牙位點顯示比維護良好的自然牙有較小的探測出血傾向"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-1-1","subject":"ya3","topic":"牙髓診斷與病理","meta":"109年第1次第1題","year":109,"session":1,"number":1,"question":"不可逆牙髓炎疼痛的原因為下列何者？","options":["(A) 牙髓之A-δ型神經纖維作用","(B) 因發炎髓腔壓力降低所致","(C) 牙髓之A-β型神經纖維作用","(D) 牙髓之C型神經纖維作用"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-1-2","subject":"ya3","topic":"牙髓診斷與病理","meta":"109年第1次第2題","year":109,"session":1,"number":2,"question":"關於牙髓鈣化（pulp calcification）的敘述，下列何者錯誤？","options":["(A) 牙髓鈣化的牙齒對於敲診、觸診檢查的反應通常和健康牙齒有明顯不同","(B) 牙髓鈣化的牙齒，牙冠外觀常呈現暗黃的變色（yellowish discoloration）","(C) 鈣化現象是造牙本質細胞（odontoblast）受刺激所引起的反應","(D) 牙髓鈣化的牙齒如果沒有不適症狀，定期追蹤即可，可不需根管治療介入"],"answer":0,"clinical_level":"重點"},{"id":"ya3-109-1-3","subject":"ya3","topic":"牙髓診斷與病理","meta":"109年第1次第3題","year":109,"session":1,"number":3,"question":"症候突發（flare-up）主因根管系統內細菌平衡被破壞伴隨宿主免疫反應所造成。宿主對突出（extruded）根管 系統的細菌及其產物引發免疫反應，下列何種補體蛋白很少出現在上述情況中？","options":["(A) C1q","(B) C3a","(C) C4b","(D) C5a"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-1-4","subject":"ya3","topic":"牙髓診斷與病理","meta":"109年第1次第4題","year":109,"session":1,"number":4,"question":"牙髓因受損感染而發炎，其造成疼痛的原因為何？","options":["(A) 炎症介質的釋放直接升高了感覺神經的閾值（sensory nerve threshold）","(B) 炎症介質間接增加了小動脈血管擴張","(C) 炎症介質間接降低微靜脈的通透性","(D) 降低了組織的壓力進而直接影響感覺神經的接受器"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-1-5","subject":"ya3","topic":"牙髓診斷與病理","meta":"109年第1次第5題","year":109,"session":1,"number":5,"question":"左下顎第一與第二小臼齒需要根管再治療（圖A），圖B以X光平行儀（cone indicator）正角度照射（facial projection），圖A與圖C為近心側往遠心側照射 （mesial projection），則左下顎第一小臼齒於根管再治療前遺 漏了那一個根管？","options":["(A) 頰側根管（buccal canal）","(B) 舌側根管（lingual canal）","(C) 近心側根管（mesial canal）","(D) 遠心側根管（distal canal）"],"answer":1,"image":"ya3-109-1-5.jpeg","clinical_level":"一般"},{"id":"ya3-109-1-6","subject":"ya3","topic":"牙髓診斷與病理","meta":"109年第1次第6題","year":109,"session":1,"number":6,"question":"關於根尖真性囊腫（true cyst），何者敘述正確？","options":["(A) 其形成與馬拉塞氏上皮殘留體（rests of Malassez）有關","(B) 出現比例和根尖周肉芽腫（periapical granuloma）的機率相近","(C) 使用X光片可與根尖周肉芽腫（periapical granuloma）做鑑別診斷","(D) 真性囊腫可藉由非手術性根管治療治癒"],"answer":0,"clinical_level":"一般"},{"id":"ya3-109-1-7","subject":"ya3","topic":"牙齒外傷處理","meta":"109年第1次第7題","year":109,"session":1,"number":7,"question":"患者因正中門齒外傷來院就診，根尖放射片及錐狀射束電腦斷層掃描（cone-beam computed tomography, CBCT）檢查，最可能的診斷為何？","options":["(A) 側向脫位（lateral luxation）","(B) 突出脫位（extrusive luxation）","(C) 半脫位（subluxation）","(D) 震盪（concussion）"],"answer":0,"image":"ya3-109-1-7.jpeg","clinical_level":"一般"},{"id":"ya3-109-1-8","subject":"ya3","topic":"牙齒外傷處理","meta":"109年第1次第8題","year":109,"session":1,"number":8,"question":"關於牙冠斷裂（crown fracture），下列敘述何者正確？","options":["(A) 非複雜性（uncomplicated）牙冠斷裂是指斷裂部位只涵蓋enamel","(B) 非複雜性（uncomplicated）牙冠斷裂造成牙髓壞死的可能性較低","(C) 複雜性（complicated）牙冠斷裂是指斷裂部位涵蓋了enamel、dentin及cementum","(D) 牙根發育未完成（immature tooth）的複雜性（complicated）牙冠斷裂牙齒，優先考慮使用牙髓切除術 （pulpectomy）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-1-9","subject":"ya3","topic":"牙髓診斷與病理","meta":"109年第1次第9題","year":109,"session":1,"number":9,"question":"關於牙根外吸收（external root resorption）的敘述，下列何者錯誤？","options":["(A) 臨床上可用buccal object rule來分辨牙根是出現內吸收還是外吸收","(B) 出現在齒頸部牙根外吸收（cervical root resorption）的牙齒，除了牙根表面之外，也可能出現周圍齒槽骨的 吸收","(C) 出現在齒頸部牙根外吸收（cervical root resorption）的牙齒，會失去牙髓活性（pulp vitality）","(D) 出現在齒頸部牙根外吸收（cervical root resorption），外觀看起來可能透出粉紅色（pink spot）的光澤"],"answer":2,"clinical_level":"重點"},{"id":"ya3-109-1-10","subject":"ya3","topic":"牙科解剖與生理","meta":"109年第1次第10題","year":109,"session":1,"number":10,"question":"患者服用下列何種藥物時，可以使用含血管收縮劑的麻藥進行下齒槽神經阻斷麻醉？","options":["(A) anti-depressants","(B) cocaine","(C) medicine for Parkinson disease","(D) anti-coagulants"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-1-11","subject":"ya3","topic":"根管器械","meta":"109年第1次第11題","year":109,"session":1,"number":11,"question":"為了維持根管治療期間在根尖區的通暢性（patency），常使用下列何種器械？","options":["(A) #10 H-file","(B) #10 K-file","(C) #25 H-file","(D) #25 K-file"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-1-12","subject":"ya3","topic":"根管治療程序","meta":"109年第1次第12題","year":109,"session":1,"number":12,"question":"關於雙氯苯雙胍己烷（chlorhexidine, CHX）的敘述，下列何者錯誤？","options":["(A) CHX的pH值約為5.5～7","(B) CHX易於吸附於牙齒表面，這是一種不可逆的反應","(C) 高濃度CHX具殺菌功能，低濃度具抑菌能力","(D) 2% CHX使用於根管沖洗的殺菌效果比0.12%還要好"],"answer":1,"clinical_level":"重點"},{"id":"ya3-109-1-13","subject":"ya3","topic":"根管治療程序","meta":"109年第1次第13題","year":109,"session":1,"number":13,"question":"對於前牙髓腔開擴的敘述，下列何者錯誤？","options":["(A) 舌側肩台（lingual shoulder）的位置約從舌面隆凸（cingulum）延伸至根管開口下2 mm處","(B) 若沒有移除舌側肩台（lingual shoulder），根管銼針會往唇側偏轉，使得腭側根管無法清創完全","(C) 為了容易取得直線開口，前牙應該從唇側面鑽孔，進行髓腔開擴","(D) 為了找尋舌側根管，前牙髓腔開擴應該延伸至唇側面"],"answer":2,"clinical_level":"重點"},{"id":"ya3-109-1-14","subject":"ya3","topic":"根管治療程序","meta":"109年第1次第14題","year":109,"session":1,"number":14,"question":"關於根管用藥氫氧化鈣（calcium hydroxide）在臨床運用時的注意事項，下列敘述何者錯誤？","options":["(A) 調拌時不宜過乾以確保能持續維持殺菌能力","(B) 缺點是即使經由大量沖洗仍不易完全移除","(C) 若未完全清除會干擾根管充填的封閉性及治療品質","(D) 廣效性殺菌能力連Enterococcus faecalis也能有效去除"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-1-15","subject":"ya3","topic":"根管器械","meta":"109年第1次第15題","year":109,"session":1,"number":15,"question":"關於用來測量工作長度的電子根尖定位器（electronic apex locator）的描述，下列何者錯誤？","options":["(A) 不論使用第幾代設備，只要環境控制得當仍能準確定位","(B) 不論根管內是活髓組織或壞死組織均不會影響其判讀","(C) 合併使用X光片照射雖能提升其精確性，但會增加放射線劑量所以並不建議","(D) 儘管廠商的使用說明書提醒不得用於佩戴心律調節器的患者，但實驗證實並不會影響"],"answer":2,"clinical_level":"重點"},{"id":"ya3-109-1-16","subject":"ya3","topic":"根管治療程序","meta":"109年第1次第16題","year":109,"session":1,"number":16,"question":"有關被動式注射筒根管沖洗（passive syringe irrigation）的敘述，何者正確？","options":["(A) 根管沖洗液到達距離大約在沖洗針頭往根尖處約5 mm，因此建議針頭置於髓腔處根管開口（canal orifice），以避免沖洗液超出根管","(B) 針頭粗細的選擇與根管大小有關，根管開口30號，建議使用23 gauge的針頭","(C) 根管沖洗液到達距離大約在沖洗針頭往根尖處約1～1.5 mm，因此建議針頭置於根尖稍短於工作長度，以有 效清潔根管","(D) 以同樣的力量使用較小的針頭能有較強且遠的沖洗渦流，較能有效清潔根管"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-1-17","subject":"ya3","topic":"牙周手術與再生","meta":"109年第1次第17題","year":109,"session":1,"number":17,"question":"關於牙齒蓄意再植（intentional replantation）與自體移植（autotransplantation）的術式，下列選項何者正確？","options":["(A) 選用的自體移植牙齒與接受自體移植牙齒的牙位應在同一象限","(B) 應該同時使用拔牙挺（elevator）與拔牙鉗（forcep）將牙齒小心地拔出","(C) 取出的牙齒應使用含有Hank's Balanced Salt Solution的紗布輕輕擦掉血漬","(D) 牙齒自體移植的術式中咬合調整應小心進行，以免影響傷口的癒合"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-1-18","subject":"ya3","topic":"牙周手術與再生","meta":"109年第1次第18題","year":109,"session":1,"number":18,"question":"下列何者不是以物理性機制達到止血效果的止血劑？","options":["(A) 硫酸鈣（calcium sulfate）","(B) 骨蠟（bone wax）","(C) 止血網（Surgicel）","(D) 止血膠棉（gelatin-based sponges, Gelfoam）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-1-19","subject":"ya3","topic":"根尖手術與再治療","meta":"109年第1次第19題","year":109,"session":1,"number":19,"question":"依據下圖切線設計，其翻瓣手術（flap operation）的名稱為何？","options":["(A) Semilunar incision flap","(B) Envelope flap","(C) Bayonet flap","(D) Ochsenbein-Luebke flap"],"answer":3,"image":"ya3-109-1-19.jpeg","clinical_level":"一般"},{"id":"ya3-109-1-20","subject":"ya3","topic":"牙髓診斷與病理","meta":"109年第1次第20題","year":109,"session":1,"number":20,"question":"對於活髓治療（vital pulp therapy）成果的評估標準，下列敘述何者錯誤？","options":["(A) 一般建議可接受的術後第一次追蹤時間為6至12週","(B) 對牙髓活性測試反應正常、無臨床症狀視為治療成功的條件之一","(C) 牙本質橋（dentinal bridge）的形成與否與治療是否成功無關","(D) X光影像顯示未發育完成的牙根繼續形成、牙根沒有內吸收及根尖周圍炎的現象表示治療成功"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-1-21","subject":"ya3","topic":"根尖手術與再治療","meta":"109年第1次第21題","year":109,"session":1,"number":21,"question":"根據Rud（1972）和Molven（1987）所提出評估牙根尖手術後根尖周圍組織癒合的分類，如果牙根尖放射線 透射範圍變大或未改變，則此情況屬於：","options":["(A) complete healing","(B) incomplete healing","(C) uncertain healing","(D) unsatisfactory healing"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-1-22","subject":"ya3","topic":"根管器械","meta":"109年第1次第22題","year":109,"session":1,"number":22,"question":"造成根管內分離器械（separated instrument）的原因有很多，下列何者錯誤？","options":["(A) 器械彎折或表面看見明顯缺陷而仍繼續使用","(B) 根管過度彎曲或細小卻勉強使用器械","(C) 根管內潤滑度不足仍持續過度使用","(D) 於牙根冠部使用錐度較大的器械，易造成根管器械斷離"],"answer":3,"clinical_level":"重點"},{"id":"ya3-109-1-23","subject":"ya3","topic":"牙髓診斷與病理","meta":"109年第1次第23題","year":109,"session":1,"number":23,"question":"對於因牙周破壞而導致牙周－牙髓病灶（primary periodontal defects of endodontic-periodontal origin lesion）的 患齒，下列敘述何者錯誤？","options":["(A) 對牙髓活性檢測通常沒有反應","(B) 需進行根管治療與牙周治療","(C) 通常可看到V型（V-shaped）的骨頭破壞","(D) 預後主要取決於根管治療的結果"],"answer":3,"clinical_level":"重點"},{"id":"ya3-109-1-24","subject":"ya3","topic":"牙髓診斷與病理","meta":"109年第1次第24題","year":109,"session":1,"number":24,"question":"下圖為左側下顎第二小臼齒術前（pre-OP）、術後（post-OP）與1年回診（1 year f/u）的放射線學檢查結果。 則這顆患齒接受的治療術式是：","options":["(A) 直接覆髓術 （direct pulp capping）","(B) 部分冠髓切除術（partial pulpotomy）","(C) 全冠髓切除術（full pulpotomy）","(D) 部分牙髓摘除術（partial pulpectomy）"],"answer":3,"image":"ya3-109-1-24.jpeg","clinical_level":"一般"},{"id":"ya3-109-1-25","subject":"ya3","topic":"複合樹脂與材料","meta":"109年第1次第25題","year":109,"session":1,"number":25,"question":"關於根管治療過後的牙齒的復形填補，下列敘述何者錯誤？","options":["(A) 使用直接複合樹脂復形填補時，必須採分層增量填補以減少收縮應力","(B) 複合樹脂的收縮量取決於窩洞修形的形狀與C factor","(C) C factor < 3，複合樹脂越容易脫離","(D) 冠部齒質缺損大於1/3的牙齒，避免使用直接複合樹脂復形填補"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-1-26","subject":"ya3","topic":"醫學倫理與法規","meta":"109年第1次第26題","year":109,"session":1,"number":26,"question":"關於牙科治療轉診至其他次專科，下列敘述何者錯誤？","options":["(A) 即使是專科醫師，也會有需要轉診病患至其他專科的時候","(B) 轉診病患，是希望能進行標準化醫療照護（standard of care）","(C) 接受轉診的醫師（referred clinician），應配合原轉診醫師（referring clinician）的治療計劃為病患治療","(D) 受轉診專科的醫療費用應獨立，不受原轉診醫師支配或依其他協議分配"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-1-27","subject":"ya3","topic":"牙髓診斷與病理","meta":"109年第1次第27題","year":109,"session":1,"number":27,"question":"因咬耗（attrition）可能發生的組織變化，不包含下列何者？","options":["(A) 產生硬化牙本質（sclerotic dentin）","(B) 第二級牙本質 （secondary dentin)增生","(C) 被動牙齒萌出（passive eruption）","(D) 牙骨質（cementum）增厚"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-1-28","subject":"ya3","topic":"牙髓診斷與病理","meta":"109年第1次第28題","year":109,"session":1,"number":28,"question":"關於牙釉質去礦化（demineralization）的敘述，下列何者錯誤？","options":["(A) 牙釉質齲齒在鄰接面呈現以牙釉質表層為基底，朝向髓側的錐形脫鈣現象","(B) 表面薄膜（surface pellicle）的有機層對牙菌斑依附於牙釉質扮演重要的角色","(C) 因結晶大小的差異，牙釉質的去礦化速度比牙本質快速","(D) 牙釉質上呈現白斑（white spot）是早期去礦化的徵兆"],"answer":2,"clinical_level":"重點"},{"id":"ya3-109-1-29","subject":"ya3","topic":"牙周疾病與診斷","meta":"109年第1次第29題","year":109,"session":1,"number":29,"question":"關於牙菌斑形成階段的敘述，下列何者正確？①後天性牙釉質薄膜（acquired enamel pellicle）在刷牙後12小 時開始形成 ②12-24小時左右，表面開始出現球狀菌（cocci） ③1-3天左右，絲狀菌叢（Filamentous bacteria）開始生長","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-1-30","subject":"ya3","topic":"牙髓診斷與病理","meta":"109年第1次第30題","year":109,"session":1,"number":30,"question":"下圖是齲齒的組織切片圖，圖中的箭頭所指結構為何？","options":["(A) 被覆性牙本質（mantle dentin）","(B) 修復性牙本質（reparative dentin）","(C) 繼發性牙本質（secondary dentin）","(D) 硬化性牙本質（sclerotic dentin）"],"answer":1,"image":"ya3-109-1-30.jpeg","clinical_level":"一般"},{"id":"ya3-109-1-31","subject":"ya3","topic":"窩洞設計與分類","meta":"109年第1次第31題","year":109,"session":1,"number":31,"question":"下列何種填補狀態會影響牙周健康？①鄰接面填補物的粗糙度 ②鄰接面過度或不足的填補 ③填補物侵入 生物性寬度（biological width）","options":["(A) ①②③","(B) 僅①③","(C) 僅①②","(D) 僅②③"],"answer":0,"clinical_level":"一般"},{"id":"ya3-109-1-32","subject":"ya3","topic":"牙科解剖與生理","meta":"109年第1次第32題","year":109,"session":1,"number":32,"question":"下列何者不會降低牙本質通透性（permeability）？","options":["(A) 施打局部麻藥","(B) 牙本質小管管徑變小","(C) 移除塗抹層（smear layer）","(D) 牙本質液（dentinal fluid）的黏稠度（viscosity）增加"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-1-33","subject":"ya3","topic":"黏著與美學修復","meta":"109年第1次第33題","year":109,"session":1,"number":33,"question":"關於全酸蝕式（total etch）黏著劑與牙釉質之間的鍵結，下列敘述何者錯誤？","options":["(A) 為化學鍵結","(B) 為微機械（micromechanical）鍵結","(C) 藉由樹脂（resin tag）穿透至牙釉質之不規則表面","(D) 相較於與牙本質間鍵結（dentin bonding）較穩定"],"answer":0,"clinical_level":"重點"},{"id":"ya3-109-1-34","subject":"ya3","topic":"窩洞設計與分類","meta":"109年第1次第34題","year":109,"session":1,"number":34,"question":"如圖所示，傳統近心-咬合窩洞製備（MO tooth preparation）中，下列何者通常不會與牙齒表面（tooth surface）相連？","options":["(A) 頰側壁（buccal wall）","(B) 遠心壁（distal wall）","(C) 牙齦壁（gingival wall）","(D) 軸壁（axial wall）"],"answer":3,"image":"ya3-109-1-34.jpeg","clinical_level":"重點"},{"id":"ya3-109-1-35","subject":"ya3","topic":"牙體修形程序","meta":"109年第1次第35題","year":109,"session":1,"number":35,"question":"在鄰接面窩洞修形時，要如何避免橡皮障（rubber dam）撕裂（tear）？","options":["(A) 使用已成型環帶（contoured band）","(B) 使用木楔（wooden wedge）","(C) 使用高容量吸除器（high-volume evacuator）","(D) 使用精修磨針（finishing bur）來修整修復體邊緣"],"answer":1,"clinical_level":"重點"},{"id":"ya3-109-1-36","subject":"ya3","topic":"牙體修形程序","meta":"109年第1次第36題","year":109,"session":1,"number":36,"question":"圖示之gingival margin trimmer應如何編號？","options":["(A) 8─95─1.3─14","(B) 8─14─1.3 ─95","(C) 13─95─8─14","(D) 13─5─8─14"],"answer":2,"image":"ya3-109-1-36.jpeg","clinical_level":"重點"},{"id":"ya3-109-1-37","subject":"ya3","topic":"黏著與美學修復","meta":"109年第1次第37題","year":109,"session":1,"number":37,"question":"高彈性係數（modulus of elasticity）複合樹脂，填補於齒頸部窩洞，鍵結界面剝離（debonding）的主要原因為 何？","options":["(A) 聚合後硬度較低","(B) 填補時流動性較高","(C) 牙齒受力彎折時不易變形","(D) 樹脂聚合時收縮率較大"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-1-38","subject":"ya3","topic":"複合樹脂與材料","meta":"109年第1次第38題","year":109,"session":1,"number":38,"question":"關於牙科複合樹脂中基質（matrix）寡合物（oligomer）的敘述，下列何者錯誤？","options":["(A) BisGMA 的分子量較 UDMA 為高","(B) BisGMA 分解後會產生Bisphenol-A","(C) 可加入TEGDMA 以改變複合樹脂的黏稠度","(D) TEGDMA 中含有芳香烴（aromatic hydrocarbons）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-1-39","subject":"ya3","topic":"黏著與美學修復","meta":"109年第1次第39題","year":109,"session":1,"number":39,"question":"在牙齒比色時，常用的VITA Classical 比色版（A1~D4），下列敘述何者錯誤？","options":["(A) 分類中的A系列偏紅","(B) 分類中的B系列偏黃","(C) 分類中的C系列偏灰","(D) 分類中的D系列偏綠"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-1-40","subject":"ya3","topic":"複合樹脂與材料","meta":"109年第1次第40題","year":109,"session":1,"number":40,"question":"關於複合樹脂完成（finishing）和拋光（polishing）的敘述，下列何者錯誤？","options":["(A) 為了得到更好的視野，在進行此步驟時，可將低速手機的水關閉","(B) 鄰接面牙齦邊緣處之多餘樹脂可利用 12 號手術刀片來修整","(C) 當使用微粒型複合樹脂（microfilled resin）來填補時，使用 fine finishing diamonds 比起 carbide finishing burs 較會對填補物造成表面傷害","(D) 填料顆粒（filler）較小的樹脂，較易得到較光滑的表面"],"answer":2,"clinical_level":"重點"},{"id":"ya3-109-1-41","subject":"ya3","topic":"黏著與美學修復","meta":"109年第1次第41題","year":109,"session":1,"number":41,"question":"關於下圖中齒頸部病灶的敘述，下列何者錯誤？","options":["(A) 深度太靠近牙髓腔，建議先進行活性測試","(B) 有三級牙本質（tertiary dentin）增生，可增強與複合樹脂鍵結","(C) 可能由於刷牙不當造成","(D) 切端牙釉質邊緣可製備斜面（bevel），增強複合樹脂固位"],"answer":1,"image":"ya3-109-1-41.jpeg","clinical_level":"一般"},{"id":"ya3-109-1-42","subject":"ya3","topic":"複合樹脂與材料","meta":"109年第1次第42題","year":109,"session":1,"number":42,"question":"關於溝隙封填的敘述，下列何者錯誤？","options":["(A) 不管小孩或是大人都適合使用溝隙封填來預防齲齒","(B) 不適用於唾液分泌缺乏容易造成齲齒的成人","(C) 建議將牙齒表面清理乾淨，再用磷酸進行處理","(D) 填補後不需要進一步拋光"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-1-43","subject":"ya3","topic":"複合樹脂與材料","meta":"109年第1次第43題","year":109,"session":1,"number":43,"question":"關於複合樹脂進行直接填補時的缺點，下列敘述何者錯誤？","options":["(A) 樹脂容易吸水產生水解（hydrolytic breakdown）","(B) 磨耗抵抗力較汞齊低","(C) 複合樹脂的聚合收縮可能會造成術後敏感","(D) 牙齒的熱膨脹係數比樹脂高"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-1-44","subject":"ya3","topic":"窩洞設計與分類","meta":"109年第1次第44題","year":109,"session":1,"number":44,"question":"哪一類的固位釘（pin）在牙本質內有較好的固位性？","options":["(A) cemented pin","(B) friction-locked pin","(C) self-threaded pin","(D) amalgam pin"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-1-45","subject":"ya3","topic":"窩洞設計與分類","meta":"109年第1次第45題","year":109,"session":1,"number":45,"question":"汞齊充填的窩洞修形，咬合面窩緣角（occlusal cavosurface angle）最理想的角度為下列何者？","options":["(A) 70～80 度","(B) 90～100 度","(C) 110～120 度","(D) 130～140 度"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-1-46","subject":"ya3","topic":"牙體修形程序","meta":"109年第1次第46題","year":109,"session":1,"number":46,"question":"操作牙釘槽（pinhole）時，不慎穿透牙髓，下列處置何者不當？","options":["(A) 止血後，在牙釘槽開口覆蓋氫氧化鈣襯底","(B) 治療完成後告知病人實情和處理方式","(C) 仍置入牙釘於牙髓貫穿處","(D) 定期以X光片評估，病人有不適時通知牙醫師"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-1-47","subject":"ya3","topic":"窩洞設計與分類","meta":"109年第1次第47題","year":109,"session":1,"number":47,"question":"下列那一種狀況不是做金屬嵌體的禁忌症？","options":["(A) 高齲齒率","(B) 年輕的病患","(C) 美觀的考量","(D) 大型窩洞的填補"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-1-48","subject":"ya3","topic":"黏著與美學修復","meta":"109年第1次第48題","year":109,"session":1,"number":48,"question":"在金屬嵌體的牙齒修形有倒凹（undercut），預計以樹脂黏合劑黏著時，下列何者不可作為封凹（block out） 的材料？①複合樹脂（composite resin） ②氧化鋅丁香油酚黏合劑（zinc oxide-eugenol cement） ③樹脂 強化玻璃離子體（resin-reinforced glass ionomer）","options":["(A) ①②③","(B) 僅①","(C) 僅②③","(D) 僅②"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-1-49","subject":"ya3","topic":"窩洞設計與分類","meta":"109年第1次第49題","year":109,"session":1,"number":49,"question":"下圖是鑄造金（cast-gold）嵌體的製作，X所指牙髓壁溝設計（slot-preparation）的敘述，下列何者錯誤？","options":["(A) 可有效增加固位性（retention）","(B) 可使用 No. 169 鎢鋼鑽針（carbide bur）","(C) Faciolingually 的寬度約為2 mm","(D) 深度應小於 1 mm"],"answer":3,"image":"ya3-109-1-49.jpeg","clinical_level":"一般"},{"id":"ya3-109-1-50","subject":"ya3","topic":"黏著與美學修復","meta":"109年第1次第50題","year":109,"session":1,"number":50,"question":"關於在前牙美學上的比例，下列敘述何者正確？①黃金比例的產生是由於有60%的人具有此比例 ②所謂的 黃金比例即是犬齒：側門齒：正中門齒為0.618 : 1 : 1.618 ③側門齒的寬長比（width-to-length ratio）通常為 0.75~0.80 ④有磨耗的正中門齒的寬長比（width-to-length ratio）會比未磨耗者高","options":["(A) ①②③","(B) ①②④","(C) ①③④","(D) ②③④"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-1-51","subject":"ya3","topic":"黏著與美學修復","meta":"109年第1次第51題","year":109,"session":1,"number":51,"question":"關於理想牙齒美觀的敘述，下列何者錯誤？","options":["(A) 上顎正中門牙長度約 10～11 mm","(B) 超過40歲後，門牙露出的量逐漸減少","(C) 上顎前牙各齒間的切緣楔隙（incisal embrasures）大小必須一致","(D) 上顎正中門齒周圍的牙齦邊緣呈現拋物線狀，最高點（gingival zenith）偏遠心方向"],"answer":2,"clinical_level":"重點"},{"id":"ya3-109-1-52","subject":"ya3","topic":"牙髓診斷與病理","meta":"109年第1次第52題","year":109,"session":1,"number":52,"question":"下列何者情況在執行失活齒內漂白（internal bleaching）時，易造成牙根外吸收（external root resorption）？","options":["(A) 使用10%碳醯胺過氧化物（carbamide peroxide）為漂白劑","(B) 加熱處理","(C) 選用玻璃離子體（glass ionomer）作為齒頸部之屏障（barrier）","(D) 用過硼酸鈉（sodium perborate）與蒸餾水混合為漂白劑"],"answer":1,"clinical_level":"重點"},{"id":"ya3-109-1-53","subject":"ya3","topic":"牙科解剖與生理","meta":"109年第1次第53題","year":109,"session":1,"number":53,"question":"下列何者是齒槽骨上篩板（cribriform plate）的穿孔（perforations）？","options":["(A) Oxytalan fibers的插入","(B) Sharpey's fibers的插入","(C) Haversian canals的開口","(D) Volkmann's canals的開口"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-1-54","subject":"ya3","topic":"牙周手術與再生","meta":"109年第1次第54題","year":109,"session":1,"number":54,"question":"牙周手術後一個月內，於手術區的牙齒搖動性增加是由於手術期間那一個地方損傷造成？","options":["(A) 上皮附連（epithelial attachment）","(B) 牙齦結締組織的網狀層（reticular layer）","(C) 牙周韌帶（periodontal ligament）","(D) 牙齦結締組織的乳突層（papillary layer）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-1-55","subject":"ya3","topic":"牙科解剖與生理","meta":"109年第1次第55題","year":109,"session":1,"number":55,"question":"關於牙齦結締組織結構的敘述，下列何者錯誤？","options":["(A) 蛋白多醣（proteoglycans）為基質的成分，呈現過碘酸希夫染色陽性反應（periodic acid-Schiff-positive reaction）","(B) 牙齦主要的結締組織纖維是第一型膠原纖維","(C) 第三型膠原纖維用以連續基底膜的纖維與血管壁","(D) 纖維黏連蛋白（fibronectin）為基質的成分，可幫助調節細胞的黏著與移動"],"answer":2,"clinical_level":"重點"},{"id":"ya3-109-1-56","subject":"ya3","topic":"牙科解剖與生理","meta":"109年第1次第56題","year":109,"session":1,"number":56,"question":"關於牙齦上皮（gingival epithelium）的敘述，下列何者錯誤？","options":["(A) 由複層鱗狀上皮所組成","(B) 在天生的宿主防禦（innate host defense）扮演主動的角色","(C) 其中的黑色素細胞（melanocytes）是一種透明細胞（clear cells）","(D) 角質細胞分化過程，張力纖維（tonofilament）有減少的現象"],"answer":3,"clinical_level":"重點"},{"id":"ya3-109-1-57","subject":"ya3","topic":"牙周手術與再生","meta":"109年第1次第57題","year":109,"session":1,"number":57,"question":"關於多根牙的根叉二級病變，下列術式的治療何者結果最不可預測？","options":["(A) 下顎大臼齒進行引導組織再生術（GTR）","(B) 下顎大臼齒隧道成形術（tunnel preparation）","(C) 上顎大臼齒牙根切除術（root resection）","(D) 上顎大臼齒進行引導組織再生術（GTR）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-1-58","subject":"ya3","topic":"牙周疾病與診斷","meta":"109年第1次第58題","year":109,"session":1,"number":58,"question":"關於侵襲性牙周炎最主要特徵的敘述，下列何者正確？","options":["(A) 好發於糖尿病第I型的病人","(B) 口腔內有多處不良的牙齦下補綴物及口腔衛生不好","(C) 最容易發生於heavy smoker","(D) 患者常有phagocyte功能異常"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-1-59","subject":"ya3","topic":"牙周疾病與診斷","meta":"109年第1次第59題","year":109,"session":1,"number":59,"question":"下列藥物何者最不會引起牙齦腫大（gingival enlargement）？","options":["(A) 抗痙攣藥物（anticonvulsants）","(B) 免疫抑制劑（immunosuppressants）","(C) 雙磷酸鹽類藥物（bisphosphonates）","(D) 鈣離子阻斷劑（calcium channel blockers）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-1-60","subject":"ya3","topic":"牙周疾病與診斷","meta":"109年第1次第60題","year":109,"session":1,"number":60,"question":"關於慢性牙周膿瘍（chronic periodontal abscess）的敘述，下列何者錯誤？","options":["(A) 通常伴隨牙齦腫大和疼痛","(B) 有滲出物（exudate）的產生","(C) 膿瘍位置通常和可探測到的牙周囊袋位置相同","(D) 通常不會有竇管（sinus tract）的形成"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-1-61","subject":"ya3","topic":"牙周疾病與診斷","meta":"109年第1次第61題","year":109,"session":1,"number":61,"question":"單就牙周齒槽骨喪失改變牙齒旋轉中心位置，如附圖。考量咬合力對牙齒預後（prognosis）的影響，下列何 者正確？","options":["(A) 甲牙齒預後較乙牙齒好","(B) 乙牙齒預後較甲牙齒好","(C) 甲牙齒與乙牙齒預後一樣差","(D) 旋轉中心位置不影響預後"],"answer":0,"image":"ya3-109-1-61.jpeg","clinical_level":"一般"},{"id":"ya3-109-1-62","subject":"ya3","topic":"牙周疾病與診斷","meta":"109年第1次第62題","year":109,"session":1,"number":62,"question":"Cyclic or permanent neutropenia, leukocyte adhesion deficiency（LAD）、Papillon-Lefèvre syndrome（PLS）、 Down syndrome、Chediak-Steinbrinck-Higashi syndrome等具有下列何種共同特性？","options":["(A) PMNs的數目及功能異常","(B) 具hyperinflammatory monocyte phenotype, MФ+","(C) cathepsin C 基因突變","(D) 低磷酸酶"],"answer":0,"clinical_level":"一般"},{"id":"ya3-109-1-63","subject":"ya3","topic":"牙周疾病與診斷","meta":"109年第1次第63題","year":109,"session":1,"number":63,"question":"一位中年男性在上顎側門牙有嚴重牙周炎，下列何者是最可能的解剖學上因素？","options":["(A) 高繫帶附著（frenum attachment）","(B) 發育溝（developmental groove）","(C) 牙釉突（enamel projection）","(D) 牙根凹陷（root concavity）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-1-64","subject":"ya3","topic":"牙周疾病與診斷","meta":"109年第1次第64題","year":109,"session":1,"number":64,"question":"關於刷牙（brushing）的敘述，下列何者錯誤？","options":["(A) 以貝氏刷牙法（Bass method）刷牙，可能造成牙齦萎縮","(B) 手動刷牙的效率與力道（brushing force）呈線性正相關","(C) 當手動刷牙力道超過300g時，容易造成牙齦疼痛與牙齦流血","(D) 刷牙的清潔效率與刷頭設計、個人手部靈巧度有關"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-1-65","subject":"ya3","topic":"牙周非手術治療","meta":"109年第1次第65題","year":109,"session":1,"number":65,"question":"下列器械何者最適合選擇使用治療右上第二大臼齒近心側？","options":["(A) Gracey # 1-2","(B) Gracey #13-14","(C) Gracey #15-16","(D) Gracey #17-18"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-1-66","subject":"ya3","topic":"植牙學","meta":"109年第1次第66題","year":109,"session":1,"number":66,"question":"關於冷凍乾燥異體移植骨（FDBA）與脫鈣冷凍乾燥異體移植骨（DFDBA）的敘述，下列何者正確？","options":["(A) FDBA被認為具引導骨生成性質（osteoconduction），DFDBA則具誘導骨生成性質（osteoinduction）","(B) 經過萃取過程，FDBA可釋放出BMP-2，DFDBA則無","(C) 兩者均呈現不透射線性（radiopaque）","(D) 使用來自皮質骨（cortical bone）的DFDBA所造成之骨內缺損填滿比例比來自髓質骨（cancellous bone）高"],"answer":0,"clinical_level":"一般"},{"id":"ya3-109-1-67","subject":"ya3","topic":"牙周手術與再生","meta":"109年第1次第67題","year":109,"session":1,"number":67,"question":"施行牙根切除術（root resection）的決定因素，下列何者錯誤？","options":["(A) 牙根的開展程度","(B) 牙根長度與型式","(C) 牙根切開後，單一牙根動搖程度","(D) 牙根切開後，單一牙根角化黏膜量"],"answer":3,"clinical_level":"重點"},{"id":"ya3-109-1-68","subject":"ya3","topic":"牙周手術與再生","meta":"109年第1次第68題","year":109,"session":1,"number":68,"question":"關於根向移位翻瓣手術（apically displaced flap）的敘述，下列何者錯誤？","options":["(A) 在牙根面（radicular surface）上做垂直切線，可得到較好的手術視野","(B) 將瓣膜放置在牙齒與骨頭交界處，可避免牙周囊袋的再復發或骨頭暴露","(C) 此手術可消除牙周囊袋，並得到較寬的附連牙齦","(D) 當骨質有開裂（dehiscence）時，需使用全皮層翻瓣術（full-thickness flap）"],"answer":0,"clinical_level":"重點"},{"id":"ya3-109-1-69","subject":"ya3","topic":"牙周手術與再生","meta":"109年第1次第69題","year":109,"session":1,"number":69,"question":"下列Miller牙齦萎縮的類型，經過手術後，何者可較有機會達成完全牙根覆蓋（complete root coverage）？","options":["(A) I & II","(B) II & III","(C) II & IV","(D) I & IV"],"answer":0,"clinical_level":"一般"},{"id":"ya3-109-1-70","subject":"ya3","topic":"牙周手術與再生","meta":"109年第1次第70題","year":109,"session":1,"number":70,"question":"關於牙周手術敷料的敘述，下列何者錯誤？","options":["(A) 透過保護手術區域的組織而非提供癒合的因子來幫助傷口癒合","(B) 盡量減少術後的出血和和感染","(C) 避免因為接觸傷口區域所造成的不適和疼痛感","(D) 常用的Coe-Pak牙周敷料成分內含丁香油酚"],"answer":3,"clinical_level":"重點"},{"id":"ya3-109-1-71","subject":"ya3","topic":"牙周手術與再生","meta":"109年第1次第71題","year":109,"session":1,"number":71,"question":"下列何者不是牙周可吸收再生膜（bioresorbable barrier membranes）的缺點？","options":["(A) 容易過早水解","(B) 上皮細胞容易長入再生膜屏障區域","(C) 充填之材料易早期喪失","(D) 需進行第二次手術將再生膜移除"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-1-72","subject":"ya3","topic":"牙周手術與再生","meta":"109年第1次第72題","year":109,"session":1,"number":72,"question":"關於牙周組織再生術的敘述，下列何者錯誤？","options":["(A) 下顎臼齒頰側class II furcation合併three-walled defects，是做牙周再生的理想病例","(B) 臨床實驗證實citric acid或fibronectin處理牙根面，可有意義的促進牙周再生","(C) wide class III furcations及少於two-walled的infrabony defects，其牙周再生之成功有限","(D) gingivectomy 術後組織癒合是secondary intention"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-1-73","subject":"ya3","topic":"牙周非手術治療","meta":"109年第1次第73題","year":109,"session":1,"number":73,"question":"關於維持期（maintenance phase），若病人有複雜之補綴物，牙周破壞到牙齦分岔處，病人的動機和配合度不 高，第一年會建議病人多久定期回診檢查一次？","options":["(A) 1～2個月","(B) 3個月","(C) 6個月","(D) 12個月"],"answer":0,"clinical_level":"重點"},{"id":"ya3-109-1-74","subject":"ya3","topic":"植牙學","meta":"109年第1次第74題","year":109,"session":1,"number":74,"question":"關於人工植體的維護治療之敘述，下列何者正確？","options":["(A) 可以使用酸性含氟清潔劑（acidic fluoride prophylactic agents）","(B) 可以使用噴砂去除牙結石","(C) 可以使用金屬超音波去除植體表面之牙結石","(D) 可以使用塑膠刮刀去除植體表面之牙結石"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-1-75","subject":"ya3","topic":"牙科解剖與生理","meta":"109年第1次第75題","year":109,"session":1,"number":75,"question":"對於白血病患者的牙科治療考量，下列敘述何者最正確？","options":["(A) 建議至少在化療前10天拔除無法保留或未來容易感染的牙齒","(B) 急性發炎期時不建議進行任何牙周病治療","(C) 若有口腔念珠菌感染時可使用nystatin懸浮液漱口，濃度80,000 U/mL，一天使用4次","(D) 慢性白血病的患者的牙周病治療可與常人無異"],"answer":0,"clinical_level":"一般"},{"id":"ya3-109-1-76","subject":"ya3","topic":"牙科解剖與生理","meta":"109年第1次第76題","year":109,"session":1,"number":76,"question":"當凝血功能異常的患者進行牙周病治療時，下列何者敘述較為正確？","options":["(A) 肝臟疾病及長期使用抗生素的患者，門診手術前需監測INR（international normalized ratio）及血小板數量","(B) 溫韋伯氏疾病（Von Willebrand disease）患者，需監控PT（prothrombin time），以評估牙周處置項目","(C) 牙科門診常用止血劑為tranexamic acid及eugenol","(D) 對於服用抗凝血藥物的患者，進行非手術性治療時其INR數值控制在1.5到2.0較佳"],"answer":0,"clinical_level":"一般"},{"id":"ya3-109-1-77","subject":"ya3","topic":"牙科解剖與生理","meta":"109年第1次第77題","year":109,"session":1,"number":77,"question":"關於系統性疾病的敘述，下列何者錯誤？","options":["(A) 酮病（ketosis）常發生在非胰島素依賴性糖尿病患者","(B) 罹患慢性阻塞性肺病不可使用鎮靜與麻醉劑來減緩病患焦慮","(C) 嚴重肝病變患者接受結石刮除/牙根整平術之前應檢驗PT, PTT, platelet count, bleeding time","(D) 洗腎患者宜約洗腎隔天進行治療並避免開立非類固醇抗發炎藥（NSAID）"],"answer":0,"clinical_level":"重點"},{"id":"ya3-109-1-78","subject":"ya3","topic":"植牙學","meta":"109年第1次第78題","year":109,"session":1,"number":78,"question":"關於人工植體和自然牙周圍組織的比較之敘述，下列何者錯誤？","options":["(A) 人工植體的游離牙齦深度比自然牙較深","(B) 人工植體和齒槽骨是直接密合的","(C) 人工植體比自然牙周邊牙齦含有較少量的膠原蛋白和較多量的纖維母細胞","(D) 人工植體周邊牙齦內部的膠原蛋白纖維皆互相平行，自然牙內部膠原蛋白纖維成交錯走向"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-1-79","subject":"ya3","topic":"植牙學","meta":"109年第1次第79題","year":109,"session":1,"number":79,"question":"研究顯示，持續一分鐘的時間，會引起成骨細胞壞死的臨界攝氏溫度是幾度？","options":["(A) 37","(B) 43","(C) 47","(D) 51"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-1-80","subject":"ya3","topic":"植牙學","meta":"109年第1次第80題","year":109,"session":1,"number":80,"question":"若植牙承受的咬合負荷大於其乘載能力，則可能導致機械性或生物性的失敗。以下敘述何者錯誤？","options":["(A) 機械性失敗的狀況包括植牙螺絲彎曲、鬆脫甚至斷裂","(B) 生物性失敗的狀況包括持續發展的周圍骨喪失，甚至植體脫落","(C) 根據2000年Pierrisnard等的研究指出，植體長度增加有助於減低加諸於植體的應力","(D) 眾多有限元素分析研究皆指出，非植牙長軸的力量會增加應力集中於植體齒頸部"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-2-1","subject":"ya3","topic":"醫學倫理與法規","meta":"109年第2次第1題","year":109,"session":2,"number":1,"question":"病患因牙痛前來求診，醫師本著良好的臨床知識及技術，謹慎地執行診斷及治療，避免讓病患承擔任何不當的 風險，即是在履行醫學倫理的那一原則？","options":["(A) 病患自主原則","(B) 不傷害原則","(C) 行善原則","(D) 公平正義原則"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-2-2","subject":"ya3","topic":"牙髓診斷與病理","meta":"109年第2次第2題","year":109,"session":2,"number":2,"question":"深部的齲齒（deep caries lesions）容易造成牙髓傷害，是因為深部區域牙本質小管（dentinal tubules）產生下列 何種改變？","options":["(A) 牙本質小管密度減少","(B) 牙本質小管的滲透力增加","(C) 牙本質小管的直徑減少","(D) 牙本質小管的長度增加"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-2-3","subject":"ya3","topic":"牙髓診斷與病理","meta":"109年第2次第3題","year":109,"session":2,"number":3,"question":"有關牙髓的敘述，下列何者正確？","options":["(A) 少細胞區（cell-poor zone）可發現微血管與具髓鞘之神經纖維交織穿越","(B) 少細胞區（cell-poor zone）的功能為協助修復性牙本質的生成","(C) 多細胞區（cell-rich zone）的未分化之間葉幹細胞提供了牙本質的再生來源","(D) 多細胞區（cell-rich zone）緊鄰造牙本質細胞層（odontoblast layer），提供牙本質生成所需"],"answer":2,"clinical_level":"重點"},{"id":"ya3-109-2-4","subject":"ya3","topic":"牙髓診斷與病理","meta":"109年第2次第4題","year":109,"session":2,"number":4,"question":"有關牙髓神經傳導之敘述，下列何者正確？","options":["(A) 90%之A型神經纖維為A-δ型神經纖維","(B) 牙髓發育中髓鞘神經纖維（myelinated fiber）較無髓鞘神經纖維（unmyelinated fiber）早","(C) C型神經纖維為髓鞘神經纖維（myelinated fiber）","(D) 牙本質小管內液體流動對C型神經纖維之影響較大"],"answer":0,"clinical_level":"重點"},{"id":"ya3-109-2-5","subject":"ya3","topic":"牙髓診斷與病理","meta":"109年第2次第5題","year":109,"session":2,"number":5,"question":"下圖為使用不同偏移角度對上顎右側後牙所拍攝的X光片。依據Weine的分類定義，右上第二小臼齒的根管形 態是屬於那一型？而箭頭所指的是第一大臼齒的那個根管？","options":["(A) 第二型根管形態，近心頰側根管（MB canal）","(B) 第二型根管形態，第二近心頰側根管（MB2 canal）","(C) 第三型根管形態，近心頰側根管（MB canal）","(D) 第三型根管形態，第二近心頰側根管（MB2 canal）"],"answer":1,"image":"ya3-109-2-5.jpeg","clinical_level":"一般"},{"id":"ya3-109-2-6","subject":"ya3","topic":"牙髓診斷與病理","meta":"109年第2次第6題","year":109,"session":2,"number":6,"question":"最常存在於原發性根管內感染（primay intraradicular infection）之微生物為何？","options":["(A) 革蘭式陽性菌（gram-positive bacteria）","(B) 革蘭式陰性菌（gram-negative bacteria）","(C) 兼性厭氧菌（facultative anaerobes）","(D) 兼性嗜氧菌（facultative aerobes）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-2-7","subject":"ya3","topic":"牙髓診斷與病理","meta":"109年第2次第7題","year":109,"session":2,"number":7,"question":"有關裂齒（cracked tooth）與垂直牙根斷裂（vertical root fracture）的敘述，何者正確？","options":["(A) 裂齒大部分為頰舌側走向","(B) 垂直牙根斷裂通常起始點為牙根表面延伸至根管內壁上","(C) 裂齒常發生在下顎第二大臼齒","(D) 垂直牙根斷裂常在近遠心側有特別深的牙周囊袋"],"answer":2,"clinical_level":"重點"},{"id":"ya3-109-2-8","subject":"ya3","topic":"牙齒外傷處理","meta":"109年第2次第8題","year":109,"session":2,"number":8,"question":"關於乳牙齒列所遭受的牙科創傷，處理方式往往不同於恆牙齒列，下列關於乳牙齒列牙科創傷的敘述，何者正 確？","options":["(A) 最常見的乳牙齒列之牙科外傷是脫槽（avulsions）齒","(B) 即使是牙冠－牙根斷裂（crown-root fractures）的乳齒，也不一定需要拔除","(C) 針對乳牙齒列，很少對其牙齒進行固定（splinting），除非涉及到齒槽骨折（alveolar fractures）","(D) 乳牙齒列如果發生內縮鬆脫（intrusive luxation），不需做額外的檢查治療，等它自然復位即可"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-2-9","subject":"ya3","topic":"牙齒外傷處理","meta":"109年第2次第9題","year":109,"session":2,"number":9,"question":"下列何者因牙齒外傷後導致的牙根吸收，主要是由壞死感染的牙髓所引發？","options":["(A) 取代性牙根外吸收 （external replacement root resorption）","(B) 齒頸部牙根外吸收（external cervical root resorption）","(C) 發炎性牙根外吸收（external inflammatory root resorption）","(D) 牙根內吸收（internal root resorption）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-2-10","subject":"ya3","topic":"牙齒外傷處理","meta":"109年第2次第10題","year":109,"session":2,"number":10,"question":"下列那些外傷牙齒緊急處理時，可以採用部分冠髓切除術（partial pulpotomy）？","options":["(A) 非複雜性牙冠斷裂且根尖未閉合","(B) 非複雜性牙冠斷裂且根尖已閉合","(C) 複雜性牙冠斷裂且根尖已閉合，可用複合樹脂填補者","(D) 複雜性牙冠斷裂且根尖已閉合，需以牙冠復形者"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-2-11","subject":"ya3","topic":"牙科解剖與生理","meta":"109年第2次第11題","year":109,"session":2,"number":11,"question":"進行下顎第一大臼齒局部麻醉時，除了使用lidocaine作下齒槽神經阻斷麻醉以外，也可以附帶使用那一種麻 醉藥作浸潤麻醉，以達到最佳麻醉效果？","options":["(A) prilocaine","(B) mepivacaine","(C) bupivacaine","(D) articaine"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-2-12","subject":"ya3","topic":"根管治療程序","meta":"109年第2次第12題","year":109,"session":2,"number":12,"question":"根管治療時，若以傳統注射針頭搭配被動（passive）方式來沖洗，沖洗液射程往往最多只能比針頭尖端多幾 mm？","options":["(A) 1","(B) 3","(C) 5","(D) 7"],"answer":0,"clinical_level":"一般"},{"id":"ya3-109-2-13","subject":"ya3","topic":"根管治療程序","meta":"109年第2次第13題","year":109,"session":2,"number":13,"question":"關於C型根管系統（C-shaped canal system）的敘述，下列何者錯誤？","options":["(A) 亞洲人種的發生率高於歐洲人","(B) 常發生於下顎第二大臼齒","(C) 具C型根管系統的牙齒，通常在髓室底（pulpal floor）就呈現C型開口","(D) 根管治療時，牙根穿孔容易發生在根管舌側"],"answer":2,"clinical_level":"重點"},{"id":"ya3-109-2-14","subject":"ya3","topic":"根管治療程序","meta":"109年第2次第14題","year":109,"session":2,"number":14,"question":"關於次氯酸鈉意外（sodium hypochlorite accident），下列敘述何者正確？","options":["(A) 因沖洗針頭使用不小心，導致NaOCl滲漏或噴灑至病患衣物及皮膚所致","(B) 病患當下產生劇痛（severe pain）、出血以及局部組織腫脹等症狀，是一種症候突發（flare-up）","(C) 可能會有組織壞死、感覺異常（paresthesia）、或繼發性的感染（secondary infection）發生","(D) 必須開立類固醇類藥物，以控制感染及疼痛"],"answer":2,"clinical_level":"重點"},{"id":"ya3-109-2-15","subject":"ya3","topic":"根管治療程序","meta":"109年第2次第15題","year":109,"session":2,"number":15,"question":"關於根管修形過程中應該要達到的理想機械修形目標，下列敘述何者錯誤？","options":["(A) 修形後的根管形態不僅要完整，並且要維持原始根管的中心性","(B) 若修形過程中發生根管偏誤（transportation）等情況，即使予以修正後仍會影響根管治療的結果","(C) 修形後的根管形態，不論在齒頸部及根尖部的齒質都不能有弱化的現象以預防牙根斷裂","(D) 為了避免根管的過度修形，充分的髓腔開擴及適度擴大根管冠狀端三分之一處非常重要"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-2-16","subject":"ya3","topic":"牙體修形程序","meta":"109年第2次第16題","year":109,"session":2,"number":16,"question":"No.212橡皮障夾（No. 212 clamp）是一種無翼的蝴蝶形橡皮障夾（wingless butterfly clamp），下列何種是正 確的操作方法？","options":["(A) 橡皮障、橡皮障夾和支架（frame）一組同時夾上牙齒","(B) 牙齒先夾上橡皮障夾固定，再套上橡皮障，最後固定支架","(C) 牙齒先套上橡皮障和固定支架，最後再夾上橡皮障夾","(D) 牙齒先夾上橡皮障夾，再套上橡皮障和固定支架"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-2-17","subject":"ya3","topic":"根管器械","meta":"109年第2次第17題","year":109,"session":2,"number":17,"question":"相對於不鏽鋼根管銼，鎳鈦合金根管銼的彈性係數（modulus of elasticity）是不鏽鋼根管銼之多少倍？","options":["(A) 4至5倍","(B) 8至10倍","(C) 1/4至1/5倍","(D) 1/8至1/10倍"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-2-18","subject":"ya3","topic":"根尖手術與再治療","meta":"109年第2次第18題","year":109,"session":2,"number":18,"question":"從牙根尖組織解剖結構的角度來看，在牙根尖手術（apical surgery）中，最適當的切根為與牙齒長軸的角度 為何？","options":["(A) 呈90度角","(B) 呈30度角","(C) 呈45度角","(D) 呈60度角"],"answer":0,"clinical_level":"一般"},{"id":"ya3-109-2-19","subject":"ya3","topic":"根尖手術與再治療","meta":"109年第2次第19題","year":109,"session":2,"number":19,"question":"下列何者不屬於牙根尖手術可以使用的逆充填材料（retrograde root-end filling materials）？","options":["(A) glass-ionomer cement（GIC）","(B) resin","(C) bio-ceramic","(D) MTA"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-2-20","subject":"ya3","topic":"根尖手術與再治療","meta":"109年第2次第20題","year":109,"session":2,"number":20,"question":"如下圖所示，若欲針對下顎門齒區的根尖病灶（apical lesion）進行牙根尖手術（apical surgery）治療，最適 合的翻瓣設計為何？","options":["(A) 緣下曲線翻瓣（submarginal curved flap）","(B) Ochsenbein-Luebke翻瓣（Ochsenbein-Luebke flap）","(C) 方形翻瓣（rectangular flap）","(D) 三角形翻瓣（triangular flap）"],"answer":2,"image":"ya3-109-2-20.jpeg","clinical_level":"一般"},{"id":"ya3-109-2-21","subject":"ya3","topic":"根管治療程序","meta":"109年第2次第21題","year":109,"session":2,"number":21,"question":"根據Friedman和Mor的研究指出，關於根管治療預後的敘述，何者錯誤？","options":["(A) 治療前無根尖周圍炎，初次接受根管治療的牙齒，十年追蹤的治癒率平均為九成以上","(B) 治療前無根尖周圍炎，接受根管重新治療的牙齒，十年追蹤的治癒率平均為九成以上","(C) 治療前有根尖周圍炎，初次接受根管治療的牙齒，十年追蹤的治癒率平均約為八成","(D) 治療前有根尖周圍炎，接受根管重新治療的牙齒，十年追蹤的治癒率降為七成以下"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-2-22","subject":"ya3","topic":"根管治療程序","meta":"109年第2次第22題","year":109,"session":2,"number":22,"question":"根管重新治療時欲移除根管內的馬來膠封填材，較不建議使用下列何種方式？","options":["(A) 熱源","(B) 溶劑","(C) 超音波器械","(D) 高速手機鑽針"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-2-23","subject":"ya3","topic":"根管治療程序","meta":"109年第2次第23題","year":109,"session":2,"number":23,"question":"下列何者不是造成根管治療後牙齒發生牙冠變色的原因？","options":["(A) 病人有服用四環黴素的病史","(B) 根管內有未移除的壞死牙髓組織","(C) 冠部填補物有微滲漏（microleakage）情形","(D) 使用含有金屬成分的根管封填劑（canal sealer）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-109-2-24","subject":"ya3","topic":"牙髓診斷與病理","meta":"109年第2次第24題","year":109,"session":2,"number":24,"question":"根管－牙周疾病（endo-perio combined lesion）的分類中，下列何種病變具有活性（vital）牙髓 ？","options":["(A) Primary endodontic lesion","(B) Primary endodontic lesion with secondary periodontal involvement","(C) Primary periodontal lesion","(D) Primary periodontal lesion with secondary endodontic involvement"],"answer":2,"clinical_level":"重點"},{"id":"ya3-109-2-25","subject":"ya3","topic":"根管器械","meta":"109年第2次第25題","year":109,"session":2,"number":25,"question":"有關K-file和H-file的敘述，下列何者正確？","options":["(A) K-file修形根管時銼修（filing）比鑽修（reaming），較不易導致根管中心軸偏移","(B) 當K-file的凹槽（flutes）排列變得較為緊密或疏鬆，雖然已形成永久變形仍能使用","(C) 使用H-file時，應避免使用銼修（filing），因為器械斷裂可能性極高","(D) H-file使用時應儘量避免預先彎曲器械，因為其壓力點可能會增加疲勞斷裂的可能性"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-2-26","subject":"ya3","topic":"黏著與美學修復","meta":"109年第2次第26題","year":109,"session":2,"number":26,"question":"隨著美學意識抬頭，漂白（bleaching）越來越被國人重視。關於持續式漂白法（walking bleaching），下列敘 述何者正確？","options":["(A) 剛完成良好根管治療根尖牙周炎（apical periodontits）尚未癒合的牙齒，應待癒合後才可進行漂白","(B) 一些有缺陷的修復體（restoration）必須重新再治療，因為有時牙齒變色是不良修復體所造成的","(C) 根管填充物應移除到相當於比頰側牙齦略低的位置，建議使用次氯酸鈉或是磷酸清洗根管","(D) 過硼酸鈉（sodium perborate）和雙氧水混合，比和蒸餾水混合漂白時間更快，長時間觀察漂白結果較好"],"answer":1,"clinical_level":"重點"},{"id":"ya3-109-2-27","subject":"ya3","topic":"窩洞設計與分類","meta":"109年第2次第27題","year":109,"session":2,"number":27,"question":"初萌發的大臼齒咬頭處牙釉質（enamel）的平均厚度約為多少 mm？","options":["(A) 1.0～1.5","(B) 1.6～2.1","(C) 2.5～3.0","(D) 3.5～4.0"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-2-28","subject":"ya3","topic":"牙髓診斷與病理","meta":"109年第2次第28題","year":109,"session":2,"number":28,"question":"在挖除齲齒的過程中，若有牙髓暴露導致出血，下列何種溶液最能達到抗菌以及有效抑制出血的目的？","options":["(A) 生理食鹽水（normal saline）","(B) 腎上腺素（epinephrine）","(C) 雙氯苯雙胍己烷（chlorhexidine solution）","(D) 次氯酸鈉（sodium hypochlorite）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-2-29","subject":"ya3","topic":"牙科解剖與生理","meta":"109年第2次第29題","year":109,"session":2,"number":29,"question":"牙本質去礦化的臨界酸鹼值（critical pH value）為多少？","options":["(A) 4.5","(B) 5.2","(C) 5.5","(D) 6.2"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-2-30","subject":"ya3","topic":"窩洞設計與分類","meta":"109年第2次第30題","year":109,"session":2,"number":30,"question":"關於牙本質齲齒的敘述，下列何者錯誤？","options":["(A) 牙本質齲齒的受影響層（affected zone）和正常牙本質礦化程度一樣","(B) 受影響層（affected zone）可不需完全移除","(C) 可利用 1% acid red 52 對感染層（infected zone）做選擇性染色","(D) 當齲齒進展較慢時，較易形成硬化牙本質（sclerotic dentin）"],"answer":0,"clinical_level":"重點"},{"id":"ya3-109-2-31","subject":"ya3","topic":"窩洞設計與分類","meta":"109年第2次第31題","year":109,"session":2,"number":31,"question":"胃食道逆流患者若發生腐蝕（erosion），較不會出現在前後牙的那個牙面？","options":["(A) 舌側","(B) 切端","(C) 咬合面","(D) 唇側"],"answer":3,"clinical_level":"重點"},{"id":"ya3-109-2-32","subject":"ya3","topic":"黏著與美學修復","meta":"109年第2次第32題","year":109,"session":2,"number":32,"question":"關於水份在自酸蝕（self-etch）黏著系統中的功用，下列敘述何者正確？①使黏著劑中的單體（monomer）離 子化（ionized） ②降低黏著劑的黏稠度（viscosity） ③常與乙醇作為共同溶劑 ④添加之重量百分比約為 50 wt％","options":["(A) ①②③","(B) ②③④","(C) ①③④","(D) ①②④"],"answer":0,"clinical_level":"一般"},{"id":"ya3-109-2-33","subject":"ya3","topic":"黏著與美學修復","meta":"109年第2次第33題","year":109,"session":2,"number":33,"question":"與全酸蝕（total-etch）黏著劑相較，下列何者是自酸蝕底劑（self-etching primer）的優點？","options":["(A) 酸蝕牙釉質的效果較佳","(B) 與牙釉質鍵結力較佳","(C) 與牙釉質鍵結不易有微滲漏（microleakage）","(D) 術後敏感較少"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-2-34","subject":"ya3","topic":"牙體修形程序","meta":"109年第2次第34題","year":109,"session":2,"number":34,"question":"關於氣動（air driven）及電動（electric）高速手機的轉速及功率的敘述，下列何者正確？","options":["(A) 轉速：氣動＞電動，功率：氣動＞電動","(B) 轉速：氣動＞電動，功率：氣動＜電動","(C) 轉速：氣動＜電動，功率：氣動＞電動","(D) 轉速：氣動＜電動，功率：氣動＜電動"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-2-35","subject":"ya3","topic":"牙體修形程序","meta":"109年第2次第35題","year":109,"session":2,"number":35,"question":"下列何者與橡皮障（rubber dam）的施用無關？","options":["(A) 潤滑劑","(B) 橡皮障夾","(C) 圓形鑽針（round bur）","(D) 打孔器（punch）"],"answer":2,"clinical_level":"重點(深度)"},{"id":"ya3-109-2-36","subject":"ya3","topic":"牙體修形程序","meta":"109年第2次第36題","year":109,"session":2,"number":36,"question":"復形治療時，欲使用排齦線防濕，有關排齦線放置的敘述，下列何者正確？","options":["(A) 放置至附連牙齦（attached gingiva）中","(B) 長度須超過牙齦側窩洞壁（gingival wall）1mm","(C) 露出牙齦邊緣（gingival margin）","(D) 放置至使游離牙齦（free gingiva）泛白的深度"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-2-37","subject":"ya3","topic":"複合樹脂與材料","meta":"109年第2次第37題","year":109,"session":2,"number":37,"question":"光聚合（light-curing）複合樹脂在進行聚合時，下列敘述何者錯誤？","options":["(A) 聚合度（polymerization rate）與聚合光強度及照射時間有關","(B) 複合樹脂聚合程度一般不超過 65%","(C) 填料顆粒體積越小，聚合光散射（scattering）越低","(D) 每次樹脂添加的厚度不應超過 1.5～2.0 mm"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-2-38","subject":"ya3","topic":"窩洞設計與分類","meta":"109年第2次第38題","year":109,"session":2,"number":38,"question":"下列關於結構因素（C-factor）的敘述，何者正確？","options":["(A) 是指樹脂充填於窩洞時，未黏著面／黏著面的比值","(B) C-factor 越大，表示充填的緻密度越高","(C) C-factor 越大，表示樹脂聚合時流動之代償性越大","(D) C-factor 越大，表示樹脂聚合後的收縮應力越大"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-2-39","subject":"ya3","topic":"牙體修形程序","meta":"109年第2次第39題","year":109,"session":2,"number":39,"question":"關於複合樹脂填補時，預先使用木楔（prewedging）的敘述中，下列何者錯誤？①為所有窩洞填補過程的必 要操作 ②可提供成型環帶（matrix band）置入空間 ③使用木楔對橡皮障下的牙齦無保護效果 ④減少傷 害鄰牙","options":["(A) ①②","(B) ②③","(C) ③④","(D) ①③"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-2-40","subject":"ya3","topic":"牙體修形程序","meta":"109年第2次第40題","year":109,"session":2,"number":40,"question":"三級窩洞填補時，對於填補物外懸（overhang）的樹脂可以使用下列何者刮除？","options":["(A) No.15 刀片","(B) No.11 刀片","(C) No.12 刀片","(D) 研光器（burnisher）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-2-41","subject":"ya3","topic":"黏著與美學修復","meta":"109年第2次第41題","year":109,"session":2,"number":41,"question":"下列關於上顎前牙形態之敘述，何者錯誤？","options":["(A) 將 mesiofacial 與 distofacial line angle 修得更接近，會使牙齒看起來寬度較窄","(B) 將 developmental depression 修得更接近，會使牙齒看起來寬度較窄","(C) 強調 gingival perikymata，會使牙齒看起來較短","(D) 將 gingival height of contour 修得更往牙齦方向，會使牙齒看起來較短"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-2-42","subject":"ya3","topic":"複合樹脂與材料","meta":"109年第2次第42題","year":109,"session":2,"number":42,"question":"比較複合樹脂和汞齊合金的性質，下列何者錯誤？","options":["(A) 樹脂之磨耗量較大","(B) 樹脂與牙齒熱膨脹係數差異較小","(C) 樹脂填補後之體積變化量較大","(D) 樹脂填補操作敏感度較高"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-2-43","subject":"ya3","topic":"窩洞設計與分類","meta":"109年第2次第43題","year":109,"session":2,"number":43,"question":"使用汞齊填補臼齒二級窩洞，其鄰接面和牙齒之間的窩緣角（cavosurface angle）應為多少度？","options":["(A) 45 度","(B) 90 度","(C) 120 度","(D) 180 度"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-2-44","subject":"ya3","topic":"窩洞設計與分類","meta":"109年第2次第44題","year":109,"session":2,"number":44,"question":"關於第一類汞齊充填的窩洞製備原則，下列敘述何者錯誤？","options":["(A) 咬合面深度須達 1.5 mm 以上","(B) 髓壁（pulpal wall）需建立在 DEJ 以下至少 0.2 mm","(C) 頰舌、近遠心壁皆需向咬合面聚攏（converge）","(D) 大臼齒邊緣嵴（marginal ridge）需保留 2 mm以上"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-2-45","subject":"ya3","topic":"窩洞設計與分類","meta":"109年第2次第45題","year":109,"session":2,"number":45,"question":"下列何種情形不會在第二類型汞齊填補（Class II amalgam filling）邊緣嵴（marginal ridge）後，因重建高度與 鄰牙不協調而產生？","options":["(A) 填補的牙齒容易產生食物阻塞（food impaction）","(B) 填補的牙齒不容易維持牙周健康","(C) 填補牙齒的對咬牙易造成冷熱敏感","(D) 填補的牙齒在使用牙線時，清潔效果降低"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-2-46","subject":"ya3","topic":"窩洞設計與分類","meta":"109年第2次第46題","year":109,"session":2,"number":46,"question":"第二類（class II）汞齊填補之窩洞修形時，鄰接盒型（proximal box）所做的固位溝（retention groove）需位 於何處？","options":["(A) 軸向牙齦線角（axiogingival line angle）","(B) 頰、舌側壁（buccal and lingual wall）","(C) 牙齦壁（gingival wall）","(D) 牙髓壁（pulpal wall）"],"answer":1,"clinical_level":"重點"},{"id":"ya3-109-2-47","subject":"ya3","topic":"窩洞設計與分類","meta":"109年第2次第47題","year":109,"session":2,"number":47,"question":"關於金合金嵌體的鄰接面齦緣斜面（gingival bevel）修形的敘述，下列何者錯誤？","options":["(A) 為了去除強度較弱的牙釉質","(B) 邊緣較易研光（burnish）","(C) 較為美觀","(D) 改善邊緣的密貼度"],"answer":2,"clinical_level":"重點"},{"id":"ya3-109-2-48","subject":"ya3","topic":"窩洞設計與分類","meta":"109年第2次第48題","year":109,"session":2,"number":48,"question":"下列何種方式可以有效增加金合金嵌體或冠蓋體（gold inlay or onlay）之固持性（retention）？","options":["(A) 減少復形體之近遠心側環覆面積（circumference）","(B) 將窩洞相對側壁之平行程度（parallel）調整成向咬合面聚攏（convergence toward occlusal）","(C) 增加窩洞側壁之長度","(D) 於鄰接面之牙齦側壁（gingival wall）增加針孔（pinholes）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-2-49","subject":"ya3","topic":"黏著與美學修復","meta":"109年第2次第49題","year":109,"session":2,"number":49,"question":"下列何種黏著劑成分可強化對金屬或 zirconia 之黏著？","options":["(A) 酸性單體 10-methacryloyloxydecyl dihydrogen phosphate（10-MDP）","(B) 有機溶劑丙酮（acetone）","(C) 親水性單體 2-hydroxyethyl methacrylate（HEMA）","(D) 起始劑 benzoyl peroxide（BPO）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-109-2-50","subject":"ya3","topic":"黏著與美學修復","meta":"109年第2次第50題","year":109,"session":2,"number":50,"question":"關於理想的臉部美觀的敘述，下列何者錯誤？","options":["(A) 上唇長度（鼻子下緣到上唇下緣），會隨年齡而增加","(B) 切緣平面（incisal plane）是指正中門牙切端的平面","(C) 切緣平面會平行於兩側的瞳孔連線","(D) 切緣平面不會是平的，而是大致平行於微笑時的下唇弧度"],"answer":1,"clinical_level":"重點"},{"id":"ya3-109-2-51","subject":"ya3","topic":"黏著與美學修復","meta":"109年第2次第51題","year":109,"session":2,"number":51,"question":"使用漂白劑時，牙釉質上殘留的氧會抑制樹脂硬化，因此牙齒漂白後至少需多久才可以填補複合樹脂？","options":["(A) 一天","(B) 三天","(C) 一星期","(D) 三星期"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-2-52","subject":"ya3","topic":"黏著與美學修復","meta":"109年第2次第52題","year":109,"session":2,"number":52,"question":"有關透明度（translucency）的敘述，下列何者錯誤？","options":["(A) 透明度代表光穿透牙齒或復形物的程度","(B) 在門牙使用紫色的顏色改變劑（color modifier），可模擬透明度","(C) 利用不透光的樹脂（opaque resin）遮住牙齒的色斑（stain）會減低光的穿透","(D) 光穿透的深度愈深，愈容易造成美觀失真（loss of esthetic vitality）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-2-53","subject":"ya3","topic":"牙周疾病與診斷","meta":"109年第2次第53題","year":109,"session":2,"number":53,"question":"關於健康的連接上皮（junctional epithelium）的敘述，下列何者錯誤？","options":["(A) 沒有角質素（keratin）","(B) 被歸類為角化不全（parakeratinized）上皮細胞","(C) 在底端可觀察到1～2個細胞寬","(D) 具hemidesmosome的結構"],"answer":1,"clinical_level":"重點"},{"id":"ya3-109-2-54","subject":"ya3","topic":"牙科解剖與生理","meta":"109年第2次第54題","year":109,"session":2,"number":54,"question":"牙骨質（cementum）的胚胎來源於下列何者？","options":["(A) dental follicle","(B) reduced enamel epithelium","(C) epithelial rests of Malassez","(D) basal lamina of Hertwig's epithelial root sheath"],"answer":0,"clinical_level":"重點"},{"id":"ya3-109-2-55","subject":"ya3","topic":"牙科解剖與生理","meta":"109年第2次第55題","year":109,"session":2,"number":55,"question":"關於牙周韌帶主纖維（principal fibers）的敘述，下列何者錯誤？","options":["(A) 主纖維所含有膠原蛋白的量，主要是由羥基脯氨酸（hydroxyproline）的量來決定","(B) 夏庇氏纖維（Sharpey's fibers）的鈣化與豐富的膠原蛋白（collagen protein）有關","(C) 第一及第三型膠原蛋白其原纖維（fibrils）與纖維形成有關","(D) 齒槽嵴纖維（alveolar crest fibers），可防止牙齒的突出及抵抗側方的移動"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-2-56","subject":"ya3","topic":"牙周疾病與診斷","meta":"109年第2次第56題","year":109,"session":2,"number":56,"question":"關於牙周組織（periodontium）的敘述，下列何者錯誤？","options":["(A) 上皮內的Langerhans cells是吞噬細胞的一部份","(B) Merkel cells含nerve endings，與tactile sensitivity有關","(C) PDL cells具有產生pericementum與periosteum的潛力","(D) sockets的walls在X光片上稱cribriform plates，在組織學上稱lamina dura"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-2-57","subject":"ya3","topic":"牙周疾病與診斷","meta":"109年第2次第57題","year":109,"session":2,"number":57,"question":"關於periodontal index（PI）及periodontal disease index（PDI）的敘述，下列何者錯誤？","options":["(A) PI 計分最低是 0","(B) PI 是可逆的（reversible）","(C) PDI是不可逆的（irreversible）","(D) PDI是以牙周囊袋（pocket depth）判斷計分"],"answer":3,"clinical_level":"重點"},{"id":"ya3-109-2-58","subject":"ya3","topic":"牙周非手術治療","meta":"109年第2次第58題","year":109,"session":2,"number":58,"question":"有位50歲的男士其CPITN社區牙周治療需求指數的紀錄如表格，請問該男士的牙周治療需求為何？","options":["(A) 接受口腔衛生教育即可","(B) 有兩個部位必須進行牙周手術","(C) 不須接受牙周治療，其缺牙區可直接進行贋復重建","(D) 需要進行口腔衛生教育與超音波潔牙及牙根整平術"],"answer":3,"image":"ya3-109-2-58.jpeg","clinical_level":"一般"},{"id":"ya3-109-2-59","subject":"ya3","topic":"牙周疾病與診斷","meta":"109年第2次第59題","year":109,"session":2,"number":59,"question":"下列何者不是增加牙齒搖動度（increased mobility）的原因？","options":["(A) 齒槽骨喪失","(B) 磨牙","(C) 牙齦過度發炎","(D) 懷孕或使用避孕藥物"],"answer":[0,1,2,3],"clinical_level":"一般","explanation_pending":false},{"id":"ya3-109-2-60","subject":"ya3","topic":"牙周疾病與診斷","meta":"109年第2次第60題","year":109,"session":2,"number":60,"question":"牙菌斑形成過程中，下列何種細菌具有凝集（coaggregation）其它口內細菌的能力？","options":["(A) Fusobacterium nucleatum","(B) Prevotella loescheii","(C) Capnocytophaga ochracea","(D) Streptococcus sanguinis"],"answer":0,"clinical_level":"一般"},{"id":"ya3-109-2-61","subject":"ya3","topic":"牙科解剖與生理","meta":"109年第2次第61題","year":109,"session":2,"number":61,"question":"隨著炎性病灶演進時（early→ established→ more advanced lesions），其主要的炎性細胞的變化（shift of inflammatory cells），下列敘述何者正確？","options":["(A) 從neutrophils→mast cells→macrophages","(B) 從neutrophils→plasma cells→lymphocytes","(C) 從plasma cells→lymphocytes→neutrophils","(D) 從neutrophils→lymphocytes→plasma cells"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-2-62","subject":"ya3","topic":"牙周疾病與診斷","meta":"109年第2次第62題","year":109,"session":2,"number":62,"question":"下列毒性因子（virulence factors）中，何者不是Aggregatibacter actinomycetemcomitans JP2產生的？","options":["(A) leukotoxin（LtxA）","(B) gingipains（RgPA, RgPB）","(C) lipopolysaccharides（LPS）","(D) cytolethal distending toxin（Cdt）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-2-63","subject":"ya3","topic":"牙周疾病與診斷","meta":"109年第2次第63題","year":109,"session":2,"number":63,"question":"下顎第一大臼齒，依據水平骨性吸收（H）與垂直性骨吸收（V）的程度，下列何者屬於根叉侵犯Class II， subclass B？","options":["(A) H= 0 mm；V= 1～3mm","(B) H= 2 mm；V= 4～6mm","(C) H= 3 mm, not through and through；V= 4～6mm","(D) H= through and through；V≧7mm"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-2-64","subject":"ya3","topic":"牙科解剖與生理","meta":"109年第2次第64題","year":109,"session":2,"number":64,"question":"關於以chlorhexidine（CHX）漱口的敘述，下列何者正確？","options":["(A) 在牙周病囊袋清創或拔牙時，能降低菌血症的風險","(B) 不建議牙齦增生或牙齦肥大的患者長期使用","(C) CHX的安全性研究顯示，長時間遇熱會有致癌風險","(D) 最佳濃度是以0.12%，10 mL漱口30秒"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-2-65","subject":"ya3","topic":"牙周非手術治療","meta":"109年第2次第65題","year":109,"session":2,"number":65,"question":"何種 Gracey curettes適用於大臼齒的遠心鄰界面（distoproximal surfaces）？","options":["(A) No. 13-14","(B) No. 7-8","(C) No. 5-6","(D) No. 1-2"],"answer":0,"clinical_level":"一般"},{"id":"ya3-109-2-66","subject":"ya3","topic":"植牙學","meta":"109年第2次第66題","year":109,"session":2,"number":66,"question":"取口內自體骨時所需考量的觀點，下列何者正確？","options":["(A) 若要使用鑽針輔助取骨，轉速宜小於5,000 rpm，以避免周圍骨壞死","(B) 取骨區域無論上下顎，均需至少距離牙根尖端5 mm","(C) 應盡量避免於牙周或植牙之同一手術區域取骨","(D) 不宜從外生贅骨（exostosis）區域取骨"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-2-67","subject":"ya3","topic":"牙周手術與再生","meta":"109年第2次第67題","year":109,"session":2,"number":67,"question":"下列何種牙周手術後疼痛（postoperative pain）最為劇烈？","options":["(A) 引導組織再生手術（guided tissue regeneration）","(B) 游離牙齦移植手術（free gingival graft）","(C) 骨切除術（resective osseous surgery）","(D) 牙齦切除術（gingivectomy）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-2-68","subject":"ya3","topic":"牙周手術與再生","meta":"109年第2次第68題","year":109,"session":2,"number":68,"question":"關於骨移植材料的敘述，下列何者正確？","options":["(A) 骨誘導（osteoinduction）是生理作用（physical effect）","(B) Bio-Oss是同種異體移植物（allograft）","(C) 拔牙窩經8～12週癒合，新形成的皮質骨可以做為骨移植材料","(D) 口腔外自體移植骨，通常會造成牙根吸收及腐骨形成的現象"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-2-69","subject":"ya3","topic":"牙周手術與再生","meta":"109年第2次第69題","year":109,"session":2,"number":69,"question":"關於牙周術後照顧（post-surgical care）的敘述，下列何者錯誤？","options":["(A) 術後的牙菌斑控制是決定牙周手術長期結果最重要的因素","(B) 可以使用0.1～0.2%的chlorhexidine solution 漱口，一天兩次","(C) 傷口的穩定會影響手術的結果","(D) 在手術後初期可使用牙間刷（interdental brush）進行牙齒之間的清潔"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-2-70","subject":"ya3","topic":"牙周手術與再生","meta":"109年第2次第70題","year":109,"session":2,"number":70,"question":"游離軟組織移植（free soft tissue graft）的區域，約在手術後多久較容易觀察到creeping attachment的現象？","options":["(A) 1個月","(B) 3個月","(C) 6個月","(D) 1年"],"answer":3,"clinical_level":"一般"},{"id":"ya3-109-2-71","subject":"ya3","topic":"牙周手術與再生","meta":"109年第2次第71題","year":109,"session":2,"number":71,"question":"下列手術器械以及其配合的使用模式之敘述，下列何者正確？","options":["(A) back-action chisel使用推（push）的方式","(B) Ochsenbein chisel使用推（push）的方式","(C) 骨銼（bone file）使用推（push）的方式","(D) 刮匙（curette）使用推（push）的方式"],"answer":1,"clinical_level":"一般"},{"id":"ya3-109-2-72","subject":"ya3","topic":"牙周手術與再生","meta":"109年第2次第72題","year":109,"session":2,"number":72,"question":"關於healing after periodontal surgery的敘述，下列何者錯誤？","options":["(A) 血塊是必要的且儘量厚些","(B) 上皮細胞於初始縫合後，約24小時開始分化與生長","(C) 連接上皮在10至12天回到其術前狀況","(D) 拔牙後1至2個月的拔牙窩，常被選為移植骨來源之一"],"answer":0,"clinical_level":"一般"},{"id":"ya3-109-2-73","subject":"ya3","topic":"牙周非手術治療","meta":"109年第2次第73題","year":109,"session":2,"number":73,"question":"關於維持期（maintenance phase）時病人回診（recall）時間，若病人在牙周治療完成之後牙周狀況穩定，傷 口癒合良好，第一年會建議病人多久定期回診檢查一次？","options":["(A) 1～2個月","(B) 3個月","(C) 6個月","(D) 12個月"],"answer":1,"clinical_level":"重點"},{"id":"ya3-109-2-74","subject":"ya3","topic":"牙周疾病與診斷","meta":"109年第2次第74題","year":109,"session":2,"number":74,"question":"Lang& Tonetti（2003）對維護期的牙周危險因子評估（periodontal risk assessment）之敘述，下列何者為非？","options":["(A) 囊袋探測出血的比例","(B) BL%／age","(C) 全口32顆牙齒喪失數目","(D) 有無系統性疾病或抽菸"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-2-75","subject":"ya3","topic":"植牙學","meta":"109年第2次第75題","year":109,"session":2,"number":75,"question":"癌症或是骨質疏鬆症的患者可能使用雙磷酸鹽類藥物（bisphosphonate），可能副作用為顎骨壞死 （bisphosphonate-related osteonecrosis of the jaw, BRONJ）。關於BRONJ的敘述，下列何者正確？","options":["(A) 根據2007年Wang EP的研究指出，雙磷酸鹽類藥物以靜脈注射方式進行癌症治療的患者有2.5%到5.4%的機率 產生BRONJ","(B) 根據2007年Wade ML的研究指出，雙磷酸鹽類藥物以口服方式進行骨質疏鬆症治療的患者有1.5%到2.5%的 機率產生BRONJ","(C) 血檢報告中的C-terminal telopeptide 數值若為300 pg/ml表示BRONJ發生的風險很高","(D) 使用口服雙磷酸鹽類藥物三年以上的患者，BRONJ的風險很低，可以放心進行拔牙及植牙等治療"],"answer":0,"clinical_level":"一般"},{"id":"ya3-109-2-76","subject":"ya3","topic":"牙周手術與再生","meta":"109年第2次第76題","year":109,"session":2,"number":76,"question":"當服用抗凝血藥物的患者進行牙周病治療時，下列敘述何者最正確？","options":["(A) INR（international normalized ratio）數值小於2.0時可以進行阻斷性麻醉、較容易的牙周手術及簡單的拔牙手 術","(B) 若牙周手術前INR過高，經內科醫師會診後可能會建議病人停藥一週","(C) 若患者有停用抗凝血劑藥物，則在牙周手術後24小時始可恢復用藥","(D) 手術過程中可局部使用抗凝血劑如eugenol，以控制手術區域出血狀況"],"answer":0,"clinical_level":"重點"},{"id":"ya3-109-2-77","subject":"ya3","topic":"牙科解剖與生理","meta":"109年第2次第77題","year":109,"session":2,"number":77,"question":"關於高血壓病患的牙周病治療的敘述，下列何者正確？","options":["(A) 因為早上血壓較低且平穩，適合於上午約診治療","(B) 就診時血壓為收縮壓165 mmHg/舒張壓100 mmHg時，仍可進行正常牙周病治療","(C) 可以少量使用含1：100,000 epinephrine的麻藥來增加麻醉深度","(D) 牙周膜內注射（intraligamentary injection），比血管內注射（intravascular injection）較不會引起明顯的血液 動態變化"],"answer":2,"clinical_level":"一般"},{"id":"ya3-109-2-78","subject":"ya3","topic":"植牙學","meta":"109年第2次第78題","year":109,"session":2,"number":78,"question":"根據研究，植體植入後，若低於多少的微動（micromovement）將不會影響骨整合？","options":["(A) 150 μm","(B) 200 μm","(C) 250 μm","(D) 300 μm"],"answer":0,"clinical_level":"一般"},{"id":"ya3-109-2-79","subject":"ya3","topic":"植牙學","meta":"109年第2次第79題","year":109,"session":2,"number":79,"question":"在定期維護下之健康植牙，其植體周圍軟組織內的菌種主要為何？","options":["(A) cocci","(B) fusiforms","(C) motile rods","(D) spirochetes"],"answer":0,"clinical_level":"重點"},{"id":"ya3-109-2-80","subject":"ya3","topic":"植牙學","meta":"109年第2次第80題","year":109,"session":2,"number":80,"question":"關於implant assessments的敘述，下列何者錯誤？","options":["(A) Mombelli’s modified plaque index （mPI） of [2]：指的是肉眼可見菌斑","(B) 探診檢查PPD、CAL、BoP時：用2～3N輕力探診","(C) X線片檢查：術後每年一次拍X線片，如有peri-implantitis時則立即拍照","(D) 咬合關係的檢查：首重於是否有穩定的正中咬合及前伸及側方運動有無咬合干擾"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-1-1","subject":"ya3","topic":"醫學倫理與法規","meta":"110年第1次第1題","year":110,"session":1,"number":1,"question":"陳先生是腦中風患者，在例行牙科檢查中，牙醫師發現他的左下大臼齒有嚴重齲齒，需要填補治療，但治療時 也可能會侵犯牙髓。牙醫師應進行何種處理較為妥適？","options":["(A) 根據「代理決定」原則，開始幫患者進行牙科治療","(B) 根據「代理決定」原則，在家屬同意後，開始幫患者進行牙科治療","(C) 根據「告知」原則，向患者解釋後，開始幫患者進行牙科治療","(D) 根據「告知」原則，向患者解釋並尋求同意後再治療。若患者無法理解或表達，家屬同意後，可幫患者進行 牙科治療"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-1-2","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第1次第2題","year":110,"session":1,"number":2,"question":"牙根形成階段，牙根尖閉合於何時完成（apical closure）？","options":["(A) 於牙齒萌出時","(B) 大約於牙齒萌出後 1年","(C) 大約於牙齒萌出後 3年","(D) 大約於牙齒萌出後 5年"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-1-3","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第1次第3題","year":110,"session":1,"number":3,"question":"關於牙髓腔內血液流量調整與控制的敘述，下列何者錯誤？","options":["(A) 在正常生理條件下，牙髓的血管緊張度（pulpal vascular tone）是維持在部分緊縮狀態","(B) 人體藉由神經與內分泌物質來調整血管緊張度（pulpal vascular tone）","(C) 牙髓的血流調整，大多藉由神經調控牙髓微血管收縮，而非調控微血管擴張","(D) 常見透過腎上腺素（α- adrenergic）、細胞旁激素（paracrine）及內分泌激素（endocrine）來調控微血管管徑 大小"],"answer":2,"clinical_level":"重點"},{"id":"ya3-110-1-4","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第1次第4題","year":110,"session":1,"number":4,"question":"關於牙髓中的三種抗原辨識細胞：巨噬細胞（marcophages）、樹突細胞（dendritic cells）和T細胞，下列敘述 何者正確？","options":["(A) 牙髓受細菌侵襲時，均會被活化及呈現","(B) 在健康的牙髓中，巨噬細胞是以單核球呈現","(C) 樹突細胞的數目在牙髓受到感染後會減少","(D) 牙髓受感染時，T細胞會被活化並分化成漿細胞"],"answer":1,"clinical_level":"重點"},{"id":"ya3-110-1-5","subject":"ya3","topic":"牙髓診斷與病理","meta":"110年第1次第5題","year":110,"session":1,"number":5,"question":"九歲女童因右下第一大臼齒齲齒而前來就診，臨床檢查發現患齒周圍牙齦呈現正常形態且無觸痛情況，但對冷 刺激有疼痛反應且會持續約40秒的時間，敲診時患齒會有疼痛的情況，放射線學檢查結果如下圖所示。則右下 第一大臼齒最適合的診斷為何？","options":["(A) 可逆性牙髓炎（reversible pulpitis）合併無症狀根尖周圍炎（asymptomatic apical periodontitis）","(B) 不可逆性牙髓炎（irreversible pulpitis）合併無症狀根尖周圍炎（asymptomatic apical periodontitis）","(C) 可逆性牙髓炎（reversible pulpitis）合併症狀性根尖周圍炎（symptomatic apical periodontitis）","(D) 不可逆性牙髓炎（irreversible pulpitis）合併症狀性根尖周圍炎（symptomatic apical periodontitis）"],"answer":3,"image":"ya3-110-1-5.jpeg","clinical_level":"重點"},{"id":"ya3-110-1-6","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第1次第6題","year":110,"session":1,"number":6,"question":"下列何種情況不需要投與抗生素治療？","options":["(A) 持續性感染（persistent infection）","(B) 蜂窩性組織炎（cellulitis）","(C) 骨髓炎（osteomyelitis）","(D) 慢性根尖膿腫（chronic apical abscess）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-1-7","subject":"ya3","topic":"牙髓診斷與病理","meta":"110年第1次第7題","year":110,"session":1,"number":7,"question":"有關使用選擇性麻醉（selective anesthesia）測試診斷牙髓疾病，下列敘述何者正確？","options":["(A) 可使用於下顎單顆牙齒疼痛的診斷","(B) 使用於上顎單顆牙齒疼痛的診斷較為準確，麻醉順序為後牙往前牙方向","(C) 選擇性麻醉診斷通常用於確認病患所指稱的疼痛牙齒","(D) 選擇性麻醉主要是鑑別確認上顎或下顎的疼痛牙齒診斷"],"answer":3,"clinical_level":"重點"},{"id":"ya3-110-1-8","subject":"ya3","topic":"牙齒外傷處理","meta":"110年第1次第8題","year":110,"session":1,"number":8,"question":"牙齒脫落（avulsion）的緊急浸泡溶液中，依最能維持牙根表面細胞活性之溶液排序，下列何者正確？","options":["(A) 牛奶＞唾液＞生理食鹽水＞水","(B) 唾液＞生理食鹽水＞水＞牛奶","(C) 生理食鹽水＞水＞牛奶＞唾液","(D) 水＞牛奶＞唾液＞生理食鹽水"],"answer":0,"clinical_level":"一般"},{"id":"ya3-110-1-9","subject":"ya3","topic":"牙齒外傷處理","meta":"110年第1次第9題","year":110,"session":1,"number":9,"question":"關於牙齒外傷後的放射線檢查，下列敘述何者正確？","options":["(A) 根據International Association of Dental Traumatology（IADT）2012年的guideline，針對外傷的牙齒至少需要 拍攝3張根尖片","(B) 3D的影像並未被證實比2D的放射線影像，可以提供更多的資訊","(C) 如有軟組織的撕裂傷，應在縫合前拍攝根尖片","(D) 頰舌面方向的牙根吸收，比較容易在根尖片上被檢測出來"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-1-10","subject":"ya3","topic":"牙齒外傷處理","meta":"110年第1次第10題","year":110,"session":1,"number":10,"question":"下列那一種外傷牙齒緊急處理後，所需固定的時間最久？","options":["(A) 動搖之半脫位（subluxation）牙齒","(B) 突出脫位齒（extrusive luxation）","(C) 側向脫位齒（lateral luxation）","(D) 口外乾燥時間小於1小時之脫落齒（avulsion）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-1-11","subject":"ya3","topic":"根管器械","meta":"110年第1次第11題","year":110,"session":1,"number":11,"question":"關於根管治療所使用的鎳鈦器械，下列敘述何者正確？","options":["(A) 使用動能驅動（engine-driven）的器械都是鎳鈦材質","(B) 現在使用的鎳鈦器械均透過電腦設計後，再將鎳鈦金屬線以機械研磨方式做成所要的形狀","(C) 最新設計的鎳鈦旋轉器械並不一定設計以radial land來避免器械旋轉切削時偏移根管原來的路徑","(D) 最新設計的鎳鈦旋轉器械操作時即使不用潤滑劑，也不會造成器械斷裂"],"answer":2,"clinical_level":"重點"},{"id":"ya3-110-1-12","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第1次第12題","year":110,"session":1,"number":12,"question":"開立止痛藥物給予因牙髓病變產生牙痛之患者，下列敘述何者錯誤？","options":["(A) 首選藥物為Ibuprofen 200～400 mg","(B) 若患者已經服用Ibuprofen 200～400 mg後仍無法止痛時，可以改成Ibuprofen 600～800 mg","(C) 若患者對Aspirin過敏，可以改開Acetaminophen 500 mg","(D) Opioid與Acetaminophen合併製成的藥物，可用於重度牙痛患者"],"answer":[0,1,2,3],"clinical_level":"一般","explanation_pending":false},{"id":"ya3-110-1-13","subject":"ya3","topic":"根管器械","meta":"110年第1次第13題","year":110,"session":1,"number":13,"question":"0.02錐度（taper）的20號根管銼，距離尖端10 mm處的直徑為何？","options":["(A) 0.32 mm","(B) 0.40 mm","(C) 0.42 mm","(D) 0.48 mm"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-1-14","subject":"ya3","topic":"牙髓診斷與病理","meta":"110年第1次第14題","year":110,"session":1,"number":14,"question":"上顎左側第一大臼齒（如圖），圖 A、B為正角度拍攝之X光片，則圖Ｃ之拍攝角度為何？根管由近心至遠心 分別為何？","options":["(A) 近心偏移角度（mesisl shift）；腭根管（palatal canal），近心頰側1根管（MB1 canal）， 近心頰側2根管 （MB2 canal），遠心頰側根管（DB canal）","(B) 遠心偏移角度（distal shift）；腭根管（palatal canal），近心頰側1根管（MB1 canal）， 近心頰側2根管 （MB2 canal），遠心頰側根管（DB canal）","(C) 近心偏移角度（mesisl shift）；腭根管（palatal canal），近心頰側2根管（MB2 canal）， 近心頰側1根管 （MB1 canal），遠心頰側根管（DB canal）","(D) 遠心偏移角度（distal shift）；腭根管（palatal canal），近心頰側2根管（MB2 canal）， 近心頰側1根管 （MB1 canal），遠心頰側根管（DB canal）"],"answer":2,"image":"ya3-110-1-14.jpeg","clinical_level":"一般"},{"id":"ya3-110-1-15","subject":"ya3","topic":"根管器械","meta":"110年第1次第15題","year":110,"session":1,"number":15,"question":"關於力平衡技術（balanced force technique）的敘述，下列何者正確？","options":["(A) 1985年由Dr. Roane所提出，他當時建議使用k-flex file","(B) Dr. Roane建議使用的銼針不可預彎","(C) 順時針將銼針放置根管內接觸牙本質（須超過180度）","(D) 逆時針旋轉（少於120度）向根尖施力切削擴大根管"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-1-16","subject":"ya3","topic":"根管治療程序","meta":"110年第1次第16題","year":110,"session":1,"number":16,"question":"關於根管沖洗液NaOCl溶液和2% chlorhexidine的使用，下列敘述何者錯誤？","options":["(A) 臨床上建議在同一次根管治療中使用這兩種根管沖洗液，先使用chlorhexidine再以NaOCl溶液最後沖洗","(B) 兩者混合後顏色產生變化，呈現橘紅色","(C) 兩者混合後產生沉澱，根管壁會被染色，影響根管充填時的密封","(D) 兩者混合會產生有毒的物質parachloroaniline （PCA），對細胞有害"],"answer":0,"clinical_level":"重點"},{"id":"ya3-110-1-17","subject":"ya3","topic":"根管器械","meta":"110年第1次第17題","year":110,"session":1,"number":17,"question":"在根管修形中將手動器械與旋轉器械合併使用常帶來不錯的效果，下列敘述何者錯誤？","options":["(A) 兩種器械均能各自充分發揮其特色並避免斷裂","(B) 以手動器械確保滑行路徑平順通暢","(C) 使用具錐度的旋轉器械負責擴大根管冠狀端三分之一","(D) 使用錐度較大及尺寸較小的旋轉器械負責根尖部的擴大修形"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-1-18","subject":"ya3","topic":"根管治療程序","meta":"110年第1次第18題","year":110,"session":1,"number":18,"question":"下列有關根管塗抹層（smear layer）之敘述，何者正確？","options":["(A) 於根管修形時，附著於根管壁上之有機物，厚度約1～5μm","(B) 臨床上用5%次氯酸鈉（NaOCl）移除塗抹層","(C) 一般認為塗抹層會增加根管封填的漏隙","(D) 根管修形完成建議以2% ethylenediamine tetra-acetic acid（EDTA）沖洗，1分鐘後再以次氯酸鈉（NaOCl）完 成清潔，可有效去除塗抹層"],"answer":2,"clinical_level":"重點"},{"id":"ya3-110-1-19","subject":"ya3","topic":"牙髓診斷與病理","meta":"110年第1次第19題","year":110,"session":1,"number":19,"question":"在經過良好的非手術性根管治療後，仍有手術需求的牙齒，其根管內最不易發現下列何種微生物 （microorganism）？","options":["(A) Actinomyces viscocus","(B) Propionibacterium propionicum","(C) Enterococcus faecalis","(D) Candida albicans"],"answer":0,"clinical_level":"一般"},{"id":"ya3-110-1-20","subject":"ya3","topic":"根尖手術與再治療","meta":"110年第1次第20題","year":110,"session":1,"number":20,"question":"如下圖所示，上顎右側正中門齒頰側根尖處牙齦有明顯腫脹現象，而牙周囊袋探測結果均在正常範圍內，若 欲進行患齒之根尖手術治療（apical surgery），最適合的翻瓣設計為何？","options":["(A) 緣下曲線翻瓣（submarginal curved flap）","(B) 緣下方形翻瓣（submarginal rectangular flap）","(C) 方形翻瓣（rectangular flap）","(D) 三角形翻瓣（triangular flap）"],"answer":1,"image":"ya3-110-1-20.jpeg","clinical_level":"一般"},{"id":"ya3-110-1-21","subject":"ya3","topic":"根管治療程序","meta":"110年第1次第21題","year":110,"session":1,"number":21,"question":"當根管發生穿孔時，下列何者較不適合當止血劑的材料？","options":["(A) Ca(OH)2","(B) calcium sulfate","(C) ferric sulfate","(D) collagen（Colla-Cote）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-1-22","subject":"ya3","topic":"根管治療程序","meta":"110年第1次第22題","year":110,"session":1,"number":22,"question":"影響根管穿孔修補的預後有許多因素，下列敘述何者錯誤？","options":["(A) 穿孔位置在根尖部會比在冠部的預後佳","(B) 穿孔發生後立即修補會比延後修補的預後佳","(C) 醫生對穿孔的修補與封閉能力也會影響預後","(D) 不論使用何種材料修補，預後是差不多的"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-1-23","subject":"ya3","topic":"根管治療程序","meta":"110年第1次第23題","year":110,"session":1,"number":23,"question":"下列何者不是影響非手術性根管治療（nonsurgical root canal treatment）牙根尖周圍癒合（periapical healing） 的主要因素？","options":["(A) 牙根尖是否通暢（patency）","(B) 根管封填所使用的方法","(C) 根管封填的品質","(D) 是否有醫源性的牙根穿孔（iatrogenic perforation）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-1-24","subject":"ya3","topic":"根管治療程序","meta":"110年第1次第24題","year":110,"session":1,"number":24,"question":"臨床上經過根管治療後的牙齒，常發現其強度降低，下列何者是牙冠斷裂機率增加的主要原因？","options":["(A) 根管治療後的牙齒喪失水分，導致其易碎性（friability）增加","(B) 牙齒喪失活性，缺乏養分，強度因而降低","(C) 根管開擴以及清創以後，其齒質的結構改變，因而強度降低","(D) 因為根管治療後，化學性質改變，導致強度下降"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-1-25","subject":"ya3","topic":"根管治療程序","meta":"110年第1次第25題","year":110,"session":1,"number":25,"question":"根管錐度較大（large taper）的牙齒，應選用何種根柱（post）最為合適？","options":["(A) 螺紋根柱（screw post）","(B) 纖維根柱（fiber post）","(C) 不鏽鋼根柱（stainless steel post）","(D) 鑄造根柱（casting post）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-1-26","subject":"ya3","topic":"牙髓診斷與病理","meta":"110年第1次第26題","year":110,"session":1,"number":26,"question":"下列何者不是鑑別診斷牙髓－牙周疾病（endodontic-periodontal combined lesions）之臨床檢查方法？","options":["(A) 牙髓活性測試（pulp vitality test）","(B) 放射線攝影檢查（radiographic examination）","(C) 牙周囊袋探測（probing）","(D) 牙齒搖動度（mobility）"],"answer":3,"clinical_level":"重點"},{"id":"ya3-110-1-27","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第1次第27題","year":110,"session":1,"number":27,"question":"關於牙釉質的敘述，下列何者錯誤？","options":["(A) 源自外胚層（ectoderm）","(B) 除齒頸部以外，牙釉稜柱（enamel rod）與牙齒表面和牙本質牙釉質交界（dentinoenamel junction）互相平行","(C) 曲結牙釉質（gnarled enamel）因為結構特異性，比其他部位牙釉質不易斷裂","(D) 在齒頸部表層常存在無結構（structureless）層"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-1-28","subject":"ya3","topic":"牙髓診斷與病理","meta":"110年第1次第28題","year":110,"session":1,"number":28,"question":"病患因牙髓炎感到搏動痛（throbbing pain）是牙髓腔內那一種神經纖維（fiber）被活化？","options":["(A) A fiber","(B) A-α fiber","(C) C fiber","(D) A-β fiber"],"answer":2,"clinical_level":"重點"},{"id":"ya3-110-1-29","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第1次第29題","year":110,"session":1,"number":29,"question":"關於飲水加氟的敘述，下列何者錯誤？","options":["(A) 超過 10 ppm 的氟會顯著增加氟斑的機率","(B) 低於 0.1 ppm 的氟不具齲齒預防效果","(C) 最適當的濃度為 0.2 ppm","(D) 所使用的濃度遠低於局部塗氟"],"answer":2,"clinical_level":"重點"},{"id":"ya3-110-1-30","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第1次第30題","year":110,"session":1,"number":30,"question":"關於齲齒與發生部位主要致齲菌的敘述，下列何者錯誤？","options":["(A) 造成牙根部齲齒的主要病菌為 Actinomyces","(B) 造成牙本質齲齒的主要病菌為 Lactobacillus","(C) 造成牙釉質齲齒的主要病菌為 Streptococcus sanguis","(D) 造成牙本質齲齒的主要病菌為 Streptococcus mutans"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-1-31","subject":"ya3","topic":"窩洞設計與分類","meta":"110年第1次第31題","year":110,"session":1,"number":31,"question":"下列何者不是評估齲齒風險的主要指標？","options":["(A) 口內現有齲齒病灶的數量","(B) 患者家族罹患齲齒的狀況","(C) 攝取致齲性碳水化合物的頻率","(D) 唾液分泌的流量"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-1-32","subject":"ya3","topic":"牙髓診斷與病理","meta":"110年第1次第32題","year":110,"session":1,"number":32,"question":"下列何者不是影響牙本質通透性（permeability）的主要因素？","options":["(A) 不含血管收縮劑的表面麻醉劑","(B) 牙本質小管的管徑及長度","(C) 牙髓中血管移除物質的速率","(D) 牙本質液（dentinal fluid）的黏稠度"],"answer":0,"clinical_level":"一般"},{"id":"ya3-110-1-33","subject":"ya3","topic":"黏著與美學修復","meta":"110年第1次第33題","year":110,"session":1,"number":33,"question":"牙本質與黏著劑鍵結後，需要達到多少鍵結強度（bond strength），才能抗衡複合樹脂聚合收縮所產生的應力 （stress）？","options":["(A) 3 MPa","(B) 7 MPa","(C) 11 MPa","(D) 17 MPa"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-1-34","subject":"ya3","topic":"窩洞設計與分類","meta":"110年第1次第34題","year":110,"session":1,"number":34,"question":"直接填補中，考量填補材料是具有鍵結之複合樹脂或無鍵結之汞齊充填，可能改變之窩洞型態設計有哪些？ ①窩緣面邊緣（cavosurface margin） ②固位型（retention form） ③方便型（convenience form） ④抗力 型（resistance form）","options":["(A) ①②④","(B) ②③④","(C) ①③④","(D) ①②③"],"answer":0,"clinical_level":"一般"},{"id":"ya3-110-1-35","subject":"ya3","topic":"牙體修形程序","meta":"110年第1次第35題","year":110,"session":1,"number":35,"question":"關於牙齦邊緣削器（gingival margin trimmer）的特徵，下列敍述何者錯誤？","options":["(A) 刃部具有曲線弧度","(B) 可用於金合金嵌體（inlay）的牙齦緣斜面製備","(C) 器械刀刃不分左右，均可用於窩洞不同方向切削","(D) 可移除汞齊第二類窩洞中的齒髓軸壁線角的尖銳角度"],"answer":2,"clinical_level":"重點"},{"id":"ya3-110-1-36","subject":"ya3","topic":"牙體修形程序","meta":"110年第1次第36題","year":110,"session":1,"number":36,"question":"使用橡皮障（rubber dam）時，若橡皮障在被隔離牙齒的區間出現皺褶，其可能原因為何？","options":["(A) 橡皮障過度拉扯","(B) 橡皮障太薄","(C) 橡皮障上打洞的間距過短","(D) 橡皮障上打洞的間距過長"],"answer":3,"clinical_level":"重點"},{"id":"ya3-110-1-37","subject":"ya3","topic":"複合樹脂與材料","meta":"110年第1次第37題","year":110,"session":1,"number":37,"question":"汞齊合金（amalgam alloy）中那一種金屬容易被水氣、唾液汚染，引起汞齊產生延緩膨脹（delay expansion）？","options":["(A) 銀","(B) 鋅","(C) 汞","(D) 銅"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-1-38","subject":"ya3","topic":"複合樹脂與材料","meta":"110年第1次第38題","year":110,"session":1,"number":38,"question":"下列那一種牙科黏合劑（dental cement）的粉劑中含有氧化鋅（zinc oxide）？①磷酸鋅（zinc phosphate）黏 合劑 ②聚羧酸（polycarboxylate）黏合劑 ③玻璃離子體（glass ionomer）黏合劑 ④複合體（compomer） 黏合劑","options":["(A) 僅①②","(B) 僅②③","(C) ①②③","(D) ①③④"],"answer":0,"clinical_level":"一般"},{"id":"ya3-110-1-39","subject":"ya3","topic":"複合樹脂與材料","meta":"110年第1次第39題","year":110,"session":1,"number":39,"question":"前牙大範圍的複合樹脂填補，下列何者不是增加微機械固位（micro-mechanical retention）的方法？","options":["(A) 使用粗糙的鑽石鑽針（diamond bur）","(B) 製造較寬的斜面","(C) 增加固位溝和鴿尾形（dovetail）","(D) 使用自酸蝕黏著系統（self-etch bonding system）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-1-40","subject":"ya3","topic":"黏著與美學修復","meta":"110年第1次第40題","year":110,"session":1,"number":40,"question":"進行第五類複合樹脂填補時，窩洞之牙齦緣若無牙釉質存在，其窩緣角（cavosurface angle）應為多少度？","options":["(A) 45 度","(B) 90 度","(C) 135 度","(D) 180 度"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-1-41","subject":"ya3","topic":"黏著與美學修復","meta":"110年第1次第41題","year":110,"session":1,"number":41,"question":"當眼睛直視牙齒太久，視覺可能會發生顏色疲勞（color fatigue），以致對於黃－橙色（yellow-orange shades）較不敏感，此時要如何才能快速恢復正常？","options":["(A) 看紅色的物體或背景","(B) 看綠色的物體或背景","(C) 看藍色的物體或背景","(D) 看白色的物體或背景"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-1-42","subject":"ya3","topic":"牙體修形程序","meta":"110年第1次第42題","year":110,"session":1,"number":42,"question":"進行第二類窩洞填補時，若與鄰牙有0.5～1.0 mm 間隙，下列何種情形最容易造成與鄰牙無接觸（open contact）的結果？","options":["(A) 使用 tofflemire-type matrix 直接填補複合樹脂","(B) 使用 sectional matix 直接填補複合樹脂","(C) 使用間接複合樹脂填補","(D) 使用 tofflemire-type matrix 直接填補汞齊合金"],"answer":0,"clinical_level":"一般"},{"id":"ya3-110-1-43","subject":"ya3","topic":"複合樹脂與材料","meta":"110年第1次第43題","year":110,"session":1,"number":43,"question":"下列何種複合樹脂之填補方法，無法有效減少複合樹脂聚合收縮？","options":["(A) 逐層（incremental）填補","(B) 牙釉質做斜面（bevel）","(C) 具彈性的襯裡（flexible liner）","(D) 以流動性樹脂填補"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-1-44","subject":"ya3","topic":"窩洞設計與分類","meta":"110年第1次第44題","year":110,"session":1,"number":44,"question":"有關汞齊充填第二類窩洞，鄰接面盒（proximal box）的修形，下列何者錯誤？","options":["(A) 鄰接面窩緣角以 90 度為宜","(B) 與鄰牙間的間隙以不超過 0.5 mm 為佳","(C) 牙齦窩緣角在牙釉質時須為 90 度","(D) 軸髓線角（axiopulpal line angle）須圓滑或為斜面（bevel）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-1-45","subject":"ya3","topic":"窩洞設計與分類","meta":"110年第1次第45題","year":110,"session":1,"number":45,"question":"下圖為下顎大臼齒，最適合打固位釘（pin）的區域為何？","options":["(A) 1","(B) 2","(C) 3","(D) 4"],"answer":2,"image":"ya3-110-1-45.jpeg","clinical_level":"一般"},{"id":"ya3-110-1-46","subject":"ya3","topic":"複合樹脂與材料","meta":"110年第1次第46題","year":110,"session":1,"number":46,"question":"關於汞齊（amalgam）之缺點，下列何者錯誤？","options":["(A) 不能與齒質黏著（bonding）","(B) 不美觀","(C) 汞污染","(D) 腐蝕產物會增加邊緣微滲漏（microleakage）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-1-47","subject":"ya3","topic":"窩洞設計與分類","meta":"110年第1次第47題","year":110,"session":1,"number":47,"question":"下圖為上顎小臼齒包覆舌側咬頭之冠蓋體修形，在鄰接面兩側製備溝槽主要是防止冠蓋體往哪個方向之移 位？","options":["(A) 舌側","(B) 頰側","(C) 近心","(D) 遠心"],"answer":0,"image":"ya3-110-1-47.jpeg","clinical_level":"一般"},{"id":"ya3-110-1-48","subject":"ya3","topic":"窩洞設計與分類","meta":"110年第1次第48題","year":110,"session":1,"number":48,"question":"製備上顎小臼齒的局部覆蓋牙冠（partial-coverage crown）（如圖），最不適當的頰側咬合終接線（finish line）為何？","options":["(A) A","(B) B","(C) C","(D) D"],"answer":3,"image":"ya3-110-1-48.jpeg","clinical_level":"一般"},{"id":"ya3-110-1-49","subject":"ya3","topic":"窩洞設計與分類","meta":"110年第1次第49題","year":110,"session":1,"number":49,"question":"下列何者不是鑄造金屬嵌體固位（retention）的主要來源？","options":["(A) 垂直壁（vertical wall）儘量平行","(B) 咬合斜面（occlusal bevel）和牙齦斜面（gingival bevel）","(C) 在鄰接面盒（proximal box）頰舌側做固位溝（retention groove）","(D) 將咬合面窩洞延伸到顏側／舌側面溝（facial/lingual surface groove）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-1-50","subject":"ya3","topic":"黏著與美學修復","meta":"110年第1次第50題","year":110,"session":1,"number":50,"question":"在不改變牙齒長度的情況下，為使前牙看起來較長，下列處置何者正確？①增加近心線角與遠心線角的距 離 ②縮短近心線角與遠心線角的距離 ③製備牙釉質橫嵴（perikymata） ④縮短牙齒唇側面發育凹陷 （developmental depression）的距離","options":["(A) ①③","(B) ①④","(C) ②③","(D) ②④"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-1-51","subject":"ya3","topic":"黏著與美學修復","meta":"110年第1次第51題","year":110,"session":1,"number":51,"question":"關於持續漂白法（walking bleaching）的過程，下列敘述何者錯誤？","options":["(A) 建議移除馬來膠至臨床牙冠下約 1～2 mm, 並直接置放漂白劑以達最佳漂白效果","(B) 為了確認牙髓腔內完全清創，會擴大足夠的牙髓腔入口修形（endodontic access opening）","(C) 常見的使用材料為過硼酸鈉（sodium perborate）","(D) 此為一種非活齒漂白（nonvital bleaching）的技術"],"answer":0,"clinical_level":"重點"},{"id":"ya3-110-1-52","subject":"ya3","topic":"黏著與美學修復","meta":"110年第1次第52題","year":110,"session":1,"number":52,"question":"想要使用 cosmetic contouring 技巧讓圖中患者恢復年輕的外貌，下列何者錯誤？","options":["(A) 藉由修磨牙釉質改變牙齒的外型","(B) 圓滑（rounding）門齒角（incisal angles）","(C) 打開切端溝隙（incisal embrasure）","(D) 增加唇側線角（labial line angle）的隆凸度"],"answer":3,"image":"ya3-110-1-52.jpeg","clinical_level":"一般"},{"id":"ya3-110-1-53","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第1次第53題","year":110,"session":1,"number":53,"question":"Langerhans cell 在口腔上皮的最主要功能為下列何者？","options":["(A) antigen presentation","(B) phagocytosis","(C) intracellular killing","(D) cytokine secretion"],"answer":0,"clinical_level":"重點"},{"id":"ya3-110-1-54","subject":"ya3","topic":"牙周疾病與診斷","meta":"110年第1次第54題","year":110,"session":1,"number":54,"question":"關於牙齒被動萌出（passive eruption）的敘述，下列何者正確？","options":["(A) 透過牙周韌帶收縮","(B) 透過牙齒位移","(C) 牙齒向咬合平面移動","(D) 牙齦向根尖方向位移"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-1-55","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第1次第55題","year":110,"session":1,"number":55,"question":"口腔黏膜角質化的程度依區域不同，從最高到最低依序排列，下列何者正確？","options":["(A) 牙齦＞舌頭的腹面＞頰部＞硬腭","(B) 硬腭＞舌頭的腹面＞牙齦＞頰部","(C) 硬腭＞牙齦＞舌頭的腹面＞頰部","(D) 牙齦＞硬腭＞舌頭的腹面＞頰部"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-1-56","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第1次第56題","year":110,"session":1,"number":56,"question":"關於牙齦上皮（gingival epithelium）構造的敘述，下列何者錯誤？","options":["(A) 當兩個表皮細胞呈緊密接合（tight junctions）時，離子及小分子仍然可以互相交通","(B) 電子顯微鏡下，兩個角質細胞藉著半胞橋小體（hemidesmosome）結合","(C) 其細胞質中的粒線體，由基底層往棘皮層逐漸減少","(D) 棘皮層（stratum spinosum）含有角質小體（keratinosomes），其含有酸性磷酸酯酶與角質化的程度有關"],"answer":1,"clinical_level":"重點"},{"id":"ya3-110-1-57","subject":"ya3","topic":"牙周疾病與診斷","meta":"110年第1次第57題","year":110,"session":1,"number":57,"question":"依據Page & Schröeder（1976年）的牙周組織病理病灶分期，關於initial lesion的敘述，下列何者正確？","options":["(A) 在牙菌斑堆積7天後，在臨床上即呈現此一時期病灶的變化","(B) 此一時期的病灶是subclinical，僅可用組織切片去證實","(C) 葡萄球菌（staphylococci）是initial lesion中最首先出現的細菌","(D) 淋巴球是initial lesion的最主要血球細胞"],"answer":1,"clinical_level":"重點"},{"id":"ya3-110-1-58","subject":"ya3","topic":"牙周疾病與診斷","meta":"110年第1次第58題","year":110,"session":1,"number":58,"question":"下列何種細菌不屬於Söcransky 1998的red complex species？","options":["(A) P. gingivalis","(B) P. intermedia","(C) T. forsythia","(D) T. denticola"],"answer":1,"clinical_level":"重點"},{"id":"ya3-110-1-59","subject":"ya3","topic":"牙周疾病與診斷","meta":"110年第1次第59題","year":110,"session":1,"number":59,"question":"關於牙周病之齒槽骨缺損（bone destruction pattern）的敘述，下列何者錯誤？","options":["(A) 水平骨喪失（horizontal bone loss）指鄰牙之間齒槽間隔（interdental septa）骨高度下降，且在同一牙齒周圍 的破壞都是相同的","(B) 垂直骨缺損（vertical bone defect）通常伴隨著年齡而增加","(C) 水平骨喪失（horizontal bone loss）的邊緣骨（marginal bone）和牙齒表面垂直","(D) 垂直骨缺損（vertical bone defect）若發生在頰舌側，從X光片上不易判讀"],"answer":0,"clinical_level":"一般"},{"id":"ya3-110-1-60","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第1次第60題","year":110,"session":1,"number":60,"question":"服用抗凝血劑warfarin的局部侵襲性牙周炎患者，在牙周第一期治療應該避免使用那一類抗生素？","options":["(A) amoxicillin","(B) doxycycline","(C) metronidazole","(D) azithromycin"],"answer":2,"clinical_level":"重點"},{"id":"ya3-110-1-61","subject":"ya3","topic":"牙周非手術治療","meta":"110年第1次第61題","year":110,"session":1,"number":61,"question":"一位十六歲女性有先天心瓣膜異常且齦下細菌培養為A.a.-positive，在作潔牙與根面整平前，應該給予下列何 種抗生素？","options":["(A) 只給予tetracycline","(B) 同時給予tetracycline及amoxicillin","(C) 同時給予amoxicillin及metronidazole","(D) 只給予amoxicillin"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-1-62","subject":"ya3","topic":"牙周疾病與診斷","meta":"110年第1次第62題","year":110,"session":1,"number":62,"question":"關於functional diagram （Lang and Tonetti, 2003）之「牙周危險評估」的敘述，下列何者正確？","options":["(A) BoP在≤10%患者的牙周病進展可視為low risk","(B) 殘餘PPD > 4 mm，具有單獨評估因子（sole parameter）的價值","(C) 如果32顆牙中有超過8顆牙齒喪失可被考慮為high risk","(D) 使用BL%／age評估牙周病危險度，積極治療前比治療後（SPT）更正確"],"answer":0,"clinical_level":"重點"},{"id":"ya3-110-1-63","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第1次第63題","year":110,"session":1,"number":63,"question":"關於牙周組織內之免疫反應（immune responses）的敘述，下列何者錯誤？","options":["(A) 自然殺手細胞（NK cells）攻擊病毒-感染細胞是經由apoptosis","(B) defensins與cathelicidins是人類主要的抗菌蛋白","(C) C3a與C5a在活化mast cells和吸引吞食性細胞到細菌侵入點，擔任重要角色","(D) 大多數的nucleated cells產生IFN-α與IFN-β，但IFN-γ是由NK cells與 B cells產生"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-1-64","subject":"ya3","topic":"牙周非手術治療","meta":"110年第1次第64題","year":110,"session":1,"number":64,"question":"刷牙的方法中，關於牙刷刷毛的動作方式，下列敘述何者正確？","options":["(A) Bass method主要是以vibration呈現","(B) Stillman method與Charters method起步動作相同","(C) Leonard technique是牙齒閉合且前後來回刷","(D) Fones method是垂直方向的roll technique"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-1-65","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第1次第65題","year":110,"session":1,"number":65,"question":"最可能引發鵝口瘡、口黏膜脫皮的副作用的牙膏成分為下列何者？","options":["(A) sodium lauryl sulfate","(B) silica","(C) chlorhexidine","(D) fluoride"],"answer":0,"clinical_level":"一般"},{"id":"ya3-110-1-66","subject":"ya3","topic":"牙周手術與再生","meta":"110年第1次第66題","year":110,"session":1,"number":66,"question":"下列何者屬於不可吸收之牙周再生膜材料？","options":["(A) 膠原蛋白","(B) 聚乳酸（polylactic acid）","(C) 聚四氟乙烯（polytetrafluoroethylene）","(D) 聚乳糖（polyglactin）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-1-67","subject":"ya3","topic":"牙周手術與再生","meta":"110年第1次第67題","year":110,"session":1,"number":67,"question":"關於BMP-2的使用，下列敘述何者錯誤？","options":["(A) 已取得美國FDA認證，適用於牙周硬（骨）與軟組織的再生","(B) BMP-2是一種造骨細胞分化因子（differentiation factor）而不是增生因子（proliferation factor）","(C) 主要的功能在誘導骨生成（osteoinduction）","(D) 臨床常將BMP-2和第一型膠原蛋白結合使用"],"answer":0,"clinical_level":"重點"},{"id":"ya3-110-1-68","subject":"ya3","topic":"牙周手術與再生","meta":"110年第1次第68題","year":110,"session":1,"number":68,"question":"關於牙周翻瓣手術術後齒槽骨的變化情形，下列何者錯誤？","options":["(A) 1-3天內會發生表層骨壞死","(B) 骨頭修復約在3-4週內達到高峰","(C) 一般而言，術後2-3 mm骨頭喪失是可以被預期的","(D) 骨板厚度較薄的地方可預期有較多骨吸收"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-1-69","subject":"ya3","topic":"牙周手術與再生","meta":"110年第1次第69題","year":110,"session":1,"number":69,"question":"關於在根叉侵犯牙齒進行引導組織再生術（guided tissue regeneration）的敘述，下列何者錯誤？","options":["(A) 當鄰間骨（interproximal bone）離CEJ越遠時，成功機率越高","(B) 當根叉型態越複雜、或開展程度較低時，易造成清潔效率不佳而降低再生術式的成功率","(C) 根叉侵犯處若有齒頸牙釉投射（cervical enamel projection），宜於手術中移除，以免阻礙結締組織附著","(D) 相較於再生膜，使用牙釉基質蛋白（enamel matrix protein）可更有效降低根叉缺損深度及降低術後不適"],"answer":0,"clinical_level":"重點"},{"id":"ya3-110-1-70","subject":"ya3","topic":"牙周疾病與診斷","meta":"110年第1次第70題","year":110,"session":1,"number":70,"question":"關於biologic width的敘述，下列何者錯誤？","options":["(A) 意指牙周健康狀態下，附著於牙根之牙齦組織的寬度","(B) 又可區分為結締組織、連結上皮及角化黏膜三個部分","(C) 根據Gargiulo等人的研究結果，人類的biologic width平均大約為2 mm","(D) 當biologic width不足的時候，可透過手術或矯正方式修正"],"answer":1,"clinical_level":"重點"},{"id":"ya3-110-1-71","subject":"ya3","topic":"牙周手術與再生","meta":"110年第1次第71題","year":110,"session":1,"number":71,"question":"關於可吸收性再生膜的敘述，下列何者錯誤？","options":["(A) 可免去移除再生膜的二次手術","(B) 由巨噬細胞和多形核白血球的酵素活性反應所吸收","(C) 經由水解反應降解，並透過檸檬酸循環（Krebs cycle）排出","(D) 於牙周再生無法達到同等於不可吸收性再生膜的結果"],"answer":3,"clinical_level":"重點"},{"id":"ya3-110-1-72","subject":"ya3","topic":"牙周手術與再生","meta":"110年第1次第72題","year":110,"session":1,"number":72,"question":"關於牙根表面處理（root surface conditioning）的敘述，下列何者錯誤？","options":["(A) EDTA 能選擇性地移除牙根表面之氫氧基磷灰石（hydroxyapatite）並使膠原蛋白基質（collagenous matrix） 露出","(B) tetracycline 除了有抗菌功能外，還能抑制膠原蛋白的分解","(C) citric acid 能使牙根表面去礦化（demineralization）","(D) 牙根經表面處理後，能使表皮細胞更易往根尖方向生長（down-growth）"],"answer":3,"clinical_level":"重點"},{"id":"ya3-110-1-73","subject":"ya3","topic":"牙周疾病與診斷","meta":"110年第1次第73題","year":110,"session":1,"number":73,"question":"關於牙周病復發（recurrence）症狀的敘述，下列何者錯誤？","options":["(A) 牙周囊袋變深","(B) 牙齒動搖度增加","(C) X光片上有齒槽骨吸收現象","(D) 明顯牙結石堆積"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-1-74","subject":"ya3","topic":"窩洞設計與分類","meta":"110年第1次第74題","year":110,"session":1,"number":74,"question":"若病人是蛀牙的高危險群，在牙周治療完成後的維護期應多久拍攝一次後牙咬翼放射照片？","options":["(A) 每1～3個月","(B) 每6～18個月","(C) 每24～36個月","(D) 36個月以上"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-1-75","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第1次第75題","year":110,"session":1,"number":75,"question":"根據Seventh Report of the Joint National Committee（JNC-7）於預防、檢測、評估及治療高血壓的準則，下列 何種狀況可能被診斷為第一期高血壓（stage 1 hypertension）？","options":["(A) systolic BP介於120～139 mm Hg","(B) diastolic BP介於80～89 mm Hg","(C) systolic BP介於140～159 mm Hg或diastolic BP 介於90～99 mm Hg","(D) systolic BP大於160 mm Hg或diastolic BP大於100 mm Hg"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-1-76","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第1次第76題","year":110,"session":1,"number":76,"question":"對於肝臟疾病患者的牙周治療準則，下列何種敘述最正確？","options":["(A) 治療前需要查看患者凝血時間、出血時間等數值，但不用理會INR（international normalized ratio）數值","(B) 建議在肝臟移植治療前會診牙科，評估拔除感染風險較高的牙齒","(C) 多數肝臟疾病與藥物毒性相關，因此不用特別檢查或是詢問是否有B型肝炎病毒抗體","(D) 肝臟疾病的患者在牙科治療後，不建議給予任何藥物以免增加肝臟負擔"],"answer":1,"clinical_level":"重點"},{"id":"ya3-110-1-77","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第1次第77題","year":110,"session":1,"number":77,"question":"下列何者是帕比隆雷佛利症候群（Papillon-Lefèvre syndrome）病患的遺傳性障礙？","options":["(A) 白血球細胞黏附（adhesion）功能缺損","(B) 非特異性組織鹼性磷酸酶（tissue-nonspecific ALP）缺乏","(C) 蛋白酶C活性變異（mutation）","(D) 第21號染色體具三套染色體綜合症（trisomy 21）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-1-78","subject":"ya3","topic":"植牙學","meta":"110年第1次第78題","year":110,"session":1,"number":78,"question":"下列何種植體表面不是用消去法粗糙面（subtractive processes）的處理方式？","options":["(A) 噴砂（sand blast）","(B) 酸蝕（acid etching）","(C) 噴漿（plasma spraying）","(D) 研磨（machining）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-1-79","subject":"ya3","topic":"植牙學","meta":"110年第1次第79題","year":110,"session":1,"number":79,"question":"關於牙科種植體種植位置的敘述，下列何者錯誤？","options":["(A) 植體最少需與下齒槽神經保持2 mm以上的距離","(B) 植體最少需與mandibular foramen保持2 mm以上的距離","(C) 植體最少需與鄰接自然牙保持1.5-2.0 mm以上的距離","(D) 植體與植體間距至少2-3.0 mm"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-1-80","subject":"ya3","topic":"植牙學","meta":"110年第1次第80題","year":110,"session":1,"number":80,"question":"鈦金屬人工植體周圍結締組織，其膠原纖維的走向通常為下列何者？","options":["(A) 垂直於鈦金屬表面","(B) 平行於鈦金屬表面","(C) 雜亂無章","(D) 完全無接觸"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-2-1","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第2次第1題","year":110,"session":2,"number":1,"question":"牙齒發育中的那個階段，會開始生成牙本質（dentin）？","options":["(A) 蕾期（Bud stage）","(B) 梨形期（Pear stage）","(C) 鐘形期（Bell stage）","(D) 帽狀期（Cap stage）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-2-2","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第2次第2題","year":110,"session":2,"number":2,"question":"下列細胞或組織依牙齒形成時由前至後生成的順序，何者正確？①前造釉細胞（preameloblast） ②造釉母細 胞（ameloblast） ③前造牙本質細胞（ preodontoblast） ④造牙本質細胞（odontoblast ） ⑤牙釉質 （enamel） ⑥牙本質（dentin）","options":["(A) ①③④⑥②⑤","(B) ①②⑤③④⑥","(C) ③④⑥①②⑤","(D) ①③②⑤④⑥"],"answer":0,"clinical_level":"重點"},{"id":"ya3-110-2-3","subject":"ya3","topic":"牙髓診斷與病理","meta":"110年第2次第3題","year":110,"session":2,"number":3,"question":"若根管治療後，仍持續有根尖周圍炎（apical periodontitis），那一種微生物（microbe）最常會在根管內被檢測 到？","options":["(A) Enterococcus faecalis","(B) Porphyromonas endodontalis","(C) Prevotella intermedia","(D) Candida albicans"],"answer":0,"clinical_level":"重點"},{"id":"ya3-110-2-4","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第2次第4題","year":110,"session":2,"number":4,"question":"病患求診症狀為臉部右側反覆的劇烈刺痛（sharp, shooting, repetitive）且具觸發區域（trigger zone），臉部外 觀無紅腫，最有可能的診斷為何？","options":["(A) 鼻竇炎（sinusitis）","(B) 三叉神經痛（trigeminal neuralgia）","(C) 不可逆牙髓炎（irreversible pulpitis）","(D) 蜂窩性組織炎（cellulitis）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-2-5","subject":"ya3","topic":"根管治療程序","meta":"110年第2次第5題","year":110,"session":2,"number":5,"question":"拍攝根管治療診斷與治療用途的根尖片時，關於X光片錐體偏移角度（cone shift angle）的敘述，下列何者錯 誤？","options":["(A) 下顎臼齒應該由遠心往近心偏移20度拍攝","(B) 上顎小臼齒應該由近心往遠心偏移20度拍攝","(C) 下顎門齒應由遠心往近心偏移20度拍攝","(D) 上顎門齒應由近心往遠心偏移20度拍攝"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-2-6","subject":"ya3","topic":"牙髓診斷與病理","meta":"110年第2次第6題","year":110,"session":2,"number":6,"question":"根尖周圍炎（apical periodontitis）所導致的骨吸收，和下列何者較無關係？","options":["(A) TNF-α","(B) TNF-β","(C) IL-1","(D) IL-6"],"answer":1,"clinical_level":"重點"},{"id":"ya3-110-2-7","subject":"ya3","topic":"牙齒外傷處理","meta":"110年第2次第7題","year":110,"session":2,"number":7,"question":"下列各種牙齒外傷在做完適當的緊急處理後，何者最需要再進行根管治療？","options":["(A) 複雜性牙冠斷裂（complicated crown fracture）","(B) 橫向牙根斷裂（horizontal root fracture）","(C) 半脫位齒（subluxation）","(D) 根尖已閉合之內縮脫位齒（intrusive luxation）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-2-8","subject":"ya3","topic":"牙齒外傷處理","meta":"110年第2次第8題","year":110,"session":2,"number":8,"question":"關於牙齒脫落（avulsion）的相關敘述，下列何者正確？","options":["(A) 在口外乾燥時間小於60分鐘時，牙根尖發育完成（closed apex）的牙齒，有機會讓血管再生 （revascularization）","(B) 在口外乾燥時間小於60分鐘時，牙根尖尚未閉合（open apex）的牙齒，在植回前將牙根表面覆蓋二甲胺四 環素（minocycline），可有效增加血管再生的機會","(C) 在口外乾燥時間大於60分鐘時，牙根尖發育完成（closed apex）的牙齒，在植回前需要盡力保存牙根上的牙 周韌帶","(D) 在口外乾燥時間大於60分鐘時，牙根尖尚未閉合（open apex）的牙齒，因為預後不好所以不建議植回"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-2-9","subject":"ya3","topic":"牙齒外傷處理","meta":"110年第2次第9題","year":110,"session":2,"number":9,"question":"牙齒外傷後的活髓治療（vital pulp therapy），下列敘述何者正確？","options":["(A) 無發炎的牙髓對於活髓治療至關重要，因此在前48小時是最佳的治療時間","(B) 使用氫氧化鈣作為活髓治療的敷料（dressing），有抗菌消毒及使牙髓接觸面液化壞死效果","(C) 氫氧化鈣作為活髓治療的敷料（dressing）時，不會對牙髓產生毒性刺激","(D) MTA（mineral trioxide aggregate）和氫氧化鈣的封閉（seal）效果相同"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-2-10","subject":"ya3","topic":"牙髓診斷與病理","meta":"110年第2次第10題","year":110,"session":2,"number":10,"question":"關於由齒源性（odontogenic）感染所造成的疼痛，下列敘述何者錯誤？","options":["(A) 正確而迅速的止痛來自正確的診斷、明確的牙科治療及藥物的使用","(B) 根管治療術後疼痛在服用類固醇後的4～8小時通常有明顯的改善","(C) 根管治療前30分鐘服用抗生素可以減少急性牙髓炎術後疼痛","(D) 根管治療前服用非類固醇抗發炎藥物（NSAID），可以減少根管治療前與根管治療後產生的疼痛"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-2-11","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第2次第11題","year":110,"session":2,"number":11,"question":"因牙髓病變而產生中重度牙痛之患者，若在服用Ibuprofen 600～800 mg後仍然無法止痛時，可以考慮同時合 併使用下列那一種藥物以緩解疼痛？","options":["(A) Acetaminophen 500 mg","(B) Acetaminophen 1000 mg","(C) Amoxicillin 500 mg","(D) Amoxicillin 1000 mg"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-2-12","subject":"ya3","topic":"根管器械","meta":"110年第2次第12題","year":110,"session":2,"number":12,"question":"關於鎳鈦金屬器械，下列敘述何者錯誤？","options":["(A) 近年新改良推出的鎳鈦金屬器械，其合金彈性為傳統鎳鈦金屬合金的50倍","(B) 經由電解拋光（electropolished）的表面處理後，能改善器械抗斷裂的能力","(C) 反覆的高溫滅菌過程並不會明顯降低該器械的抗斷裂強度","(D) 若在器械表面鍍上一層氮化鈦（titanium nitride）將可增加切割效率"],"answer":0,"clinical_level":"重點"},{"id":"ya3-110-2-13","subject":"ya3","topic":"根管治療程序","meta":"110年第2次第13題","year":110,"session":2,"number":13,"question":"C型根管系統（C-shaped root canal system）較不常發生在下列那一個恆齒齒位？","options":["(A) 下顎第一小臼齒","(B) 下顎第二小臼齒","(C) 下顎第一大臼齒","(D) 下顎第二大臼齒"],"answer":[0,1,2],"clinical_level":"重點","explanation_pending":false},{"id":"ya3-110-2-14","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第2次第14題","year":110,"session":2,"number":14,"question":"依超音波（ultrasonic）的定義，頻率在多少赫茲（Hz）以上為超音波？","options":["(A) 4,500","(B) 9,500","(C) 15,000","(D) 25,000"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-2-15","subject":"ya3","topic":"根管治療程序","meta":"110年第2次第15題","year":110,"session":2,"number":15,"question":"根管治療中常建議大量使用沖洗液來清潔根管，其目的不包括下列何者？","options":["(A) 可能對器械所達不到的區域做清潔及殺菌的功用","(B) 可能保存塗抹層（smear layer）阻擋細菌入侵","(C) 可能有效去除修形中的殘屑並濕潤管壁","(D) 可能有效破壞細菌微生物"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-2-16","subject":"ya3","topic":"牙髓診斷與病理","meta":"110年第2次第16題","year":110,"session":2,"number":16,"question":"下列何者不是臺灣較常見的牙根與牙髓解剖構造變異（variation）？","options":["(A) 齒外齒（dens evaginatus）","(B) 牛狀齒（Taurodontism）","(C) 具有遠心舌側根（distolingual root）的下顎第一大臼齒","(D) C型根管（C-shaped root canal system）"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-2-17","subject":"ya3","topic":"根尖手術與再治療","meta":"110年第2次第17題","year":110,"session":2,"number":17,"question":"關於牙根尖切除術（apical root-end resection）的敘述，下列何者錯誤？","options":["(A) 切面應儘量垂直牙根長軸","(B) 可用檸檬酸（citric acid）來移除切面的塗抹層（smear layer）","(C) 切除3 mm牙根尖可移除大部分的根管分支（ramification）","(D) 使用鑽石裂溝磨針（diamond fissure bur）可得到平滑的根尖切除表面（smooth resected root-end surface）"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-2-18","subject":"ya3","topic":"根尖手術與再治療","meta":"110年第2次第18題","year":110,"session":2,"number":18,"question":"關於牙齒根尖手術術前的考量，下列敘述何者錯誤？","options":["(A) 下顎第一大臼齒必須注意皮瓣垂直切線傷到頦神經","(B) 上顎第一大臼齒顎側牙根切除也可以從頰側牙齦翻起皮瓣進入切除","(C) 上顎犬齒的前庭區較淺，牙根較長，因此應先移除根尖病灶再切除牙根尖","(D) 切除上顎小臼齒要小心，避免切除的牙根掉入鼻竇"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-2-19","subject":"ya3","topic":"牙周手術與再生","meta":"110年第2次第19題","year":110,"session":2,"number":19,"question":"如果計劃對已裝上假牙的上顎側門齒（根管內有長又深的根柱）做探查手術（exploratory flap operation），下 列術式的考量何者錯誤？","options":["(A) 術前先與病人討論一旦確認牙齒已經發生垂直牙根斷裂，做探查手術時是否可以一併拔除","(B) 全部黏膜骨膜（full mucoperiosteal）翻瓣術式，可能造成假牙邊緣附連牙齦萎縮","(C) 全部黏膜骨膜翻瓣術式，可以見到齒頸部牙根是否已經發生垂直牙根斷裂","(D) 適合使用部分黏膜骨膜（limited mucoperiosteal）翻瓣術式，因為假牙邊緣附連牙齦不會萎縮且垂直牙根斷 裂常發生在牙根尖"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-2-20","subject":"ya3","topic":"根管治療程序","meta":"110年第2次第20題","year":110,"session":2,"number":20,"question":"關於根管穿孔修補材料MTA（mineral trioxide aggregate）的敘述，下列何者錯誤？","options":["(A) 擁有絕佳的生物相容性","(B) 對穿孔封閉的能力佳","(C) 在發炎的環境下能順利硬化","(D) 長期追蹤預後非常穩定理想"],"answer":2,"clinical_level":"重點"},{"id":"ya3-110-2-21","subject":"ya3","topic":"根管治療程序","meta":"110年第2次第21題","year":110,"session":2,"number":21,"question":"根管清潔與修形（cleaning and shaping）的過程中造成平台（ledge）的主要原因，下列敘述何者錯誤？","options":["(A) 直線入口（straight-line access）修形不足","(B) 根管沖洗或潤滑不足","(C) 根管彎曲處擴大不足","(D) 修形產生的碎屑塞住根管的根尖部位"],"answer":2,"clinical_level":"重點"},{"id":"ya3-110-2-22","subject":"ya3","topic":"根管治療程序","meta":"110年第2次第22題","year":110,"session":2,"number":22,"question":"臨床上常用來移除馬來膠的方式，不包括下列何者？","options":["(A) 使用可以恆定輸出的熱能器械軟化並取出","(B) 使用鎳鈦（Ni-Ti）旋轉器械取出","(C) 使用尤加利油（eucalyptol）軟化並取出","(D) 直接使用蓋氏鑽針（GG drill）下到根尖部將之取出"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-2-23","subject":"ya3","topic":"牙周疾病與診斷","meta":"110年第2次第23題","year":110,"session":2,"number":23,"question":"下列的檢查方法中，那一種最能鑑別診斷患齒是牙周疾病或是牙髓疾病？","options":["(A) 牙齒動搖度測試","(B) 牙周囊袋探測","(C) 膿腫（abscess）或竇管（sinus tract）發生的位置","(D) 敲診與觸診檢查"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-2-24","subject":"ya3","topic":"牙髓診斷與病理","meta":"110年第2次第24題","year":110,"session":2,"number":24,"question":"牙周疾病對牙髓的影響，下列敘述何者錯誤？","options":["(A) 可能會刺激修復性牙本質（reparative dentin）形成","(B) 牙本質是很好的絕緣體，所以不會造成牙髓發炎","(C) 嚴重時會引起牙髓發炎甚至壞死","(D) 當牙周嚴重破壞到根尖孔時可能造成牙髓的病變"],"answer":1,"clinical_level":"重點"},{"id":"ya3-110-2-25","subject":"ya3","topic":"窩洞設計與分類","meta":"110年第2次第25題","year":110,"session":2,"number":25,"question":"對於接受根管治療的牙齒，下列敘述何者錯誤？","options":["(A) 冠部填補物（coronal restoration）脫落時間超過3個月時，患齒必須重新進行根管治療","(B) 喪失近心邊緣脊（marginal ridge）的臼齒，根管治療後不建議使用複合樹脂填補進行永久復形","(C) 應等根尖病灶完全癒合，再進行贋復牙冠的製作","(D) 齒質結構完整的牙齒，不需要置放根柱（post）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-2-26","subject":"ya3","topic":"醫學倫理與法規","meta":"110年第2次第26題","year":110,"session":2,"number":26,"question":"關於知情同意（informed consent），下列敘述何者錯誤？","options":["(A) 內容包含此治療的優缺點以及替代的治療方式","(B) 應使用病患能了解的語彙","(C) 可以由櫃臺的助理告知病患並交付病患簽署之","(D) 知情同意中的治療選項必須符合標準化的醫療照護（standard of care）"],"answer":2,"clinical_level":"重點"},{"id":"ya3-110-2-27","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第2次第27題","year":110,"session":2,"number":27,"question":"有關牙本質小管（dentinal tubules）之敘述，下列何者錯誤？","options":["(A) 牙本質小管在牙冠呈略為S形，但是在前牙尖端、咬頭及牙根處較直","(B) 牙本質小管的管周牙本質（peritubular dentin）礦化程度比周圍的管間牙本質（intertubular dentin）更高","(C) 單位面積下牙本質小管的數目，在牙本質牙釉質交界處（DEJ）比在接近牙髓腔處多","(D) 牙本質小管內含的 Tomes' fiber，是牙本質細胞突（odontoblast process）"],"answer":2,"clinical_level":"重點"},{"id":"ya3-110-2-28","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第2次第28題","year":110,"session":2,"number":28,"question":"在牙本質中，礦化程度（mineralization）最高的是下列何者？","options":["(A) 管周牙本質（peritubular dentin）","(B) 管間牙本質（intertubular dentin）","(C) 球狀牙本質（globular dentin）","(D) 被覆牙本質（mantle dentin）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-110-2-29","subject":"ya3","topic":"窩洞設計與分類","meta":"110年第2次第29題","year":110,"session":2,"number":29,"question":"如下圖所示，初期齲齒在偏光顯微鏡下形成四個區域，下列何者標示正確？","options":["(A) a-完整表面（intact surface layer）；b-病灶體（body of the lesion）；c-暗區（dark zone）；d-透光區 （translucent zone）","(B) a-完整表面（intact surface layer）；b-透光區（translucent zone）；c-病灶體（body of the lesion）；d-暗區 （dark zone）","(C) a-透光區（translucent zone）；b-病灶體（body of the lesion）；c-暗區（dark zone）；d-完整表面（intact surface layer）","(D) a-完整表面（intact surface layer）；b-透光區（translucent zone）；c-暗區（dark zone）；d-病灶體（body of the lesion）"],"answer":0,"image":"ya3-110-2-29.jpeg","clinical_level":"一般"},{"id":"ya3-110-2-30","subject":"ya3","topic":"窩洞設計與分類","meta":"110年第2次第30題","year":110,"session":2,"number":30,"question":"下列何者不能作為高齲齒罹患率的指標？","options":["(A) 既有填充物邊緣完整性","(B) 過去兩年內新發生齲齒的數目","(C) 唾液分泌量","(D) 所有齒列中齲齒的數目"],"answer":0,"clinical_level":"一般"},{"id":"ya3-110-2-31","subject":"ya3","topic":"牙髓診斷與病理","meta":"110年第2次第31題","year":110,"session":2,"number":31,"question":"下列何者最可能是造成牙齒的舌側面、切緣面與咬合面廣泛性酸蝕的病因？","options":["(A) 胃食道逆流","(B) 口腔清潔不徹底","(C) 酸性飲料","(D) 抽菸"],"answer":0,"clinical_level":"一般"},{"id":"ya3-110-2-32","subject":"ya3","topic":"黏著與美學修復","meta":"110年第2次第32題","year":110,"session":2,"number":32,"question":"牙科常見的吸附黏結（adsorption adhesion）中，下列何者是初級鍵結（primary bond）？①氫鍵（hydrogen bond） ②離子鍵（ionic bond） ③共價鍵（covalent bond） ④凡得瓦力（van der Waals force）","options":["(A) ①②","(B) ②③","(C) ③④","(D) ①④"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-2-33","subject":"ya3","topic":"黏著與美學修復","meta":"110年第2次第33題","year":110,"session":2,"number":33,"question":"關於以磷酸酸蝕牙本質的敍述，下列何者錯誤？","options":["(A) 減少牙本質小管間的微小孔洞（microporosity）","(B) 部份或全部移除塗抹層（smear layer）","(C) 牙本質去礦化深度可達 7.5 μm","(D) 露出牙本質膠原纖維（collagen fiber）"],"answer":0,"clinical_level":"一般"},{"id":"ya3-110-2-34","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第2次第34題","year":110,"session":2,"number":34,"question":"關於磨牙產生噪音對聽力造成傷害的敘述，下列何者錯誤？","options":["(A) 聲音的強度（intensity）高，容易造成傷害","(B) 低頻比高頻容易造成傷害","(C) 個人對聲音的敏感度高，容易造成傷害","(D) 聲音產生時間長，容易造成傷害"],"answer":1,"clinical_level":"重點(深度)"},{"id":"ya3-110-2-35","subject":"ya3","topic":"醫學倫理與法規","meta":"110年第2次第35題","year":110,"session":2,"number":35,"question":"牙醫師看診時，關於病患在診療椅上位置之敘述，下列何者錯誤？","options":["(A) 當牙醫師治療上顎牙齒時，病患上顎咬合面角度應與地面垂直","(B) 病患頭部可左右調整位置，讓醫師的視野更清楚","(C) 病患在診療椅上的高度，要低於牙醫師手肘的高度","(D) 病患的頭部位置不得低於其腳部高度"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-2-36","subject":"ya3","topic":"牙體修形程序","meta":"110年第2次第36題","year":110,"session":2,"number":36,"question":"下圖的工具適用於汞齊填補中何種作用？","options":["(A) 填壓（condensing）","(B) 雕刻（carving）","(C) 研光（burnishing）","(D) 拋光（polishing）"],"answer":2,"image":"ya3-110-2-36.jpeg","clinical_level":"一般"},{"id":"ya3-110-2-37","subject":"ya3","topic":"複合樹脂與材料","meta":"110年第2次第37題","year":110,"session":2,"number":37,"question":"關於高銅汞齊合金（high copper amalgam alloy）的敘述，下列何者錯誤？","options":["(A) 銅含量的重量百分比通常大於 12%","(B) 降低汞錫合金（gamma II）的生成","(C) 增加潛變（creep）的機率","(D) 降低汞齊合金產生腐蝕（corrosion）的產物"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-2-38","subject":"ya3","topic":"複合樹脂與材料","meta":"110年第2次第38題","year":110,"session":2,"number":38,"question":"有關提高複合樹脂聚合程度的方式，下列何者錯誤？","options":["(A) 增加光聚機照射的距離","(B) 提高光聚機照射的強度","(C) 增加光聚機照射的時間","(D) 分層填補方式"],"answer":0,"clinical_level":"一般"},{"id":"ya3-110-2-39","subject":"ya3","topic":"複合樹脂與材料","meta":"110年第2次第39題","year":110,"session":2,"number":39,"question":"關於臨床上複合樹脂填補完成後，有時會在填補牙齒上出現白線（white line）現象的敘述，下列何者錯誤？","options":["(A) 可能由於修形過程中，切削器械造成牙齒微斷裂而產生","(B) 可能由於複合樹脂不適當的聚合收縮而產生","(C) 為避免白線發生，應由牙齒往樹脂方向拋光（polish）","(D) 如果發生在美觀區，則可用鑽針移除，再用樹脂修補即可"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-2-40","subject":"ya3","topic":"複合樹脂與材料","meta":"110年第2次第40題","year":110,"session":2,"number":40,"question":"進行複合樹脂充填治療時，其操作之順序應為何？①上橡皮障 ②窩洞修形 ③比色 ④充填","options":["(A) ①→②→③→④","(B) ②→③→①→④","(C) ③→①→②→④","(D) ①→③→②→④"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-2-41","subject":"ya3","topic":"黏著與美學修復","meta":"110年第2次第41題","year":110,"session":2,"number":41,"question":"關於使用複合樹脂進行間隙關閉（diastema closure）的敘述，下列何者正確？","options":["(A) 一定要進行牙釉質切削以得到最佳之黏著效果","(B) 所謂黃金比率是指由正面觀（facial view）直視，上顎正中門齒：側門齒：犬齒之近遠心寬度比值為 1.618： 0.618：1","(C) 為達到對稱，間隙關閉時要同時兩側一起施作","(D) 在填補時可以不使用木楔（wooden wedge）"],"answer":3,"clinical_level":"重點"},{"id":"ya3-110-2-42","subject":"ya3","topic":"牙體修形程序","meta":"110年第2次第42題","year":110,"session":2,"number":42,"question":"關於Tofflemire matrix system應用於後牙二類窩洞，下列敘述何者正確？①其頭部（head）的溝槽（slot）方向 朝向牙齦端 ②其頭部（head）的溝槽（slot）方向朝向咬合平面 ③金屬隔片（matrix band）放入型帶固位 器（matrix retainer）後，隔片彎曲形成的較大開口應朝向咬合平面 ④金屬隔片（matrix band）放入型帶固 位器（matrix retainer）後，隔片彎曲形成的較大開口應朝向牙齦端","options":["(A) ①③","(B) ①④","(C) ②③","(D) ②④"],"answer":0,"clinical_level":"一般"},{"id":"ya3-110-2-43","subject":"ya3","topic":"複合樹脂與材料","meta":"110年第2次第43題","year":110,"session":2,"number":43,"question":"在複合樹脂填補時，使用RMGI （resin-modified glass ionomer）做窩洞底墊的優點，下列敘述何者錯誤？","options":["(A) 可減少術後敏感的機會","(B) RMGI 可和樹脂及牙齒產生鍵結","(C) 可減緩樹脂聚合時產生的收縮應力","(D) RMGI 的斷裂韌性（fracture toughness）比複合樹脂高"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-2-44","subject":"ya3","topic":"窩洞設計與分類","meta":"110年第2次第44題","year":110,"session":2,"number":44,"question":"關於陶瓷嵌體（inlay）窩洞製備的原則，下列敘述何者錯誤？","options":["(A) 峽（isthmus）的寬度修磨至少 1.5～2 mm","(B) 功能咬頭（functional cusp）的咬合修磨至少 1.5～2 mm","(C) 頰舌側軸向修磨（axial reduction）至少 1～1.5 mm","(D) 鄰接面邊緣（proximal margin）可與鄰牙接觸"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-2-45","subject":"ya3","topic":"窩洞設計與分類","meta":"110年第2次第45題","year":110,"session":2,"number":45,"question":"關於第一類的汞齊窩洞修形，下列敘述何者錯誤？","options":["(A) 咬合面兩個窩洞的間距若小於 0.5 mm 就需要合而為一","(B) 保留邊緣嵴（marginal ridge）時，需有 1.0 mm 的寬度","(C) 近遠心壁應向咬合面開展（divergence）","(D) 髓腔壁（pulpal wall）至少需進入牙本質內 0.1～0.2 mm"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-2-46","subject":"ya3","topic":"牙體修形程序","meta":"110年第2次第46題","year":110,"session":2,"number":46,"question":"汞齊填補時，填壓、雕刻與研光（burnishing）的敘述，下列何者錯誤？","options":["(A) 窩洞過量填壓（overpack）後，立即做研光的步驟","(B) 進行雕刻前研光（pre-carve burnishing）時，為預防汞齊斷裂，研光時力量要輕","(C) 初始的雕刻可用較大的盤狀－梨狀（discoid-cleoid）的器械","(D) 雕刻出過深的咬合面溝，可能導致邊緣的汞齊產生碎片斷裂（chipping）"],"answer":1,"clinical_level":"重點"},{"id":"ya3-110-2-47","subject":"ya3","topic":"複合樹脂與材料","meta":"110年第2次第47題","year":110,"session":2,"number":47,"question":"鋅（Zinc）添加入汞齊合金內，不會產生下列何種效應？","options":["(A) 降低邊緣斷裂","(B) 在低銅的汞齊中，口水污染可能造成體積膨脹","(C) 降低 gamma-2 phase","(D) 增加機械強度"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-2-48","subject":"ya3","topic":"窩洞設計與分類","meta":"110年第2次第48題","year":110,"session":2,"number":48,"question":"有關鑄造金屬嵌體的牙齦邊緣及咬合邊緣要加上斜面（bevel），下列敘述何者正確？","options":["(A) 可保留邊緣的牙本質","(B) 此斜面為 45 度角","(C) 可以增加邊緣密合度","(D) 可增加印模的精準度"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-2-49","subject":"ya3","topic":"黏著與美學修復","meta":"110年第2次第49題","year":110,"session":2,"number":49,"question":"下列有關陶瓷嵌體的臨床治療步驟，何者錯誤？","options":["(A) 不需把牙齒吹乾再比色，以避免齒質過度脫水，造成比色不正確","(B) 使用不含丁香油酚（eugenol）的暫時黏著劑固定暫時填補物","(C) 黏著前先把嵌體放到牙齒上檢查密合度，並以咬合紙確認是否有咬合干擾","(D) 黏著時需要有良好的隔濕環境，以避免濕氣、唾液或是血液的汙染"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-2-50","subject":"ya3","topic":"黏著與美學修復","meta":"110年第2次第50題","year":110,"session":2,"number":50,"question":"在前牙美學方面，關於顏色方面考量的敘述，下列何者錯誤？","options":["(A) 顏色的基本參考要件為色調（hue）、明度（value）、彩度（chroma）","(B) 牙齒的顏色會隨著年紀而變化，多是因為磨耗（wear）導致","(C) 比色應在防水隔濕後與清理乾淨後，才能判斷出較精確的顏色","(D) 不同光線對相同物體的顏色判斷會有不同的結果，又稱為同色異構現象（metamerism）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-2-51","subject":"ya3","topic":"黏著與美學修復","meta":"110年第2次第51題","year":110,"session":2,"number":51,"question":"關於互補色在牙科美學的應用，下列何者錯誤？","options":["(A) 填補時加入紫色顏色改良劑（violet color modifier），可以淡化牙齒本身的黃色","(B) 填補時加入紫色與灰色顏色改良劑混合物（mixture of gray and violet color modifier），可以增加齒頸部的半 透明度（translucency）","(C) 填補時加入紫色顏色改良劑（violet color modifier），可以增加明亮度（brightness）","(D) 視覺疲勞時會降低對黃橘色的敏感度"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-2-52","subject":"ya3","topic":"牙髓診斷與病理","meta":"110年第2次第52題","year":110,"session":2,"number":52,"question":"下列何者是造成附圖中牙齒變色的主要原因？","options":["(A) 四環黴素染色（tetracycline-stained teeth）","(B) 氟斑齒（dental fluorosis）","(C) 不良的口腔衛生","(D) 牙釉質發育不全（enamel hypoplasia）"],"answer":0,"image":"ya3-110-2-52.jpeg","clinical_level":"一般"},{"id":"ya3-110-2-53","subject":"ya3","topic":"牙周疾病與診斷","meta":"110年第2次第53題","year":110,"session":2,"number":53,"question":"關於牙骨質增生（hypercementosis）的敘述，下列何者錯誤？","options":["(A) 與年齡有關係","(B) 可發生於單顆牙或全部牙齒","(C) 在X光片上無法與根尖牙骨質發育不良（periapical cemental dysplasia）做鑑別診斷","(D) 脊狀型（spikelike）牙骨質增生通常是源自太大之矯正或咬合力量"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-2-54","subject":"ya3","topic":"牙周手術與再生","meta":"110年第2次第54題","year":110,"session":2,"number":54,"question":"下列何者是牙周翻瓣手術後，手術區域皮瓣（flap）不發生缺血性壞死的主要原因？","options":["(A) 手術區域富含小動脈","(B) 手術區域富含小靜脈","(C) 手術區域富含側支循環（collateral circulation）","(D) 手術區域富含預留小動脈"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-2-55","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第2次第55題","year":110,"session":2,"number":55,"question":"關於牙周韌帶主要纖維的敘述，下列何者正確？","options":["(A) 通稱為夏庇氏的纖維（Sharpey's fiber）","(B) 垂直于齒槽骨和牙骨質","(C) 夏庇氏的纖維有一定程度上鈣化","(D) 與豐富的Type II 膠原蛋白相關"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-2-56","subject":"ya3","topic":"牙周疾病與診斷","meta":"110年第2次第56題","year":110,"session":2,"number":56,"question":"關於牙齦纖維及細胞的敘述，下列何者錯誤？","options":["(A) 橫中隔纖維（transseptal fibers）分布在鄰近牙齒的齒槽上牙骨質","(B) 造纖維細胞除了合成膠原纖維及結締組織的基質外，也參與膠原纖維的降解（degradation）","(C) 臨床上正常的牙齦可以發現漿細胞及淋巴球在接近牙齦溝底部的結締組織中","(D) 牙齦手術後，通常可發現牙齦有疤痕現象"],"answer":3,"clinical_level":"重點"},{"id":"ya3-110-2-57","subject":"ya3","topic":"牙周疾病與診斷","meta":"110年第2次第57題","year":110,"session":2,"number":57,"question":"關於壞死潰瘍性牙周炎（NUP）的敘述，下列何者正確？","options":["(A) 未治療的壞死潰瘍性牙齦炎（NUG）經過長久時間一定會轉變成NUP","(B) Deep probing depth是診斷的重要依據","(C) 其只會發生於HIV（+）或AIDS患者","(D) NUP與NUG在HIV（+）的患者上，其二者細菌的組成相似"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-2-58","subject":"ya3","topic":"牙周疾病與診斷","meta":"110年第2次第58題","year":110,"session":2,"number":58,"question":"關於社區牙周治療需求指數（CPITN）的敘述，下列何者錯誤？","options":["(A) 將全口牙齒分成6個區域（sextants）檢查","(B) Code 1：是指該區域檢查沒有牙周囊袋、出血及牙結石與不良的補綴物","(C) Code 2：是指該區域檢查沒有牙周囊袋超過3 mm，但在牙周囊袋中有牙結石存在","(D) Code 4：是指該區域受檢查的牙齒的牙周囊袋超過6 mm"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-2-59","subject":"ya3","topic":"牙周疾病與診斷","meta":"110年第2次第59題","year":110,"session":2,"number":59,"question":"下列何者不是牙周病的危險因子（risk factor）？","options":["(A) 性別","(B) 抽菸","(C) 糖尿病","(D) 牙周致病細菌"],"answer":0,"clinical_level":"重點"},{"id":"ya3-110-2-60","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第2次第60題","year":110,"session":2,"number":60,"question":"關於流行病學調查牙齒喪失或拔除的原因的敘述，下列何者錯誤？","options":["(A) 年齡一直到40～45歲主要的原因是齲齒","(B) 齲齒和牙周病是造成老年人牙齒喪失的原因","(C) 整體而言，牙齒拔除的原因，齲齒占30～35%，牙周病占將近50%","(D) 抽菸也是造成牙齒喪失的風險因子"],"answer":2,"clinical_level":"重點"},{"id":"ya3-110-2-61","subject":"ya3","topic":"牙周疾病與診斷","meta":"110年第2次第61題","year":110,"session":2,"number":61,"question":"關於牙周炎的免疫反應中T細胞與B細胞的敘述，下列何者錯誤？","options":["(A) 在進展的牙周炎中，Th2產生的細胞激素會增加","(B) B‐1細胞與T細胞相互作用後，可發展成記憶細胞（memory cells）和長壽命的漿細胞（long‐lived plasma cells）","(C) 白細胞介素12（IL-12）的濃度較低時，T細胞將朝Th2發展","(D) 在牙周炎中B細胞產生的免疫球蛋白主要是免疫球蛋白G，其次是免疫球蛋白M"],"answer":1,"clinical_level":"重點"},{"id":"ya3-110-2-62","subject":"ya3","topic":"牙周疾病與診斷","meta":"110年第2次第62題","year":110,"session":2,"number":62,"question":"關於牙周病原菌之毒性（virulence）的敘述，下列何者錯誤？","options":["(A) P.g. 與 T. denticola 產生 proteases分解免疫球蛋白分子和補體蛋白","(B) A.a. 產生leukotoxin 毒殺 PMNs","(C) P.g.釋出一因子來促進 PMNs 移至感染位點","(D) 由P.g.、Pi.、A.a.與Capnocytophga 等產生的toxins 會影響造纖維細胞"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-2-63","subject":"ya3","topic":"牙周疾病與診斷","meta":"110年第2次第63題","year":110,"session":2,"number":63,"question":"男性患者接受腎臟移植後，服用免疫抑制劑和抗血小凝集劑/鈣離子阻斷劑，有牙齦腫大的現象，則該藥劑最 可能為下列何者？","options":["(A) cyclosporin A + phenytoin","(B) dilatin + nifedipine","(C) cyclosporin A + nifedipine","(D) bleomycin + nifedipine"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-2-64","subject":"ya3","topic":"牙周非手術治療","meta":"110年第2次第64題","year":110,"session":2,"number":64,"question":"關於牙周病第一階段治療（phase I therapy）的敘述，下列何者正確？","options":["(A) 初次治療即須優先清創牙齦下的細菌性牙菌斑及牙結石","(B) 侵犯型牙周病的基本治療 , 抗生素療程是第一選項","(C) 完成第一階段治療後，可立即進入第二階段的手術治療","(D) 應先溝通並教導病患牙菌斑控制與照護，以啟動第一階段治療療程"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-2-65","subject":"ya3","topic":"牙周非手術治療","meta":"110年第2次第65題","year":110,"session":2,"number":65,"question":"非手術牙周病治療之手動器械結構，刀刃切緣（cutting edges）會通過下列何者的中心長軸？","options":["(A) blade","(B) lower shank","(C) face","(D) handle"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-2-66","subject":"ya3","topic":"牙周手術與再生","meta":"110年第2次第66題","year":110,"session":2,"number":66,"question":"關於Emdogain的敘述，下列何者正確？","options":["(A) 主成分amelogenin是由造牙本質細胞（odontoblast）分泌","(B) 臨床驗證可誘導牙骨質（cementum）與齒槽骨生成","(C) 誘導牙周骨再生能力與冷凍乾燥異體移植骨（FDBA）相當，但遜於異體骨移質材（xenograft）","(D) 不可與牙根表面處理（root conditioning）藥劑併用"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-2-67","subject":"ya3","topic":"牙周手術與再生","meta":"110年第2次第67題","year":110,"session":2,"number":67,"question":"牙周翻瓣手術術後需多長時間，牙齦溝會完全上皮化（epithelialization）且功能性排列的齒槽嵴上纖維 （supracrestal fibers）才會開始建立？","options":["(A) 2週","(B) 4週","(C) 8週","(D) 12週"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-2-68","subject":"ya3","topic":"牙周手術與再生","meta":"110年第2次第68題","year":110,"session":2,"number":68,"question":"關於施行牙冠增長術（crown lengthening）的考量，下列何者錯誤？","options":["(A) 一般而言，牙齦溝（gingival sulcus）底部至補綴物需至少有3 mm距離","(B) 一般而言，手術後在齒槽脊上至少要有4 mm完整的牙齒結構","(C) 除了欲預計治療的牙齒外，骨修型亦需在鄰近牙齒執行，以避免術後齒槽脊的高低落差","(D) 骨修型結合根向移位翻瓣手術（apically positioned flap with bone contouring）為進行上顎前牙區單一牙齒牙 冠增長術的禁忌症"],"answer":0,"clinical_level":"重點"},{"id":"ya3-110-2-69","subject":"ya3","topic":"牙周手術與再生","meta":"110年第2次第69題","year":110,"session":2,"number":69,"question":"骨切除術（resective osseous surgery）的選擇因素，下列敘述何者錯誤？","options":["(A) 應用在2～3 mm 骨喪失，合併中等長度牙根幹（root trunk）的1～2骨壁缺損（1～2 walled defect）最理想","(B) 患者有嚴重的附連喪失及深的骨內缺損，不適合做此種手術","(C) 患者的骨內缺損是3骨壁（three-walled defects）","(D) 理想的齒槽骨邊緣外型應呈現正向結構（positive architecture）"],"answer":2,"clinical_level":"重點"},{"id":"ya3-110-2-70","subject":"ya3","topic":"牙周手術與再生","meta":"110年第2次第70題","year":110,"session":2,"number":70,"question":"下列何者不是常見的皮下結締組織移植（connective tissue graft）的來源？","options":["(A) 硬腭（hard palate）","(B) 軟腭（soft palate）","(C) 下腭臼齒後墊（retromolar pad）","(D) 上腭粗隆（maxillary tuberosity）"],"answer":1,"clinical_level":"重點"},{"id":"ya3-110-2-71","subject":"ya3","topic":"牙周手術與再生","meta":"110年第2次第71題","year":110,"session":2,"number":71,"question":"利用血小板可提供生長因子（growth factors）的觀念，在臨床上蒐集不含抗凝血劑的周邊血成份，藉以得下 列何種再生材？","options":["(A) PRP","(B) PRF","(C) PDGF","(D) FGF"],"answer":1,"clinical_level":"一般"},{"id":"ya3-110-2-72","subject":"ya3","topic":"牙周手術與再生","meta":"110年第2次第72題","year":110,"session":2,"number":72,"question":"下列附圖為何種牙周翻瓣術式？","options":["(A) modified Widman flap","(B) papilla preservation flap","(C) apically repositioned flap","(D) coronally repositioned flap"],"answer":1,"image":"ya3-110-2-72.jpeg","clinical_level":"重點"},{"id":"ya3-110-2-73","subject":"ya3","topic":"牙周非手術治療","meta":"110年第2次第73題","year":110,"session":2,"number":73,"question":"關於牙周治療完成之後的維持期（maintenance phase），若病人牙周狀況控制不好，有復發的牙周囊袋以及口 腔衛生不甚理想，應建議患者多久拍攝全口牙根尖片和後咬翼放射照片（posterior bite-wing examination）？","options":["(A) 每6個月","(B) 每6～18個月","(C) 每12～24個月","(D) 每24～36個月"],"answer":[0,1,2,3],"clinical_level":"一般","explanation_pending":false},{"id":"ya3-110-2-74","subject":"ya3","topic":"牙周疾病與診斷","meta":"110年第2次第74題","year":110,"session":2,"number":74,"question":"在維持期（maintenance phase）時發現病人有變深的牙周囊袋以及X光片上可以觀察到齒槽骨破壞，下列何者 是最不可能的原因？","options":["(A) 牙齒斷裂（cracked teeth）","(B) 設計不良的補綴物","(C) 系統性疾病改變宿主免疫力","(D) 藥物導致牙齦腫大"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-2-75","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第2次第75題","year":110,"session":2,"number":75,"question":"有心絞痛病史的患者在牙周病治療過程中，突然感到呼吸急促且胸口疼痛。請問下列處置何者最正確？","options":["(A) 暫停一切牙科治療，立即讓患者坐起休息","(B) 給予一顆0.3 mg的nitroglycerin吞服，若三分鐘內未緩解再給一顆","(C) 給予患者氧氣並保持直立坐姿觀察。若患者不適的症狀在三分鐘內緩解，可以繼續完成牙周病治療","(D) 若三分鐘後患者仍感到胸口疼痛，可以給予第二顆nitroglycerin（0.3 mg），並準備轉送急診"],"answer":3,"clinical_level":"一般"},{"id":"ya3-110-2-76","subject":"ya3","topic":"牙科解剖與生理","meta":"110年第2次第76題","year":110,"session":2,"number":76,"question":"牙科初診患者如果懷疑有糖尿病，以下狀況何者最需轉介至新陳代謝科進一步評估？","options":["(A) 有糖尿病症狀且隨機血糖值（casual glucose）大於或等於200 mg/dL","(B) 有糖尿病症狀且空腹血糖值（fasting blood glucose）大於或等於100 mg/dL","(C) glycosylated hemoglobin（HbA1c）檢驗數值為7%","(D) 容易緊張且有頻尿症狀"],"answer":0,"clinical_level":"一般"},{"id":"ya3-110-2-77","subject":"ya3","topic":"牙周非手術治療","meta":"110年第2次第77題","year":110,"session":2,"number":77,"question":"下列何種病患不是使用超音波洗牙機設備（metal ultrasonic device）做結石刮除治療的禁忌？","options":["(A) 吞嚥困難患者（dysphagia）","(B) 慢性肺窘迫障礙患者（chronic pulmonary distress disorder）","(C) 新型心跳節律器患者（newer pacemaker）","(D) 鈦金屬植體者（titanium implant）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-2-78","subject":"ya3","topic":"植牙學","meta":"110年第2次第78題","year":110,"session":2,"number":78,"question":"關於粗糙面植體（rough implant surface）的敘述，下列何者錯誤？","options":["(A) 增加骨接觸表面積","(B) 受細菌感染的機率較高","(C) 較容易達到第一級穩定（primary stability）","(D) 可以提升第二級穩定（secondary stability）"],"answer":2,"clinical_level":"一般"},{"id":"ya3-110-2-79","subject":"ya3","topic":"植牙學","meta":"110年第2次第79題","year":110,"session":2,"number":79,"question":"取頦（chin）自體骨時，安全距離應與下顎前牙根尖約為多少mm？","options":["(A) 3","(B) 5","(C) 7","(D) 8"],"answer":1,"clinical_level":"重點"},{"id":"ya3-110-2-80","subject":"ya3","topic":"植牙學","meta":"110年第2次第80題","year":110,"session":2,"number":80,"question":"如果要進行拔牙後立即植牙，下列何者是不需考慮的？","options":["(A) 植體植入後要能維持初期穩定","(B) 拔除牙齒的牙周並無明顯的化膿性感染","(C) 植體置入不得超過根尖2 mm","(D) 拔牙窩內壁與植體表面縫隙的距離"],"answer":2,"clinical_level":"一般"},{"id":"ya3-111-1-1","subject":"ya3","topic":"牙髓診斷與病理","meta":"111年第1次第1題","year":111,"session":1,"number":1,"question":"關於牙齒的神經支配，下列敘述何者錯誤？","options":["(A) 主要的感覺神經是由三叉神經的V2及V3分支支配","(B) 下頷臼齒的感覺神經可能由頸椎神經C2及C3分支支配","(C) A-δ 軸突（axons）有髓鞘（myelinated sheath）包覆","(D) A-δ軸突（axons）的傳導速率比A-β軸突（axons）快"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-2","subject":"ya3","topic":"牙髓診斷與病理","meta":"111年第1次第2題","year":111,"session":1,"number":2,"question":"關於牙髓腔內血液循環的敘述，下列何者錯誤？","options":["(A) 牙冠牙髓腔內血管叢的密度是牙根牙髓腔內的2倍","(B) 牙髓組織中血液的重量（weight）占牙髓所有組織的3%","(C) 病患在急性牙髓炎有搏動性的牙痛感覺（throbbing pain），是因為牙髓腔內血管搏動產生的","(D) 在靜止狀態下牙髓腔內血流量很高，約0.15～0.60 mL/min/g"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-3","subject":"ya3","topic":"牙髓診斷與病理","meta":"111年第1次第3題","year":111,"session":1,"number":3,"question":"使用電髓活性測試（electric pulp test）檢測牙髓組織活性時，下列何者可能會造成假陽性反應（false-positive responses）？","options":["(A) 牙髓組織局部壞死（partial pulp necrosis）","(B) 根管有鈣化情形（canal with calcific obliteration）","(C) 牙根發育未成熟的牙齒（immature tooth）","(D) 最近剛發生撞傷的牙齒（recently traumatized tooth）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-4","subject":"ya3","topic":"牙髓診斷與病理","meta":"111年第1次第4題","year":111,"session":1,"number":4,"question":"59歲男性因左下第二大臼齒金屬贋復牙冠（metal crown）脫落而前來就診，臨床檢查發現患齒周圍牙齦外觀呈 現正常，牙周囊袋探測結果均在正常範圍，對冷刺激（cold test）與電髓活性檢查（electric pulp test）沒有反 應，並且患齒也沒有觸痛與敲痛的症狀，放射線學檢查結果如下圖所示。則左下第二大臼齒的診斷何者最為適 當？","options":["(A) 牙髓壞死（pulp necrosis）合併正常根尖組織（normal apical tissue）","(B) 牙髓壞死（pulp necrosis）合併無症狀根尖周圍炎（asymptomatic apical periodontitis）","(C) 牙髓壞死（pulp necrosis）合併症狀性根尖周圍炎（symptomatic apical periodontitis）","(D) 牙髓壞死（pulp necrosis）合併慢性根尖膿腫（chronic apical abscess）"],"answer":1,"image":"ya3-111-1-4.jpeg","clinical_level":"一般"},{"id":"ya3-111-1-5","subject":"ya3","topic":"牙科解剖與生理","meta":"111年第1次第5題","year":111,"session":1,"number":5,"question":"關於肌筋膜疼痛（myofascial pain）造成的牽引痛（referred pain）之敘述，下列何者錯誤？","options":["(A) 通常會有觸發區（trigger point）","(B) 通常呈現搏動疼痛（throbbing pain）","(C) 可給與NSAID藥物治療","(D) 咬肌（masseter muscle）的肌筋膜痛會轉移到上顎後牙區"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-6","subject":"ya3","topic":"牙科解剖與生理","meta":"111年第1次第6題","year":111,"session":1,"number":6,"question":"根據2007年美國心臟學會（AHA）與美國牙醫學會（ADA）建議的準則，關於根管治療時使用預防性抗生素 的敘述，下列何者錯誤？","options":["(A) 有人工心臟瓣膜（artificial heart valve）的病患須給與預防性抗生素","(B) 預防性抗生素應於術前10分鐘服用","(C) 成人通常建議給與2 g的安莫西林（amoxicillin）抗生素","(D) 對於安莫西林（amoxicillin）過敏的成人，可以改用600 mg的克林達黴素（clindamycin）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-7","subject":"ya3","topic":"牙齒外傷處理","meta":"111年第1次第7題","year":111,"session":1,"number":7,"question":"關於牙齒受到外傷後做牙髓敏感性測試（sensitivity test），下列敘述何者錯誤？","options":["(A) 根尖孔未閉合的恆牙以乾冰（CO2 ice）做牙髓敏感性測試比以電髓測試（EPT）的可信度高","(B) 根尖孔未閉合的恆牙使用二氯二氟甲烷（dichlorodifluoromethane）做牙髓敏感性測試比電髓測試（EPT）的 可信度低","(C) 可以使用血氧儀（pulse oximetry）評估牙髓的血流狀態","(D) 可以使用雷射都普勒血流儀（Laser Doppler flowmetry）評估牙髓的血流狀態"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-8","subject":"ya3","topic":"牙齒外傷處理","meta":"111年第1次第8題","year":111,"session":1,"number":8,"question":"有關牙齒外傷後，產生牙髓根管堵塞（pulp canal obliteration）的現象，下列敘述何者錯誤？","options":["(A) 牙冠可能呈現較黃的色澤","(B) 通常是因為牙髓受到外傷刺激而壞死所產生的現象","(C) 在開放型根尖（open apex）的外傷牙較常見","(D) 發生在側向脫位（lateral luxation）的牙齒比內縮脫位（intrusive luxation）的比例高"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-9","subject":"ya3","topic":"牙齒外傷處理","meta":"111年第1次第9題","year":111,"session":1,"number":9,"question":"脫落齒在清除完牙根及齒槽內的髒汙後，依標準程序，其口外乾燥時間在那一種情況下，牙根表面不需額外處 理即可植回？","options":["(A) 大於1小時且牙根已閉合","(B) 大於1小時且牙根未閉合","(C) 小於1小時且牙根已閉合","(D) 小於1小時且牙根未閉合"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-10","subject":"ya3","topic":"根管治療程序","meta":"111年第1次第10題","year":111,"session":1,"number":10,"question":"根管治療中以X光照射來測量工作長度時，為使頰舌側根管能分辨清楚，下列偏移方法何者錯誤？","options":["(A) 照射下顎小臼齒時將放射錐（cone）朝近心側偏移（mesial shift）","(B) 照射上顎大臼齒時將放射錐（cone）朝近心側偏移（mesial shift）","(C) 照射下顎大臼齒時將放射錐（cone）朝近心側偏移（mesial shift）","(D) 照射下顎門齒時將放射錐（cone）朝遠心側偏移（distal shift）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-11","subject":"ya3","topic":"根尖手術與再治療","meta":"111年第1次第11題","year":111,"session":1,"number":11,"question":"根管再治療時必須使用溶解劑如chloroform（氯仿）、halothane（溴氯三氟乙烷）、eucalyptol （尤加利油） 或甲基氯仿（methyl chloroform）溶解馬來膠，下列敘述何者錯誤？","options":["(A) 溶解馬來膠的效果：chloroform> halothane > eucalyptol","(B) 對於人體的毒性：halothane > eucalyptol","(C) 讓人感到不舒服的氣味：chloroform＞eucalyptol","(D) 甲基氯仿（methyl chloroform）比氯仿毒性低但溶解馬來膠效果一樣"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-12","subject":"ya3","topic":"根管器械","meta":"111年第1次第12題","year":111,"session":1,"number":12,"question":"ISO 30號的根管銼與下列那一支根管銼使用相同顏色的銼柄（file handle）？","options":["(A) 50號","(B) 55號","(C) 60號","(D) 70號"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-13","subject":"ya3","topic":"根管治療程序","meta":"111年第1次第13題","year":111,"session":1,"number":13,"question":"關於Ethylenediamine Tetra-Acetic Acid（EDTA）的敘述，下列何者正確？","options":["(A) 使用EDTA能有效的移除塗抹層的有機成分","(B) 可使用17% EDTA來移除塗抹層","(C) EDTA浸泡根管壁時間越久，越能有效移除塗抹層","(D) EDTA和次氯酸鈉（NaOCl）混合時會增強次氯酸鈉溶解組織的能力"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-14","subject":"ya3","topic":"根管器械","meta":"111年第1次第14題","year":111,"session":1,"number":14,"question":"根據International Standards Organization（ISO）、American National Standards Institute（ANSI）與American Dental Association（ADA）共同規範的35號手用器械（hand instrument），其器械尖端之直徑（tip diameter, mm）與錐度（taper, mm/mm）分別為下列何者？","options":["(A) 0.035；0.02","(B) 0.035；0.04","(C) 0.35；0.02","(D) 0.35；0.04"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-15","subject":"ya3","topic":"根管治療程序","meta":"111年第1次第15題","year":111,"session":1,"number":15,"question":"下列何者不是理想根管封填材料應該具備的特質？","options":["(A) 操作容易","(B) 體積穩定不易收縮","(C) 對於根尖周圍組織沒有刺激性","(D) 可緻密充填且不易被移除"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-16","subject":"ya3","topic":"根管器械","meta":"111年第1次第16題","year":111,"session":1,"number":16,"question":"關於鎳鈦旋轉器械的斷裂機轉，下列敘述何者錯誤？","options":["(A) 一般來說比不銹鋼器械的抗斷裂能力強","(B) 斷裂模式分成扭轉（torsional）斷裂及週期性（flexural）疲勞斷裂2種","(C) 錐度或尺寸越大的器械在彎曲的根管越能抵擋斷裂","(D) 器械重複使用越多次越容易造成週期性疲勞斷裂"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-17","subject":"ya3","topic":"根管治療程序","meta":"111年第1次第17題","year":111,"session":1,"number":17,"question":"下列關於髓腔開擴（access cavity preparation）的敘述，何者錯誤？","options":["(A) 可藉由放射線影像評估由咬合面至髓腔的深度","(B) 以咬合面（occlusal）及牙根外形（external root form）評估牙髓走向","(C) 咬合面的中心（the center of the occlusal table）就是牙髓腔的中心","(D) 髓腔開擴只移除絕對需要移除的齒質"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-18","subject":"ya3","topic":"根尖手術與再治療","meta":"111年第1次第18題","year":111,"session":1,"number":18,"question":"關於汞齊（amalgam）、IRM與MTA等根管逆充填材料的特性，下列敘述何者錯誤？","options":["(A) 材料調拌後的凝固時間（setting time）：汞齊大於MTA","(B) 調拌後24小時展現的抗壓強度（compressive strength）：IRM大於MTA","(C) 對人體的生物相容性（biocompatibility）：MTA優於IRM","(D) 顯現在根尖片的不透射性（radiopaque）：汞齊大於MTA"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-19","subject":"ya3","topic":"牙科解剖與生理","meta":"111年第1次第19題","year":111,"session":1,"number":19,"question":"理想的情況下，傷口的軟組織癒合成熟期（maturation phase）約在何時發生？纖維母細胞（fibroblast）的數 量會如何變化？","options":["(A) 術後5～7天；纖維母細胞減少","(B) 術後5～7天；纖維母細胞增加","(C) 術後10～14天；纖維母細胞減少","(D) 術後10～14天；纖維母細胞增加"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-20","subject":"ya3","topic":"根尖手術與再治療","meta":"111年第1次第20題","year":111,"session":1,"number":20,"question":"Enterococcus faecalis是根管治療失敗病例中，最常發現的致病菌種，因為其具有下列何項特殊的性質？","options":["(A) 因為其低鹼耐受性，Enterococcus faecalis可以抵抗大部分根管沖洗溶液的化學清潔作用","(B) 因為其質子對流系統（proton pump）可以自行調節內部至鹼性濃度","(C) Enterococcus faecalis可以生存在長期無氧與無養份的環境下，存活至適當時機再行繁殖","(D) Enterococcus faecalis可以在多菌種感染的環境下繁殖"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-21","subject":"ya3","topic":"牙髓診斷與病理","meta":"111年第1次第21題","year":111,"session":1,"number":21,"question":"關於牙根尖組織病變的敘述，下列敘述何者錯誤？","options":["(A) 大約有15～42%的牙根尖組織病變會轉變成囊腫（cyst）","(B) 真性囊腫（true cyst）往往伴隨著連續性的上皮細胞，並與牙齒產生隔離現象","(C) 囊袋囊腫（pocket cyst）則是其空腔往往向著受感染的牙齒根管是敞開的","(D) 囊袋囊腫（pocket cyst）往往無法單由非手術性根管治療來解決，常須藉由手術方式才能解決"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-22","subject":"ya3","topic":"根管治療程序","meta":"111年第1次第22題","year":111,"session":1,"number":22,"question":"下列何者不是影響人為根管穿孔修補預後（prognosis of perforation repair）的主要因素？","options":["(A) 穿孔修補是否能達到良好的封閉","(B) 穿孔的原因","(C) 穿孔的位置","(D) 發生穿孔至修補時間間隔的長短"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-23","subject":"ya3","topic":"牙周疾病與診斷","meta":"111年第1次第23題","year":111,"session":1,"number":23,"question":"下列何種牙齒牙周破壞的X光影像，與其他三者差異較大？","options":["(A) vertical root fracture","(B) palatal-gingival groove","(C) periapical osteosclerosis","(D) lateral periodontal cyst"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-24","subject":"ya3","topic":"牙髓診斷與病理","meta":"111年第1次第24題","year":111,"session":1,"number":24,"question":"在牙髓疾病的診斷上常須牙周探針來做探測，下列何者比較不會顯示窄而深的牙周囊袋？","options":["(A) 側位牙周囊腫（lateral periodontal cyst）","(B) 舌溝（lingual groove）","(C) 齒頸部牙釉質突（cervical enamel projection）","(D) 垂直牙根斷裂（vertical root fracture）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-25","subject":"ya3","topic":"根管治療程序","meta":"111年第1次第25題","year":111,"session":1,"number":25,"question":"進行活髓治療血管再形成術式（revascularization procedures）時，下列敘述何者錯誤？","options":["(A) 應選用不含腎上腺素（epinephrine）的麻藥","(B) 使用雙氯苯雙胍己烷（chlorhexidine）進行根管沖洗可加強殺菌效果","(C) 若使用次氯酸鈉（NaOCl）作為根管沖洗液時，建議的濃度為1.5%","(D) 在刺激根尖組織形成血栓前，應使用17%EDTA進行最終的根管沖洗"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-26","subject":"ya3","topic":"醫學倫理與法規","meta":"111年第1次第26題","year":111,"session":1,"number":26,"question":"施行牙科處置之前，由醫師提供醫療建議給病患，病患在被告知、了解後，同意治療，這種「知情同意」的 作法符合醫學倫理的那一項原則？","options":["(A) 行善原則","(B) 正義原則","(C) 尊重自主原則","(D) 不傷害原則"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-27","subject":"ya3","topic":"窩洞設計與分類","meta":"111年第1次第27題","year":111,"session":1,"number":27,"question":"下列何者不是臨床上區分牙本質與牙釉質的方法？","options":["(A) 顏色飽和度","(B) 齒質硬度","(C) 透光程度","(D) 以染劑染色"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-28","subject":"ya3","topic":"窩洞設計與分類","meta":"111年第1次第28題","year":111,"session":1,"number":28,"question":"關於牙釉質的特性，下列敘述何者錯誤？","options":["(A) 牙釉質比牙本質容易斷裂，是因為牙釉質的低彈性係數（elastic modulus）所導致","(B) 就牙釉質的厚度而言，臼齒較小臼齒厚","(C) 一般來說，不管乳牙或是恆牙，牙釉柱（enamel rod）皆垂直牙本質牙釉質交界（DEJ）以及牙齒表面，除 了恆牙齒頸部區域之外","(D) 與牙本質相比，牙釉質具有高抗壓強度（compressive strength）、低抗張強度（tensile strength）"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-29","subject":"ya3","topic":"複合樹脂與材料","meta":"111年第1次第29題","year":111,"session":1,"number":29,"question":"相較於樹脂冠蓋體（resin onlay），下列何者是陶瓷冠蓋體（ceramic onlay）最大的優點？","options":["(A) 陶瓷冠蓋體較硬，可提供較長期的咬合穩定性","(B) 試戴（try-in）陶瓷冠蓋體時無斷裂之虞","(C) 可將陶瓷冠蓋體之邊緣置放在牙本質","(D) 病患有異常咬合習慣（parafunctional habit）時，也可使用陶瓷冠蓋體"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-30","subject":"ya3","topic":"窩洞設計與分類","meta":"111年第1次第30題","year":111,"session":1,"number":30,"question":"關於冠蓋體（onlay）的咬頭修磨，下列敘述何者錯誤？","options":["(A) 會延伸到頰側或舌側溝","(B) 可重新調整咬合關係","(C) 可增加抗力（resistance）的效果","(D) 可增加固位（retention）的效果"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-31","subject":"ya3","topic":"窩洞設計與分類","meta":"111年第1次第31題","year":111,"session":1,"number":31,"question":"金屬鑄造體裙狀修形（skirting）較不適用於下列何者？","options":["(A) 上顎第二小臼齒遠心頰面","(B) 上顎第一小臼齒近心頰面","(C) 下顎第二小臼齒遠心頰面","(D) 下顎第一大臼齒近心頰面"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-32","subject":"ya3","topic":"黏著與美學修復","meta":"111年第1次第32題","year":111,"session":1,"number":32,"question":"關於上顎前牙的最佳比例（proportionality），下列敘述何者錯誤？","options":["(A) 從正面看時，上顎正中門牙：側門牙：犬齒寬度的黃金比例為 1.618：1.0：0.618","(B) 少數人天生具有此黃金比例","(C) 上顎正中門牙之寬／長比約為 0.75～0.8","(D) 理想的上顎正中門齒的寬／長比例小於上顎側門齒"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-33","subject":"ya3","topic":"黏著與美學修復","meta":"111年第1次第33題","year":111,"session":1,"number":33,"question":"進行複合樹脂比色時，使用下列何者最為理想？","options":["(A) 該樹脂廠商提供的比色板","(B) Vita Classical shade guide","(C) 尚未聚合的樹脂","(D) 剛聚合的樹脂"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-34","subject":"ya3","topic":"黏著與美學修復","meta":"111年第1次第34題","year":111,"session":1,"number":34,"question":"關於瓷鑲面（porcelain veneer）與牙釉質之鍵結，下列敘述何者錯誤？","options":["(A) 牙釉質以磷酸（phosphoric acid）處理可增加機械性鍵結","(B) 牙釉質表面不需以矽烷偶合劑（silane coupling agent）處理","(C) 矽烷偶合劑（silane coupling agent）使用目的是與瓷鑲面的磷酸鈣鍵結","(D) 瓷鑲面內面以氫氟酸（hydrofluoric acid）處理可增加機械性鍵結"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-35","subject":"ya3","topic":"牙周疾病與診斷","meta":"111年第1次第35題","year":111,"session":1,"number":35,"question":"關於牙齒上生物膜（biofilm）的敘述，下列何者錯誤？","options":["(A) 生理性的生物膜由 Streptococcus sanguis 和 S. mitis 組成","(B) 生物膜是由細菌及其副產物、胞外基質、水所構成","(C) 生物膜為微生物隨機附著所形成","(D) 在口腔內不同環境，生物膜群落有顯著差異"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-36","subject":"ya3","topic":"窩洞設計與分類","meta":"111年第1次第36題","year":111,"session":1,"number":36,"question":"對於低（low）與高（high）齲齒風險的成人，分別建議各需多久回診？","options":["(A) 低風險：9-12個月；高風險：3個月","(B) 低風險：9-12 個月；高風險：4-6 個月","(C) 低風險：4-6 個月；高風險：3 個月","(D) 均為 6 個月"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-37","subject":"ya3","topic":"窩洞設計與分類","meta":"111年第1次第37題","year":111,"session":1,"number":37,"question":"下列何者不適宜用於評估病患之齲齒風險（caries risk）？","options":["(A) 血糖測量","(B) The O' Leary index","(C) 飲食分析","(D) 唾液流速"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-38","subject":"ya3","topic":"複合樹脂與材料","meta":"111年第1次第38題","year":111,"session":1,"number":38,"question":"關於複合樹脂填補的敘述，下列何者錯誤？","options":["(A) 結構因子（C factor）會影響牙本質鍵結強度","(B) 牙釉質窩洞壁修磨的斜面（bevel）加寛，可增強窩洞邊緣封閉效果","(C) 複合樹脂的熱膨脹係數為牙齒的 1/4，造成口內溫度變化時會影響邊緣完整性","(D) 複合樹脂聚合後吸收水份，可減少窩洞邊緣微滲漏（microleakage）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-39","subject":"ya3","topic":"黏著與美學修復","meta":"111年第1次第39題","year":111,"session":1,"number":39,"question":"有一組牙本質黏著劑，其中甲劑成分是乙醇（ethanol）、2-hydroxyethyl methacrylate（HEMA），乙劑成分是 HEMA、bisphenol glycidyl methacrylate（Bis-GMA），下列敘述何者錯誤？","options":["(A) 這是一組自酸蝕（self-etch）黏著劑","(B) 須配合酸蝕劑使用","(C) 甲劑是處理劑（primer），乙劑是樹脂黏著劑（resin adhesive）","(D) 操作時先使用甲劑，再使用乙劑"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-40","subject":"ya3","topic":"牙體修形程序","meta":"111年第1次第40題","year":111,"session":1,"number":40,"question":"以4碼方式標示為 10-8.5-8-14 的牙科切削型的手動器械中，第一碼 10 代表的意義為下列何者？","options":["(A) 刃長（blade length）10 mm","(B) 刃寬（blade width）10 mm","(C) 刃長（blade length）1 mm","(D) 刃寬（blade width）1 mm"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-41","subject":"ya3","topic":"牙體修形程序","meta":"111年第1次第41題","year":111,"session":1,"number":41,"question":"下列何種握持器械法能提供牙體復形操作上最細緻的觸感？","options":["(A) Inverted Pen Grasp","(B) Modified Pen Grasp","(C) Palm and Thumb Grasp","(D) Modified Palm and Thumb Grasp"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-42","subject":"ya3","topic":"牙體修形程序","meta":"111年第1次第42題","year":111,"session":1,"number":42,"question":"如下圖所示，使用於上下或頰舌側方向整平窩洞壁之手持器械為何？","options":["(A) hoe","(B) dental file","(C) angle former","(D) enamel hatchet"],"answer":3,"image":"ya3-111-1-42.jpeg","clinical_level":"一般"},{"id":"ya3-111-1-43","subject":"ya3","topic":"窩洞設計與分類","meta":"111年第1次第43題","year":111,"session":1,"number":43,"question":"關於汞齊（amalgam）性質的敍述，下列何者錯誤？","options":["(A) 汞齊的熱膨脹線性係數（linear coefficient of thermal expansion）是牙齒的2.5倍","(B) 高銅汞齊的抗壓強度（compressive strength）與牙齒接近","(C) 高銅汞齊的抗張強度（tensile strength）比牙齒高","(D) 汞齊填補至少要有 1.5 至 2.0 mm 厚度"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-44","subject":"ya3","topic":"複合樹脂與材料","meta":"111年第1次第44題","year":111,"session":1,"number":44,"question":"下列何者不可能是複合樹脂（composite resin）的內含物？","options":["(A) bis-GMA（bisphenol A glycerolate dimethacrylate）","(B) silicon dioxide","(C) camphorquinone","(D) acetone"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-45","subject":"ya3","topic":"複合樹脂與材料","meta":"111年第1次第45題","year":111,"session":1,"number":45,"question":"複合樹脂填補時，關於逐層填補（incremental placement）的描述，下列何者錯誤？","options":["(A) 每層以不超過 2 mm 為原則","(B) 可減少聚合產生的應力（polymerization stress）","(C) 可減少牙齒變形（tooth deformation）","(D) 可增加牙齒剛性（stiffness）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-46","subject":"ya3","topic":"複合樹脂與材料","meta":"111年第1次第46題","year":111,"session":1,"number":46,"question":"前牙複合樹脂填補時，使用木楔（wooden wedge）的目的，下列何者錯誤？","options":["(A) 增加光反射以提高聚合","(B) 分開相鄰牙齒","(C) 保護鄰接面牙齦","(D) 建立適合接觸點"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-47","subject":"ya3","topic":"黏著與美學修復","meta":"111年第1次第47題","year":111,"session":1,"number":47,"question":"以直接複合樹脂貼面復形上顎門牙時，若牙齒齒頸部(下圖１處)有明顯變色情形，使用不透明色澤（opaque shade），齒頸部色澤（cervical shade），主體色澤（body shade）和半透明色澤（translucent shade）等複合樹 脂，應採用下列何者選擇以達美觀效果？","options":["(A) 2：齒頸部色澤，3：不透明色澤，4：主體色澤，5：半透明色澤","(B) 2：不透明色澤，3：齒頸部色澤，4：主體色澤，5：半透明色澤","(C) 2：主體色澤，3：齒頸部色澤，4：不透明色澤，5：半透明色澤","(D) 2：齒頸部色澤，3：主體色澤，4：不透明色澤，5：半透明色澤"],"answer":1,"image":"ya3-111-1-47.jpeg","clinical_level":"一般"},{"id":"ya3-111-1-48","subject":"ya3","topic":"複合樹脂與材料","meta":"111年第1次第48題","year":111,"session":1,"number":48,"question":"使用傳統光照樹脂填補後牙鄰接面時，齒齦壁（gingival wall）上第一層樹脂厚度建議為多少厚度？","options":["(A) 0.5～1 mm","(B) 1～2 mm","(C) 2～3 mm","(D) 3～4 mm"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-49","subject":"ya3","topic":"複合樹脂與材料","meta":"111年第1次第49題","year":111,"session":1,"number":49,"question":"關於第二類（Class II）窩洞製備以及複合樹脂填補的過程，下列敘述何者錯誤？","options":["(A) axial wall 要有 bevel 來增加鍵結面積","(B) 結構因子（Configuration factor, C-factor）和樹脂聚合收縮的應力有關","(C) 分層填補的厚度以不超過 2 mm 為佳","(D) 追加從頰側或舌側面光照，能使光固化效果更完全"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-50","subject":"ya3","topic":"窩洞設計與分類","meta":"111年第1次第50題","year":111,"session":1,"number":50,"question":"下列何者不是汞齊填補物之缺點？","options":["(A) 會顯著改變牙齦下細菌生物膜之組成","(B) 不美觀","(C) 可能因電位差而生 galvanic reaction","(D) 移除過程中可能產生汞蒸氣"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-51","subject":"ya3","topic":"牙體修形程序","meta":"111年第1次第51題","year":111,"session":1,"number":51,"question":"若以13-85-10-14的齦緣修整器（gingival margin trimmer）修整齦壁窩緣（gingival cavosurface），可得到多少 度的窩緣角？","options":["(A) 5 度","(B) 20 度","(C) 45 度","(D) 90 度"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-52","subject":"ya3","topic":"牙體修形程序","meta":"111年第1次第52題","year":111,"session":1,"number":52,"question":"在汞齊黏著系統中，最常使用的樹脂應為下列何者？","options":["(A) 光聚合無填料樹脂（light cured unfilled resin）","(B) 光聚合含填料樹脂（light cured filled resin）","(C) 自聚合含填料樹脂（self cured filled resin）","(D) 自聚合無填料樹脂（self cured unfilled resin）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-53","subject":"ya3","topic":"牙科解剖與生理","meta":"111年第1次第53題","year":111,"session":1,"number":53,"question":"關於牙齒主動萌出（active eruption）的敘述，下列何者錯誤？","options":["(A) 透過牙周韌帶收縮","(B) 透過牙齒位移","(C) 牙齒向咬合平面移動","(D) 牙齦向根尖方向位移"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-54","subject":"ya3","topic":"牙周疾病與診斷","meta":"111年第1次第54題","year":111,"session":1,"number":54,"question":"關於附連牙齦（attached gingiva）的敘述，下列何者錯誤？","options":["(A) 上顎前庭牙齦，最窄處在小臼齒區","(B) 上顎腭側均為附連牙齦","(C) 附連牙齦可以被碘溶液染成褐色","(D) 附連牙齦寬度，隨著年齡增加而增加"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-55","subject":"ya3","topic":"牙科解剖與生理","meta":"111年第1次第55題","year":111,"session":1,"number":55,"question":"關於牙骨質結構的敘述，下列何者錯誤？","options":["(A) 牙骨質的夏庇氏纖維（Sharpey's fibers），由造纖維細胞所形成，而基質的纖維則由造牙骨質母細胞所製造","(B) 牙骨質的有機基質，主要由90%第一型膠原纖維及5%第四型膠原纖維所組成","(C) 無細胞牙骨質大部分的夏庇氏纖維垂直牙根表面，而有細胞牙骨質的纖維通常平行牙根表面","(D) 無細胞牙骨質呈板狀排列，經由增生線加以分開"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-56","subject":"ya3","topic":"牙科解剖與生理","meta":"111年第1次第56題","year":111,"session":1,"number":56,"question":"下列何種細胞之抗原呈現（antigen presentation）功能不是經toll-like receptors（TLRs）來認知pathogen- associated molecular patterns（PAMPs）？","options":["(A) 蘭格罕氏細胞（Langerhans cells）","(B) 樹狀突細胞（dendritic cells）","(C) 多形核白血球（polymorphonuclear neutrophils /PMNs）","(D) 巨噬細胞（macrophages）"],"answer":[0,1,2,3],"image":"","clinical_level":"一般","explanation_pending":false},{"id":"ya3-111-1-57","subject":"ya3","topic":"牙科解剖與生理","meta":"111年第1次第57題","year":111,"session":1,"number":57,"question":"關於骨質疏鬆症（osteoporosis）的敘述，下列何者錯誤？","options":["(A) 以白種人與亞洲裔年老女性較常發生","(B) 患者的股骨（femur）及脊椎（spine）最常發生骨吸收","(C) 研究已確定患者同時也會罹患牙周炎","(D) 長期以bisphosphonate治療的患者，於進行牙周病手術時，要評估發生osteonecrosis of the jaw（ONJ）的機率"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-58","subject":"ya3","topic":"牙周疾病與診斷","meta":"111年第1次第58題","year":111,"session":1,"number":58,"question":"下列何者最不可能是牙周病的危險因子（risk factors）？","options":["(A) 抽菸（tobacco smoking）","(B) 齒面微生物堆積（microbial tooth deposits）","(C) 壓力（stress）","(D) 糖尿病（diabetes mellitus）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-59","subject":"ya3","topic":"牙周疾病與診斷","meta":"111年第1次第59題","year":111,"session":1,"number":59,"question":"關於牙周炎的發生，下列敘述何者錯誤？","options":["(A) 牙周炎病灶（advanced lesion）中含有大量的B cells及plasma cells","(B) T cells會活化及招募（recruitment）PMNs進入發炎位置","(C) Th-1 cells會促進macrophages吞噬致病菌","(D) Th-2 cells可抑制牙周炎的發生"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-60","subject":"ya3","topic":"牙周疾病與診斷","meta":"111年第1次第60題","year":111,"session":1,"number":60,"question":"根據Socransky等學者1998研究，在牙齦下牙菌斑中微生物的組合中，下列細菌何者屬於Red complex species？","options":["(A) P. intermedia、P. nigrescens 與 E. codens","(B) F. nucleatum、P. micros 與 C. gingivalis","(C) P. gingivalis 、T. forsythia 與 T. denticola","(D) C. gingivalis、C. rectus 與 P. intermedia"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-61","subject":"ya3","topic":"牙周疾病與診斷","meta":"111年第1次第61題","year":111,"session":1,"number":61,"question":"關於咬合創傷（trauma from occlusion）的敘述，下列何者錯誤？","options":["(A) 牙周韌帶變寬","(B) 牙齒動搖度增加","(C) 伴隨明顯的牙齒磨耗","(D) 伴隨牙齒病理性移位"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-62","subject":"ya3","topic":"牙周疾病與診斷","meta":"111年第1次第62題","year":111,"session":1,"number":62,"question":"關於胞膜受體與牙周細菌的敘述，下列何者錯誤？","options":["(A) 細胞膜上的類鐸受體-4（toll-like receptor- 4）可以識別革蘭氏陰性菌細胞壁的成分脂肪多醣 （lipopolysaccharides）","(B) 革蘭氏陽性菌細胞壁的成分壁脂酸（lipoteichoic acid）可經由類鐸受體-4刺激免疫反應","(C) Porphyromonas gingivalis菌的脂肪多醣同時可被類鐸受體-2和類鐸受體-4識別","(D) CD14/TLR-4/MD2複合體與脂肪多醣誘發細胞激素有關"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-63","subject":"ya3","topic":"牙周疾病與診斷","meta":"111年第1次第63題","year":111,"session":1,"number":63,"question":"一位30歲男性有嚴重的牙周炎與周邊血T-helper cells低於200/mm3，最可能患下列何種牙周病和系統性疾病？","options":["(A) 糖尿病相關之急性牙周炎","(B) 白血病相關之急性牙周炎","(C) 愛滋病相關之急性牙周炎","(D) 白血球黏著缺失相關之急性牙周炎"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-64","subject":"ya3","topic":"牙周非手術治療","meta":"111年第1次第64題","year":111,"session":1,"number":64,"question":"牙刷朝根尖方向，刷毛輕觸牙齦與牙齒，振動刷毛同時牙刷朝咬合面方向旋轉清潔，是下列何種刷牙方 法？","options":["(A) Stillman method","(B) Bass method","(C) Modified Charters technique","(D) Modified Stillman technique"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-65","subject":"ya3","topic":"牙周非手術治療","meta":"111年第1次第65題","year":111,"session":1,"number":65,"question":"漱口水成分中，下列何者不會造成牙齒染色？","options":["(A) stannous fluoride","(B) chlorhexidine","(C) essential oils","(D) povidone iodine"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-66","subject":"ya3","topic":"牙周手術與再生","meta":"111年第1次第66題","year":111,"session":1,"number":66,"question":"根據Cortellini和Tonetti的建議，當骨內缺損（intrabony defects）深度超過多少mm、角度小於多少度時，有最 佳的牙周再生效果？","options":["(A) 5；37","(B) 3；37","(C) 3；25","(D) 3；45"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-67","subject":"ya3","topic":"牙周手術與再生","meta":"111年第1次第67題","year":111,"session":1,"number":67,"question":"關於根叉管道修形術（tunnel preparation）的敘述，下列何者正確？","options":["(A) 適用於有三級或深度二級根叉侵犯（furcation involvement）的下顎大臼齒","(B) 接受治療的牙齒需有較大的牙根開展（root divergence）及較長的牙根幹（root trunk）","(C) 若有需要，需移除部分牙根尖區（inter-radicular）齒槽骨，但不可移除齒間（interdental）齒槽骨","(D) 齲齒率的高低並非執行此術式的考量因素"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-68","subject":"ya3","topic":"牙周手術與再生","meta":"111年第1次第68題","year":111,"session":1,"number":68,"question":"關於牙根覆蓋手術的選擇，下列敘述何者錯誤？","options":["(A) 冠向移位翻瓣術（coronal advanced flap），在單一的或多處的牙齦萎縮都可使用","(B) 表皮下結締組織移植術（subepithelial connective tissue graft）有較好的顏色相配","(C) 半月形的冠向移位翻瓣術（coronal advanced flap），建議使用在下顎牙齒","(D) 使用游離牙齦移植術比引導組織再生術，可以得到較多的附連牙齦"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-69","subject":"ya3","topic":"牙周手術與再生","meta":"111年第1次第69題","year":111,"session":1,"number":69,"question":"下列何者非黏膜牙齦手術（mucogingival surgery）之目的？","options":["(A) 增加牙齦組織寬度","(B) 更正特定組織缺陷","(C) 減低囊袋深度","(D) 促進齒槽骨生長"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-70","subject":"ya3","topic":"牙周疾病與診斷","meta":"111年第1次第70題","year":111,"session":1,"number":70,"question":"根據Miller 1985年牙齦萎縮分類的敘述，下列何者錯誤？","options":["(A) Class I：周圍組織退縮未超過 mucogingival junction，且沒有齒間軟硬組織的喪失。","(B) Class II：周圍組織退縮超過 mucogingival junction，且沒有齒間軟硬組織的喪失。","(C) Class III：周圍組織退縮超過 mucogingival junction，且有齒間軟硬組織的喪失。","(D) Class IV：周圍組織退縮超過 mucogingival junction，且沒有齒間軟硬組織的喪失。"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-71","subject":"ya3","topic":"牙周手術與再生","meta":"111年第1次第71題","year":111,"session":1,"number":71,"question":"Simplified papilla preservation flap於斜切（oblique incision）牙齦乳突的時候，應使刀片與牙齒長軸夾角約呈幾 度？","options":["(A) 0度","(B) 15度","(C) 30度","(D) 45度"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-72","subject":"ya3","topic":"牙周手術與再生","meta":"111年第1次第72題","year":111,"session":1,"number":72,"question":"下列那些材料製成的牙周再生膜須藉由二次手術移除？","options":["(A) polyglycolic acid","(B) polylatic acid","(C) e-PTFE","(D) collagen"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-73","subject":"ya3","topic":"牙周非手術治療","meta":"111年第1次第73題","year":111,"session":1,"number":73,"question":"關於維持期（maintenance phase），若病人在第一年回診結果，牙周狀況穩定，但口腔衛生不佳，有咬合或複 雜之補綴物問題，或正在進行矯正治療，應建議病人之後多久定期回診檢查？","options":["(A) 1～2個月","(B) 3～4個月","(C) 6個月","(D) 6～12個月"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-74","subject":"ya3","topic":"牙周疾病與診斷","meta":"111年第1次第74題","year":111,"session":1,"number":74,"question":"預估在維護期的病人之臨床附連喪失增加的最佳指標是下列何者？","options":["(A) 探診時流血（BoP）","(B) 探測囊袋深度增加（PPD）","(C) 高牙菌生物膜指數（plaque biofilm scores）","(D) 齒槽骨高度減少（alveolar bone height）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-75","subject":"ya3","topic":"牙周非手術治療","meta":"111年第1次第75題","year":111,"session":1,"number":75,"question":"在牙周病治療過程中，對於有心血管疾病病史的患者，以下何種處置最為正確？","options":["(A) 裝有心臟節律器或是植入式心律去顫器的患者，皆不可以使用超音波及電燒等儀器進行牙周治療","(B) 關於感染性心內膜炎預防性抗生素的口服藥物，如沒有抗藥性鏈球菌，首選是clindamycin 600 mg","(C) 對於感染性心內膜炎高風險患者，曾持續服用penicillin，如懷疑有抗藥性鏈球菌，下次牙周病治療前建議可 改用azithromycine為預防性抗生素","(D) 服用抗凝血劑腦血管意外（cerebrovascular accident）患者，牙科處置前一定先停藥"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-76","subject":"ya3","topic":"牙周手術與再生","meta":"111年第1次第76題","year":111,"session":1,"number":76,"question":"評估牙周手術時，下列何者不需要投予抗生素以預防感染性心內膜炎？","options":["(A) 人工心臟瓣膜（prosthetic cardiac valve）","(B) 感染性心內膜炎病史（previous infective endocarditis）","(C) 先天性心臟缺損（congenital heart defect）","(D) 二尖瓣脫垂無瓣膜回流（mitral valve prolapse without valvular regurgitation）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-77","subject":"ya3","topic":"牙周非手術治療","meta":"111年第1次第77題","year":111,"session":1,"number":77,"question":"關於有系統性疾病患者的牙周病治療時機之敘述，下列何者錯誤？","options":["(A) 服用抗凝血劑的牙周病患，需要執行手術或拔除多顆牙齒時，其INR（international normalized ratio）要控制 在1.5～2.0 之間","(B) 每天服用325 mg aspirin的患者，因為會影響止血，所以在牙周手術前需要停藥7～10天","(C) 有嚴重肝病的患者在進入牙周病療程前，須先以prothrombin time來檢驗凝血功能","(D) 正在接受化療的病患，其白血球計數至少需高於2,000/mm3才可進行牙周治療"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-1-78","subject":"ya3","topic":"牙科解剖與生理","meta":"111年第1次第78題","year":111,"session":1,"number":78,"question":"Bisphosphonates 的主要作用機轉為下列何者？","options":["(A) 增加osteoclast的activity","(B) 壓抑osteoclast的activity","(C) 增加osteoblast的activity","(D) 壓抑osteoblast的activity"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-79","subject":"ya3","topic":"植牙學","meta":"111年第1次第79題","year":111,"session":1,"number":79,"question":"關於植體探測深度的敘述，下列何者錯誤？","options":["(A) 植體周圍之探測深度較自然牙的變異較大","(B) 植體探測深度加深，臨床上不一定代表有較多的附連喪失","(C) 在發炎情況時，植體周圍的探測位置較自然牙更貼近於齒槽骨","(D) 探測深度在3 mm時，即視為植體周圍黏膜炎（peri-mucositis）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-111-1-80","subject":"ya3","topic":"植牙學","meta":"111年第1次第80題","year":111,"session":1,"number":80,"question":"關於植體周圍軟組織的敘述，下列何者錯誤？","options":["(A) 植體周圍軟組織附連圍繞植體形成生物封閉（biological seal）","(B) 植體周圍上皮附連結構與自然牙齒相同","(C) 上皮細胞不會與植體表面形成 hemidesmosomes 的結構","(D) 植體周圍結締組織之微血管叢較自然牙齒少"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-111-2-1","subject":"ya3","topic":"牙齒外傷處理","meta":"111年第2次第1題","year":111,"session":2,"number":1,"question":"因外傷脫槽超過1小時且牙根發育完成的恆牙，有關植回前的牙根表面處理，下列敘述何者錯誤？","options":["(A) 可將牙齒浸泡於酸液中5分鐘，以移除牙根表面的牙周韌帶及殘餘組織","(B) 接著可浸泡牙齒於2%氟化亞錫溶液（stannous fluoride）中5分鐘","(C) 各種對於牙根表面的處理，主要目的都是針對減少牙齒植回後的牙根吸收","(D) 研究顯示在牙根表面使用Emdogain可大幅減少牙根吸收的機會，建議常規使用"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-2","subject":"ya3","topic":"根管器械","meta":"111年第2次第2題","year":111,"session":2,"number":2,"question":"根據ISO所規範之手動根管器械，其D0變化比例最大者為：","options":["(A) 8號→10號","(B) 10號→15號","(C) 15號→20號","(D) 20號→25號"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-3","subject":"ya3","topic":"根尖手術與再治療","meta":"111年第2次第3題","year":111,"session":2,"number":3,"question":"手術性根管治療的骨質癒合過程，依序為何？ ①清除沒有活性碎屑（eradication of nonvital debris） ②形成骨 痂（callus formation） ③肉芽組織增生（proliferation of granulation tissue） ④海綿骨轉化成緻密骨 （conversion of woven bone to lamellar bone） ⑤骨質重新塑造（remodeling bone unit）","options":["(A) ①②③④⑤","(B) ①③②④⑤","(C) ③①②④⑤","(D) ①③②⑤④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-4","subject":"ya3","topic":"牙髓診斷與病理","meta":"111年第2次第4題","year":111,"session":2,"number":4,"question":"牙本質母細胞（odontoblast）是由下列何種細胞分化而來？","options":["(A) 未分化之軟骨（undifferentiated cartilage）","(B) 未分化之基底組織細胞 （undifferentiated basal cell）","(C) 未分化之外胚層間葉細胞（undifferentiated ectomesenchymal cell）","(D) 未分化之骨母細胞（undifferentiated osteoblast）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-5","subject":"ya3","topic":"牙髓診斷與病理","meta":"111年第2次第5題","year":111,"session":2,"number":5,"question":"關於牙髓內防禦細胞（defense cell）的敘述，下列何者錯誤？","options":["(A) 在正常牙髓內很少發現肥大細胞（mast cell）","(B) 在正常牙髓內可以發現淋巴細胞（lymphocyte）","(C) 在正常牙髓內的淋巴細胞，以B淋巴細胞（B lymphocyte）為主","(D) 巨噬細胞（macrophage）可以移除牙髓內死亡的細胞"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-6","subject":"ya3","topic":"牙髓診斷與病理","meta":"111年第2次第6題","year":111,"session":2,"number":6,"question":"有關牙髓內膠原蛋白（collagen）的敘述，下列何者正確？","options":["(A) 主要是由type I 及type II的膠原蛋白所組成","(B) 造牙本質細胞（odontoblasts）只有分泌type I膠原蛋白","(C) 隨著年齡增加，膠原蛋白的數量會減少","(D) 通常冠部牙髓的膠原蛋白數量會比根尖部牙髓多"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-7","subject":"ya3","topic":"牙髓診斷與病理","meta":"111年第2次第7題","year":111,"session":2,"number":7,"question":"關於牙髓活性檢測方法的敘述，下列何者正確？","options":["(A) 溫度測試（thermal test）不適合用在裝有贋復牙冠的牙齒","(B) 電髓活性測試（electric pulp test）的數值與牙髓活性程度有關","(C) 使用橡皮障（rubber dam）隔絕以水浴法進行熱溫測試（heat test）時，應從最後面的牙齒開始施測","(D) 進行窩洞測試（test cavity）時，須先對患齒進行施打麻藥以避免疼痛"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-8","subject":"ya3","topic":"牙髓診斷與病理","meta":"111年第2次第8題","year":111,"session":2,"number":8,"question":"病患口腔檢查左下第一大臼齒，其X光如圖所示。根據病歷記載5年前曾經因不可逆牙髓炎治療過左下第一大 臼齒。現檢查病患時，無咬痛、無觸摸疼痛、無牙齦腫大等臨床症狀、牙周囊袋檢查正常、補綴物邊緣有繼發 齲齒（secondary caries）。則對其左下第一大臼齒診斷與建議之治療計畫何者最適當？","options":["(A) 已根管治療牙齒（previously treated），症狀型根尖周圍炎（symptomatic apical periodontitis）；須根管再治 療（endodontic retreatment）","(B) 初步治療牙齒（previously initiated therapy），症狀型根尖周圍炎（symptomatic apical periodontitis）；須根 管再治療（endodontic retreatment）","(C) 已根管治療牙齒（previously treated），無症狀型根尖周圍炎（asymptomatic apical periodontitis）；可繼續觀 察3個月","(D) 已根管治療牙齒（previously treated），無症狀型根尖周圍炎（asymptomatic apical periodontitis）；須根管再 治療（endodontic retreatment）"],"answer":3,"image":"ya3-111-2-8.jpeg","clinical_level":"一般"},{"id":"ya3-111-2-9","subject":"ya3","topic":"牙髓診斷與病理","meta":"111年第2次第9題","year":111,"session":2,"number":9,"question":"關於急性根尖膿腫（acute apical abscess）的敘述，下列何者正確？","options":["(A) 在敲診及觸診時，會有劇烈的疼痛","(B) 只對電髓測試有反應","(C) 根尖X光片判讀上，無任何異常","(D) 牙齒鄰近口內及臉部組織，通常有膿流出狀況發生"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-111-2-10","subject":"ya3","topic":"牙齒外傷處理","meta":"111年第2次第10題","year":111,"session":2,"number":10,"question":"關於牙根水平斷裂（horizontal root fracture）的治療及預後，下列敘述何者錯誤？","options":["(A) 立即復位與固定，是最優先的處置","(B) 斷裂部分可能以鈣化組織或結締組織（connective tissue）的方式來癒合","(C) 冠部（coronal segment）牙齒結構漸漸透出黃色色澤，多因牙髓壞死引起","(D) 若出現牙髓壞死的狀況，通常先進行冠部（coronal segment）的根管治療"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-111-2-11","subject":"ya3","topic":"牙齒外傷處理","meta":"111年第2次第11題","year":111,"session":2,"number":11,"question":"下列那種外傷牙齒必須在外傷發生10天內進行根管治療？","options":["(A) 半脫位齒（subluxation）","(B) 突出脫位齒（extrusive luxation）","(C) 根尖未閉合之內縮脫位齒（intrusive luxation）","(D) 1小時內植回且根尖已閉合之脫落齒（avulsion）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-12","subject":"ya3","topic":"根管器械","meta":"111年第2次第12題","year":111,"session":2,"number":12,"question":"關於牙科常用音波（sonic）、超音波（ultrasonic）根管器械的描述，下列敘述何者錯誤？","options":["(A) 壓電式（piezoelectric）的超音波根管器械為線性震盪模式，非常適合用於根管內的精細修形","(B) 超音波根管器械震盪頻率大約落在25～30 kHz","(C) 音波器械的震盪頻率大約落在2～3 kHz","(D) 超音波根管器械應用於根管沖洗時，要儘量深入根管，同時要與管壁作適當接觸"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-111-2-13","subject":"ya3","topic":"根管治療程序","meta":"111年第2次第13題","year":111,"session":2,"number":13,"question":"左側上顎第一小臼齒與第二小臼齒因不可逆牙髓炎需根管治療，左圖為治療前以X光平行儀（cone indicator） 輔助正角度照射，右圖為治療後側角度照射。則右圖紅色箭頭所指之根管為何？其X光側角度方向為何？","options":["(A) 頰側根管；由遠心側向近心側照射（distal shift）","(B) 腭側根管；由遠心側向近心側照射（distal shift）","(C) 頰側根管；由近心側向遠心側照射（mesial shift）","(D) 腭側根管；由近心側向遠心側照射（mesial shift）"],"answer":3,"image":"ya3-111-2-13.jpeg","clinical_level":"一般"},{"id":"ya3-111-2-14","subject":"ya3","topic":"根管治療程序","meta":"111年第2次第14題","year":111,"session":2,"number":14,"question":"有關次氯酸鈉（NaOCl）溶液在根管治療時的作用，下列敘述何者錯誤？","options":["(A) 控制髓腔開擴時的出血","(B) 抗菌能力","(C) 具有溶解生物膜（biofilm）的能力","(D) 對NaOCl溶液過敏的患者可以改換chlorhexidine溶液當根管沖洗液"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-111-2-15","subject":"ya3","topic":"根管治療程序","meta":"111年第2次第15題","year":111,"session":2,"number":15,"question":"根管治療時，下列何種情形最有可能使用抗生素？","options":["(A) 持續腫脹","(B) 根管封填後","(C) 預防症狀突發（flare-up）","(D) 竇管（sinus tract）產生時"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-16","subject":"ya3","topic":"根管治療程序","meta":"111年第2次第16題","year":111,"session":2,"number":16,"question":"髓腔開擴與冠狀端修形是根管修形中起始最重要的一步，其相關描述，下列何者錯誤？","options":["(A) 不應為了增加視野而過度修形，而造成日後牙齒斷裂","(B) 臨床上最常用於髓腔開擴後的根管入口探測器械應為#10 H-file","(C) 不論採用step-back或是step-down技術，蓋氏鑽針（Gates-Glidden drill）常用於冠狀端開展","(D) 鎳鈦旋轉器械也常針對冠狀端開展設計專門器械來應付"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-17","subject":"ya3","topic":"根尖手術與再治療","meta":"111年第2次第17題","year":111,"session":2,"number":17,"question":"在牙根尖手術（apical surgery）中，會以3 mm 長度切除根尖的原因為何？","options":["(A) 壓力能均勻分布於根尖，使術後從牙根尖破裂的機會下降","(B) 暴露的牙本質小管數量能夠增加，使封填緻密度上升","(C) 使手術視野更加清楚，提升封填效率以縮短手術時間","(D) 切除範圍能包含大部分容易堆積細菌且難以清潔的根管"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-18","subject":"ya3","topic":"根尖手術與再治療","meta":"111年第2次第18題","year":111,"session":2,"number":18,"question":"關於牙根尖手術中局部止血（hemostasis）的方式，下列敘述何者錯誤？","options":["(A) 膠原蛋白類的材料是藉由引導血小板附著，產生聚集和釋放反應達到止血效果","(B) 骨蠟（bone wax）會刺激第十二凝血因子的產生而達到止血的效果","(C) 止血膠網（Surgicel）是再生氧化纖維編織而成，酸鹼值低，會延遲傷口癒合","(D) 止血膠棉（Gelfoam）是一種明膠棉，藉由活化內在凝血途徑達成止血效果"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-19","subject":"ya3","topic":"根尖手術與再治療","meta":"111年第2次第19題","year":111,"session":2,"number":19,"question":"關於牙根尖手術用藥的敘述，下列何者錯誤？","options":["(A) 病人在手術前30分鐘服用止痛劑（NSAID）可以減少手術後疼痛","(B) 須注意肝腎功能不佳的病人服用止痛藥所造成的傷害","(C) 手術前服用抗生素可以減少牙根尖手術術後感染與併發症的機會","(D) 手術前後使用chlorhexidine gluconate（0.12%）進行口腔內消毒，可以減少口腔內的細菌量"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-20","subject":"ya3","topic":"牙髓診斷與病理","meta":"111年第2次第20題","year":111,"session":2,"number":20,"question":"若將受感染的牙本質碎屑推出根尖孔時，常會造成根尖周圍組織感染，在感染區域中最常發現的是那二種 菌？","options":["(A) Actinomyces israelii及Propionibacterium propionicum","(B) Fusobacterium nucleatum及Fusobacterium periodonticum","(C) Streptococcus anginosus及Streptococcus mitisi","(D) Streptococcus sanguinis及Enterococcus faecalis"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-21","subject":"ya3","topic":"根管治療程序","meta":"111年第2次第21題","year":111,"session":2,"number":21,"question":"下列那一種狀況的牙齒，在根管治療後的存活率（survival rate）較高？","options":["(A) 術前有較深的牙周囊袋或竇管（sinus tract）","(B) 牙齒的近心及遠心側沒有鄰接牙","(C) 非大臼齒（nonmolar teeth）","(D) 治療的過程中有根管充填材被推出根尖外"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-22","subject":"ya3","topic":"窩洞設計與分類","meta":"111年第2次第22題","year":111,"session":2,"number":22,"question":"關於圍箍效應（ferrule effect）的敘述，下列何者錯誤？","options":["(A) ferrule必須在健康的齒質上，高度至少需要2～3 mm","(B) ferrule愈長愈能增加牙齒的斷裂抗力","(C) ferrule能增加抵抗根柱（post）產生的側向力","(D) ferrule的設計可以增加齒頸部的拉應力（tensile strength）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-23","subject":"ya3","topic":"牙髓診斷與病理","meta":"111年第2次第23題","year":111,"session":2,"number":23,"question":"有關primary endodontic lesion with secondary periodontal involvement，下列敘述何者正確？","options":["(A) 臨床上患齒具有壞死之牙髓且有牙垢聚積於牙根面上","(B) X光影像顯示患齒具有廣泛性的牙周病但無伴隨有根尖周圍缺損（destruction of periapical alveolar bone）","(C) 治療計畫為根管治療即可","(D) 牙周治療應始於根管治療後2個月"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-111-2-24","subject":"ya3","topic":"牙齒外傷處理","meta":"111年第2次第24題","year":111,"session":2,"number":24,"question":"8歲男童一小時前因外傷導致上顎右側正中門齒牙冠斷裂（crown fracture），臨床檢查發現患齒周圍牙齦有輕 微紅腫，且對冷刺激有反應且無持續疼痛情形（lingering pain），敲診時患齒有輕微不適，患齒的臨床影像紀 錄與放射線學檢查結果如下圖所示。則對於右上正中門齒最適合的治療術式為何？","options":["(A) 間接覆髓術 （indirect pulp capping）","(B) 部分冠髓切除術（partial pulpotomy）","(C) 部分牙髓摘除術（partial pulpectomy）","(D) 根尖成形術（apexification）"],"answer":1,"image":"ya3-111-2-24.jpeg","clinical_level":"一般"},{"id":"ya3-111-2-25","subject":"ya3","topic":"根管治療程序","meta":"111年第2次第25題","year":111,"session":2,"number":25,"question":"關於根尖成形術（apexification）的敘述，下列何者正確？","options":["(A) 根尖成形術為對牙髓發炎但根尖尚未發育完全的牙齒，在根尖處進行誘導以形成鈣化沉積","(B) 氫氧化鈣製劑在過去被廣泛使用，但長期使用將導致根管阻塞","(C) 做完根尖成形術後形成鈣化屏障，故不容易發生牙根斷裂（root fracture）","(D) 根尖成形術最常見發生失敗的原因為細菌感染，可能因為沒有正確地做根管的清創"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-26","subject":"ya3","topic":"醫學倫理與法規","meta":"111年第2次第26題","year":111,"session":2,"number":26,"question":"下列何者不是病患教育材料（patient educational materials，如：衛教單張等）的優點？","options":["(A) 可促進病患健康的行為","(B) 可提升醫療訴訟勝訴的機會","(C) 可增加病患滿意度","(D) 有助於照會程序進行順利"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-27","subject":"ya3","topic":"牙髓診斷與病理","meta":"111年第2次第27題","year":111,"session":2,"number":27,"question":"患者口內狀況如圖，推論造成患者下顎前牙牙髓腔變小的主因，最可能為下列何者？","options":["(A) 原發牙本質（primary dentin）堆積","(B) 繼發牙本質（secondary dentin）堆積","(C) 第三級牙本質（tertiary dentin）堆積","(D) 被覆牙本質（mantle dentin）堆積"],"answer":2,"image":"ya3-111-2-27.jpeg","clinical_level":"一般"},{"id":"ya3-111-2-28","subject":"ya3","topic":"牙科解剖與生理","meta":"111年第2次第28題","year":111,"session":2,"number":28,"question":"有關老化在牙齒及牙周組織的表現，下列何者錯誤？","options":["(A) 牙齒形狀改變","(B) 牙髓的生理及解剖上的改變","(C) 牙齒顏色變黃","(D) 牙骨質變薄"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-29","subject":"ya3","topic":"窩洞設計與分類","meta":"111年第2次第29題","year":111,"session":2,"number":29,"question":"關於牙齒各結構發生齲齒的主要致病菌，下列何者正確？① 牙本質：S. mutans 和 Lactobacillus ② 牙釉質： S. sanguis 和 S. mutans ③ 牙根：Actinomyces","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-30","subject":"ya3","topic":"窩洞設計與分類","meta":"111年第2次第30題","year":111,"session":2,"number":30,"question":"關於牙本質齲齒區域的敘述，下列何者錯誤？","options":["(A) 感染區（infected zone）有機與無機成分皆遭到破壞","(B) 受影響區（affected zone）無需完全移除","(C) 感染區（infected zone）仍有自我修復的可能","(D) 受影響區（affected zone）有完整的膠原交鏈（collagen cross-linking）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-111-2-31","subject":"ya3","topic":"窩洞設計與分類","meta":"111年第2次第31題","year":111,"session":2,"number":31,"question":"關於口內復形物檢查時的發現，下列何者最不需要重新置換填補？","options":["(A) 銀粉邊緣溝（amalgam marginal ditching）","(B) 復形物上有斷裂線（fracture line）","(C) 前牙樹脂復形物邊緣變色（marginal staining）","(D) 鄰接接觸面（interproximal contact）無法讓牙線通過"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-111-2-32","subject":"ya3","topic":"窩洞設計與分類","meta":"111年第2次第32題","year":111,"session":2,"number":32,"question":"下列何者不是造成牙齒腐蝕（erosion）的原因？","options":["(A) 過多之產酸細菌","(B) 長期食用過多酸性食物","(C) 暴食症（bulimia）","(D) 反覆胃酸逆流"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-111-2-33","subject":"ya3","topic":"窩洞設計與分類","meta":"111年第2次第33題","year":111,"session":2,"number":33,"question":"一位口腔內牙齒排列不整，且有多顆廣泛性齲齒的病患就診，經給予抗生素解決急性腫脹疼痛問題後，下列 何者並非在控制期所應執行之治療項目？","options":["(A) 去除齲齒與發炎","(B) 洗牙","(C) 執行預防齲齒策略","(D) 矯正治療"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-34","subject":"ya3","topic":"黏著與美學修復","meta":"111年第2次第34題","year":111,"session":2,"number":34,"question":"使用磷酸酸蝕牙釉質表面以產生黏著（adhesion）時，下列敘述何者錯誤？","options":["(A) 一般使用磷酸的濃度約為30%到40%間","(B) 酸蝕的時間不得少於15秒","(C) 所產生的黏著是機械（mechanical）黏著","(D) 所產生的撕裂黏著強度（shear bond strength）可達 20 GPa"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-35","subject":"ya3","topic":"根管器械","meta":"111年第2次第35題","year":111,"session":2,"number":35,"question":"幫病患裝置位於左側下顎大臼齒的橡皮障後，發現唾液一直湧入橡皮障中，最可能的原因為下列何者？","options":["(A) 橡皮障正反面置放顛倒","(B) 橡皮障在齒齦緣未反轉至牙齦溝","(C) 使用 W56 的 clamp retainer","(D) 未使用圍巾（napkin）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-36","subject":"ya3","topic":"牙體修形程序","meta":"111年第2次第36題","year":111,"session":2,"number":36,"question":"以 4 碼方式標示為 10-8.5-8-14 的牙科切削型的手動器械中，關於此一器械的敘述，下列何者正確？","options":["(A) 刃長（blade length）為 8mm","(B) 刃寬（blade width）為 14mm","(C) 刃角（blade angle）為 8.5 百分度（centigrade）","(D) 切緣角（cutting edge angle）10 百分度（centigrade）"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-111-2-37","subject":"ya3","topic":"窩洞設計與分類","meta":"111年第2次第37題","year":111,"session":2,"number":37,"question":"下列位置之窩洞，何者不屬於第一類型窩洞？","options":["(A) 下顎第一小臼齒咬合面（occlusal surface）","(B) 上顎側門齒腭側面（palatal surface）","(C) 上顎第一大臼齒咬頭尖端（cusp tip）","(D) 下顎第二大臼齒頰側溝（buccal groove）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-38","subject":"ya3","topic":"複合樹脂與材料","meta":"111年第2次第38題","year":111,"session":2,"number":38,"question":"低銅汞齊合金（low copper amalgam alloy）填補後，產生化學腐蝕（chemical corrosion），汞齊表面變成黑 色，這種顏色的改變，與下列何種化合物有關？","options":["(A) Ag - S","(B) Ag - Hg","(C) Ag - Sn","(D) Ag - Cu"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-39","subject":"ya3","topic":"複合樹脂與材料","meta":"111年第2次第39題","year":111,"session":2,"number":39,"question":"牙科光聚合式複合樹脂中，常使用 camphoroquinon 作為光起始劑（photoinitiator），其最主要的吸收波長為 多少？","options":["(A) 470 µm","(B) 470 nm","(C) 370 µm","(D) 370 nm"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-40","subject":"ya3","topic":"複合樹脂與材料","meta":"111年第2次第40題","year":111,"session":2,"number":40,"question":"關於牙科複合樹脂材料中，所添加填料（filler）的敘述，下列何者錯誤？① 成分多為氧化鋯、玻璃、或是二 氧化矽 ② 提高熱膨脹係數 ③ 填料顆粒越大，越具抗磨耗性（wear resistance） ④ 減少複合樹脂聚合收 縮","options":["(A) ①③","(B) ①④","(C) ②③","(D) ②④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-41","subject":"ya3","topic":"黏著與美學修復","meta":"111年第2次第41題","year":111,"session":2,"number":41,"question":"比色時，操作者注視下列那種顏色，無助於降低色覺疲勞？","options":["(A) 紅色","(B) 藍色","(C) 紫色","(D) 灰色"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-42","subject":"ya3","topic":"黏著與美學修復","meta":"111年第2次第42題","year":111,"session":2,"number":42,"question":"關於前牙空隙關閉（diastema closure）的敘述，下列何者錯誤？","options":["(A) 前牙空隙較寬時易呈現背景色（show-through effect）","(B) 主要靠的是牙釉質鍵結","(C) 當空隙超過 2.5 mm，使用矯正加上瓷牙貼面美觀較佳","(D) 上顎正中門牙理想修復的長寬比（length／width）為 1.5：1"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-111-2-43","subject":"ya3","topic":"複合樹脂與材料","meta":"111年第2次第43題","year":111,"session":2,"number":43,"question":"關於微粒型複合樹脂（microfill composites）與混雜型複合樹脂（hybrid composite）的敘述，下列何者錯誤？","options":["(A) 微粒型複合樹脂的填料含量比混雜型複合樹脂少","(B) 微粒型複合樹脂適合用在第五類（Class V）窩洞的填補","(C) 混雜型複合樹脂的彈性係數比微粒型複合樹脂高","(D) 填料的含量和聚合收縮產生的應力成正比"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-111-2-44","subject":"ya3","topic":"窩洞設計與分類","meta":"111年第2次第44題","year":111,"session":2,"number":44,"question":"關於金屬冠蓋體（onlay）復形之裙狀製備（skirt preparation）的敘述，何者錯誤？","options":["(A) 可用於增加固位性（retention）與抗力性（resistance）","(B) 增加包覆範圍可減少術後牙齒斷裂","(C) 須切削入牙本質","(D) 裙狀製備會增加金屬露出部分"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-111-2-45","subject":"ya3","topic":"複合樹脂與材料","meta":"111年第2次第45題","year":111,"session":2,"number":45,"question":"下列何種材料不適用於汞齊充填時之底墊（base）？","options":["(A) 氫氧化鈣","(B) 聚羥酸鹽（polycarboxylate）","(C) 樹脂強化玻璃離子體","(D) 氧化鋅丁香油酚（zinc oxide-eugenol）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-46","subject":"ya3","topic":"根尖手術與再治療","meta":"111年第2次第46題","year":111,"session":2,"number":46,"question":"在打固位釘的過程中，穿出了牙齒外層，且穿出處在上皮附連（epithelial attachment）底下，下列何種處理方 式最適當？","options":["(A) 將 pin 超出牙齒處切斷，剩餘部份留置牙齒內即可","(B) 取出 pin，並將 pin 的通道處以 MTA 填補","(C) 取出 pin，並將 pin 的通道以樹脂填補","(D) 將 pin 超出牙齒處切斷，平行原通道再置入第二根 pin"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-47","subject":"ya3","topic":"窩洞設計與分類","meta":"111年第2次第47題","year":111,"session":2,"number":47,"question":"較大之第五類型（Class V）汞齊填補，下列何者可增加窩洞固位性（retention）？","options":["(A) 製備四個小凹（retention coves）","(B) 打固位釘（retention pin）","(C) 製作鴿尾形（dovetail）","(D) 斜面（bevel）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-48","subject":"ya3","topic":"黏著與美學修復","meta":"111年第2次第48題","year":111,"session":2,"number":48,"question":"下列何者非使用樹脂黏合劑（resin luting cement）黏著陶瓷嵌體（ceramic inlays/onlays）的主要考慮因素？","options":["(A) 與牙本質、牙釉質及嵌體皆有黏著力","(B) 溶解度較低","(C) 相較其它黏劑，etch-and-rinse type 樹脂黏合劑操作步驟最迅速簡單","(D) 增加復形物強度"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-49","subject":"ya3","topic":"牙體修形程序","meta":"111年第2次第49題","year":111,"session":2,"number":49,"question":"當嵌體窩洞修形後較深的地方，決定要以氫氧化鈣糊劑做覆髓，其周邊至少需露出多少牙本質，以供玻璃離 子黏合劑做為基底的操作？","options":["(A) 0.2～0.4 mm","(B) 0.5～1.0 mm","(C) 1.1～1.5 mm","(D) 1.6～2.0 mm"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-50","subject":"ya3","topic":"根管治療程序","meta":"111年第2次第50題","year":111,"session":2,"number":50,"question":"關於失活齒齒內漂白（non-vital internal bleaching）的敘述，下列何者錯誤？","options":["(A) 可使用過硼酸鈉（sodium perborate）混合蒸餾水做漂白","(B) 有外傷病史的病人會有較高機會產生牙根外吸收","(C) 不可使用10％碳醯胺過氧化物（carbamide peroxide）","(D) 一般來說漂白效果非長久性"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-51","subject":"ya3","topic":"黏著與美學修復","meta":"111年第2次第51題","year":111,"session":2,"number":51,"question":"瓷鑲面（porcelain veneer）與牙齒的黏著，下列黏合劑何者最適宜？","options":["(A) 多羧酸鹽黏合劑（polycarboxylate cement）","(B) 氧化鋅－丁香油酚黏合劑（zinc oxide-eugenol cement）","(C) 第二類玻璃離子體黏合劑（glass ionomer cement）","(D) 雙重聚合樹脂貼黏合劑（dual cured resin luting cement）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-111-2-52","subject":"ya3","topic":"牙科解剖與生理","meta":"111年第2次第52題","year":111,"session":2,"number":52,"question":"下列何項敘述，不是老年人的牙齒特徵？","options":["(A) 牙釉質磨損","(B) 牙齒看起來比較黃","(C) 前牙切端具有透明感","(D) 牙髓腔較小"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-53","subject":"ya3","topic":"牙科解剖與生理","meta":"111年第2次第53題","year":111,"session":2,"number":53,"question":"關於牙周組織神經傳導的敘述，下列何者錯誤？","options":["(A) 牙周組織含有機械性刺激接受器（mechanoreceptor）","(B) 牙齦不含本體感受器（proprioceptors）","(C) 記錄痛覺、觸覺、壓力的神經，其滋養（trophic）中心在中腦核（mesencephalic nucleus）","(D) 本體感受神經（proprioceptive nerves）經三叉神經傳到牙周組織"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-111-2-54","subject":"ya3","topic":"牙周疾病與診斷","meta":"111年第2次第54題","year":111,"session":2,"number":54,"question":"12歲女童，牙齦有瀰漫性糜爛出血並有水泡，病患有發高燒且疼痛不願意進食，其最可能之診斷為下列何 者？","options":["(A) herpetic gingivostomatitis","(B) necrotizing ulcerative gingivitis","(C) streptococcal gingivitis","(D) puberty associated gingivitis"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-55","subject":"ya3","topic":"牙周疾病與診斷","meta":"111年第2次第55題","year":111,"session":2,"number":55,"question":"下列何者屬於不可逆性之臨床流行病學指數？","options":["(A) Periodontal Disease Index of Ramfjord","(B) Periodontal Index of Russell","(C) Papillary Bleeding Index","(D) PMA Index"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-56","subject":"ya3","topic":"牙髓診斷與病理","meta":"111年第2次第56題","year":111,"session":2,"number":56,"question":"鑑別病變來自於牙周或牙髓組織時，下列何者最為重要？","options":["(A) X光檢查","(B) 牙髓活性測試","(C) 牙周囊袋深度測量","(D) 患者陳述對痛的感受"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-57","subject":"ya3","topic":"牙周疾病與診斷","meta":"111年第2次第57題","year":111,"session":2,"number":57,"question":"下列何種細菌分泌的白血球毒素（leukotoxin）在牙周疾病致病機轉上扮演重要的角色？","options":["(A) T. forsythia","(B) P. gingivalis","(C) T. denticola","(D) A. actinomycetemcomitans"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-111-2-58","subject":"ya3","topic":"牙科解剖與生理","meta":"111年第2次第58題","year":111,"session":2,"number":58,"question":"下列何者不屬於T helper-1（Th-1）細胞反應有關的細胞激素（cytokine）？","options":["(A) interleukin-2","(B) interferon-γ","(C) tumor necrosis factor-α","(D) interleukin-10"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-59","subject":"ya3","topic":"牙科解剖與生理","meta":"111年第2次第59題","year":111,"session":2,"number":59,"question":"在牙周組織中主要產生前列腺素（prostaglandins）之細胞為下列何者？","options":["(A) 造纖維細胞、多形核嗜中性白血球","(B) 造纖維細胞、巨噬細胞","(C) 造纖維細胞、破骨細胞","(D) 多形核嗜中性白血球、巨噬細胞"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-60","subject":"ya3","topic":"牙周非手術治療","meta":"111年第2次第60題","year":111,"session":2,"number":60,"question":"關於CO2及Nd-YAG雷射在牙周病治療的使用，下列敘述何者錯誤？","options":["(A) 有極佳的止血效果","(B) 對軟組織有極佳的切除作用（ablation）","(C) 對硬組織的治療效果良好且無副作用","(D) 對牙釉質表面會有融化（melting）的可能，所以不可直接以雷射處理"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-111-2-61","subject":"ya3","topic":"牙周手術與再生","meta":"111年第2次第61題","year":111,"session":2,"number":61,"question":"下列何者是有最可預期性的牙周囊袋降低手術（pocket reduction technique）？","options":["(A) 骨切除術（resective osseous surgery）","(B) 牙周瓣膜翻開合併骨移植術","(C) 引導組織再生術（guided tissue regeneration technique）","(D) 牙釉基質蛋白再生技術（enamel matrix protein regenerative technique）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-62","subject":"ya3","topic":"牙周手術與再生","meta":"111年第2次第62題","year":111,"session":2,"number":62,"question":"關於游離牙齦移植手術（free gingival graft）的敘述，下列何者錯誤？","options":["(A) 受植位（recipient site）切線大小，大約為附連牙齦（attached gingiva）期望寬度的兩倍","(B) 牙齦移植片置於骨組織上，較少產生術後腫脹","(C) 牙齦移植片置於骨組織上，6個月後收縮量約50%","(D) 理想的牙齦移植片厚度為1.0～1.5 mm"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-111-2-63","subject":"ya3","topic":"植牙學","meta":"111年第2次第63題","year":111,"session":2,"number":63,"question":"關於移植材料的敘述，下列何者正確？","options":["(A) 磷酸三鈣（tricalcium phosphate），其鈣磷比為1.67，具部分吸收及被軟組織所包圍之特性","(B) Bio-Oss®為具骨誘導能力之有孔洞的異類移植骨（xenograft）","(C) 石膏（plaster of Paris）具生物相容性，1～2週完全吸收","(D) 氫氧磷灰石（hydroxyapatite），會引起發炎性反應"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-64","subject":"ya3","topic":"牙周手術與再生","meta":"111年第2次第64題","year":111,"session":2,"number":64,"question":"下列何種手術，最可預期加深口腔前庭的效果？","options":["(A) 引導組織再生術（guided tissue regeneration）","(B) 根向移位翻瓣術（apically displaced flap）","(C) 側移位翻瓣術（laterally positioned flap）","(D) 游離牙齦移植術（free gingival graft）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-65","subject":"ya3","topic":"牙周疾病與診斷","meta":"111年第2次第65題","year":111,"session":2,"number":65,"question":"牙周病治療可改善糖尿病患者血糖控制之原因為下列何者？","options":["(A) 減少糖尿病致病菌","(B) 提高脂質合成作用","(C) 增加不可逆高度醣化終產物","(D) 改善胰島素阻抗作用"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-66","subject":"ya3","topic":"牙周疾病與診斷","meta":"111年第2次第66題","year":111,"session":2,"number":66,"question":"懷孕的牙周病患，口內革蘭氏陰性細菌產生的內毒素，會導致下列何種發炎物質的增加，而影響胎兒的生長 發育？","options":["(A) IL-6, IL-8","(B) MMP-1, MMP-8","(C) PGE2, TNF-α","(D) IL-6, MMP-2"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-67","subject":"ya3","topic":"植牙學","meta":"111年第2次第67題","year":111,"session":2,"number":67,"question":"一般而言，執行鼻竇增高術且要同時置入植體時，術前齒槽骨之高度至少須有多少mm？","options":["(A) 1","(B) 3","(C) 5","(D) 7"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-68","subject":"ya3","topic":"植牙學","meta":"111年第2次第68題","year":111,"session":2,"number":68,"question":"前牙單顆植體，為考量美觀因素，植入體肩台（shoulder）之位置為何？","options":["(A) 與鄰牙頰側骨嵴同高","(B) 位於鄰牙頰側骨嵴以下1～2 mm","(C) 與鄰牙頰側CEJ同高","(D) 位於鄰牙頰側CEJ以下1～2 mm"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-69","subject":"ya3","topic":"植牙學","meta":"111年第2次第69題","year":111,"session":2,"number":69,"question":"關於上顎竇（maxillary sinus）外側壁之動脈血管供應，下列敘述何者正確？","options":["(A) 上顎竇外側壁十分薄，沒有動脈血管供應","(B) 由外頸動脈之分支上顎動脈（maxillary artery）供應","(C) 由內頸動脈之分支上顎動脈（maxillary artery）供應","(D) 由內頸動脈之下顎動脈第一分支向上彎曲的血管叢供應"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-70","subject":"ya3","topic":"牙科解剖與生理","meta":"111年第2次第70題","year":111,"session":2,"number":70,"question":"牙齦基底細胞（basal cells）的細胞膜與下列何者相鄰（adjacent）？","options":["(A) lamina densa","(B) lamina lucida","(C) tonofilaments","(D) anchoring fibrils"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-71","subject":"ya3","topic":"牙周疾病與診斷","meta":"111年第2次第71題","year":111,"session":2,"number":71,"question":"關於牙齦炎的敘述，下列何者錯誤？","options":["(A) 牙齦炎的predisposing factors中不包括口呼吸","(B) Löe（1965）實驗性牙齦炎研究證明牙菌斑是發生牙齦炎的主因","(C) 約在懷孕的第二期和第三期，會增加牙齦炎的盛行率及嚴重度","(D) 懷孕性牙齦炎惡化與牙菌斑的增加無關但與progesterone的增加有關"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-111-2-72","subject":"ya3","topic":"牙周疾病與診斷","meta":"111年第2次第72題","year":111,"session":2,"number":72,"question":"一位25歲男性患者因牙齦嚴重潰瘍和疼痛來就診，臨床表徵為牙齦邊緣覆蓋一層黃白色薄膜、牙間乳突凹 陷、部份附連及齒槽骨喪失且無其他系統性疾病和發燒。下列何者是最可能的診斷？","options":["(A) necrotizing stomatitis","(B) necrotizing ulcerative periodontitis","(C) primary herpetic gingivostomatitis","(D) necrotizing ulcerative gingivitis"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-73","subject":"ya3","topic":"牙周疾病與診斷","meta":"111年第2次第73題","year":111,"session":2,"number":73,"question":"從牙齦病轉為牙周炎時，組織內占60%的免疫細胞是下列何者？","options":["(A) 多形核中性白血球","(B) B 細胞 + 漿細胞","(C) 輔助T細胞","(D) 巨噬細胞"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-74","subject":"ya3","topic":"牙周疾病與診斷","meta":"111年第2次第74題","year":111,"session":2,"number":74,"question":"關於Porphyromonas gingivalis之特殊致病特性的敘述，下列何者錯誤？","options":["(A) 其fimbriae媒介adhesion，其capsule可防被 phagocytosis","(B) 產生一系列的毒性因子，包括proteinases及collagenase","(C) 會促進趨化性（chemotaxis）","(D) 此菌有能力侵入軟組織（invade soft tissue）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-75","subject":"ya3","topic":"牙周非手術治療","meta":"111年第2次第75題","year":111,"session":2,"number":75,"question":"關於牙齦上與牙齦下的細菌性牙菌斑生物膜及牙結石清除的步驟，下列敘述何者正確？","options":["(A) 研究顯示慢性牙周炎，以牙周刮刀（curettes）器械治療時，會比使用其他器械有更佳的療效","(B) 除了需要將牙結石及牙菌斑生物膜清除外，還要將牙骨質完全整平去除","(C) 細菌的lipopolysaccharide黏附力強，不容易從牙骨質上清除","(D) 這個清除牙菌斑生物膜及牙結石的步驟，現通稱為牙根清創（root debridement）以取代根面整平術（root planing）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-76","subject":"ya3","topic":"植牙學","meta":"111年第2次第76題","year":111,"session":2,"number":76,"question":"下列何者不是以超音波骨刀（piezosurgery）施行手術的優點？","options":["(A) 減少組織損傷，避免取骨時影響活性，有效保存類成骨細胞（osteoblast-like）的數目","(B) 相較於傳統鑽針處理的植牙位置，能減少術後（7～14天）手術位置周圍的促炎性細胞激素之生成","(C) 穩定且可調整強度的沖洗系統，所產生的空穴現象（cavitation）能避免翻瓣時的軟組織損傷","(D) 進行骨整形手術（osteoplasty）時，在傷口復原期間能減少額外的骨質流失"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-77","subject":"ya3","topic":"牙周疾病與診斷","meta":"111年第2次第77題","year":111,"session":2,"number":77,"question":"病人在牙周病治療完成後，牙齦探測流血（BoP）為15%，有4個≧5 mm殘存牙周囊袋，2顆牙缺失，齒槽骨與 年紀的關係（BL%/age）是0.25，沒有系統性疾病及抽菸的習慣，若依Lang&Tonetti提出的功能性圖 （functional diagram），此病人是屬於何種類別？","options":["(A) low- risk","(B) medium- risk","(C) severe- risk","(D) high- risk"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-111-2-78","subject":"ya3","topic":"牙科解剖與生理","meta":"111年第2次第78題","year":111,"session":2,"number":78,"question":"關於牙科治療的感染性心內膜炎（infective endocarditis, IE）預防的敘述，下列何者正確？","options":["(A) 根據2008年美國心臟學會建議：所有先天性心臟病患者都是IE高危險群，需要術前抗生素預防","(B) 患者曾有過心內膜炎的病史，目前健康，執行口腔手術前不需要事先抗生素防治IE","(C) 侵襲性牙周炎（或是early-onset periodontitis）的年輕牙周病患的牙齦下致病菌A. actinomycetemcomitans 與IE 有關","(D) IE高風險病患需要良好的口腔衛生教育，建議使用oral irrigators加強清潔效果"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-111-2-79","subject":"ya3","topic":"牙周疾病與診斷","meta":"111年第2次第79題","year":111,"session":2,"number":79,"question":"懷孕婦女因荷爾蒙的影響可能會有較嚴重的牙齦發炎，與下列何種細菌最有關？","options":["(A) Fusobacterium nucleatum","(B) Prevotella intermedia","(C) Porphyromonas gingivalis","(D) Treponema denticola"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-111-2-80","subject":"ya3","topic":"植牙學","meta":"111年第2次第80題","year":111,"session":2,"number":80,"question":"植體周圍發炎過程可能會導致植體周圍支持骨的喪失，下列敘述何者最為正確？","options":["(A) 根據2010年Koldsland等的研究指出，植體周圍炎（peri-implantitis）發生率約為於1%到5%","(B) 臨床醫師需定期評估組織型態、探測深度變化及放射線影像以了解植體周圍骨頭狀態","(C) 根據Sixth European Workshop on Periodontology報告指出，酗酒及植體表面處理是植體周圍炎的主要風險指 標","(D) 目前證據顯示，糖尿病及抽菸不會影響植體周圍炎的發生率"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-1","subject":"ya3","topic":"牙科解剖與生理","meta":"112年第1次第1題","year":112,"session":1,"number":1,"question":"關於牙本質（dentin）的敘述，下列何者正確？","options":["(A) 最初生成的礦化牙本質稱作牙本前質（predentin）","(B) 修復性牙本質（reparative dentin）是由新分化的造牙本質細胞（odontoblast）所形成","(C) 替代性牙本質（replacing dentin）的生成較對稱（symmetric）","(D) 反應性第三級牙本質（reactionary tertiary dentin）是無管狀（atubular）的牙本質"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-2","subject":"ya3","topic":"牙科解剖與生理","meta":"112年第1次第2題","year":112,"session":1,"number":2,"question":"有關牙齒形態之敘述，下列何者正確？","options":["(A) 齒中齒（dens invaginatus）常發生於下顎小臼齒","(B) C型根管之下顎第二大臼齒牙根頰側常有一溝槽","(C) 齒外齒（dens evaginatus）常發生於上顎側門牙","(D) 腭齦溝（palato-gingival groove）常發生於上顎側門牙，往往導致牙周的問題"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-3","subject":"ya3","topic":"根管治療程序","meta":"112年第1次第3題","year":112,"session":1,"number":3,"question":"關於下顎第一大臼齒牙根與根管解剖形態的敘述，下列何者錯誤？","options":["(A) 通常近心牙根只有1個，有時卻出現3個根管","(B) 近心牙根有時出現近心中間（middle mesial）根管，較不易清創與封填","(C) 牙根分叉處有許多副根管（accessory canal），都需要進行清創","(D) 遠心牙根較少出現3個根管"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-4","subject":"ya3","topic":"牙髓診斷與病理","meta":"112年第1次第4題","year":112,"session":1,"number":4,"question":"有關牙根內吸收（internal root resorption）的敘述，何者正確？","options":["(A) 初期對冰刺激有反應","(B) X光片顯示根管有不規則之吸收透射影像","(C) 大部分病例牙髓活性測試為陽性反應，但通常不會有症狀，可不須進行根管治療，僅需觀察","(D) 組織切片可見多核之巨細胞（multinucleated giant cells）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-5","subject":"ya3","topic":"牙髓診斷與病理","meta":"112年第1次第5題","year":112,"session":1,"number":5,"question":"當病患覺得牙齒隨著心跳在搏動或是牙齒在抽痛（throbbing pain），是何種神經被激發？","options":["(A) A-δ fiber","(B) A-β fiber","(C) A-γ fiber","(D) C fiber"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-6","subject":"ya3","topic":"牙髓診斷與病理","meta":"112年第1次第6題","year":112,"session":1,"number":6,"question":"根據Nobuhara等人的研究，無症狀根尖周圍炎（asymptomatic apical periodontitis）依出現機率由大至小排序： ①肉芽組織（granulation tissue） ②囊腫（cyst） ③疤痕組織（scar tissue）","options":["(A) ①②③","(B) ②①③","(C) ①③②","(D) ②③①"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-7","subject":"ya3","topic":"牙齒外傷處理","meta":"112年第1次第7題","year":112,"session":1,"number":7,"question":"複雜性牙冠斷裂（complicated crown farcture）病例，一般經過多少小時後，其保留健康牙髓的機會將大大降 低？","options":["(A) 12","(B) 24","(C) 36","(D) 48"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-8","subject":"ya3","topic":"牙齒外傷處理","meta":"112年第1次第8題","year":112,"session":1,"number":8,"question":"關於牙齒外傷的診斷與治療，下列敘述何者正確？","options":["(A) 牙根尖已閉合之橫向牙根斷裂（horizontal root fracture）有可能不需根管治療","(B) 對於根尖閉合（closed apex）的脫落（avulsion）牙，並且在口外乾燥情況小於60分鐘內，建議根管治療後 植回固定","(C) 對於開放型牙尖（open apex）的脫落（avulsion）牙，並且在口外乾燥情況大於60分鐘，建議活髓治療 （vital pulp therapy）後植回固定（flexible splint）","(D) 半脫位（subluxation）和側向脫位（lateral luxation）最大的不同是有沒有搖動度（mobility）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-9","subject":"ya3","topic":"牙齒外傷處理","meta":"112年第1次第9題","year":112,"session":1,"number":9,"question":"下列有關橫向牙根斷裂（horizontal root fracture）牙齒外傷的敘述，何者錯誤？","options":["(A) 緊急處理為儘早復位並至少固定3個月","(B) 後續處理不一定需要做根管治療","(C) 牙根斷裂線在X光影像上呈現變寬且伴隨斷裂線邊緣放射線透過性病灶時，就需做根管治療","(D) 大部分病例，若發生齒髓壞死時，常侷限於牙根冠部（coronal portion of root）"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-10","subject":"ya3","topic":"根管治療程序","meta":"112年第1次第10題","year":112,"session":1,"number":10,"question":"有關SLOB（Same Lingual ,Opposite Buccal）法則，無法分辨出下列那一種情況？","options":["(A) 分辨頰舌側根管","(B) 決定根尖孔位置","(C) 分辨根尖彎曲方向","(D) 分辨未封填根管"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-11","subject":"ya3","topic":"窩洞設計與分類","meta":"112年第1次第11題","year":112,"session":1,"number":11,"question":"關於根柱（post）敘述，下列何者錯誤？","options":["(A) 根柱可能是預製式也有可能是客製化","(B) 依照材質來分有可能是金屬類根柱或玻璃纖維根柱","(C) 依照根柱外形來分有可能是螺絲型或平行型根柱","(D) 由於根柱可以強化牙齒牙根強度，所以移除根柱會造成牙齒牙根強度降低"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-12","subject":"ya3","topic":"根管器械","meta":"112年第1次第12題","year":112,"session":1,"number":12,"question":"關於根管治療中常用之蓋氏鑽針（Gates-Glidden drill），下列敘述何者錯誤？","options":["(A) 類似火焰的外型使其在提拉的過程中可垂直向下方切割","(B) 安全性雖高但是若過度使用，容易造成根管穿孔","(C) 依照國際標準，三號的蓋氏鑽針截面直徑為0.9 mm","(D) 轉速設定在750～1500 rpm範圍，最適合用於切割牙本質"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-13","subject":"ya3","topic":"根管治療程序","meta":"112年第1次第13題","year":112,"session":1,"number":13,"question":"根據1984年Vertucci, F. J.對於人類永久齒根管解剖的研究指出，下列牙根分叉處根管（furcation canal）發生的 機率，何者最高？","options":["(A) 上顎第一大臼齒","(B) 上顎第二大臼齒","(C) 下顎第一大臼齒","(D) 下顎第二大臼齒"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-14","subject":"ya3","topic":"根管治療程序","meta":"112年第1次第14題","year":112,"session":1,"number":14,"question":"關於氫氧化鈣作為根管用藥的敘述，下列何者錯誤？","options":["(A) 氫氧化鈣必須以水作為載具置入根管才能發揮作用","(B) 在根管內24小時就可達到快速殺菌的效果","(C) 其殺菌效果主要是來自具有高酸鹼值","(D) 殺菌能力不僅廣效且可持續數週"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-15","subject":"ya3","topic":"根管治療程序","meta":"112年第1次第15題","year":112,"session":1,"number":15,"question":"關於根管沖洗液雙氯苯雙胍己烷（chlorhexidine）和次氯酸鈉（NaOCl）溶液的比較，下列敘述何者錯誤？","options":["(A) chlorhexidine常用的濃度為0.12%～2%，次氯酸鈉則為0.5%～6%","(B) chlorhexidine偏酸性，次氯酸鈉屬於鹼性溶液","(C) chlorhexidine的組織溶解力差，低濃度的次氯酸鈉可藉由加熱增加組織溶解能力","(D) 2% chlorhexidine抗菌力遠不如5.25%次氯酸鈉"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-16","subject":"ya3","topic":"根管治療程序","meta":"112年第1次第16題","year":112,"session":1,"number":16,"question":"關於根管治療清創與修形的基本目標的敘述，下列何者錯誤？","options":["(A) 提供足夠的通道讓根管沖洗液能進入根管尖端的感染區域","(B) 為接下來的根管充填創造出足夠的空間","(C) 鎳鈦旋轉器械可將所有根管內壁做充分的清創與修形","(D) 最終修形的成果必須保持根管結構的完整性"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-17","subject":"ya3","topic":"根尖手術與再治療","meta":"112年第1次第17題","year":112,"session":1,"number":17,"question":"下列何項敘述不是牙齒根尖手術術前使用牙科電腦斷層攝影（CBCT）檢查的原因？","options":["(A) 確認下顎第一大臼齒根尖病變範圍是否延伸到下齒槽神經管","(B) 確認上顎前牙根尖病變是否造成鼻腔底部穿通","(C) 評估上顎小臼齒及大臼齒的根尖病變是否與鼻竇沾黏","(D) 透過CBCT可以正確診斷牙齒牙根是否有垂直牙根斷裂"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-18","subject":"ya3","topic":"根尖手術與再治療","meta":"112年第1次第18題","year":112,"session":1,"number":18,"question":"進行牙根尖手術時，關於手術牙齒與相對應之解剖結構考量（anatomical consideration）的配對，下列何者錯 誤？","options":["(A) 上顎正中門齒 – 大腭孔（greater palatine foramen）","(B) 下顎第二小臼齒 – 頦孔（mental foramen）","(C) 上顎第一大臼齒 – 上顎竇（maxillary sinus）","(D) 下顎第二大臼齒 – 頰側皮質骨板（buccal cortical plate）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-19","subject":"ya3","topic":"根尖手術與再治療","meta":"112年第1次第19題","year":112,"session":1,"number":19,"question":"上顎牙齒如果要進行腭側（palatal）牙根根尖手術，下列敘述何者錯誤？","options":["(A) 如果要進行腭側皮瓣翻瓣手術，必須要避免傷到前腭動脈（anterior palatine artery）","(B) 將垂直切線放在上顎側門齒可能會傷到前腭動脈（anterior palatine artery），一旦傷到前腭動脈必須進行手 術縫合","(C) 術後必須配合手術固定板（surgical stent）才能縫合固定腭側皮瓣","(D) 上顎小臼齒與第一大臼齒的腭側牙根，必須以腭側皮瓣翻瓣手術來切除感染的腭側牙根"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-20","subject":"ya3","topic":"根尖手術與再治療","meta":"112年第1次第20題","year":112,"session":1,"number":20,"question":"非手術根管治療常需先拆除根柱（post），過程中可能引發的風險何者錯誤？","options":["(A) 牙齒斷裂","(B) 鄰牙壞死","(C) 根柱斷裂","(D) 無法拆除"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-21","subject":"ya3","topic":"根管器械","meta":"112年第1次第21題","year":112,"session":1,"number":21,"question":"關於根管內分離器械（separated instrument）的敘述，何者正確？","options":["(A) 發現分離器械時的治療計畫為牙根尖手術或拔除","(B) 影響分離器械預後的因素為分離器械殘留在根管的位置","(C) 鎳鈦器械分離之前沒有預兆，所以達到建議使用次數就必須丟棄不用","(D) 若無法移除根管內的分離器械，必定導致根管治療失敗"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-22","subject":"ya3","topic":"根管治療程序","meta":"112年第1次第22題","year":112,"session":1,"number":22,"question":"有關牙根穿孔之修補（perforation repair），下列何者較不影響其預後？","options":["(A) 牙根穿孔的方式","(B) 穿孔的位置","(C) 修補前的感染期間","(D) 修復材料的封閉能力"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-23","subject":"ya3","topic":"黏著與美學修復","meta":"112年第1次第23題","year":112,"session":1,"number":23,"question":"關於牙齒漂白藥劑的敘述，下列何者錯誤？","options":["(A) 過硼酸鈉（sodium perborate）與水混合後會釋放出偏硼酸鈉（sodium metaborate）與過氧化氫（hydrogen peroxide)","(B) 與30%過氧化氫相比較，過硼酸鈉較被建議用於內部漂白（internal bleaching）","(C) 10%過碳酸醯胺（carbamide peroxide）微弱酸性，pH=5.0～6.5","(D) 10%尿素過氧化氫（urea hydrogen peroxide）約可釋放6%的過氧化氫"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-24","subject":"ya3","topic":"牙周疾病與診斷","meta":"112年第1次第24題","year":112,"session":1,"number":24,"question":"患齒在牙齦溝（gingival crevice）有深且窄的骨缺損，並有沿著牙根面的竇管（sinus tract）開口，最不可能的 診斷為何？","options":["(A) 垂直牙根斷裂","(B) 牙根面有發育溝（developmental groove），腭齦溝（palatogingival groove）","(C) 根管系統之感染","(D) 咬合傷害（occlusal trauma）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-25","subject":"ya3","topic":"牙髓診斷與病理","meta":"112年第1次第25題","year":112,"session":1,"number":25,"question":"下列那一種狀況較不適合使用直接覆髓術式（direct pulp capping）？","options":["(A) 窩洞過度修形時造成小範圍牙髓暴露","(B) 牙齒外傷引起牙髓暴露","(C) 支台齒牙齒修形造成牙髓暴露","(D) 細菌感染的牙髓"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-26","subject":"ya3","topic":"醫學倫理與法規","meta":"112年第1次第26題","year":112,"session":1,"number":26,"question":"關於知情同意（informed consent）的敘述，下列何者錯誤？","options":["(A) 知情同意三要素包含：告知、決定能力、自願","(B) 病人作決定時須沒有受到任何的暗示或脅迫","(C) 告知時使用醫學專業用語才能表現醫師專業能力","(D) 有能力作決定的病人，就有權利選擇、決定其醫療處置方式"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-27","subject":"ya3","topic":"牙髓診斷與病理","meta":"112年第1次第27題","year":112,"session":1,"number":27,"question":"如果在修磨牙釉質時，患者就感覺牙齒輕微酸軟，可能是牙釉質中何種構造受到刺激所導致？","options":["(A) 多結性牙釉質 （gnarled enamel）","(B) 牙釉梭（enamel spindle）","(C) 牙釉板（enamel lamellae）","(D) 牙釉叢（enamel tufts）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-28","subject":"ya3","topic":"牙科解剖與生理","meta":"112年第1次第28題","year":112,"session":1,"number":28,"question":"關於牙齒的硬度比較，下列何者正確？","options":["(A) 牙釉質>牙本質>牙骨質","(B) 牙釉質>牙骨質>牙本質","(C) 牙骨質>牙釉質>牙本質","(D) 牙釉質>牙本質=牙骨質"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-29","subject":"ya3","topic":"牙髓診斷與病理","meta":"112年第1次第29題","year":112,"session":1,"number":29,"question":"關於齲齒的敘述，下列何者錯誤？","options":["(A) 牙根齲齒通常具有明確的邊緣且截面呈現 V 字形","(B) 牙根齲齒發生率受唾液分泌量影響","(C) 鄰接面牙釉質齲齒常發生在接觸面之下","(D) 鄰接面牙釉質齲齒的放射線影像呈現錐形（cone），其尖端朝向牙釉質及牙本質交接面"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-30","subject":"ya3","topic":"牙髓診斷與病理","meta":"112年第1次第30題","year":112,"session":1,"number":30,"question":"下列何者不是齲齒中，感染性牙本質（infected dentin）的特徵？","options":["(A) 在受影響牙本質（affected dentin）的外層","(B) 可保留再礦化","(C) 富含細菌","(D) 牙本質小管變形"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-31","subject":"ya3","topic":"牙體修形程序","meta":"112年第1次第31題","year":112,"session":1,"number":31,"question":"牙體復形治療時，給予病人局部麻藥，何者不是牙醫師期望的效果？","options":["(A) 牙齒鎮痛","(B) 減少唾液分泌","(C) 減少治療區之血流量","(D) 增強口腔肌肉張力"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-32","subject":"ya3","topic":"黏著與美學修復","meta":"112年第1次第32題","year":112,"session":1,"number":32,"question":"經過磷酸（phosphoric acid）處理後的牙釉質表面，在電子顯微鏡下所呈現的酸蝕型態如圖所示，下列敘述何 者正確？","options":["(A) 上圖為 type I，下圖為 type II","(B) 上圖為 type II，下圖為 type I","(C) 上圖為 type I，下圖為 type III","(D) 上圖為 type III，下圖為 type I"],"answer":2,"image":"ya3-112-1-32.jpeg","clinical_level":"一般"},{"id":"ya3-112-1-33","subject":"ya3","topic":"黏著與美學修復","meta":"112年第1次第33題","year":112,"session":1,"number":33,"question":"複合樹脂填補時，使用酸蝕技術（acid etching technique）處理牙釉質（enamel），下列敘述何者錯誤？","options":["(A) 牙釉稜柱（enamel prism）中心及周邊部位均會被酸蝕溶解","(B) 牙釉質酸蝕後塗布樹脂黏著劑，所形成之樹脂突（resin tag）厚度為 10-20 micron","(C) 牙釉質酸蝕後塗布樹脂黏著劑，所形成之微樹脂突（micro-resin tag）位於牙釉稜柱中心（prism core）","(D) 牙釉質經酸蝕後，表面自由能（surface free energy）會增加"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-34","subject":"ya3","topic":"牙體修形程序","meta":"112年第1次第34題","year":112,"session":1,"number":34,"question":"以3碼方式標示的牙科切削型的手動器械，各碼依序代表下列何者？ ①刃寬（blade width） ② 刃長（blade length） ③刃角（blade angle） ④切緣角（cutting edge angle）","options":["(A) ①②③","(B) ②③①","(C) ①②④","(D) ②①④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-35","subject":"ya3","topic":"牙體修形程序","meta":"112年第1次第35題","year":112,"session":1,"number":35,"question":"使用低速手機（low speed handpiece）與高速手機（high speed handpiece）的比較，下列敘述何者錯誤？","options":["(A) 低速手機在窩洞製備的觸感（tactile sensation）較佳","(B) 碳鋼磨針（carbide bur）使用於低速手機時，壽命較長","(C) 低速手機適用於修形與磨光（finishing and polishing）","(D) 低速手機產生的振動較明顯"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-36","subject":"ya3","topic":"窩洞設計與分類","meta":"112年第1次第36題","year":112,"session":1,"number":36,"question":"上顎門齒舌面窩洞是屬 Black分類（Black's classification）之第幾類型窩洞？","options":["(A) 第一類型","(B) 第二類型","(C) 第三類型","(D) 第四類型"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-37","subject":"ya3","topic":"複合樹脂與材料","meta":"112年第1次第37題","year":112,"session":1,"number":37,"question":"玻璃離子體黏合劑（glass ionomer cement）不適用於下列何種成年人窩洞填補？","options":["(A) 牙根齲齒","(B) 齒頸部酸蝕（erosion）窩洞","(C) 咬合面齲齒","(D) 齒頸部磨損（abrasion）窩洞"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-38","subject":"ya3","topic":"複合樹脂與材料","meta":"112年第1次第38題","year":112,"session":1,"number":38,"question":"關於以複合樹脂為基底的溝隙封填劑（pit and fissure sealant）的敘述，下列何者錯誤？","options":["(A) 基質（matrix）內通常會加入 Bis-GMA","(B) 通常會加入TEGDMA 以增加黏稠度","(C) 可加入二氧化鈦（titanium dioxide）作為調色劑（colorant）","(D) 可為自凝型（self-curing），或是光凝型（light-curing）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-39","subject":"ya3","topic":"黏著與美學修復","meta":"112年第1次第39題","year":112,"session":1,"number":39,"question":"第三類複合樹脂填補後，在移除顎側多餘的材料並加以完成（final finishing）的過程，所使用鎢鋼鑽針 （carbide bur）的順序應為下列何者？","options":["(A) 先使用 8 刃，再使用 12 刃鎢鋼鑽針","(B) 先使用 12 刃，再使用 24 刃鎢鋼鑽針","(C) 先使用 24 刃，再使用 12 刃鎢鋼鑽針","(D) 先使用 12 刃，再使用 8 刃鎢鋼鑽針"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-40","subject":"ya3","topic":"黏著與美學修復","meta":"112年第1次第40題","year":112,"session":1,"number":40,"question":"前牙複合樹脂填補時，要達到合適的顏色選擇。決定顏色的時機，下列何者正確？","options":["(A) 吹乾牙齒後","(B) 橡皮障（rubber dam）置放後","(C) 窩洞製備後","(D) 表面染色（stain）去除後"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-41","subject":"ya3","topic":"複合樹脂與材料","meta":"112年第1次第41題","year":112,"session":1,"number":41,"question":"複合樹脂填補前，先將樹脂加熱再填補之相關敘述，下列何者錯誤？","options":["(A) 使用樹脂加熱器將樹脂預熱至 40°C","(B) 加熱的樹脂可降低黏稠度（viscosity）","(C) 加熱的樹脂可降低剛性（stiffness）","(D) 某些樹脂在加熱後，可以增加樹脂在邊緣的貼附性（marginal adaption）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-42","subject":"ya3","topic":"窩洞設計與分類","meta":"112年第1次第42題","year":112,"session":1,"number":42,"question":"下列何種條件是後牙樹脂填補的禁忌症（contraindication）？①承受過大咬合力之大型窩洞 ②鄰接面窩洞延 伸至牙根 ③無法隔濕 ④無法光照區域","options":["(A) 僅①②","(B) 僅③④","(C) 僅②③④","(D) ①②③④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-43","subject":"ya3","topic":"窩洞設計與分類","meta":"112年第1次第43題","year":112,"session":1,"number":43,"question":"近似立方體的第一類型複合樹脂窩洞（Class I cavity），其結構因子（C-factor）大約是多少？","options":["(A) 0.1～0.2","(B) 0.3～0.5","(C) 1.0～2.0","(D) 4.0～5.0"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-44","subject":"ya3","topic":"牙體修形程序","meta":"112年第1次第44題","year":112,"session":1,"number":44,"question":"汞齊填補時，下列何者剩餘牙本質厚度需使用樹脂強化玻璃離子體底墊？① 0.2 ～ 0.4 mm ② 0.5 ～ 1.0 mm ③ 1.1 ～ 1.5 mm ④ 1.6 ～ 2.0 mm","options":["(A) 僅①","(B) 僅①②","(C) 僅①②③","(D) ①②③④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-45","subject":"ya3","topic":"窩洞設計與分類","meta":"112年第1次第45題","year":112,"session":1,"number":45,"question":"第二類（Class II）窩洞的鄰接盒型（proximal box）過寬，使得頰舌側固位倒凹（retentive undercuts）無法互 相平行對應時，下列方法何者最不適合用來增加固位（retention）及抗力（resistance）？","options":["(A) 製備出多條固位溝","(B) 使用汞齊黏著系統（amalgam bonding system）","(C) 垂直方向置入自旋式螺針（self-threading pin）","(D) 水平方向置入自旋式螺針（self-threading pin）"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-46","subject":"ya3","topic":"複合樹脂與材料","meta":"112年第1次第46題","year":112,"session":1,"number":46,"question":"汞齊（amalgam）在硬化過程中不慎接觸到水，最不可能產生的變化為：","options":["(A) 體積收縮","(B) 增加孔洞","(C) 強度降低","(D) 增加腐蝕"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-47","subject":"ya3","topic":"牙體修形程序","meta":"112年第1次第47題","year":112,"session":1,"number":47,"question":"在陶瓷嵌體（ceramic inlays/onlays）修形後，下列何者最不適合用於增加臨時復形物與牙齒的固著力？","options":["(A) 使用聚羧酸鹽黏合劑（polycarboxylate cement）作為黏著劑","(B) 黏著前，可在臨時復形物內面製備出小的倒凹","(C) 黏著前，應在牙齒的修形邊緣處以磷酸做點狀酸蝕（spot etch）","(D) 若鄰牙也是復形物，可與鄰牙黏接以增加固著力"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-48","subject":"ya3","topic":"窩洞設計與分類","meta":"112年第1次第48題","year":112,"session":1,"number":48,"question":"下圖金合金嵌體的剖面圖中，X的理想角度應為何？","options":["(A) 15-20 度","(B) 40-45 度","(C) 60-65 度","(D) 75-80 度"],"answer":1,"image":"ya3-112-1-48.jpeg","clinical_level":"一般"},{"id":"ya3-112-1-49","subject":"ya3","topic":"窩洞設計與分類","meta":"112年第1次第49題","year":112,"session":1,"number":49,"question":"在金屬冠蓋體（onlay）裙邊形狀修形（skirt preparation）設計中，下列敘述何者最不適當？","options":["(A) 可增加冠蓋體固持效果","(B) 可防止剩餘齒質斷裂","(C) 可改善美觀效果","(D) 可重建復形牙齒的外形"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-50","subject":"ya3","topic":"黏著與美學修復","meta":"112年第1次第50題","year":112,"session":1,"number":50,"question":"下列何種狀況會造成視覺上牙齒亮度（lightness）降低？","options":["(A) 齒頸部磨耗（abrasion）","(B) 美白後的牙齒","(C) 塗深色唇膏","(D) 脫水的牙齒"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-51","subject":"ya3","topic":"黏著與美學修復","meta":"112年第1次第51題","year":112,"session":1,"number":51,"question":"A、B圖中箭頭所指牙齒，最有可能變色的原因分別為何？","options":["(A) 圖Ａ是矯正後牙齒白斑；圖Ｂ是充填後變色","(B) 圖Ａ是氟斑齒；圖Ｂ是充填後變色","(C) 圖Ａ是氟斑齒；圖Ｂ是創傷後牙髓壞死","(D) 圖Ａ是矯正後牙齒白斑；圖Ｂ是創傷後牙髓壞死"],"answer":2,"image":"ya3-112-1-51.jpeg","clinical_level":"一般"},{"id":"ya3-112-1-52","subject":"ya3","topic":"牙體修形程序","meta":"112年第1次第52題","year":112,"session":1,"number":52,"question":"下列何者最不適合用來作為陶瓷嵌體的暫時性填補物（provisional restoration）的黏著劑？","options":["(A) polycarboxylate cement","(B) zinc phosphate cement","(C) eugenol-based temporary cement","(D) resin-based temporary cement"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-53","subject":"ya3","topic":"牙周疾病與診斷","meta":"112年第1次第53題","year":112,"session":1,"number":53,"question":"下列何者為中間分岔嵴（intermediate bifurcation ridge）？","options":["(A) 凸累贅牙骨質（convex excrescence cementum）","(B) 凹累贅牙骨質（concave excrescence cementum）","(C) 凸累贅牙本質（convex excrescence dentin）","(D) 凹累贅牙本質（concave excrescence dentin）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-54","subject":"ya3","topic":"牙周疾病與診斷","meta":"112年第1次第54題","year":112,"session":1,"number":54,"question":"關於人類牙齦上皮的構造與成分，下列敘述何者錯誤？","options":["(A) 人類牙齦的上皮細胞是完全角化的（orthokeratinized）","(B) 非角化上皮（nonkeratinized epithelium）不具有顆粒層及角質層","(C) 基底板（basal lamina）最先合成的角質素是K19，其分子量較小","(D) K1角質素是角質層最主要的成分"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-55","subject":"ya3","topic":"牙周疾病與診斷","meta":"112年第1次第55題","year":112,"session":1,"number":55,"question":"關於人類牙齦上皮的代謝特徵之敘述，下列何者錯誤？","options":["(A) 牙齦溝上皮（sulcular epithelium）受到細菌等的局部刺激，可避免（prevent）其角質化","(B) 健康的牙齦溝上皮是含有網錐（rete pegs）的非角化複層麟狀上皮","(C) 牙齦角質化隨著年齡的增加及停經的發生而減少","(D) 健康的口腔上皮（oral epithelium）通常呈現角化不全（parakeratinized）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-56","subject":"ya3","topic":"牙周手術與再生","meta":"112年第1次第56題","year":112,"session":1,"number":56,"question":"牙周韌帶的principal fiber groups中，何者在一般的牙周手術時被切斷，並不會增加牙齒的鬆動度？","options":["(A) alveolar crest fibers","(B) horizontal fibers","(C) oblique fibers","(D) apical fibers"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-57","subject":"ya3","topic":"牙周疾病與診斷","meta":"112年第1次第57題","year":112,"session":1,"number":57,"question":"關於dental biofilms中微生物組成的敘述，下列何者正確？","options":["(A) 在牙齒的咬合面裂溝中，較多的細菌為葡萄球菌（staphylococci ）","(B) 在牙齒與牙齒之鄰接面（approximal surface）存在較多嗜氣細菌（aerobic species）","(C) 微生物組成不受到唾液分泌、食物及刷牙的影響","(D) 在牙齦溝中（gingival crevice）因為low Eh（oxidation-reduction potential）所以存在大量厭氣細菌（anaerobic species）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-58","subject":"ya3","topic":"牙周疾病與診斷","meta":"112年第1次第58題","year":112,"session":1,"number":58,"question":"關於壞死潰瘍性牙周炎（necrotizing ulcerative periodontitis）的敘述，下列何者錯誤？","options":["(A) 患有人類免疫缺陷病毒（HIV）之患者的口腔常有此現象","(B) 破壞僅限於牙齦，不會影響到齒槽骨","(C) 疾病的發生與宿主免疫力（host immunity）有密切關係","(D) 疾病的發生與生理性壓力和營養有密切關係"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-59","subject":"ya3","topic":"牙周疾病與診斷","meta":"112年第1次第59題","year":112,"session":1,"number":59,"question":"依圖示之社區牙周治療需求指數記錄（community periodontal index for treatment needs, CPITN），此象限應為 下列何者？","options":["(A) Code 1","(B) Code 2","(C) Code 3","(D) Code 4"],"answer":3,"image":"ya3-112-1-59.jpeg","clinical_level":"重點"},{"id":"ya3-112-1-60","subject":"ya3","topic":"牙周非手術治療","meta":"112年第1次第60題","year":112,"session":1,"number":60,"question":"承上題該病患之此象限的治療需求（treatment needs）為下列何者？","options":["(A) 此象限因牙齒數不足三顆，其治療需求應依前牙象限的紀錄指數為主","(B) 14、15兩顆小臼齒只需加強口腔衛生及洗牙","(C) 僅15小臼齒需加強口腔衛生及洗牙","(D) 此象限除了加強口腔衛生及洗牙，還需進一步牙周專業處理"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-61","subject":"ya3","topic":"牙周疾病與診斷","meta":"112年第1次第61題","year":112,"session":1,"number":61,"question":"牙周免疫反應關於T細胞之間功能可塑性（functional plasticity）轉換的敘述，下列何者錯誤？","options":["(A) Th17受到白細胞介素12（IL-12）影響可發展成Th1","(B) Th17受到白細胞介素4（IL-4）影響可發展成Th2","(C) Th1和Th2相對穩定，不會轉換成其他T細胞","(D) 調控T細胞（regulatory T-cells, Treg cells）相對穩定，不會轉換成Th17"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-62","subject":"ya3","topic":"牙周疾病與診斷","meta":"112年第1次第62題","year":112,"session":1,"number":62,"question":"下圖是Page和Schröeder（1976年）那一期牙齦炎／牙周炎的組織病理病灶？","options":["(A) 初期牙齦病灶","(B) 早期牙齦病灶","(C) 建立期病灶","(D) 晚期病灶"],"answer":1,"image":"ya3-112-1-62.jpeg","clinical_level":"重點"},{"id":"ya3-112-1-63","subject":"ya3","topic":"牙周非手術治療","meta":"112年第1次第63題","year":112,"session":1,"number":63,"question":"有關牙周治療後促進牙周組織癒合的因素，不包括下列何者？","options":["(A) 大量增加牙齦組織的氧（oxygen）含量以促進組織癒合","(B) 增加營養攝取（例如：維生素C及蛋白質）","(C) 減少dental plaque的堆積","(D) cortisone的使用會妨礙造纖維細胞的生長，影響結締組織的生成，不利於癒合"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-64","subject":"ya3","topic":"牙周非手術治療","meta":"112年第1次第64題","year":112,"session":1,"number":64,"question":"關於Gracey curettes系列器械的敘述，下列何者正確？","options":["(A) After Five curette的terminal shank長度比standard Gracey curettes增加5 mm，適合治療窄而深的囊袋","(B) Mini Five curettes是standard Gracey curettes的改良型，特徵是刀刃長度只有有標準型的1/2，適合治療根叉 （furcation）病變","(C) Gracey #15-16結構特徵是具有 Gracey #13-14 的shank，適合後牙近心側的治療","(D) Gracey curvettes屬於 mini-bladed curettes；其操作更能貼近後牙牙齒表面而不會產生刮痕"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-65","subject":"ya3","topic":"牙周非手術治療","meta":"112年第1次第65題","year":112,"session":1,"number":65,"question":"完成牙周病基本治療後的療效評估（re-evaluation），下列敘述何者正確？","options":["(A) 臨床治療目標需達到無探測流血","(B) 探測流血 ＜10%，未來仍然會有高風險牙周病的復發率","(C) 良好的牙菌斑控制下，多根牙的治療效果優於單根牙","(D) 臼齒區探測囊袋深度＞6 mm時，重做基本治療優於手術處置"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-66","subject":"ya3","topic":"牙周手術與再生","meta":"112年第1次第66題","year":112,"session":1,"number":66,"question":"臨床上，目前已被證實可促進牙周再生（periodontal regeneration），包括硬（骨）與軟組織的生物活性因子 （biologic mediator），下列何者錯誤？","options":["(A) 牙釉基質蛋白（enamel matrix protein）","(B) 血小板衍生生長因子（platelet-derived growth factor）","(C) 成纖維細胞生長因子（fibroblast growth factor）","(D) 骨成型蛋白（bone morphogenetic protein）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-67","subject":"ya3","topic":"牙周手術與再生","meta":"112年第1次第67題","year":112,"session":1,"number":67,"question":"關於上顎大臼齒牙根切除術（root resection）的執行，下列何者正確？","options":["(A) 近心頰側（mesiobuccal）根由於較短、且支持骨量較少，是執行牙根切開術最常被移除的牙根","(B) 牙根宜採水平式切除，以減少切削面的凹陷","(C) 若術前無法進行根管治療，則於術後二週內完成根管治療即可","(D) 臨時填補物邊緣需距離齒槽嵴至少需2 mm"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-68","subject":"ya3","topic":"牙周手術與再生","meta":"112年第1次第68題","year":112,"session":1,"number":68,"question":"下列何者不是決定牙周再生術式之準則（criteria）？","options":["(A) 角化牙齦厚度","(B) 骨缺損之形態與尺寸","(C) 缺損區之骨壁（bone wall）數量","(D) 牙根裸露之程度與形態"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-69","subject":"ya3","topic":"牙周疾病與診斷","meta":"112年第1次第69題","year":112,"session":1,"number":69,"question":"依照Glickman的根叉侵犯（furcation involvement）分類，下列根叉侵犯何者的外型如死巷（cul-de-sac）構 造？","options":["(A) Grade I根叉侵犯","(B) Grade II根叉侵犯","(C) Grade III根叉侵犯","(D) Grade IV根叉侵犯"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-70","subject":"ya3","topic":"牙周手術與再生","meta":"112年第1次第70題","year":112,"session":1,"number":70,"question":"關於微創手術（minimal invasive surgery）的敘述，下列何者錯誤？","options":["(A) 縫合時應維持皮瓣微微的張力","(B) 如果骨缺損較大的時候，可以將切線延伸至相鄰之牙齦乳突","(C) 翻瓣時可以使用modified papilla preservation technique或是simplified papilla preservation flap","(D) 不應將皮瓣做冠向移置（coronal displacement）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-71","subject":"ya3","topic":"牙周手術與再生","meta":"112年第1次第71題","year":112,"session":1,"number":71,"question":"游離軟組織移植手術術後第14天，傷口處在下列那一階段？","options":["(A) initial phase","(B) revascularization phase","(C) tissue maturation phase","(D) inflammation phase"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-72","subject":"ya3","topic":"牙周手術與再生","meta":"112年第1次第72題","year":112,"session":1,"number":72,"question":"關於牙周手術中的牙根表面處理，下列敘述何者錯誤？","options":["(A) 目標為去除塗抹層（smear layer），使牙根表面去礦化","(B) 較低酸鹼值的表面處理溶劑可能會造成周邊牙周組織的壞死","(C) EDTA具有抑制纖維分解的能力","(D) 處理後的牙根在癒合後主要以長連接上皮及纖維組織為主並無新生牙骨質"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-73","subject":"ya3","topic":"牙周疾病與診斷","meta":"112年第1次第73題","year":112,"session":1,"number":73,"question":"對於個別牙齒危險評估（risk assessment）的敘述，下列何者錯誤？","options":["(A) 牙周破壞和牙齒異常位置（malposition）有明確關係","(B) 破壞到牙根分岔（furcation）的牙齒，預後較差","(C) 醫源性（iatrogenic factors）的問題如不良牙套，會影響牙周健康","(D) 牙齒動搖度（mobility）增加，代表牙周組織的支持減少所導致"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-74","subject":"ya3","topic":"牙周非手術治療","meta":"112年第1次第74題","year":112,"session":1,"number":74,"question":"關於支持性牙周治療（supportive periodontal therapy, SPT）的敘述，下列何者錯誤？","options":["(A) 記錄牙周囊袋以及口腔衛生狀況","(B) 加強動機，尤其是口腔衛生不佳的患者","(C) 做全口牙根整平術","(D) 全齒列磨光及塗氟"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-112-1-75","subject":"ya3","topic":"牙科解剖與生理","meta":"112年第1次第75題","year":112,"session":1,"number":75,"question":"對於患有心血管疾病的患者，其牙周病治療的考量下列何者最正確？","options":["(A) 高血壓患者自述有按時吃藥控制，平常在家測量約為130/80 mmHg。進行牙周病手術治療時可以不用監控血 壓","(B) 牙科診間應備有氧氣及有效期限內的nitroglycerin等急救設備及藥物","(C) 曾患心肌梗塞的患者，一年內不建議進行牙周病治療","(D) 曾進行心臟繞道（cardiac bypass）手術的患者，建議在牙科治療前一律給予預防性抗生素"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-76","subject":"ya3","topic":"牙科解剖與生理","meta":"112年第1次第76題","year":112,"session":1,"number":76,"question":"目前已知數種病毒會導致病毒性肝炎，由於多數的受感染者並未被診斷出來，因此臨床醫護人員受感染的風 險較高。下列何者敘述較為正確？","options":["(A) Hepatitis A virus及Hepatitis B virus感染的患者多數會痊癒而不會造成慢性肝病","(B) Hepatitis C virus 感染的患者只有5%到10%患者會發展為慢性HCV感染，其中又以嬰幼兒居多","(C) Hepatitis B virus容易經由受傷的皮膚或粘膜感染人體，因此建議所有醫療人員需施打疫苗","(D) Hepatitis G virus 是種DNA病毒，可藉由血液感染人體"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-77","subject":"ya3","topic":"牙科解剖與生理","meta":"112年第1次第77題","year":112,"session":1,"number":77,"question":"一位女性懷孕第16週，牙科門診主訴牙齦紅腫、刷牙流血，症狀持續約兩週。經檢查後診斷為牙周炎，下列 處置何者較為正確？","options":["(A) 不建議幫患者進行任何牙科治療，包含潔牙及根面整平術","(B) 懷孕中期（second trimester）狀態較為穩定，建議替患者進行牙周病手術治療","(C) 根據美國牙醫協會聲明：「必要時仍可以做正常的牙科放射線拍攝」","(D) 就診時，建議平躺姿勢較為舒適，並且每次治療時間勿過長"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-78","subject":"ya3","topic":"植牙學","meta":"112年第1次第78題","year":112,"session":1,"number":78,"question":"關於植體的敘述，下列何者正確？","options":["(A) 鬆質骨（cancellous bone）之BIC（bone-to implant contact）比皮質骨（cortical bone）多","(B) 植牙第一年都會有2.0 mm之bone resorption","(C) 成功之植體在第一年受力後，年平均crest bone loss 預期小於0.1 mm","(D) 跟埋入植型（submerged）比較起來，非埋入植型（nonsubmerged）不會有植牙第一年之bone remodeling"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-79","subject":"ya3","topic":"植牙學","meta":"112年第1次第79題","year":112,"session":1,"number":79,"question":"植體立即負荷（immediate loading）其成功的最重要因素是依靠下列何者？","options":["(A) primary implant stability","(B) a splinted prosthesis","(C) implant surface coating","(D) systematic oral hygiene"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-1-80","subject":"ya3","topic":"植牙學","meta":"112年第1次第80題","year":112,"session":1,"number":80,"question":"牙齦在健康情況下，以大於0.5 N來探測植體牙齦溝的深度（implant gingival sulcus），通常牙周探測具前端 （直徑0.5 mm）會落在下列何項解剖位置內？","options":["(A) 在植體牙齦溝內","(B) 連接上皮","(C) 結締組織內，靠近連接上皮端","(D) 結締組織內，靠近齒槽骨端"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-1","subject":"ya3","topic":"牙髓診斷與病理","meta":"112年第2次第1題","year":112,"session":2,"number":1,"question":"病人主訴近2個月上顎左側小臼齒區喝冰水敏感。經檢查上顎左側小臼齒齒頸部牙釉質脫落磨耗，牙本質暴 露，此敏感為牙髓內何種神經纖維所引發？","options":["(A) A-alpha 神經纖維","(B) A-delta 神經纖維","(C) C 神經纖維","(D) A-gamma 神經纖維"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-2","subject":"ya3","topic":"牙科解剖與生理","meta":"112年第2次第2題","year":112,"session":2,"number":2,"question":"關於牙齒發育的敘述，下列何者正確？","options":["(A) 牙齒主要由外胚層間葉組織（ectomesenchyme）與中胚層發育而來","(B) 外胚層間葉組織（ectomesenchyme）分化為造釉母細胞（ameloblast）","(C) 鐘型期（bell stage）於牙本質與牙釉質形成之後，感覺神經進入牙乳頭（dental papilla）","(D) 造成C形牙根是因舌側赫威氏上皮根鞘（Hertwig's root sheath）無法結合所致，因此常造成舌側溝（lingual groove）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-3","subject":"ya3","topic":"牙科解剖與生理","meta":"112年第2次第3題","year":112,"session":2,"number":3,"question":"牙齒發育過程中由表皮細胞（epithelial cell）與間葉細胞（mesenchymal cell）分化成造釉母細胞（ameloblast） 與造牙本質細胞（odontoblast），下列敘述何者正確？","options":["(A) 造釉母細胞之分化時程通常較造牙本質細胞早","(B) 造釉母細胞之分化時程通常較造牙本質細胞晚","(C) 造釉母細胞與造牙本質細胞之分化時程一樣快","(D) 造釉母細胞與造牙本質細胞分屬不同層次，兩者分化時程難分先後"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-4","subject":"ya3","topic":"牙髓診斷與病理","meta":"112年第2次第4題","year":112,"session":2,"number":4,"question":"未經根管治療的初級根管感染來源（primary root canal infection）是多種微生物產生的結果，下列何種細菌占 有主導地位？","options":["(A) 專性厭氧菌（obligate anaerobes）","(B) 專性嗜氧菌（obligate aerobe）","(C) 兼性厭氧菌（facultative anaerobic organism）","(D) 微需氧菌（microaerophile）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-5","subject":"ya3","topic":"牙髓診斷與病理","meta":"112年第2次第5題","year":112,"session":2,"number":5,"question":"在慢性根尖周圍炎病變的發展中，神經胜肽（neuropeptides）也參與免疫調節、骨吸收和傷口癒合。下列何者 上調（up-regulate）免疫炎性反應？","options":["(A) 血管活性腸肽（vasoactive intestinal peptide, VIP）","(B) 神經胜肽Y（neuropeptide Y, NPY）","(C) 物質P（substance P, SP）","(D) 降鈣素基因相關肽（calcitonin gene-related peptide, CGRP）"],"answer":[2,3],"image":"","clinical_level":"一般"},{"id":"ya3-112-2-6","subject":"ya3","topic":"牙髓診斷與病理","meta":"112年第2次第6題","year":112,"session":2,"number":6,"question":"關於牙髓病檢查，下列敘述何者錯誤？","options":["(A) 選擇性麻醉試驗（selective anesthesia test）可用以區分疼痛來自於上顎還是下顎的牙齒","(B) 雷射都卜勒流量儀（laser doppler flowmeter）是藉由偵測牙髓內的血流，來檢查牙髓活性","(C) 在眾多冷溫試驗（cold test）的方法中，使用氯乙烷（ethyl chloride）會比使用乾冰（carbon dioxide ice）所 得的結果更準確","(D) 進行熱測試（heat test）時，使用熱水浴法（hot water bath）可以得到最準確的結果"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-7","subject":"ya3","topic":"牙髓診斷與病理","meta":"112年第2次第7題","year":112,"session":2,"number":7,"question":"有關物質P（substance P）的敘述，下列何者正確？","options":["(A) 只存在中樞神經系統（CNS）","(B) 只存在周圍神經系統（PNS）","(C) 可促使肥大細胞（mast cells）釋放出組織胺（histamine）","(D) 可引起血管收縮"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-8","subject":"ya3","topic":"牙齒外傷處理","meta":"112年第2次第8題","year":112,"session":2,"number":8,"question":"牙齒外傷後，所謂非複雜性牙冠斷裂（uncomplicated crown fractures），是指下列何者？","options":["(A) 僅有牙釉質斷裂，未侵犯其他牙齒硬組織","(B) 同時侵犯牙釉質與牙本質的斷裂，未傷及牙髓組織","(C) 未侵犯至牙骨質牙釉質交界（cemento-enamel junction），但合併牙髓暴露之牙本質斷裂","(D) 同時侵犯牙釉質、牙本質與少量牙髓的牙齒斷裂，不需根管治療之牙齒"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-9","subject":"ya3","topic":"牙齒外傷處理","meta":"112年第2次第9題","year":112,"session":2,"number":9,"question":"25歲女性撞到右上門牙，檢查發現牙齒完整，牙齦溝出血，動搖度與鄰牙相較顯著增加但無移位，電髓活性測 試無反應，冷測試有反應，明顯敲診痛與輕微觸診痛，Ｘ光檢查無特殊發現。何者為此外傷牙齒最適當的診 斷？","options":["(A) 齒震盪（concussion）","(B) 半脫位（subluxation）","(C) 側向脫位（lateral luxation）","(D) 內縮脫位（intrusive luxation）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-10","subject":"ya3","topic":"根管治療程序","meta":"112年第2次第10題","year":112,"session":2,"number":10,"question":"關於活髓治療（vital pulp therapy）的敘述，下列何者錯誤？","options":["(A) 牙髓組織健康且沒有發炎狀況，是活髓治療成功的重要條件","(B) MTA（mineral trioxide aggregate）因其酸鹼值（pH value）較高及生物相容性佳，是較常被推薦使用的醫材","(C) 氫氧化鈣硬化後之緻密度，可以使微生物無法穿透造成感染","(D) MTA（mineral trioxide aggregate）比氫氧化鈣有更緻密封填的效果"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-11","subject":"ya3","topic":"根管治療程序","meta":"112年第2次第11題","year":112,"session":2,"number":11,"question":"關於根管充填用馬來膠針（gutta-percha）的敘述，下列何者錯誤？","options":["(A) 其成分中馬來膠約20%，氧化鋅（zinc oxide）約65%，放射線不透光劑（radiopacifiers）約10%，塑化劑 （plasticizers）約5%","(B) 馬來膠是天然橡膠的同素異構物（trans-isomer）","(C) 馬來膠晶相在常溫下為alpha phase，比較難擠壓，經加熱後會相轉變為beta phase，比較具有流動性","(D) alpha phase的馬來膠經加熱冷卻後的體積穩定性較好，收縮量較小"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-12","subject":"ya3","topic":"根管器械","meta":"112年第2次第12題","year":112,"session":2,"number":12,"question":"關於標準化K-type files（ANSI No. 28）根管銼的敘述，下列何者錯誤？","options":["(A) 長度有21、25、31 mm，cutting flutes 有16 mm","(B) 35號標準化銼針（file）的顏色標示是綠色，D0直徑是0.35 mm，D16直徑是0.67 mm","(C) 30號、60號、110號有相同的顏色標示，都是藍色","(D) 錐度（taper）都是0.02"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-13","subject":"ya3","topic":"根管治療程序","meta":"112年第2次第13題","year":112,"session":2,"number":13,"question":"下列何者不屬於矽酸鈣類封填劑（tricalcium/dicalcium silicate sealer）的優點？","options":["(A) 具有良好的生物相容性","(B) 硬化過程中具有非常少的體積變化","(C) 具有較長的硬化時間以利操作","(D) 具有親水性及高鹼性"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-14","subject":"ya3","topic":"根管治療程序","meta":"112年第2次第14題","year":112,"session":2,"number":14,"question":"關於切開引流（incision for drainage）的敘述，下列何者錯誤？","options":["(A) 須施以局部麻醉","(B) 在最腫脹的區域做橫向切線（horizontally oriented incision〉切開牙齦","(C) 小心地分開組織深入膿瘍區域，直到感染來源之牙齒牙根處","(D) 引流管（drain）的放置可以避免切口（incision）太快關閉"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-15","subject":"ya3","topic":"牙髓診斷與病理","meta":"112年第2次第15題","year":112,"session":2,"number":15,"question":"下列何種狀況較難用錐狀射束電腦斷層掃描（cone beam computed tomography, CBCT）正確診斷？","options":["(A) 垂直牙根斷裂（vertical root fracture）","(B) 水平牙根斷裂（horizontal root fracture）","(C) 齒頸部外吸收（external cervical resorption）","(D) 牙根內吸收（internal resorption）"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-16","subject":"ya3","topic":"根管治療程序","meta":"112年第2次第16題","year":112,"session":2,"number":16,"question":"下列何者不是根管沖洗液次氯酸鈉（sodium hypochlorite）具有的作用？","options":["(A) 機械沖洗（mechanical flushing）根管殘屑","(B) 止血作用（hemostasis）","(C) 溶解活的或是壞死組織（dissolve vital or necrotic tissue）","(D) 潤滑作用（lubricating action）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-17","subject":"ya3","topic":"根管治療程序","meta":"112年第2次第17題","year":112,"session":2,"number":17,"question":"根尖孔大的根管可使用馬來膠針（gutta-percha, GP）客製主錐（custom main cone）進行根管充填，關於客製 主錐的製備程序，下列何者錯誤？","options":["(A) 通常選擇可到達根管工作長度的GP進行製備","(B) 可將GP尖端浸泡馬來膠軟化溶液1～2秒以軟化表層材料","(C) 可使用加熱方式軟化GP表層材料","(D) 進行GP尖端塑形時，需注意每次置放的方向應一致"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-18","subject":"ya3","topic":"根管治療程序","meta":"112年第2次第18題","year":112,"session":2,"number":18,"question":"移除部分牙髓進行活髓治療，當使用NaOCl處理至少多久仍無法有效控制出血時，須考慮移除全部的冠部牙 髓組織？","options":["(A) 1分鐘以內","(B) 2～4分鐘","(C) 5～10分鐘","(D) 大於10分鐘"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-19","subject":"ya3","topic":"根尖手術與再治療","meta":"112年第2次第19題","year":112,"session":2,"number":19,"question":"根尖手術進行切線設計，欲進行邊緣下切線（submarginal incision）時，須考慮附連牙齦（attached gingiva） 的寬度，下列敘述何者正確？","options":["(A) 附連牙齦至少需有2 mm寬","(B) 附連牙齦在犬齒區域比大臼齒區域寬","(C) 附連牙齦寬度，平均而言下顎比上顎寬","(D) 切線落在離牙齦溝（gingiva sulcus）1 mm的位置最適合"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-20","subject":"ya3","topic":"根尖手術與再治療","meta":"112年第2次第20題","year":112,"session":2,"number":20,"question":"根尖手術中，若使用牽引器（retractor）無法穩定撐開牙齦進行手術時，下列何種做法最適當？","options":["(A) 將牽引器置於軟組織上","(B) 在皮質骨切個小溝槽以定位牽引器","(C) 將牽引器置於骨窗（bone window）內下緣","(D) 使用骨膜剝離器（periosteal elevator）取代"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-21","subject":"ya3","topic":"牙髓診斷與病理","meta":"112年第2次第21題","year":112,"session":2,"number":21,"question":"關於根管治療預後評估所使用的根尖周指數（Periapical Index, PAI），下列敘述何者正確？","options":["(A) 是評估根尖觸診時按壓疼痛的指數","(B) 依按壓疼痛的程度分為0～3分，3分為牙齦表面已有腫脹","(C) 為牙周囊袋之測量，按囊袋深度分為0～5分，5分為囊袋深度超過6 mm","(D) 為評量根尖病灶X光放射線透過度的方法"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-22","subject":"ya3","topic":"牙髓診斷與病理","meta":"112年第2次第22題","year":112,"session":2,"number":22,"question":"關於感染性根管內的細菌，下列敘述何者錯誤？","options":["(A) 尚未接受根管治療的感染性根管中大多是多種菌、厭氧菌","(B) 已接受過根管治療並完成根管充填的感染性根管中大多為單一菌、非厭氧菌","(C) 已接受過根管治療並完成根管充填的感染性根管中最常被分離出的菌種為Enterococcus faecalis","(D) 已接受過根管治療但根管充填距離未達根尖一半的感染性根管中的細菌多為非厭氧菌"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-23","subject":"ya3","topic":"根尖手術與再治療","meta":"112年第2次第23題","year":112,"session":2,"number":23,"question":"關於牙根切除術（root resection），下列敘述何者正確？","options":["(A) 術前最好先進行根管治療","(B) 失敗的主要原因是牙周的破壞","(C) 活髓牙根切除後要先觀察牙髓的活性，再進行根管治療","(D) 長期預後觀察，活髓牙根切除比失活牙根切除為佳"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-24","subject":"ya3","topic":"根管治療程序","meta":"112年第2次第24題","year":112,"session":2,"number":24,"question":"根管治療後的牙齒，下列何者不是剩餘齒質結構太少常見的併發症？","options":["(A) 齲齒和牙周病","(B) 冠心移位或脫落","(C) 牙根斷裂","(D) 牙根吸收"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-25","subject":"ya3","topic":"黏著與美學修復","meta":"112年第2次第25題","year":112,"session":2,"number":25,"question":"關於根管治療後牙齒接受齒內漂白（internal bleaching）的敘述，下列何者錯誤？","options":["(A) 不可以在根管封填當次同時進行","(B) 變色牙齒的外觀，在齒內漂白後通常可以得到改善","(C) 銀粉填補造成之牙齒變色較不易漂白","(D) 變色復發趨勢與牙齒變色時間長短無顯著相關"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-26","subject":"ya3","topic":"醫學倫理與法規","meta":"112年第2次第26題","year":112,"session":2,"number":26,"question":"對於根管治療後的牙齒，提供病人後續治療策略的選擇和說明優缺點，讓病人在進行治療前，能共享現有的 醫療實證結果，並支持病人做出符合其偏好的醫療方式，符合下列那一項醫學倫理的原則？","options":["(A) 公平正義原則","(B) 行善原則","(C) 不傷害原則","(D) 自主原則"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-27","subject":"ya3","topic":"牙科解剖與生理","meta":"112年第2次第27題","year":112,"session":2,"number":27,"question":"關於牙釉質（enamel）的特性，下列敘述何者錯誤？","options":["(A) 生成牙釉質的造釉母細胞（ameloblasts），起源於外胚層","(B) 恆牙牙釉稜柱（enamel rods）在所有部位之排列均垂直於牙本質牙釉質交界（DEJ）和牙齒表面","(C) 靠近牙本質交接處之牙釉稜柱（enamel rods）的直徑大小會比牙齒表面來得小","(D) 牙釉質的生理性磨耗一年約 15～30 µm 左右"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-28","subject":"ya3","topic":"牙科解剖與生理","meta":"112年第2次第28題","year":112,"session":2,"number":28,"question":"有關繼生牙本質生成（secondary dentin formation）之敘述，下列何者錯誤？","options":["(A) 生成速率逐年遞減","(B) 生成速率低於原生牙本質（primary dentin）","(C) 造成牙髓腔（pulp chamber）縮小","(D) 一旦牙齒萌發就停止生成"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-29","subject":"ya3","topic":"牙科解剖與生理","meta":"112年第2次第29題","year":112,"session":2,"number":29,"question":"關於後天性牙釉質薄膜（acquired enamel pellicle）的敘述，下列何者錯誤？","options":["(A) 由唾液中的成分構成","(B) 可幫助再礦化（remineralization）","(C) 會增加牙齒間的摩擦力","(D) 為無細胞、無結構性的有機膜"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-30","subject":"ya3","topic":"牙科解剖與生理","meta":"112年第2次第30題","year":112,"session":2,"number":30,"question":"關於齲齒的受影響牙本質（affected dentin）區域，下列敘述何者錯誤？","options":["(A) 此區有自我修復的能力","(B) 此區的管間牙本質（intertubular dentin）呈現去礦化（demineralization）","(C) 此區應徹底移除，以免微生物殘留","(D) 此區比正常牙本質軟"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-31","subject":"ya3","topic":"醫學倫理與法規","meta":"112年第2次第31題","year":112,"session":2,"number":31,"question":"下列何者不是在高齲齒率患者回診時建議的治療或事項？","options":["(A) 專業塗氟","(B) 口腔清潔與飲食諮商","(C) 每 6～12 月照射咬翼X光片","(D) 照射全口根尖 X 光攝影"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-32","subject":"ya3","topic":"牙科解剖與生理","meta":"112年第2次第32題","year":112,"session":2,"number":32,"question":"牙本質小管的單位面積數量，在牙髓端（pulp）及牙本質—牙釉質交接處（DEJ）分別為下列何者？","options":["(A) 45,000/mm2 及 20,000/mm2","(B) 4,500/mm2 及 2,000/mm2","(C) 45,000/mm2 及 2,000/mm2","(D) 2,000/mm2 及 4,500/mm2"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-33","subject":"ya3","topic":"黏著與美學修復","meta":"112年第2次第33題","year":112,"session":2,"number":33,"question":"對於塗抹層（smear layer）的敘述，下列何者錯誤？","options":["(A) 塗抹層會降低牙本質（dentin）的滲透性（permeability）","(B) 塗抹層含有氫氧磷灰石（hydroxyapatite）","(C) 塗抹層含有變質膠原蛋白（denatured collagen）","(D) 牙本質液（dentinal fluid）不能通過塗抹層中的小孔洞（porosity），向外流動擴散（diffusion）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-34","subject":"ya3","topic":"牙體修形程序","meta":"112年第2次第34題","year":112,"session":2,"number":34,"question":"關於牙科直鑿（straight chisel）的敘述，下列何者錯誤？","options":["(A) 主要是使用於牙釉質","(B) 刃部（blade）有雙斜面（bevel）","(C) 柄部（shank）與刃部（blade）皆是直線（straight）型","(D) 主切緣（primary edge）是垂直於握把的中軸線（axis of handle）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-35","subject":"ya3","topic":"牙體修形程序","meta":"112年第2次第35題","year":112,"session":2,"number":35,"question":"使用高速手機磨牙的敘述，下列何者錯誤？","options":["(A) 使用具有彎角（contra-angle）的手機","(B) 需要有水冷系統","(C) 手機轉速小於 200,000 rpm","(D) 對手機施力要輕柔"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-36","subject":"ya3","topic":"牙體修形程序","meta":"112年第2次第36題","year":112,"session":2,"number":36,"question":"在無法使用橡皮障（rubber dam）的狀況，欲進行嵌體試戴，應使用何種裝置預防嵌體在過程中不慎吞入？","options":["(A) 以棉捲（cotton rolls）隔絕牙齒兩側","(B) 以牙線（floss）綁住嵌體","(C) 以棉捲固定器（cotton roll holder）增加隔離區域","(D) 以紗布製作喉嚨屏障（throat shields）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-37","subject":"ya3","topic":"複合樹脂與材料","meta":"112年第2次第37題","year":112,"session":2,"number":37,"question":"關於傳統玻璃離子體（conventional glass ionomer）的敘述，下列何者錯誤？","options":["(A) 在牙釉質及牙本質上產生的巨剪力黏結強度（macroshear bond strength），約 6～12 MPa 間","(B) 為水性系統（aqueous system），可有效地潤濕牙齒組織，因此可很容易地貼合到牙齒上細微的空間 （micromechanical space）內","(C) 可在牙齒組織上產生機械性（mechanical）及化學性（chemical）黏結","(D) 黏著強度較牙本質黏著劑為低"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-38","subject":"ya3","topic":"牙體修形程序","meta":"112年第2次第38題","year":112,"session":2,"number":38,"question":"使用橡皮障（rubber dam）時，牙齒間的橡皮障出現皺褶，可能的原因為何？","options":["(A) 橡皮障的厚度太薄","(B) 在打洞時，洞與洞之間距離太寬","(C) 打出的牙弓形態偏離橡皮障中心","(D) 打出的牙弓形態過小"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-39","subject":"ya3","topic":"複合樹脂與材料","meta":"112年第2次第39題","year":112,"session":2,"number":39,"question":"複合樹脂在磨光（polish）後，隨著長期接觸飲料與食物後，下列敘述何者正確？","options":["(A) 最易保持光澤：奈米粒子型複合樹脂（nanofilled composite），最易失去光澤：巨粒子型複合樹脂 （macrofilled composite）","(B) 最易保持光澤：巨粒子型複合樹脂（macrofilled composite），最易失去光澤：混雜型複合樹脂（hybrid composite）","(C) 最易保持光澤：混雜型複合樹脂（hybrid composite），最易失去光澤：奈米粒子型複合樹脂（nanofilled composite）","(D) 最易保持光澤：巨粒子型複合樹脂（macrofilled composite），最易失去光澤：奈米粒子型複合樹脂 （nanofilled composite）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-40","subject":"ya3","topic":"窩洞設計與分類","meta":"112年第2次第40題","year":112,"session":2,"number":40,"question":"關於第三類窩洞複合樹脂填補的敘述，下列何者錯誤？","options":["(A) 為了增加樹脂的固位性，大多都會製備固位溝（retention groove）","(B) 為了增加鍵結，可在唇側的窩緣邊緣（cavosurface margin）做牙釉質斜面","(C) 為了增加美觀，通常會在唇側的窩緣邊緣（cavosurface margin）做牙釉質斜面","(D) 為了增加鍵結，必須確實做好隔濕"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-41","subject":"ya3","topic":"窩洞設計與分類","meta":"112年第2次第41題","year":112,"session":2,"number":41,"question":"在第三類型窩洞（Class III cavity）製備時，下列敘述何者錯誤？","options":["(A) 應由舌側或腭側進入為優先考量","(B) 沒有支撐的頰側牙釉質（unsupported facial enamel）必須完全移除","(C) 從邊緣嵴（marginal ridge）開始切削，並避免傷害鄰牙","(D) 若頰側（facial surfaces）有齲齒，可由頰側進入製備"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-42","subject":"ya3","topic":"牙體修形程序","meta":"112年第2次第42題","year":112,"session":2,"number":42,"question":"臨床狀況使用小窩裂溝封閉劑（pit and fissure sealant）的治療方法中，下列敘述何者正確？","options":["(A) 可使用於蛀牙風險高合併牙釉質融合不良（incomplete coalescence of enamel ）的成人患者","(B) 治療前不需經過咬翼片 X 光檢查","(C) 可使用於進行至牙本質的蛀牙","(D) 操作前應以探針用力探測溝縫"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-43","subject":"ya3","topic":"窩洞設計與分類","meta":"112年第2次第43題","year":112,"session":2,"number":43,"question":"相較於汞齊之填補，第二類型複合樹脂填補的窩洞修形原則，下列敘述何者錯誤？","options":["(A) 深度需較深，因要靠牙本質鍵結","(B) 寬度要較窄，以避免承受過多咬合力","(C) 修形線角應圓滑，以降低應力集中","(D) 無須為了預防蛀牙而做修形之延伸"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-44","subject":"ya3","topic":"牙體修形程序","meta":"112年第2次第44題","year":112,"session":2,"number":44,"question":"關於汞齊充填時，使用填壓器（condenser）的敘述，下列何者錯誤？","options":["(A) 球形汞齊（spherical amalgam）的充填要用較寬大的填壓器","(B) 初期填壓窩洞時，使用較寬大的填壓器能填的較緻密","(C) 使用較大的填壓器時，須使用較大的力量","(D) 較大的填壓器適用於咬合面的過度填壓（over packing）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-45","subject":"ya3","topic":"牙體修形程序","meta":"112年第2次第45題","year":112,"session":2,"number":45,"question":"汞齊填補後的雕刻（carving）與研光（burnishing）的敘述，下列何者正確？","options":["(A) pre-carve burnishing 時，應輕柔地使用小頭研光器","(B) 雕刻時先用較小的雕刀再換大的","(C) post-carve burnishing 時，應使用大頭研光器以增進邊緣完整性","(D) 雕刻時要貼著未修形的齒質修整"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-46","subject":"ya3","topic":"窩洞設計與分類","meta":"112年第2次第46題","year":112,"session":2,"number":46,"question":"在進行包覆咬頭的複雜汞齊（complex amalgam）窩洞製備時，下列何者最不適當？","options":["(A) 移除所有舊的填補物","(B) 移除所有齲齒與脆弱區域","(C) 製備出完整窩緣角（cavosurface angle）的復形物邊緣","(D) 保留脆弱的咬頭"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-47","subject":"ya3","topic":"窩洞設計與分類","meta":"112年第2次第47題","year":112,"session":2,"number":47,"question":"關於金屬鑄造體的窩洞修形，下列敘述何者錯誤？","options":["(A) 咬合面窩洞的外展與牙齒長軸的角度以 2～5 度為佳","(B) 窩洞較淺時，外展的角度需越大","(C) 頰舌側外壁的修形，須以牙釉質外緣當成修形的導引","(D) 第二類窩洞修形的軸壁及髓壁內側皆須位於牙本質"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-48","subject":"ya3","topic":"窩洞設計與分類","meta":"112年第2次第48題","year":112,"session":2,"number":48,"question":"在金屬鑄造體中，從初級外展（primary flare）延伸到臨界線角（transitional line angle）的修形設計為下列何 者？","options":["(A) 固位溝（retention groove）","(B) 窩緣斜面（cavosurface bevel）","(C) 托架溝（slot）","(D) 裙狀修形（skirting）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-49","subject":"ya3","topic":"窩洞設計與分類","meta":"112年第2次第49題","year":112,"session":2,"number":49,"question":"以瓷嵌體復形後牙，如需包覆（cap）其中一咬頭，以下敘述何者錯誤？","options":["(A) 窩洞外形大於咬頭尖（cusp tip）與主要咬合溝（primary groove）距離的三分之二時，須考慮包覆咬頭","(B) 咬頭咬合面需磨掉 1.5～2.0 mm 以增加強度","(C) 邊緣角（cavosurface angle）為 90 度","(D) 在頰舌側可以以 chamfer margin 減少齒質被磨除"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-50","subject":"ya3","topic":"複合樹脂與材料","meta":"112年第2次第50題","year":112,"session":2,"number":50,"question":"關於結構因子（C-factor）的敘述，下列何者錯誤？","options":["(A) 定義是鍵結面的數目除以未鍵結面的數目","(B) 第四級（Class IV）窩洞的 C-factor 比第一級（Class I）窩洞大","(C) 使用相同填補方式時，C-factor 越大複合樹脂聚合收縮產生的應力越大","(D) C-factor 越大，在牙髓壁（pulp floor）的鍵結破壞越可能發生"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-51","subject":"ya3","topic":"黏著與美學修復","meta":"112年第2次第51題","year":112,"session":2,"number":51,"question":"診間活齒漂白（in-office vital bleaching）與居家漂白（home-applied bleaching）所使用的藥劑，下列敘述何者 正確？","options":["(A) 診間活齒漂白使用 10～15 % 過硼酸鈉（sodium perborate）","(B) 居家漂白使用 30～35 % 過硼酸鈉（sodium perborate）","(C) 居家漂白使用 10～15 % 過氧化氫（hydrogen peroxide）","(D) 診間活齒漂白使用 30～35 % 過氧化氫（hydrogen peroxide）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-52","subject":"ya3","topic":"黏著與美學修復","meta":"112年第2次第52題","year":112,"session":2,"number":52,"question":"有關失活性牙漂白（nonvital bleaching）之敘述，下列何者錯誤？","options":["(A) 只適用於齒內治療完成的牙齒","(B) 有可能會造成齒頸部外吸收（external cervical resorption）","(C) 用 sodium perborate 可達成漂白效果","(D) 一般建議利用加熱以加速漂白"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-53","subject":"ya3","topic":"牙科解剖與生理","meta":"112年第2次第53題","year":112,"session":2,"number":53,"question":"關於口腔黏膜（oral mucosa）的部位與特性搭配，下列何者正確？","options":["(A) 舌背（dorsum of the tongue）－咀嚼黏膜（masticatory mucosa）","(B) 牙齦（gingiva）－內襯黏膜（lining mucosa）","(C) 齒槽黏膜（alveolar mucosa）－特化黏膜（specialized mucosa）","(D) 硬顎（hard palate）－咀嚼黏膜（masticatory mucosa）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-54","subject":"ya3","topic":"牙科解剖與生理","meta":"112年第2次第54題","year":112,"session":2,"number":54,"question":"游離牙齦（free gingiva）的血液供應來自下列何者？①骨膜上血管（supraperiosteal blood vessels） ②牙周韌 帶血管（blood vessels of the periodontal ligament） ③齒槽骨血管（blood vessels of the alveolar bone）","options":["(A) 僅①③","(B) 僅①②","(C) 僅②③","(D) ①②③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-55","subject":"ya3","topic":"植牙學","meta":"112年第2次第55題","year":112,"session":2,"number":55,"question":"健康狀態下，下列植體結締組織附著（connective tissue attachment）組成，何者較自然牙多？","options":["(A) 膠原纖維（collagen fiber）","(B) 造纖維細胞（fibroblast）","(C) 血管結構（vascular structure）","(D) 發炎細胞（inflammatory cell）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-56","subject":"ya3","topic":"牙周非手術治療","meta":"112年第2次第56題","year":112,"session":2,"number":56,"question":"牙根分叉（furcation）處常難以清理而導致牙齒預後（prognosis）不良，在清理牙根分叉時，器械進入 （access）下列何者最為困難？","options":["(A) 下顎第一大臼齒舌側分叉（lingual furcation）","(B) 上顎第一大臼齒遠心側分叉（distal furcation）","(C) 上顎第一大臼齒近心側分叉（mesial furcation）","(D) 上顎第一小臼齒近心遠心分叉（mesiodistal furcation）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-57","subject":"ya3","topic":"牙周疾病與診斷","meta":"112年第2次第57題","year":112,"session":2,"number":57,"question":"牙齦卟啉菌（Porphyromonas gingivalis）可延緩多形核嗜中性球（polymorphonuclear neutrophils）的滲出 （transmigration），減弱宿主對抗細菌侵襲的能力，其機制是透過抑制下列何者的生成？","options":["(A) IL-1","(B) IL-6","(C) IL-8","(D) TNFα"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-58","subject":"ya3","topic":"牙周疾病與診斷","meta":"112年第2次第58題","year":112,"session":2,"number":58,"question":"利用牙周探針進行牙周探測時，下列何者比較不是牙周探測的影響因子？","options":["(A) 牙周探針的厚度","(B) 牙周探針的材質","(C) 探測時所用的壓力","(D) 軟組織發炎細胞浸潤及伴隨膠原蛋白喪失的程度"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-59","subject":"ya3","topic":"牙周疾病與診斷","meta":"112年第2次第59題","year":112,"session":2,"number":59,"question":"依據Mallya & Lam（2019）學者提出的利用影像判斷齒槽骨喪失程度將牙周病進展分類，下列敘述何者錯 誤？","options":["(A) 達牙根長度的10%為Stage I","(B) 達牙根長度的40%為Stage II","(C) 達牙根長度的60%為Stage III","(D) 達牙根長度的80%為Stage IV"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-60","subject":"ya3","topic":"牙周疾病與診斷","meta":"112年第2次第60題","year":112,"session":2,"number":60,"question":"在2017 World Workshop公布的牙周病新分類中，Stage IV牙周炎患者相較於Stage III牙周炎患者增加的治療複 雜性（complexity）因子，下列何者錯誤？","options":["(A) 最嚴重牙位齒間臨床附連組織減少≧8 mm","(B) 因為咀嚼機能障礙需要進行重建","(C) 因為次級咬合傷害需要進行重建","(D) 剩餘牙齒少於20顆"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-61","subject":"ya3","topic":"牙周疾病與診斷","meta":"112年第2次第61題","year":112,"session":2,"number":61,"question":"在2017 World Workshop公布的牙周病新分類中，關於根管－牙周病灶（endo-periodontal lesions）的臨床分類 的敘述，下列何者錯誤？","options":["(A) 先評估是否為牙根損傷的根管－牙周病灶，需檢測牙根斷裂、牙髓腔破損、外根管吸收等牙根損傷","(B) 在牙周炎患者的根管－牙周病灶，排除牙根損傷後，依牙周破壞的程度分為Grade 1、2、3","(C) 在非牙周病患者的根管－牙周病灶，Grade 2為單一牙面存在窄而深的牙周囊袋","(D) 包含牙根損傷的根管－牙周病灶通常為無望的預後（hopeless prognosis）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-62","subject":"ya3","topic":"牙周疾病與診斷","meta":"112年第2次第62題","year":112,"session":2,"number":62,"question":"牙周疾病發展過程中，當receptor activator of NF-κB ligand（RANKL）和它的接受器RANK結合時，會發生下 列何種事件？","options":["(A) 造骨細胞凋零（apoptosis）","(B) 造骨細胞增生（proliferation）","(C) T細胞被活化（activation）","(D) 破骨細胞分化（differentiation）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-63","subject":"ya3","topic":"牙周非手術治療","meta":"112年第2次第63題","year":112,"session":2,"number":63,"question":"口腔衛生的改善並不僅是使用好的潔牙方式，還須依照個人的需求給予建議。關於潔牙的建議，下列敘述何 者錯誤？","options":["(A) 研究指出，刷牙時間與牙菌斑移除量有關，因此建議刷牙時間至少兩分鐘或更久","(B) 由於貝氏刷牙法能有效清潔齒頸部及牙齦溝，因此建議用在薄牙齦表現型（thin gingival phenotype）的病人","(C) 牙刷的使用方式以及牙膏的研磨性質對於牙齒的磨耗影響大於刷毛的軟硬度","(D) 刷牙的力道對於牙菌斑移除的效力影響不大，但用力的刷牙可能導致牙齦萎縮以及齒頸部牙根表面的楔形缺 損"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-64","subject":"ya3","topic":"牙周非手術治療","meta":"112年第2次第64題","year":112,"session":2,"number":64,"question":"關於非手術性牙周治療，下列敘述何者錯誤？","options":["(A) 使用非手術性牙周治療搭配Er:YAG雷射，尚未完全證實治療效果具有顯著差異","(B) 分四次完成牙根整平術較單次完成全口牙根整平術，治療效果顯著較佳","(C) 非手術性牙周治療的終點為牙周囊袋≦4mm且沒有探測出血（BoP）","(D) 於非手術性牙周治療後再次進行非手術性治療，在大臼齒、根叉處、角性骨缺損處，改善效果有限"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-65","subject":"ya3","topic":"牙周手術與再生","meta":"112年第2次第65題","year":112,"session":2,"number":65,"question":"上顎第一大臼齒的牙根叉侵犯以引導組織再生手術治療，下列何者手術效果最佳？","options":["(A) 近心側二級牙根叉侵犯（Class II furcation involvement）","(B) 近遠心三級牙根分叉侵犯（Class III furcation involvement）","(C) 遠心側二級牙根叉侵犯（Class II furcation involvement）","(D) 頰側二級牙根叉侵犯（Class II furcation involvement）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-66","subject":"ya3","topic":"牙周手術與再生","meta":"112年第2次第66題","year":112,"session":2,"number":66,"question":"關於牙齦切除術的敘述，下列何者錯誤？","options":["(A) 可以切除牙齦的過度增生","(B) 當有牙周骨內缺損需放置再生材料時，不適合使用此術式","(C) 需考慮角質化牙齦的切除量","(D) 以外斜面（external bevel）約60度角切除牙齦"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-67","subject":"ya3","topic":"牙周手術與再生","meta":"112年第2次第67題","year":112,"session":2,"number":67,"question":"改良式魏德曼翻瓣術（modified Widman flap procedure）的操作步驟，下列順序何者正確？①以外斜面切開 （external bevel incision）由牙齦邊緣以下2 mm處向牙骨質牙釉質交界切下 ②以齒間切開（interdental incision）去除齒間組織及牙齦邊緣組織（gingival collar） ③以牙齦溝切開（crevicular incision）向牙骨嵴切 下 ④以扇形邊內斜面切開（scalloped internal bevel incision）方式由牙齦邊緣以下0.5至1 mm處向牙骨嵴切下","options":["(A) ④③②","(B) ③④②","(C) ①②③","(D) ①③②"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-68","subject":"ya3","topic":"牙周手術與再生","meta":"112年第2次第68題","year":112,"session":2,"number":68,"question":"關於牙周整形手術（periodontal plastic surgery）的適應症，下列敘述何者錯誤？","options":["(A) 處理牙齦體積增加或者牙根覆蓋","(B) 改善齒槽骨的畸形及軟組織的美觀問題","(C) 改善因為解剖構造、或發育、或疾病所造成的牙齦、黏膜及骨頭的缺損","(D) 調整牙齒周圍而非植體周圍之牙齦的高度、質地及厚度"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-69","subject":"ya3","topic":"牙周手術與再生","meta":"112年第2次第69題","year":112,"session":2,"number":69,"question":"關於垂直切線（vertical incision）的敘述，下列何者錯誤？","options":["(A) 如果要將翻瓣（flap）往根尖置放，就必須在翻瓣雙側作垂直切線","(B) 垂直切線要延伸超過mucogingival junction進入齒槽黏膜（alveolar mucosa）","(C) 垂直切線可在頰側及舌（腭）側進行，以達到兩側翻瓣往根尖方向置放","(D) 頰側垂直切線，不可以直接切在齒間乳頭"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-70","subject":"ya3","topic":"牙周手術與再生","meta":"112年第2次第70題","year":112,"session":2,"number":70,"question":"下列何種黏膜齒齦手術（mucogingival surgery）僅適用於單一牙齒牙齦萎縮的處理？","options":["(A) 游離牙齦移植術（free gingival graft）","(B) 雙側乳突翻瓣術（double-papilla flap）","(C) 皮下結締組織移植術（subepithelial connective tissue graft）","(D) 冠向移位翻瓣術（coronally displaced flap）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-71","subject":"ya3","topic":"牙周手術與再生","meta":"112年第2次第71題","year":112,"session":2,"number":71,"question":"下列何者為引導組織再生結合骨移植材料術式之最佳臨床適應症？","options":["(A) 下顎第一大臼齒第三級根叉侵犯（furcation involvement）","(B) 上顎第一小臼齒近心側第二級根叉侵犯（furcation involvement）","(C) 下顎第二小臼齒近心側4 mm深之三壁（three-wall），且無根叉侵犯（furcation involvement）的骨內缺損","(D) 上顎第二大臼齒遠心側1 mm深之三壁（three-wall）骨內缺損結合遠心第二級根叉侵犯（furcation involvement）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-72","subject":"ya3","topic":"牙周非手術治療","meta":"112年第2次第72題","year":112,"session":2,"number":72,"question":"關於牙周維護性治療（supportive periodontal therapy）的敘述，下列何者錯誤？","options":["(A) 有抽菸的人對於定期牙周回診的順從度比沒有抽菸的人顯著來得低","(B) 牙周維護性治療的間隔越久，兩次回診間的殘餘囊袋數目會變多","(C) 若發現病人刷牙因素造成楔形缺損（wedge-shaped dental defect）時，應避免以震動（vibratory movement） 的方式刷牙","(D) 應對有探測出血（BoP）的位置及探測深度（PPD）超過4 mm的囊袋，進行洗牙（scaling）及牙根整平 （root planing）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-73","subject":"ya3","topic":"牙科解剖與生理","meta":"112年第2次第73題","year":112,"session":2,"number":73,"question":"有關慢性腎臟病（chronic kidney disease, CKD）的敘述，下列何者正確？","options":["(A) CKD是糖尿病的併發症之一，特徵是腎絲球過濾率（eGFR）＜110 mL/min/1.73m2","(B) 重症的CKD，可能由於單核細胞和巨噬細胞的功能受損，致使免疫功能不全","(C) 良好的牙菌斑控制，就能有效的改善CKD的腎臟功能特殊標記血清胱蛋白（cystatin C）數值","(D) 第二型糖尿病的牙周病處置，牙齦上清創與拋光對腎絲球過濾率（eGFR）的改善效果，與手術性療法相同"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-74","subject":"ya3","topic":"牙周非手術治療","meta":"112年第2次第74題","year":112,"session":2,"number":74,"question":"關於糖尿病病人牙周治療的敘述，下列何者正確？","options":["(A) 執行需時較久的牙周治療前，應減少飲食並維持insulin的劑量不變","(B) 病人突然意識不清、全身震顫抽搐，可能是血糖值低於60 mg/dL","(C) 病人突然有低血糖症候群病徵時，緊急狀況下應先給與insulin注射","(D) 病人血糖數據HbA1c為5.5%時，代表糖尿病的血糖值控制過低"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-75","subject":"ya3","topic":"牙周疾病與診斷","meta":"112年第2次第75題","year":112,"session":2,"number":75,"question":"關於系統性問題與牙周健康的敘述，下列何者錯誤？","options":["(A) 停經婦女仍然會因荷爾蒙改變，引起口腔黏膜與牙周組織的臨床病徵","(B) 病患有壓力或身心障礙問題時，會因cortisol增加導致免疫抑制，因而影響牙周健康","(C) 研究顯示大於65歲牙周炎患者罹患中風（stroke）的風險比小於65歲牙周炎患者會增加約3倍","(D) 美國心臟協會已確認牙周炎是冠心症（coronary heart disease）發生之相關連結因子"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-112-2-76","subject":"ya3","topic":"植牙學","meta":"112年第2次第76題","year":112,"session":2,"number":76,"question":"根據Tarnow（2003）的研究，相鄰植牙間的平均乳頭高度為多少mm？","options":["(A) ≧5 mm","(B) 4.2 mm","(C) 3.4 mm","(D) 2 mm"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-77","subject":"ya3","topic":"植牙學","meta":"112年第2次第77題","year":112,"session":2,"number":77,"question":"富含血小板的血漿（PRP）和富含白細胞和血小板的纖維蛋白（L-PRF）的差別不包括下列何者？","options":["(A) L-PRF製備簡單","(B) L-PRF有較多的纖維蛋白","(C) L-PRF製備須要抗凝劑","(D) L-PRF有較佳的骨傳導潛力（osteoconductive potential）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-78","subject":"ya3","topic":"植牙學","meta":"112年第2次第78題","year":112,"session":2,"number":78,"question":"在使用無翻瓣方式植入人工植體時，下列何者不是此術式的缺點？","options":["(A) 角化組織喪失","(B) 植牙位置不正確","(C) 開裂或開窗型骨缺陷","(D) 術後腫脹的增加"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-79","subject":"ya3","topic":"植牙學","meta":"112年第2次第79題","year":112,"session":2,"number":79,"question":"關於植牙手術中常用的再生膜，下列敘述何者錯誤？","options":["(A) 可吸收再生膜可避免為了從傷口移除所須的二次手術","(B) 膠原蛋白的再生膜是可吸收的","(C) 可吸收的再生膜維持空間的時間可長達數年","(D) 擴展的聚四氟乙烯膜（expanded polytetrafluoroethylene membrane）是不可吸收膜"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-112-2-80","subject":"ya3","topic":"植牙學","meta":"112年第2次第80題","year":112,"session":2,"number":80,"question":"關於植體周圍炎治療，下列敘述何者錯誤？","options":["(A) 欲以手術處理植體周圍炎之前，病人須先達到良好的口腔衛生控制","(B) 手術治療後，平滑表面植體在探測深度及牙齦探測出血的降低程度上比起粗糙表面植體顯著來得多","(C) 植體周圍炎手術後拍攝X光所見之骨缺損的填充（bone fill）並不能代表重新骨整合（re-osseointegration）確 實發生","(D) 當植體周圍炎發生時，非手術性治療多半無效，應直接進行手術性治療"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-1","subject":"ya3","topic":"牙髓診斷與病理","meta":"113年第1次第1題","year":113,"session":1,"number":1,"question":"下列何者不是上顎側門齒較常發生的變異形態？","options":["(A) 齒中齒（dens invaginatus）","(B) 爪型咬頭（talon cusp）","(C) 顎齦溝（palatogingival groove）","(D) 牛型齒（taurodontism）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-2","subject":"ya3","topic":"牙髓診斷與病理","meta":"113年第1次第2題","year":113,"session":1,"number":2,"question":"在正常牙髓組織中原本就存在可以抵抗齲齒細菌的免疫細胞為下列何者？","options":["(A) 巨噬細胞（macrophage），樹狀突細胞（dendritic cell），T淋巴細胞（T lymphocyte）","(B) 樹狀突細胞（dendritic cell），巨噬細胞（macrophage），嗜中性白血球（neutrophil）","(C) 巨噬細胞（macrophage），嗜中性白血球（neutrophil），肥大細胞（mast cell），樹狀突細胞 （dendritic cell），T淋巴細胞（T lymphocyte）","(D) 樹狀突細胞（dendritic cell），巨噬細胞（macrophage），T淋巴細胞（T lymphocyte），嗜中性白血球 （neutrophil）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-3","subject":"ya3","topic":"牙髓診斷與病理","meta":"113年第1次第3題","year":113,"session":1,"number":3,"question":"有關牙本質與牙髓組織內神經分布的敘述，下列何者正確？","options":["(A) 牙本質小管內液體的流動可刺激A-δ神經纖維，引起尖銳痛或刺痛","(B) 引發C神經纖維衝動的閾值比引發A-δ神經纖維衝動的閾值低","(C) A-β神經纖維是A神經纖維中傳導速度最快者，負責本體感覺","(D) C神經纖維主要分布於牙本質與牙髓交接處，傳導速度較A神經纖維慢"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-4","subject":"ya3","topic":"牙髓診斷與病理","meta":"113年第1次第4題","year":113,"session":1,"number":4,"question":"根尖周圍炎的感染是一種微生物和宿主的競爭，下列何者屬於微生物的攻擊力？","options":["(A) 抑制吞噬作用及溶酶體（lysosomal）功能","(B) 具物理障礙的表面","(C) 激活補體系統","(D) 適應性免疫（adaptive immune）反應"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-5","subject":"ya3","topic":"牙髓診斷與病理","meta":"113年第1次第5題","year":113,"session":1,"number":5,"question":"根尖周圍炎在X光片上常可以觀察到因為骨吸收而形成的根尖病灶，其骨缺失主要是由下列何種細胞引起？","options":["(A) 噬骨細胞（osteoclasts）","(B) 造骨細胞（osteoblasts）","(C) 毀牙骨質細胞（cementoclasts）","(D) 破齒質細胞（odontoclasts）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-6","subject":"ya3","topic":"牙周疾病與診斷","meta":"113年第1次第6題","year":113,"session":1,"number":6,"question":"cementum是礦化無血管的結締組織，可分為三類，下列那一類位在靠根尖一半的牙根上？","options":["(A) 無細胞及無纖維牙骨質（acellular afibrillar cementum）","(B) 無細胞及有外在纖維牙骨質（acellular extrinsic fiber cementum）","(C) 有細胞及有內在纖維牙骨質（cellular intrinsic fiber cementum）","(D) 有細胞及有外在纖維牙骨質（cellular extrinsic fiber cementum）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-7","subject":"ya3","topic":"根管治療程序","meta":"113年第1次第7題","year":113,"session":1,"number":7,"question":"下圖左側X光片為正照，右側X光片為近心往遠心拍攝，依據Weine的分類定義，右上第二小臼齒的根管形態屬 於第幾型？而根管內疑似有分離器械（separated instrument）情況的是那個根管？","options":["(A) 第二型根管形態，頰側根管","(B) 第二型根管形態，腭側根管","(C) 第四型根管形態，頰側根管","(D) 第四型根管形態，腭側根管"],"answer":1,"image":"ya3-113-1-7.jpeg","clinical_level":"一般"},{"id":"ya3-113-1-8","subject":"ya3","topic":"牙齒外傷處理","meta":"113年第1次第8題","year":113,"session":1,"number":8,"question":"關於暫時性根尖牙周破壞（transient apical breakdown），下列敘述何者錯誤？","options":["(A) 發生在剛受過外傷的牙齒","(B) 牙齒會變色但可恢復過來","(C) 牙齒會變色並且不可能恢復過來","(D) 牙齒根尖可看到放射線透射度（radiolucency）的病徵"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-9","subject":"ya3","topic":"牙齒外傷處理","meta":"113年第1次第9題","year":113,"session":1,"number":9,"question":"牙齒沒有產生位移、對敲診及觸診敏感、有比正常更大的搖動情形、牙齦溝滲血、牙髓測試正常，但有時候 在初診時沒有反應。以上敘述為何種牙齒脫位？","options":["(A) 震盪（concussion）","(B) 半脫位（subluxation）","(C) 側向脫位（lateral luxation）","(D) 外脫位（extrusive luxation）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-10","subject":"ya3","topic":"牙齒外傷處理","meta":"113年第1次第10題","year":113,"session":1,"number":10,"question":"牙齒外傷造成的取代性牙根外吸收（external replacement root resorption），下列敘述何者錯誤？","options":["(A) 臨床檢查時，牙齒無動搖，敲診呈現金屬聲音","(B) 在青少年時期會與鄰牙咬合切面有落差，呈現低位咬合（infraocclusion）","(C) 無法藉根管治療及根管內長期置放氫氧化鈣來抑制吸收的進行","(D) X光影像上，牙根吸收處仍可見到牙周韌帶"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-11","subject":"ya3","topic":"根管器械","meta":"113年第1次第11題","year":113,"session":1,"number":11,"question":"使用下列何組器械在擴大根管時，因更換器械號數所產生的體積改變比率最高？","options":["(A) K-file #8 擴大到 #10","(B) K-file #10 擴大到 #15","(C) K-file #15 擴大到 #20","(D) K-file #45 擴大到 #50"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-12","subject":"ya3","topic":"根管器械","meta":"113年第1次第12題","year":113,"session":1,"number":12,"question":"關於蓋氏鑿鑽（Gates-Glidden drill）的敘述，下列何者錯誤？","options":["(A) 共有六個號數，有不鏽鋼及鎳鈦合金製品","(B) 前端有卵圓形安全導引頭（safty tip），可用來導引鑿鑽","(C) 主要是用來擴大根管的冠部以及較筆直的部分","(D) 使用方法是向下施力切削進入狹窄管腔內迅速擴大狹窄管腔"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-13","subject":"ya3","topic":"牙科解剖與生理","meta":"113年第1次第13題","year":113,"session":1,"number":13,"question":"下列常被使用的止痛藥物，何者的作用機轉，最不可能是抑制環氧合酶（cyloxygenase, COX）？","options":["(A) Acetaminophen","(B) Ibuprofen","(C) Diclofenac","(D) Ketorolac"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-14","subject":"ya3","topic":"根管治療程序","meta":"113年第1次第14題","year":113,"session":1,"number":14,"question":"下列那個牙位C形根管（C-shaped canals）的發生機率最低？","options":["(A) 下顎第二大臼齒（mandibular second molar）","(B) 上顎第一大臼齒（maxillary first molar）","(C) 下顎第一小臼齒（mandibular first premolar）","(D) 上顎第一小臼齒（maxillary first premolar）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-15","subject":"ya3","topic":"根管器械","meta":"113年第1次第15題","year":113,"session":1,"number":15,"question":"使用電子式根尖定位器（electronic apex locator）測量根管操作長度的敘述，下列何者正確？","options":["(A) 根管中殘留有活髓或壞死牙髓組織會影響其準確度","(B) 有研究顯示此儀器會干擾心律調節器（pacemaker）的作用，此類病患不可使用","(C) 準確度高，因此單獨以此方法確認工作長度即可","(D) 第三代雙周波的根尖定位器較不受沖洗溶液中電解質的影響"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-16","subject":"ya3","topic":"根管器械","meta":"113年第1次第16題","year":113,"session":1,"number":16,"question":"操作無翼（wingless）的蝴蝶形橡皮障夾（butterfly clamp）No.212時，建議使用以下那一種橡皮障的置 放方法？","options":["(A) 橡皮障夾、橡皮障及支架一起置放","(B) 先放橡皮障夾，其次橡皮障，最後放支架","(C) 橡皮障夾及橡皮障一起置放，最後放支架","(D) 橡皮障及支架一起置放，最後放橡皮障夾"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-17","subject":"ya3","topic":"根管治療程序","meta":"113年第1次第17題","year":113,"session":1,"number":17,"question":"下列何者可達到有效的馬來膠針（gutta-percha cone, GP cone）消毒？","options":["(A) 浸泡5.25%NaOCl溶液30秒","(B) 浸泡5.25%NaOCl溶液1分鐘","(C) 浸泡70%酒精溶液30秒","(D) 浸泡70%酒精溶液1分鐘"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-18","subject":"ya3","topic":"牙髓診斷與病理","meta":"113年第1次第18題","year":113,"session":1,"number":18,"question":"一般而言，上顎恆牙第一大臼齒有幾個牙髓角（pulp horn）？","options":["(A) 1個","(B) 2個","(C) 3個","(D) 4個"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-19","subject":"ya3","topic":"根尖手術與再治療","meta":"113年第1次第19題","year":113,"session":1,"number":19,"question":"有關根尖手術的敘述，下列何者錯誤？","options":["(A) 根尖切除後之斷面，理論上要和牙齒牙根的長軸（long axis）垂直較佳","(B) 進行根尖切除術時，一般建議移除3 mm的牙根尖","(C) mineral trioxide aggregate（MTA）可用來做根尖逆充填（retrograde filling）的材料","(D) ferric sulfate是很好的止血劑，在根尖手術時應充分使用"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-20","subject":"ya3","topic":"牙科解剖與生理","meta":"113年第1次第20題","year":113,"session":1,"number":20,"question":"關於手術治療時傷口癒合（wound healing）的敘述，下列何者錯誤？","options":["(A) 巨噬細胞（macrophages）於發炎後期（late inflammation）出現，負責傷口的消毒（decontamination）","(B) 纖維母細胞（fibroblasts）於增生期（proliferative phase）初期，會先分泌製作第一型膠原蛋白 （type I collagen）","(C) 上皮屏障（epithelial barrier）通常在傷口縫合後36～42小時後形成","(D) 牙骨質形成（cementogenesis）通常於根尖切除（root-end resection）12天後開始形成"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-21","subject":"ya3","topic":"根尖手術與再治療","meta":"113年第1次第21題","year":113,"session":1,"number":21,"question":"病人求診主訴為右下顎小臼齒區咬痛，右下顎第二小臼齒經診斷為已根管治療，症狀型根尖周圍炎 （previously treated, symptomatic apical periodontitis）。放射線影像如圖示。其治療計畫何者較為 適當？","options":["(A) 可能為多根管牙齒，根管充填品質不良且有可能漏失根管，以非手術性根管治療為優先選項","(B) 牙根尖膨大，可能為多根管牙齒，非手術性根管治療預後不佳，直接根尖手術治療較為適當","(C) 牙根尖膨大側支根管多，以牙齒再植手術，根尖切除並逆充填MTA效率較佳","(D) 牙根膨大，可能為C型根管，預後不佳，建議直接拔除"],"answer":0,"image":"ya3-113-1-21.jpeg","clinical_level":"一般"},{"id":"ya3-113-1-22","subject":"ya3","topic":"根尖手術與再治療","meta":"113年第1次第22題","year":113,"session":1,"number":22,"question":"若重做根管病例，其根管內充填物是硬黏合劑（hard cement），在去除舊有充填材料時，下列敘述何者錯 誤？","options":["(A) 使用超音波器械（ultrasonic instrument）前先試用溶劑","(B) 治療中常需加照X光，協助了解狀況","(C) 治療前與病人討論穿孔或器械斷裂的可能性是不必要的","(D) 轉診專科醫師是明智的"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-23","subject":"ya3","topic":"牙髓診斷與病理","meta":"113年第1次第23題","year":113,"session":1,"number":23,"question":"病人左下第二小臼齒活髓測試無反應，第一大臼齒為做過根管治療的牙齒，兩顆牙齒的牙周囊袋都深入到牙 根尖，X光影像如圖示，此診斷為下列那一種牙髓－牙周病灶？","options":["(A) 原發性牙周病灶（primary periodontal lesions）","(B) 原發性牙周病灶，繼發性牙髓病灶（primary periodontal lesions with secondary endodontic involvement）","(C) 真正的合併病灶（true combined lesions）","(D) 伴隨的牙髓和牙周病灶（concomitant pulpal and periodontal lesions）"],"answer":2,"image":"ya3-113-1-23.jpeg","clinical_level":"一般"},{"id":"ya3-113-1-24","subject":"ya3","topic":"根尖手術與再治療","meta":"113年第1次第24題","year":113,"session":1,"number":24,"question":"下列何者不是牙根切除術（root resection）的適應症？","options":["(A) 牙根融合（root fusion）","(B) 牙根斷裂","(C) 無法根管治療的牙根","(D) 嚴重的 II 級或 III 級牙根分叉病變"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-25","subject":"ya3","topic":"牙齒外傷處理","meta":"113年第1次第25題","year":113,"session":1,"number":25,"question":"關於牙髓內出血造成牙齒變色的敘述，下列何者錯誤？","options":["(A) 通常與牙齒受外力撞擊有關","(B) 變色程度與牙髓內出血持續時間有關","(C) 牙齒撞擊造成的變色，即使牙髓存活，變色仍然存在","(D) 與硫化鐵積聚有關，齒內漂白（internal bleaching）有良好的效果"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-26","subject":"ya3","topic":"醫學倫理與法規","meta":"113年第1次第26題","year":113,"session":1,"number":26,"question":"關於根管治療的知情同意（informed consent），下列敘述何者錯誤？","options":["(A) 必須以非專業語言（Layperson’s language）跟病患說明","(B) 不可由前台工作人員單獨為病患進行說明及簽署同意書","(C) 知情同意只能在治療之前進行","(D) 必須告知病患替代治療或選項（alternative therapies or options）的優缺點"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-27","subject":"ya3","topic":"牙科解剖與生理","meta":"113年第1次第27題","year":113,"session":1,"number":27,"question":"牙髓腔內那一種神經纖維被活化最可能造成牙齒刺痛（sharp pain）感覺？","options":["(A) A fiber","(B) A-β fiber","(C) A-δ fiber","(D) C fiber"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-28","subject":"ya3","topic":"牙周非手術治療","meta":"113年第1次第28題","year":113,"session":1,"number":28,"question":"下列有關氯己定（chlorhexidine）漱口水的敘述何者錯誤？","options":["(A) 氯己定是一種廣效性制菌劑","(B) 長期使用會造成味覺變苦","(C) 應避免同時使用含月桂硫酸鈉（sodium laurel sulfate）的牙膏","(D) 在高齲齒病人，建議使用濃度為5% chlorhexidine gluconate 溶液"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-29","subject":"ya3","topic":"牙髓診斷與病理","meta":"113年第1次第29題","year":113,"session":1,"number":29,"question":"關於牙釉質齲齒（enamel caries）的敘述，下列何者錯誤？","options":["(A) 當齲齒病灶只侷限在牙釉質時，牙髓細胞不會產生發炎反應","(B) 當牙釉質齲齒還未形成窩洞（noncavitated）時，可以藉由再礦化停止病變","(C) 當咬翼X光片發現鄰接面齲齒病灶時，牙釉質表面仍可能完整","(D) 鄰接面牙釉質齲齒的放射線影像呈現錐形，其尖端朝向牙釉質及牙本質交接面"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-30","subject":"ya3","topic":"牙髓診斷與病理","meta":"113年第1次第30題","year":113,"session":1,"number":30,"question":"利用electric pulp tester測量牙髓活性時，若數值很高病人才有反應，應非下列何種原因造成？","options":["(A) 牙齒過度敏感","(B) 牙髓局部壞死","(C) 過厚的修復性牙本質（reparative dentin）","(D) 牙齒與測量儀器接觸不良"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-31","subject":"ya3","topic":"窩洞設計與分類","meta":"113年第1次第31題","year":113,"session":1,"number":31,"question":"齲齒經檢查完成初步處置及制定治療計畫，屬於下列那一個階段？","options":["(A) 控制期（control phase）","(B) 再評估期（re-evaluation phase）","(C) 執行期（definitive phase）","(D) 維持期（maintenance phase）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-32","subject":"ya3","topic":"黏著與美學修復","meta":"113年第1次第32題","year":113,"session":1,"number":32,"question":"牙齒結構的無機成分（羥基磷灰石）與牙科樹脂的共價化學鍵合，屬於何種黏著的機制？","options":["(A) 機械（mechanical）","(B) 吸附（adsorption）","(C) 擴散（diffusion）","(D) 靜電（electrostatic）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-33","subject":"ya3","topic":"黏著與美學修復","meta":"113年第1次第33題","year":113,"session":1,"number":33,"question":"奈米滲漏（nanoleakage）有斑點圖案（spotted pattern）與水樹（water tree）兩種型態，下列敘述何者 錯誤？","options":["(A) 斑點圖案的奈米滲漏通常發生於使用自酸蝕黏著劑","(B) 這些圖案可由硝酸銀染料滲透顯示","(C) 斑點圖案的奈米滲漏通常出現在混合層","(D) 水樹型態的奈米滲漏是由於樹脂不完全滲透混合層造成"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-34","subject":"ya3","topic":"黏著與美學修復","meta":"113年第1次第34題","year":113,"session":1,"number":34,"question":"關於牙釉質的黏著，下列敘述何者錯誤？","options":["(A) 目前大多數磷酸凝膠的濃度為30%至40%，最常見的是37%","(B) 15秒與60秒酸蝕導致的牙釉質表面粗糙度相似","(C) 複合樹脂與磷酸酸蝕後的牙釉質間的剪力黏著強度（shear bond strength）通常不會超過 20 MPa","(D) 15秒與60秒酸蝕導致的牙釉質黏著強度相似"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-35","subject":"ya3","topic":"根管器械","meta":"113年第1次第35題","year":113,"session":1,"number":35,"question":"關於橡皮障框（rubber dam frame）的敘述，下列何者錯誤？","options":["(A) 金屬橡皮障框（metal frame）可以高溫消毒","(B) Young型的橡皮障框多為環型設計","(C) 塑膠橡皮障框（plastic frame）為輻射線可穿透（radiolucent）","(D) 塑膠橡皮障框（plastic frame）使用壽命較金屬橡皮障框（metal frame）短"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-36","subject":"ya3","topic":"窩洞設計與分類","meta":"113年第1次第36題","year":113,"session":1,"number":36,"question":"在近心－咬合面窩洞修形（MO cavity preparation）中，下列何者不存在？","options":["(A) 近心壁（mesial wall）","(B) 遠心壁（distal wall）","(C) 頰側壁（buccal wall）","(D) 舌側壁（lingual wall）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-37","subject":"ya3","topic":"複合樹脂與材料","meta":"113年第1次第37題","year":113,"session":1,"number":37,"question":"下列何者為牙齒內主要與樹脂材料產生化學鍵結的有機質？","options":["(A) 第一類膠原蛋白（type Ⅰ collagen）","(B) 第二類膠原蛋白（type Ⅱ collagen）","(C) 第三類膠原蛋白（type Ⅲ collagen）","(D) 第四類膠原蛋白（type Ⅳ collagen）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-38","subject":"ya3","topic":"複合樹脂與材料","meta":"113年第1次第38題","year":113,"session":1,"number":38,"question":"複合樹脂填補過程中，下列那種牙材最適合作為襯底（liner）材料，以保護牙髓？","options":["(A) 聚羧酸鹽黏合劑（polycarboxylate cement）","(B) 氫氧化鈣（calcium hydroxide）","(C) 氧化鋅丁香油酚（ZOE）","(D) 磷酸鋅黏合劑（zinc phosphate cement）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-39","subject":"ya3","topic":"複合樹脂與材料","meta":"113年第1次第39題","year":113,"session":1,"number":39,"question":"下列何種器械適用於複合樹脂填補的凹面（concave surface）完成（finishing）？①flexible discs ②finishing strips ③finishing cups ④finishing points","options":["(A) ①②","(B) ③④","(C) ①③","(D) ②④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-40","subject":"ya3","topic":"黏著與美學修復","meta":"113年第1次第40題","year":113,"session":1,"number":40,"question":"關於牙齒比色的敘述，下列何者錯誤？","options":["(A) 牙齒比色應在使用橡皮障隔離口腔其他組織後進行","(B) 將比色板依據明度（value）來排列，可使比色變得更容易","(C) 最適合的光源是色溫5,500 K，亮度1,000～1,500流明（lux）","(D) 使用VITA 3D Master比色板時，應優先選擇亮度（lightness）"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-41","subject":"ya3","topic":"牙體修形程序","meta":"113年第1次第41題","year":113,"session":1,"number":41,"question":"關於bitine ring（如下圖）的敘述，下列何者錯誤？","options":["(A) 建議在黏著處理前先放置好圍合片","(B) 圍合片不可超過窩洞牙齦緣1 mm以上","(C) 圍合片僅需輕微研光（light burnishing）","(D) 可搭配預先放置木楔（prewedging）製備窩洞"],"answer":1,"image":"ya3-113-1-41.jpeg","clinical_level":"一般"},{"id":"ya3-113-1-42","subject":"ya3","topic":"複合樹脂與材料","meta":"113年第1次第42題","year":113,"session":1,"number":42,"question":"關於樹脂溝隙封劑（resin sealants）的敘述，下列何者錯誤？","options":["(A) 每年以5～10%的速度失效","(B) 機械固位性（mechanical retention）比樹脂修飾玻璃離子溝隙封劑高","(C) 在酸蝕後，直接使用溝隙封劑較搭配黏著劑（bonding agent）使用，有較深的浸潤（penetration）","(D) 流動性樹脂亦可做為溝隙封劑使用"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-43","subject":"ya3","topic":"牙體修形程序","meta":"113年第1次第43題","year":113,"session":1,"number":43,"question":"關於第二類汞齊填補時使用木楔（wedge）的敘述，下列何者錯誤？","options":["(A) 木楔放置高度為牙齦緣（gingival margin）下","(B) 上顎第一小臼齒近心側牙根呈凸面（convex），木楔和牙齒的貼合度良好","(C) 一個溝隙（embrasure）可放置兩個木楔","(D) 可使用刀片來調整木楔的形狀"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-44","subject":"ya3","topic":"牙體修形程序","meta":"113年第1次第44題","year":113,"session":1,"number":44,"question":"在進行汞齊填補使用固位釘（pin），有時會需要彎折（bend）釘柱（如下圖），關於彎折的敘述，下列何 者錯誤？","options":["(A) spoon excavator不可以被使用來進行固位釘的彎折","(B) 彎折時可能造成牙本質斷裂","(C) 彎折是為了搭配牙根外型","(D) 可利用The Thread Mate System（TMS）bending tool建立固位釘彎折的支點"],"answer":2,"image":"ya3-113-1-44.jpeg","clinical_level":"一般"},{"id":"ya3-113-1-45","subject":"ya3","topic":"窩洞設計與分類","meta":"113年第1次第45題","year":113,"session":1,"number":45,"question":"在進行汞齊填補窩洞製備時，汞齊需要有一定的厚度，且剩餘的齒質也需要有足夠的強度以支持復形物，是 屬於何種設計應遵循的原則？","options":["(A) outline form","(B) retention form","(C) resistance form","(D) convenience form"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-46","subject":"ya3","topic":"窩洞設計與分類","meta":"113年第1次第46題","year":113,"session":1,"number":46,"question":"在下列何種情形下，窩洞修形時應考慮使用覆嵌（onlay）或其他冠外修復體（extracoronal restoration）來保護咬頭？","options":["(A) 寬度為頰-舌咬頭間距離的1/2","(B) 寬度為1 mm","(C) 寬度為咬頭至中央溝寬度的1/3","(D) 寬度為頰-舌咬頭間距離的1/4"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-47","subject":"ya3","topic":"窩洞設計與分類","meta":"113年第1次第47題","year":113,"session":1,"number":47,"question":"關於製備瓷或樹脂嵌體的原則，下列敘述何者正確？","options":["(A) 應在鄰接盒（proximal box）製備固位溝（retentive groove）以增加固位","(B) 修形的邊緣應儘量置放在牙齦以上","(C) 修形的咬合邊緣（occlusal margin）應製備斜面（bevel）","(D) 窩洞的內角應呈直角以增加抗力型"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-48","subject":"ya3","topic":"黏著與美學修復","meta":"113年第1次第48題","year":113,"session":1,"number":48,"question":"使用樹脂黏合劑黏著陶瓷嵌體的敘述，下列何者錯誤？","options":["(A) 酸蝕後的牙本質可以chlorhexidine再濕潤","(B) 陶瓷嵌體內面應以氫氟酸（hydrofluoric acid）處理","(C) 應使用光聚合，三步驟酸蝕及沖洗（light-cured, three-step etch-and-rinse）黏合劑系統","(D) 牙本質酸蝕15秒，牙釉質酸蝕30秒"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-49","subject":"ya3","topic":"牙體修形程序","meta":"113年第1次第49題","year":113,"session":1,"number":49,"question":"取模製作覆嵌（onlay）時，使用排齦線（retraction cord）的敘述，下列何者錯誤？","options":["(A) 窩洞邊緣在牙齦下方位置，需要使用排齦線","(B) 目的是加寬牙齦溝","(C) 讓足夠的取模材料流入牙齦下方","(D) 含腎上腺素的排齦線，使用上沒有禁忌症"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-50","subject":"ya3","topic":"黏著與美學修復","meta":"113年第1次第50題","year":113,"session":1,"number":50,"question":"下列何者不是牙齒外染性變色（extrinsic discoloration）的原因？","options":["(A) 吃檳榔","(B) 喝咖啡","(C) 外傷","(D) 殘留的Nasmyth membrane"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-51","subject":"ya3","topic":"黏著與美學修復","meta":"113年第1次第51題","year":113,"session":1,"number":51,"question":"關於walking bleaching的敘述，下列何者正確？①療程結束後一到二週才可進行樹脂填補 ②牙根內吸收 為常見的併發症 ③療程結束後在牙髓腔放置氫氧化鈣主要是為了減少美白劑對樹脂黏著的干擾 ④使用加 熱的過氧化氫（hydrogen peroxide）以加速美白效果","options":["(A) 僅①","(B) 僅③","(C) 僅①②③","(D) ①②③④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-52","subject":"ya3","topic":"黏著與美學修復","meta":"113年第1次第52題","year":113,"session":1,"number":52,"question":"有關活齒（vital tooth）醫師處方居家美白與診間美白（in-office bleaching）的差異，下列敘述何者錯 誤？","options":["(A) 診間美白常使用30%～35%過氧化氫（hydrogen peroxide）","(B) 居家美白常使用10%～15%碳醯胺過氧化物（carbamide peroxide）","(C) 居家美白需要製作美白牙托","(D) 居家美白藥劑接觸時間較短"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-53","subject":"ya3","topic":"牙科解剖與生理","meta":"113年第1次第53題","year":113,"session":1,"number":53,"question":"牙骨質（cementum）種類與位置的配對，下列何者錯誤？","options":["(A) 無細胞無纖維性牙骨質（acellular afibrillar cementum）－牙釉質靠近齒頸部","(B) 無細胞外纖維性牙骨質（acellular extrinsic fiber cementum）－根尖三分之一","(C) 有細胞混合性分層牙骨質（cellular mixed stratified cementum）－牙根分叉","(D) 有細胞內纖維性牙骨質（cellular intrinsic fiber cementum）－吸收腔隙（resorption lacunae）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-54","subject":"ya3","topic":"牙科解剖與生理","meta":"113年第1次第54題","year":113,"session":1,"number":54,"question":"發炎前期產生的Interleukin-8，其主要作用於何種細胞？","options":["(A) 漿細胞（plasma cells）","(B) T淋巴細胞（T lymphocytes）","(C) 嗜中性白血球（neutrophils）","(D) 內皮細胞（endothelial cells）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-55","subject":"ya3","topic":"牙科解剖與生理","meta":"113年第1次第55題","year":113,"session":1,"number":55,"question":"硬腭黏膜與頰黏膜的不同處包含下列何者？①keratinized stratified squamous epithelium覆蓋 ②較為 偏紅色（redder） ③具明顯的epithelial ridges","options":["(A) 僅①","(B) ①②","(C) ②③","(D) ①③"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-56","subject":"ya3","topic":"牙周疾病與診斷","meta":"113年第1次第56題","year":113,"session":1,"number":56,"question":"如果有兩位病人，分別為60歲及40歲，檢查後發現他們剩下的結締組織附連（connective tissue attachment）及齒槽骨狀況相近，對於預後（prognosis）而言，下列那一敘述最適當？","options":["(A) 60歲病人一般預後較好，因為其平均餘命較短","(B) 60歲病人一般預後較好，因為40歲病人牙周破壞的平均速度較快","(C) 40歲病人一般預後較好，因為其癒合能力較佳","(D) 40歲病人一般預後較好，因為其清潔口腔能力較佳"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-57","subject":"ya3","topic":"牙周疾病與診斷","meta":"113年第1次第57題","year":113,"session":1,"number":57,"question":"當牙齒生物膜（dental biofilm）形成過程中，結合到後天性薄膜（acquired pellicle）的主要是那類細 菌？","options":["(A) 葡萄球菌屬（Staphylococcus）","(B) 奈瑟氏球菌屬（Neisseria）","(C) 鏈球菌屬（Streptococcus）","(D) 普雷沃氏菌屬（Prevotella）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-58","subject":"ya3","topic":"牙周疾病與診斷","meta":"113年第1次第58題","year":113,"session":1,"number":58,"question":"對牙齦卟啉菌（P. gingivalis, Pg）脂多醣（lipopolysaccharide, LPS）的敘述，下列何者最不適當？","options":["(A) Pg LPS為病原相關分子模式（pathogen-associated molecular patterns, PAMP）","(B) Pg LPS活化類鐸受體-2（toll-like receptor-2, TLR-2）","(C) Pg LPS增加介白質-12（IL-12）的產生","(D) Pg LPS引發強烈的Th2細胞反應"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-59","subject":"ya3","topic":"牙周疾病與診斷","meta":"113年第1次第59題","year":113,"session":1,"number":59,"question":"在牙齦溝液（gingival crevicular fluid）中的主要抗微生物肽（antimicrobial peptides）為下列何 者？","options":["(A) α-defensins","(B) β-defensins","(C) θ-defensins","(D) cathelicidins"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-60","subject":"ya3","topic":"牙周疾病與診斷","meta":"113年第1次第60題","year":113,"session":1,"number":60,"question":"有關牙齦探測流血（bleeding on probing, BoP）的敘述，下列何者錯誤？","options":["(A) 評估BoP趨勢可以正確診斷牙齦組織發炎","(B) BoP與牙齦溝或牙周囊袋底部存在發炎細胞浸潤相關","(C) BoP檢測的陽性預測值高，為牙周破壞的重要指標","(D) BoP檢測的陰性預測值高，為牙周穩定的重要指標"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-61","subject":"ya3","topic":"牙周疾病與診斷","meta":"113年第1次第61題","year":113,"session":1,"number":61,"question":"在2017 World Workshop公布的牙周病新分類中，下列何者不是用來區分Stage II與Stage III患者預期牙周 炎治療複雜性（complexity）因子？","options":["(A) 最嚴重牙位齒間臨床附連喪失≧6 mm","(B) 垂直骨缺損≧3 mm","(C) 存在Class II or III牙根分叉處侵犯","(D) 中等程度齒槽嵴缺損"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-62","subject":"ya3","topic":"牙周疾病與診斷","meta":"113年第1次第62題","year":113,"session":1,"number":62,"question":"在2017 World Workshop公布的牙周病新分類中，關於評估牙周炎級別（Grade）的危險因子（risk factors）之定義，下列敘述何者錯誤？","options":["(A) 調節級別的危險因子為抽菸、糖尿病","(B) Grade A：無抽菸、或從未被診斷為糖尿病之患者","(C) Grade B：每天抽菸＜10支、或糖化血色素（HbA1c）＜6.5的糖尿病之患者","(D) Grade C：每天抽菸≧10支、或糖化血色素（HbA1c）≧7的糖尿病之患者"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-63","subject":"ya3","topic":"牙周非手術治療","meta":"113年第1次第63題","year":113,"session":1,"number":63,"question":"關於齒齦下清創（subgingival debridement）之後的牙周囊袋細菌學變化，下列敘述何者正確？","options":["(A) 總細菌數因為不同菌種彼此消長，沒有顯著改變","(B) 喜氧的鏈球菌與桿菌總數量顯著增加","(C) 口腔衛生不佳者，最快數週後又會回復治療前的菌態","(D) Porphyromonas gingivalis的平均數量沒有顯著改變"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-64","subject":"ya3","topic":"牙周非手術治療","meta":"113年第1次第64題","year":113,"session":1,"number":64,"question":"下列何種患者尚未被證明使用電動牙刷可獲得口腔衛生的改善？","options":["(A) 兒童和青少年","(B) 住院患者，包括需要清潔牙齒的老年人","(C) 慢性牙周炎患者","(D) 矯正患者"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-65","subject":"ya3","topic":"牙周手術與再生","meta":"113年第1次第65題","year":113,"session":1,"number":65,"question":"下列何者為牙齦切除術的適應症？","options":["(A) 上顎前牙微笑露齦（gummy smile），角質化牙齦寬度為1 mm","(B) 下顎第一小臼齒齲齒延伸至齒槽骨嵴，需露出齲齒邊緣","(C) 上顎第一小臼齒牙齒斷裂延伸至齒槽骨嵴，需露出牙齒斷裂處","(D) 藥物引起的牙齦增大（gingival enlargement）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-66","subject":"ya3","topic":"牙周手術與再生","meta":"113年第1次第66題","year":113,"session":1,"number":66,"question":"關於牙釉基質衍生物（enamel matrix derivatives）的敘述，下列何者錯誤？","options":["(A) 為取自豬的含牙釉基質蛋白的酸性萃取物","(B) 為凝膠狀物質","(C) 必須合併骨粉使用","(D) 先以EDTA處理的目的是為了去除塗抹層（smear layer）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-67","subject":"ya3","topic":"牙周手術與再生","meta":"113年第1次第67題","year":113,"session":1,"number":67,"question":"關於牙周手術前準備，下列敘述何者錯誤？","options":["(A) 停止抽菸3到4個星期","(B) 給與非類固醇消炎止痛藥（NSAID）","(C) 簽署手術同意書","(D) 當收縮壓大於110毫米汞柱時，不建議進行手術"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-68","subject":"ya3","topic":"牙周手術與再生","meta":"113年第1次第68題","year":113,"session":1,"number":68,"question":"關於牙根覆蓋術（root coverage）的敘述，下列何者錯誤？","options":["(A) 無論使用全皮層瓣（full-thickness flap）或蒂狀瓣（pedicle graft），都不會影響其結果","(B) 手術前須先清除牙根面上之結石及牙菌斑","(C) Miller氏分類Class II及Class III可以達到完全的牙根覆蓋術","(D) 手術方法主要分成兩類，即為蒂狀瓣（pedicle graft）移植及游離軟組織移植（free gingival graft）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-69","subject":"ya3","topic":"牙周手術與再生","meta":"113年第1次第69題","year":113,"session":1,"number":69,"question":"關於牙齦切除術後，牙周組織癒合的敘述，下列何者正確？","options":["(A) 結締組織完全修復大約需要8週","(B) 傷口表面完成上皮化通常需要3到4天","(C) 在術後12到24小時，傷口邊緣的上皮細胞就開始向傷口處移動","(D) 上皮完全的修復大約需要14天的時間"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-70","subject":"ya3","topic":"牙周疾病與診斷","meta":"113年第1次第70題","year":113,"session":1,"number":70,"question":"關於牙根與分叉侵犯的敘述，下列何者錯誤？","options":["(A) 牙根幹（root trunk）會影響治療方式的選擇","(B) 牙釉突起（enamel projections）盛行率，在上、下顎第一大臼齒最高","(C) 特別長的牙根幹或融合牙根的牙齒，當根叉暴露時，不適合作手術治療","(D) 長的牙根及短的牙根幹的牙齒，適合做手術並符合功能的需求"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-71","subject":"ya3","topic":"牙周疾病與診斷","meta":"113年第1次第71題","year":113,"session":1,"number":71,"question":"病人在牙周病治療完成後，牙齦探測流血比例（BoP%）為21%，有7個超過5 mm的牙周囊袋，缺失3顆牙，齒 槽骨喪失百分比與年紀的比例關係（BL%/Age）是0.9，沒有系統性疾病，沒有抽菸的習慣，若依學者Lang & Tonetti提出的功能性圖（functional diagram），此病人屬於何種類別？","options":["(A) 低風險（low-risk）","(B) 中度風險（medium-risk）","(C) 高風險（high-risk）","(D) 嚴重風險（severe-risk）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-72","subject":"ya3","topic":"牙科解剖與生理","meta":"113年第1次第72題","year":113,"session":1,"number":72,"question":"關於慢性阻塞性肺病（chronic obstructive pulmonary disease, COPD）與牙周病關聯的研究，下列敘述 何者錯誤？","options":["(A) 罹患COPD的患者，有較嚴重的牙周囊袋探測深度與牙周附連喪失","(B) 與骨缺損輕微者相比，牙周病患者有較嚴重骨缺損時，較容易罹患COPD","(C) 牙菌斑堆積、口腔衛生習慣不良的患者，其慢性呼吸道疾病的風險增加","(D) 嚴重牙周病患者，former smokers與current smokers的COPD風險相同"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-113-1-73","subject":"ya3","topic":"牙科解剖與生理","meta":"113年第1次第73題","year":113,"session":1,"number":73,"question":"下列何者為糖尿病影響牙周病機轉的路徑順序？①AGE/RAGE ②hyperglycemia ③ecological shift in periodontal microbiome ④endothelial cell dysfunction","options":["(A) ①②③④","(B) ①②④③","(C) ②①③④","(D) ②①④③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-74","subject":"ya3","topic":"牙科解剖與生理","meta":"113年第1次第74題","year":113,"session":1,"number":74,"question":"有關糖尿病患的低血糖（hypoglycemia），下列敘述何者正確？","options":["(A) 在執行專業牙周治療時，低血糖是罕見的偶發事件","(B) 低血糖發生的原因，可能與過度身體活動有關","(C) 低血糖的症狀包括皮膚乾燥、口渴","(D) 低血糖的定義是血糖＜60 mg/dL"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-75","subject":"ya3","topic":"植牙學","meta":"113年第1次第75題","year":113,"session":1,"number":75,"question":"在植牙設計中，下列何者可促進植體和骨頭的接觸（bone-implant contact），進一步縮短癒合時間？","options":["(A) 機械表面（machined surface）","(B) 粗糙表面（rough surface）","(C) 骨平面（bone-level）","(D) 組織平面（tissue-level）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-76","subject":"ya3","topic":"植牙學","meta":"113年第1次第76題","year":113,"session":1,"number":76,"question":"根據Recum等人（1996）的研究指出，人工植牙置入後，初期骨頭癒合時，多大的微移動 （micromovements）會損害成骨細胞的分化，且讓齒槽骨和植體表面之間形成纖維疤痕組織？","options":["(A) 10 μm","(B) 50 μm","(C) 100 μm","(D) 150 μm"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-77","subject":"ya3","topic":"植牙學","meta":"113年第1次第77題","year":113,"session":1,"number":77,"question":"為避免植牙手術時因過熱造成骨壞死，骨細胞的臨界溫度（critical temperature）不宜超過多少°C長達1 分鐘？","options":["(A) 43","(B) 47","(C) 53","(D) 57"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-78","subject":"ya3","topic":"植牙學","meta":"113年第1次第78題","year":113,"session":1,"number":78,"question":"關於植體周圍病變敘述，下列何者錯誤？","options":["(A) 植體周圍黏膜炎的患者，在X光檢查下無法發現該植體周圍有骨喪失","(B) 植體周圍黏膜炎跟牙齦炎無論在對細菌入侵的宿主反應及臨床發炎症狀上都極為相似","(C) 植體周圍炎進展的速度通常較牙周炎緩慢","(D) 即使植體周圍骨喪失超過一半，該植體可能在臨床檢查上仍無法測得有動搖情形"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-79","subject":"ya3","topic":"植牙學","meta":"113年第1次第79題","year":113,"session":1,"number":79,"question":"為避免傷害植體水平生物性寬度（horizontal biological width），植入直徑6 mm之植體時，相鄰兩顆植 體中心應至少距離多少mm？","options":["(A) 3","(B) 5","(C) 7","(D) 9"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-1-80","subject":"ya3","topic":"植牙學","meta":"113年第1次第80題","year":113,"session":1,"number":80,"question":"關於植體周圍炎（peri­implantitis）危險因子的敘述，下列何者正確？","options":["(A) 根據Heitz­Mayfield等（2008）的研究指出，壓力、牙周病病史及抽菸都是植體周圍炎的危險因子","(B) 根據Roccuzzo等（2010）的研究指出，嚴重牙周病病史的患者，其植體喪失機率與常人無異","(C) 植體上部構造的設計，除了在發音功能及美觀的考量外，仍需有可自我清潔及專業維護的設計","(D) 根據Baelum及Ellegaard（2004）的研究指出，光滑表面（相對於粗糙面）的植體有較高的失敗率"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-1","subject":"ya3","topic":"根管治療程序","meta":"113年第2次第1題","year":113,"session":2,"number":1,"question":"根據Krasner and Rankow 所提出有關決定牙髓腔和根管入口位置的原則，下列何者正確？","options":["(A) 髓腔壁周圍顏色較髓腔底部為深暗","(B) 根管入口常位於牙根發育融合線（root developmental fusion line）的中央","(C) 根管入口常位於髓腔壁與髓腔底部的轉角（The angle in the floor-wall junction）","(D) 根管入口常位於髓腔底部，其與髓腔壁距離約1～2 mm"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-2","subject":"ya3","topic":"牙髓診斷與病理","meta":"113年第2次第2題","year":113,"session":2,"number":2,"question":"牙髓內A-β神經纖維可能扮演的角色為下列何者？","options":["(A) 感受觸覺與壓力","(B) 作為本體感受器（proprioceptor）","(C) 在正常之牙髓組織內感受痛覺","(D) 在發炎的牙髓組織內產生P物質（substance P）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-3","subject":"ya3","topic":"牙髓診斷與病理","meta":"113年第2次第3題","year":113,"session":2,"number":3,"question":"有關牙本質的敘述，下列何者正確？","options":["(A) 原生牙本質（primary dentin）為牙根完全形成前之牙本質","(B) 繼生牙本質（secondary dentin）為牙齒萌發後所生成之牙本質","(C) 繼生牙本質（secondary dentin）之牙本質小管排列較不規則","(D) 被覆牙本質（mantle dentin）屬於繼生牙本質（secondary dentin）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-113-2-4","subject":"ya3","topic":"牙髓診斷與病理","meta":"113年第2次第4題","year":113,"session":2,"number":4,"question":"根尖周圍炎的致病因子中脂肪多醣類（lipopolysaccharide, LPS）所引發的效應，下列何者正確？","options":["(A) LPS 因血管擴張由血流進入根尖周圍組織","(B) 不同類別的微生物表達不同的分子模式，也由宿主細胞上不同的模式識別類鐸受體（TLR）","(C) LPS啟動樹突狀細胞上的類鐸受體（TLR）以刺激B淋巴細胞分化","(D) 類鐸受體（TLR）是在感染後合成的，屬於適應免疫系統（adaptive immune response）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-5","subject":"ya3","topic":"牙髓診斷與病理","meta":"113年第2次第5題","year":113,"session":2,"number":5,"question":"因應宿主免疫反應及微生物之間的動態交互作用，急性根尖周圍炎可能的發展為下列何者？","options":["(A) 如果根管治療立即消除刺激物，則進展為慢性根尖周圍炎","(B) 如果根管治療立即消除刺激物，則恢復到正常根尖周圍組織","(C) 如果高度化膿性病原體大量侵入根尖周圍組織，則會形成慢性發炎","(D) 如果刺激物持續存在於根尖周圍組織，則會形成膿腫"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-6","subject":"ya3","topic":"牙髓診斷與病理","meta":"113年第2次第6題","year":113,"session":2,"number":6,"question":"根尖周圍炎中主要的非特異性先天免疫（nonspecific innate immune）防禦機制是由下列何種細胞吞噬 （phagocytosis）細菌？","options":["(A) 淋巴細胞 （lymphocytes）","(B) 嗜中性白血球（neutrophils）","(C) 漿細胞（plasma cells）","(D) 抗原呈現細胞（antigen-presenting cells）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-7","subject":"ya3","topic":"牙髓診斷與病理","meta":"113年第2次第7題","year":113,"session":2,"number":7,"question":"有關選擇性麻醉（selective anesthesia）測試，下列敘述何者正確？","options":["(A) 作為牽引痛（referred pain）的鑑別診斷","(B) 牙髓活性測試後仍無結論才介入使用","(C) 優先從下顎後牙開始麻醉","(D) 以牙周膜內注射（intra-ligamentary injection）不會同時麻醉鄰牙"],"answer":[0,1],"image":"","clinical_level":"重點","explanation_pending":false},{"id":"ya3-113-2-8","subject":"ya3","topic":"牙齒外傷處理","meta":"113年第2次第8題","year":113,"session":2,"number":8,"question":"關於外傷牙中的水平牙根斷裂（horizontal root fractures），下列敘述何者正確？","options":["(A) 牙齒需進行復位並固定，固定時間一般建議為兩週","(B) X光診斷時，以平行法照射即可診斷出大部分的病例","(C) 若斷裂部分位於根尖處，於固定後可暫不做立即的處置","(D) 當牙根斷裂的冠部段發生牙髓壞死時，通常根尖段牙髓也已壞死"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-113-2-9","subject":"ya3","topic":"牙齒外傷處理","meta":"113年第2次第9題","year":113,"session":2,"number":9,"question":"如圖，25歲男性於數年前右上門牙曾撞到，當時除疼痛外無其他症狀，也未曾就醫，目前檢查並無臨床任何 症狀，電髓活性測試為無反應，有如圖A之變色，Ｘ光顯示如圖B。關於tooth 11，下列敘述何者正確？","options":["(A) 牙髓產生鈣化現象，若無症狀，觀察即可","(B) 應進行窩洞測試（test cavity）以確認牙髓活性","(C) 需進行根管治療，以預防日後根尖病灶的形成","(D) 牙髓在當時外傷應已壞死，只是未發生感染，觀察即可"],"answer":0,"image":"ya3-113-2-9.jpeg","clinical_level":"一般"},{"id":"ya3-113-2-10","subject":"ya3","topic":"牙髓診斷與病理","meta":"113年第2次第10題","year":113,"session":2,"number":10,"question":"關於垂直牙根斷裂早期不易診斷出來的原因，下列何者錯誤？","options":["(A) 竇管（sinus tract）出現的位置通常與慢性根尖膿瘍類似，均在根尖處","(B) 臨床表徵與根管治療後未癒合的狀況類似","(C) Ｘ光檢查下，骨頭的破壞容易被牙齒疊影遮蔽","(D) Ｘ光檢查下，若牙齒已完成根管治療，根管充填材料會阻礙裂痕的偵測"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-11","subject":"ya3","topic":"根管器械","meta":"113年第2次第11題","year":113,"session":2,"number":11,"question":"有關鎳鈦旋轉器械設計的敘述，下列何者錯誤？","options":["(A) 為了減少修形失誤的產生，鎳鈦旋轉器械大多使用非切削尖端（rounded noncutting tips）的設計，又稱 之為Batt tips","(B) 有些鎳鈦旋轉器械具有radial land的設計，除了強化刀刃，增加切削效率，也可以增加安全性","(C) 鎳鈦合金的成分比例約為鎳55%，鈦45%","(D) 鎳鈦合金主要有兩個主要晶相：沃斯田相（austenite）及麻田散相（martensite），並具有遠優於不鏽鋼 材質的pseudoelasticity，所以對於斷裂也有更好的抗性（resistance）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-113-2-12","subject":"ya3","topic":"根管治療程序","meta":"113年第2次第12題","year":113,"session":2,"number":12,"question":"關於次氯酸鈉（sodium hypochloride, NaOCl）組織溶解力的敘述，下列何者正確？","options":["(A) 20℃ 0.5%NaOCl的組織溶解力與20℃ 5.25%NaOCl相同","(B) 20℃ 5.25%NaOCl的組織溶解力優於60℃ 0.5%NaOCl","(C) 45℃ 0.5%NaOCl的組織溶解力與20℃ 5.25%NaOCl相同","(D) 20℃ 5.25%NaOCl的組織溶解力與60℃ 0.5%NaOCl相同"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-113-2-13","subject":"ya3","topic":"根管器械","meta":"113年第2次第13題","year":113,"session":2,"number":13,"question":"關於標準化器械的組合，下列何者錯誤？","options":["(A) K-file #15 #45 #90；白色","(B) K-file #25 #55 #110；紅色","(C) K-file #35 #65 #130；綠色","(D) K-file #40 #80 #140；黑色"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-14","subject":"ya3","topic":"根管器械","meta":"113年第2次第14題","year":113,"session":2,"number":14,"question":"關於被動式超音波器械操作（passive ultrasonic instrumentation, PUI），下列敘述何者錯誤？","options":["(A) 這是一種活化沖洗液的方法（activation of the irrigant）","(B) 沖洗液應使用新鮮溶液（fresh solution）","(C) 根管清潔與修形的過程中皆可使用以幫助根管徹底清創","(D) 除非是寬大根管，一般狀況是使用15號的小號銼針"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-15","subject":"ya3","topic":"根管治療程序","meta":"113年第2次第15題","year":113,"session":2,"number":15,"question":"關於根管內用藥氫氧化鈣Ca(OH)2 ，下列敘述何者錯誤？","options":["(A) 可水解細胞壁上的內毒素（lipopolysaccharides, LPS），使細菌的生物活性降低","(B) 可輔助溶解根管內殘餘壞死組織","(C) 即使根管尚未完成直線入口修形（straight line access, SLA），亦能達到良好殺菌效果","(D) 因為高鹼度，具殺菌功效"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-113-2-16","subject":"ya3","topic":"根管治療程序","meta":"113年第2次第16題","year":113,"session":2,"number":16,"question":"發生NaOCl沖洗液超出根尖孔（extrusion）意外時，下列何者處置錯誤？","options":["(A) 使用生理食鹽水進行根管沖洗","(B) 立刻給與熱敷以加速患部組織代謝","(C) 可以施打局部麻醉合併給與止痛藥進行疼痛控制","(D) 通常建議給與抗生素"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-17","subject":"ya3","topic":"根尖手術與再治療","meta":"113年第2次第17題","year":113,"session":2,"number":17,"question":"關於穿孔修補治療預後（prognosis）的評估，下列何者錯誤？","options":["(A) 接近根尖處的牙根穿孔，預後較差","(B) 牙根穿孔處若伴隨牙周相通（periodontal communication），則預後較差","(C) 牙根穿孔尺寸小於1 mm有較好的預後","(D) 穿孔發生早期即進行修補有較好的預後"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-18","subject":"ya3","topic":"根管治療程序","meta":"113年第2次第18題","year":113,"session":2,"number":18,"question":"下列何者不是根管治療過程中「根管修形（shaping）」的目標？","options":["(A) 協助移除倒凹根管內壞死的組織（necrotic tissue）及細菌","(B) 讓消毒沖洗液（disinfecting irrigant）能到達根管的根尖部位","(C) 為徹底清潔，可破壞牙根結構的完整性","(D) 創造根管充填的空間"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-19","subject":"ya3","topic":"根尖手術與再治療","meta":"113年第2次第19題","year":113,"session":2,"number":19,"question":"根尖手術的縫線選擇，下列敘述何者正確？","options":["(A) 4-0縫線是最常使用的號數","(B) 合成單股線較能減少細菌滋生","(C) 絲線（silk）使用時間最久，也是最建議的材料","(D) 常規使用可吸收（resorbable）的縫線，可促進傷口貼合"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-20","subject":"ya3","topic":"根尖手術與再治療","meta":"113年第2次第20題","year":113,"session":2,"number":20,"question":"牙髓病根尖手術中使用甲基藍（methylene blue）的目的下列何者錯誤？","options":["(A) 確定牙根尖完整切除","(B) 確定牙根有無斷裂","(C) 確定封填有無隙漏","(D) 可阻止上皮細胞形成長連接上皮（long junctional epithelium）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-21","subject":"ya3","topic":"根管治療程序","meta":"113年第2次第21題","year":113,"session":2,"number":21,"question":"關於初次與重新的根管治療，下列敘述何者錯誤？","options":["(A) 重新根管治療難度較高","(B) 外在的復形物必須先移除，若需要時再重新製作臨時復形物","(C) 重新根管治療和初次治療的成功率一樣高","(D) 重新根管治療時，和病患溝通的時間較長"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-22","subject":"ya3","topic":"根管治療程序","meta":"113年第2次第22題","year":113,"session":2,"number":22,"question":"在修補根管穿孔（perforation）的過程中，應避免使用下列何種材料止血？","options":["(A) 硫酸鈣（calcium sulfate）","(B) 硫酸鐵（ferric sulfate）","(C) 膠原蛋白（collagen-based material）","(D) 氫氧化鈣（calcium hydroxide）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-23","subject":"ya3","topic":"牙髓診斷與病理","meta":"113年第2次第23題","year":113,"session":2,"number":23,"question":"關於牙髓疾病和牙周疾病X光影像的特徵，下列敘述何者錯誤？","options":["(A) 牙髓病灶多為局部性，牙周病灶多為廣泛性","(B) 牙髓疾病齒槽骨喪失（bone loss）根尖部較寬（wider apically），牙周疾病則是冠部較寬 （wider coronally）","(C) 牙髓疾病具有垂直骨喪失（vertical bone loss），牙周疾病通常沒有垂直骨喪失","(D) 牙髓疾病根尖周圍通常有放射線透過性的影像，牙周疾病根尖周圍不一定有放射線透過性的影像"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-113-2-24","subject":"ya3","topic":"窩洞設計與分類","meta":"113年第2次第24題","year":113,"session":2,"number":24,"question":"牙齒置放纖維根柱（fiber post）時，下列根柱長度的參考值何者正確？","options":["(A) 牙冠長度的1/2","(B) 根管長度的1/2","(C) 牙周齒槽骨高度的1/2","(D) 根管長度的2/3"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-25","subject":"ya3","topic":"黏著與美學修復","meta":"113年第2次第25題","year":113,"session":2,"number":25,"question":"下列那一種情形是齒內漂白（internal bleaching）的適應症？","options":["(A) 淺表層牙釉質變色","(B) 牙釉質形成缺陷","(C) 牙本質變色","(D) 嚴重的牙本質缺損"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-113-2-26","subject":"ya3","topic":"醫學倫理與法規","meta":"113年第2次第26題","year":113,"session":2,"number":26,"question":"懷孕5個月的婦女，因大臼齒頰側牙齦出現膿包並伴隨自發性悶痛，臨床檢查發現患齒有金屬贋復牙冠 （prosthetic crown），近心齒頸部有齲齒且頰側牙齦腫脹伴隨竇管存在。下列治療計畫何者最為合適？","options":["(A) 由於孕婦不適合拍攝X光片，無法獲得足夠資訊進行正確診斷，先觀察就好","(B) 牙科治療可能對孕婦造成壓力，只能開立止痛藥與抗生素進行感染控制","(C) 告知病患拍攝X光片對胎兒可能造成的風險，若病患不同意拍攝X光片，為避免產生醫療糾紛，無法提供後 續牙科治療","(D) 可先拆除贋復牙冠並移除齲齒以評估造成患齒症狀的病因，若確定為牙髓與根尖組織疾病問題，則可給與 初步的根管清創與修形處理"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-27","subject":"ya3","topic":"牙科解剖與生理","meta":"113年第2次第27題","year":113,"session":2,"number":27,"question":"關於唾液流量的敘述，下列何者錯誤？","options":["(A) 未受刺激唾液流量的正常值為小於0.1 mL/min","(B) 受刺激後唾液流量的正常值為1.5～2.5 mL/min","(C) 服用抗高血壓藥物會影響唾液流量","(D) 低的唾液流量會降低齒質的再礦化（remineralization）"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-113-2-28","subject":"ya3","topic":"牙科解剖與生理","meta":"113年第2次第28題","year":113,"session":2,"number":28,"question":"關於牙本質小管的敘述，下列何者正確？","options":["(A) 牙本質通透性（permeability）與牙本質小管長度無關","(B) 平均管徑在靠近牙髓腔處大於牙本質牙釉質交界處（DEJ）","(C) 管內的神經元（neuron）受刺激會造成牙本質敏感","(D) 切削牙本質的過程會降低牙本質液（dentinal fluid）的流動"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-29","subject":"ya3","topic":"牙科解剖與生理","meta":"113年第2次第29題","year":113,"session":2,"number":29,"question":"對於口腔中微生物生長環境，下列何處的生物膜（biofilm）酸鹼值（pH）接近7？①口腔黏膜 ②舌頭 ③ 無齲齒的牙齒 ④牙釉質的齲齒 ⑤牙根的齲齒","options":["(A) ①②","(B) ③④","(C) ④⑤","(D) ①③"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-30","subject":"ya3","topic":"牙科解剖與生理","meta":"113年第2次第30題","year":113,"session":2,"number":30,"question":"關於齲齒的敘述，下列何者正確？","options":["(A) 建議使用探針來檢查牙釉質初期齲齒（initial lesion）","(B) 牙釉質去礦化的臨界酸鹼值（critical pH value）比牙本質高","(C) 牙根表面齲蝕通常缺乏明確的邊緣且截面呈現U字形","(D) 當齲齒進展較快時，較易形成硬化牙本質（sclerotic dentin）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-113-2-31","subject":"ya3","topic":"醫學倫理與法規","meta":"113年第2次第31題","year":113,"session":2,"number":31,"question":"臨床流行病學用於解釋診斷測試（diagnostic）與黃金標準（gold standard）的機會表（contingency table）如下圖，下列敘述何者錯誤？","options":["(A) B區域表示虛正反應（false positive）","(B) D區域表示實負反應（true negative）","(C) 敏感性（sensitivity）是指A區域除以（A+C）區域","(D) 特異性（specificity）是指A區域除以（A+B）區域"],"answer":3,"image":"ya3-113-2-31.jpeg","clinical_level":"重點"},{"id":"ya3-113-2-32","subject":"ya3","topic":"複合樹脂與材料","meta":"113年第2次第32題","year":113,"session":2,"number":32,"question":"汞齊填補（amalgam fillings）周邊齒質呈現汞齊藍色（amalgam blue）的現象與下列何者有直接關係？","options":["(A) 細菌代謝物沾附汞齊周邊齒質","(B) 填補物周邊牙釉質去礦化","(C) 汞齊腐蝕物滲入周邊齒質","(D) 填補物周邊齒質有過多的汞齊充填"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-33","subject":"ya3","topic":"黏著與美學修復","meta":"113年第2次第33題","year":113,"session":2,"number":33,"question":"下列何種處理最可能會造成去礦化牙本質之膠原蛋白塌陷（collagen collapse）？","options":["(A) 沖洗酸蝕劑後使用有機溶劑如乙醇塗抹牙本質","(B) 沖洗酸蝕劑後用強力吸唾（high-volume suction）去除多餘的水","(C) 沖洗酸蝕劑後用氣槍完全吹乾牙本質","(D) 沖洗酸蝕劑後用棉球擦拭牙本質"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-34","subject":"ya3","topic":"黏著與美學修復","meta":"113年第2次第34題","year":113,"session":2,"number":34,"question":"在酸蝕與沖洗黏著系統（etch-and-rinse adhesive system）中，為了達成良好的黏著力需讓牙本質濕潤， 下列何者最不可能是此系統中使用的溶劑？","options":["(A) 甲苯","(B) 乙醇","(C) 水","(D) 丙酮"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-35","subject":"ya3","topic":"黏著與美學修復","meta":"113年第2次第35題","year":113,"session":2,"number":35,"question":"關於牙釉質酸蝕的敘述，下列何者錯誤？","options":["(A) 利用30-40 %磷酸酸蝕牙釉質","(B) 酸蝕牙釉質15秒與60秒，所產生表面粗糙度是相似的","(C) 會降低牙釉質表面自由能（surface-free energy）","(D) 樹脂可藉由毛細作用滲入酸蝕後牙釉質而黏著"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-113-2-36","subject":"ya3","topic":"根管器械","meta":"113年第2次第36題","year":113,"session":2,"number":36,"question":"關於橡皮障夾（rubber dam clamp）構造的名稱，下列何者錯誤？","options":["(A) ①：Bow","(B) ②：Points","(C) ③：Jaws","(D) ④：Beak"],"answer":3,"image":"ya3-113-2-36.jpeg","clinical_level":"重點"},{"id":"ya3-113-2-37","subject":"ya3","topic":"窩洞設計與分類","meta":"113年第2次第37題","year":113,"session":2,"number":37,"question":"製備玻璃陶瓷（glass-ceramic）復形物時，刻意將鄰接面打開的理由為下列何者？①較容易完成 （finish）修形的窩洞壁 ②利於後續的印模 ③易於後續置入復形物 ④增加美觀","options":["(A) 僅①④","(B) 僅②③","(C) ①②④","(D) ①②③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-38","subject":"ya3","topic":"窩洞設計與分類","meta":"113年第2次第38題","year":113,"session":2,"number":38,"question":"下列何者是金屬鑄造嵌體的禁忌症（contraindication）？①高齲齒率 ②年輕病患 ③大型齲齒 ④前牙 美觀區","options":["(A) 僅①","(B) ①②④","(C) ②③","(D) 僅②④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-39","subject":"ya3","topic":"複合樹脂與材料","meta":"113年第2次第39題","year":113,"session":2,"number":39,"question":"為避免復形物在口內經過長期的熱脹冷縮產生縫隙（microleakage），選用那個復形材其熱膨脹係數與牙齒 最為接近？","options":["(A) 複合樹脂","(B) 玻璃離子","(C) 汞齊合金","(D) 溝隙封填劑"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-40","subject":"ya3","topic":"複合樹脂與材料","meta":"113年第2次第40題","year":113,"session":2,"number":40,"question":"若有一管複合樹脂，包裝上標示“A2 Dentin”顏色，下列敘述何者正確？","options":["(A) A代表色度（chroma）","(B) dentin代表透明度（translucency）","(C) A代表明度（value）","(D) 2代表色相（hue）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-41","subject":"ya3","topic":"牙體修形程序","meta":"113年第2次第41題","year":113,"session":2,"number":41,"question":"病人因門齒舊樹脂填補物變色求診，下列何種狀況需將殘留於軸壁（axial wall）的舊填補物完全移除？① 深層有銀汞材料，且會影響顏色 ②病人抱怨每吃冰的食物就會痛 ③放射影像顯示填補物下有陰影 ④舊 填補物與窩洞邊緣有微滲漏（microleakage）","options":["(A) 僅②","(B) 僅③④","(C) 僅②③④","(D) ①②③④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-42","subject":"ya3","topic":"複合樹脂與材料","meta":"113年第2次第42題","year":113,"session":2,"number":42,"question":"以分層填補法（incremental technique）進行第二級複合樹脂填補時，下列敘述何者最不適當？","options":["(A) 每層樹脂聚合後，應塗上黏著劑再放置下一層","(B) 使用分層填補法時，每層樹脂厚度應小於2 mm","(C) 使用分層填補法時，應由最深處開始填補","(D) 可提升複合樹脂之聚合程度"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-43","subject":"ya3","topic":"牙體修形程序","meta":"113年第2次第43題","year":113,"session":2,"number":43,"question":"下列那一顆牙齒在汞齊第一級窩洞修形中，鑽針進入方向應為牙齒長軸與咬合面垂直線的分角線？","options":["(A) 上顎第一小臼齒","(B) 上顎第二小臼齒","(C) 下顎第一小臼齒","(D) 下顎第二小臼齒"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-44","subject":"ya3","topic":"窩洞設計與分類","meta":"113年第2次第44題","year":113,"session":2,"number":44,"question":"關於汞齊填補放置固位釘（pin）的位置，下列敘述何者錯誤？","options":["(A) 當鄰近的窩洞邊緣位於CEJ以上，固位釘渠（pin channel）至少距離DEJ 0.5 mm","(B) 大部分建議放置在轉角處（line angle）","(C) 上顎小臼齒建議放置在近心側或遠心側","(D) 固位釘渠的鑽針（pin channel drill）應與外圍的齒質平行"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-45","subject":"ya3","topic":"牙體修形程序","meta":"113年第2次第45題","year":113,"session":2,"number":45,"question":"汞齊拋光時，溫度最高不可超過攝氏多少度，否則會造成牙髓無法挽救的傷害？","options":["(A) 40度","(B) 50度","(C) 60度","(D) 70度"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-46","subject":"ya3","topic":"複合樹脂與材料","meta":"113年第2次第46題","year":113,"session":2,"number":46,"question":"當陶瓷嵌體表面染色時，最適當的移除方式為下列何者？","options":["(A) 以橡皮杯沾氧化鋁打亮膏（aluminum oxide polishing paste）拋光移除","(B) 以超音波洗牙機頭清除","(C) 以氣動噴砂機（air-abrasive polisher）噴除","(D) 以高速手機利用鑽石鑽針磨除"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-47","subject":"ya3","topic":"窩洞設計與分類","meta":"113年第2次第47題","year":113,"session":2,"number":47,"question":"陶瓷嵌體屬於永久復形物，下列有關其失敗原因的敘述何者錯誤？","options":["(A) 咬頭硨削厚度不能超過1.5 mm以免傷害原本咬頭強度","(B) 斷裂易發生在邊緣嵴（marginal）連接的峽部（isthmus）區域","(C) 常見的失敗原因為陶瓷塊狀斷裂與邊緣黏合劑磨耗","(D) 初期樹脂黏合劑（resin cements）的磨耗與邊緣溝隙的大小呈正相關"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-48","subject":"ya3","topic":"牙髓診斷與病理","meta":"113年第2次第48題","year":113,"session":2,"number":48,"question":"當嵌體窩洞修形時，關於覆髓施作的條件，下列敘述何者錯誤？","options":["(A) 因人為失誤造成牙髓暴露，應逕行根管治療，不應覆髓","(B) 需要乾淨無污染的操作區域","(C) 牙髓暴露小於0.5 mm時","(D) 無臨床牙髓炎的症狀"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-49","subject":"ya3","topic":"窩洞設計與分類","meta":"113年第2次第49題","year":113,"session":2,"number":49,"question":"金屬鑄造體裙狀修形（skirting）的方法與目的，下列敘述何者錯誤？","options":["(A) 是改善固位及抗力的方法","(B) 須延伸超越頰舌面的線角","(C) 通常只修形牙釉質","(D) 只適用於鑲嵌體（inlay）的修形"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-113-2-50","subject":"ya3","topic":"黏著與美學修復","meta":"113年第2次第50題","year":113,"session":2,"number":50,"question":"前牙填補複合樹脂的比色原則，下列敘述何者錯誤？","options":["(A) 牙齒表面染色（stain）需去除","(B) 比色時牙齒應保持濕潤","(C) 色調配對（shade matching）時，操作者和比色目標應距離約25～35 cm","(D) 凝視牙齒與比色板時間至少20秒"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-51","subject":"ya3","topic":"黏著與美學修復","meta":"113年第2次第51題","year":113,"session":2,"number":51,"question":"VITA Toothguide 3D-Master比色板中，關於2M3色板的表示，下列何者正確？","options":["(A) 比2M1的彩度（chroma）低","(B) 3代表色調（hue）","(C) M代表彩度（chroma）","(D) 2代表明度（value）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-52","subject":"ya3","topic":"黏著與美學修復","meta":"113年第2次第52題","year":113,"session":2,"number":52,"question":"患者微笑時正中門齒：側門齒：犬齒之正面觀比例為1.618：1：0.816，下列敘述何者正確？","options":["(A) 正中門齒：側門齒比例小於黃金比例","(B) 側門齒：犬齒比例符合黃金比例","(C) 由黃金比例可推測犬齒實際大小偏寬","(D) 調整牙齒長度不會改變黃金比例"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-53","subject":"ya3","topic":"牙科解剖與生理","meta":"113年第2次第53題","year":113,"session":2,"number":53,"question":"角質細胞（keratinocyte）於下列那一層開始出現電子緻密透明角質體（electron-dense keratohyalin bodies）？","options":["(A) 基底層（stratum basale）","(B) 棘細胞層（stratum spinosum）","(C) 顆粒層（stratum granulosum）","(D) 角質層（stratum corneum）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-54","subject":"ya3","topic":"牙科解剖與生理","meta":"113年第2次第54題","year":113,"session":2,"number":54,"question":"下列何種細胞會分化成為可分泌抗體的漿細胞（plasma cells）？","options":["(A) T細胞（T cells）","(B) B細胞（B cells）","(C) 造纖維細胞（fibroblasts）","(D) 巨核細胞（megakaryocytes）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-55","subject":"ya3","topic":"牙科解剖與生理","meta":"113年第2次第55題","year":113,"session":2,"number":55,"question":"下列何者未參與多形核嗜中性細胞（PMNs）黏附（adhesion）到血管內皮細胞的過程？","options":["(A) intercellular adhesion molecule-1（ICAM-1）","(B) vascular cell adhesion molecule-1（VCAM-1）","(C) endothelial leukocyte adhesion molecule-1（ELAM-1）","(D) hemidesmosomes"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-56","subject":"ya3","topic":"牙科解剖與生理","meta":"113年第2次第56題","year":113,"session":2,"number":56,"question":"細菌的外膜含有可與宿主之類鐸受體（toll-like receptor）相互作用的大分子，下列那種大分子在革蘭氏 陰性及革蘭氏陽性細菌的外膜中均可出現？","options":["(A) 脂蛋白（lipoprotein）","(B) 脂多醣（lipopolysaccharide）","(C) 肽聚糖（peptidoglycan）","(D) 脂磷壁酸（lipoteichoic acid）"],"answer":[0,1,2,3],"image":"","clinical_level":"一般","explanation_pending":false},{"id":"ya3-113-2-57","subject":"ya3","topic":"牙科解剖與生理","meta":"113年第2次第57題","year":113,"session":2,"number":57,"question":"負責在胞內體（endosome）辨認細菌核酸的是下列那種類鐸受體（toll-like receptor, TLR）？","options":["(A) TLR-2","(B) TLR-5","(C) TLR-6","(D) TLR-9"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-58","subject":"ya3","topic":"牙周疾病與診斷","meta":"113年第2次第58題","year":113,"session":2,"number":58,"question":"關於探測出血（bleeding on probing）的敘述，下列何者最不適當？","options":["(A) 沒有探測出血不能當成牙周健康的優異指標（indicator）","(B) 單純探測出血不能成為未來附連喪失（loss of attachment）的指標","(C) 探測出血是牙齦發炎的最好臨床指標","(D) 探測出血加上囊袋深度增加（increasing pocket depth），可作為未來附連喪失的良好預測因子"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-113-2-59","subject":"ya3","topic":"牙周疾病與診斷","meta":"113年第2次第59題","year":113,"session":2,"number":59,"question":"在Page & Schröeder（1976）建立的實驗性牙齦炎（experimental gingivitis）模型中，對牙菌斑堆積2～ 4天時所產生的起始病灶（initial lesion），下列敘述何者錯誤？","options":["(A) 外觀可見些微紅腫","(B) 牙齦溝液流動（gingival crevicular fluid flow）增加","(C) 多形核嗜中性球（polymorphonuclear neutrophils）聚積","(D) 結締組織（connective tissue）喪失"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-60","subject":"ya3","topic":"牙周疾病與診斷","meta":"113年第2次第60題","year":113,"session":2,"number":60,"question":"下列何者不是用來評估牙周組織支持喪失的指標系統？","options":["(A) Russell（1956）提出的Periodontal Index","(B) Ramfjord（1959）提出的Periodontal Disease Index","(C) Ainamo & Bay（1975）提出的二分法計分系統","(D) Carlos et al.（1986）提出的Extent and Severity Index"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-61","subject":"ya3","topic":"牙周疾病與診斷","meta":"113年第2次第61題","year":113,"session":2,"number":61,"question":"在成人壞死性牙齦炎的患者，下列何者不是最常見的臨床表現？","options":["(A) 齒間牙齦乳突壞死","(B) 口臭","(C) 偽膜形成","(D) 流涎"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-62","subject":"ya3","topic":"牙周疾病與診斷","meta":"113年第2次第62題","year":113,"session":2,"number":62,"question":"在2017 World Workshop公布的牙周病新分類中，關於區分Stage III與Stage IV牙周炎患者的治療複雜性 （complexity）因子，下列敘述何者錯誤？","options":["(A) 相較於Stage III患者，Stage IV患者齒列需有複雜的重建治療","(B) 若治療涉及跨多科合作的全口重建治療，則可評估為Stage IV患者","(C) 評估Stage III與Stage IV牙周炎患者，需整合性的評估複雜性因子","(D) Stage III與Stage IV牙周炎患者皆存在嚴重程度的齒槽嵴缺損"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-113-2-63","subject":"ya3","topic":"牙周非手術治療","meta":"113年第2次第63題","year":113,"session":2,"number":63,"question":"牙周炎與牙根表面的細菌生物膜以及牙結石有高度相關，關於非手術性牙周囊袋／牙根清創術 （pocket/root debridement）治療的敘述，下列何者錯誤？","options":["(A) 治療的目的在於降低細菌殘留量至某閾值，讓宿主得以抵抗微生物的感染","(B) 臨床上可以用探測流血與否，以及抵抗探測能力為療效評估指標","(C) 研究顯示，當牙周囊袋小於5 mm時，臨床上可以完全移除牙根表面的牙結石","(D) 牙結石是微生物群聚的好場所，但其本身並不會導致發炎"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-64","subject":"ya3","topic":"牙周非手術治療","meta":"113年第2次第64題","year":113,"session":2,"number":64,"question":"關於牙齦下牙根清創（subgingival debridement）的方法，下列敘述何者錯誤？","options":["(A) Badersten 等（1984）根據牙周病的嚴重度或侵犯的範圍，全口治療可分成四或六個診次完成","(B) Quirynen 等（1995）首度提出24小時內完成全口牙根清創，可以節省每象限所需的治療時間","(C) Kawashima 等（2007）研究指出與手動器械相比，使用音波或超音波器械操作，有較少牙根表面的耗損","(D) Lang 等（2008）系統性文獻回顧，以24小時內完成全口牙根清創的治療，在降低牙周細菌方面並無明顯優 勢"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-113-2-65","subject":"ya3","topic":"牙周手術與再生","meta":"113年第2次第65題","year":113,"session":2,"number":65,"question":"下列那一項手術治療方式較適合一級牙根叉侵犯（Class I furcation involvement）的牙齒？","options":["(A) 管道修形術（tunnel preparation）","(B) 牙根切除術（root resection）","(C) 引導組織再生術（guided tissue regeneration）","(D) 翻瓣清創手術（open flap debridement）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-113-2-66","subject":"ya3","topic":"牙周手術與再生","meta":"113年第2次第66題","year":113,"session":2,"number":66,"question":"下列何者不是牙冠增長手術的適應症？","options":["(A) 牙齦下齲齒","(B) 牙根中段穿孔","(C) 牙齦下斷裂","(D) 臨床牙冠過短，固持力（retention）不足"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-113-2-67","subject":"ya3","topic":"牙周手術與再生","meta":"113年第2次第67題","year":113,"session":2,"number":67,"question":"評估是否執行牙周手術，下列敘述何者錯誤？","options":["(A) 根據Lindhe等學者（1982）提出的臨界探測深度（critical probing depth）理論，臼齒區域的初期牙周 探測深度（initial probing depth）大於6 mm，翻瓣手術的效果才會優於非手術治療","(B) 非手術治療後，牙周探測深度仍大於4 mm且有探測出血（bleeding on probing）的齒位，建議手術治療","(C) 牙齒的動搖度及牙根的長度為手術治療的評估因子之一","(D) 當殘餘囊袋合併有骨內缺損（intrabony defects）時，乳頭保存翻瓣手術（papilla preservation flap）的效果會優於傳統翻瓣手術（modified Widman flap）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-68","subject":"ya3","topic":"牙周手術與再生","meta":"113年第2次第68題","year":113,"session":2,"number":68,"question":"在切開及剝離牙齦時，欲保留齒間乳頭（interdental papilla）的完整，下列何種器械最不適合用於齒間 的區域？","options":["(A) [見附圖]","(B) [見附圖]","(C) [見附圖]","(D) [見附圖]"],"answer":0,"image":"ya3-113-2-68.jpeg","clinical_level":"一般"},{"id":"ya3-113-2-69","subject":"ya3","topic":"牙周手術與再生","meta":"113年第2次第69題","year":113,"session":2,"number":69,"question":"關於牙周手術後的變化，下列敘述何者錯誤？","options":["(A) 牙齒動搖度增加的原因為牙周韌帶被刮除","(B) 牙齒動搖度增加大約會在四個星期後緩解","(C) 牙周手術治療後造成牙根敏感的機會比非手術性治療高","(D) 維持良好的牙菌斑控制可以減緩牙根敏感"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-113-2-70","subject":"ya3","topic":"牙周手術與再生","meta":"113年第2次第70題","year":113,"session":2,"number":70,"question":"下列常見的縫線中，何者通常不需要拆線？","options":["(A) 絲線（silk suture）","(B) 尼龍線（nylon suture）","(C) 聚四氟乙烯線（ePTFE suture）","(D) 聚乙醇酸線（polyglycolic acid suture）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-71","subject":"ya3","topic":"牙周手術與再生","meta":"113年第2次第71題","year":113,"session":2,"number":71,"question":"關於同種異體移植骨（allograft）的敘述，下列何者錯誤？","options":["(A) 可能引起免疫反應","(B) 取自死亡12小時後患者之海綿骨，經處理後而得","(C) 其顆粒大小為250～750微米","(D) 感染人類免疫缺乏病毒（HIV）的機率約8百萬分之一"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-72","subject":"ya3","topic":"牙周疾病與診斷","meta":"113年第2次第72題","year":113,"session":2,"number":72,"question":"關於學者Lang & Tonetti提出的功能性圖（funtional diagram）要評估的項目，下列何者錯誤？","options":["(A) 全口28顆牙齒喪失數目","(B) 有無系統性疾病或抽菸","(C) 囊袋探測出血牙齒顆數","(D) 牙周支持喪失百分比相對於年齡的比例（BL%/age）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-113-2-73","subject":"ya3","topic":"牙科解剖與生理","meta":"113年第2次第73題","year":113,"session":2,"number":73,"question":"關於急性高血糖急診（acute hyperglycemic emergency）的敘述，下列何者錯誤？","options":["(A) 定義是血糖＞350～400 mg/dL","(B) 發生的原因，可能與未診斷的糖尿病有關","(C) 症狀包括皮膚乾熱、低血壓、呼吸急促","(D) 必須立即轉送至醫院急救"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-74","subject":"ya3","topic":"牙科解剖與生理","meta":"113年第2次第74題","year":113,"session":2,"number":74,"question":"關於不良妊娠之子癇前症（preeclampsia）的敘述，下列何者正確？","options":["(A) 常發生於牙周病患懷孕初期，有致命風險","(B) 其臨床特徵是血壓過低，容易暈眩","(C) 患者的尿液中，可檢出糖分過高","(D) C-reactive protein的水平（level）增高"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-75","subject":"ya3","topic":"牙科解剖與生理","meta":"113年第2次第75題","year":113,"session":2,"number":75,"question":"關於牙周病與癌症的關聯，下列敘述何者錯誤？","options":["(A) 研究證實，經由調控系統性炎症及免疫反應，可以提高某些癌症患者的存活率","(B) 嚴重牙周病的糖尿病患者，會增加其癌前病變和惡性病變發生的風險","(C) 口腔癌患者的牙周病囊袋探測深度、探測時流血、牙周附連喪失與正常患者相似","(D) 例行的牙科複診、維持口腔健康的預防醫學處置，能降低男性食道癌風險"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-113-2-76","subject":"ya3","topic":"牙周手術與再生","meta":"113年第2次第76題","year":113,"session":2,"number":76,"question":"下列何者不是ePTFE（expanded polytetrafluoroethylene）再生膜的特性？","options":["(A) 須要二次手術移除","(B) 降解過程可能會產生不同程度的炎症反應","(C) 維持長時間隔離組織","(D) 一旦暴露在口腔，不會自發癒合，並可能被口腔細菌污染，導致骨質流失"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-77","subject":"ya3","topic":"牙周手術與再生","meta":"113年第2次第77題","year":113,"session":2,"number":77,"question":"骨形態生成蛋白質（bone morphogenetic proteins, BMPs）是一群存在於身體，對骨骼發育很重要的蛋白 質。下列何者被證實有最強的骨生成作用？","options":["(A) BMP-1","(B) BMP-2","(C) BMP-3","(D) BMP-7"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-113-2-78","subject":"ya3","topic":"植牙學","meta":"113年第2次第78題","year":113,"session":2,"number":78,"question":"下列何者不是人工植牙在美觀區併發症風險增加的原因？","options":["(A) 病人過高的期望","(B) 低微笑線","(C) 薄的牙周組織","(D) 不足的齒槽骨寬度"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-113-2-79","subject":"ya3","topic":"醫學倫理與法規","meta":"113年第2次第79題","year":113,"session":2,"number":79,"question":"採用何種放射線檢查，病患接受的輻射劑量最高？","options":["(A) Panoramic radiography","(B) Large field-of-view cone-beam computed tomography","(C) Limited field-of-view cone-beam computed tomography","(D) Full mouth x-ray series"],"answer":[1,3],"image":"","clinical_level":"一般"},{"id":"ya3-113-2-80","subject":"ya3","topic":"植牙學","meta":"113年第2次第80題","year":113,"session":2,"number":80,"question":"關於以局部給與抗菌藥物處理植體周圍疾病的敘述，下列何者錯誤？","options":["(A) 植體周圍囊袋跟自然牙牙齦溝之結構類似，但溝液（crevicular fluid）流動速率較慢（low flow rate）","(B) 目前局部抗菌藥物多半是扮演植體周圍機械性清創的輔助角色","(C) 根據網絡統合分析（network meta-analyses）結果，局部抗菌藥物對於植體周圍炎治療效果跟單獨機械性 清創相比差異不大","(D) 目前對於局部抗菌藥物的適應症，可能是在手術前控制植體周圍組織的發炎反應"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-1","subject":"ya3","topic":"牙髓診斷與病理","meta":"114年第1次第1題","year":114,"session":1,"number":1,"question":"下列何者不是牙髓防禦機制（pulp defense mechanism）？","options":["(A) 神經性發炎反應（neurogenic inflammation）","(B) 牙本質小管液體回流（fluid inflow）","(C) 動靜脈分流（arteriovenous shunt）","(D) 三度牙本質（tertiary dentin）形成"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-2","subject":"ya3","topic":"牙髓診斷與病理","meta":"114年第1次第2題","year":114,"session":1,"number":2,"question":"關於牙髓神經的敘述，下列何者錯誤？","options":["(A) 主要的感覺神經是 A fiber 與 C fiber","(B) C fiber 神經纖維分布在牙髓本體深部","(C) A fiber 目前只發現 A-α、A-β、A-γ三種神經纖維類型","(D) A-α神經纖維直徑比 A-γ寬"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-3","subject":"ya3","topic":"牙髓診斷與病理","meta":"114年第1次第3題","year":114,"session":1,"number":3,"question":"有關造成根管感染的微生物（microbes），下列敘述何者錯誤？","options":["(A) 初期根管感染多為革蘭氏陰性菌（gram-negative bacteria）","(B) 次氯酸鈉對革蘭氏陽性菌（gram-positive bacteria）比革蘭氏陰性菌（gram-negative bacteria）有更佳 的殺菌效果","(C) Enterococcus faecalis是屬於兼性厭氧革蘭氏陽性菌（facultative anaerobic gram-positive bacteria）","(D) 唾液的一些成分可進到根管裡變成微生物的營養來源"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-4","subject":"ya3","topic":"牙髓診斷與病理","meta":"114年第1次第4題","year":114,"session":1,"number":4,"question":"根尖周圍炎的致病機轉（pathogenesis）與下列何者無關？","options":["(A) 先天免疫反應（innate immune response）","(B) 適應性免疫反應（adaptive immune response）","(C) 神經性發炎（neurogenic inflammation）","(D) 自主免疫反應（auto immune response）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-5","subject":"ya3","topic":"牙周疾病與診斷","meta":"114年第1次第5題","year":114,"session":1,"number":5,"question":"cementum 是礦化無血管的結締組織，可分為三類，下列那一類位在靠冠部一半的牙根上？","options":["(A) 無細胞及無纖維牙骨質（acellular afibrillar cementum）","(B) 無細胞及有外在纖維牙骨質（acellular extrinsic fiber cementum）","(C) 有細胞及有內在纖維牙骨質（cellular intrinsic fiber cementum）","(D) 有細胞及有外在纖維牙骨質（cellular extrinsic fiber cementum）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-6","subject":"ya3","topic":"牙髓診斷與病理","meta":"114年第1次第6題","year":114,"session":1,"number":6,"question":"根據美國牙髓病學會 2012 診斷分類，最可能出現下列何種分類？","options":["(A) 牙髓壞死（pulp necrosis）合併急性根尖膿腫（acute apical abscess）","(B) 可逆性牙髓炎（reversible pulpitis）合併慢性根尖膿腫（chronic apical abscess）","(C) 可逆性牙髓炎（reversible pulpitis）合併無症狀型根尖周圍炎（asymptomatic apical periodontitis）","(D) 牙髓壞死（pulp necrosis）合併硬化性骨炎（condensing osteitis）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-7","subject":"ya3","topic":"牙髓診斷與病理","meta":"114年第1次第7題","year":114,"session":1,"number":7,"question":"病人例行口腔檢查發現上顎左側第一大臼齒咬合面與遠心側有深部齲齒（deep caries），X 光片如圖所示， 於探測時齲齒已深入牙髓腔。病人無自發性疼痛、冰與熱刺激皆有反應、無咬痛、敲診與觸診正常。針對上顎 左側第一大臼齒的診斷何者正確？","options":["(A) 牙髓診斷：可逆性牙髓炎（reversible pulpitis）；牙根尖周圍診斷：正常根尖組織（normal apical tissue）","(B) 牙髓診斷：無症狀型不可逆性牙髓炎（asymptomatic irreversible pulpitis）；牙根尖周圍診斷：正常根 尖組織（normal apical tissue）","(C) 牙髓診斷：無症狀型不可逆性牙髓炎（asymptomatic irreversible pulpitis）；牙根尖周圍診斷：無症狀 型根尖周圍炎（asymptomatic apical periodontitis）","(D) 牙髓診斷：有症狀型不可逆性牙髓炎（symptomatic irreversible pulpitis）；牙根尖周圍診斷：無症狀 型根尖周圍炎（asymptomatic apical periodontitis）"],"answer":1,"image":"ya3-114-1-7.jpeg","clinical_level":"一般"},{"id":"ya3-114-1-8","subject":"ya3","topic":"牙齒外傷處理","meta":"114年第1次第8題","year":114,"session":1,"number":8,"question":"牙齒外傷分類中，診斷為複雜性牙冠斷裂（complicated crown fracture）的牙齒，下列敘述何者最適當？","options":["(A) 通常需配合牙周病的相關治療","(B) 牙根未發育完成之恆牙，以保留牙髓為優先考量","(C) 牙根發育完成之恆牙，一律以進行根管治療為首選","(D) 未來選擇使用複合樹脂或含釘柱之牙套復形，並不影響牙髓的治療計畫"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-9","subject":"ya3","topic":"牙齒外傷處理","meta":"114年第1次第9題","year":114,"session":1,"number":9,"question":"外傷產生齒槽骨斷裂（alveolar fracture）時，下列敘述何者正確？","options":["(A) 鄰近牙齒的牙髓壞死可能與其有關","(B) 鄰近斷裂區的牙齒一般需及早進行根管治療","(C) 若對牙髓測試無反應，無論有無症狀，都需進行根管治療","(D) 使用根尖片與錐狀束電腦斷層（cone beam computed tomography, CBCT）可達到相同的診斷效果"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-10","subject":"ya3","topic":"牙齒外傷處理","meta":"114年第1次第10題","year":114,"session":1,"number":10,"question":"由牙齒外傷所造成的各種牙根吸收，下列那一種無法經由根管治療而停止？","options":["(A) 發炎性根尖外吸收（external apical inflammatory resorption）","(B) 發炎性牙根外吸收（external inflammatory root resorption）","(C) 取代性牙根外吸收（external replacement root resorption）","(D) 牙根內吸收（internal root resorption）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-11","subject":"ya3","topic":"根管治療程序","meta":"114年第1次第11題","year":114,"session":1,"number":11,"question":"關於下齒槽阻斷麻醉（inferior alveolar nerve block）中麻醉藥劑的敘述，下列何者錯誤？","options":["(A) articaine 與 lidocaine 的成人最大劑量相同，都是 700 mg","(B) bupivacaine 相較於 lidocaine 作用（onset）較慢，但是麻醉時間幾乎是 lidocaine 的兩倍","(C) 不含腎上腺素（epinephrine）的 3% mepivacaine，其麻醉時間會縮短到約 50 分鐘","(D) 1.8 mL 及 3.6 mL 的 2% lidocaine 其麻醉效果相同，增加腎上腺素（epinephrine）的濃度也沒有明顯的效 益"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-12","subject":"ya3","topic":"根管器械","meta":"114年第1次第12題","year":114,"session":1,"number":12,"question":"關於鎳鈦旋轉器械的敘述，下列何者正確？","options":["(A) radial land 的設計是為了增進效率與安全性","(B) 器械的螺紋數（spirals）越多，螺紋角（helix angle）越小","(C) 刀刃與切削表面的夾角對切削效率的影響不大","(D) 如果同一支器械中使用不定螺距（variable pitch）的設計，通常器械的尖端螺距較小"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-13","subject":"ya3","topic":"根管治療程序","meta":"114年第1次第13題","year":114,"session":1,"number":13,"question":"因牙髓病變而產生顏面部腫脹之病人，若服用 penicillin 類抗生素 2～3 天後，臉部腫脹仍然沒有消退跡象 時，可以考慮加開下列那一項藥物以控制感染？","options":["(A) cephalosporin","(B) clindamycin","(C) metronidazole","(D) tetracycline"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-14","subject":"ya3","topic":"根管治療程序","meta":"114年第1次第14題","year":114,"session":1,"number":14,"question":"在不考慮病人本身疾病史及過敏史的狀況下，下列那一類止痛藥為控制牙痛的首選用藥？","options":["(A) 乙醯胺酚（acetaminophen）","(B) 非類固醇消炎止痛藥（non-steroidal anti-inflammatory drugs, NSAIDs）","(C) 阿斯匹靈（aspirin）","(D) 鴉片類藥物（opioid）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-15","subject":"ya3","topic":"根管治療程序","meta":"114年第1次第15題","year":114,"session":1,"number":15,"question":"下列牙髓感染性的情況何者不需要給與全身性抗生素（systemic antibiotics）？","options":["(A) 牙齦上的竇管（sinus tract at gingiva）","(B) 蜂窩性組織炎（cellulitis）","(C) 發燒（fever）","(D) 頭頸部淋巴腺腫大（lymphadenopathy）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-16","subject":"ya3","topic":"牙髓診斷與病理","meta":"114年第1次第16題","year":114,"session":1,"number":16,"question":"下列何者是錐狀射束電腦斷層掃描（cone beam computed tomography, CBCT）應用於牙髓病診斷所建議採用 的體素大小（voxel size）範圍？","options":["(A) ＜0.025 mm3","(B) 0.075 mm3～0.125 mm3","(C) 0.20 mm3～0.40 mm3","(D) 0.50 mm3～0.80 mm3"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-17","subject":"ya3","topic":"根管治療程序","meta":"114年第1次第17題","year":114,"session":1,"number":17,"question":"下列何者不是根管治療直線入口（straight-line access）的優點？","options":["(A) 可降低器械斷裂的風險","(B) 可保留更多的健全齒質結構（sound tooth structure）","(C) 器械可直線放入根管開口","(D) 使根管徹底清創更容易達成"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-18","subject":"ya3","topic":"根管治療程序","meta":"114年第1次第18題","year":114,"session":1,"number":18,"question":"以退展法（step-back technique）修形根管，由根尖開口往牙冠方向每退 0.5 mm 的號數分別為 No.30、 No.35、No.40、No.45、No.50、No.55。則根尖處根管修形的錐度為何？","options":["(A) 0.5","(B) 0.05","(C) 0.10","(D) 0.15"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-19","subject":"ya3","topic":"根尖手術與再治療","meta":"114年第1次第19題","year":114,"session":1,"number":19,"question":"關於軟組織傷口的癒合（wound healing），下列敘述何者正確？","options":["(A) 血管生成（angiogenesis）通常在術後 24 小時內即已開始","(B) 手術的目標主要希望達到組織能進行修復（repair），而非再生（regeneration）","(C) 在發炎階段（inflammatory phase），巨噬細胞（macrophage）數量的增加，會延遲組織的癒合","(D) 在增生階段（proliferative phase），主要的關鍵細胞是成纖維細胞（fibroblast）與內皮細胞 （endothelial cells）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-20","subject":"ya3","topic":"根尖手術與再治療","meta":"114年第1次第20題","year":114,"session":1,"number":20,"question":"有關牙髓手術常使用藥劑的敘述，下列何者錯誤？","options":["(A) 術前 1 小時必須常規給與 NSAID 止痛藥與抗生素，以助術後的止痛與感染控制","(B) 止血膠網（Surgicel）為物理性止血劑，若殘留於手術區組織會延遲傷口癒合","(C) 根尖手術前，通常建議使用 0.12% chlorhexidine gluconate 漱口以降低手術區域的細菌數量","(D) 根尖手術局部麻醉通常建議使用含有 1：50,000 腎上腺素（epinephrine）的麻藥"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-21","subject":"ya3","topic":"根管治療程序","meta":"114年第1次第21題","year":114,"session":1,"number":21,"question":"根管穿孔（canal perforation）通常在那個位置預後較差？","options":["(A) 髓腔底部","(B) 根管冠部齒槽骨嵴","(C) 根管中段","(D) 根尖處"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-22","subject":"ya3","topic":"根尖手術與再治療","meta":"114年第1次第22題","year":114,"session":1,"number":22,"question":"關於移除根管中馬來膠的相關敘述，下列何者錯誤？","options":["(A) 移除過程中應該合併使用電子根尖定位器，以避免馬來膠被帶出牙根尖外","(B) 溶劑應該經常更換以維持其溶解效率","(C) 許多鎳鈦旋轉器械也可以用來移除馬來膠","(D) 對於先前過度充填（overextended obturation）的個案，可以考慮使用 K-file 以順時針方向逐步移除"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-23","subject":"ya3","topic":"窩洞設計與分類","meta":"114年第1次第23題","year":114,"session":1,"number":23,"question":"預製金屬根柱有主動式根柱（active post）和被動式根柱（passive post），為了促進根柱的固持性 （retension），下列敘述何者錯誤？","options":["(A) 主動式根柱的固持性主要來自於螺紋卡進根管壁，被動式根柱則來自於黏著劑","(B) 主動式根柱在放置過程可能會發生垂直牙根斷裂","(C) 被動式根柱中，平行根柱比錐形根柱更具有固持性","(D) 平行根柱要移除更多的牙本質，比錐形根柱容易導致牙根斷裂"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-24","subject":"ya3","topic":"牙髓診斷與病理","meta":"114年第1次第24題","year":114,"session":1,"number":24,"question":"關於牙本質不正常鈣化（calcific metamorphosis）造成牙齒變色的敘述，下列何者錯誤？","options":["(A) 與牙齒受外力撞擊有關","(B) 牙冠呈現黃色或黃棕色","(C) 牙髓通常會壞死，需要根管治療","(D) 如病人要求，可先試行齒外漂白（external bleaching）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-25","subject":"ya3","topic":"牙科解剖與生理","meta":"114年第1次第25題","year":114,"session":1,"number":25,"question":"有關使用雙磷酸鹽藥物（bisphosphonates）靜脈注射的患者，下列敘述何者錯誤？","options":["(A) 雙磷酸鹽藥物常用來治療骨質疏鬆","(B) 雙磷酸鹽藥物有抑制骨吸收，維持骨密度的作用","(C) 可能會產生骨性壞死","(D) 牙齒發生病變，需要馬上拔牙"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-26","subject":"ya3","topic":"根管治療程序","meta":"114年第1次第26題","year":114,"session":1,"number":26,"question":"有關根管治療中根管銼針（file）分離之處置，下列敘述何者錯誤？","options":["(A) 應立即告知患者，並協助轉診相關專科醫師協助處理分離器械事宜","(B) 設法繞過分離器械進行進一步之擴大修形與充填","(C) 避免醫療上之不必要糾紛，應考慮立即拔除並進行植牙等之替代處置方案","(D) 應將分離器械後剩餘未分離部分保存於根管治療之病歷資料內"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-27","subject":"ya3","topic":"窩洞設計與分類","meta":"114年第1次第27題","year":114,"session":1,"number":27,"question":"下列何種牙釉質通常不具有光滑的表面質地（surface texture）？","options":["(A) 歇止性嚴重齲齒（arrested advanced caries）","(B) 鈣化不全牙釉質（hypocalcified enamel）","(C) 歇止性初期齲齒（arrested initial caries）","(D) 活躍性初期齲齒（active initial caries）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-28","subject":"ya3","topic":"窩洞設計與分類","meta":"114年第1次第28題","year":114,"session":1,"number":28,"question":"關於接觸區（contact area）的敘述，下列何者錯誤？","options":["(A) 適當接觸區可協助維持牙齒位置的穩定性","(B) 接觸區型態不當會增加牙周病風險","(C) 接觸區通常位於牙齒鄰接面的中央偏舌側","(D) 接觸區會隨著年紀增大"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-29","subject":"ya3","topic":"窩洞設計與分類","meta":"114年第1次第29題","year":114,"session":1,"number":29,"question":"根據 Modified Keyes-Jordan diagram，影響齲齒風險率（caries risk）的因子中，下列何者不屬於主要影 響因子（primary modifying factors）？","options":["(A) 性別","(B) 唾液","(C) 口腔衛生","(D) 免疫系統"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-30","subject":"ya3","topic":"窩洞設計與分類","meta":"114年第1次第30題","year":114,"session":1,"number":30,"question":"關於牙根齲齒進展快速之原因，下列敘述何者錯誤？","options":["(A) 在高於 pH 值 5.5 環境下就可能去礦化","(B) 牙根表面較粗糙且清潔不易","(C) 蛀牙斷面型態呈現 V-shape","(D) 近年牙根齲齒盛行率增加"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-31","subject":"ya3","topic":"窩洞設計與分類","meta":"114年第1次第31題","year":114,"session":1,"number":31,"question":"針對於低（low）與高（high）齲齒風險且齒列完整的成人，分別建議多久進行 X 光放射線檢查？","options":["(A) 低風險：12～18 個月；高風險：6～12 個月","(B) 低風險：12～24 個月；高風險：9～12 個月","(C) 低風險：24～36 個月；高風險：6～18 個月","(D) 低風險：36 個月以上；高風險：12～24 個月"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-32","subject":"ya3","topic":"窩洞設計與分類","meta":"114年第1次第32題","year":114,"session":1,"number":32,"question":"關於檢查齲齒方法的敘述，下列何者最不適當？","options":["(A) 使用尖銳的探針用力地探測小窩與裂隙處","(B) 眼睛觀察咬合面變色處","(C) 用強光由頰舌側方向照射鄰接面","(D) 以咬翼片（bite-wing film）檢查後牙鄰接面"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-33","subject":"ya3","topic":"黏著與美學修復","meta":"114年第1次第33題","year":114,"session":1,"number":33,"question":"關於第四代和第五代牙本質黏著劑，下列敘述何者錯誤？","options":["(A) 第四代依照操作步驟，又稱 Three step etch-and-rinse adhesives","(B) 第五代牙本質黏著劑將親水性底劑與厭水性樹脂合為一瓶以簡化黏著過程","(C) 第四代黏著劑較第五代有較好的黏著強度表現","(D) 此兩種黏著劑皆使用磷酸酸蝕以提高牙本質表面能（surface energy）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-34","subject":"ya3","topic":"黏著與美學修復","meta":"114年第1次第34題","year":114,"session":1,"number":34,"question":"要在牙釉質上產生良好的黏著（adhesion），黏著劑（adhesive）的表面張力（surface tension）與牙釉質 的表面能量（surface energy）之間的關係為何？","options":["(A) 牙釉質的表面能量要大於黏著劑的表面張力","(B) 黏著劑的表面張力要大於牙釉質的表面能量","(C) 與牙釉質的表面能量無關","(D) 與黏著劑的表面張力無關"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-35","subject":"ya3","topic":"黏著與美學修復","meta":"114年第1次第35題","year":114,"session":1,"number":35,"question":"使用牙本質黏著劑進行複合樹脂填補時，窩洞經磷酸酸蝕沖水後，過度吹乾將對牙本質表面的膠原纖維 （collagen fiber）造成何種影響？","options":["(A) 可避免膠原纖維被水解","(B) 膠原纖維會塌陷（collapse）","(C) 促進牙本質黏著劑滲入膠原纖維","(D) 膠原纖維網狀體積會增加"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-36","subject":"ya3","topic":"窩洞設計與分類","meta":"114年第1次第36題","year":114,"session":1,"number":36,"question":"下列那些位置的窩洞屬於第一類（class Ⅰ）修形？①後牙咬頭區 ②後牙頰舌側靠咬合面 2/3 區 ③上頷 門齒舌側面 ④後牙咬合區","options":["(A) 僅①②","(B) 僅①③④","(C) 僅②③④","(D) ①②③④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-37","subject":"ya3","topic":"窩洞設計與分類","meta":"114年第1次第37題","year":114,"session":1,"number":37,"question":"關於牙齒修形的原則，下列敘述何者錯誤？","options":["(A) 玻璃陶瓷（glass-ceramic）因不易彎折，窩洞邊緣須有 1.5～2 mm 厚度","(B) 玻璃陶瓷（glass-ceramic）窩洞修形壁須與牙釉質外表面呈 90°","(C) 複合樹脂窩洞任何修形壁須與牙釉質外表面呈 90°","(D) 複合樹脂窩洞建議以鑽石鑽針修形，增加粗糙（roughness）度"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-38","subject":"ya3","topic":"複合樹脂與材料","meta":"114年第1次第38題","year":114,"session":1,"number":38,"question":"比較汞齊合金與複合樹脂填補，下列敘述何者錯誤？","options":["(A) 汞齊合金填補的窩洞設計較簡單","(B) 汞齊合金填補有較高的初期邊緣滲漏（initial marginal leakage）","(C) 複合樹脂填補移除較少的齒質","(D) 複合樹脂有較低的熱傳導率"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-39","subject":"ya3","topic":"複合樹脂與材料","meta":"114年第1次第39題","year":114,"session":1,"number":39,"question":"下列那些方法無法減少複合樹脂聚合引起的收縮應力？","options":["(A) 增加 C factor","(B) 使用 0.5 mm 厚度的流動樹脂做襯底（liner）","(C) 使用 soft-start 的光聚合模式","(D) 分層填補"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-40","subject":"ya3","topic":"黏著與美學修復","meta":"114年第1次第40題","year":114,"session":1,"number":40,"question":"當牙齒處於脫水的狀態，比色時容易呈現何種誤差？","options":["(A) 色調（shade）較淺；透明度（translucency）較高","(B) 色調（shade）較淺；透明度（translucency）較低","(C) 色調（shade）較深；透明度（translucency）較高","(D) 色調（shade）較深；透明度（translucency）較低"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-41","subject":"ya3","topic":"複合樹脂與材料","meta":"114年第1次第41題","year":114,"session":1,"number":41,"question":"複合樹脂填補後，邊緣產生白線（white line）的可能原因與下列何者無關？","options":["(A) 邊緣斜面（bevel）過寬","(B) 複合樹脂聚合收縮產生的應力過大","(C) 沒有適當移除無支撐牙釉質（unsupported enamel）","(D) 塑形磨光不當（traumatic contouring and finishing）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-42","subject":"ya3","topic":"複合樹脂與材料","meta":"114年第1次第42題","year":114,"session":1,"number":42,"question":"關於第二級複合樹脂填補的完成（finishing）步驟，下列敘述何者正確？","options":["(A) 當樹脂已光照硬化後，需等待 24 小時才可進行完成和拋光","(B) 鄰接面邊緣多餘的樹脂不可使用研磨盤（abrasive discs）修整","(C) 鄰接面牙齦緣的外懸（overhang）可使用 12 號刀片移除","(D) 鄰接面牙齦緣不應以砂條（finishing strips）修整"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-43","subject":"ya3","topic":"窩洞設計與分類","meta":"114年第1次第43題","year":114,"session":1,"number":43,"question":"針對大型的齒質缺損咬頭需進行覆蓋（capped），通常強烈建議進行咬頭覆蓋的缺損範圍標準為何？","options":["(A) 缺損範圍為一級溝（primary groove）至外廓高隆線（hight of contour）1/2","(B) 缺損範圍為一級溝（primary groove）至外廓高隆線（hight of contour）2/3","(C) 缺損範圍超過一級溝（primary groove）至咬頭尖端 1/2","(D) 缺損範圍超過一級溝（primary groove）至咬頭尖端 2/3"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-44","subject":"ya3","topic":"窩洞設計與分類","meta":"114年第1次第44題","year":114,"session":1,"number":44,"question":"在進行一級汞齊填補前，若使用鑽針或挖匙（spoon excavators）移除齲齒，會在 pulpal wall 留下凹陷， 凹陷的外圍保留部分平坦之構造（甲）稱為下列何者？","options":["(A) peripheral seat","(B) retention groove","(C) occlusal rest","(D) base"],"answer":0,"image":"ya3-114-1-44.jpeg","clinical_level":"一般"},{"id":"ya3-114-1-45","subject":"ya3","topic":"窩洞設計與分類","meta":"114年第1次第45題","year":114,"session":1,"number":45,"question":"關於汞齊（amalgam）的敘述，下列何者錯誤？","options":["(A) 高銅汞齊是指含有重量 40%的銅","(B) 高銅汞齊與低銅汞齊相比，消除了比較弱的 gamma 2 相","(C) 含鋅汞齊較不含鋅的汞齊機械性質高","(D) 含鋅高銅汞齊受水分污染時，較含鋅銅汞齊不會產生延遲膨脹（delayed expansion）"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-46","subject":"ya3","topic":"窩洞設計與分類","meta":"114年第1次第46題","year":114,"session":1,"number":46,"question":"下列何種設計不會增加鑄造金屬嵌體（cast metal inlay）的固位（retention）？","options":["(A) 增加垂直壁的外展（divergent）角度","(B) 在鄰接面盒（proximal box）頰舌側做固位溝（retention groove）","(C) 將咬合面窩洞延伸到頰側／舌側面溝（facial/lingual surface groove）","(D) 裙邊形狀修形（skirt preparation）設計"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-47","subject":"ya3","topic":"窩洞設計與分類","meta":"114年第1次第47題","year":114,"session":1,"number":47,"question":"關於金合金嵌體窩洞修形時，鄰接面的二度開展（secondary flare）的敘述，下列何者錯誤？","options":["(A) 讓補綴物邊緣容易清潔","(B) 建議產生小於 30°的金屬補綴物邊緣，以便研光（burnish）","(C) 可產生較強牙釉質邊緣（enamel margin）","(D) 會增加金屬露出部分，影響美觀"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-48","subject":"ya3","topic":"窩洞設計與分類","meta":"114年第1次第48題","year":114,"session":1,"number":48,"question":"有關樹脂冠蓋體（resin composite onlay）及瓷冠蓋體（ceramic onlay）的敘述，下列何者錯誤？","options":["(A) 樹脂黏合劑（resin cement）對樹脂冠蓋體比對瓷冠蓋體有更好的黏著效果","(B) 瓷冠蓋體的長期咬合穩定度較樹脂冠蓋體佳","(C) 可壓製陶瓷（pressable ceramics）比傳統長石瓷（traditional feldspathic porcelain）冠蓋體較不易 造成對咬牙齒的磨耗","(D) 瓷冠蓋體比樹脂冠蓋體更容易在試戴（try-in）時裂掉"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-49","subject":"ya3","topic":"複合樹脂與材料","meta":"114年第1次第49題","year":114,"session":1,"number":49,"question":"與直接複合樹脂填補比較，下列何者不是間接複合樹脂嵌體的優點？","options":["(A) 聚合收縮較少","(B) 嵌體具有較強的硬度","(C) 可建立較理想的接觸（contact）","(D) 修形較簡單，可避免喪失過多的齒質"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-50","subject":"ya3","topic":"黏著與美學修復","meta":"114年第1次第50題","year":114,"session":1,"number":50,"question":"關於牙釉質的色彩表現，下列敘述何者錯誤？","options":["(A) 厚的牙釉質比薄的牙釉質明度較高","(B) 老年人因為牙釉質磨損，牙齒色相偏黃","(C) 牙齒切端完全由牙釉質組成，會有乳白色（opalescent）效果","(D) 切端光暈（incisal halo）是切端牙釉質鈣化程度較高所導致"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-51","subject":"ya3","topic":"黏著與美學修復","meta":"114年第1次第51題","year":114,"session":1,"number":51,"question":"患者因笑起來不好看求診（如下圖），下列何者為最適當的治療？","options":["(A) 牙釉質修形（cosmetic contouring）","(B) 直接複合樹脂貼片（direct composite veneer）","(C) 間接陶瓷貼片（indirect porcelain veneer）","(D) 全瓷冠（all ceramic crown）"],"answer":2,"image":"ya3-114-1-51.jpeg","clinical_level":"一般"},{"id":"ya3-114-1-52","subject":"ya3","topic":"根管治療程序","meta":"114年第1次第52題","year":114,"session":1,"number":52,"question":"執行失活齒內漂白（internal bleaching），進行下列何種處理會增加牙根外吸收（external root resorption）風險？①強光照射 ②加熱處理 ③使用 30%過氧化氫（hydrogen peroxide） ④使用 10%碳 醯胺過氧化物（carbamide peroxide）","options":["(A) ①②③","(B) 僅①②","(C) ①②④","(D) 僅③④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-53","subject":"ya3","topic":"牙科解剖與生理","meta":"114年第1次第53題","year":114,"session":1,"number":53,"question":"下列何者不是內襯黏膜（lining mucosa）？","options":["(A) 頰黏膜（buccal mucosa）","(B) 牙齦（gingiva）","(C) 齒槽黏膜（alveolar mucosa）","(D) 軟腭（soft palate）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-54","subject":"ya3","topic":"牙科解剖與生理","meta":"114年第1次第54題","year":114,"session":1,"number":54,"question":"關於成骨不全症（osteogenesis imperfecta）的敘述，下列何者錯誤？","options":["(A) 大多為體染色體顯性遺傳（autosomal dominant form）","(B) 患者的口腔表徵包括牙本質發育不全（dentinogenesis imperfecta）","(C) 主要為第三型膠原蛋白（type III collagen）的缺陷","(D) 治療藥物包括雙磷酸鹽（biphosphonate）和基因重組人類生長賀爾蒙"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-55","subject":"ya3","topic":"植牙學","meta":"114年第1次第55題","year":114,"session":1,"number":55,"question":"齒槽骨的原始頰舌側水平寬度為 12 mm，牙齒拔除 12 個月後，此無牙區的頰側和舌側將分別喪失多少骨頭？","options":["(A) 2 mm；4 mm","(B) 4 mm；2 mm","(C) 3 mm；2 mm","(D) 3 mm；3 mm"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-56","subject":"ya3","topic":"牙科解剖與生理","meta":"114年第1次第56題","year":114,"session":1,"number":56,"question":"下列何者的趨化作用（chemotaxis）最強？","options":["(A) IL-1β","(B) TNF-α","(C) IL-6","(D) IL-8"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-57","subject":"ya3","topic":"牙科解剖與生理","meta":"114年第1次第57題","year":114,"session":1,"number":57,"question":"細菌 DNA 刺激免疫細胞是透過下列何者辨認（recognizes）DNA 低甲基化（hypomethylated）CpG 區域的作 用？","options":["(A) 類鐸受體-2（TLR-2）","(B) 類鐸受體-4（TLR-4）","(C) 類鐸受體-6（TLR-6）","(D) 類鐸受體-9（TLR-9）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-58","subject":"ya3","topic":"牙周疾病與診斷","meta":"114年第1次第58題","year":114,"session":1,"number":58,"question":"關於牙齦炎患者的診斷，下列敘述何者錯誤？","options":["(A) 在牙周附連組織完整的個體，有無影像上的齒槽骨喪失是用來作為牙齦炎患者的診斷依據之一","(B) 在牙周附連組織降低且曾患有牙周炎的患者，若全口探測流血位點＜10%，探測囊袋深度≦3 mm，則診斷為 牙齦健康個體","(C) 在牙周附連組織降低但未曾患有牙周炎的患者，若全口探測流血位點＜10%，探測囊袋深度≦3 mm，則診斷 為牙齦健康個體","(D) 在牙周附連組織完整的個體，若全口探測流血位點≧10%，探測囊袋深度≦3 mm，則診斷為牙齦炎患者"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-59","subject":"ya3","topic":"牙周疾病與診斷","meta":"114年第1次第59題","year":114,"session":1,"number":59,"question":"在 2017 World Workshop 公布的牙周病新分類中，下列何者不是評估牙周炎級別（Grade）的基本原則？","options":["(A) 不是所有個體對於牙周炎的易感性皆相同","(B) 牙周炎進展和嚴重程度是多項影響因子共同作用的結果","(C) 個體對於病菌感染所引起的宿主反應由單一影響因子調控，會影響臨床表現型","(D) 部分患者需要更為複雜的治療策略來成功治療牙周炎"],"answer":2,"image":"","clinical_level":"重點(深度)"},{"id":"ya3-114-1-60","subject":"ya3","topic":"牙周疾病與診斷","meta":"114年第1次第60題","year":114,"session":1,"number":60,"question":"Papillon-Lefèvre syndrome 病患有嚴重牙周病，與下列何種基因變異有關？","options":["(A) IL-1","(B) TNF-α","(C) Cathepsin C","(D) IL-10"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-61","subject":"ya3","topic":"牙周疾病與診斷","meta":"114年第1次第61題","year":114,"session":1,"number":61,"question":"25 歲病人主訴牙齦紅腫發炎約一年之久，發炎牙齦旁有明顯牙菌斑堆積，但沒有齒槽骨喪失，若將此紅腫的 牙齦切除以組織切片觀察，可見下列何種明顯的變化？","options":["(A) 牙齦組織內有很多的漿細胞（plasma cells）","(B) 牙齦組織內有膠原蛋白（collagen）的增加","(C) 牙齦溝上皮（sulcular epithelium）往牙根端增生（proliferation），形成囊袋上皮","(D) 牙齦溝內有大量巨噬細胞（macrophages）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-62","subject":"ya3","topic":"牙周疾病與診斷","meta":"114年第1次第62題","year":114,"session":1,"number":62,"question":"關於慢性牙周炎的敘述，下列何者錯誤？","options":["(A) 通常患者口腔衛生不佳，有大量牙菌斑及牙結石堆積","(B) 精神壓力會影響慢性牙周炎的疾病進展","(C) 口腔內有製作不良的牙齦下補綴物為促進因子","(D) 未治療的牙齦炎是植體周圍炎的風險指標（risk indicator）之一"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-63","subject":"ya3","topic":"牙周非手術治療","meta":"114年第1次第63題","year":114,"session":1,"number":63,"question":"關於牙周刮匙（periodontal curettes）與鐮刀型結石刮（sickle scalers）的敘述， 下列何者正確？","options":["(A) 一般牙周刮匙刀刃的工作末端區只有一側有切削邊緣（cutting edge）","(B) 與鐮刀型結石刮相比，牙周刮匙較不會造成囊袋組織的撕裂外傷","(C) 所有的鐮刀型結石刮只適合去除前牙的齒齦上牙結石","(D) 鐮刀型結石刮比較適合刮除牙周囊袋上皮，可促進新的附連生成"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-64","subject":"ya3","topic":"牙周非手術治療","meta":"114年第1次第64題","year":114,"session":1,"number":64,"question":"在完全喪失齒間乳頭的廣闊齒間空間處最適合使用何種刷牙工具？","options":["(A) 牙線","(B) 單束毛牙刷","(C) 牙間刷","(D) 牙籤"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-65","subject":"ya3","topic":"牙周疾病與診斷","meta":"114年第1次第65題","year":114,"session":1,"number":65,"question":"Hamp 等學者依據牙根分叉水平方向牙周侵犯的嚴重程度分為 Class I、II、III，下列何者屬於二級的牙根叉 侵犯（Class II furcation involvement）？","options":["(A) 1 mm","(B) 2 mm","(C) 4 mm","(D) 頰舌側分叉侵犯相通（through and through）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-66","subject":"ya3","topic":"牙周手術與再生","meta":"114年第1次第66題","year":114,"session":1,"number":66,"question":"下列那項因素不利於牙根叉侵犯以引導組織再生手術治療的效果？","options":["(A) 牙齦為較厚的表現型（thicker phenotype）","(B) 齒間骨嵴（interdental crest）比牙根叉入口（entrance）靠近牙根尖的方向","(C) 曾經根管治療過，但無根尖病灶","(D) 牙齦邊緣覆蓋住牙根叉入口，無軟組織退縮現象"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-67","subject":"ya3","topic":"牙周手術與再生","meta":"114年第1次第67題","year":114,"session":1,"number":67,"question":"多顆牙齒需作根向移位翻瓣手術（apically displaced flap）時，使用何種縫合法（suture）最佳？","options":["(A) 連續縫合法（continuous suture）","(B) 垂直褥墊式縫合法（vertical mattress suture）","(C) 骨膜縫合法（periosteal suture）","(D) 間斷齒間乳頭縫合法（interrupted interdental suture）"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-68","subject":"ya3","topic":"牙周手術與再生","meta":"114年第1次第68題","year":114,"session":1,"number":68,"question":"下列何者並非骨切除手術（resective osseous surgery）的適應症？","options":["(A) 外生贅骨（exostosis）","(B) 淺的骨陷口（shallow bone crater）","(C) 骨平台（bony ledge）","(D) 三骨壁骨缺損（three-wall bony defect）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-69","subject":"ya3","topic":"牙周手術與再生","meta":"114年第1次第69題","year":114,"session":1,"number":69,"question":"游離牙齦移植體（free gingival graft）置於 periosteum 上後，移植體（gingival graft）會有多少比例 的收縮（shrinkage）？","options":["(A) 20%","(B) 25%","(C) 50%","(D) 75%"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-70","subject":"ya3","topic":"牙周手術與再生","meta":"114年第1次第70題","year":114,"session":1,"number":70,"question":"下列何種翻瓣術適合用於引導組織再生手術（guided tissue regeneration）？","options":["(A) 原始魏德曼翻瓣術（original Widman flap）","(B) 冠向移位翻瓣術（coronally advanced flap）","(C) 根向移位翻瓣術（apically advanced flap）","(D) 改良式魏德曼翻瓣術（modified Widman flap）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-71","subject":"ya3","topic":"牙周非手術治療","meta":"114年第1次第71題","year":114,"session":1,"number":71,"question":"在牙周維護性治療（supportive periodontal therapy）檢查中，何種檢測較能反應目前牙周發炎狀況？","options":["(A) 牙齒搖動度","(B) 牙齦探測流血","(C) X 光檢查齒槽骨高度","(D) 囊袋探測深度"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-72","subject":"ya3","topic":"牙科解剖與生理","meta":"114年第1次第72題","year":114,"session":1,"number":72,"question":"關於牙周病與急性呼吸道感染，下列敘述何者正確？","options":["(A) 社區型肺炎感染與吸入牙周病的感染性厭氧性細菌有關","(B) 住院型肺炎的感染，可能與 Haemophilus influenzae有關","(C) 系統性抗生素給藥，即可有效控制住院型肺炎的感染","(D) 在加護病房（intensive care unit）的被照護者，潛在的肺炎致病菌常出現在頰黏膜上"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-73","subject":"ya3","topic":"牙科解剖與生理","meta":"114年第1次第73題","year":114,"session":1,"number":73,"question":"研究顯示心血管疾病（cardiovascular disease, CVD）與慢性發炎疾病有關聯，下列敘述何者錯誤？","options":["(A) 系統性發炎增高，是 CVD 與牙周病的共同危險因子","(B) 急性的牙周病變、high-density lipoproteins（HDL）是 CVD 的致病因子","(C) 牙周病的炎症反應可以擴散到遠端器官，激發肝臟發生急性反應，從而促進動脈粥樣化形成","(D) 牙周囊袋的發炎潰瘍，使細菌侵入產生的菌血症，是動脈粥樣化形成的原因之一"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-74","subject":"ya3","topic":"牙周非手術治療","meta":"114年第1次第74題","year":114,"session":1,"number":74,"question":"關於進行牙周病治療的時機，下列敘述何者正確？","options":["(A) 經診斷確定無牙周病的患者，應每 3 個月一次預防性回診","(B) 高血壓且確定有心血管疾病的牙周病患者，牙周病治療應該延後","(C) 高血糖 HbA1c：9%的牙周病患，應在血糖控制下降後才可牙周病治療","(D) 在第三孕期執行牙根清創或拔牙處置是安全的"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-75","subject":"ya3","topic":"植牙學","meta":"114年第1次第75題","year":114,"session":1,"number":75,"question":"和自然牙相比之下，植牙周圍會降低觸覺敏感性、反射功能和本體感覺，是因為缺乏下列何種結構？","options":["(A) 齒槽骨","(B) 黏膜","(C) 牙周韌帶","(D) 角化牙齦"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-76","subject":"ya3","topic":"植牙學","meta":"114年第1次第76題","year":114,"session":1,"number":76,"question":"下列關於立即植牙的敘述，何者錯誤？","options":["(A) 減少治療時間","(B) 骨生成效果佳有助於植體與骨接觸","(C) 將來可能需要黏膜牙齦手術以矯正因皮瓣手術而受影響的組織","(D) 在剩餘骨量無法提供植體穩定時，只要無骨內病變，仍可以考慮"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-77","subject":"ya3","topic":"植牙學","meta":"114年第1次第77題","year":114,"session":1,"number":77,"question":"下列何者不是上顎竇提升術（maxillary sinus elevation）的禁忌症？","options":["(A) 上顎竇感染","(B) 上顎後牙區剩餘齒槽骨高度 6 mm","(C) 嚴重過敏性鼻炎（allergic rhinitis）","(D) 上顎竇曾接受過放射線治療"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-78","subject":"ya3","topic":"植牙學","meta":"114年第1次第78題","year":114,"session":1,"number":78,"question":"植體斷裂是臨床上不易處理的併發症，下列何者不是造成的可能原因？","options":["(A) 植體材料的疲乏","(B) 補綴設計的脆弱點","(C) 牙周炎","(D) 磨牙"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-114-1-79","subject":"ya3","topic":"植牙學","meta":"114年第1次第79題","year":114,"session":1,"number":79,"question":"關於植體周圍炎的研究顯示其病理機轉與牙周炎不同，下列何者錯誤？","options":["(A) 植體周圍炎病灶處嗜中性白血球數量較多","(B) 植體周圍炎病灶和生物膜（biofilm）間缺乏表皮襯墊（epithelial lining）","(C) 植體周圍炎和牙周炎囊袋內的牙菌斑主要成分均為革蘭氏陰性厭氧菌","(D) 植體周圍炎病灶處在齒槽骨外有 1 mm 寬的未發炎結締組織"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-114-1-80","subject":"ya3","topic":"植牙學","meta":"114年第1次第80題","year":114,"session":1,"number":80,"question":"當植牙區的頰側角化牙齦寬度少於 2 mm 時，下列何種術式無法保留或增加角化牙齦寬度？","options":["(A) 使用部分厚度皮瓣（partial thickness flap）","(B) 將含有角化牙齦的皮瓣縫合在更接近根尖處","(C) 在牙齦上以「打孔」（punch）切線方式，將植體暴露於口腔中","(D) 使用游離牙齦移植體（free gingival graft）縫合於傷口處"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-1","subject":"ya3","topic":"牙髓診斷與病理","meta":"114年第2次第1題","year":114,"session":2,"number":1,"question":"關於牙髓內免疫細胞的敘述，下列何者正確？","options":["(A) 樹狀突細胞（dendritic cell）是牙髓內抗體呈現細胞（anti-body presenting cell）","(B) 樹狀突細胞（dendritic cell）具有第一型（class I）主要組織相容複合體（major histocompatibility complex, MHC）","(C) 在正常牙髓內可發現細胞毒殺型（cytotoxic）與輔助型（helper）T 淋巴細胞（T lymphocyte）","(D) 樹狀突細胞（dendritic cell）的第一型（class I）主要組織相容複合體（major histocompatibility complex, MHC）與毒殺型（cytotoxic）T 淋巴細胞（T lymphocyte）結合"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-2","subject":"ya3","topic":"牙髓診斷與病理","meta":"114年第2次第2題","year":114,"session":2,"number":2,"question":"關於牙本質的敘述，下列何者正確？","options":["(A) 牙根完成前所生成之牙本質稱為原生牙本質（primary dentin）","(B) 繼生牙本質（secondary dentin）為牙齒萌發後所形成之牙本質，連結原生牙本質（primary dentin）之牙 本質小管","(C) 三度牙本質（tertiary dentin）內沒有牙本質小管，牙本質完全鈣化","(D) 被覆牙本質（mantle dentin）屬於繼生牙本質（secondary dentin）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-3","subject":"ya3","topic":"牙髓診斷與病理","meta":"114年第2次第3題","year":114,"session":2,"number":3,"question":"關於根尖結構的敘述，下列何者錯誤？","options":["(A) 根尖狹窄（apical constriction）距根尖孔（apical foraman）約 0.5～2 mm","(B) 根尖狹窄（apical constriction）與牙骨質牙本質交界（cementodentinal junction）位置相同，也常作 為根管治療工作長度的內參考點","(C) 根尖孔（apical foraman）是一個漏斗狀開口，大部分距解剖牙根尖（anatomic apex）約 0.5～3 mm","(D) 根尖孔（apical foraman）隨著年紀增加，牙骨質堆積使得距根尖的變化量愈大"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-4","subject":"ya3","topic":"牙髓診斷與病理","meta":"114年第2次第4題","year":114,"session":2,"number":4,"question":"根尖周圍炎可以由外因性（exogenous）和內因性因子（endogenous factors）所導致，下列何者為內因性因 子？","options":["(A) 化學劑（chemical agents）","(B) 膽固醇晶體（cholesterol crystals）","(C) 微生物及其毒素（microbes and their toxins）","(D) 異物（foreign bodies）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-5","subject":"ya3","topic":"牙髓診斷與病理","meta":"114年第2次第5題","year":114,"session":2,"number":5,"question":"當發生牙髓感染時，下列何種調理素（opsonin）會包覆細菌以增強吞噬細胞的吞噬作用？","options":["(A) C3a","(B) C3b","(C) C5a","(D) C5b"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-6","subject":"ya3","topic":"牙髓診斷與病理","meta":"114年第2次第6題","year":114,"session":2,"number":6,"question":"對於口腔內出現竇管（intraoral sinus tract）時，最適合用來探測（tracing）病灶來源的馬來膠針 （gutta-percha）是幾號？","options":["(A) ISO ＃20","(B) ISO ＃30","(C) ISO ＃40","(D) ISO ＃50"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-7","subject":"ya3","topic":"牙髓診斷與病理","meta":"114年第2次第7題","year":114,"session":2,"number":7,"question":"急性根尖周圍炎合併膿腫（acute apical periodontitis with abscess formation），其組織中最顯著的細 胞為何？","options":["(A) 巨噬細胞（macrophage）","(B) 嗜中性白血球（neutrophilic leukocyte）","(C) 肥大細胞（mast cell）","(D) 噬骨細胞（osteoclast）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-8","subject":"ya3","topic":"牙齒外傷處理","meta":"114年第2次第8題","year":114,"session":2,"number":8,"question":"當牙齒因外傷造成側向脫位（lateral luxation），下列何者不是它的緊急處理方式？","options":["(A) 根管治療","(B) 咬合調整","(C) 復位","(D) 固定"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-9","subject":"ya3","topic":"牙齒外傷處理","meta":"114年第2次第9題","year":114,"session":2,"number":9,"question":"外傷牙若發生牙根外吸收（external root resorption）時，於根管治療過程中，須在根管中置放何種藥物較 能有效的抑制牙根外吸收的進行？","options":["(A) camphorated parachlorophenol (CMCP)","(B) chlorhexidine","(C) eugenol/iodine","(D) Ca(OH)2"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-10","subject":"ya3","topic":"牙齒外傷處理","meta":"114年第2次第10題","year":114,"session":2,"number":10,"question":"關於牙齒受到半脫位（subluxation）、震盪（concussion）、脫位（luxation）的理學檢查結果，下列敘述 何者錯誤？","options":["(A) 半脫位的牙齒對敲診敏感、牙齒動搖度增加，牙齒沒有位移","(B) 震盪的牙齒對敲診敏感、牙齒動搖度增加，牙齒沒有位移","(C) 脫位的牙齒對敲診敏感、牙齒動搖度增加，同時牙齒有位移","(D) 震盪和半脫位的外傷牙齒在放射根尖片影像通常沒有明顯變化"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-11","subject":"ya3","topic":"根管治療程序","meta":"114年第2次第11題","year":114,"session":2,"number":11,"question":"下列何者不是理想根管封填劑（ideal sealer）的主要特性？","options":["(A) 需具有放射線不透過性（radiopacity）","(B) 良好的封閉效果","(C) 如果需要再治療時能溶於溶劑","(D) 硬化速度較快"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-12","subject":"ya3","topic":"根管治療程序","meta":"114年第2次第12題","year":114,"session":2,"number":12,"question":"關於三氧礦化聚合物（mineral trioxide aggregate, MTA）的敘述，下列何者錯誤？","options":["(A) 硬化機轉為水合作用（hydration），初步硬化時間約 2 小時 45 分鐘","(B) 混合調拌硬化 21 天後抗壓強度（compressive strength）及酸鹼值 pH 才達到最高值","(C) 主成分有 calcium silicate, calcium carbonate, calcium sulfate, calcium aluminate 以及 bismuth oxide","(D) 灰色 MTA 及白色 MTA 的放射線不透過性（radiopacity）相當於 3.04 mm 厚的鋁金屬"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-13","subject":"ya3","topic":"根管器械","meta":"114年第2次第13題","year":114,"session":2,"number":13,"question":"關於音波（sonic）、超音波（ultrasonic）根管器械的敘述，下列何者錯誤？","options":["(A) 目前牙科臨床操作超音波根管器械有壓電式（piezoelectric）與磁振式（magnetostrictive）兩種","(B) 牙髓病科常用壓電式（piezoelectric）超音波根管器械，優點是使用時產熱較磁振式 （magnetostrictive）少","(C) 使用壓電式（piezoelectric）超音波根管器械移除根柱時每次使用 10～15 秒就必須吹風或用水沖洗，以避 免產生熱效應傷害","(D) 音波與超音波根管器械，目前皆廣泛用於根管的擴大與修形"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-14","subject":"ya3","topic":"根管治療程序","meta":"114年第2次第14題","year":114,"session":2,"number":14,"question":"關於次氯酸鈉溶液意外（sodium hypochlorite accidents）的處置，下列何者正確？","options":["(A) 應在意外發生後的數小時和數天內密切追蹤","(B) 立即冰敷並持續數天以減少腫脹","(C) 除了止痛藥，應加開抗生素、抗組織胺（antihistamine）及皮質類固醇（corticosteroids）等藥物","(D) 病患的症狀通常會持續半年以上"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-15","subject":"ya3","topic":"根管器械","meta":"114年第2次第15題","year":114,"session":2,"number":15,"question":"關於通暢銼（patency file）的敘述，下列何者錯誤？","options":["(A) 使用小號 K 型根管銼（K-file），通常是越小越好","(B) 被動地（passively）延伸出根尖孔","(C) 可幫助移除根尖堆積的殘屑（debris）以維持正確工作長度","(D) 這些銼針可能會將污染的牙本質殘屑帶出根尖孔外"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-16","subject":"ya3","topic":"根管治療程序","meta":"114年第2次第16題","year":114,"session":2,"number":16,"question":"下列何種沖洗液無法殺死糞腸球菌（Enterococcus faecalis）？","options":["(A) 5.25%次氯酸鈉（sodium hypochlorite, NaOCl）","(B) 2%氯己定（chlorhexidine, CHX）","(C) MTAD（a mixture of a tetracycline isomer, an acid, and a detergent）","(D) 17%乙二胺四乙酸（ethylenediaminetetraacetic acid, EDTA）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-17","subject":"ya3","topic":"根管治療程序","meta":"114年第2次第17題","year":114,"session":2,"number":17,"question":"使用三種抗生素糊劑（triple antibiotic paste, TAP）或氫氧化鈣做為再生牙髓治療步驟（regenerative endodontic procedures, REPs）的根管內用藥，下列敘述何者錯誤？","options":["(A) TAP 為 ciprofloxacin、metronidazole 與 minocycline 的混合物","(B) 短期使用氫氧化鈣根管用藥，不會顯著降低牙根抗斷裂性質（fracture resistance）","(C) 使用被動超音波沖洗（passive ultrasonic irrigation）可有效移除根管內的 TAP 與氫氧化鈣用藥","(D) 高濃度的 TAP（1000 mg/L）會造成幹細胞毒性"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-18","subject":"ya3","topic":"根管治療程序","meta":"114年第2次第18題","year":114,"session":2,"number":18,"question":"關於發生根管斷離器械（separated instrument）時處置的考量，下列敘述何者正確？","options":["(A) 斷離器械能否移除是決定根管治療預後最重要的影響因素","(B) 可使用編織法（braiding technique），利用數支 H 銼針（H files）纏繞斷離器械而將其取出","(C) 根管擴大至 MAF（master apical file）時發生斷離器械，因斷械較粗不易取出，預後較差","(D) 位於根管彎曲處的斷離器械，通常建議使用 Masserann kit 進行移除"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-19","subject":"ya3","topic":"根尖手術與再治療","meta":"114年第2次第19題","year":114,"session":2,"number":19,"question":"下列何者最不適合使用方形翻瓣（rectangular flap）？","options":["(A) 下顎側門齒根尖手術","(B) 上顎犬齒根尖手術","(C) 下顎大臼齒根尖手術","(D) 上顎正中門齒牙根穿孔修補手術"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-20","subject":"ya3","topic":"根尖手術與再治療","meta":"114年第2次第20題","year":114,"session":2,"number":20,"question":"上顎正中門齒小於 3 mm 的牙根尖病變進行牙根尖手術時，下列何者並非必須使用的材料與器械？","options":["(A) 人工骨材","(B) 牙根尖逆充填材料","(C) 手術縫線","(D) 根尖修形的超音波器械"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-21","subject":"ya3","topic":"根管治療程序","meta":"114年第2次第21題","year":114,"session":2,"number":21,"question":"關於根管治療預後評估的敘述，下列何者錯誤？","options":["(A) 無臨床症狀和牙齦腫脹，可判定為成功根管治療","(B) 根尖周指數（Periapical Index, PAI）為評量根尖病灶 X 光放射線透過度的方法","(C) 根尖周指數（Periapical Index, PAI）最大的放射線透射病灶的評量分為 5 分","(D) 1 年追蹤若根尖病灶 X 光放射線透過度（radiolucency）沒有改變或增大，可視為不成功的根管治療"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-22","subject":"ya3","topic":"根尖手術與再治療","meta":"114年第2次第22題","year":114,"session":2,"number":22,"question":"關於根管再治療，下列敘述何者錯誤？","options":["(A) 目前無明顯證據顯示根管再治療不能一次有效完成","(B) 建議使用次氯酸鈉（NaOCl）合併 17% EDTA 才能有效移除管壁生物膜（biofilm）","(C) 根管次氯酸鈉（NaOCl）沖洗時，沖洗針頭應深入距工作長度少 2 mm，才能較有效移除生物膜（biofilm）","(D) 置放氫氧化鈣才能有效移除生物膜（biofilm）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-23","subject":"ya3","topic":"牙周疾病與診斷","meta":"114年第2次第23題","year":114,"session":2,"number":23,"question":"牙周發炎對牙髓的影響，下列敘述何者錯誤？","options":["(A) 臨床上常見到第 3 或 4 期牙周炎擴散到根尖孔並伴有牙髓壞死的情況","(B) 牙周感染可能經由副根管擴散到牙髓，最常發生在牙根分叉處和靠近根尖處","(C) 牙周病和牙周治療應被視為牙髓炎和牙髓壞死的潛在原因","(D) 牙周病會導致牙髓退化是很明確的共識"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-24","subject":"ya3","topic":"窩洞設計與分類","meta":"114年第2次第24題","year":114,"session":2,"number":24,"question":"牙科治療處置時，下列何者牙齒的剛性（stiffness）最弱？","options":["(A) 咬合面（occlusal）的窩洞修形","(B) 近心咬合面（MO）的窩洞修形","(C) 遠心咬合面（DO）的缺損入口窩洞修形","(D) 近遠心咬合面（MOD）的缺損入口窩洞修形"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-25","subject":"ya3","topic":"窩洞設計與分類","meta":"114年第2次第25題","year":114,"session":2,"number":25,"question":"根管治療後的牙齒，在執行贋復治療時，會在根管內置入根柱（post），關於根柱的敘述，下列何者正確？","options":["(A) 根柱的放置，可以強化（reinforce）齒質","(B) 根柱的目的是用來固持（retain）冠心（core）","(C) 任何根管治療後的牙齒都有放置根柱的必要","(D) 在選定根柱系統後便可以使用牙鑽（drill）將根管製備成符合根柱系統的大小"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-26","subject":"ya3","topic":"根管治療程序","meta":"114年第2次第26題","year":114,"session":2,"number":26,"question":"患者來院就診進行根管治療，診治中不幸發生分離器械（separated instrument）事件，下列何者是錯誤處 置？","options":["(A) 先設法取出","(B) 轉診","(C) 建議拔牙","(D) 主動告知"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-27","subject":"ya3","topic":"牙科解剖與生理","meta":"114年第2次第27題","year":114,"session":2,"number":27,"question":"下列何種唾液成分不具有緩衝（buffering）功能？","options":["(A) 重碳酸鹽（bicarbonate）","(B) 溶解酵素（lysozyme）","(C) 磷酸鹽（phosphate）","(D) 尿素（urea）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-28","subject":"ya3","topic":"牙科解剖與生理","meta":"114年第2次第28題","year":114,"session":2,"number":28,"question":"關於牙齒硬度的敘述，下列何者錯誤？","options":["(A) 越靠近 DEJ 的牙釉質硬度越低","(B) 越靠近 DEJ 的牙本質硬度越高","(C) 越靠近 DEJ 的牙釉質含氟量越高","(D) 年紀越大，牙本質硬度越高"],"answer":2,"image":"","clinical_level":"重點(深度)"},{"id":"ya3-114-2-29","subject":"ya3","topic":"牙科解剖與生理","meta":"114年第2次第29題","year":114,"session":2,"number":29,"question":"關於氟化物使用在預防齲齒的敘述，下列何者錯誤？","options":["(A) 飲水加氟最適當的濃度為 0.7 ppm","(B) 局部塗抹的氟化物產品中，含有 5% sodium flouride 的氟漆（fluoride varnish）效果最好","(C) 高齲齒率的病患，建議每 3 個月進行氟漆的塗抹","(D) 一般含氟牙膏的含氟量約 2,000 ppm"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-30","subject":"ya3","topic":"牙體修形程序","meta":"114年第2次第30題","year":114,"session":2,"number":30,"question":"關於臨床上齲齒移除的敘述，下列何者錯誤？","options":["(A) 臨床上常用 1% acid red 52 做齲齒檢測劑（caries detection solution）","(B) 齲齒檢測劑（caries detection solution）可將細菌染色，確認需要移除的範圍","(C) 在緩慢進展的齲齒病變，應該完全移除軟性牙本質，直至堅固的牙本質為止","(D) 當齲齒的牙本質挖除到只剩堅固的牙本質時，仍然可能有細菌殘留"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-31","subject":"ya3","topic":"窩洞設計與分類","meta":"114年第2次第31題","year":114,"session":2,"number":31,"question":"對於齲齒檢查的敘述，下列何者錯誤？","options":["(A) 低鈣化牙釉質（hypocalcified enamel）在乾燥或潮濕時，都可看到白色斑點","(B) 光滑表面的初期齲齒（smooth-surface incipient caries）在乾燥或潮濕時，都可看到白色斑點","(C) 鄰接面齲齒延伸到牙本質時，在咬合面邊緣嵴有時可見陰影的外觀","(D) 鄰接面牙根表面病灶較易由咬翼片發現"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-32","subject":"ya3","topic":"牙體修形程序","meta":"114年第2次第32題","year":114,"session":2,"number":32,"question":"關於襯底（liner）和基底（base）材料的敘述，下列何者錯誤？","options":["(A) 光聚合氫氧化鈣襯底較傳統型溶解度低","(B) 基底材料的功能為避免牙髓受到熱刺激","(C) 使用氫氧化鈣襯底會降低黏著效果","(D) 襯底材料可以減少咀嚼時局部應力（local stresses）的產生"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-33","subject":"ya3","topic":"黏著與美學修復","meta":"114年第2次第33題","year":114,"session":2,"number":33,"question":"通用型黏著劑（universal adhesives）中含有何種單體可與氫氧磷灰石（hydroxyapatite）間形成奈米層 （nanolayering）？","options":["(A) 10-MDP","(B) 4-META","(C) phynel-P","(D) HEMA"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-34","subject":"ya3","topic":"黏著與美學修復","meta":"114年第2次第34題","year":114,"session":2,"number":34,"question":"關於自酸蝕黏著劑（self-etch adhesives）的敘述，下列何者錯誤？","options":["(A) 底劑中含有酸性單體","(B) 含有 10～30 wt% 水以離子化酸性單體","(C) 不完全移除塗抹層（smear layer）","(D) 不會形成樹脂懸突（resin tag）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-35","subject":"ya3","topic":"黏著與美學修復","meta":"114年第2次第35題","year":114,"session":2,"number":35,"question":"有關三步驟全酸蝕黏著系統（three-step, etch-and-rinse adhesives）的敘述，下列何者正確？","options":["(A) 酸蝕後之氫氧磷灰石（hydroxyapatite）具有低表面能（surface free energy）","(B) 酸蝕後之膠原蛋白（collagen）具有高表面能（surface free energy）","(C) 底劑（primer）的單體主要為親水性單體","(D) 黏著劑（bonding agent）的單體主要為親水性單體"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-36","subject":"ya3","topic":"牙體修形程序","meta":"114年第2次第36題","year":114,"session":2,"number":36,"question":"附圖中鎢鋼（carbide）鑽針類型的敘述，下列何者正確？","options":["(A) 169 號鑽針為①類型","(B) 33 1/2 號鑽針為②類型","(C) 2 號鑽針為③類型","(D) 1/4 號鑽針為④類型"],"answer":1,"image":"ya3-114-2-36.jpeg","clinical_level":"一般"},{"id":"ya3-114-2-37","subject":"ya3","topic":"牙科解剖與生理","meta":"114年第2次第37題","year":114,"session":2,"number":37,"question":"下列何種病患，較不適合使用一般橡皮障（rubber dam）？①心律不整 ②呼吸困難 ③腎功能不良 ④甲 狀腺機能過低 ⑤乳膠過敏","options":["(A) ①②","(B) ③④","(C) ②⑤","(D) ①⑤"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-38","subject":"ya3","topic":"複合樹脂與材料","meta":"114年第2次第38題","year":114,"session":2,"number":38,"question":"在掃雪機技術（snowplow technique）中，首先使用下列何種類型複合樹脂置放於窩洞底層？","options":["(A) 可填塞型（packable composite）","(B) 奈米填料型（nanofilled composite）","(C) 混雜型（hybrid composites）","(D) 流動型（flowable composites）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-39","subject":"ya3","topic":"黏著與美學修復","meta":"114年第2次第39題","year":114,"session":2,"number":39,"question":"前牙複合樹脂窩洞設計中，下列何者不是斜面（bevel）製備的主要功能？","options":["(A) 移除無牙本質支持的牙釉質","(B) 增加美觀","(C) 易於樹脂混色","(D) 增加黏著表面積（bond surface）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-40","subject":"ya3","topic":"複合樹脂與材料","meta":"114年第2次第40題","year":114,"session":2,"number":40,"question":"下列何者可能是導致複合樹脂填補術後敏感的原因？①樹脂聚合收縮 ②黏劑系統（adhesive system）操作 不正確 ③過度修形牙齒 ④使用襯底（liner） ⑤填補後過度修形","options":["(A) 僅①③","(B) 僅①②③⑤","(C) ①②③④⑤","(D) 僅②④⑤"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-41","subject":"ya3","topic":"複合樹脂與材料","meta":"114年第2次第41題","year":114,"session":2,"number":41,"question":"複合樹脂的窩洞設計中，關於斜面（bevel）的操作，下列何者最不適當？","options":["(A) 第三類（Class Ⅲ）窩洞的齲齒若侵犯至牙骨質面時，在牙釉質緣及牙骨質緣皆應有斜面設計","(B) 第四類（Class Ⅳ）窩洞可使用火焰形鑽石磨針，以 45 度角進行修磨邊緣斜面","(C) 第四類（Class Ⅳ）窩洞唇側緣可修磨扇形（scalloped）或非線性的斜面","(D) 第四類（Class Ⅳ）窩洞邊緣斜面寬度約 0.5～2 mm"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-42","subject":"ya3","topic":"複合樹脂與材料","meta":"114年第2次第42題","year":114,"session":2,"number":42,"question":"相較於標準混雜型樹脂（standard hybrid resin composite），關於流動性複合樹脂（flowable resin composite）的敘述，下列何者錯誤？","options":["(A) 聚合收縮較高","(B) 樹脂基質（resin matrix）含量較高","(C) 聚合收縮應力較低","(D) 彈性係數較低"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-43","subject":"ya3","topic":"複合樹脂與材料","meta":"114年第2次第43題","year":114,"session":2,"number":43,"question":"進行複合樹脂第二級窩洞填補時，關於使用隔環（bitine ring）與成型環帶（matrix）的敘述，下列何者最 不適當？","options":["(A) 成型環帶不可超出窩洞之牙齦邊緣（gingival margin）下方 0.5 mm，以免刺激牙齦","(B) 較不適用有鄰接面頰舌側嚴重缺損窩洞","(C) 隔環可分開相鄰牙齒","(D) 隔環放置時可能造成成型環帶變形"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-44","subject":"ya3","topic":"牙體修形程序","meta":"114年第2次第44題","year":114,"session":2,"number":44,"question":"圖中對圍合片（matrix band）進行的動作，稱之為下列何者？","options":["(A) burnishing the matrix band","(B) trimming the matrix band","(C) polishing the matrix band","(D) bending the matrix band"],"answer":0,"image":"ya3-114-2-44.jpeg","clinical_level":"一般"},{"id":"ya3-114-2-45","subject":"ya3","topic":"窩洞設計與分類","meta":"114年第2次第45題","year":114,"session":2,"number":45,"question":"關於汞齊（amalgam）的敘述，下列何者錯誤？","options":["(A) 以粉末的種類分成切削型（lathe-cut）、混合型（admixed）、球型（spheres）","(B) 可經由腐蝕產物（corrosion product）來降低邊緣滲漏","(C) 汞齊中的金屬鍵（metallic bonds）很容易斷裂","(D) 成分中含有約 50%的汞"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-46","subject":"ya3","topic":"黏著與美學修復","meta":"114年第2次第46題","year":114,"session":2,"number":46,"question":"關於瓷嵌／覆體的術後追蹤維護，下列敘述何者錯誤？","options":["(A) 可使用超音波洗牙機清洗表面","(B) 可使用氈輪或橡膠杯配合氧化鋁拋光膏去除表面污漬","(C) 患者可使用中性氟化鈉溶液","(D) 避免咀嚼冰塊和咬指甲"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-47","subject":"ya3","topic":"窩洞設計與分類","meta":"114年第2次第47題","year":114,"session":2,"number":47,"question":"關於金屬冠蓋體（onlay）的裙邊修形（skirt preparation）設計，下列敘述何者錯誤？","options":["(A) 修磨時不可超過牙齒的過渡線角（transitional line angle of the tooth）","(B) 增加補綴物的固持效果（retention）","(C) 會增加金屬露出部分，影響美觀","(D) 可防止牙齒斷裂"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-48","subject":"ya3","topic":"牙體修形程序","meta":"114年第2次第48題","year":114,"session":2,"number":48,"question":"有關鑄金贋復體的咬合調整完成的適當標準，下列敘述何者錯誤？","options":["(A) 贋復體上沒有較重的標記","(B) 咬合調整時儘量保留分布於咬頭斜面（cusp incline）上的咬合點","(C) 贋復體上具有最佳位置和形狀的接觸點","(D) 贋復體與鄰接牙上存在均勻分佈的接觸點"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-49","subject":"ya3","topic":"黏著與美學修復","meta":"114年第2次第49題","year":114,"session":2,"number":49,"question":"關於二氧化鋯（zirconia）復形物，下列敘述何者錯誤？","options":["(A) 不易被磷酸（phosphoric acid）酸蝕","(B) 試戴過程時被口水蛋白污染，可用氫氧化鈉溶液清潔","(C) 噴砂處理會產生單斜（monoclinic）晶相","(D) 不可用樹脂修飾玻璃離子體材料（resin-modified glass ionomer）來黏著"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-50","subject":"ya3","topic":"黏著與美學修復","meta":"114年第2次第50題","year":114,"session":2,"number":50,"question":"製作瓷貼片時，下列何者不是牙釉質內製備（intra-enamel preparation）優於無修磨（no-prep）方式的優 點？","options":["(A) 牙齒修磨量較少，屬於可逆性治療","(B) 黏著強度較高","(C) 貼片邊緣較明確","(D) 可避免貼片外形過度突出（overcontouring）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-51","subject":"ya3","topic":"黏著與美學修復","meta":"114年第2次第51題","year":114,"session":2,"number":51,"question":"關於牙齒形狀對視覺效果的敘述，下列何者錯誤？","options":["(A) 強調牙齦側的釉質橫嵴（gingival perikymata），可讓牙齒視覺上感覺較短","(B) 強調發育溝（developmental depression），可讓牙齒視覺上感覺較長","(C) 減少近心線角與遠心線角的距離，可讓牙齒視覺上感覺較窄","(D) 將外廓高隆線（height of contour）向牙齦方向移動，可讓牙齒視覺上感覺較短"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-52","subject":"ya3","topic":"牙髓診斷與病理","meta":"114年第2次第52題","year":114,"session":2,"number":52,"question":"下列那一個因素不會增加齒內漂白（internal bleaching）後產生牙根外吸收的機率？","options":["(A) 牙周韌帶受到傷害","(B) 齒頸部牙骨質不足（cementum deficiency），牙本質暴露","(C) 使用 10%碳醯胺過氧化物（carbamide peroxide）當漂白劑","(D) 使用加熱來加速漂白速度"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-53","subject":"ya3","topic":"牙科解剖與生理","meta":"114年第2次第53題","year":114,"session":2,"number":53,"question":"成骨不全症（Osteogenesis imperfecta）主要是何種膠原蛋白的缺陷？","options":["(A) 第一型膠原蛋白（Type I collagen）","(B) 第二型膠原蛋白（Type II collagen）","(C) 第三型膠原蛋白（Type III collagen）","(D) 第四型膠原蛋白（Type IV collagen）"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-54","subject":"ya3","topic":"牙周疾病與診斷","meta":"114年第2次第54題","year":114,"session":2,"number":54,"question":"關於牙周韌帶的敘述，下列何者錯誤？","options":["(A) 牙周韌帶空間類似沙漏（hourglass）形狀，最窄的位置為牙根中段部分（mid-root level）","(B) 牙周韌帶寬度接近 0.25 mm，範圍界於 0.2～0.4 mm","(C) 牙周韌帶中的馬拉塞氏（Malassez）上皮細胞為赫威氏上皮根鞘（Hertwig's epithelial root sheath）的 遺跡","(D) 牙周韌帶中的 oxytalan fibers 主要為根尖－咬合面走向，位於較靠近齒槽骨的一側"],"answer":3,"image":"","clinical_level":"重點(深度)"},{"id":"ya3-114-2-55","subject":"ya3","topic":"牙周疾病與診斷","meta":"114年第2次第55題","year":114,"session":2,"number":55,"question":"關於連接上皮（junctional epithelium）構造的敘述，下列何者錯誤？","options":["(A) 基底層組成成分之一的透明層（lamina lucida）提供半胞橋小體（hemidesmosome）的連接","(B) 是一種非角質化的複層鱗狀上皮","(C) 牙周囊袋清創或手術後，連接上皮可以完全修復其原有的構造","(D) 連接上皮藉著內基底層（internal basal lamina）連接到牙齦的結締組織"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-56","subject":"ya3","topic":"牙周疾病與診斷","meta":"114年第2次第56題","year":114,"session":2,"number":56,"question":"危險因子（risk factors）可增加產生疾病（develop the disease）的可能性，下列何者最不屬於牙周疾病 的危險因子？","options":["(A) 吸菸（tobacco smoking）","(B) 糖尿病（diabetes）","(C) 致病菌（pathogenic bacteria）及牙齒的微生物堆積（microbial tooth deposits）","(D) 探測出血（bleeding on probing）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-57","subject":"ya3","topic":"牙周疾病與診斷","meta":"114年第2次第57題","year":114,"session":2,"number":57,"question":"由健康狀態進展成牙周炎的同區微生物群（microbiota），對於微生物變化（microbial shifts）的趨勢， 下列敘述何者錯誤？","options":["(A) 由 rods 轉換成 cocci","(B) 由 nonmotile 轉換成 motile","(C) 由 fermenting 轉換成 proteolytic","(D) 由 facultative anaerobes 轉換成 obligate anaerobes"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-58","subject":"ya3","topic":"牙周疾病與診斷","meta":"114年第2次第58題","year":114,"session":2,"number":58,"question":"在廣泛型侵襲性牙周炎（generalized aggressive periodontitis）中，下列何者相對占較次要角色？","options":["(A) 伴放線桿菌（Aggregatibacter actinomycetemcomitans）","(B) 福賽斯坦納菌（Tannerella forsythia）","(C) 中間普雷沃菌（Prevotella intermedia）","(D) 牙齦卟啉菌（Porphyromonas gingivalis）"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-59","subject":"ya3","topic":"牙周疾病與診斷","meta":"114年第2次第59題","year":114,"session":2,"number":59,"question":"2017 World Workshop 公布的牙周病新分類中，關於評估牙周病分期需先診斷個體是否有牙周炎，下列敘述 何者正確？","options":["(A) 可利用全口平均臨床附連組織喪失達到閾值來認定有無牙周炎","(B) 至少兩顆不同牙齒其鄰接面存在臨床附連組織喪失可認定有牙周炎","(C) 兩顆以上牙齒頰側或舌側面存在臨床附連組織喪失≧3 mm 及牙周囊袋探測深度≧3 mm，可認定有牙周炎","(D) 影像學檢查若無可識別的齒槽骨喪失，可排除個體有牙周炎"],"answer":2,"image":"","clinical_level":"重點(深度)"},{"id":"ya3-114-2-60","subject":"ya3","topic":"牙周疾病與診斷","meta":"114年第2次第60題","year":114,"session":2,"number":60,"question":"在 2017 World Workshop 公布的牙周病新分類中，關於結合牙周炎分期與疾病牙齒分布範圍的敘述，下列何 者正確？","options":["(A) Localized Stage III 代表≦30%的牙位齒間囊袋探測深度≧5 mm","(B) Generalized Stage III 代表≧30%的牙位齒間臨床附連喪失≧5 mm","(C) Localized Stage III 代表≦30%的牙齒齒槽骨喪失超過牙根長度的中間 1/3（middle third）部分","(D) Generalized Stage III 代表≧30%的牙齒齒槽骨喪失超過牙根長度的 50%"],"answer":1,"image":"","clinical_level":"重點(深度)"},{"id":"ya3-114-2-61","subject":"ya3","topic":"牙周疾病與診斷","meta":"114年第2次第61題","year":114,"session":2,"number":61,"question":"在 2017 World Workshop 公布的牙周病新分類中，評估牙周炎級別（Grade）時，關於牙周炎的系統性影響 （systemic impact），下列敘述何者正確？","options":["(A) High sensitivity CRP 是評估 Stage IV 牙周炎病患的重要指標","(B) Grade A：High sensitivity CRP 數值＜0.1 mg/L","(C) Grade B：High sensitivity CRP 數值為 0.1～0.3 mg/L","(D) Grade C：High sensitivity CRP 數值＞0.5 mg/L"],"answer":0,"image":"","clinical_level":"重點(深度)"},{"id":"ya3-114-2-62","subject":"ya3","topic":"牙周疾病與診斷","meta":"114年第2次第62題","year":114,"session":2,"number":62,"question":"比較抽菸者和未抽菸者的牙周臨床疾病表徵之敘述中，下列何者錯誤？","options":["(A) 前者有較深的牙周囊袋","(B) 前者有較多的牙周附連喪失","(C) 前者有較多的齒槽骨破壞","(D) 前者有較嚴重的探測出血"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-63","subject":"ya3","topic":"牙周非手術治療","meta":"114年第2次第63題","year":114,"session":2,"number":63,"question":"關於牙根整平術的敘述，下列何者正確？","options":["(A) 細菌的內毒素會滲入牙骨質中","(B) 牙根整平術時，也會同時移除受感染的牙結石及牙骨質","(C) 超音波洗牙已可將內毒素移除，無需進一步進行牙根整平術","(D) 牙結石是誘發牙周發炎反應的主因，所以應將其移除"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-64","subject":"ya3","topic":"牙周非手術治療","meta":"114年第2次第64題","year":114,"session":2,"number":64,"question":"關於清潔工具的敘述，下列何者錯誤？","options":["(A) 對於中度至重度牙周病患者，相較於牙線，正確使用牙間刷可更有效清除牙菌斑","(B) 根叉處或上顎第一小臼齒的近心側牙根凹陷，使用牙間刷比牙線更能有效清潔","(C) 牙間刷的選擇上，直徑應比牙縫開展（gingival embrasures）來得小","(D) 單束毛牙刷可有效清潔下顎小臼齒及大臼齒的舌側面，以及牙齦嚴重萎縮的牙根表面"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-65","subject":"ya3","topic":"牙周手術與再生","meta":"114年第2次第65題","year":114,"session":2,"number":65,"question":"關於β-三鈣磷酸鹽（β-tricalcium phosphate, β-TCP）的敘述，下列何者錯誤？","options":["(A) 具有骨傳導（osteoconduction）特性","(B) β-TCP 的吸收速度與其化學結構、孔隙（porosity）、顆粒的大小有關","(C) 可作為血小板衍生生長因子-BB（PDGF-BB）的載體","(D) 是一種異體移植骨，具有良好的生物相容性"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-66","subject":"ya3","topic":"牙周疾病與診斷","meta":"114年第2次第66題","year":114,"session":2,"number":66,"question":"關於生物寬度（biologic width）的敘述，下列何者錯誤？","options":["(A) 亦稱為 supracrestal tissue attachment","(B) 連接上皮（junctional epithelium）與結締組織附連（connective tissue attachment）的長度約為 2 mm","(C) 結締組織附連的長度相較於連接上皮有較大的個別差異存在","(D) 固定假牙的邊緣若侵犯到生物寬度，牙齦常有發炎的情形"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-67","subject":"ya3","topic":"牙周手術與再生","meta":"114年第2次第67題","year":114,"session":2,"number":67,"question":"移植骨內含的物質能誘導鄰近的細胞轉化為造骨細胞（osteoblasts），以促進新骨生成，屬於下列何種特 性？","options":["(A) 骨發生（osteogenesis）","(B) 骨整合（osseointegration）","(C) 骨傳導（osteoconduction）","(D) 骨誘導（osteoinduction）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-68","subject":"ya3","topic":"牙周手術與再生","meta":"114年第2次第68題","year":114,"session":2,"number":68,"question":"關於生長因子骨成形蛋白（bone morphogenetic proteins, BMPs）的敘述，下列何者錯誤？","options":["(A) 屬於 transforming growth factor-α superfamily 中的生長因子","(B) BMP-2 具有促進骨生成的能力","(C) BMP-7 又稱作 osteogenic protein-1","(D) BMP-3 又稱作 osteogenin"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-69","subject":"ya3","topic":"牙周疾病與診斷","meta":"114年第2次第69題","year":114,"session":2,"number":69,"question":"造成頰側牙齦萎縮（gingival recession）最常見的原因為下列何者？","options":["(A) 太過用力的刷牙方式","(B) 牙菌斑引起的發炎反應","(C) 補綴物的邊緣放置在牙齦下","(D) 矯正治療"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-70","subject":"ya3","topic":"牙周手術與再生","meta":"114年第2次第70題","year":114,"session":2,"number":70,"question":"關於改良式冠向移前管道術（modified coronally advanced tunnel, MCAT）的敘述，下列何者正確？","options":["(A) 與 Allen（1994）及 Zabalegui 等人（1999）提出之管道術（tunnel technique）的不同在於，此術式的上 皮下結締組織移植（subepithelial connective tissue graft）沒有被翻瓣覆蓋住","(B) 在 Cairo 牙齦退縮分類中 RT1、RT2 及 RT3，均可達成完全牙根覆蓋（complete root coverage）","(C) 在下顎前牙區域常因翻瓣的張力增加，造成前庭深度變淺或翻瓣開裂（flap dehiscence）","(D) 翻瓣內緣的上皮組織不建議移除"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-71","subject":"ya3","topic":"牙周手術與再生","meta":"114年第2次第71題","year":114,"session":2,"number":71,"question":"做牙周再生手術時，何種縫合法可確保牙周翻瓣有較好的貼合度？","options":["(A) 間斷縫合法（interrupted suture）","(B) 連續縫合法（continuous suture）","(C) 懸吊式縫合法（suspensory suture）","(D) 改良式褥墊縫合法（modified mattress suture）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-72","subject":"ya3","topic":"牙周非手術治療","meta":"114年第2次第72題","year":114,"session":2,"number":72,"question":"在牙周維護性治療（supportive periodontal therapy），下列何種情況不可以視為失敗中的病例（failing case）？","options":["(A) 從 X 光檢查中發現骨喪失增加","(B) 從臨床檢查中發現牙齒搖動度增加","(C) 從臨床檢查中發現牙齦紅腫發炎且囊袋探測時會流血","(D) 從臨床檢查中發現有殘餘牙周囊袋"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-114-2-73","subject":"ya3","topic":"牙科解剖與生理","meta":"114年第2次第73題","year":114,"session":2,"number":73,"question":"動物研究顯示心血管疾病與慢性發炎疾病有關，同樣罹患牙周炎下，給與高膽固醇飲食 13 週後，其動脈粥樣 化病變（atheroma）為正常飲食的幾倍？","options":["(A) 1.5","(B) 2","(C) 3","(D) 4"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-74","subject":"ya3","topic":"牙科解剖與生理","meta":"114年第2次第74題","year":114,"session":2,"number":74,"question":"牙周病患者於妊娠期間接受牙周病治療，對於降低妊娠併發症的影響，下列敘述何者錯誤？","options":["(A) 牙周病治療可以降低約 50%的不良妊娠（adverse pregnancy outcome）","(B) 系統性文獻回顧及統合分析顯示：牙周病治療可以有效降低周產期死亡風險","(C) 非手術性的牙周療程對第二孕期是安全的，且治療越早介入越好","(D) 妊娠期牙周治療可降低早產的風險，並改善出生體重"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-75","subject":"ya3","topic":"牙周手術與再生","meta":"114年第2次第75題","year":114,"session":2,"number":75,"question":"對於控制良好的糖尿病患者，在下顎第一大臼齒遠心側有三壁骨缺損，其最適合的治療方式為下列何者？","options":["(A) 直接進入定期維護","(B) 進行翻瓣手術並放入骨粉等材料","(C) 切除遠心根並行 socket preservation","(D) 進行牙周再生手術（periodontal regeneration）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-76","subject":"ya3","topic":"植牙學","meta":"114年第2次第76題","year":114,"session":2,"number":76,"question":"下列何項不是延遲植牙（delayed implant placement）的優點？","options":["(A) 避免拔牙區的感染","(B) 植牙區有足夠的軟組織可關閉傷口","(C) 可降低黏膜牙齦皮瓣手術的必要性","(D) 可省去修補植體周圍骨缺損所需的引導骨再生術"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-77","subject":"ya3","topic":"植牙學","meta":"114年第2次第77題","year":114,"session":2,"number":77,"question":"關於植體周圍疾病治療的敘述，下列何者錯誤？","options":["(A) 植體周圍黏膜炎的治療是有效的","(B) 植體周圍炎的治療是不可預測的","(C) 植體周圍炎疾病的預防、早期發現和治療對於成功結果至關重要","(D) 相對於粗糙植體表面，光滑植體表面的去污或消毒是較困難的"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-78","subject":"ya3","topic":"植牙學","meta":"114年第2次第78題","year":114,"session":2,"number":78,"question":"健康的人工植牙周圍骨頭高度在第一年吸收 1～1.5 mm 後，每年平均約吸收多少的量？","options":["(A) 0.1 mm or less","(B) 0.1～0.2 mm","(C) 0.2～0.3 mm","(D) 0.3～0.4 mm"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-79","subject":"ya3","topic":"植牙學","meta":"114年第2次第79題","year":114,"session":2,"number":79,"question":"關於植體檢查維護的敘述，下列何者錯誤？","options":["(A) 植體探測深度的價值主要在於觀察經過一段時間後深度的變化而非其初始深度","(B) 植體探測深度可能受到探針粗細、探針插入角度、植體贋復物設計等影響而有所不同","(C) 植體動搖度（mobility）檢查對檢測失敗或是喪失骨整合的植體具有高度敏感性（sensitivity）","(D) 對有感染跡象的植體做細菌培養的價值在於讓臨床醫師可以針對培養出的菌種投與適當的抗生素"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-114-2-80","subject":"ya3","topic":"植牙學","meta":"114年第2次第80題","year":114,"session":2,"number":80,"question":"在獲取頦（chin）自體骨時，一般要求取骨厚度不要超過多少 mm？","options":["(A) 3","(B) 4","(C) 5","(D) 6"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-1","subject":"ya3","topic":"牙髓診斷與病理","meta":"115年第1次第1題","year":115,"session":1,"number":1,"question":"病人至醫院求診，主訴為最近這兩天右側牙齒自發性疼痛。自陳昨晚痛到睡不著，今早喝了熱咖啡，右側後排 牙齒更痛，時間超過 1 分鐘。此疼痛為牙髓內何種神經所引發？","options":["(A) A-delta 神經纖維","(B) A-beta 神經纖維","(C) C 神經纖維","(D) A-alpha 神經纖維"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-2","subject":"ya3","topic":"牙髓診斷與病理","meta":"115年第1次第2題","year":115,"session":1,"number":2,"question":"下列由牙釉質（enamel）往牙髓主體（pulp proper）方向之組織細胞排列順序何者正確？①造牙本質細胞 （odontoblast） ②牙本質（dentin） ③牙本前質（predentin） ④多細胞區（cell-rich zone） ⑤少 細胞區（cell-poor zone）","options":["(A) ③②①⑤④","(B) ②③①⑤④","(C) ②③①④⑤","(D) ③②①④⑤"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-3","subject":"ya3","topic":"根管治療程序","meta":"115年第1次第3題","year":115,"session":1,"number":3,"question":"下列何種根管封填糊劑的細胞毒性最強？","options":["(A) resin sealer","(B) calcium silicate sealer","(C) eugenol-type sealer","(D) paraformaldehyde sealer"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-4","subject":"ya3","topic":"牙髓診斷與病理","meta":"115年第1次第4題","year":115,"session":1,"number":4,"question":"有關牙根垂直縱裂（vertical root fracture）之敘述，下列何者錯誤？","options":["(A) 裂縫起源於根管內壁，向牙根表面蔓延","(B) 好發於曾接受根管治療的牙齒","(C) 好發於下顎大臼齒的近心牙根","(D) 裂縫起源於牙冠，向根尖方向蔓延"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-5","subject":"ya3","topic":"牙齒外傷處理","meta":"115年第1次第5題","year":115,"session":1,"number":5,"question":"關於外傷造成牙根炎性外吸收（external inflammatory root resorption）的敘述，下列何者正確？","options":["(A) 根管治療即可停止牙根炎性外吸收","(B) 牙髓壞死即可造成牙根炎性外吸收","(C) 牙根炎性外吸收通常在牙髓仍有活性時發生","(D) 牙髓壞死合併牙骨質損傷時，容易造成牙根炎性外吸收"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-6","subject":"ya3","topic":"牙科解剖與生理","meta":"115年第1次第6題","year":115,"session":1,"number":6,"question":"對有藥物引起之顎骨壞死（medication-related osteonecrosis of jaw, MRONJ）風險的病患進行根管治療 時，下列何者不是降低其發生風險的方式？","options":["(A) 治療前使用口樂舒汀（chlorhexidine）漱口一分鐘以降低口內細菌量","(B) 避免使用含有血管收縮素（vasoconstrictor）的麻藥以減少破壞組織血液循環","(C) 放置橡皮障（rubber dam）以達到無菌操作","(D) 經常確認根尖通暢性（patency）以達到徹底的根管清潔降低感染風險"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-7","subject":"ya3","topic":"根管治療程序","meta":"115年第1次第7題","year":115,"session":1,"number":7,"question":"關於根管治療過程發生平台（ledge）的敘述，下列何者錯誤？","options":["(A) 根管彎曲越大，發生平台機率越高","(B) 細窄根管較容易發生平台","(C) 工作長度短的根管較容易發生平台","(D) 根管修形過程沖洗不足可能導致平台發生"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-8","subject":"ya3","topic":"牙髓診斷與病理","meta":"115年第1次第8題","year":115,"session":1,"number":8,"question":"關於近來大量用於診斷與治療的牙科錐束電腦斷層掃描（cone beam computed tomography, CBCT）的敘述， 下列何者錯誤？","options":["(A) 相較於醫用電腦斷層掃描（MDCT），病患所接收到的放射線曝光劑量範圍比較少","(B) 可以協助臨床醫師決定該患齒是否要採取手術或非手術治療","(C) 對於所有需要評估是否要根管再治療的個案都應該採用斷層分析","(D) 大幅提升在牙根尖與周圍組織的判讀能力"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-9","subject":"ya3","topic":"牙周疾病與診斷","meta":"115年第1次第9題","year":115,"session":1,"number":9,"question":"顎齦溝（palatogingival grooves）屬於發育異常，關於顎齦溝的敘述，下列何者錯誤？","options":["(A) 常見於上顎門牙區，臨床上很容易辨別","(B) 上顎正中門齒的發生率明顯高於上顎側門齒","(C) 如果牙根表面的局部牙周破壞延伸到根尖，會導致牙髓病變","(D) 臨床上如果出現有症狀的牙周問題，通常預後不佳"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-10","subject":"ya3","topic":"醫學倫理與法規","meta":"115年第1次第10題","year":115,"session":1,"number":10,"question":"現今普遍以電子紀錄（electronic records）方式記錄並儲存病患資料。關於這些資料的儲存與使用，應該 注意的事項，下列敘述何者錯誤？","options":["(A) 需保密的病患資料包含數位放射線影像（digital radiographs）以及帳目（account ledgers）等等","(B) 只有臨床醫師（clinician）和經授權的醫院員工（authorized staff）可以看到病患的資料","(C) 可以考慮以高級加密標準（Advanced Encryption Standard, AES）保護病患隱私","(D) 若有多份備份資料（multiple copies of backup data）時，應存放於同一資料室的不同櫃子中"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-11","subject":"ya3","topic":"牙髓診斷與病理","meta":"115年第1次第11題","year":115,"session":1,"number":11,"question":"在急性根尖周圍炎（acute apical periodontitis）中嗜中性多形核白血球（polymorphonuclear neutrophilic leukocytes）的量何時達到最多？","options":["(A) 6～12 小時","(B) 13～23 小時","(C) 24～48 小時","(D) 49～72 小時"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-12","subject":"ya3","topic":"牙髓診斷與病理","meta":"115年第1次第12題","year":115,"session":1,"number":12,"question":"下列何者屬於引起根尖周圍炎的物理刺激？","options":["(A) 過度封填（overfilling）","(B) 根管內用藥（intracanal medication）","(C) 沖洗液（irrigants）","(D) 根管封填材料（root canal filling materials）"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-13","subject":"ya3","topic":"牙髓診斷與病理","meta":"115年第1次第13題","year":115,"session":1,"number":13,"question":"病患求診抱怨下顎右側第一大臼齒不舒服，有自發性疼痛、咬合疼痛、敲診及觸診檢查有劇烈疼痛，冷、熱 及電髓測試有反應，X 光片顯示無根尖病變。下列何者為最可能的診斷？","options":["(A) 牙髓炎引起的症狀型根尖周圍炎（symptomatic apical periodontitis）","(B) 牙髓壞死引起的症狀型根尖周圍炎（symptomatic apical periodontitis）","(C) 牙髓炎引起的急性根尖膿腫（acute apical abscess）","(D) 牙髓壞死引起的急性根尖膿腫（acute apical abscess）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-14","subject":"ya3","topic":"牙齒外傷處理","meta":"115年第1次第14題","year":115,"session":1,"number":14,"question":"外傷造成脫位（luxation）的牙齒，若產生變色（discoloration）情形，下列敘述何者錯誤？","options":["(A) 僅外傷數天後即可能產生變色","(B) 牙齒起初略呈粉紅色漸轉灰暗色，失去透光度","(C) 變色的牙齒一般顏色不可回復，需進行根管治療","(D) 可能與鈣化變態（calcific metamorphosis）有關的，呈現黃褐色傾向"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-15","subject":"ya3","topic":"牙齒外傷處理","meta":"115年第1次第15題","year":115,"session":1,"number":15,"question":"如臨床圖與Ｘ光片影像，患者於數年前因車禍外傷，當時進行 tooth 11, 12 的根管治療，目前無任何臨床症 狀。tooth 11 牙根狀況的診斷，下列敘述何者最適當？","options":["(A) 正常","(B) 表面吸收（surface resorption）","(C) 取代性吸收（replacement resorption）","(D) 炎性外吸收（external inflammatory resorption）"],"answer":2,"image":"ya3-115-1-15.jpeg","clinical_level":"一般"},{"id":"ya3-115-1-16","subject":"ya3","topic":"根管器械","meta":"115年第1次第16題","year":115,"session":1,"number":16,"question":"下列何組器械容易在整理時弄錯號數？","options":["(A) K-file #20，K-file #60","(B) H-file #40，H-file #90","(C) K-file #35，K-file #70","(D) H-file #25，H-file #45"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-17","subject":"ya3","topic":"根管器械","meta":"115年第1次第17題","year":115,"session":1,"number":17,"question":"關於電子根尖定位儀（electronic apex locater）的敘述，下列何者正確？","options":["(A) 根管內的組織狀態會對根管長度測定器的判讀有影響","(B) 根管外吸收未達到內壁不會對根管長度測定器的判讀有影響","(C) 合併使用 X 光片判讀根管長度並不會增加準確性","(D) 不適用於有裝心律調節器的患者"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-18","subject":"ya3","topic":"牙科解剖與生理","meta":"115年第1次第18題","year":115,"session":1,"number":18,"question":"在施行根管治療或補綴治療時常用的局部麻醉藥物（local anesthetics）的建議最大劑量（typical maximum dose），下列何者正確？","options":["(A) 2% Lidocaine, 1:100,000 epinephrine, 13 cartridges","(B) 2% Lidocaine, 1:50,000 epinephrine, 8 cartridges","(C) 4% Articaine, 1:100,000 epinephrine, 10 cartridges","(D) 4% Articaine, 1:200,000 epinephrine, 10 cartridges"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-19","subject":"ya3","topic":"牙髓診斷與病理","meta":"115年第1次第19題","year":115,"session":1,"number":19,"question":"下列那一種錐狀射束電腦斷層掃描（cone beam computed tomography, CBCT）設定，較適用於拍攝單顆需牙 髓治療的牙齒？","options":["(A) 大視野（field of view, FOV），大體素（voxel size）","(B) 大視野（field of view, FOV），小體素（voxel size）","(C) 小視野（field of view, FOV），大體素（voxel size）","(D) 小視野（field of view, FOV），小體素（voxel size）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-20","subject":"ya3","topic":"根管治療程序","meta":"115年第1次第20題","year":115,"session":1,"number":20,"question":"關於根管治療的醫源性意外的處置考量，下列何者錯誤？","options":["(A) 將根管往根管反彎曲方向（anticurvature direction）開展，有助於繞道平台（bypass ledge）","(B) 封填超出根尖孔的馬來膠（gutta-percha）可使用尤加利油（eucalyptol）與 H 銼針（H file）來移除","(C) 當根管過度充填（extrusion of obturation）造成根尖組織破壞與發炎時，可考慮使用類固醇藥物治療","(D) 使用超音波器械移除斷離的鎳鈦器械，需小心發生鎳鈦器械再斷裂的情況"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-21","subject":"ya3","topic":"根管治療程序","meta":"115年第1次第21題","year":115,"session":1,"number":21,"question":"有關氫氧化鈣 Ca(OH)2 於根管用藥的敘述，下列何者正確？","options":["(A) 氫氧化鈣的 pH 值低，具有殺菌的效果","(B) 螺旋渦針（lentulo spiral）以逆時針方向置放氫氧化鈣","(C) 氫氧化鈣有助於溶解壞死組織與破壞細菌與其附產物","(D) 氫氧化鈣置放在根管腔具有止痛的效果"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-22","subject":"ya3","topic":"根尖手術與再治療","meta":"115年第1次第22題","year":115,"session":1,"number":22,"question":"根尖手術進行麻醉時，下列敘述何者正確？","options":["(A) 和非手術性治療一樣，麻醉考量都是以止痛為唯一目的","(B) 從麻醉到開始進行手術，時間不宜超過 10 分鐘，以維持麻醉效果","(C) 翻瓣後的補充麻醉，通常麻醉效果較差","(D) 上顎比下顎更需要長效型的麻醉"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-23","subject":"ya3","topic":"根尖手術與再治療","meta":"115年第1次第23題","year":115,"session":1,"number":23,"question":"根尖手術時使用含腎上腺素（epinephrine）較高濃度的麻藥，主要是要利用何種特性？","options":["(A) 作用於齒槽黏膜（alveolar mucosa）上的α接受器，達到血管收縮的目的","(B) 作用於骨骼肌上的β接受器","(C) 腎上腺素有麻醉效果","(D) 腎上腺素可減緩代謝速率，延長麻藥作用時間"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-24","subject":"ya3","topic":"根尖手術與再治療","meta":"115年第1次第24題","year":115,"session":1,"number":24,"question":"根據 Sjögren 等學者的研究發現，依其成功率由大而小排列，下列三項依序為何？①在齒內治療前，齒髓為 活性 ②在齒內治療前，齒髓為壞死且牙根周圍有病變 ③重新治療的牙齒且牙根周圍有病變","options":["(A) ①＞②＞③","(B) ②＞①＞③","(C) ①＝②＞③（①和②沒有差別，但成功率＞③）","(D) ①＝②＝③（沒有差別）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-25","subject":"ya3","topic":"牙周手術與再生","meta":"115年第1次第25題","year":115,"session":1,"number":25,"question":"強逼萌出術（forced eruption）可以增加臨床牙冠長度，關於強逼萌出術的敘述，下列何者錯誤？","options":["(A) 適用於垂直牙根斷裂的牙齒","(B) 單牙根的治療效果比多牙根好","(C) 強逼萌出量＜4 mm 較容易成功","(D) 可以保留相鄰的牙齒結構"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-26","subject":"ya3","topic":"根尖手術與再治療","meta":"115年第1次第26題","year":115,"session":1,"number":26,"question":"關於根管再治療（endodontic retreatment），下列敘述何者正確？","options":["(A) 在初始治療（primary endodontic treatment）後，因為病灶未癒合、根管疾病復發並產生新的疾病與併發 症等原因，可考慮是否進行再治療","(B) 再治療可分為下列幾種方向：牙根尖手術（apical surgery）、半切斷術（hemisection）、蓄意再植 （intentional replantation）及拔牙（extraction）","(C) 當牙周狀況穩定，有保存適當的齒質，並且沒有垂直性牙齒斷裂時，可以考慮做手術性的再治療","(D) 非手術性的再治療擁有較低的風險，並且不會在治療的過程中移除更多的齒質"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-27","subject":"ya3","topic":"牙髓診斷與病理","meta":"115年第1次第27題","year":115,"session":1,"number":27,"question":"當齲齒接近牙髓時，若牙齒受到較大刺激，類牙本質細胞（odontoblast-like cell）會形成何種牙本質？","options":["(A) 原生牙本質（primary dentin）","(B) 繼生牙本質（secondary dentin）","(C) 修復性三度牙本質（reparative tertiary dentin）","(D) 反應性三度牙本質（reactionary tertiary dentin）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-28","subject":"ya3","topic":"窩洞設計與分類","meta":"115年第1次第28題","year":115,"session":1,"number":28,"question":"相較於完整牙齒，具大型近心－咬合－遠心（M-O-D）二級窩洞之牙齒，其牙冠的堅硬度（stiffness）會減 少約多少百分比？","options":["(A) 10%","(B) 30%","(C) 60%","(D) 80%"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-29","subject":"ya3","topic":"黏著與美學修復","meta":"115年第1次第29題","year":115,"session":1,"number":29,"question":"利用基質（substrate）上不規則的粗糙表面所形成的黏著（adhesion），稱為下列何者？","options":["(A) 機械（mechanical）黏著","(B) 吸附（adsorption）黏著","(C) 擴散（diffusion）黏著","(D) 靜電（electrostatic）黏著"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-30","subject":"ya3","topic":"窩洞設計與分類","meta":"115年第1次第30題","year":115,"session":1,"number":30,"question":"下列各個窩洞壁（cavity walls）中，何者被稱為內壁（internal wall）？","options":["(A) 舌壁（lingual wall）","(B) 頰壁（buccal wall）","(C) 唇壁（labial wall）","(D) 軸壁（axial wall）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-31","subject":"ya3","topic":"複合樹脂與材料","meta":"115年第1次第31題","year":115,"session":1,"number":31,"question":"下列那一種物質會抑制複合樹脂的聚合？","options":["(A) Bisphenol A ethoxylated dimethacrylate（Bis-EMA）","(B) Benzoyl peroxide","(C) Camphorquinone","(D) Eugenol"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-32","subject":"ya3","topic":"窩洞設計與分類","meta":"115年第1次第32題","year":115,"session":1,"number":32,"question":"金屬冠蓋體的牙齒修形過程中，包覆功能性咬頭的終接線（finishing line），下列何者最為適當？","options":["(A) shoulder","(B) beveled shoulder","(C) chamfer","(D) knife-edged"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-33","subject":"ya3","topic":"黏著與美學修復","meta":"115年第1次第33題","year":115,"session":1,"number":33,"question":"關於牙齒漂白藥劑碳醯胺過氧化物（carbamide peroxide）的敘述，下列何者錯誤？","options":["(A) 常用於居家漂白（home bleaching）及齒內漂白（internal bleaching）","(B) 10%濃度的 carbamide peroxide 可分解出約 3.5%的過氧化氫（hydrogen peroxide）","(C) 由 carbamide peroxide 分解出的尿素（urea）會降低口內的 pH 值，增加蛀牙機率","(D) carbamide peroxide 的活性可維持 10 小時，但約 50%的活性在 2 小時內作用消耗掉"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-34","subject":"ya3","topic":"窩洞設計與分類","meta":"115年第1次第34題","year":115,"session":1,"number":34,"question":"對於不同齲齒風險成人的介入處理，下列敘述何者錯誤？","options":["(A) 高風險：每 3 個月門診口腔檢查和預防，每 6～12 個月進行一次咬翼 X 光檢查","(B) 中度風險：每 4～6 個月門診口腔檢查和預防，每次回診時都塗氟","(C) 低風險：每 9～12 個月門診口腔檢查和預防","(D) 低風險：居家使用含 5,000 ppm NaF 的含氟牙膏"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-35","subject":"ya3","topic":"牙髓診斷與病理","meta":"115年第1次第35題","year":115,"session":1,"number":35,"question":"關於牙本質齲齒區域（zones of dentin caries）受影響層（affected zone）的敘述，下列何者錯誤？","options":["(A) 無需完全移除","(B) 涵蓋半透明層（translucent zone）","(C) 膠原交鏈（collagen cross-linking）仍完整","(D) 特徵為管周牙本質（peritubular dentin）的去礦化"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-36","subject":"ya3","topic":"窩洞設計與分類","meta":"115年第1次第36題","year":115,"session":1,"number":36,"question":"臨床上關於口內已存在的舊銀粉復形物（amalgam restorations）檢查發現中，下列何者最不需要重新置換 填補？","options":["(A) 在咬合面峽區域（occlusal isthmus）上有斷裂線","(B) 在頰側面有深度 0.4 mm 的銀粉邊緣溝（amalgam marginal ditching）","(C) 在牙齦 1/3 區域有 0.4 mm 的孔洞（void）","(D) 在鄰接面有突出物（proximal overhang）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-37","subject":"ya3","topic":"窩洞設計與分類","meta":"115年第1次第37題","year":115,"session":1,"number":37,"question":"下列有關齲齒治療計畫的階段排序，何者正確？①擬訂預防與處理齲齒計畫 ②仔細檢查致齲危險因素 ③ 全口檢查，確認齲齒部位、深度、大小及活躍性 ④決定處理齲齒病灶的方法","options":["(A) ①④②③","(B) ②①③④","(C) ③②①④","(D) ④①③②"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-38","subject":"ya3","topic":"黏著與美學修復","meta":"115年第1次第38題","year":115,"session":1,"number":38,"question":"關於黏著（adhesion）的敘述，下列何者正確？","options":["(A) 化學黏著力僅發生在牙釉質之氫氧磷灰石（hydroxyapatite）","(B) 黏著劑的表面張力需比牙釉質或牙本質表面能高才會有好的黏著力","(C) 牙科黏著劑必須提供好的初始黏著力以抵抗後續的樹脂收縮力","(D) 金屬與高分子聚合物間不會有任何黏著力"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-39","subject":"ya3","topic":"黏著與美學修復","meta":"115年第1次第39題","year":115,"session":1,"number":39,"question":"有關底劑（primer）和黏著劑（adhesive）合一的第五代牙本質黏著劑操作方式，下列何者錯誤？","options":["(A) 單次塗的愈厚，鍵結強度（bond strength）愈強","(B) 塗後以壓縮的空氣吹薄，是為確保溶劑完全蒸發","(C) 塗後以壓縮的空氣吹薄，再塗一次可增加鍵結強度（bond strength）","(D) 塗的太薄會降低鍵結強度（bond strength）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-40","subject":"ya3","topic":"窩洞設計與分類","meta":"115年第1次第40題","year":115,"session":1,"number":40,"question":"圖片中①②③④所指的位置名稱，下列何者正確？","options":["(A) ①為 occlusal wall","(B) ②為 axial wall","(C) ③為 pulpal wall","(D) ④為 gingival wall"],"answer":3,"image":"ya3-115-1-40.jpeg","clinical_level":"一般"},{"id":"ya3-115-1-41","subject":"ya3","topic":"複合樹脂與材料","meta":"115年第1次第41題","year":115,"session":1,"number":41,"question":"有關混雜型複合樹脂（hybrid composites）的敘述，下列何者錯誤？","options":["(A) 年磨耗量約 1～5 μm，遠低於汞齊","(B) 適合於填補前牙窩洞","(C) 填料含量高於微粒型（microfill composites）複合樹脂","(D) 物理性質優於微粒型（microfill composites）複合樹脂"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-42","subject":"ya3","topic":"複合樹脂與材料","meta":"115年第1次第42題","year":115,"session":1,"number":42,"question":"如下圖的前牙鄰接面窩洞，使用何種樹脂有助於改善填補後的透視現象（show through effect）？","options":["(A) 奈米混合型樹脂（nanohybrid composite）","(B) 微粒型樹脂（mirofilled composite）","(C) 不透光的樹脂（opaque resin）","(D) 塊填樹脂(bulkfill composite)"],"answer":2,"image":"ya3-115-1-42.jpeg","clinical_level":"一般"},{"id":"ya3-115-1-43","subject":"ya3","topic":"牙體修形程序","meta":"115年第1次第43題","year":115,"session":1,"number":43,"question":"下列有關前牙樹脂填補的步驟，依序應為何者？①完成（finishing） ②比色 ③窩洞製備 ④橡皮障隔濕 ⑤樹脂充填 ⑥拋光","options":["(A) ④③②⑤⑥①","(B) ②④③⑤①⑥","(C) ③②④⑤①⑥","(D) ②④③⑤⑥①"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-44","subject":"ya3","topic":"窩洞設計與分類","meta":"115年第1次第44題","year":115,"session":1,"number":44,"question":"關於中型的第一類（class Ⅰ）複合樹脂窩洞製備，下列敘述何者最不適當？","options":["(A) 小臼齒至少保留 1.5 mm 的邊緣嵴寬度","(B) 大臼齒至少保留 2 mm 的邊緣嵴寬度","(C) 咬合面邊緣建議修磨斜面（bevel）","(D) 初步的進入深度大約自中央溝向牙髓方向 1.5 mm 深"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-45","subject":"ya3","topic":"複合樹脂與材料","meta":"115年第1次第45題","year":115,"session":1,"number":45,"question":"下列何者不是可以減少複合樹脂聚合收縮應力的方法？","options":["(A) soft-start 光照聚合","(B) 以流動性樹脂填補","(C) 分層（incremental）填補","(D) 使用玻璃離子黏合劑襯底"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-46","subject":"ya3","topic":"窩洞設計與分類","meta":"115年第1次第46題","year":115,"session":1,"number":46,"question":"關於汞齊合金（amalgam）的敘述，下列何者錯誤？","options":["(A) 適當的汞齊腐蝕產物有助於封閉與牙齒間的微滲漏（microleakage）","(B) 添加鋅（zinc）至汞齊會降低機械強度","(C) 混合型（admixed）汞齊的填壓力道應高於球型（spherical）汞齊","(D) 高銅汞齊的γ2 相較低銅汞齊少"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-47","subject":"ya3","topic":"窩洞設計與分類","meta":"115年第1次第47題","year":115,"session":1,"number":47,"question":"關於汞齊填補物（amalgam restoration）的敘述，下列何者錯誤？","options":["(A) 高銅汞齊的抗壓強度與自然牙接近","(B) 熱膨脹係數高於自然牙","(C) 高銅汞齊的抗張強度比抗壓強度高","(D) 與自然牙的磨耗（wear）速度接近"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-48","subject":"ya3","topic":"黏著與美學修復","meta":"115年第1次第48題","year":115,"session":1,"number":48,"question":"對於陶瓷復形物的臨床操作，下列敘述何者錯誤？","options":["(A) 二氧化鋯（zirconia）牙冠，內側可用 9%氫氟酸（hydrofluoric acid）酸蝕，來增加黏著強度","(B) 二矽酸鋰（lithium disilicate）牙冠，內側可用矽烷偶合劑（silane coupling agent）處理，來增加黏 著強度","(C) 二矽酸鋰（lithium disilicate）嵌體應該先黏著後，再確認有無咬合干擾","(D) 應使用不含丁香油酚（eugenol）的暫時黏著劑來固定暫時填補物"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-49","subject":"ya3","topic":"黏著與美學修復","meta":"115年第1次第49題","year":115,"session":1,"number":49,"question":"使用樹脂黏合劑黏著陶瓷嵌體的敘述，下列何者錯誤？","options":["(A) 臨床使用雙重聚合（dual cure）樹脂黏合劑，可減少光照時間","(B) 樹脂黏合劑可與牙釉質、牙本質以及陶瓷嵌體黏結","(C) 陶瓷嵌體經樹脂黏合劑黏結後可被強化","(D) 樹脂黏合劑可降低微滲漏"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-50","subject":"ya3","topic":"窩洞設計與分類","meta":"115年第1次第50題","year":115,"session":1,"number":50,"question":"有關上顎第一小臼齒瓷嵌體（ceramic inlay）窩洞製備之敘述，下列何者正確？","options":["(A) 應有足夠的厚度且需增加固持力（retention）的固位溝（retentive groove）","(B) 在 isthmus 處之寬度應為 1.0 mm","(C) 咬合面至少應有 1.5～2.0 mm 的厚度","(D) 應有 0.5 mm 的斜面"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-51","subject":"ya3","topic":"黏著與美學修復","meta":"115年第1次第51題","year":115,"session":1,"number":51,"question":"口內檢查如發現左上正中門齒表面呈現淺層（0.2～0.3 mm 內）小範圍的不透明白色斑點，下列治療計畫何 者最適當？","options":["(A) 居家漂白（home bleaching）","(B) 輕微磨除（microabrasion）","(C) 浮石粉磨光（polishing）","(D) 陶瓷貼面（porcelain veneers）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-52","subject":"ya3","topic":"黏著與美學修復","meta":"115年第1次第52題","year":115,"session":1,"number":52,"question":"關於診間活性牙齒漂白（in-office vital bleaching）的敘述，下列何者錯誤？","options":["(A) 當漂白的溫度增加 10°C 時，化學反應的速率會變快","(B) 漂白時通常不需要上麻醉，以避免降低牙齒的感受性","(C) 比居家漂白（home bleaching）更易產生術後敏感（sensitivity）","(D) 建議先酸蝕牙齒以增加過氧化氫（hydrogen peroxide）的穿透能力，增加漂白效率"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-53","subject":"ya3","topic":"牙科解剖與生理","meta":"115年第1次第53題","year":115,"session":1,"number":53,"question":"關於角質細胞（keratinocyte）由基底層（basal layer）往上皮表面（epithelial surface）分化和特化過 程，下列何者錯誤？","options":["(A) 細胞質中的張力絲（tonofilament）數目增加","(B) 胞橋小體（desmosome）數目增加","(C) 粒線體（mitochondria）數目增加","(D) 高基氏體（Golgi complex）數目減少"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-54","subject":"ya3","topic":"牙周手術與再生","meta":"115年第1次第54題","year":115,"session":1,"number":54,"question":"下列何者不是評估進行牙周手術的因素？","options":["(A) 牙周囊袋的深度","(B) 探測出血（bleeding on probing）的程度","(C) 非手術性牙周治療的執行程度","(D) 牙齒排列的狀況"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-55","subject":"ya3","topic":"牙周手術與再生","meta":"115年第1次第55題","year":115,"session":1,"number":55,"question":"牙齦切除術（gingivectomy）後的傷口，上皮形成（epithelialization）的時間約為下列何者？","options":["(A) 0 到 4 天","(B) 5 到 14 天","(C) 15 到 20 天","(D) 21 到 28 天"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-56","subject":"ya3","topic":"牙周手術與再生","meta":"115年第1次第56題","year":115,"session":1,"number":56,"question":"下列何種縫合方式可以使翻瓣更貼近牙根表面，達到良好的癒合？","options":["(A) Interrupted figure-eight suture","(B) Single interrupted sling suture","(C) Simple loop suture","(D) Anchor suture"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-57","subject":"ya3","topic":"牙周手術與再生","meta":"115年第1次第57題","year":115,"session":1,"number":57,"question":"附圖為何種牙周手術器械？","options":["(A) Kirkland 15/16","(B) Orban 1/2","(C) Waerhaug 1/2","(D) interdental knife"],"answer":0,"image":"ya3-115-1-57.jpeg","clinical_level":"重點"},{"id":"ya3-115-1-58","subject":"ya3","topic":"牙科解剖與生理","meta":"115年第1次第58題","year":115,"session":1,"number":58,"question":"世界衛生組織對骨質疏鬆症（osteoporosis）的定義中，T-scores 所參考的健康對照為幾歲？","options":["(A) 20 歲以下","(B) 20～30 歲","(C) 40～50 歲","(D) 60 歲以上"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-59","subject":"ya3","topic":"植牙學","meta":"115年第1次第59題","year":115,"session":1,"number":59,"question":"相較於非切削植體（non-cutting implant），自助攻牙植體（self-tapping implant）於何處多加切削邊 （cutting edge）？","options":["(A) 末端（apical portion）","(B) 中段（middle portion）","(C) 冠部（coronal portion）","(D) 中段和冠部（middle and coronal portion）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-60","subject":"ya3","topic":"牙周疾病與診斷","meta":"115年第1次第60題","year":115,"session":1,"number":60,"question":"根據 1960 至 1980 年代美國成年人口腔衛生調查，男性比女性有較多的附連喪失（attachment loss），下列 何者為其最可能因素？","options":["(A) 男女在遺傳因素（genetic factor）上的差異","(B) 男性口腔衛生（oral hygiene）較女性差","(C) 男性普遍壓力（stress）比女性大","(D) 男性比女性較少接受牙科預防性治療（preventive care）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-61","subject":"ya3","topic":"牙周疾病與診斷","meta":"115年第1次第61題","year":115,"session":1,"number":61,"question":"氯化血紅素（hemin）為下列那類細菌生長時所必需？","options":["(A) 鏈球菌屬（Streptococcus）","(B) 卟琳菌屬（Porphyromonas）","(C) 凝聚桿菌屬（Aggregatibacter）","(D) 細梭細菌屬（Fusobacteria）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-62","subject":"ya3","topic":"牙周疾病與診斷","meta":"115年第1次第62題","year":115,"session":1,"number":62,"question":"與局部型侵襲性牙周炎（localized aggressive periodontitis）特別相關的放線共生放線桿菌 （Aggregatibacter actinomycetemcomitans）JP2 基因型，相較於其他放線共生放線桿菌，其最主要特性為 何？","options":["(A) 產生較多蛋白酶（proteinase）","(B) 入侵（invade）表皮細胞的能力較強","(C) 較高的白細胞毒素（leukotoxin）基因表達","(D) 其纖毛（fimbriae）引發較強烈的宿主免疫反應"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-63","subject":"ya3","topic":"牙周疾病與診斷","meta":"115年第1次第63題","year":115,"session":1,"number":63,"question":"組織學研究發現，當牙周炎骨吸收發生時，覆蓋在骨頭上保持沒有發炎細胞浸潤的結締組織，其寬度約為多 少？","options":["(A) 0.3～0.5 mm","(B) 0.5～1 mm","(C) 1～1.5 mm","(D) 1.5～2 mm"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-64","subject":"ya3","topic":"牙周疾病與診斷","meta":"115年第1次第64題","year":115,"session":1,"number":64,"question":"48 歲男性病患，無全身性疾病，每天抽菸約 10 根，全口牙位皆有深的牙周探測囊袋深度及伴隨探測流血， 由下圖病患之全口根尖片影像進行判讀，根據 2017 World Workshop 公布的牙周病新分類，下列何者為此病 患的牙周病診斷？","options":["(A) Stage III, Grade B, generalized","(B) Stage IV, Grade B, generalized","(C) Stage III, Grade C, generalized","(D) Stage IV, Grade C, generalized"],"answer":3,"image":"ya3-115-1-64.jpeg","clinical_level":"一般"},{"id":"ya3-115-1-65","subject":"ya3","topic":"牙周疾病與診斷","meta":"115年第1次第65題","year":115,"session":1,"number":65,"question":"在 2017 World Workshop 公布的牙周病新分類中，有關牙周炎分期（Stage）的敘述，下列何者正確？","options":["(A) Stage 是以病人為主體的評估","(B) Stage 是以牙齒為主體的評估","(C) 需先評估現有全部牙齒的破壞分布，以有效區分 Stage I／Stage II 與 Stage III／Stage IV 患者","(D) 在特定時間檢查口內所有牙齒，不同嚴重程度牙齒會獲得不同 Stage 的診斷"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-66","subject":"ya3","topic":"牙周疾病與診斷","meta":"115年第1次第66題","year":115,"session":1,"number":66,"question":"在 2017 World Workshop 公布的牙周病新分類中，關於利用直接證據評估牙周炎級別（Grade）的敘述，下列 何者錯誤？","options":["(A) Grade A：五年臨床附連組織減少＜1 mm","(B) Grade B：五年臨床附連組織減少＜2 mm","(C) Grade B：五年放射線影像齒槽骨喪失＜2 mm","(D) Grade C：五年放射線影像齒槽骨喪失≧2 mm"],"answer":0,"image":"","clinical_level":"重點(深度)"},{"id":"ya3-115-1-67","subject":"ya3","topic":"牙周疾病與診斷","meta":"115年第1次第67題","year":115,"session":1,"number":67,"question":"關於糖尿病與牙周炎的關係，下列敘述何者錯誤？","options":["(A) 牙周炎的併發症會出現於 Type I 及 Type II 的糖尿病患者","(B) 糖尿病患者的多形核嗜中性白血球（PMNs）chemotaxis 和 phagocytosis 的功能不正常","(C) 45 歲以上糖尿病患者血糖控制不良（HbA1c＞9%）時，比起非糖尿病者，有 2.9 倍罹患嚴重牙周炎的機會","(D) 糖尿病患者的 IgA、IgG、IgM 皆受影響而異常"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-68","subject":"ya3","topic":"牙周非手術治療","meta":"115年第1次第68題","year":115,"session":1,"number":68,"question":"有效的牙齦下清創（subgingival debridement）合併自我牙齦上的感染控制，可以改變牙周環境。下列敘述 何者錯誤？","options":["(A) 根據 Cobb（2002）文獻指出，牙齦下菌叢革蘭氏陽性嗜氧菌（球菌及桿菌）的增加與牙周健康相關","(B) 長期臨床追蹤顯示，治療後牙周囊袋超過 4 mm 的牙齒，脫落的風險是小於 4 mm 的 46 倍","(C) 臨床上沒有探測流血，且治療後牙周囊袋探測至 4 mm 以下，可定義為治療成功","(D) 平均而言，初次非手術性治療後的再評估中，可能有 35%的牙周囊袋無法達到治療成功的結果"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-69","subject":"ya3","topic":"牙周非手術治療","meta":"115年第1次第69題","year":115,"session":1,"number":69,"question":"超音波洗牙機在儀器尖端以高頻振動的形式將電流轉化為機械能；振動頻率範圍為 18,000 至 45,000 Hz，其 振幅範圍為多少μm？","options":["(A) 1～10","(B) 10～100","(C) 100～1000","(D) 1000～10000"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-70","subject":"ya3","topic":"牙周非手術治療","meta":"115年第1次第70題","year":115,"session":1,"number":70,"question":"牙周器械根據使用目的進行分類，下列敘述何者錯誤？","options":["(A) 牙周探針（periodontal probes）用於定位、測量和標記囊袋深度","(B) 牙周內視鏡（periodontal endoscopes）可以看到較深的牙周囊袋以及牙根分叉處的沉積物","(C) 橡膠杯（rubber cups）可用來清潔及拋光牙根表面","(D) 牙周刮刀（curettes）主要用於牙齦下刮除牙結石、牙根表面整平和去除囊袋內軟組織"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-71","subject":"ya3","topic":"牙周手術與再生","meta":"115年第1次第71題","year":115,"session":1,"number":71,"question":"關於去礦化冷凍乾燥骨（demineralized freeze-dried bone allograft, DFDBA）的敘述，下列何者錯誤？","options":["(A) 為同種異體移植骨","(B) 吸收速度較異種牛骨粉（deproteinized bovine bone mineral）慢","(C) 具有骨傳導（osteoconduction）特性","(D) 具有骨誘導（osteoinduction）特性"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-72","subject":"ya3","topic":"牙周手術與再生","meta":"115年第1次第72題","year":115,"session":1,"number":72,"question":"前牙的牙冠增長手術希望保留頰側至少幾 mm 的角質化牙齦？","options":["(A) 1","(B) 2","(C) 3","(D) 4"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-73","subject":"ya3","topic":"醫學倫理與法規","meta":"115年第1次第73題","year":115,"session":1,"number":73,"question":"關於牙科 X 光片拍攝間隔的敘述，下列何者錯誤？","options":["(A) 蛀牙高危險群的病人，應每 6～18 個月拍攝後牙咬翼片檢查","(B) 牙周疾病控制不佳的病人，應每 12～24 個月拍攝患齒區域的根尖片或垂直咬翼片檢查","(C) 接受過牙周病治療且控制良好的病人，應每 24～36 個月拍攝咬翼片檢查","(D) 臨床上無蛀牙亦無蛀牙高風險因子的病人，應每 18～24 個月拍攝後牙咬翼片檢查"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-74","subject":"ya3","topic":"牙科解剖與生理","meta":"115年第1次第74題","year":115,"session":1,"number":74,"question":"關於感染性心內膜炎（infective endocarditis, IE）高風險的患者，於牙科術前的預防性抗生素的使用， 下列敘述何者錯誤？","options":["(A) 緊急排膿的處置，為術前 1 小時優先使用 2～3g 的 amoxicillin","(B) 在英格蘭的不良事件報告數據顯示：即使對 penicillin 過敏，使用 amoxicillin 的潛在風險也比 clindamycin 低","(C) 門診治療時的給藥途徑：注射給藥（parenteral administration）優於口服用藥","(D) 對於有吞嚥障礙的病患，可以使用 azithromycin（200 mg/5 mL）口服懸浮液"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-75","subject":"ya3","topic":"牙科解剖與生理","meta":"115年第1次第75題","year":115,"session":1,"number":75,"question":"有關先天性心臟病（congenital heart disease）的臨床表徵敘述，下列何者錯誤？","options":["(A) 心臟缺陷造成周邊血管慢性缺氧與代償性紅血球增多","(B) 兒童的口腔表徵有牙齦炎、嘴唇和黏膜發紺","(C) 乳牙萌發遲緩，恆牙則不受影響","(D) 牙釉質發育不良（enamel hypoplasia）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-76","subject":"ya3","topic":"牙科解剖與生理","meta":"115年第1次第76題","year":115,"session":1,"number":76,"question":"關於 HIV 陽性患者的口腔與免疫表徵，下列敘述何者正確？","options":["(A) HIV 陽性患者的口腔常有壞死性潰瘍性牙周炎，伴隨 CD4 計數遽增","(B) HIV 的病毒很少經由口水傳播，因為在口水有抗 HIV 的免疫抑制因子","(C) 根據 WHO 對 HIV 感染的臨床分期，牙周病病徵出現在第四期","(D) HIV 陽性患者的牙科治療，經由針扎傳染疾病的風險大約是 0.03%"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-77","subject":"ya3","topic":"植牙學","meta":"115年第1次第77題","year":115,"session":1,"number":77,"question":"下列何者是在上顎竇提升術及骨擴大術（maxillary sinus elevation and bone augmentation）的術式中， 可以同時植牙（simultaneous implant placement）的最重要因素？","options":["(A) 最少有 5 mm 的原生骨（native bone）高度","(B) 最少有 3 mm 的原生骨（native bone）高度","(C) 最少有 1 mm 的原生骨（native bone）高度","(D) 植體在原生骨（native bone）中可得到初步穩定"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-78","subject":"ya3","topic":"植牙學","meta":"115年第1次第78題","year":115,"session":1,"number":78,"question":"錐狀束電腦斷層（CBCT）可提供患者在植牙手術前詳細的影像評估。關於錐狀束電腦斷層特性的敘述，下列 何者錯誤？","options":["(A) 視野（FOV）分成三種：大視野（大於 15 cm），中視野（8 到 15 cm），和小視野（小於 8 cm）","(B) 更高的輻射暴露，及較低分辨率的圖像，是小視野的特徵","(C) 和電腦斷層（CT）相比，錐狀束電腦斷層的輻射暴露較低","(D) 可提供三度空間的影像"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-1-79","subject":"ya3","topic":"植牙學","meta":"115年第1次第79題","year":115,"session":1,"number":79,"question":"關於植體探測深度的敘述，下列何者錯誤？","options":["(A) 以傳統不鏽鋼探針施以 0.25N 的力道探測植體，不會對植體周圍黏膜造成不良反應","(B) 植體周圍不像自然牙有垂直牙根走向的結締組織膠原纖維","(C) 在發炎的植體周圍探測時，探針常會穿入結締組織到靠近齒槽骨的位置","(D) 自然牙周圍之探測深度變異程度比植體來得大"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-115-1-80","subject":"ya3","topic":"植牙學","meta":"115年第1次第80題","year":115,"session":1,"number":80,"question":"關於植體周圍黏膜炎之治療，下列敘述何者錯誤？","options":["(A) 目前證據顯示機械性清創之外的局部輔助性治療方法無法顯著地消除植體周圍發炎情形","(B) 定期回診清除生物膜（biofilm）可避免植體周圍黏膜炎發展成植體周圍炎","(C) 使用全身輔助性抗菌劑（adjunctive systemic antimicrobials）因弊大於利，故不建議用於植體周圍黏膜 炎之治療","(D) 不鏽鋼器械可能會刮傷植體表面，不可用在植體周圍之治療"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya3-115-2-1","subject":"ya3","topic":"牙科解剖與生理","meta":"115年第2次第1題","year":115,"session":2,"number":1,"question":"下列永久齒列前齒，何者最有可能具雙根管雙根尖？","options":["(A) 上顎門齒","(B) 上顎犬齒","(C) 下顎側門齒","(D) 上顎側門齒"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-2","subject":"ya3","topic":"根管治療程序","meta":"115年第2次第2題","year":115,"session":2,"number":2,"question":"欲分辨出下顎門齒的兩根管，最理想的X光照射角度為何？","options":["(A) 平行法照射","(B) 將錐筒（cone）往上偏移照射","(C) 遠心向照射（distal projection），錐筒（cone）指向該牙近心處","(D) 近心向照射（mesial projection），錐筒（cone）指向該牙遠心處"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-3","subject":"ya3","topic":"牙齒外傷處理","meta":"115年第2次第3題","year":115,"session":2,"number":3,"question":"臨床上，利用放射影像學檢查來診斷受到外傷之牙齒及周圍組織，下列何者錯誤？","options":["(A) 若口內檢查僅有軟組織受到外傷，則無須拍攝X光片檢查","(B) 電腦斷層影像系統，可輔助診斷臨床上難以發現的牙根斷裂","(C) 牙齒的咬合面X光影像（occlusal radiograph）可以協助檢查牙齒移位","(D) 可利用多張不同角度的根尖片，增加外傷牙齒診斷的正確性"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-4","subject":"ya3","topic":"根尖手術與再治療","meta":"115年第2次第4題","year":115,"session":2,"number":4,"question":"施行根尖手術時，常以超音波器械做根尖窩洞修形（root-end cavity preparation），下列敘述何者正確？","options":["(A) 器械應平行牙齒的長軸","(B) 強度開到最強，縮減操作時間","(C) 不要噴水，以免妨礙操作視線","(D) 使用超音波器械比鑽針更容易造成根尖破裂（apical fracture）的產生"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-5","subject":"ya3","topic":"根尖手術與再治療","meta":"115年第2次第5題","year":115,"session":2,"number":5,"question":"根管再治療時，常用來移除馬來膠針（gutta-percha）的溶劑中，何種藥品的毒性相對較小？","options":["(A) 氯仿（chloroform）","(B) 尤加利油（eucalyptol）","(C) 溴氯三氟乙烷（halothane）","(D) 精製松節油（rectified turpentine）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-6","subject":"ya3","topic":"根管治療程序","meta":"115年第2次第6題","year":115,"session":2,"number":6,"question":"關於根管治療後牙齒組成變化的敘述，下列何者錯誤？","options":["(A) 喪失的水分是游離水的變化","(B) 抗壓強度（compressive strength）和抗拉強度（tensile strength）的降低與含水量變化有關","(C) 螯合劑（chelators）影響非膠原蛋白（NCP），導致牙本質侵蝕和表面軟化","(D) 次氯酸鈉（sodium hypochlorite）可以水解長肽鏈產生蛋白水解作用"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-7","subject":"ya3","topic":"黏著與美學修復","meta":"115年第2次第7題","year":115,"session":2,"number":7,"question":"關於齒內漂白（internal bleaching）的併發症，下列敘述何者錯誤？","options":["(A) 臨床報告和組織學研究顯示，可能會導致牙根內吸收","(B) 化學物質與熱結合可能導致牙骨質壞死、牙周膜發炎和牙根吸收","(C) 過硼酸鈉（sodium perborate）與水混合比35%過氧化氫安全","(D) 在齒頸部應避免氧化劑接觸太多牙本質"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-8","subject":"ya3","topic":"牙髓診斷與病理","meta":"115年第2次第8題","year":115,"session":2,"number":8,"question":"關於牙周疾病對牙髓的影響，下列何者正確？","options":["(A) 一般而言，牙周病治療不會對牙髓造成直接傷害","(B) 當牙周病造成牙周骨破壞至側根管時，會導致牙髓壞死","(C) 當牙周治療造成側根管暴露時，會導致牙髓壞死","(D) 牙周病的嚴重度與牙髓壞死的機率有直接相關"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-9","subject":"ya3","topic":"牙科解剖與生理","meta":"115年第2次第9題","year":115,"session":2,"number":9,"question":"關於牙齒內蛋白質的敘述，下列何者錯誤？","options":["(A) 牙本質內膠原蛋白（collagen）主要成分是Type I膠原蛋白，約占70%；其餘分別是Type II和Type III膠原蛋白","(B) 牙本質內非膠原蛋白之蛋白質主要成分為牙本質磷酸蛋白（dentin phosphoprotein）和牙本質唾液蛋白（dentin sialoprotein）","(C) 牙本質唾液蛋白（dentin sialoprotein）可能與牙本質礦化有關，但機制尚未明確","(D) 牙髓內的膠原蛋白（collagen）主要成分是Type I與Type III膠原蛋白"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-10","subject":"ya3","topic":"牙科解剖與生理","meta":"115年第2次第10題","year":115,"session":2,"number":10,"question":"牙髓腔組織從組織學研究來看可分為四層，對於牙髓腔各層組織之敘述，下列何者錯誤？","options":["(A) 成纖維細胞（fibroblast）是中心牙髓區（pulp proper）主要的細胞","(B) 由於靠近牙根尖的神經分布較多，因此無細胞區（cell-poor zone）在牙根處比在牙冠處明顯","(C) 位於多細胞區（cell-rich zone）的成纖維細胞（fibroblast），具有分化形成造牙本質細胞（odontoblast）的潛力","(D) 無細胞區鄰接造牙本質細胞層（odontoblast layer）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-11","subject":"ya3","topic":"牙髓診斷與病理","meta":"115年第2次第11題","year":115,"session":2,"number":11,"question":"有關裂齒（cracked tooth）及垂直牙根斷裂（vertical root fracture）的敘述，下列何者正確？","options":["(A) 裂齒經根管治療並以牙冠贋復後預後極好；垂直牙根斷裂預後極差","(B) 裂齒多見於牙冠近遠心側，故無法由X光片明確診斷；垂直牙根斷裂常見於牙根頰舌側，X光片上容易明確判讀","(C) 裂齒從牙冠部位產生並可延伸至牙根；垂直牙根斷裂多只在牙根部位產生","(D) 裂齒最常見於後牙；垂直牙根斷裂僅見於做過根管治療的後牙"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-12","subject":"ya3","topic":"牙髓診斷與病理","meta":"115年第2次第12題","year":115,"session":2,"number":12,"question":"關於不可逆性牙髓炎（irreversible pulpitis）的敘述，下列何者正確？","options":["(A) 很少有自發性症狀","(B) 外界刺激不會產生疼痛","(C) 受到冷或熱的刺激時會造成疼痛反應延長","(D) 受感染牙髓有廣泛性的尖銳痛或鈍痛，但不會持續數小時"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-13","subject":"ya3","topic":"牙髓診斷與病理","meta":"115年第2次第13題","year":115,"session":2,"number":13,"question":"有關根尖放射菌病（apical actinomycosis）的敘述，下列何者正確？","options":["(A) 屬根管內的細菌感染造成（intraradicular infection）","(B) 大部分是因放線菌（Actinomycoces）族群和糞腸球菌（Enteroccocus faecalis）造成","(C) 須藉由根尖手術治療","(D) 需要根管內細菌提供養分以供生存"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-14","subject":"ya3","topic":"牙齒外傷處理","meta":"115年第2次第14題","year":115,"session":2,"number":14,"question":"何種類型的外傷，日後最容易造成如下圖右上正中門齒的影像？","options":["(A) 齒震盪（concussion）","(B) 半脫位（subluxation）","(C) 外突脫位（extrusive luxation）","(D) 內縮脫位（intrusive luxation）"],"answer":3,"image":"ya3-115-2-14.jpeg","clinical_level":"一般"},{"id":"ya3-115-2-15","subject":"ya3","topic":"牙髓診斷與病理","meta":"115年第2次第15題","year":115,"session":2,"number":15,"question":"下列關於裂齒（cracked tooth）的敘述，何者正確？","options":["(A) 大都由牙冠延伸至牙齦下且多數為頰舌側方向的非完整斷裂","(B) 可經由顯微鏡、染色及光透照射找出斷裂長度及位置","(C) 在咀嚼時會有急性疼痛對熱刺激敏感，對冷刺激舒緩","(D) 是造成垂直牙根斷裂（vertical root fracture）的主因"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-16","subject":"ya3","topic":"根管器械","meta":"115年第2次第16題","year":115,"session":2,"number":16,"question":"關於鎳鈦器械的敘述，下列何者正確？","options":["(A) nitinol合金組成為鎳45%、鈦55%","(B) 合金受力時晶相會由麻田散相（martensite）變成奧斯田相（austenite）","(C) 有radial land設計的器械對根管壁的摩擦力大，所以切削效率較差","(D) 因為合金有超彈性，所以器械製作時只能用切削研磨製成"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-17","subject":"ya3","topic":"根管治療程序","meta":"115年第2次第17題","year":115,"session":2,"number":17,"question":"對於常用止痛藥每日最大劑量限制的建議，下列何者錯誤？","options":["(A) 乙醯胺酚（Acetaminphen）2,000 mg","(B) Diclofenac potassium 200 mg","(C) 阿斯匹靈（Aspirin）4,000 mg","(D) 布洛芬（Ibuprofen acid）2,400 mg"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-18","subject":"ya3","topic":"根管器械","meta":"115年第2次第18題","year":115,"session":2,"number":18,"question":"關於K型銼針、H型銼針與R型銼針的根管治療器械之敘述，下列何者正確？","options":["(A) K型與R型銼針器械多是扭轉三角或四方形或菱形不鏽鋼鋼線製成","(B) 以R型銼針的切削能力最佳","(C) 透過balanced force technique可以避免這三種器械操作時造成根管形態的偏差","(D) H型銼針是直接研磨圓形或菱形不鏽鋼鋼線加工而成"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-19","subject":"ya3","topic":"牙髓診斷與病理","meta":"115年第2次第19題","year":115,"session":2,"number":19,"question":"口腔底蜂窩性組織炎（Ludwig angina）不包含下列那一個筋膜腔（fascial space）的感染腫脹？","options":["(A) 頦下間隙（submental space）","(B) 舌下隙（sublingual space）","(C) 顎下隙（submandibular space）","(D) 翼下顎間隙（pterygomandibular space）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-20","subject":"ya3","topic":"根管治療程序","meta":"115年第2次第20題","year":115,"session":2,"number":20,"question":"當錐狀射束電腦斷層掃描（cone beam computed tomography, CBCT）體素大小（voxel size）越大時，下列敘述何者正確？","options":["(A) 影像的解析度愈高","(B) 檔案愈大","(C) 掃描時間愈短","(D) 影像重組的時間愈久"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-21","subject":"ya3","topic":"根管治療程序","meta":"115年第2次第21題","year":115,"session":2,"number":21,"question":"關於馬來膠錐（gutta-percha cone）的組成，下列敘述何者錯誤？","options":["(A) gutta-percha含量最高","(B) ZnO主要做為填料（filler）","(C) waxes和resins主要做為塑形劑","(D) metal sulfate可提供放射線不透過性（radiopacity）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-22","subject":"ya3","topic":"根管治療程序","meta":"115年第2次第22題","year":115,"session":2,"number":22,"question":"關於血管再生術（revascularization）誘導牙髓組織再生的組織工程策略，下列何者錯誤？","options":["(A) 應用無細胞方法（cell-free approach）作為組織再生策略","(B) 置入根尖乳突幹細胞（stem cells from apical papilla）作為細胞來源","(C) 刺激根尖組織出血於根管內形成血塊作為支架","(D) 使用EDTA沖洗暴露根管表面牙本質基質的生長因子，以促進幹細胞的生長分化行為"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-23","subject":"ya3","topic":"根管治療程序","meta":"115年第2次第23題","year":115,"session":2,"number":23,"question":"根管治療時的根管沖洗針頭會將沖洗液帶入針尖前1 mm的位置，最適宜的沖洗針頭大小為何？","options":["(A) 22 gauge","(B) 25 gauge","(C) 27 gauge","(D) 30 gauge"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-24","subject":"ya3","topic":"根尖手術與再治療","meta":"115年第2次第24題","year":115,"session":2,"number":24,"question":"根尖手術中，使用礦化三氧聚合物（mineral trioxide aggregate, MTA）作為逆充填材料，下列敘述何者正確？","options":["(A) 其防止滲漏（leakage）的表現較複合樹脂差","(B) 生物相容性佳，牙骨質（cementum）甚至可生成並附連於MTA表面","(C) 組織毒性低，其調拌初期酸鹼值達12.5，一週後則pH降至約7","(D) 水合過程若有血液存在，會影響其硬化，增加滲漏（leakage）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-25","subject":"ya3","topic":"根尖手術與再治療","meta":"115年第2次第25題","year":115,"session":2,"number":25,"question":"此放射線影像（如下圖）由遠心往近心方向照射（distal shift projection），先前被治療過的右下顎第二小臼齒可能遺漏了那一個根管？","options":["(A) 頰側根管","(B) 舌側根管","(C) 遠心根管","(D) 近心根管"],"answer":1,"image":"ya3-115-2-25.jpeg","clinical_level":"一般"},{"id":"ya3-115-2-26","subject":"ya3","topic":"醫學倫理與法規","meta":"115年第2次第26題","year":115,"session":2,"number":26,"question":"病患來看診時，主訴某區域牙齒疼痛，經醫生看診後發現其中一顆牙齒有蛀牙。下列何者為醫師該有的態度？","options":["(A) 立即處理病患所述的牙齒","(B) 建議病患馬上拔除，減少疼痛","(C) 請病患描述疼痛情形，了解過去病史及病患全身性病史。經臨床診斷後，為病患解釋病情且做最佳的治療","(D) 即時給與病患藥物改善疼痛即可"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-27","subject":"ya3","topic":"牙髓診斷與病理","meta":"115年第2次第27題","year":115,"session":2,"number":27,"question":"老化對牙髓造成的影響，下列何者錯誤？","options":["(A) 牙髓細胞減少","(B) 髓內礦化減少","(C) 基質水分流失","(D) 無髓鞘（unmyelinated）神經變性（degeneration）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-28","subject":"ya3","topic":"牙科解剖與生理","meta":"115年第2次第28題","year":115,"session":2,"number":28,"question":"相較於牙釉質，關於牙本質的敘述，下列何者正確？①具較高抗壓強度（compressive strength） ②具較高抗張強度（tensile strength） ③具較低硬度（hardness） ④具較高彈性係數（elastic modulus）","options":["(A) ①②③","(B) 僅④","(C) 僅②③","(D) ①③④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-29","subject":"ya3","topic":"牙科解剖與生理","meta":"115年第2次第29題","year":115,"session":2,"number":29,"question":"關於唾液與其防止齲齒的敘述，下列何者錯誤？","options":["(A) 成人每天產生1至1.5公升唾液，在睡眠期間產生較少","(B) 唾液中的抗菌蛋白，能有效降低齲齒率","(C) 唾液具有緩衝能力，可減少酸的形成，亦可讓生物膜pH值升高","(D) 頭頸部放射治療後，唾液腺會纖維化，導致患者出現口乾症狀"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-30","subject":"ya3","topic":"牙體修形程序","meta":"115年第2次第30題","year":115,"session":2,"number":30,"question":"關於牙根齲齒的敘述，下列何者錯誤？","options":["(A) 牙根表面齲蝕通常缺乏明確的邊緣且截面呈現U字形","(B) 發生率受唾液分泌量影響","(C) 進展速度約是牙冠齲齒的兩倍","(D) 使用沖牙機（water irrigation device）可移除牙根表面的生物膜（biofilm）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-31","subject":"ya3","topic":"牙體修形程序","meta":"115年第2次第31題","year":115,"session":2,"number":31,"question":"對於咬合面齲齒（occlusal surface caries）的敘述，下列何者錯誤？","options":["(A) 病灶牙齒若表面呈灰白（chalkiness），可能有牙釉質齲齒","(B) 視診檢查小窩及溝裂齲齒（pit-and-fissure caries）時，建議使用探針來提高偵測可信度","(C) 咬合面齲齒在左右兩側牙齒常同時發生","(D) 細菌會快速聚集在新萌發牙齒的溝裂（pits and fissures）處"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-32","subject":"ya3","topic":"牙體修形程序","meta":"115年第2次第32題","year":115,"session":2,"number":32,"question":"關於再發性齲齒（recurrent caries）的診斷與治療，下列敘述何者錯誤？","options":["(A) 通常不透射線（radiopaque）充填物的周圍有透射性（radiolucent）的影像，可能有再發性齲齒","(B) 填補物窩緣的變色，均視為齲蝕需重新填補","(C) 以抗齲蝕性質的材質修復，並不表示對齲齒有免疫性","(D) 汞齊填補物周圍齒質有黃褐色變色且與窩緣面邊緣相連時，則須重新置換填補物"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-33","subject":"ya3","topic":"黏著與美學修復","meta":"115年第2次第33題","year":115,"session":2,"number":33,"question":"化學黏著力分成主要（primary）與二級（secondary）黏著力，下列何者為主要黏著力？","options":["(A) 氫鍵（hydrogen bonds）","(B) 共價鍵（covalent bonds）","(C) 偶極力（dipole interaction）","(D) 凡德瓦（van der Waals）力"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-34","subject":"ya3","topic":"黏著與美學修復","meta":"115年第2次第34題","year":115,"session":2,"number":34,"question":"填補齲齒時，有關牙本質黏著劑與鍵結的敘述，下列何者正確？","options":["(A) 牙本質酸蝕後膠原蛋白暴露，會導致表面能量變低","(B) 牙本質具有牙本質小管，黏著劑中的樹脂成分會延伸入小管中形成柱狀結構，是黏著強度的主要來源","(C) 窩洞修磨後，牙本質表面會形成塗抹層（smear layer），與牙本質間有良好黏著強度","(D) 牙本質小管內有液體，因此酸蝕後應該儘量吹乾"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-35","subject":"ya3","topic":"牙科解剖與生理","meta":"115年第2次第35題","year":115,"session":2,"number":35,"question":"牙本質小管的管徑，在近牙髓端及牙本質牙釉質交界處（DEJ）分別大約為何種大小？","options":["(A) 近牙髓端：2.37 µm；牙本質牙釉質交界處（DEJ）：0.63 µm","(B) 近牙髓端：0.63 µm；牙本質牙釉質交界處（DEJ）：2.37 µm","(C) 近牙髓端：2.37 µm；牙本質牙釉質交界處（DEJ）：6.3 µm","(D) 近牙髓端：6.3 µm；牙本質牙釉質交界處（DEJ）：2.37 µm"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-36","subject":"ya3","topic":"窩洞設計與分類","meta":"115年第2次第36題","year":115,"session":2,"number":36,"question":"使用多晶體形（polycrystalline）直接填補材料復形時，窩洞修形的深度應至少為何？","options":["(A) 0.5 mm","(B) 1 mm","(C) 1.5 mm","(D) 移掉齲齒即可"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-37","subject":"ya3","topic":"窩洞設計與分類","meta":"115年第2次第37題","year":115,"session":2,"number":37,"question":"關於初步抗力修形（primary resistance form）的敘述，下列何者錯誤？","options":["(A) 銀粉填補物厚度不應少於1.5 mm","(B) 外型缺損大於中央溝到咬頭間距離一半時，咬頭高度應予修低","(C) 透過線角的圓化（rounding）可減少應力","(D) 上顎前牙無牙本質支持的牙釉質應予移除"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-38","subject":"ya3","topic":"複合樹脂與材料","meta":"115年第2次第38題","year":115,"session":2,"number":38,"question":"使用玻璃離子（glass ionomer）復形材填補齒頸部齲齒時，下列操作何者正確？","options":["(A) 窩洞製備時必須製作固位溝（retentive grooves）和牙釉質斜面（enamel bevel）提升固位性（retention）","(B) 填補前應使用37%磷酸移除塗抹層（smear layer）方便齒質與復形材結合","(C) 填補後表面必須酸蝕、沖水、吹乾後塗黏著劑，避免復形物遭液體污染","(D) 填補後儘量以手動器械修形以避免材料脫水"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-39","subject":"ya3","topic":"複合樹脂與材料","meta":"115年第2次第39題","year":115,"session":2,"number":39,"question":"關於牙齒組織與牙科材料的線性熱膨脹係數（linear coefficient of thermal expansion）的敘述，下列何者錯誤？","options":["(A) 牙科汞齊（amalgam）＞ 牙齒硬組織","(B) 不含填料的壓克力樹脂（unfilled acrylic resin）＞ 牙科複合樹脂（composite resin）","(C) 牙科複合樹脂（composite resin）＞ 牙齒硬組織","(D) 牙科汞齊＞ 不含填料的壓克力樹脂（unfilled acrylic resin）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-40","subject":"ya3","topic":"窩洞設計與分類","meta":"115年第2次第40題","year":115,"session":2,"number":40,"question":"關於窩洞製備中增加固位（retention）的修形，下列敘述何者最不適當？","options":["(A) 固位溝（retention groove）常製備於鄰接面盒（proximal box）中","(B) 小凹（cove）應在牙釉質上","(C) 溝槽（slot）的位置為牙釉質牙本質交界內至少0.5～1 mm","(D) 斜面（bevel）的位置為牙釉質邊緣"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-41","subject":"ya3","topic":"複合樹脂與材料","meta":"115年第2次第41題","year":115,"session":2,"number":41,"question":"關於複合樹脂的描述，下列何者正確？","options":["(A) 使用camphorquinone作為光啟始劑的樹脂，以波長390～420 nm光聚合最佳","(B) 體積收縮率約1.5%～5.0%","(C) 當溫度改變時，牙齒收縮和膨脹的量比樹脂大","(D) 添加填料（filler）至基質（matrix）中會增加聚合收縮"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-42","subject":"ya3","topic":"窩洞設計與分類","meta":"115年第2次第42題","year":115,"session":2,"number":42,"question":"關於製備樹脂填補的第二類窩洞（class Ⅱ cavity）的敘述，下列何者正確？","options":["(A) 小型窩洞的邊緣不需有斜面（bevel）","(B) 修形小型鄰接盒型（proximal box）窩洞時，鑽針進入方向應與牙齒長軸成30°","(C) 小型窩洞的頰舌側邊緣窩緣角應小於90°","(D) 初步的髓腔壁製備深度為超過DEJ 1 mm"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-43","subject":"ya3","topic":"窩洞設計與分類","meta":"115年第2次第43題","year":115,"session":2,"number":43,"question":"在大範圍的第四類窩洞（Class Ⅳ）複合樹脂填補時，關於窩洞設計中斜面（bevel）的敘述，下列何者最不適當？","options":["(A) 可以改善複合樹脂界面美觀","(B) 增加斜面面積，可增加複合樹脂和牙齒的鍵結強度","(C) 當窩洞延伸到牙根時，牙根區域至少要1 mm寬的斜面來增加鍵結強度","(D) 扇形（scallop）斜面可讓複合樹脂與牙齒間的界面不明顯"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-44","subject":"ya3","topic":"牙體修形程序","meta":"115年第2次第44題","year":115,"session":2,"number":44,"question":"在進行第一類汞齊（Class Ⅰ amalgam）填補時，在進行填壓（condensation）過程中，最接近咬合面處若有過度填塞（overpack）（如圖），下列何者敘述正確？","options":["(A) overpack是不能接受的，可能造成牙釉質斷裂","(B) overpack是可以接受的，可以確保窩洞邊緣被amalgam完全覆蓋，並需於carving時移除","(C) overpack是可以接受的，只要請病人回去咬一咬就可以適應","(D) overpack是可以接受的，外溢的部分很堅固不容易脫落"],"answer":1,"image":"ya3-115-2-44.jpeg","clinical_level":"一般"},{"id":"ya3-115-2-45","subject":"ya3","topic":"牙體修形程序","meta":"115年第2次第45題","year":115,"session":2,"number":45,"question":"第二類汞齊窩洞充填，鄰接面使用雙重木楔楔入（wedge-wedging or double-wedging technique）的方法，最常用於下列何者？","options":["(A) 上顎第一小臼齒","(B) 上顎第一大臼齒","(C) 下顎第一小臼齒","(D) 下顎第一大臼齒"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-46","subject":"ya3","topic":"窩洞設計與分類","meta":"115年第2次第46題","year":115,"session":2,"number":46,"question":"關於鑄金覆嵌（cast gold onlay）窩洞修形，下列敘述何者錯誤？","options":["(A) 牙齦壁（gingival wall）邊緣完成線（finish line）為斜面邊緣（bevel margin）","(B) 咬合面邊緣不應製備斜面邊緣（bevel margin）","(C) 非中心咬頭（noncentric cusp）邊緣完成線可以是弧形緣（chamfer）或長斜面（long bevel）","(D) 中心咬頭（centric cusp）修磨厚度為1.5～2.0 mm"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-47","subject":"ya3","topic":"黏著與美學修復","meta":"115年第2次第47題","year":115,"session":2,"number":47,"question":"關於鑄金贋復體的黏著過程，下列敘述何者錯誤？","options":["(A) 聚羧酸黏著劑（polycarboxylate cement）為黏著鑄金嵌體／覆體最佳黏著劑","(B) 在黏著前，可使用棉捲做隔濕","(C) 放置上贋復物後，應用類似ball burnisher的器械稍微加壓在牙齒的凹窩處","(D) 應以頰舌側邊緣緊密度確認黏著定位"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-48","subject":"ya3","topic":"黏著與美學修復","meta":"115年第2次第48題","year":115,"session":2,"number":48,"question":"利用電腦輔助設計與製作（CAD/CAM）陶瓷嵌體時，下列敘述何者正確？","options":["(A) 為了增加固位性，鄰接盒（proximal box）需呈往咬合面內縮（convergent）","(B) 為了增加固位性，鄰接盒（proximal box）邊緣需製備斜面（bevel）","(C) 為了增加口掃印模方便性，頰舌側應呈現刀切邊緣（knife edge margin）","(D) 為了足夠的強度，中央溝厚度至少要1.5 mm"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-49","subject":"ya3","topic":"黏著與美學修復","meta":"115年第2次第49題","year":115,"session":2,"number":49,"question":"當病患口內有陶瓷嵌體（ceramic inlays/onlays）復形物時，下列何種氟化物可以預防二次齲齒，且不會對陶瓷及牙齒造成不利影響？①acidulated phosphate fluoride solution ②stannous fluoride gel ③ neutral sodium fluoride solution","options":["(A) ①②③","(B) 僅②","(C) 僅③","(D) 僅②③"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-50","subject":"ya3","topic":"黏著與美學修復","meta":"115年第2次第50題","year":115,"session":2,"number":50,"question":"下列何者為內因性牙齒變色（intrinsic discoloration）的原因？①齲齒 ②年紀大牙齒變黃 ③氟斑齒 ④Amalgam blue","options":["(A) 僅③","(B) 僅②③","(C) 僅①②④","(D) ①②③④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-51","subject":"ya3","topic":"黏著與美學修復","meta":"115年第2次第51題","year":115,"session":2,"number":51,"question":"關於“Vital classical”和“Vital 3D master”兩種常用比色板，下列敘述何者錯誤？","options":["(A) 前者A至D的分類是基於色度（chroma）的差異","(B) 兩者皆屬於以陶瓷為基礎的比色板（ceramic-based tooth shade guide）","(C) 3R2.5為“Vital 3D master”比色板之比色結果","(D) 後者涵蓋更多牙齒的色域"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-52","subject":"ya3","topic":"黏著與美學修復","meta":"115年第2次第52題","year":115,"session":2,"number":52,"question":"下列何種材料不適用於強調美觀的瓷鑲面製作？","options":["(A) milled leucite-reinforced ceramic","(B) polycrystalline ceramics","(C) feldspathic porcelain","(D) pressed lithium disilicate-reinforced ceramic"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-53","subject":"ya3","topic":"植牙學","meta":"115年第2次第53題","year":115,"session":2,"number":53,"question":"根據Pietrokovski and Massler（1967）、Schropp et al.（2003）和Misawa et al.（2016），如果齒槽骨原始水平寬度為12 mm，牙齒拔除12個月後，此無牙區的寬度將變為多少mm？","options":["(A) 10","(B) 8","(C) 6","(D) 4"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-54","subject":"ya3","topic":"植牙學","meta":"115年第2次第54題","year":115,"session":2,"number":54,"question":"有關拔牙窩的癒合過程，其先後順序為何？①肉芽組織生成（granulation tissue formation） ②發炎細胞吞噬作用（inflammatory cells phagocytosis） ③凝塊生成（coagulum formation） ④未成熟骨生成（immature bone formation）","options":["(A) ①②③④","(B) ②③①④","(C) ③②①④","(D) ③①②④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-55","subject":"ya3","topic":"牙科解剖與生理","meta":"115年第2次第55題","year":115,"session":2,"number":55,"question":"關於齒槽突的構造與重塑的敘述，下列何者錯誤？","options":["(A) 齒槽突結構中，齒槽骨體（alveolar bone proper）在放射線學上又稱為齒槽骨板（lamina dura）","(B) 涎蛋白（sialoprotein）是細胞黏著蛋白，對造骨細胞的附著非常重要","(C) 一般而言，造骨細胞數量會隨著老化過程而顯著減少，而破骨細胞數量則否","(D) 破骨細胞的活力及皺摺邊緣的型態，會受到甲狀腺荷爾蒙的影響"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-56","subject":"ya3","topic":"牙周疾病與診斷","meta":"115年第2次第56題","year":115,"session":2,"number":56,"question":"造成牙周炎的主要細菌中，常與局部侵襲性牙周炎（localized aggressive periodontitis）相關聯的是下列那種細菌？","options":["(A) 福賽斯坦納菌（Tannerella forsythia）","(B) 伴放線桿菌（Aggregatibacter actinomycetemcomitans）","(C) 中間普雷沃菌（Prevotella intermedia）","(D) 牙齦卟啉菌（Porphyromonas gingivalis）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-57","subject":"ya3","topic":"牙周疾病與診斷","meta":"115年第2次第57題","year":115,"session":2,"number":57,"question":"可與所有人類口腔細菌共凝集（coaggregation）的是下列那類細菌？","options":["(A) 韋榮氏球菌屬（Veillonella）","(B) 細梭細菌屬（Fusobacteria）","(C) 二氧化碳嗜纖維菌屬（Capnocytophaga）","(D) 普雷沃氏菌屬（Prevotella）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-58","subject":"ya3","topic":"牙周疾病與診斷","meta":"115年第2次第58題","year":115,"session":2,"number":58,"question":"下列何者不屬抗發炎細胞因子（anti-inflammatory cytokines）？","options":["(A) IL-10","(B) IL-17","(C) TGF-β","(D) IL-1Ra"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-59","subject":"ya3","topic":"牙周疾病與診斷","meta":"115年第2次第59題","year":115,"session":2,"number":59,"question":"體內產生對抗牙周炎致病菌的抗體是以下列那一類為主？","options":["(A) IgA","(B) IgD","(C) IgG","(D) IgM"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-60","subject":"ya3","topic":"牙周疾病與診斷","meta":"115年第2次第60題","year":115,"session":2,"number":60,"question":"關於評估牙周組織支持喪失的指標系統，下列敘述何者錯誤？","options":["(A) Russell（1956）提出的Periodontal Index用來評估牙周支持組織喪失，其中牙齒動搖度過大導致功能喪失為分數8","(B) Russell（1956）提出的Periodontal Index是一個可逆的評分系統，牙齒經治療後可以回復到較低的分數或0分","(C) Ramfjord（1959）提出的Periodontal Disease Index用來評估破壞性牙周病，其中分數3代表牙周囊袋深度達3 mm以上","(D) Ramfjord（1959）提出的Periodontal Disease Index是一個不可逆的評分系統，牙齒經治療後無法回復到較低的分數"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-61","subject":"ya3","topic":"牙周疾病與診斷","meta":"115年第2次第61題","year":115,"session":2,"number":61,"question":"在2017 World Workshop公布的牙周病新分類中，有關用來評估牙周炎嚴重程度分期的因子之一「牙齒缺失」的定義，下列何者錯誤？","options":["(A) Stage I：沒有牙齒因為牙周炎喪失","(B) Stage II：因為牙周炎而喪失的牙齒數≦3 teeth","(C) Stage III：因為牙周炎而喪失的牙齒數≦4 teeth","(D) Stage IV：因為牙周炎而喪失的牙齒數≧5 teeth"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-62","subject":"ya3","topic":"牙周疾病與診斷","meta":"115年第2次第62題","year":115,"session":2,"number":62,"question":"依據2017 World Workshop公布的牙周病新分類，牙周炎診斷為3期局部A級（localized Stage III, Grade A），下列敘述何者正確？","options":["(A) 中度疾病，侵犯的牙齒少於30%、疾病進展是慢速的","(B) 中度疾病，侵犯的牙齒超過30%、疾病進展是慢速的","(C) 重度疾病，侵犯的牙齒少於30%、疾病進展是慢速的","(D) 重度疾病，侵犯的牙齒超過30%、疾病進展是快速的"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-63","subject":"ya3","topic":"牙周非手術治療","meta":"115年第2次第63題","year":115,"session":2,"number":63,"question":"關於牙周治療器械Sickle的敘述，下列何者錯誤？","options":["(A) Sickle有兩個切除刀鋒（cutting edges）","(B) Sickle主要用於牙齦下清潔，且不易傷害牙齦","(C) 持握器械應用改良握筆式（modified pen grasp）持握器械","(D) 刀鋒必須要經常的進行銳利（sharpening）方能有效去除牙根沉積物"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-64","subject":"ya3","topic":"牙周非手術治療","meta":"115年第2次第64題","year":115,"session":2,"number":64,"question":"關於音波與超音波器械操作時，所產生氣霧（aerosol）的敘述，下列何者正確？","options":["(A) Epstein-Barr virus在氣霧中，不會經由人對人傳染","(B) Legionella pneumophila可於牙科治療椅的供水管路中被檢出","(C) 根據Harrel與Molinari之建議，第一級感染防護是治療前先給與抗菌漱口水","(D) 以0.12% chlorhexidine含漱1分鐘可以有效降低氣霧細菌量達12小時"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-65","subject":"ya3","topic":"牙周手術與再生","meta":"115年第2次第65題","year":115,"session":2,"number":65,"question":"下列何種骨缺損（bony defect）為骨切除術（resective osseous surgery）的適應症？","options":["(A) 上顎第二小臼齒腭側深度9 mm的單骨壁（one-wall）骨缺損","(B) 下顎第一大臼齒鄰接面深度1 mm的雙骨壁（two-wall）骨缺損","(C) 下顎第二大臼齒遠心側深度8 mm的三骨壁（three-wall）骨缺損","(D) 上顎第一小臼齒頰側深度6 mm的開裂（dehiscence）骨缺損"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-66","subject":"ya3","topic":"牙周疾病與診斷","meta":"115年第2次第66題","year":115,"session":2,"number":66,"question":"關於齒頸部釉質突起（cervical enamel projection, CEP）的敘述，下列何者錯誤？","options":["(A) CEP是造成牙根叉區域牙周破壞的局部因子（local factor）之一","(B) 大臼齒CEP的發生比率為8.6～28.6%","(C) 依據Masters與Hoskins的分類，Grade II是指CEP水平延伸至牙根叉內","(D) CEP的存在，會影響到牙菌斑與牙結石的清除效果"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-67","subject":"ya3","topic":"牙周手術與再生","meta":"115年第2次第67題","year":115,"session":2,"number":67,"question":"關於引導組織再生手術中常用的可吸收再生膜的敘述，下列何者錯誤？","options":["(A) 常合併骨移植材料使用","(B) 手術後暴露會加速再生膜分解，不會影響到牙周組織的再生效果","(C) 聚乳酸（polylactic acid）再生膜為一種合成的可吸收再生膜","(D) 不需要第二次手術移除，且相較於不可吸收再生膜，比較不會造成術後感染"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-68","subject":"ya3","topic":"牙周手術與再生","meta":"115年第2次第68題","year":115,"session":2,"number":68,"question":"翻瓣後清創與調理牙根表面（root instrumentation and conditioning）的方式，下列何者目前較少使用？","options":["(A) 使用ultrasonic instruments清創牙根表面","(B) 使用rotating fine-grained diamond stones清創牙根表面","(C) 使用EDTA做牙根表面的調理","(D) 使用citric acid做牙根表面的調理"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-69","subject":"ya3","topic":"植牙學","meta":"115年第2次第69題","year":115,"session":2,"number":69,"question":"下列何者最可能不是植體周圍炎的風險指標（risk indicator）？","options":["(A) 有牙周炎病史","(B) 抽菸","(C) 口腔衛生不佳","(D) 有植體周圍炎家族史"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-70","subject":"ya3","topic":"牙周手術與再生","meta":"115年第2次第70題","year":115,"session":2,"number":70,"question":"進行牙齦豐隆術（gingival augmentation）時，使用下列何種移植材料最可預期增加角質化組織（keratinized tissue）的寬度？","options":["(A) free graft from the palate","(B) acellular freeze‐dried dermal matrix","(C) human fibroblast‐derived dermal matrix","(D) subepithelial connective tissue graft"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-71","subject":"ya3","topic":"牙周手術與再生","meta":"115年第2次第71題","year":115,"session":2,"number":71,"question":"當牙周囊袋超過黏膜牙齦交界，並有厚且可處理的牙周囊袋壁（manageable pocket walls），最適當的手術方法為下列何者？","options":["(A) 根向移位翻瓣術（apically displaced flap）","(B) 游離牙齦移植術（free gingival graft）","(C) 皮下結締組織移植術（subepithelial connective tissue graft）","(D) 側移位翻瓣術（laterally positioned flap）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-72","subject":"ya3","topic":"牙周疾病與診斷","meta":"115年第2次第72題","year":115,"session":2,"number":72,"question":"關於學者Lang & Tonetti提出的功能性圖（funtional diagram）對於牙周風險評估（periodontal risk assessment）的敘述，下列何者錯誤？","options":["(A) 在積極治療前進行「齒槽骨喪失百分比與年紀的比例（BL%/age）」評估，比在牙周維護期進行評估更準確","(B) 如果有超過8顆牙齒喪失可被考慮為高度風險（high risk）","(C) 殘餘牙周囊袋＞4 mm本身不具有單獨評估因子的價值","(D) 戒菸超過5年以上的人應跟不抽菸的患者視同一致，即有相對較低的牙周病復發風險"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-73","subject":"ya3","topic":"牙周疾病與診斷","meta":"115年第2次第73題","year":115,"session":2,"number":73,"question":"關於牙周病與系統性疾病的關聯，下列敘述何者正確？","options":["(A) 牙周病的炎性反應呈現WBC、CRP和fibrinogen升高，與傳染性系統疾病有關","(B) 與非牙周病患者相比，牙周病患者血清中CRP呈現高約0.56 mg/L的差異","(C) 年紀大於60歲的高齡牙周病患者與年輕患者（＜50歲）相較，罹患冠狀動脈疾病的風險較高","(D) 缺牙超過10顆以上的牙周病患者，其動脈粥狀硬化的風險增加約1.9倍"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-74","subject":"ya3","topic":"牙周疾病與診斷","meta":"115年第2次第74題","year":115,"session":2,"number":74,"question":"關於牙齦pyogenic granuloma的敘述，下列何者錯誤？","options":["(A) 可能與內分泌有關聯","(B) 與牙菌斑堆積無關","(C) 常發生於懷孕的第二、三個月","(D) 治療後的疾病復發率約15%"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-75","subject":"ya3","topic":"牙周疾病與診斷","meta":"115年第2次第75題","year":115,"session":2,"number":75,"question":"性賀爾蒙（sex hormones）對牙齦組織的影響，下列敘述何者錯誤？","options":["(A) 牙齦與牙周組織有性賀爾蒙的受體，受血清與唾液中的性賀爾蒙濃度調控","(B) 性賀爾蒙主要是影響血管反應，修飾慢性發炎的炎症","(C) 青春期（onset of puberty）的賀爾蒙變化，只有女性受到影響","(D) Estrogen能促進膠原蛋白的代謝和血管生成，降低牙齦上皮的角化"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-76","subject":"ya3","topic":"牙周疾病與診斷","meta":"115年第2次第76題","year":115,"session":2,"number":76,"question":"頭頸部腫瘤的患者經常會進行放射線治療（radiation therapy），常見為黏膜炎、口腔乾燥、放射線齲齒及牙周組織變化等口腔副作用，下列敘述何者最適當？","options":["(A) 若治療目標區為唾液腺組織，則將來會有口乾症的副作用，進而影響菌叢變化為牙周感受性高者，如Porphyromonas gingivalis","(B) 為減少放射性骨壞死（osteoradionecrosis）的發生率，建議放射線治療兩週前就先拔除預後不佳的牙齒","(C) 口腔衛教建議每天使用0.4%氟化亞錫牙膏或1.0%氟化鈉凝膠刷牙，並且每年回診一次","(D) 療程結束3年以上的患者，放射性骨壞死（osteoradionecrosis）的發生率會大幅下降，仍可進行拔牙及牙周手術治療"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-77","subject":"ya3","topic":"植牙學","meta":"115年第2次第77題","year":115,"session":2,"number":77,"question":"植體可藉由減除過程（subtractive processes），進行表面處理。下列敘述何者錯誤？","options":["(A) 機械處理（machining）、酸蝕（acid etching）、爆破（blasting）均為常見的方法","(B) 表面處理可加速或增進骨整合的程度","(C) 經過表面處理的改變，可在宏觀（macroscopic level）下觀察到","(D) 減除過程是將原本的植體的表面結構移除或改變"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-78","subject":"ya3","topic":"植牙學","meta":"115年第2次第78題","year":115,"session":2,"number":78,"question":"關於植體周圍疾病治療的敘述，下列何者錯誤？","options":["(A) 患者有植體周圍黏膜炎時，輔助性療法無法增加機械性清創移除生物膜及消除發炎的效力","(B) 以鈦刷（titanium brush）對植體做表面去感染（surface decontamination）時，植體表面不會受到結構性損傷","(C) 植體周圍炎經過治療後復發的機率在平滑面植體（turned surface）會比粗糙面植體（rough surface）來得高","(D) 植體周圍炎手術後拍攝X光所見之骨缺損的填充（bone fill）並不能代表重新骨整合（re- osseointegration）確實發生"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-79","subject":"ya3","topic":"植牙學","meta":"115年第2次第79題","year":115,"session":2,"number":79,"question":"關於植體周圍炎處理的敘述，下列何者錯誤？","options":["(A) 如果經過非手術治療後，植體周圍仍有持續探測出血化膿，且探測深度≧6 mm，建議以手術方式治療","(B) 如果經過非手術治療後，植體周圍仍有探測出血，探測深度達5 mm且存在骨缺損，建議以手術方式治療","(C) 以植體成型術（implantoplasty）去除植體表面感染時要注意過熱可能造成植體周圍骨頭的破壞","(D) 在粗糙面植體（rough surface implant）周圍使用骨粉（bone grafting material）填入骨缺損，可在術後X光見到骨頭高度（bone level）有所提升"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya3-115-2-80","subject":"ya3","topic":"植牙學","meta":"115年第2次第80題","year":115,"session":2,"number":80,"question":"在運用osteotome technique進行鼻竇升高時，可預期增加的垂直骨高度約為幾mm？","options":["(A) 4","(B) 6","(C) 8","(D) 10"],"answer":0,"image":"","clinical_level":"一般"}];
